// Hyperrealism in p5.brush:
// Top-down view through still water onto pale turquoise mosaic tiles,
// a child's tangerine-orange swim goggles resting slightly off-centre
// with a strap curling toward the corner, beneath a trembling net of caustic light.

const W = 1200;
const H = 1200;

// Mosaic grid constants
const TILE_PITCH = 78;
const GROUT_W = 6.8;

// Goggles center & orientation (slightly off-centre)
const GOG_CX = 528;
const GOG_CY = 638;
const GOG_ANG = -19; // degrees

// Precomputed strap paths and Voronoi caustic cells
let strapLoopPts = [];
let strapTailPts = [];
let voronoiCells = [];
let voronoiEdges = [];
let voronoiVertices = [];

async function setup() {
  createCanvas(W, H, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(8472);
  noiseSeed(8472);

  // Register custom brushes for fine broken caustic pen lines & soft watercolour glazes
  brush.add("caustic_pen", {
    type: "default",
    weight: 0.65,
    scatter: 0.06,
    sharpness: 0.88,
    grain: 0.22,
    opacity: 225,
    spacing: 0.18,
    pressure: [0.25, 1.35, 0.2],
    rotate: "natural",
    noise: 0.45
  });

  brush.add("caustic_glow", {
    type: "default",
    weight: 2.2,
    scatter: 0.35,
    sharpness: 0.2,
    grain: 0.15,
    opacity: 55,
    spacing: 0.25,
    pressure: [0.2, 1.1, 0.2],
    rotate: "natural",
    noise: 0.3
  });

  brush.add("silicone_shader", {
    type: "default",
    weight: 1.4,
    scatter: 0.18,
    sharpness: 0.35,
    grain: 0.35,
    opacity: 85,
    spacing: 0.2,
    pressure: [0.3, 1.0, 0.3],
    rotate: "natural",
    noise: 0.25
  });

  buildStrapGeometry();
  buildCausticNetwork();
}

function draw() {
  translate(-width / 2, -height / 2);

  // Warm sunlit ivory-sand paper ground (gives warm luminosity through all glazes)
  background("#fcf6e8");

  // 1. UNDERWATER LIGHT BANDS & BASE WATERCOLOUR GLAZES
  drawUnderwaterBaseBands();

  // 2. GROUT BEDDING & TEXTURE
  drawGroutBase();

  // 3. LAYERED WATERCOLOUR MOSAIC TILES (Batched by glaze color for performance)
  drawMosaicTiles();

  // 4. GROUT SEAM SHADOWS, TILE BEVEL HIGHLIGHTS & GLASS RIPPLES
  drawTileBevelsAndSeams();

  // 5. FAINT WARPED SHADOW OF GOGGLES & STRAP + WARM REFRACTED ORANGE GLOW
  drawGogglesShadowAndRefraction();

  // 6. SUB-SURFACE CAUSTIC GLOW ON THE TILES
  drawFloorCausticGlow();

  // 7. CURLING TANGERINE SILICONE STRAP (3D ribbon with twists, bevels, glints)
  drawCurlingStrap();

  // 8. CHILD'S TANGERINE-ORANGE SWIM GOGGLES (Gaskets, frame, nose bridge, domed lenses)
  drawSwimGoggles();

  // 9. TREMBLING CAUSTIC LIGHT NET (Fine broken white & pale lemon pen lines
  //    bending across grout seams and wrapping over the domed lenses)
  drawCausticNetOverEverything();

  // 10. FINAL SPECULAR GLINTS & OPTICAL SURFACE POLISH
  drawFinalSpecularGlints();

  noLoop();
}

// ============================================================================
// OPTICAL PHYSICS, WATER WAVE FIELD & 3D SURFACE ELEVATION
// ============================================================================

// Smooth water surface swell height and gradient at (x, y)
function waterWave(x, y) {
  let nx = x * 0.0028;
  let ny = y * 0.0028;
  let a1 = (x * 0.29 + y * 0.21);
  let a2 = (x * 0.17 - y * 0.33);
  let a3 = (x * 0.41 + y * 0.08);

  let h =
    0.45 * sin(a1) +
    0.32 * cos(a2) +
    0.23 * sin(a3) +
    0.55 * (noise(nx, ny) - 0.5);

  // Spatial gradient approximates refraction deflection
  let gx =
    0.45 * 0.29 * cos(a1) * 0.01745 -
    0.32 * 0.17 * sin(a2) * 0.01745 +
    0.23 * 0.41 * cos(a3) * 0.01745 +
    (noise(nx + 0.02, ny) - noise(nx - 0.02, ny)) * 0.45;

  let gy =
    0.45 * 0.21 * cos(a1) * 0.01745 +
    0.32 * 0.33 * sin(a2) * 0.01745 +
    0.23 * 0.08 * cos(a3) * 0.01745 +
    (noise(nx, ny + 0.02) - noise(nx, ny - 0.02)) * 0.45;

  return { h, gx, gy };
}

// Displaces a point on the tiled pool floor via water refraction
function floorRefract(x, y) {
  let w = waterWave(x, y);
  return [x + w.gx * 68, y + w.gy * 68];
}

// Coordinate transforms between world and goggle-local space
function toGoggleLocal(x, y) {
  let dx = x - GOG_CX;
  let dy = y - GOG_CY;
  let c = cos(-GOG_ANG);
  let s = sin(-GOG_ANG);
  return [dx * c - dy * s, dx * s + dy * c];
}

function fromGoggleLocal(lx, ly) {
  let c = cos(GOG_ANG);
  let s = sin(GOG_ANG);
  return [GOG_CX + lx * c - ly * s, GOG_CY + lx * s + ly * c];
}

// Anatomical polar contour for child's swim goggle eye cup
// side: -1 for left eye, +1 for right eye
function eyeCupPoint(cx, cy, side, rx, ry, angDeg) {
  let u = side * cos(angDeg); // +1 toward outer temple, -1 toward nose bridge
  let v = sin(angDeg);        // -1 toward top brow, +1 toward lower cheek

  // Slight nasal flattening, outer temple fullness, and anatomical cheek curve
  let modX = 1.0 + 0.055 * u - 0.025 * v;
  let modY = 1.0 + 0.065 * u * v - 0.045 * cos(2 * angDeg);

  let px = cx + rx * modX * cos(angDeg);
  let py = cy + ry * modY * sin(angDeg);
  return [px, py];
}

// Evaluates 3D elevation z and surface normal (nx, ny) of the scene at (x, y)
// Used so caustic light lines bend across grout seams and wrap over domed lenses & frame
function sceneSurfaceProfile(x, y) {
  let [lx, ly] = toGoggleLocal(x, y);

  // Check left and right eye cups
  let cups = [
    { cx: -134, cy: 0, side: -1 },
    { cx: 134, cy: 0, side: 1 }
  ];

  for (let i = 0; i < 2; i++) {
    let c = cups[i];
    let dx = lx - c.cx;
    let dy = ly - c.cy;
    let ang = atan2(dy, dx);
    let u = c.side * cos(ang);
    let v = sin(ang);
    let modX = 1.0 + 0.055 * u - 0.025 * v;
    let modY = 1.0 + 0.065 * u * v - 0.045 * cos(2 * ang);

    // Normalized radial distance relative to domed lens (rx=75, ry=52)
    let rLens = sqrt(sq(dx / (75 * modX)) + sq(dy / (52 * modY)));
    if (rLens < 1.0) {
      // Convex polycarbonate dome
      let domeZ = 44 * sqrt(max(0, 1 - rLens * rLens)) + 14;
      let nxLocal = (dx / (75 * modX)) * 18;
      let nyLocal = (dy / (52 * modY)) * 18;
      let ca = cos(GOG_ANG), sa = sin(GOG_ANG);
      return {
        z: domeZ,
        nx: nxLocal * ca - nyLocal * sa,
        ny: nxLocal * sa + nyLocal * ca,
        onLens: true,
        onGoggle: true,
        cupIndex: i,
        rNorm: rLens
      };
    }

    // Frame bezel & soft silicone gasket (rLens from 1.0 to 1.54)
    let rGasket = sqrt(sq(dx / (115 * modX)) + sq(dy / (83 * modY)));
    if (rGasket < 1.0) {
      let rimT = (rGasket - 0.65) / 0.35; // 0 at lens edge, 1 at outer gasket rim
      let frameZ = 0;
      let slope = 0;
      if (rimT < 0.45) {
        // Raised molded frame bezel
        let b = sin((rimT / 0.45) * 180);
        frameZ = 16 + 12 * b;
        slope = 14 * cos((rimT / 0.45) * 180);
      } else {
        // Flanged silicone skirt sloping down to tiles
        let sT = (rimT - 0.45) / 0.55;
        frameZ = 16 * (1 - sT) + 3.5 * sin(sT * 360);
        slope = -10;
      }
      let nxLocal = cos(ang) * slope;
      let nyLocal = sin(ang) * slope;
      let ca = cos(GOG_ANG), sa = sin(GOG_ANG);
      return {
        z: frameZ,
        nx: nxLocal * ca - nyLocal * sa,
        ny: nxLocal * sa + nyLocal * ca,
        onLens: false,
        onGoggle: true,
        cupIndex: i,
        rNorm: rLens
      };
    }
  }

  // Check arched nose bridge
  if (abs(lx) < 58 && abs(ly) < 22) {
    let arch = cos((lx / 58) * 90);
    let cross = cos((ly / 22) * 90);
    if (arch > 0 && cross > 0) {
      let zBridge = 22 * arch * cross;
      return {
        z: zBridge,
        nx: -sin((lx / 58) * 90) * 8,
        ny: (ly / 22) * 10,
        onLens: false,
        onGoggle: true,
        cupIndex: -1,
        rNorm: 2
      };
    }
  }

  // Default: Tiled pool floor with recessed grout seams
  let rx = ((x % TILE_PITCH) + TILE_PITCH) % TILE_PITCH;
  let ry = ((y % TILE_PITCH) + TILE_PITCH) % TILE_PITCH;
  let nx = 0;
  let ny = 0;
  let z = 0;

  // Bevel step across vertical grout seam
  if (rx < GROUT_W) {
    let t = (rx / GROUT_W) * 2 - 1; // -1 to +1 across grout
    z -= 3.2 * (1 - t * t);
    nx = t * 5.2;
  } else if (rx < GROUT_W + 4.5) {
    nx = 2.8;
  } else if (rx > TILE_PITCH - 4.5) {
    nx = -2.8;
  }

  // Bevel step across horizontal grout seam
  if (ry < GROUT_W) {
    let t = (ry / GROUT_W) * 2 - 1;
    z -= 3.2 * (1 - t * t);
    ny = t * 5.2;
  } else if (ry < GROUT_W + 4.5) {
    ny = 2.8;
  } else if (ry > TILE_PITCH - 4.5) {
    ny = -2.8;
  }

  return { z, nx, ny, onLens: false, onGoggle: false, cupIndex: -1, rNorm: 9 };
}

// Displaces a caustic point so it trembles with the water, bends at grout seams,
// and wraps/refracts over the 3D domed lenses and goggles frame
function causticDisplace(x, y) {
  let w = waterWave(x, y);
  let surf = sceneSurfaceProfile(x, y);

  // High-frequency capillary water tremble
  let trX = (noise(x * 0.018, y * 0.018, 10) - 0.5) * 7.5;
  let trY = (noise(x * 0.018, y * 0.018, 25) - 0.5) * 7.5;

  // Sun angle projection + surface normal refraction/bend
  // Light comes from upper-left (-0.42, -0.52), so elevated surfaces shift caustic lines
  // toward top-left while dome normals curve them radially over the convex surface
  let dx = w.gx * 52 + trX + surf.nx - surf.z * 0.36;
  let dy = w.gy * 52 + trY + surf.ny - surf.z * 0.44;

  return {
    x: x + dx,
    y: y + dy,
    onLens: surf.onLens,
    onGoggle: surf.onGoggle,
    z: surf.z
  };
}

// ============================================================================
// LAYER 1 & 2: UNDERWATER LIGHT BANDS & GROUT BEDDING
// ============================================================================

function drawUnderwaterBaseBands() {
  brush.noStroke();
  brush.noHatch();

  // Soft-edged bands of cerulean, viridian, pale aqua, and sunlit warm seafoam
  const bands = [
    { y0: -80, y1: 280, col: "#7ce0d2", op: 42 },
    { y0: 140, y1: 540, col: "#2682a6", op: 38 },
    { y0: 380, y1: 780, col: "#1f7d70", op: 36 },
    { y0: 560, y1: 980, col: "#8fe8d8", op: 44 },
    { y0: 820, y1: 1280, col: "#25799b", op: 38 },
    // Warm golden sunlight wash through the central-upper water column
    { y0: 40, y1: 680, col: "#e9f5c6", op: 35 },
    { y0: 520, y1: 1120, col: "#f7e6b2", op: 28 }
  ];

  for (let b of bands) {
    brush.fill(b.col, b.op);
    brush.fillBleed(0.42, "out");
    brush.fillTexture(0.55, 0.25);

    let pts = [];
    for (let x = -60; x <= W + 60; x += 120) {
      let waveOff = 65 * sin(x * 0.22 + b.y0 * 0.15) + 35 * cos(x * 0.35);
      pts.push([x, b.y0 + waveOff - (x - 600) * 0.18]);
    }
    for (let x = W + 60; x >= -60; x -= 120) {
      let waveOff = 65 * sin(x * 0.22 + b.y1 * 0.15) + 35 * cos(x * 0.35);
      pts.push([x, b.y1 + waveOff - (x - 600) * 0.18]);
    }
    drawClosedShape(pts, 0.25);
  }
  brush.noFill();
}

function drawGroutBase() {
  // Subtle warm sand-limestone and pale aqua-grey texture along grout corridors
  for (let c = 0; c <= 16; c++) {
    let gx = c * TILE_PITCH;
    brush.set("2B", c % 2 === 0 ? "#dfd0b4" : "#c7d4c6", 0.9);
    let vPts = [];
    for (let y = -40; y <= H + 40; y += 60) {
      vPts.push(floorRefract(gx, y));
    }
    brush.spline(vPts, 0.25);
  }

  for (let r = 0; r <= 16; r++) {
    let gy = r * TILE_PITCH;
    brush.set("2B", r % 2 === 0 ? "#dfd0b4" : "#c7d4c6", 0.9);
    let hPts = [];
    for (let x = -40; x <= W + 40; x += 60) {
      hPts.push(floorRefract(x, gy));
    }
    brush.spline(hPts, 0.25);
  }
  brush.noStroke();
}

// ============================================================================
// LAYER 3 & 4: LAYERED WATERCOLOUR MOSAIC TILES & BEVEL SEAMS
// ============================================================================

// Compute rounded mosaic tile polygon in refracted floor coordinates
function getTilePolygon(col, row, inset = 0, jitterX = 0, jitterY = 0) {
  let x0 = col * TILE_PITCH + GROUT_W * 0.5 + inset + jitterX;
  let y0 = row * TILE_PITCH + GROUT_W * 0.5 + inset + jitterY;
  let s = TILE_PITCH - GROUT_W - inset * 2;
  let cr = max(2, 5.5 - inset * 0.3); // rounded glass tile corner

  let rawPts = [
    [x0 + cr, y0],
    [x0 + s * 0.5, y0],
    [x0 + s - cr, y0],
    [x0 + s, y0 + cr],
    [x0 + s, y0 + s * 0.5],
    [x0 + s, y0 + s - cr],
    [x0 + s - cr, y0 + s],
    [x0 + s * 0.5, y0 + s],
    [x0 + cr, y0 + s],
    [x0, y0 + s - cr],
    [x0, y0 + s * 0.5],
    [x0, y0 + cr]
  ];

  return rawPts.map(p => floorRefract(p[0], p[1]));
}

function drawMosaicTiles() {
  brush.noStroke();
  brush.noHatch();

  // 8 primary watercolour glaze buckets (cerulean, viridian, pale aqua, warm sunlit seafoam)
  const primaryGlazes = [
    { col: "#1d6f68", op: 92, bleed: 0.14 }, // 0: Deep Viridian
    { col: "#217496", op: 90, bleed: 0.14 }, // 1: Deep Cerulean
    { col: "#298982", op: 85, bleed: 0.13 }, // 2: Rich Viridian-Aqua
    { col: "#3296ad", op: 84, bleed: 0.13 }, // 3: Cerulean Turquoise
    { col: "#4eb6b0", op: 80, bleed: 0.12 }, // 4: Medium Turquoise
    { col: "#71cfc4", op: 78, bleed: 0.12 }, // 5: Pale Turquoise
    { col: "#97e3d5", op: 76, bleed: 0.12 }, // 6: Luminous Pale Aqua
    { col: "#bfead0", op: 74, bleed: 0.12 }  // 7: Sunlit Warm Aqua-Gold
  ];

  // Secondary inner glaze buckets for layered ceramic/glass depth
  const secondaryGlazes = [
    { col: "#18635d", op: 52 }, // 0: Viridian depth glaze
    { col: "#237ca3", op: 50 }, // 1: Cerulean depth glaze
    { col: "#5fd1c2", op: 48 }, // 2: Bright aqua heart
    { col: "#e8dfa0", op: 45 }, // 3: Warm sunlight gold glaze
    { col: "#f29d52", op: 44 }  // 4: Warm tangerine bounce near goggles
  ];

  let batches1 = Array.from({ length: primaryGlazes.length }, () => []);
  let batches2 = Array.from({ length: secondaryGlazes.length }, () => []);

  for (let row = -1; row <= 15; row++) {
    for (let col = -1; col <= 15; col++) {
      let cx = (col + 0.5) * TILE_PITCH;
      let cy = (row + 0.5) * TILE_PITCH;

      // Artisanal tile-placement micro-jitter
      let jx = (noise(col * 1.7, row * 1.7, 1) - 0.5) * 2.2;
      let jy = (noise(col * 1.7, row * 1.7, 2) - 0.5) * 2.2;

      // Wave light band modulation
      let bandWave =
        0.5 +
        0.32 * sin(col * 28 + row * 21) +
        0.18 * cos(col * 19 - row * 34) +
        (noise(col * 0.35, row * 0.35, 5) - 0.5) * 0.42;

      let idx = constrain(floor(bandWave * primaryGlazes.length), 0, primaryGlazes.length - 1);

      // Artisanal variation: occasionally shift a tile by 1 shade warmer/cooler
      if (random() < 0.28) {
        idx = constrain(idx + (random() < 0.5 ? 1 : -1), 0, primaryGlazes.length - 1);
      }

      let poly1 = getTilePolygon(col, row, 0.3, jx, jy);
      batches1[idx].push(poly1);

      // Secondary inner glaze on ~65% of tiles for translucent watercolour build-up
      let distGog = dist(cx, cy, GOG_CX + 18, GOG_CY + 24);
      if (distGog < 330 && random() < 0.42) {
        // Warm tangerine/amber bounce on tiles near the orange goggles
        batches2[4].push(getTilePolygon(col, row, 6.5, jx + 1.5, jy + 1.5));
      } else if (random() < 0.65) {
        let sIdx = idx <= 2 ? (col + row) % 2 : idx >= 6 ? 3 : 2;
        batches2[sIdx].push(getTilePolygon(col, row, 5.5, jx, jy));
      }
    }
  }

  // Render primary tile glazes in color batches
  for (let b = 0; b < primaryGlazes.length; b++) {
    let g = primaryGlazes[b];
    brush.fill(g.col, g.op);
    brush.fillBleed(g.bleed, "in");
    brush.fillTexture(0.48, 0.38);
    for (let poly of batches1[b]) {
      drawClosedShape(poly, 0.12);
    }
  }

  // Render secondary inner glazes in color batches
  for (let b = 0; b < secondaryGlazes.length; b++) {
    let g = secondaryGlazes[b];
    brush.fill(g.col, g.op);
    brush.fillBleed(0.18, "in");
    brush.fillTexture(0.42, 0.28);
    for (let poly of batches2[b]) {
      drawClosedShape(poly, 0.15);
    }
  }

  brush.noFill();
}

function drawTileBevelsAndSeams() {
  // For each tile, draw crisp glass bevel highlights (top/left) & recessed edge shadows (bottom/right)
  for (let row = 0; row <= 15; row++) {
    for (let col = 0; col <= 15; col++) {
      let jx = (noise(col * 1.7, row * 1.7, 1) - 0.5) * 2.2;
      let jy = (noise(col * 1.7, row * 1.7, 2) - 0.5) * 2.2;
      let x0 = col * TILE_PITCH + GROUT_W * 0.5 + jx;
      let y0 = row * TILE_PITCH + GROUT_W * 0.5 + jy;
      let s = TILE_PITCH - GROUT_W;

      let pTL = floorRefract(x0 + 3, y0 + 2);
      let pTR = floorRefract(x0 + s - 3, y0 + 2);
      let pBL = floorRefract(x0 + 2, y0 + s - 3);
      let pBR = floorRefract(x0 + s - 2, y0 + s - 2);

      // Top & left sunlit glass bevel highlight
      let isBright = sin(col * 28 + row * 21) > -0.1;
      brush.set("2H", isBright ? "#fffbe0" : "#b8f0e4", isBright ? 0.75 : 0.55);
      brush.line(pTL[0], pTL[1], pTR[0], pTR[1]);
      brush.line(pTL[0], pTL[1], pBL[0], pBL[1]);

      // Bottom & right tile edge shadow against grout
      brush.set("cpencil", (col + row) % 2 === 0 ? "#185e59" : "#1c5a70", 0.65);
      brush.line(pBL[0], pBL[1], pBR[0], pBR[1]);
      brush.line(pTR[0], pTR[1], pBR[0], pBR[1]);

      // Occasional subtle diagonal vitreous glass ripple inside the tile
      if ((col * 7 + row * 13) % 5 === 0) {
        brush.set("2H", "#e6f9ec", 0.45);
        let r1 = floorRefract(x0 + 14, y0 + s - 16);
        let r2 = floorRefract(x0 + s - 16, y0 + 14);
        brush.line(r1[0], r1[1], r2[0], r2[1]);
      }
    }
  }
  brush.noStroke();
}

// ============================================================================
// LAYER 5: FAINT WARPED SHADOW OF GOGGLES & STRAP + WARM REFRACTED LENS GLOW
// ============================================================================

function drawGogglesShadowAndRefraction() {
  const shOffX = 28;
  const shOffY = 38;

  brush.noStroke();
  brush.noHatch();

  // 1. Faint warped shadow of the left & right eye-cup frames and nose bridge
  let shadowPolys = [];
  for (let side of [-1, 1]) {
    let cx = side * 134;
    let pts = [];
    for (let a = 0; a < 360; a += 15) {
      let [lx, ly] = eyeCupPoint(cx, 0, side, 112, 80, a);
      let [wx, wy] = fromGoggleLocal(lx, ly);
      // Warp shadow across grout seams and water waves
      let surf = sceneSurfaceProfile(wx + shOffX, wy + shOffY);
      let [rx, ry] = floorRefract(wx + shOffX + surf.nx * 0.8, wy + shOffY + surf.ny * 0.8);
      pts.push([rx, ry]);
    }
    shadowPolys.push(pts);
  }

  // Nose bridge + side buckles shadow polygons
  let bridgeSh = [];
  let bridgeLocal = [
    [-70, -18], [0, -22], [70, -18],
    [70, 16], [0, 12], [-70, 16]
  ];
  for (let p of bridgeLocal) {
    let [wx, wy] = fromGoggleLocal(p[0], p[1]);
    // Nose bridge arches higher off floor, so its shadow offsets slightly further
    bridgeSh.push(floorRefract(wx + shOffX * 1.25, wy + shOffY * 1.25));
  }
  shadowPolys.push(bridgeSh);

  // Draw cool deep-viridian/cerulean warped shadow wash
  brush.fill("#134952", 68);
  brush.fillBleed(0.24, "out");
  brush.fillTexture(0.45, 0.3);
  for (let poly of shadowPolys) {
    drawClosedShape(poly, 0.18);
  }

  // 2. Warm Tangerine-Amber Refracted Caustic Glow inside the shadow of the domed lenses!
  // Sunlight passing through the tinted lenses and translucent orange silicone skirts
  // focuses warm apricot-orange light onto the turquoise tiles below.
  let lensGlowPolys = [];
  for (let side of [-1, 1]) {
    let cx = side * 134;
    let pts = [];
    for (let a = 0; a < 360; a += 18) {
      let [lx, ly] = eyeCupPoint(cx, 0, side, 68, 46, a);
      let [wx, wy] = fromGoggleLocal(lx, ly);
      pts.push(floorRefract(wx + shOffX * 0.88, wy + shOffY * 0.88));
    }
    lensGlowPolys.push(pts);
  }

  brush.fill("#ff8820", 72);
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.4, 0.2);
  for (let poly of lensGlowPolys) {
    drawClosedShape(poly, 0.2);
  }

  // Brighter golden-apricot core inside each refracted lens shadow
  brush.fill("#ffc84a", 58);
  brush.fillBleed(0.22, "out");
  for (let side of [-1, 1]) {
    let cx = side * 134;
    let pts = [];
    for (let a = 0; a < 360; a += 24) {
      let [lx, ly] = eyeCupPoint(cx - 8, -6, side, 42, 27, a);
      let [wx, wy] = fromGoggleLocal(lx, ly);
      pts.push(floorRefract(wx + shOffX * 0.85, wy + shOffY * 0.85));
    }
    drawClosedShape(pts, 0.2);
  }
  brush.noFill();

  // 3. Faint warped shadow of the curling silicone strap on the tiles
  // Shadow separation scales dynamically with the 3D height z of the strap!
  drawStrapShadowPath(strapLoopPts);
  drawStrapShadowPath(strapTailPts);
}

function drawStrapShadowPath(RibbonPts) {
  // Draw overlapping soft shadow segments warped by grout seams
  brush.set("silicone_shader", "#154f57", 2.6);
  let shSpine = [];
  for (let i = 0; i < RibbonPts.length; i++) {
    let p = RibbonPts[i];
    let sep = 8 + p.z * 0.85;
    let sx = p.x + sep * 0.72;
    let sy = p.y + sep * 0.96;
    let surf = sceneSurfaceProfile(sx, sy);
    let [rx, ry] = floorRefract(sx + surf.nx * 0.9, sy + surf.ny * 0.9);
    shSpine.push([rx, ry, 0.85]);
  }
  brush.spline(shSpine, 0.3);

  // Warm orange transmitted edge glow beside the strap shadow
  brush.set("caustic_glow", "#e87825", 1.1);
  let glowSpine = shSpine.map(pt => [pt[0] - 4, pt[1] - 4, 0.6]);
  brush.spline(glowSpine, 0.3);
  brush.noStroke();
}

// ============================================================================
// LAYER 6 & 9: VORONOI CAUSTIC NETWORK GENERATOR & RENDERING
// ============================================================================

function buildCausticNetwork() {
  // Generate jittered seed points in wave-space for organic cellular caustic web
  let seeds = [];
  let step = 148;
  for (let gy = -120; gy <= H + 160; gy += step) {
    for (let gx = -120; gx <= W + 160; gx += step) {
      let sx = gx + random(-step * 0.36, step * 0.36);
      let sy = gy + random(-step * 0.36, step * 0.36);
      seeds.push([sx, sy]);
    }
  }

  // Compute exact 2D Voronoi polygon for each seed via Sutherland-Hodgman half-plane clipping
  let bbox = [
    [-220, -220],
    [W + 220, -220],
    [W + 220, H + 220],
    [-220, H + 220]
  ];

  for (let i = 0; i < seeds.length; i++) {
    let si = seeds[i];
    let poly = bbox.slice();

    for (let j = 0; j < seeds.length; j++) {
      if (i === j) continue;
      let sj = seeds[j];
      let d = dist(si[0], si[1], sj[0], sj[1]);
      if (d > step * 2.6) continue;

      let mx = (si[0] + sj[0]) * 0.5;
      let my = (si[1] + sj[1]) * 0.5;
      let nx = sj[0] - si[0];
      let ny = sj[1] - si[1];

      poly = clipPolygonHalfPlane(poly, mx, my, nx, ny);
      if (poly.length < 3) break;
    }

    if (poly.length >= 3) {
      voronoiCells.push({ center: si, verts: poly });
    }
  }

  // Extract unique edges and 3-way junction vertices for bright caustic cusps
  let edgeMap = new Map();
  let vertMap = new Map();

  for (let cell of voronoiCells) {
    let v = cell.verts;
    for (let k = 0; k < v.length; k++) {
      let p1 = v[k];
      let p2 = v[(k + 1) % v.length];

      let k1 = `${round(p1[0] / 3) * 3},${round(p1[1] / 3) * 3}`;
      let k2 = `${round(p2[0] / 3) * 3},${round(p2[1] / 3) * 3}`;

      if (!vertMap.has(k1)) vertMap.set(k1, p1);
      if (k1 === k2) continue;

      let eKey = k1 < k2 ? `${k1}_${k2}` : `${k2}_${k1}`;
      if (!edgeMap.has(eKey)) {
        edgeMap.set(eKey, { p1, p2, centers: [cell.center] });
      } else {
        edgeMap.get(eKey).centers.push(cell.center);
      }
    }
  }

  voronoiEdges = Array.from(edgeMap.values());
  voronoiVertices = Array.from(vertMap.values());
}

function clipPolygonHalfPlane(poly, mx, my, nx, ny) {
  let out = [];
  for (let i = 0; i < poly.length; i++) {
    let cur = poly[i];
    let prev = poly[(i + poly.length - 1) % poly.length];
    let dCur = (cur[0] - mx) * nx + (cur[1] - my) * ny;
    let dPrev = (prev[0] - mx) * nx + (prev[1] - my) * ny;

    if (dCur <= 0) {
      if (dPrev > 0) {
        let t = dPrev / (dPrev - dCur);
        out.push([prev[0] + t * (cur[0] - prev[0]), prev[1] + t * (cur[1] - prev[1])]);
      }
      out.push(cur);
    } else if (dPrev <= 0) {
      let t = dPrev / (dPrev - dCur);
      out.push([prev[0] + t * (cur[0] - prev[0]), prev[1] + t * (cur[1] - prev[1])]);
    }
  }
  return out;
}

// Soft underwater luminous glow along the caustic ridges before goggles are drawn
function drawFloorCausticGlow() {
  for (let e of voronoiEdges) {
    let p1 = e.p1;
    let p2 = e.p2;
    if ((p1[0] < -60 && p2[0] < -60) || (p1[0] > W + 60 && p2[0] > W + 60)) continue;
    if ((p1[1] < -60 && p2[1] < -60) || (p1[1] > H + 60 && p2[1] > H + 60)) continue;

    let steps = 10;
    let pts = [];
    for (let s = 0; s <= steps; s++) {
      let t = s / steps;
      let ux = lerp(p1[0], p2[0], t);
      let uy = lerp(p1[1], p2[1], t);
      let d = causticDisplace(ux, uy);
      let pr = 1.15 - 0.55 * sin(t * 180); // Brighter near cell junctions
      pts.push([d.x, d.y, pr]);
    }

    brush.set("caustic_glow", "#e8f9c8", 1.35);
    brush.spline(pts, 0.35);
  }
  brush.noStroke();
}

// Fine, slightly broken white and pale lemon pen lines that form wobbling cells,
// bend across grout seams, and wrap over the goggles' domed lenses
function drawCausticNetOverEverything() {
  // PASS A: Wobbling concave cell walls (creates authentic flared triangular cusps at vertices)
  for (let cIdx = 0; cIdx < voronoiCells.length; cIdx++) {
    let cell = voronoiCells[cIdx];
    let cx = cell.center[0];
    let cy = cell.center[1];
    if (cx < -160 || cx > W + 160 || cy < -160 || cy > H + 160) continue;

    let v = cell.verts;
    for (let k = 0; k < v.length; k++) {
      let p1 = v[k];
      let p2 = v[(k + 1) % v.length];
      let edgeLen = dist(p1[0], p1[1], p2[0], p2[1]);
      if (edgeLen < 12) continue;

      let steps = constrain(floor(edgeLen / 11), 6, 22);
      let subSeg = [];

      for (let s = 0; s <= steps; s++) {
        let t = s / steps;
        let bx = lerp(p1[0], p2[0], t);
        let by = lerp(p1[1], p2[1], t);

        // Pull vertices slightly inward toward cell center to form triangular nodal webs,
        // and bow mid-edges gently with capillary wobble
        let cornerPull = 9.5 * pow(cos(t * 180), 2) + 2.2 * sin(t * 180);
        let dirX = cx - bx;
        let dirY = cy - by;
        let dLen = max(1, sqrt(dirX * dirX + dirY * dirY));

        // High-frequency perpendicular wobble along the cell wall
        let perpX = -(p2[1] - p1[1]) / edgeLen;
        let perpY = (p2[0] - p1[0]) / edgeLen;
        let wob = sin(t * 360 * 1.5 + cIdx * 37) * 2.4;

        let ux = bx + (dirX / dLen) * cornerPull + perpX * wob;
        let uy = by + (dirY / dLen) * cornerPull + perpY * wob;

        let disp = causticDisplace(ux, uy);

        // Slightly broken pen line modulation: occasionally lift the pen mid-span
        let breakVal = noise(ux * 0.025, uy * 0.025, cIdx * 0.7);
        let isBroken = (t > 0.25 && t < 0.75 && breakVal < 0.26);

        if (isBroken) {
          if (subSeg.length >= 2) {
            strokeCausticSegment(subSeg, cIdx + k);
          }
          subSeg = [];
        } else {
          let pressure = 0.65 + 0.55 * abs(cos(t * 180)) + (disp.onLens ? 0.25 : 0);
          subSeg.push({ x: disp.x, y: disp.y, pr: pressure, onLens: disp.onLens, onGoggle: disp.onGoggle });
        }
      }

      if (subSeg.length >= 2) {
        strokeCausticSegment(subSeg, cIdx + k);
      }
    }
  }

  // PASS B: Central Spine Filaments & Bright 3-Way Vertex Cusps
  for (let eIdx = 0; eIdx < voronoiEdges.length; eIdx++) {
    let e = voronoiEdges[eIdx];
    let p1 = e.p1;
    let p2 = e.p2;
    let len = dist(p1[0], p1[1], p2[0], p2[1]);
    if (len < 10) continue;
    if ((p1[0] < -50 && p2[0] < -50) || (p1[0] > W + 50 && p2[0] > W + 50)) continue;
    if ((p1[1] < -50 && p2[1] < -50) || (p1[1] > H + 50 && p2[1] > H + 50)) continue;

    // Draw intense end-cusp filaments near the 3-way vertices (t in [0, 0.35] and [0.65, 1.0])
    for (let span of [[0, 0.38], [0.62, 1.0]]) {
      let pts = [];
      for (let s = 0; s <= 5; s++) {
        let t = lerp(span[0], span[1], s / 5);
        let ux = lerp(p1[0], p2[0], t);
        let uy = lerp(p1[1], p2[1], t);
        let disp = causticDisplace(ux, uy);
        let pr = (span[0] === 0 ? (1 - s / 5) : (s / 5)) * 1.15 + 0.35;
        pts.push([disp.x, disp.y, pr]);
      }
      brush.set("caustic_pen", eIdx % 2 === 0 ? "#ffffff" : "#fff7ad", 0.95);
      brush.spline(pts, 0.3);
    }
  }

  // PASS C: Luminous Nodal Star-Webs at the 3-way Caustic Vertices
  for (let vIdx = 0; vIdx < voronoiVertices.length; vIdx++) {
    let v = voronoiVertices[vIdx];
    if (v[0] < -30 || v[0] > W + 30 || v[1] < -30 || v[1] > H + 30) continue;
    let disp = causticDisplace(v[0], v[1]);

    // Soft lemon-white flare at vertex
    brush.set("caustic_glow", disp.onGoggle ? "#fff29c" : "#f4f9c8", disp.onLens ? 1.3 : 0.95);
    brush.circle(disp.x, disp.y, random(4, 8), 0.35);

    // Crisp white pinpoint core at caustic vertex
    brush.set("rotring", "#ffffff", disp.onLens ? 0.95 : 0.75);
    brush.circle(disp.x, disp.y, random(1.8, 3.6), 0.25);
  }

  brush.noStroke();
}

function strokeCausticSegment(seg, seedVal) {
  let pts = seg.map(p => [p.x, p.y, p.pr]);
  let anyOnLens = seg.some(p => p.onLens);
  let anyOnGoggle = seg.some(p => p.onGoggle);

  // Alternate between pale lemon pen lines and crisp white pen lines
  let isLemon = seedVal % 3 !== 0;
  let col = isLemon ? (anyOnGoggle ? "#ffef82" : "#fdf4a6") : "#ffffff";
  let wt = anyOnLens ? 1.05 : anyOnGoggle ? 0.92 : 0.78;

  if (pts.length === 2) {
    brush.set("rotring", col, wt * 0.75);
    brush.line(pts[0][0], pts[0][1], pts[1][0], pts[1][1]);
  } else {
    brush.set("caustic_pen", col, wt);
    brush.spline(pts, 0.35);

    // Secondary ultra-fine white core on bright segments
    if (!isLemon || anyOnLens) {
      brush.set("rotring", "#ffffff", wt * 0.58);
      brush.spline(pts, 0.35);
    }
  }
}

// ============================================================================
// LAYER 7: CURLING TANGERINE SILICONE STRAP (3D RIBBON WITH TWISTS)
// ============================================================================

function buildStrapGeometry() {
  // Left & right buckle world coordinates
  let leftBuckle = fromGoggleLocal(-246, 2);
  let rightBuckle = fromGoggleLocal(246, -2);

  // 1. Main Head-Strap Loop: emerges from left buckle, sweeps down-right,
  //    loops gracefully up the right side and enters the right buckle
  let loopControl = [
    { x: leftBuckle[0], y: leftBuckle[1], z: 10, w: 22, twist: 15 },
    { x: 238, y: 792, z: 18, w: 23, twist: 35 },
    { x: 285, y: 928, z: 6,  w: 24, twist: 12 },
    { x: 475, y: 995, z: 4,  w: 24, twist: -18 },
    { x: 745, y: 968, z: 14, w: 24, twist: -55 },
    { x: 968, y: 842, z: 26, w: 23, twist: -115 }, // Ribbon twists here!
    { x: 1012, y: 668, z: 22, w: 23, twist: -155 },
    { x: 912, y: 552, z: 15, w: 22, twist: -105 },
    { x: rightBuckle[0], y: rightBuckle[1], z: 11, w: 21, twist: -35 }
  ];

  // 2. Curling Strap Tail: emerges from the right buckle and curls toward the top-right corner!
  let tailControl = [
    { x: rightBuckle[0], y: rightBuckle[1], z: 12, w: 21, twist: -20 },
    { x: 878, y: 492, z: 22, w: 22, twist: 28 },
    { x: 896, y: 348, z: 14, w: 22, twist: 78 },  // Graceful twist showing edge profile
    { x: 995, y: 245, z: 8,  w: 21, twist: 135 },
    { x: 1105, y: 178, z: 16, w: 20, twist: 170 },
    { x: 1118, y: 102, z: 22, w: 19, twist: 130 },
    { x: 1048, y: 84,  z: 14, w: 18, twist: 65 },
    { x: 1015, y: 132, z: 6,  w: 16, twist: 20 }   // Curled tip near top-right corner
  ];

  strapLoopPts = sampleRibbonSpline(loopControl, 68);
  strapTailPts = sampleRibbonSpline(tailControl, 56);
}

function sampleRibbonSpline(ctrl, numSamples) {
  let res = [];
  let n = ctrl.length - 1;
  for (let i = 0; i <= numSamples; i++) {
    let tGlobal = (i / numSamples) * n;
    let idx = constrain(floor(tGlobal), 0, n - 1);
    let f = tGlobal - idx;

    let p0 = ctrl[max(0, idx - 1)];
    let p1 = ctrl[idx];
    let p2 = ctrl[min(n, idx + 1)];
    let p3 = ctrl[min(n, idx + 2)];

    let x = catmullRom(p0.x, p1.x, p2.x, p3.x, f);
    let y = catmullRom(p0.y, p1.y, p2.y, p3.y, f);
    let z = catmullRom(p0.z, p1.z, p2.z, p3.z, f);
    let w = catmullRom(p0.w, p1.w, p2.w, p3.w, f);
    let twist = catmullRom(p0.twist, p1.twist, p2.twist, p3.twist, f);

    res.push({ x, y, z, w, twist });
  }

  // Compute tangents and normals
  for (let i = 0; i < res.length; i++) {
    let prev = res[max(0, i - 1)];
    let next = res[min(res.length - 1, i + 1)];
    let tx = next.x - prev.x;
    let ty = next.y - prev.y;
    let len = max(0.001, sqrt(tx * tx + ty * ty));
    res[i].nx = -ty / len;
    res[i].ny = tx / len;
  }
  return res;
}

function catmullRom(v0, v1, v2, v3, t) {
  let t2 = t * t;
  let t3 = t2 * t;
  return 0.5 * (
    (2 * v1) +
    (-v0 + v2) * t +
    (2 * v0 - 5 * v1 + 4 * v2 - v3) * t2 +
    (-v0 + 3 * v1 - 3 * v2 + v3) * t3
  );
}

function drawCurlingStrap() {
  renderSiliconeRibbon(strapLoopPts);
  renderSiliconeRibbon(strapTailPts);
}

function renderSiliconeRibbon(pts) {
  // Split ribbon into chunks of consistent face orientation (top face vs underside face across twists)
  let edgeA = [];
  let edgeB = [];
  let thickEdge = [];

  for (let i = 0; i < pts.length; i++) {
    let p = pts[i];
    // Projected half-width and visible silicone thickness rim
    let cosT = cos(p.twist);
    let sinT = sin(p.twist);
    let halfW = max(2.2, abs(p.w * 0.5 * cosT)) * (cosT >= 0 ? 1 : -1);
    let thick = 5.2 * sinT;

    let ax = p.x + p.nx * halfW;
    let ay = p.y + p.ny * halfW;
    let bx = p.x - p.nx * halfW;
    let by = p.y - p.ny * halfW;

    edgeA.push([ax, ay]);
    edgeB.push([bx, by]);
    thickEdge.push([bx + p.nx * thick, by + p.ny * thick]);
  }

  brush.noStroke();
  brush.noHatch();

  // Draw ribbon in overlapping quad chunks so twists & color shifts render cleanly
  let chunkSize = 8;
  for (let i = 0; i < pts.length - 1; i += chunkSize) {
    let end = min(pts.length - 1, i + chunkSize);
    let mid = pts[floor((i + end) * 0.5)];
    let isTopFace = cos(mid.twist) >= 0;

    // 1. Thickness rim polygon (darker burnt orange edge)
    let rimPoly = [];
    for (let k = i; k <= end; k++) rimPoly.push(edgeB[k]);
    for (let k = end; k >= i; k--) rimPoly.push(thickEdge[k]);

    brush.fill("#b82b00", 180);
    brush.fillBleed(0.04, "in");
    brush.fillTexture(0.25, 0.2);
    drawClosedShape(rimPoly, 0.08);

    // 2. Main flat ribbon surface polygon
    let facePoly = [];
    for (let k = i; k <= end; k++) facePoly.push(edgeA[k]);
    for (let k = end; k >= i; k--) facePoly.push(edgeB[k]);

    let faceCol = isTopFace ? "#ff5e12" : "#d93b04";
    brush.fill(faceCol, 205);
    brush.fillBleed(0.05, "in");
    brush.fillTexture(0.32, 0.25);
    drawClosedShape(facePoly, 0.1);

    // 3. Warm golden-apricot sunlit glaze on upper-facing curves
    if (isTopFace) {
      brush.fill("#ff9b38", 110);
      brush.fillBleed(0.08, "in");
      drawClosedShape(facePoly, 0.1);
    }
  }
  brush.noFill();

  // Stroke raised silicone border ribs & glossy specular highlights along the strap
  let spineTop = [];
  let rib1 = [];
  let rib2 = [];
  let specLine = [];

  for (let i = 0; i < pts.length; i++) {
    let p = pts[i];
    let pr = 0.7 + 0.4 * abs(cos(p.twist));
    rib1.push([edgeA[i][0], edgeA[i][1], pr]);
    rib2.push([edgeB[i][0], edgeB[i][1], pr]);
    spineTop.push([p.x, p.y, pr]);
    specLine.push([
      lerp(p.x, edgeA[i][0], 0.62),
      lerp(p.y, edgeA[i][1], 0.62),
      0.55 + 0.55 * max(0, sin(i * 12))
    ]);
  }

  // Deep vermilion shading along center channel & underside edge
  brush.set("silicone_shader", "#b32400", 1.15);
  brush.spline(rib2, 0.3);

  brush.set("cpencil", "#ff7c24", 1.1);
  brush.spline(spineTop, 0.3);

  // Crisp tangerine-orange edge ribs
  brush.set("pen", "#dd3800", 0.85);
  brush.spline(rib1, 0.3);
  brush.spline(rib2, 0.3);

  // Glossy wet lemon-cream specular highlight along sun-facing silicone rib
  brush.set("rotring", "#fff4c2", 0.75);
  brush.spline(specLine, 0.3);
  brush.noStroke();
}

// ============================================================================
// LAYER 8: CHILD'S TANGERINE-ORANGE SWIM GOGGLES
// ============================================================================

function drawSwimGoggles() {
  // 1. Soft Translucent Silicone Suction Gaskets (Eye Skirts)
  for (let side of [-1, 1]) {
    let cx = side * 134;
    let outerSkirt = [];
    let midFlange = [];
    for (let a = 0; a < 360; a += 12) {
      let pOut = eyeCupPoint(cx + side * 4, 0, side, 115, 83, a);
      let pMid = eyeCupPoint(cx + side * 2, 0, side, 104, 74, a);
      outerSkirt.push(fromGoggleLocal(pOut[0], pOut[1]));
      midFlange.push(fromGoggleLocal(pMid[0], pMid[1]));
    }

    // Translucent warm apricot-orange outer silicone skirt (lets aqua tile glow through slightly)
    brush.noStroke();
    brush.fill("#ff8528", 155);
    brush.fillBleed(0.08, "in");
    brush.fillTexture(0.35, 0.3);
    drawClosedShape(outerSkirt, 0.15);

    // Deeper tangerine inner suction cushion
    brush.fill("#f04e08", 185);
    brush.fillBleed(0.06, "in");
    drawClosedShape(midFlange, 0.15);
    brush.noFill();

    // Fine internal double-ribbed silicone gasket lines
    brush.set("cpencil", "#b82800", 0.85);
    brush.spline([...midFlange.map(p => [p[0], p[1], 0.8]), [midFlange[0][0], midFlange[0][1], 0.8]], 0.25);

    brush.set("rotring", "#ffd280", 0.65);
    brush.spline([...outerSkirt.map(p => [p[0], p[1], 0.7]), [outerSkirt[0][0], outerSkirt[0][1], 0.7]], 0.25);
    brush.noStroke();
  }

  // 2. Side Strap Buckles / Slotted Lugs & Flexible Ribbed Nose Bridge
  drawNoseBridgeAndBuckles();

  // 3. Domed Polycarbonate Lenses (Refracted tiles inside, aquatic reflections, inner gasket wall)
  for (let side of [-1, 1]) {
    drawDomedLens(side);
  }

  // 4. High-Gloss Molded Tangerine-Orange Frame Bezels (Surrounding the lenses)
  for (let side of [-1, 1]) {
    drawFrameBezel(side);
  }
}

function drawNoseBridgeAndBuckles() {
  brush.noStroke();
  brush.noHatch();

  // Slotted side buckles at left (-242) and right (+242)
  for (let side of [-1, 1]) {
    let bx0 = side * 205;
    let bx1 = side * 260;
    let buckleLocal = [
      [bx0, -24],
      [bx1, -20],
      [bx1 + side * 5, 0],
      [bx1, 20],
      [bx0, 24]
    ];
    let buckleWorld = buckleLocal.map(p => fromGoggleLocal(p[0], p[1]));

    brush.fill("#eb4806", 220);
    brush.fillBleed(0.04, "in");
    brush.fillTexture(0.3, 0.25);
    drawClosedShape(buckleWorld, 0.1);

    // Sunlit top bevel on buckle
    let topEdge = [
      fromGoggleLocal(bx0, -23),
      fromGoggleLocal((bx0 + bx1) * 0.5, -22),
      fromGoggleLocal(bx1, -19)
    ];
    brush.set("rotring", "#ffca68", 0.9);
    brush.spline(topEdge, 0.2);

    // Dark recessed strap slot inside buckle
    let s1 = fromGoggleLocal(side * 238, -13);
    let s2 = fromGoggleLocal(side * 238, 13);
    brush.set("pen", "#5e1100", 2.2);
    brush.line(s1[0], s1[1], s2[0], s2[1]);
    brush.noStroke();
  }

  // Arched Nose Bridge connecting left and right frames
  let bridgeLocal = [
    [-64, -19], [-28, -14], [0, -15], [28, -14], [64, -19],
    [64, 17],   [28, 12],   [0, 11],  [-28, 12],  [-64, 17]
  ];
  let bridgeWorld = bridgeLocal.map(p => fromGoggleLocal(p[0], p[1]));

  brush.fill("#ff590c", 230);
  brush.fillBleed(0.04, "in");
  brush.fillTexture(0.3, 0.2);
  drawClosedShape(bridgeWorld, 0.18);

  // Warm cadmium highlight across the top arch of the nose bridge
  let bridgeTop = [
    fromGoggleLocal(-56, -15),
    fromGoggleLocal(0, -12),
    fromGoggleLocal(56, -15)
  ];
  brush.set("silicone_shader", "#ffb84d", 1.3);
  brush.spline(bridgeTop, 0.25);

  // Three molded adjustment notches on the nose bridge
  for (let nx of [-18, 0, 18]) {
    let n1 = fromGoggleLocal(nx, -10);
    let n2 = fromGoggleLocal(nx, 8);
    brush.set("rotring", "#a82200", 0.85);
    brush.line(n1[0], n1[1], n2[0], n2[1]);
    let h1 = fromGoggleLocal(nx + 2.5, -9);
    let h2 = fromGoggleLocal(nx + 2.5, 7);
    brush.set("rotring", "#ffe699", 0.6);
    brush.line(h1[0], h1[1], h2[0], h2[1]);
  }
  brush.noStroke();
}

function drawDomedLens(side) {
  let cx = side * 134;

  // Lens perimeter polygon
  let lensPoly = [];
  for (let a = 0; a < 360; a += 12) {
    let p = eyeCupPoint(cx, 0, side, 75, 52, a);
    lensPoly.push(fromGoggleLocal(p[0], p[1]));
  }

  brush.noStroke();
  brush.noHatch();

  // 1. Base tinted amber-teal polycarbonate lens wash
  brush.fill("#1d6870", 175);
  brush.fillBleed(0.04, "in");
  brush.fillTexture(0.35, 0.25);
  drawClosedShape(lensPoly, 0.15);

  // 2. Inner orange-mahogany silicone cup wall visible through the peripheral rim of the lens
  let innerWallPoly = [];
  for (let a = 0; a < 360; a += 15) {
    let p = eyeCupPoint(cx + 4, 3, side, 62, 41, a);
    innerWallPoly.push(fromGoggleLocal(p[0], p[1]));
  }
  brush.fill("#b83a08", 95);
  brush.fillBleed(0.12, "in");
  drawClosedShape(lensPoly, 0.15);

  brush.fill("#1a5863", 190);
  brush.fillBleed(0.08, "in");
  drawClosedShape(innerWallPoly, 0.15);

  // 3. Refracted/magnified mosaic grout seams visible *through* the domed lens!
  let [wCx, wCy] = fromGoggleLocal(cx, 0);
  for (let offset of [-32, 0, 32]) {
    // Refracted vertical seam arc inside lens
    let vArc = [];
    for (let dy = -34; dy <= 34; dy += 11) {
      let bend = offset * (1 + 0.18 * (1 - sq(dy / 38)));
      let [wx, wy] = fromGoggleLocal(cx + bend, dy);
      vArc.push([wx, wy, 0.75]);
    }
    brush.set("cpencil", "#76d4c8", 0.65);
    brush.spline(vArc, 0.3);

    // Refracted horizontal seam arc inside lens
    if (abs(offset) <= 24) {
      let hArc = [];
      for (let dx = -50; dx <= 50; dx += 16) {
        let bend = offset * (1 + 0.18 * (1 - sq(dx / 55)));
        let [wx, wy] = fromGoggleLocal(cx + dx, bend);
        hArc.push([wx, wy, 0.75]);
      }
      brush.set("cpencil", "#76d4c8", 0.65);
      brush.spline(hArc, 0.3);
    }
  }
  brush.noStroke();

  // 4. Dichroic warm golden-amber & aqua sky reflection on upper-left dome hemisphere
  let upperDome = [];
  for (let a = 165; a <= 345; a += 15) {
    let p = eyeCupPoint(cx - 5, -4, side, 64, 43, a);
    upperDome.push(fromGoggleLocal(p[0], p[1]));
  }
  for (let a = 345; a >= 165; a -= 30) {
    let p = eyeCupPoint(cx - 6, -3, side, 22, 14, a);
    upperDome.push(fromGoggleLocal(p[0], p[1]));
  }

  brush.fill("#ffb042", 85);
  brush.fillBleed(0.16, "in");
  drawClosedShape(upperDome, 0.2);

  // Lower-right deep cerulean-viridian dome shadow crescent
  let lowerDome = [];
  for (let a = -15; a <= 155; a += 15) {
    let p = eyeCupPoint(cx + 3, 3, side, 68, 46, a);
    lowerDome.push(fromGoggleLocal(p[0], p[1]));
  }
  for (let a = 155; a >= -15; a -= 30) {
    let p = eyeCupPoint(cx + 4, 4, side, 36, 24, a);
    lowerDome.push(fromGoggleLocal(p[0], p[1]));
  }
  brush.fill("#0b333d", 115);
  brush.fillBleed(0.15, "in");
  drawClosedShape(lowerDome, 0.2);
  brush.noFill();
}

function drawFrameBezel(side) {
  let cx = side * 134;

  // Molded tangerine frame sits between outer rim (95, 67) and inner lens rim (74, 51)
  // Draw in 12 angular sectors around the eye cup so we can shade 3D curvature cleanly
  let stepA = 30;
  brush.noStroke();
  brush.noHatch();

  for (let a0 = 0; a0 < 360; a0 += stepA) {
    let a1 = a0 + stepA;
    let aMid = (a0 + a1) * 0.5;

    let pOut0 = eyeCupPoint(cx, 0, side, 95, 67, a0);
    let pOutM = eyeCupPoint(cx, 0, side, 95, 67, aMid);
    let pOut1 = eyeCupPoint(cx, 0, side, 95, 67, a1);

    let pIn1 = eyeCupPoint(cx, 0, side, 73, 50, a1);
    let pInM = eyeCupPoint(cx, 0, side, 73, 50, aMid);
    let pIn0 = eyeCupPoint(cx, 0, side, 73, 50, a0);

    let sector = [pOut0, pOutM, pOut1, pIn1, pInM, pIn0].map(p => fromGoggleLocal(p[0], p[1]));

    // Directional lighting: top-left (around 225 deg) is brightest cadmium-tangerine,
    // bottom-right (around 45 deg) is deep vermilion-orange
    let lightDot = -cos(aMid - 40);
    let col =
      lightDot > 0.45 ? "#ff7b1c" :
      lightDot > -0.15 ? "#ff5508" :
      lightDot > -0.6 ? "#e03c00" : "#ba2800";

    brush.fill(col, 235);
    brush.fillBleed(0.03, "in");
    brush.fillTexture(0.28, 0.22);
    drawClosedShape(sector, 0.12);
  }
  brush.noFill();

  // Sculptural ridge shading & highlights around the molded frame bezel
  let ridgeMid = [];
  let innerLip = [];
  let outerLip = [];
  for (let a = 0; a <= 360; a += 10) {
    let pm = eyeCupPoint(cx, 0, side, 84, 59, a);
    let pi = eyeCupPoint(cx, 0, side, 74, 51, a);
    let po = eyeCupPoint(cx, 0, side, 95, 67, a);
    ridgeMid.push([...fromGoggleLocal(pm[0], pm[1]), 0.85]);
    innerLip.push([...fromGoggleLocal(pi[0], pi[1]), 0.9]);
    outerLip.push([...fromGoggleLocal(po[0], po[1]), 0.85]);
  }

  // Deep recessed shadow line where lens meets inner bezel lip
  brush.set("pen", "#5c1200", 1.05);
  brush.spline(innerLip, 0.25);

  // Outer bezel seam
  brush.set("cpencil", "#9e2100", 0.9);
  brush.spline(outerLip, 0.25);

  // Warm apricot-gold crown highlight along upper-left frame ridge (170° to 330°)
  let crownPts = [];
  for (let a = 175; a <= 325; a += 12) {
    let pm = eyeCupPoint(cx, 0, side, 84, 59, a);
    let [wx, wy] = fromGoggleLocal(pm[0], pm[1]);
    let pr = sin(((a - 175) / 150) * 180) * 1.2 + 0.2;
    crownPts.push([wx, wy, pr]);
  }
  brush.set("silicone_shader", "#ffc45c", 1.35);
  brush.spline(crownPts, 0.3);
  brush.noStroke();
}

