function drawFinalSpecularGlints() {
  brush.noStroke();
  brush.noHatch();

  for (let side of [-1, 1]) {
    let cx = side * 134;

    // 1. Primary curved window-like specular reflection on upper-left of each domed lens
    let glint1 = [];
    for (let a = 198; a <= 268; a += 10) {
      let p = eyeCupPoint(cx, 0, side, 58, 39, a);
      glint1.push(fromGoggleLocal(p[0], p[1]));
    }
    for (let a = 268; a >= 198; a -= 10) {
      let p = eyeCupPoint(cx, 0, side, 43, 28, a);
      glint1.push(fromGoggleLocal(p[0], p[1]));
    }

    brush.wash("#fffdf2", 215);
    drawClosedShape(glint1, 0.15);
    brush.noWash();

    // Secondary smaller sky glint dot near 282°
    let glint2 = [];
    for (let a = 276; a <= 300; a += 8) {
      let p = eyeCupPoint(cx, 0, side, 57, 38, a);
      glint2.push(fromGoggleLocal(p[0], p[1]));
    }
    for (let a = 300; a >= 276; a -= 8) {
      let p = eyeCupPoint(cx, 0, side, 47, 31, a);
      glint2.push(fromGoggleLocal(p[0], p[1]));
    }
    brush.wash("#ffffff", 225);
    drawClosedShape(glint2, 0.12);
    brush.noWash();

    // 2. Crisp white pen rim-glints along the frame bezel & lower-right lens bounce
    let rimGlintTop = [];
    for (let a = 190; a <= 295; a += 12) {
      let p = eyeCupPoint(cx, 0, side, 83, 58, a);
      let [wx, wy] = fromGoggleLocal(p[0], p[1]);
      let pr = sin(((a - 190) / 105) * 180) * 1.15 + 0.25;
      rimGlintTop.push([wx, wy, pr]);
    }
    brush.set("rotring", "#ffffff", 1.1);
    brush.spline(rimGlintTop, 0.3);

    // Lower-right inner bevel bounce glint
    let rimGlintBot = [];
    for (let a = 20; a <= 85; a += 10) {
      let p = eyeCupPoint(cx, 0, side, 72, 49, a);
      let [wx, wy] = fromGoggleLocal(p[0], p[1]);
      let pr = sin(((a - 20) / 65) * 180) * 0.95 + 0.2;
      rimGlintBot.push([wx, wy, pr]);
    }
    brush.set("rotring", "#b8f7eb", 0.85);
    brush.spline(rimGlintBot, 0.3);
  }

  // 3. Sharp wet specular glints on nose bridge & strap curl crest
  let bridgeGlint = [
    [...fromGoggleLocal(-24, -13), 0.4],
    [...fromGoggleLocal(0, -14), 1.2],
    [...fromGoggleLocal(24, -13), 0.4]
  ];
  brush.set("rotring", "#ffffff", 1.05);
  brush.spline(bridgeGlint, 0.3);

  // Specular highlights along the curling strap apexes
  let curlApex1 = strapTailPts.slice(18, 30).map((p, i) => [
    p.x + p.nx * 5,
    p.y + p.ny * 5,
    sin((i / 11) * 180) * 1.1 + 0.2
  ]);
  let curlApex2 = strapTailPts.slice(38, 50).map((p, i) => [
    p.x - p.nx * 4,
    p.y - p.ny * 4,
    sin((i / 11) * 180) * 1.1 + 0.2
  ]);
  brush.set("rotring", "#ffffff", 0.95);
  brush.spline(curlApex1, 0.3);
  brush.spline(curlApex2, 0.3);

  brush.noStroke();
}

