// State helpers to guarantee clean p5.brush state transitions
function strokeOnly(name, col, w = 1) {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.set(name, col, w);
}

function washOnly(col, op = 255) {
  brush.noFill();
  brush.noHatch();
  brush.noMass();
  brush.noStroke();
  brush.wash(col, op);
}

function washAndStroke(wCol, wOp, bName, sCol, w = 1) {
  brush.noFill();
  brush.noHatch();
  brush.noMass();
  brush.wash(wCol, wOp);
  brush.set(bName, sCol, w);
}

function polyShape(pts, curv = 0, closed = true) {
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closed);
}

function draw() {
  translate(-width / 2, -height / 2);
  background(PAL.lapisDark);
  brush.noField();

  // =========================================================================
  // 1. FLAT ENAMEL TANJORE SURROUND: SPANDRELS, BORDERS & SANCTUARY VOID
  // =========================================================================
  drawOuterEnamelFrame();
  drawSpandrelArabesques();
  drawSanctuaryVoid();

  // =========================================================================
  // 2. RAISED GOLD TANJORE ARCH (PRABHAVALI) & RUBY/JADE GLASS CABOCHONS
  // =========================================================================
  drawTanjoreGoldArch();
  drawDevotionalPlinth();

  // =========================================================================
  // 3. HYPERREAL SPLIT JACKFRUIT: SOFT MODELING, RIND, BULBS & LATEX THREADS
  // =========================================================================
  drawAltarCastShadows();
  drawStandingJackfruitHalf();
  drawForegroundJackfruitWedge();
  drawLooseSeedsAndRags();
  drawStickyLatexNetwork();

  // Final framing vignettes & crisp gold/ink touchups on foreground cabochons
  drawFinalFrameTouches();

  noLoop();
}

