function drawOuterEnamelFrame() {
  // Base deep lapis field
  washOnly(PAL.lapisMid, 255);
  brush.rect(0, 0, 1200, 1200, "corner");

  // Outer vermilion enamel frame
  washAndStroke(PAL.vermilionMid, 255, "marker", PAL.ink, 1.8);
  brush.rect(14, 14, 1172, 1172, "corner");

  // Stepped gold rail
  washAndStroke(PAL.goldMid, 255, "enamel_pen", PAL.ink, 1.6);
  brush.rect(36, 36, 1128, 1128, "corner");

  // Deep emerald inner border band
  washAndStroke(PAL.emeraldMid, 255, "enamel_pen", PAL.ink, 1.8);
  brush.rect(48, 48, 1104, 1104, "corner");

  // Inner gold fillet surrounding the main field
  washAndStroke(PAL.goldBright, 255, "enamel_pen", PAL.ink, 1.5);
  brush.rect(74, 74, 1052, 1052, "corner");

  // Main deep lapis sanctuary backdrop inside frame
  washAndStroke(PAL.lapisMid, 255, "enamel_pen", PAL.ink, 2.0);
  brush.rect(86, 86, 1028, 1028, "corner");

  // Enamel geometric chevrons/blocks along the emerald border (48..74)
  for (let i = 0; i < 26; i++) {
    let t = map(i, 0, 26, 80, 1120);
    // Top & bottom border blocks
    if (i % 2 === 0) {
      washAndStroke(PAL.vermilionBright, 245, "enamel_pen", PAL.ink, 1.1);
      brush.rect(t - 10, 51, 20, 20, "corner");
      brush.rect(t - 10, 1129, 20, 20, "corner");
      brush.rect(51, t - 10, 20, 20, "corner");
      brush.rect(1129, t - 10, 20, 20, "corner");
    } else {
      let gemType = i % 4 === 1 ? "ruby" : "jade";
      drawCabochon(t, 61, 6.5, 6.5, 0, gemType);
      drawCabochon(t, 1139, 6.5, 6.5, 0, gemType);
      drawCabochon(61, t, 6.5, 6.5, 0, gemType);
      drawCabochon(1139, t, 6.5, 6.5, 0, gemType);
    }
  }

  // Four corner lotus bosses
  const corners = [
    [61, 61],
    [1139, 61],
    [61, 1139],
    [1139, 1139]
  ];
  for (let [cx, cy] of corners) {
    washAndStroke(PAL.goldLeaf, 255, "enamel_pen", PAL.ink, 1.6);
    brush.rect(cx - 24, cy - 24, 48, 48, "corner");
    drawCabochon(cx, cy, 11, 11, 0, "ruby");
    drawCabochon(cx - 14, cy - 14, 4.5, 4.5, 0, "jade");
    drawCabochon(cx + 14, cy - 14, 4.5, 4.5, 0, "jade");
    drawCabochon(cx - 14, cy + 14, 4.5, 4.5, 0, "jade");
    drawCabochon(cx + 14, cy + 14, 4.5, 4.5, 0, "jade");
  }
}

function drawSpandrelArabesques() {
  // Upper spandrel panels in deep lapis with bold vermilion, emerald & gold cloisonne medallions
  const sides = [-1, 1];
  for (let dir of sides) {
    let sx = 600 + dir * 410;
    let sy = 195;

    // Corner stepped vermilion spandrel plaque
    let plaque = [
      [600 + dir * 498, 96],
      [600 + dir * 210, 96],
      [600 + dir * 285, 145],
      [600 + dir * 375, 225],
      [600 + dir * 445, 340],
      [600 + dir * 498, 390]
    ];
    washAndStroke(PAL.vermilionDark, 255, "enamel_pen", PAL.ink, 1.8);
    polyShape(plaque, 0.1, true);

    // Inner emerald scroll leaf in spandrel
    let innerPlaque = [
      [600 + dir * 482, 112],
      [600 + dir * 270, 112],
      [600 + dir * 345, 165],
      [600 + dir * 425, 255],
      [600 + dir * 482, 340]
    ];
    washAndStroke(PAL.emeraldMid, 255, "enamel_pen", PAL.ink, 1.6);
    polyShape(innerPlaque, 0.15, true);

    // Raised gold medallion rosette in upper spandrel
    drawSpandrelRosette(sx, sy, 58, dir);

    // Secondary smaller rosette lower in spandrel
    drawSpandrelRosette(600 + dir * 455, 310, 32, dir);

    // Bold gold & black enamel vine scrolls connecting them
    strokeOnly("marker", PAL.ink, 2.2);
    brush.arc(sx, sy, 68, 0, 360);
    strokeOnly("enamel_pen", PAL.goldLeaf, 1.4);
    brush.arc(sx, sy, 64, 0, 360);
