}

function drawSpandrelRosette(cx, cy, rad, dir) {
  washAndStroke(PAL.goldMid, 255, "enamel_pen", PAL.ink, 1.6);
  brush.circle(cx, cy, rad, 0.02);

  // 12 lotus petals inside medallion alternating vermilion and lapis
  let petals = 12;
  for (let i = 0; i < petals; i++) {
    let a1 = i * (360 / petals);
    let a2 = (i + 0.5) * (360 / petals);
    let a3 = (i + 1) * (360 / petals);
    let pCol = i % 2 === 0 ? PAL.vermilionBright : PAL.lapisBright;
    let pts = [
      [cx + cos(a1) * (rad * 0.28), cy + sin(a1) * (rad * 0.28)],
      [cx + cos(a2) * (rad * 0.88), cy + sin(a2) * (rad * 0.88)],
      [cx + cos(a3) * (rad * 0.28), cy + sin(a3) * (rad * 0.28)]
    ];
    washAndStroke(pCol, 255, "enamel_pen", PAL.ink, 1.1);
    polyShape(pts, 0.2, true);
  }

  // Gold center boss + ruby/jade cabochon cluster
  washAndStroke(PAL.goldLeaf, 255, "enamel_pen", PAL.ink, 1.4);
  brush.circle(cx, cy, rad * 0.34, 0.02);
  drawCabochon(cx, cy, rad * 0.18, rad * 0.18, 0, "ruby");
  for (let i = 0; i < 6; i++) {
    let a = i * 60;
    drawCabochon(
      cx + cos(a) * (rad * 0.26),
      cy + sin(a) * (rad * 0.26),
      rad * 0.07,
      rad * 0.07,
      a,
      "jade"
    );
  }
}

// Compute point along the cusped Tanjore arch contour
// t goes from 0 (left base) to 1 (right base)
function archCuspPoint(t, baseRadius, cuspAmp, numCusps = 9) {
  const cx = 600;
  const cy = 475;
  // Angle in screen space: 180 (left) -> 270 (top) -> 360 (right)
  let ang = 180 + t * 180;
  // Scalloped cusp modulation
  let wave = abs(sin(t * numCusps * 180));
  // Ogee lift near the crown (t ~ 0.5)
  let crownLift = exp(-pow((t - 0.5) / 0.11, 2)) * 34;
  let r = baseRadius + wave * cuspAmp + crownLift;
  return [cx + cos(ang) * r, cy + sin(ang) * r, ang];
}

