  outerTrim.push([1088, 885]);
  // Cut out interior by drawing concentric bands inward
  // Wait: instead of filling across the center, let's draw the arch as a closed thick ribbon band!
  drawArchRibbon(452, 476, 22, 26, PAL.vermilionMid, PAL.ink, 2.0);
  drawArchRibbon(420, 452, 20, 22, PAL.goldBright, PAL.ink, 1.8);
  drawArchRibbon(382, 420, 18, 20, PAL.emeraldMid, PAL.ink, 1.8);
  drawArchRibbon(342, 382, 16, 18, PAL.goldLeaf, PAL.ink, 2.0);
  drawArchRibbon(324, 342, 14, 16, PAL.vermilionDark, PAL.ink, 1.5);

