  // Stud the Emerald Arch Band (r ~ 401) with alternating Ruby & Jade cabochon clusters!
  const numClusters = 19;
  for (let i = 0; i < numClusters; i++) {
    let t = map(i, 0, numClusters - 1, 0.02, 0.98);
    let [cx, cy, ang] = archCuspPoint(t, 401, 19, 9);
    let isPeak = i % 2 === 1;
    if (isPeak) {
      // Rosette cluster of 5 cabochons on cusp peak
      drawCabochonCluster(cx, cy, 8.5, "ruby", "jade");
    } else {
      // Triplet or large oval cabochon in cusp valley
