// Draws a closed U-shaped cusped arch ribbon between innerRadius and outerRadius
function drawArchRibbon(rIn, rOut, ampIn, ampOut, fillCol, strokeCol, sWeight) {
  const steps = 90;
  let pts = [];
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let [px, py] = archCuspPoint(t, rOut, ampOut, 9);
    pts.push([px, py]);
  }
  for (let i = steps; i >= 0; i--) {
    let t = i / steps;
    let [px, py] = archCuspPoint(t, rIn, ampIn, 9);
    pts.push([px, py]);
  }
  washAndStroke(fillCol, 255, "enamel_pen", strokeCol, sWeight);
  polyShape(pts, 0.04, true);

  // Add raised gold inner highlight line if gold band
  if (fillCol === PAL.goldBright || fillCol === PAL.goldLeaf) {
    let hPts = [];
    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let [px, py] = archCuspPoint(
        t,
        (rIn + rOut) * 0.5,
        (ampIn + ampOut) * 0.5,
        9
      );
      hPts.push([px, py]);
    }
    strokeOnly("enamel_pen", PAL.goldSpec, 1.1);
    brush.spline(hPts, 0.2);
  }
}

