// Glass Cabochon Gem Renderer with Gold Bezel & Hard White Catchlight
function drawCabochon(x, y, rx, ry, ang, type) {
  let r = (rx + ry) * 0.5;
  let darkCol = type === "ruby" ? PAL.rubyDark : PAL.jadeDark;
  let midCol = type === "ruby" ? PAL.rubyMid : PAL.jadeMid;
  let brightCol = type === "ruby" ? PAL.rubyBright : PAL.jadeBright;

  // Raised gold bezel setting
  washAndStroke(PAL.goldLeaf, 255, "enamel_pen", PAL.ink, 1.2);
  brush.circle(x, y, r + 2.6, 0.01);

  // Deep enamel cabochon base
  washAndStroke(darkCol, 255, "enamel_pen", PAL.ink, 1.0);
  brush.circle(x, y, r, 0.01);

  // Translucent glowing cabochon interior
  washOnly(midCol, 245);
  brush.circle(x + r * 0.08, y + r * 0.08, r * 0.78, 0.01);

  // Lower-right internal caustic reflection
  washOnly(brightCol, 235);
  brush.circle(x + r * 0.2, y + r * 0.2, r * 0.46, 0.01);

  // HARD WHITE CATCHLIGHT (Upper-Left Glass Dome Specular Glint)
  washOnly("#ffffff", 255);
  brush.circle(x - r * 0.3, y - r * 0.3, max(1.8, r * 0.28), 0.0);
  strokeOnly("rotring", "#ffffff", max(0.9, r * 0.16));
  brush.arc(x, y, r * 0.62, 200, 255);
}

function drawCabochonCluster(cx, cy, centerR, centerType, ringType) {
  // Ring of 6 smaller cabochons around 1 larger central cabochon
  let ringR = centerR * 1.55;
  let subR = centerR * 0.52;
  for (let i = 0; i < 6; i++) {
    let a = i * 60;
    drawCabochon(
      cx + cos(a) * ringR,
      cy + sin(a) * ringR,
      subR,
      subR,
      a,
      ringType
    );
  }
  drawCabochon(cx, cy, centerR, centerR, 0, centerType);
}

