// Evaluates point on the standing jackfruit's outer organic kidney-ovoid contour
function standingOuterPoint(angDeg, scaleM = 1.0) {
  const cx = 605;
  const cy = 515;
  let rx = 212 * scaleM;
  let ry = 268 * scaleM;
  // Organic jackfruit asymmetry (swollen lower belly, slightly indented left waist)
  let bulge =
    1.0 +
    0.08 * sin(angDeg * 2 - 30) +
    0.06 * cos(angDeg - 45) +
    0.04 * sin(angDeg * 3);
  let x = cx + cos(angDeg) * rx * bulge;
  let y = cy + sin(angDeg) * ry * bulge;
  return [x, y];
}

// Evaluates point on the cut interior face contour (shifted slightly left-down)
function standingCutRimPoint(angDeg, scaleM = 1.0) {
  const cx = 586;
  const cy = 524;
  let rx = 178 * scaleM;
  let ry = 236 * scaleM;
  let bulge =
    1.0 +
    0.07 * sin(angDeg * 2 - 25) +
    0.05 * cos(angDeg - 55) +
    0.03 * sin(angDeg * 3);
  let x = cx + cos(angDeg) * rx * bulge;
  let y = cy + sin(angDeg) * ry * bulge;
  return [x, y];
}

function drawStandingJackfruitHalf() {
  // 1. Woody Cut Peduncle (Stem) at the Crown (580, 175..260)
  drawJackfruitStem();

  // 2. Outer Nubbled Green Rind Mass (Back & Right Swollen 3D Body)
  let outerHull = [];
  for (let i = 0; i < 60; i++) {
    outerHull.push(standingOuterPoint(i * 6, 1.0));
  }
  washAndStroke(PAL.rindDark, 255, "charcoal", PAL.rindShadow, 1.5);
  polyShape(outerHull, 0.15, true);

  // Soft watercolor shading across the 3D rind mass (lit upper-left, shaded lower-right)
  brush.noStroke();
  brush.noWash();
  brush.fill(PAL.rindOlive, 150);
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.5, 0.3);
  let litRind = [];
  for (let a = 175; a <= 335; a += 10) {
    litRind.push(standingOuterPoint(a, 0.98));
  }
  for (let a = 335; a >= 175; a -= 10) {
    litRind.push(standingCutRimPoint(a, 0.92));
  }
  polyShape(litRind, 0.2, true);

  // Deep shadow glaze on lower-right rind belly
  brush.fill(PAL.rindShadow, 175);
  brush.fillBleed(0.25, "out");
  let darkRind = [];
  for (let a = -25; a <= 135; a += 10) {
    darkRind.push(standingOuterPoint(a, 0.99));
  }
  for (let a = 135; a >= -25; a -= 10) {
    darkRind.push(standingCutRimPoint(a, 0.92));
  }
  polyShape(darkRind, 0.2, true);

  // 3. Render hundreds of individual 3D hexagonal conical nubbles (tubercles) on the visible outer rind!
  drawStandingRindNubbles();

  // 4. Cut Rind Cortex Rim (Pale greenish-cream fibrous ring with oxidized sap stains)
  let cutOuter = [];
  let cutInner = [];
  for (let i = 0; i < 64; i++) {
    let a = i * (360 / 64);
    cutOuter.push(standingCutRimPoint(a, 1.0));
    cutInner.push(standingCutRimPoint(a, 0.91));
  }
  washAndStroke(PAL.pithLight, 250, "2B", PAL.pithDark, 1.1);
  polyShape(cutOuter, 0.15, true);

  // Soft modeled shading & radial vascular marks on the cut rind rim
  for (let i = 0; i < 180; i++) {
    let a = i * 2;
    let [x1, y1] = standingCutRimPoint(a, 0.995);
    let [x2, y2] = standingCutRimPoint(a, 0.915);
    let col =
      i % 5 === 0
        ? PAL.rindOlive
        : i % 3 === 0
        ? "#8c6942"
        : PAL.pithMid;
    strokeOnly("2B", col, random(0.6, 1.1));
    brush.line(x1, y1, x2, y2);
  }

  // 5. Deep Interior Cavity & Creamy Fibrous Rag (Chavini) Bed
  washAndStroke("#2b1504", 255, "charcoal", "#1a0b01", 1.4);
  polyShape(cutInner, 0.15, true);

  // Draw hundreds of silky, curved cream/ochre perianth rag ribbons radiating from the core
  drawInteriorFibrousRag(584, 515, 162, 212);

  // 6. Central Fibrous Core (Pith / Ragi Axis)
  drawCentralCore(584, 495);

  // 7. THE WAXY SAFFRON BULBS (ARILS) — Radial Tiers of Obsessive 3D Realism!
  drawStandingSaffronBulbs();
}

function drawJackfruitStem() {
  // Thick curved woody green-brown peduncle hooked at top of jackfruit
  let stemPts = [
    [558, 265],
    [548, 215],
    [556, 178],
    [588, 172],
    [602, 208],
    [608, 262]
  ];
  washAndStroke(PAL.rindMid, 255, "charcoal", PAL.rindShadow, 1.6);
  polyShape(stemPts, 0.2, true);

  // Longitudinal woody ridges and collar rings on the stem
  for (let i = 0; i < 28; i++) {
    let f = i / 27;
    let xTop = lerp(556, 588, f);
    let yTop = lerp(178, 172, f) + sin(f * 180) * 5;
    let xBot = lerp(552, 606, f);
    let yBot = 262;
    let col =
      f < 0.45 ? PAL.rindHighlight : f < 0.75 ? PAL.rindMid : PAL.rindShadow;
    strokeOnly("cpencil", col, random(0.7, 1.3));
    brush.spline(
      [
        [xTop, yTop],
        [(xTop + xBot) * 0.5 - 6, (yTop + yBot) * 0.5],
        [xBot, yBot]
      ],
      0.3
    );
  }

  // Cut woody top ellipse of stem
  washAndStroke(PAL.pithMid, 255, "2B", PAL.rindShadow, 1.2);
  brush.circle(572, 176, 15, 0.08);
  strokeOnly("cpencil", PAL.pithCream, 0.9);
  brush.circle(572, 176, 8, 0.05);
}

function drawStandingRindNubbles() {
  // Populate the visible outer rind crescent & crown with 3D conical hexagonal spines
  const rings = 14;
  for (let rIdx = 0; rIdx < rings; rIdx++) {
    let f = rIdx / (rings - 1);
    let numA = 56;
    for (let aIdx = 0; aIdx < numA; aIdx++) {
      let ang = aIdx * (360 / numA) + (rIdx % 2) * (180 / numA);
      let [ox, oy] = standingOuterPoint(ang, 0.99);
      let [ix, iy] = standingCutRimPoint(ang, 0.99);

      // Distance between outer hull and cut rim at this angle
      let distRim = dist(ox, oy, ix, iy);
      if (distRim > 9) {
        let px = lerp(ix, ox, f);
        let py = lerp(iy, oy, f);
        // Outward normal direction for spine tip
        let tipLen = map(f, 0, 1, 3.5, 7.5);
        let nx = cos(ang) * tipLen;
        let ny = sin(ang) * tipLen;
        // Light factor based on angle (upper-left ~ 225 deg is brightest)
        let light = map(cos(ang - 225), -1, 1, 0.05, 1.0);
        drawSingleRindNubble(px, py, nx, ny, 5.8, light);
      }
    }
  }
}

// Draws one 3D conical jackfruit spine/tubercle with lit facet, shadow facet & dark tip
function drawSingleRindNubble(cx, cy, nx, ny, rad, light) {
  let tx = cx + nx;
  let ty = cy + ny;
  let px = -ny * 0.85;
  let py = nx * 0.85;

  let litCol =
    light > 0.65
      ? PAL.rindHighlight
      : light > 0.35
      ? PAL.rindSage
      : PAL.rindOlive;
  let darkCol =
    light > 0.65 ? PAL.rindOlive : light > 0.35 ? PAL.rindMid : PAL.rindDark;

  // Dark hexagonal crevice base
  strokeOnly("2B", PAL.rindShadow, 1.1);
  brush.circle(cx, cy, rad, 0.08);

  // Shaded cone facet
  washOnly(darkCol, 240);
  polyShape(
    [
      [cx - px, cy - py],
      [cx + px, cy + py],
      [tx, ty]
    ],
    0.05,
    true
  );

  // Lit upper-left cone facet
  washOnly(litCol, 245);
  polyShape(
    [
      [cx - px * 0.9, cy - py * 0.9],
      [cx - nx * 0.6, cy - ny * 0.6],
      [tx, ty]
    ],
    0.05,
    true
  );

  // Tiny dark brown spiny point at apex
  strokeOnly("rotring", "#1f150b", 1.1);
  brush.line(tx, ty, tx + nx * 0.22, ty + ny * 0.22);
}

