// Obsessively Modeled Waxy Saffron Jackfruit Bulb (Aril)
function drawWaxySaffronBulb(bx, by, len, wid, ang, lightBias, isCutOpen) {
  push();
  translate(bx, by);
  rotate(ang);

  let halfL = len * 0.5;
  let halfW = wid * 0.5;

  // Plump pear/kidney silhouette of a jackfruit aril (narrower toward core -x, fuller toward +x)
  let bulbPts = [];
  const steps = 28;
  for (let i = 0; i < steps; i++) {
    let a = i * (360 / steps);
    let ca = cos(a);
    let sa = sin(a);
    // Pear taper: fuller when ca > 0
    let taper = 1.0 + 0.24 * ca - 0.08 * cos(2 * a);
    let groove = 1.0 + 0.04 * sin(3 * a);
    let x = ca * halfL * groove;
    let y = sa * halfW * taper * groove;
    bulbPts.push([x, y]);
  }

  // 1. Deep Crevice Ambient Occlusion Shadow behind the bulb
  washAndStroke(PAL.saffronCrevice, 235, "charcoal", "#240a01", 1.4);
  let shadowPts = bulbPts.map(([x, y]) => [x + 3.5, y + 4.5]);
  polyShape(shadowPts, 0.2, true);

  // 2. Base Waxy Amber-Saffron Body Wash
  washAndStroke(PAL.saffronRich, 255, "wax_shader", PAL.saffronDeep, 1.1);
  polyShape(bulbPts, 0.22, true);

  // 3. Soft Modeled Shading: Lower-side Burnt Amber Shadow vs Upper-side Glowing Saffron
  let lowerShade = [];
  for (let a = 10; a <= 175; a += 15) {
    let ca = cos(a),
      sa = sin(a);
    let taper = 1.0 + 0.24 * ca;
    lowerShade.push([ca * halfL * 0.96, sa * halfW * taper * 0.96]);
  }
  for (let a = 175; a >= 10; a -= 25) {
    let ca = cos(a),
      sa = sin(a);
    lowerShade.push([ca * halfL * 0.65, sa * halfW * 0.2]);
  }
  washOnly(PAL.saffronAmber, 225);
  polyShape(lowerShade, 0.2, true);

  // Main Luminous Saffron-Marigold Upper Dome
  let upperDome = [];
  for (let a = 165; a <= 370; a += 15) {
    let ca = cos(a),
      sa = sin(a);
    let taper = 1.0 + 0.22 * ca;
    upperDome.push([ca * halfL * 0.9, sa * halfW * taper * 0.85]);
  }
  for (let a = 370; a >= 165; a -= 25) {
    let ca = cos(a);
    upperDome.push([ca * halfL * 0.72, halfW * 0.18]);
  }
  washOnly(lightBias > 0.75 ? PAL.saffronBright : PAL.saffronMid, 240);
  polyShape(upperDome, 0.22, true);

  // Subsurface Waxy Apricot-Gold Core Glow
  washOnly(PAL.saffronGlow, 215);
  brush.circle(halfL * 0.14, -halfW * 0.14, halfW * 0.56, 0.08);

  // 4. Longitudinal Waxy Folds, Ridges & Cross-Contour Modeling (24 strokes per bulb)
  // Real jackfruit bulbs have distinctive longitudinal creases and plump lobes
  const numRidges = 13;
  for (let r = 0; r < numRidges; r++) {
    let vf = map(r, 0, numRidges - 1, -0.82, 0.82);
    let p1 = [-halfL * 0.82, vf * halfW * 0.52];
    let p2 = [0, vf * halfW * 0.92];
    let p3 = [halfL * 0.82, vf * halfW * 0.68];

    // Crease valleys at vf ~ -0.28 and vf ~ 0.32
    let isCrease = abs(vf + 0.26) < 0.11 || abs(vf - 0.3) < 0.11;
    let col;
    let w;
    if (isCrease) {
      col = PAL.saffronAmber;
      w = 1.15;
    } else if (vf < 0.15) {
      col = vf < -0.35 ? PAL.saffronGlow : PAL.saffronWax;
      w = 1.25;
    } else {
      col = vf > 0.55 ? PAL.saffronDeep : PAL.saffronRich;
      w = 1.1;
    }
    strokeOnly("cpencil", col, w);
    brush.spline([p1, p2, p3], 0.35);
  }

  // 5. If Cut Open: Reveal Juicy Flesh Wall & Glossy Brown Jackfruit Seed (Chakka Kuru)
  if (isCutOpen) {
    // Cut cavity rim in bright saffron-gold
    washAndStroke(PAL.saffronGlow, 250, "cpencil", PAL.saffronAmber, 1.1);
    brush.circle(halfL * 0.08, 0, halfW * 0.68, 0.06);

    // Pale papery seed coat (spermoderm) lining the cavity
    washAndStroke(PAL.pithCream, 245, "2B", PAL.pithMid, 0.9);
    brush.circle(halfL * 0.08, 0, halfW * 0.52, 0.05);

    // Smooth mahogany-brown oval seed inside
    washAndStroke(PAL.seedMid, 255, "cpencil", PAL.seedDark, 1.2);
    brush.circle(halfL * 0.1, 0, halfW * 0.42, 0.04);

    // Seed highlight
    washOnly(PAL.seedLight, 230);
    brush.circle(halfL * 0.05, -halfW * 0.08, halfW * 0.22, 0.03);
    strokeOnly("rotring", "#ffffff", 1.1);
    brush.arc(halfL * 0.08, -halfW * 0.04, halfW * 0.26, 200, 290);
  } else {
    // 6. Wet, Waxy Specular Highlights along the 2 main longitudinal lobe crests!
    // Upper lobe specular ribbon
    let spec1 = [
      [-halfL * 0.52, -halfW * 0.28],
      [-halfL * 0.05, -halfW * 0.48],
      [halfL * 0.46, -halfW * 0.34]
    ];
    strokeOnly("cpencil", PAL.saffronWax, 1.7);
    brush.spline(spec1, 0.35);
    strokeOnly("rotring", "#ffffff", 1.15);
    brush.spline(
      [
        [-halfL * 0.32, -halfW * 0.36],
        [halfL * 0.05, -halfW * 0.46],
        [halfL * 0.34, -halfW * 0.38]
      ],
      0.35
    );

    // Mid-belly secondary waxy sheen ribbon
    let spec2 = [
      [-halfL * 0.44, halfW * 0.04],
      [halfL * 0.06, -halfW * 0.04],
      [halfL * 0.52, halfW * 0.05]
    ];
    strokeOnly("cpencil", PAL.saffronWax, 1.5);
    brush.spline(spec2, 0.35);
    strokeOnly("rotring", "#ffffff", 0.95);
    brush.line(-halfL * 0.12, -halfW * 0.02, halfL * 0.26, 0);

    // Moist pinpoint catchlights near the swollen tip
    washOnly("#ffffff", 250);
    brush.circle(halfL * 0.48, -halfW * 0.16, 2.2, 0);
    brush.circle(halfL * 0.56, -halfW * 0.06, 1.4, 0);
  }

  pop();
}

