  for (let [dx, dy, dr] of sapDrops) {
    drawLatexGlobule(dx, dy, dr);
  }

  // 2. Taut, elastic sticky white latex filaments stretching across the split cleft
  // between the upper standing jackfruit half and the lower foreground wedge,
  // as well as crisscrossing between adjacent saffron bulbs!
  const bridges = [
    // Major vertical/diagonal cleft bridges (between standing half and foreground wedge)
