    [488, 658, 468, 738, -5],
    [508, 672, 496, 714, 4],
    [526, 654, 514, 736, -8],
    [546, 642, 535, 718, 6],
    [568, 618, 558, 712, -4],
    [584, 636, 578, 742, 5],
    [604, 646, 598, 716, -6],
    [622, 668, 618, 738, 7],
    [645, 632, 636, 718, -5],
    [664, 658, 658, 742, 8],
    [682, 642, 678, 726, -6],
    [704, 612, 712, 736, 10],
    // Long dramatic diagonal latex strands from the central core down to the foreground wedge
    [575, 492, 455, 725, 18],
    [594, 538, 502, 718, 14],
    [588, 552, 615, 716, -15],
    [604, 488, 672, 724, -22],
    [568, 392, 498, 498, 12],
    [598, 398, 668, 452, -12],
    // Inter-bulb sticky web bridges across the upper half
    [504, 426, 562, 438, 6],
    [562, 438, 612, 492, -5],
    [498, 498, 576, 562, 8],
    [576, 562, 658, 594, -7],
    [612, 492, 674, 522, 5],
    [535, 362, 638, 382, 10],
