  for (let [x1, y1, x2, y2, sag] of bridges) {
    drawStickyLatexStrand(x1, y1, x2, y2, sag);
  }
}

function drawLatexGlobule(x, y, r) {
  // Subtle contact shadow
  washOnly("#2b1c0e", 160);
  brush.circle(x + 1.2, y + 1.8, r, 0.05);
  // Translucent milk-slate outer drop
  washAndStroke(PAL.latexMid, 235, "rotring", PAL.latexShadow, 0.6);
  brush.circle(x, y, r, 0.05);
  // Pure white coagulated center & specular catchlight
  washOnly(PAL.latexPure, 255);
  brush.circle(x - r * 0.2, y - r * 0.2, r * 0.65, 0.02);
}

function drawStickyLatexStrand(x1, y1, x2, y2, sag) {
  let mx = (x1 + x2) * 0.5 + sag * 0.4;
  let my = (y1 + y2) * 0.5 + abs(sag);

  // Direction vector & perpendicular for Y-shaped anchor forks
  let dx = x2 - x1;
  let dy = y2 - y1;
  let d = sqrt(dx * dx + dy * dy);
  let nx = (-dy / d) * 6.5;
  let ny = (dx / d) * 6.5;

  // 1. Subtle dark refraction shadow right behind the white filament
  strokeOnly("rotring", "#291807", 0.85);
  brush.spline(
    [
      [x1 + 1, y1 + 1.5],
      [mx + 1, my + 1.5],
      [x2 + 1, y2 + 1.5]
    ],
    0.35
  );

  // 2. Forked sticky tension web anchors at both ends (Y-junctions)
  let pStartFork = [
    x1 + dx * 0.12 + sag * 0.08,
    y1 + dy * 0.12 + abs(sag) * 0.18
  ];
  let pEndFork = [
    x2 - dx * 0.12 + sag * 0.08,
    y2 - dy * 0.12 + abs(sag) * 0.18
  ];

  strokeOnly("latex_thread", PAL.latexMid, 0.85);
  brush.line(x1 + nx, y1 + ny, pStartFork[0], pStartFork[1]);
  brush.line(x1 - nx, y1 - ny, pStartFork[0], pStartFork[1]);
  brush.line(x2 + nx, y2 + ny, pEndFork[0], pEndFork[1]);
  brush.line(x2 - nx, y2 - ny, pEndFork[0], pEndFork[1]);

  // Tiny milky adhesion pads at attachment points
  washOnly(PAL.latexPure, 240);
  brush.circle(x1, y1, 2.2, 0.05);
  brush.circle(x2, y2, 2.2, 0.05);

  // 3. Main Taut Elastic White Latex Thread
  strokeOnly("latex_thread", PAL.latexPure, 1.15);
  brush.spline(
    [
      [x1, y1],
      [mx, my],
      [x2, y2]
    ],
    0.35
  );

  // Secondary ultra-fine parallel sister filament
  strokeOnly("rotring", PAL.latexMid, 0.55);
  brush.spline(
    [
      [x1 + nx * 0.45, y1 + ny * 0.45],
      [mx - nx * 0.3, my - ny * 0.3],
      [x2 - nx * 0.45, y2 - ny * 0.45]
    ],
    0.35
  );

  // 4. Tiny glistening white sap beads clinging along the stretched thread
  for (let k = 1; k <= 2; k++) {
    let tf = k === 1 ? 0.35 : 0.68;
    let bx = lerp(lerp(x1, mx, tf), lerp(mx, x2, tf), tf);
    let by = lerp(lerp(y1, my, tf), lerp(my, y2, tf), tf);
    washOnly(PAL.latexPure, 255);
    brush.circle(bx, by, random(1.4, 2.5), 0);
  }
}

function drawFinalFrameTouches() {
  // Crisp heavy black enamel inner border lines to make the flat devotional frame pop
  strokeOnly("enamel_pen", PAL.ink, 2.2);
  brush.rect(14, 14, 1172, 1172, "corner");
  brush.rect(86, 86, 1028, 1028, "corner");
}

// Hyperreal Action-Painting: Bursting Raw Egg on a Corrugated Galvanised Wall
// p5.js 2.x + p5.brush

const IX = 640;
const IY = 545;
const WALL_TILT = -4.2;
const CORR_PERIOD = 96;
const SEAM_U = -185;

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(84729);
  noiseSeed(19384);

  // Custom chisel marker for violent action-painting swipes
  brush.add("action_chisel", {
    type: "custom",
    weight: 18,
    scatter: 0.06,
    opacity: 175,
    spacing: 0.14,
    pressure: [1.15, 0.95, 0.15],
    tip: (_m) => {
      _m.rotate(-28);
      _m.rect(-5, -1.4, 10, 2.8);
    },
    rotate: "natural",
    markerTip: false,
    noise: 0.35
  });

  // Custom dragged dry-marker bristle brush
  brush.add("dry_swipe", {
    type: "custom",
    weight: 12,
    scatter: 0.35,
    opacity: 140,
    spacing: 0.18,
    pressure: [1.0, 0.7, 0.05],
    tip: (_m) => {
      _m.rotate(-15);
      _m.rect(-4, -0.5, 8, 0.8);
      _m.rect(-3, 0.9, 6, 0.6);
      _m.rect(-4, -1.8, 7, 0.5);
    },
    rotate: "natural",
    markerTip: false,
    noise: 0.7
  });

  // Custom ballistic radial blast vector field
  brush.addField("ballistic_blast", (t, field) => {
    for (let col = 0; col < field.length; col++) {
      for (let row = 0; row < field[0].length; row++) {
        let x = map(col, 0, field.length - 1, 0, width);
        let y = map(row, 0, field[0].length - 1, 0, height);
        let dx = x - IX;
        let dy = y - IY;
        let baseAngle = atan2(dy, dx);
        let distNorm = sqrt(dx * dx + dy * dy) / 800;
        let whip = sin(distNorm * 180 + baseAngle * 2) * 14;
        let rippleDeflect = cos(getWallPhase(x, y)) * 8;
        field[col][row] = baseAngle + whip + rippleDeflect;
      }
    }
    return field;
  });
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#131a22");

  // 1. Corrugated Galvanised Zinc Wall in Dusky Twilight
  drawCorrugatedWall();

  // 2. The One Rusty Vertical Lap Seam & Weathered Hex Bolts
  drawRustySeam();

  // 3. Action-Painting Under-Blast: Violent Marker Swipes & Ballistic Streaks
  drawActionMarkerBlast();

  // 4. Hyperreal Translucent Albumen Splash, Webbing, Meniscus & Chalaza
  drawAlbumenSplash();

  // 5. Rupturing Cadmium Yolk: Subsurface Glow, Membrane Wrinkles & Wet Gloss
  drawBurstingYolk();

  // 6. Forensic Shattered Eggshell Shards: 3D Rims, Peeling Membrane & Cracks
  drawEggshellShards();

  // 7. Foreground Action-Painting Over-Swipes, Flung Droplets & Fine Mist
  drawForegroundSprayAndDroplets();

  noLoop();
}

// =============================================================================
// GEOMETRY & SURFACE MATH HELPERS
// =============================================================================

function toWallUV(x, y) {
  let dx = x - 600;
  let dy = y - 600;
  let c = cos(-WALL_TILT);
  let s = sin(-WALL_TILT);
  return {
    u: dx * c - dy * s,
    v: dx * s + dy * c
  };
}

function fromWallUV(u, v) {
  let c = cos(WALL_TILT);
  let s = sin(WALL_TILT);
  return {
    x: 600 + u * c - v * s,
    y: 600 + u * s + v * c
  };
}

function getWallPhase(x, y) {
  let uv = toWallUV(x, y);
  let ph = (((uv.v + 720) / CORR_PERIOD) * 360) % 360;
  return ph < 0 ? ph + 360 : ph;
}

// Returns z in [-1, 1] (+1 = ridge crest, -1 = valley trough)
function getWallZ(x, y) {
  return cos(getWallPhase(x, y));
}

// Returns lighting intensity in [0, 1] for the corrugated zinc cylinder
function getWallLight(phase) {
  // Upper slope faces sky (phase 190..355, peak specular at 305)
  // Downward slope in deep shadow (phase 15..145, darkest core at 75)
  // Valley trough gets subtle cool bounce light (phase 145..195)
  let skyDiff = pow(max(0, -sin(phase - 25)), 1.35);
  let spec = pow(max(0, cos(phase - 312)), 7.0) * 0.55;
  let bounce = pow(max(0, cos(phase - 172)), 4.0) * 0.22;
  let shadowCore = pow(max(0, sin(phase - 15)), 1.6) * 0.35;
  return constrain(0.18 + skyDiff * 0.58 + spec + bounce - shadowCore, 0.04, 1.0);
}

function safeSpline(pts, curvature = 0.5) {
  if (!pts || pts.length < 3) return;
  let clean = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    let prev = clean[clean.length - 1];
    let d = dist(prev[0], prev[1], pts[i][0], pts[i][1]);
    if (d > 1.0) clean.push(pts[i]);
  }
  if (clean.length >= 3) {
    brush.spline(clean, curvature);
  } else if (clean.length === 2) {
    brush.line(clean[0][0], clean[0][1], clean[1][0], clean[1][1]);
  }
}

function drawShapePoly(pts, curvature = 0, closed = true) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closed);
}

// =============================================================================
// 1. CORRUGATED GALVANISED WALL
// =============================================================================

function drawCorrugatedWall() {
  brush.noField();
  brush.noStroke();
  brush.noHatch();

  let stripStep = 8;
  let steelPalette = [
    "#111720", "#161f2b", "#1d2836", "#253344",
    "#304154", "#3d5166", "#4d647a", "#607991",
    "#7791a8", "#91abc2", "#aec7de", "#cbe0f2"
  ];

  // Cylindrical shading bands across the tilted corrugations
  for (let v = -720; v <= 720; v += stripStep) {
    let phase = (((v + 720) / CORR_PERIOD) * 360) % 360;
    if (phase < 0) phase += 360;
    let light = getWallLight(phase);
    let idx = constrain(floor(light * steelPalette.length), 0, steelPalette.length - 1);
    let col = steelPalette[idx];

    let p1 = fromWallUV(-740, v - stripStep * 0.65);
    let p2 = fromWallUV(740, v - stripStep * 0.65);
    let p3 = fromWallUV(740, v + stripStep * 0.65);
    let p4 = fromWallUV(-740, v + stripStep * 0.65);

    brush.wash(col, 210);
    drawShapePoly([
      [p1.x, p1.y],
      [p2.x, p2.y],
      [p3.x, p3.y],
      [p4.x, p4.y]
    ], 0, true);
  }
  brush.noWash();

  // Atmospheric twilight washes for subtle tonal modulation across the wall
  let twilightClouds = [
    { x: 220, y: 240, r: 360, col: "#1a2233", op: 45 },
    { x: 980, y: 200, r: 420, col: "#25364a", op: 40 },
    { x: 250, y: 950, r: 440, col: "#121722", op: 55 },
    { x: 960, y: 960, r: 390, col: "#192330", op: 50 }
  ];
  brush.fillBleed(0.4, "out");
  brush.fillTexture(0.55, 0.3);
  for (let tc of twilightClouds) {
    brush.fill(tc.col, tc.op);
    brush.circle(tc.x, tc.y, tc.r, 0.35);
  }
  brush.noFill();

  // Galvanised Zinc Spangle: interlocking crystalline metallic facets
  let spangleColorsDark = ["#1c2633", "#263445", "#324357", "#3f5369"];
  let spangleColorsMid = ["#4e647a", "#637b94", "#7992ab", "#8fa9c2"];
  let spangleColorsBright = ["#a6bfd6", "#bfd6eb", "#d8eaf7", "#eef7ff"];

  for (let v = -660; v <= 660; v += 18) {
    let phase = (((v + 720) / CORR_PERIOD) * 360) % 360;
    if (phase < 0) phase += 360;
    let light = getWallLight(phase);

    // Spangle is most prominent on sky-lit slopes, ridges, and bounce zones
    if (light < 0.24 && random() < 0.65) continue;

    let uCursor = -660 + random(-20, 20);
    while (uCursor < 660) {
      let w = random(18, 48);
      let h = random(7, 16);
      if (random() < 0.42) {
        let pool = light > 0.72 ? spangleColorsBright : (light > 0.42 ? spangleColorsMid : spangleColorsDark);
        let c = random(pool);
        let op = light > 0.7 ? random(65, 135) : random(35, 85);

        let sides = floor(random(4, 6));
        let poly = [];
        for (let s = 0; s < sides; s++) {
          let ang = (s / sides) * 360 + random(-18, 18);
          let su = uCursor + cos(ang) * w * 0.5;
          let sv = v + sin(ang) * h * 0.5;
          let pt = fromWallUV(su, sv);
          poly.push([pt.x, pt.y]);
        }
        brush.noStroke();
        brush.wash(c, op);
        drawShapePoly(poly, 0, true);
        brush.noWash();

        // Crisp crystalline facet glint on the brightest zinc spangles
        if (light > 0.68 && random() < 0.45) {
          brush.set("2H", "#e3f0fc", random(0.3, 0.55));
          brush.line(poly[0][0], poly[0][1], poly[1][0], poly[1][1]);
        }
      }
      uCursor += w * random(0.85, 1.6);
    }
  }

  // Fine rolled-metal longitudinal grain, ridge highlights, and dark shadow troughs
  for (let k = -8; k <= 8; k++) {
    let baseV = k * CORR_PERIOD - 720 + CORR_PERIOD;
    if (baseV < -680 || baseV > 680) continue;

    // 1. Specular crest highlight (phase ~ 312 deg = 0.866 * CORR_PERIOD)
    let crestV = baseV - CORR_PERIOD * 0.13;
    for (let s = 0; s < 14; s++) {
      let u1 = random(-650, 580);
      let u2 = u1 + random(60, 240);
      let vOff = crestV + random(-5, 5);
      let p1 = fromWallUV(u1, vOff);
      let p2 = fromWallUV(u2, vOff);
      brush.set("2H", random() < 0.5 ? "#d4e6f7" : "#f0f8ff", random(0.35, 0.8));
      brush.line(p1.x, p1.y, p2.x, p2.y);
    }

    // 2. Deep shadow core under each ridge (phase ~ 70 deg = 0.19 * CORR_PERIOD)
    let shadowV = baseV + CORR_PERIOD * 0.19;
    for (let s = 0; s < 10; s++) {
      let u1 = random(-650, 580);
      let u2 = u1 + random(80, 280);
      let vOff = shadowV + random(-6, 6);
      let p1 = fromWallUV(u1, vOff);
      let p2 = fromWallUV(u2, vOff);
      brush.set("charcoal", "#0b1017", random(0.45, 0.95));
      brush.line(p1.x, p1.y, p2.x, p2.y);
    }

    // 3. Weathered micro-scratches across the zinc
    for (let s = 0; s < 8; s++) {
      let u1 = random(-620, 620);
      let v1 = baseV + random(-40, 40);
      let p1 = fromWallUV(u1, v1);
      let p2 = fromWallUV(u1 + random(-35, 35), v1 + random(-8, 8));
      brush.set("rotring", random() < 0.4 ? "#a8bfd4" : "#1b2430", 0.3);
      brush.line(p1.x, p1.y, p2.x, p2.y);
    }
  }
}

// =============================================================================
// 2. THE ONE RUSTY SEAM & HEX RIVETS
// =============================================================================

function drawRustySeam() {
  brush.noField();

  // Compute the sinusoidal 3D lap-edge of the overlapping corrugated sheet
  let seamPts = [];
  let shadowLeftPts = [];
  let stepV = 12;

  for (let v = -680; v <= 680; v += stepV) {
    let phase = (((v + 720) / CORR_PERIOD) * 360) % 360;
    if (phase < 0) phase += 360;
    let z = cos(phase);
    let jag = (noise(v * 0.025, 10) - 0.5) * 9;
    let uEdge = SEAM_U + z * 11 + jag;
    let shadowW = map(z, -1, 1, 7, 22);

    seamPts.push({ u: uEdge, v: v, z: z, phase: phase });
    shadowLeftPts.push({ u: uEdge - shadowW, v: v });
  }

  // 1. Rusty Watercolor Bleeds & Corrosion Stains along the seam and into troughs
  brush.noStroke();
  brush.fillBleed(0.38, "out");
  brush.fillTexture(0.75, 0.55);

  let rustWashPalette = ["#3d170b", "#5e220f", "#853114", "#ab4319", "#c95b22"];
  for (let i = 0; i < seamPts.length; i += 3) {
    let sp = seamPts[i];
    // Rust pools more heavily in the valley troughs (z < 0)
    let spread = sp.z < 0 ? random(28, 72) : random(14, 34);
    let pt = fromWallUV(sp.u + random(-14, 18), sp.v);
    let col = random(rustWashPalette);
    let op = sp.z < 0 ? random(85, 145) : random(50, 95);
    brush.fill(col, op);
    brush.circle(pt.x, pt.y, spread, 0.45);
  }
  brush.noFill();

  // 2. Crisp undulating cast shadow under the overlapping right sheet
  let shadowPoly = [];
  for (let i = 0; i < seamPts.length; i++) {
    let p = fromWallUV(seamPts[i].u, seamPts[i].v);
    shadowPoly.push([p.x, p.y]);
  }
  for (let i = shadowLeftPts.length - 1; i >= 0; i--) {
    let p = fromWallUV(shadowLeftPts[i].u, shadowLeftPts[i].v);
    shadowPoly.push([p.x, p.y]);
  }
  brush.noStroke();
  brush.wash("#0b0f15", 215);
  drawShapePoly(shadowPoly, 0, true);
  brush.noWash();

  // 3. Dry flaky iron-oxide crust along the seam edge
  for (let i = 0; i < seamPts.length - 1; i++) {
    let p1 = fromWallUV(seamPts[i].u, seamPts[i].v);
    let p2 = fromWallUV(seamPts[i + 1].u, seamPts[i + 1].v);

    // Dark corroded crevice line
    brush.set("charcoal", "#2b1008", random(0.8, 1.4));
    brush.line(p1.x, p1.y, p2.x, p2.y);

    // Bright orange-ochre rust edge & exposed nicked metal
    if (random() < 0.75) {
      let c = random(["#9e3b16", "#c4511f", "#df6d2b", "#6e260e"]);
      brush.set("cpencil", c, random(0.6, 1.2));
      brush.line(p1.x + random(-4, 6), p1.y, p2.x + random(-4, 6), p2.y);
    }

    // Specular metallic glint on the cut sheet thickness where lit
    if (seamPts[i].z > 0.2 && random() < 0.6) {
      brush.set("rotring", "#b8cde0", 0.45);
      brush.line(p1.x + 2, p1.y, p2.x + 2, p2.y);
    }
  }

  // Rust spatter & pitting along the seam
  for (let i = 0; i < 90; i++) {
    let idx = floor(random(seamPts.length));
    let sp = seamPts[idx];
    let pt = fromWallUV(sp.u + random(-35, 45), sp.v + random(-15, 15));
    brush.set("spray", random(["#4d1b0c", "#8c3314", "#c75820"]), random(0.4, 0.9));
    brush.line(pt.x, pt.y, pt.x + random(-8, 8), pt.y + random(-8, 8));
  }

  // 4. Weathered Hexagonal Rivet Bolts in the Troughs + Weeping Rust Streaks
  for (let k = -6; k <= 6; k += 2) {
    let troughV = k * CORR_PERIOD - 720 + CORR_PERIOD * 0.5;
    if (troughV < -580 || troughV > 580) continue;

    let boltU = SEAM_U + 22;
    let center = fromWallUV(boltU, troughV);

    // Weeping vertical rust drips below each bolt
    let numDrips = floor(random(3, 6));
    for (let d = 0; d < numDrips; d++) {
      let dripPts = [];
      let du = boltU + random(-8, 8);
      let dvLen = random(55, 150);
      for (let s = 0; s <= 6; s++) {
        let curV = troughV + (s / 6) * dvLen;
        let ph = (((curV + 720) / CORR_PERIOD) * 360) % 360;
        let waveShift = sin(ph) * 4;
        let pt = fromWallUV(du + waveShift + (noise(curV * 0.05, d) - 0.5) * 5, curV);
        dripPts.push([pt.x, pt.y]);
      }
      brush.set("cpencil", random(["#591f0e", "#8f3516", "#b84b1e"]), random(0.45, 0.85));
      safeSpline(dripPts, 0.4);
    }

    // Bolt cast shadow
    brush.noStroke();
    brush.wash("#090d12", 220);
    brush.circle(center.x - 3, center.y + 5, 15, 0.15);

    // Corroded washer ring
    brush.wash("#4a1b0d", 210);
    brush.circle(center.x, center.y, 14, 0.15);
    brush.noWash();

    // Hex bolt head (6 vertices)
    let hexPts = [];
    for (let h = 0; h < 6; h++) {
      let ang = h * 60 + 15;
      hexPts.push([center.x + cos(ang) * 9.5, center.y + sin(ang) * 9.5]);
    }
    brush.noStroke();
    brush.wash("#384757", 235);
    drawShapePoly(hexPts, 0, true);
    brush.noWash();

    // Top lit bevel of hex bolt
    brush.set("rotring", "#b5cadb", 0.6);
    brush.line(hexPts[3][0], hexPts[3][1], hexPts[4][0], hexPts[4][1]);
    brush.line(hexPts[4][0], hexPts[4][1], hexPts[5][0], hexPts[5][1]);

    // Rust crust on bolt head
    brush.set("cpencil", "#b5481c", 0.7);
    brush.line(hexPts[0][0], hexPts[0][1], hexPts[1][0], hexPts[1][1]);
    brush.set("rotring", "#0b0f14", 0.45);
    drawShapePoly(hexPts, 0, true);
  }
}

// =============================================================================
// 3. ACTION-PAINTING LAYER: VIOLENT MARKER SWIPES & BALLISTIC STREAKS
// =============================================================================

function drawActionMarkerBlast() {
  // Activate custom ballistic field for flowLine gestures
  brush.field("ballistic_blast");

  let flowPalette = [
    "#151e29", "#283747", "#6f8396", "#9bb0c2",
    "#cad8e6", "#d95b08", "#f58c0c", "#ffbe1a", "#9e3916"
  ];

  for (let i = 0; i < 65; i++) {
    let ang = random(360);
    let startDist = random(45, 240);
    let sx = IX + cos(ang) * startDist;
    let sy = IY + sin(ang) * startDist;
    let len = random(90, 360);
    let col = random(flowPalette);
    let br = random(["cpencil", "charcoal", "rotring", "marker"]);
    let wt = br === "marker" ? random(0.4, 0.9) : random(0.45, 1.3);
    brush.set(br, col, wt);
    brush.flowLine(sx, sy, len, ang + random(-12, 12));
  }
  brush.noField();

  // Violent Chisel-Marker & Dry-Brush Swipes radiating and whipping outward
  let swipeAngles = [
    -168, -152, -138, -122, -105, -82, -64, -45, -32, -18, -6,
    8, 22, 35, 48, 65, 82, 104, 125, 142, 158, 174,
    -145, -52, -24, 14, 41, 134, 165
  ];

  for (let i = 0; i < swipeAngles.length; i++) {
    let baseAng = swipeAngles[i] + random(-5, 5);
    let isYolkSwipe = random() < 0.34;
    let isDarkSwipe = !isYolkSwipe && random() < 0.28;

    let col;
    if (isYolkSwipe) {
      col = random(["#cc4b06", "#e87009", "#fa9a0f", "#ffc11c", "#ffe052"]);
    } else if (isDarkSwipe) {
      col = random(["#0f151d", "#1b2533", "#2b394a", "#782b12"]);
    } else {
      col = random(["#687c8f", "#899eb0", "#aec1d1", "#d2e0ec", "#eef6fc"]);
    }

    let rStart = random(35, 130);
    let rEnd = rStart + random(160, 470);
    let steps = 10;
    let swipePts = [];
    let whipCurve = random(-22, 22);

    for (let s = 0; s <= steps; s++) {
      let t = s / steps;
      let r = lerp(rStart, rEnd, t);
      let a = baseAng + sin(t * 180) * whipCurve;
      let px = IX + cos(a) * r;
      let py = IY + sin(a) * r;

      // Deform the swipe over the 3D zinc corrugations!
      let z = getWallZ(px, py);
      px += sin(WALL_TILT) * z * 8;
      py -= cos(WALL_TILT) * z * 8;

      let pressure = t < 0.2 ? map(t, 0, 0.2, 0.6, 1.3) : map(t, 0.2, 1, 1.3, 0.1);
      // Marker catches harder on the protruding ridge crests (z > 0)
      pressure *= map(z, -1, 1, 0.65, 1.25);
      swipePts.push([px, py, pressure]);
    }

    let brushType = random() < 0.6 ? "action_chisel" : (random() < 0.5 ? "dry_swipe" : "marker");
    let wt = brushType === "marker" ? random(0.6, 1.4) : random(0.55, 1.25);
    brush.set(brushType, col, wt);
    safeSpline(swipePts, 0.45);

    // High-velocity bristle split trails at the tail of each marker swipe
    let tailStart = swipePts[ max(0, swipePts.length - 4) ];
    for (let b = 0; b < 4; b++) {
      let bAng = baseAng + whipCurve * 0.5 + random(-8, 8);
      let bLen = random(40, 120);
      let bx1 = tailStart[0] + random(-8, 8);
      let by1 = tailStart[1] + random(-8, 8);
      let bx2 = bx1 + cos(bAng) * bLen;
      let by2 = by1 + sin(bAng) * bLen;
      brush.set("rotring", col, random(0.3, 0.55));
      brush.line(bx1, by1, bx2, by2);
    }
  }
}

// =============================================================================
// 4. HYPERREAL TRANSLUCENT ALBUMEN SPLASH, WEBBING & CHALAZA
// =============================================================================

function drawAlbumenSplash() {
  brush.noField();

  // Define 18 radiating viscous lobes of albumen around (IX, IY)
  let numLobes = 18;
  let lobeData = [];
  for (let i = 0; i < numLobes; i++) {
    let ang = (i / numLobes) * 360 + random(-8, 8);
    // Asymmetric explosion: longer splash toward right, upper-right, and lower-left
    let dirBoost = (ang > -65 && ang < 75) ? 1.32 : ((ang > 125 && ang < 215) ? 1.18 : 0.88);
    let reach = random(185, 340) * dirBoost;
    let valley = random(115, 165) * dirBoost;
    lobeData.push({ ang: ang, reach: reach, valley: valley });
  }

  // Build the scalloped splash contour polygon
  let splashContour = [];
  for (let i = 0; i < numLobes; i++) {
    let cur = lobeData[i];
    let next = lobeData[(i + 1) % numLobes];
    let midAng = cur.ang + (((next.ang - cur.ang + 360) % 360) * 0.5);

    // Lobe tip (bulbous liquid finger)
    for (let sub = -2; sub <= 2; sub++) {
      let a = cur.ang + sub * 3.2;
      let r = cur.reach * (1 - abs(sub) * 0.055);
      let px = IX + cos(a) * r;
      let py = IY + sin(a) * r;
      let z = getWallZ(px, py);
      splashContour.push([px, py - z * 7]);
    }

    // Concave stretched web valley between fingers
    for (let sub = -1; sub <= 1; sub++) {
      let a = midAng + sub * 4.5;
      let r = cur.valley * (1 + abs(sub) * 0.05);
      let px = IX + cos(a) * r;
      let py = IY + sin(a) * r;
      let z = getWallZ(px, py);
      splashContour.push([px, py - z * 6]);
    }
  }

  // 1. Dark wet meniscus shadow underneath the lower/outer edge of the albumen sheet
  let meniscusShadow = splashContour.map(pt => [pt[0] - 3, pt[1] + 7]);
  brush.noStroke();
  brush.wash("#0e151e", 115);
  drawShapePoly(meniscusShadow, 0.35, true);
  brush.noWash();

  // 2. Translucent opalescent egg-white glazes (layered so the zinc corrugations show through!)
  brush.fillBleed(0.18, "in");
  brush.fillTexture(0.45, 0.4);
  brush.fill("#8599ab", 65);
  drawShapePoly(splashContour, 0.35, true);

  // Inner thicker albumen ring around the yolk
  let innerAlbumen = [];
  for (let i = 0; i < 28; i++) {
    let a = (i / 28) * 360;
    let r = random(115, 165) * ((a > -50 && a < 60) ? 1.25 : 0.95);
    let px = IX + cos(a) * r;
    let py = IY + sin(a) * r;
    innerAlbumen.push([px, py]);
  }
  brush.fill("#b8cad9", 85);
  drawShapePoly(innerAlbumen, 0.4, true);

  // Warm subsurface scatter where the cadmium yolk illuminates the surrounding albumen
  let yolkGlowAlbumen = [];
  for (let i = 0; i < 20; i++) {
    let a = (i / 20) * 360;
    let r = random(95, 145);
    yolkGlowAlbumen.push([IX + cos(a) * r, IY + sin(a) * r]);
  }
  brush.fill("#f5b838", 55);
  drawShapePoly(yolkGlowAlbumen, 0.45, true);
  brush.noFill();

  // 3. Optical Refraction of the Corrugated Wall Ridges through the Clear Albumen
  for (let k = -4; k <= 4; k++) {
    let crestV = k * CORR_PERIOD - 720 + CORR_PERIOD * 0.87;
    let pTest = fromWallUV(0, crestV);
    if (dist(pTest.x, pTest.y, IX, IY) < 260) {
      let refractPts = [];
      for (let u = -220; u <= 320; u += 22) {
        let p = fromWallUV(u, crestV);
        let d = dist(p.x, p.y, IX, IY);
        if (d < 220 && d > 75) {
          // Lens distortion of the ridge line inside the convex albumen dome
          let lensShift = sin(map(d, 75, 220, 0, 180)) * 9;
          refractPts.push([p.x, p.y - lensShift]);
        }
      }
      if (refractPts.length >= 3) {
        brush.set("2H", "#e6f2fc", 0.65);
        safeSpline(refractPts, 0.5);
        brush.set("rotring", "#16212e", 0.4);
        let darkRefract = refractPts.map(pt => [pt[0], pt[1] + 10]);
        safeSpline(darkRefract, 0.5);
      }
    }
  }

  // 4. Stretched Mucin Webs, Perforated Membrane Holes & Frothy Micro-Bubbles
  for (let i = 0; i < 16; i++) {
    let a = random(360);
    let r = random(110, 210);
    let hx = IX + cos(a) * r;
    let hy = IY + sin(a) * r;
    let hr = random(6, 19);

    // Perforation hole where stretched albumen sheet tears open over the steel
    brush.noStroke();
    brush.wash("#222f3e", 145);
    brush.circle(hx, hy, hr, 0.25);
    brush.noWash();

    // Bright surface-tension rim around the hole
    brush.set("rotring", "#eef6fc", 0.45);
    brush.arc(hx, hy, hr, random(-40, 20), random(140, 220));
  }

  // Radial & tangential stretched fibrous albumen strands
  for (let i = 0; i < 55; i++) {
    let l1 = random(lobeData);
    let a = l1.ang + random(-14, 14);
    let r1 = random(85, 130);
    let r2 = min(l1.reach * 1.15, r1 + random(60, 180));
    let strandPts = [];
    for (let s = 0; s <= 5; s++) {
      let t = s / 5;
      let curR = lerp(r1, r2, t);
      let curA = a + sin(t * 180) * random(-6, 6);
      let px = IX + cos(curA) * curR;
      let py = IY + sin(curA) * curR;
      py -= getWallZ(px, py) * 5;
      strandPts.push([px, py]);
    }
    let col = random(["#d0e0ed", "#eef7ff", "#7b90a3"]);
    brush.set("rotring", col, random(0.28, 0.5));
    safeSpline(strandPts, 0.5);
  }

  // 5. Long Flung Streamers & Rayleigh-Plateau Beaded Filaments of Albumen
  for (let i = 0; i < numLobes; i++) {
    let lb = lobeData[i];
    let streamerPts = [];
    let endR = lb.reach + random(85, 240);
    let curveDir = random(-15, 15);

    for (let s = 0; s <= 7; s++) {
      let t = s / 7;
      let r = lerp(lb.reach * 0.78, endR, t);
      let a = lb.ang + t * curveDir;
      let px = IX + cos(a) * r;
      let py = IY + sin(a) * r;
      let z = getWallZ(px, py);
      py -= z * 7;
      streamerPts.push([px, py, map(t, 0, 1, 1.2, 0.2)]);
    }

    // Shadow side of streamer
    let shadowStreamer = streamerPts.map(p => [p[0] - 2, p[1] + 4, p[2]]);
    brush.set("cpencil", "#18222e", 0.75);
    safeSpline(shadowStreamer, 0.45);

    // Translucent grey-white core of streamer
    brush.set("cpencil", "#abc0d1", 0.9);
    safeSpline(streamerPts, 0.45);

    // Razor-sharp wet specular highlight along the streamer
    brush.set("rotring", "#ffffff", 0.45);
    safeSpline(streamerPts, 0.45);

    // Beaded droplets breaking off the tip
    let tip = streamerPts[streamerPts.length - 1];
    for (let b = 1; b <= 4; b++) {
      let br = endR + b * random(16, 28);
      let ba = lb.ang + curveDir + b * random(-2, 2);
      let bx = IX + cos(ba) * br;
      let by = IY + sin(ba) * br;
      drawAlbumenDroplet(bx, by, random(3.5, 8.5), ba);
    }
  }

  // 6. Rolled Liquid Meniscus Rim Highlight along the entire albumen splash contour
  for (let i = 0; i < splashContour.length; i += 2) {
    let subPts = [];
    for (let j = 0; j < 4; j++) {
      subPts.push(splashContour[(i + j) % splashContour.length]);
    }
    let midPt = subPts[1];
    let z = getWallZ(midPt[0], midPt[1]);
    // Brightest specular rim where the liquid crosses a lit zinc ridge
    let rimCol = z > 0.1 ? "#ffffff" : "#bfd2e3";
    let rimWt = z > 0.1 ? 0.65 : 0.38;
    brush.set("rotring", rimCol, rimWt);
    safeSpline(subPts, 0.5);
  }

  // 7. The Chalaza: Twisted Opaque White Spiral Ropes Anchoring the Yolk
  drawChalazaCord(IX - 72, IY - 38, -148, 165);
  drawChalazaCord(IX + 88, IY + 62, 34, 155);
}

function drawChalazaCord(startX, startY, angleDeg, length) {
  let steps = 16;
  let strandA = [];
  let strandB = [];
  let shadowStrand = [];

  for (let s = 0; s <= steps; s++) {
    let t = s / steps;
    let r = t * length;
    let a = angleDeg + sin(t * 240) * 10;
    let cx = startX + cos(a) * r;
    let cy = startY + sin(a) * r;
    let perpX = -sin(a);
    let perpY = cos(a);
    let twist = sin(t * 720) * (1 - t * 0.5) * 6.5;

    strandA.push([cx + perpX * twist, cy + perpY * twist]);
    strandB.push([cx - perpX * twist, cy - perpY * twist]);
    shadowStrand.push([cx + 2, cy + 5]);
  }

  brush.set("cpencil", "#283747", 1.1);
  safeSpline(shadowStrand, 0.5);

  brush.set("cpencil", "#9cb0c2", 1.15);
  safeSpline(strandA, 0.5);
  safeSpline(strandB, 0.5);

  brush.set("rotring", "#ffffff", 0.65);
  safeSpline(strandA, 0.5);
  brush.set("rotring", "#e6f2fa", 0.5);
  safeSpline(strandB, 0.5);
}

// =============================================================================
// 5. RUPTURING CADMIUM YOLK: MEMBRANE WRINKLES & WET GLOSS
// =============================================================================

function drawBurstingYolk() {
  brush.noField();

  // Construct the bursting yolk silhouette:
  // A compressed hemisphere on the left/bottom, tearing open into explosive liquid jets on the right/upper-right
  let yolkOutline = [];
  let numPts = 48;
  for (let i = 0; i < numPts; i++) {
    let a = (i / numPts) * 360;
    let baseR = 98;

    // Asymmetric bursting deformation
    let jet1 = pow(max(0, cos(a - (-28))), 5.0) * 145; // Primary upper-right burst jet
    let jet2 = pow(max(0, cos(a - 28)), 6.0) * 105;    // Secondary lower-right burst lobe
    let jet3 = pow(max(0, cos(a - (-132))), 7.0) * 52; // Upper-left kick
    let flatLeft = pow(max(0, cos(a - 170)), 2.5) * (-16); // Compression against the zinc wall
    let ripple = sin(a * 5) * 5 + cos(a * 8) * 3;

    let r = baseR + jet1 + jet2 + jet3 + flatLeft + ripple;
    let px = IX + cos(a) * r;
    let py = IY + sin(a) * r;
    yolkOutline.push([px, py]);
  }

  // 1. Dark amber-slate occlusion shadow beneath the yolk sac
  let yolkShadow = yolkOutline.map(p => [p[0] - 4, p[1] + 10]);
  brush.noStroke();
  brush.wash("#1a0c06", 185);
  drawShapePoly(yolkShadow, 0.4, true);
  brush.noWash();

  // 2. Deep Burnt Amber-Orange Base Underpainting
  brush.noStroke();
  brush.wash("#a83806", 240);
  drawShapePoly(yolkOutline, 0.4, true);
  brush.noWash();

  // 3. Rich Cadmium Orange & Yellow Volumetric Layering
  let midBodyPts = [];
  for (let i = 0; i < numPts; i++) {
    let a = (i / numPts) * 360;
    let p = yolkOutline[i];
    // Pull in from the dark bottom-right shadow rim
    let pull = (a > 35 && a < 175) ? 0.84 : 0.94;
    midBodyPts.push([
      lerp(IX - 12, p[0], pull),
      lerp(IY - 10, p[1], pull)
    ]);
  }
  brush.fillBleed(0.15, "in");
  brush.fillTexture(0.5, 0.35);
  brush.fill("#e86b08", 210);
  drawShapePoly(midBodyPts, 0.4, true);

  // Vibrant Cadmium Yellow Upper-Central Dome
  let brightDomePts = [];
  for (let i = 0; i < 32; i++) {
    let a = (i / 32) * 360;
    let r = 74 + pow(max(0, cos(a - (-28))), 4.0) * 78 + sin(a * 3) * 5;
    brightDomePts.push([IX - 10 + cos(a) * r, IY - 8 + sin(a) * r]);
  }
  brush.fill("#fca311", 210);
  drawShapePoly(brightDomePts, 0.45, true);

  // Luminous Subsurface Scatter Heart
  let coreGlowPts = [];
  for (let i = 0; i < 24; i++) {
    let a = (i / 24) * 360;
    let r = 48 + cos(a - (-25)) * 18;
    coreGlowPts.push([IX - 18 + cos(a) * r, IY - 16 + sin(a) * r]);
  }
  brush.fill("#ffd42e", 200);
  drawShapePoly(coreGlowPts, 0.45, true);

  brush.wash("#ffe869", 155);
  brush.circle(IX - 24, IY - 22, 34, 0.25);
  brush.noWash();
  brush.noFill();

  // 4. Sculpted 3D Shading & Liquid Flow Contours inside the Yolk
  // Deep shadow fold along the lower belly and compressed left base
  for (let s = 0; s < 32; s++) {
    let a1 = random(35, 165);
    let a2 = a1 + random(25, 55);
    let r = random(72, 98);
    let arcPts = [];
    for (let k = 0; k <= 5; k++) {
      let a = lerp(a1, a2, k / 5);
      let rr = r + pow(max(0, cos(a - 28)), 5.0) * 65;
      arcPts.push([IX + cos(a) * rr, IY + sin(a) * rr]);
    }
    brush.set("cpencil", random(["#6e1b03", "#8f2805", "#b83e06"]), random(0.65, 1.2));
    safeSpline(arcPts, 0.5);
  }

  // Explosive cadmium flow lines surging into the upper-right & lower-right rupture jets
  let jetAngles = [-28, 28, -132];
  for (let ja of jetAngles) {
    let maxReach = ja === -28 ? 235 : (ja === 28 ? 195 : 140);
    for (let f = 0; f < 18; f++) {
      let fPts = [];
      let spread = random(-12, 12);
      for (let k = 0; k <= 6; k++) {
        let t = k / 6;
        let r = lerp(35, maxReach * random(0.75, 1.08), t);
        let a = ja + spread * (1 - t * 0.45) + sin(t * 180) * 5;
        fPts.push([IX + cos(a) * r, IY + sin(a) * r]);
      }
      let c = random(["#d45207", "#f5850b", "#ffb718", "#ffe047", "#8c2505"]);
      brush.set("cpencil", c, random(0.5, 1.0));
      safeSpline(fPts, 0.45);
    }
  }

  // 5. Vitelline Membrane Tension Wrinkles (Forensic Detail!)
  // Nested curved double-lines (dark amber furrow + bright cream-white highlight ridge)
  // caused by the collapsing and stretching yolk sac membrane
  for (let w = 0; w < 52; w++) {
    let isJetWrinkle = w < 22;
    let wrinklePts = [];
    let highlightPts = [];

    if (isJetWrinkle) {
      // Longitudinal stretch wrinkles funneling into the rupture necks
      let baseA = (w % 2 === 0 ? -28 : 28) + random(-16, 16);
      let rStart = random(45, 95);
      let rEnd = rStart + random(45, 95);
      for (let k = 0; k <= 5; k++) {
        let t = k / 5;
        let r = lerp(rStart, rEnd, t);
        let a = baseA + sin(t * 180) * random(-7, 7);
        let wx = IX + cos(a) * r;
        let wy = IY + sin(a) * r;
        wrinklePts.push([wx, wy]);
        highlightPts.push([wx - 1.2, wy - 1.5]);
      }
    } else {
      // Concentric compression ripples across the intact dome of the yolk
      let centerA = random(-175, 155);
      let spanA = random(22, 48);
      let rBase = random(32, 92);
      for (let k = 0; k <= 5; k++) {
        let t = k / 5;
        let a = centerA + (t - 0.5) * spanA;
        let r = rBase + sin(t * 180) * random(-6, 6);
        let wx = IX + cos(a) * r;
        let wy = IY + sin(a) * r;
        wrinklePts.push([wx, wy]);
        highlightPts.push([wx - 1.2, wy - 1.4]);
      }
    }

    // Dark amber membrane crease
    brush.set("rotring", random(["#7d2104", "#a33206", "#c44908"]), random(0.28, 0.42));
    safeSpline(wrinklePts, 0.5);

    // Adjacent razor-sharp membrane tension highlight
    let hCol = random() < 0.45 ? "#ffffff" : (random() < 0.6 ? "#fff2a8" : "#ffd659");
    brush.set("rotring", hCol, random(0.28, 0.45));
    safeSpline(highlightPts, 0.5);
  }

  // 6. Wet Specular Gloss Reflections on the Yolk Dome & Bursting Jets
  // Primary curved window reflection across the upper-left convex dome
  let glossArc1 = [];
  for (let a = -155; a <= -75; a += 10) {
    let r = 68 + sin((a + 115) * 3) * 3;
    glossArc1.push([IX - 8 + cos(a) * r, IY - 6 + sin(a) * r]);
  }
  let glossArc2 = [];
  for (let a = -75; a >= -155; a -= 10) {
    let r = 54 + cos((a + 115) * 3) * 3;
    glossArc2.push([IX - 8 + cos(a) * r, IY - 6 + sin(a) * r]);
  }
  let mainGlossPoly = glossArc1.concat(glossArc2);

  brush.noStroke();
  brush.wash("#fff9d2", 185);
  drawShapePoly(mainGlossPoly, 0.35, true);
  brush.noWash();

  // Corrugated horizon bars cutting through the wet gloss reflection for hyperrealism!
  brush.set("rotring", "#f5900d", 0.55);
  brush.line(IX - 72, IY - 52, IX - 22, IY - 56);
  brush.line(IX - 64, IY - 38, IX - 18, IY - 41);

  // Pin-sharp pure white wet gloss edge & secondary specular ribbons on the jets
  brush.set("rotring", "#ffffff", 0.85);
  safeSpline(glossArc1, 0.5);

  // Specular ribbon along the upper-right bursting yolk jet
  let jetGloss1 = [
    [IX + 42, IY - 32],
    [IX + 95, IY - 58],
    [IX + 155, IY - 82],
    [IX + 205, IY - 102]
  ];
  brush.set("cpencil", "#fff4b8", 1.1);
  safeSpline(jetGloss1, 0.45);
  brush.set("rotring", "#ffffff", 0.7);
  safeSpline(jetGloss1, 0.45);

  // Specular ribbon along the lower-right yolk lobe
  let jetGloss2 = [
    [IX + 48, IY + 18],
    [IX + 92, IY + 42],
    [IX + 142, IY + 68]
  ];
  brush.set("rotring", "#ffffff", 0.65);
  safeSpline(jetGloss2, 0.45);

  // Crisp outer contour definition of the yolk sac
  brush.set("rotring", "#591502", 0.45);
  safeSpline(yolkOutline.slice(4, 26), 0.45);
}

// =============================================================================
// 6. FORENSIC SHATTERED EGGSHELL SHARDS
// =============================================================================

function drawEggshellShards() {
  brush.noField();

  // Shard definitions:
  // Group A: Crushed impact rosette clinging around the bursting yolk core
  // Group B: Mid-air ballistic shards hurtling outward in the explosion
  let shards = [
    // Impact crown shards on/around the yolk
    { x: IX - 78, y: IY - 18, r: 44, ang: -165, flip: false, yolkGlaze: true, membrane: true },
    { x: IX - 55, y: IY + 42, r: 48, ang: 145, flip: false, yolkGlaze: true, membrane: true },
    { x: IX - 18, y: IY + 76, r: 38, ang: 108, flip: false, yolkGlaze: true, membrane: true },
    { x: IX - 98, y: IY + 15, r: 34, ang: 178, flip: true, yolkGlaze: false, membrane: true },
