    // Mid-range flying shards (explosive ring r = 150..360)
    { x: IX - 185, y: IY - 115, r: 42, ang: -148, flip: false, yolkGlaze: false, membrane: true },
    { x: IX - 245, y: IY - 28, r: 36, ang: -172, flip: true, yolkGlaze: false, membrane: false },
    { x: IX - 195, y: IY + 125, r: 45, ang: 142, flip: false, yolkGlaze: true, membrane: true },
    { x: IX - 88, y: IY + 215, r: 34, ang: 112, flip: true, yolkGlaze: false, membrane: false },
    { x: IX + 48, y: IY + 235, r: 39, ang: 78, flip: false, yolkGlaze: false, membrane: true },
    { x: IX + 215, y: IY + 148, r: 44, ang: 34, flip: false, yolkGlaze: true, membrane: true },
    { x: IX + 275, y: IY + 32, r: 38, ang: 8, flip: true, yolkGlaze: true, membrane: false },
    { x: IX + 245, y: IY - 125, r: 48, ang: -28, flip: false, yolkGlaze: true, membrane: true },
    { x: IX + 145, y: IY - 215, r: 35, ang: -56, flip: true, yolkGlaze: false, membrane: false },
    { x: IX - 45, y: IY - 228, r: 40, ang: -98, flip: false, yolkGlaze: false, membrane: true },

    // Outer ballistic shards (r = 350..510)
    { x: IX - 365, y: IY - 225, r: 28, ang: -145, flip: false, yolkGlaze: false, membrane: false },
    { x: IX - 395, y: IY + 95, r: 31, ang: 165, flip: true, yolkGlaze: false, membrane: true },
    { x: IX - 235, y: IY + 335, r: 26, ang: 125, flip: false, yolkGlaze: false, membrane: false },
    { x: IX + 195, y: IY + 345, r: 29, ang: 58, flip: true, yolkGlaze: false, membrane: false },
    { x: IX + 385, y: IY + 185, r: 33, ang: 26, flip: false, yolkGlaze: true, membrane: false },
    { x: IX + 410, y: IY - 75, r: 30, ang: -12, flip: false, yolkGlaze: true, membrane: true },
    { x: IX + 335, y: IY - 265, r: 27, ang: -38, flip: true, yolkGlaze: false, membrane: false },
    { x: IX - 165, y: IY - 340, r: 25, ang: -115, flip: false, yolkGlaze: false, membrane: false }
  ];

  // Draw stretchy torn inner-membrane tethers between adjacent impact-crown shards
  for (let i = 0; i < 6; i++) {
    let s1 = shards[i];
    let s2 = shards[i + 1];
    if (dist(s1.x, s1.y, s2.x, s2.y) < 110) {
      let tetherPoly = [
        [s1.x + random(-10, 10), s1.y + random(-10, 10)],
        [s2.x + random(-10, 10), s2.y + random(-10, 10)],
        [s2.x + random(-4, 14), s2.y + random(4, 16)],
        [s1.x + random(-4, 14), s1.y + random(4, 16)]
      ];
      brush.noStroke();
      brush.wash("#e3dde6", 165);
      drawShapePoly(tetherPoly, 0.25, true);
      brush.noWash();
      brush.set("rotring", "#ffffff", 0.4);
      brush.line(tetherPoly[0][0], tetherPoly[0][1], tetherPoly[1][0], tetherPoly[1][1]);
    }
  }

  // Render each major shard with forensic detail
  for (let sh of shards) {
    drawForensicShard(sh);
  }

  // Render 42 tiny razor-sharp calcified shell splinters flying outward
  for (let i = 0; i < 42; i++) {
    let a = random(360);
    let d = random(110, 530);
    let sx = IX + cos(a) * d;
    let sy = IY + sin(a) * d;
    let sr = random(5, 15);

    let pts = [];
    let vCount = floor(random(3, 5));
    for (let v = 0; v < vCount; v++) {
      let va = a + (v / vCount) * 360 + random(-25, 25);
      let vr = sr * random(0.55, 1.25);
      pts.push([sx + cos(va) * vr, sy + sin(va) * vr]);
    }

    // Shadow
    let shPts = pts.map(p => [p[0] - 2, p[1] + 4]);
    brush.noStroke();
    brush.wash("#10161e", 175);
    drawShapePoly(shPts, 0, true);

    // Body
    let col = random(["#e8dfd5", "#f5efe8", "#cfc3b6", "#9aa6b2"]);
    brush.wash(col, 235);
    drawShapePoly(pts, 0, true);
    brush.noWash();

    // Crisp edge highlight & dark fracture rim
    brush.set("rotring", "#ffffff", 0.45);
    brush.line(pts[0][0], pts[0][1], pts[1][0], pts[1][1]);
    brush.set("rotring", "#241d20", 0.35);
    brush.line(pts[1][0], pts[1][1], pts[2][0], pts[2][1]);
  }
}

function drawForensicShard(sh) {
  let numV = floor(random(5, 8));
  let poly = [];
  for (let i = 0; i < numV; i++) {
    let baseA = sh.ang + (i / numV) * 360 + random(-18, 18);
    // Elongate shards slightly along fracture axes
    let stretch = (i % 2 === 0) ? random(0.85, 1.32) : random(0.55, 0.95);
    let rad = sh.r * stretch;
    poly.push([sh.x + cos(baseA) * rad, sh.y + sin(baseA) * rad]);
  }

  // 1. Cast Shadow beneath the shard
  let shadowOffset = map(dist(sh.x, sh.y, IX, IY), 0, 500, 5, 14);
  let shadowPoly = poly.map(p => [p[0] - shadowOffset * 0.45, p[1] + shadowOffset]);
  brush.noStroke();
  brush.wash("#0d121a", 185);
  drawShapePoly(shadowPoly, 0, true);
  brush.noWash();

  // 2. Peeling, curling papery inner membrane (chorion) protruding from one edge
  if (sh.membrane) {
    let m1 = poly[0];
    let m2 = poly[1];
    let midX = (m1[0] + m2[0]) * 0.5;
    let midY = (m1[1] + m2[1]) * 0.5;
    let outA = atan2(midY - sh.y, midX - sh.x);
    let curlFlap = [
      m1,
      [m1[0] + cos(outA - 20) * 14, m1[1] + sin(outA - 20) * 14],
      [midX + cos(outA) * 18, midY + sin(outA) * 18],
      [m2[0] + cos(outA + 20) * 12, m2[1] + sin(outA + 20) * 12],
      m2
    ];
    brush.noStroke();
    brush.wash("#dcd6e2", 185);
    drawShapePoly(curlFlap, 0.3, true);
    brush.noWash();
    brush.set("rotring", "#f7f5fa", 0.4);
    safeSpline(curlFlap.slice(0, 4), 0.5);
  }

  // 3. Main Calcified Shell Face (Warm Bone Cream exterior vs. Cool Blue-Grey concave interior)
  let baseCol, shadowCol, litCol;
  if (!sh.flip) {
    // Exterior shell surface: warm dusky bone cream with subtle twilight lilac shadow
    baseCol = random(["#e3d8cd", "#ece3d9", "#d6c8ba"]);
    shadowCol = "#8a7d80";
    litCol = "#faf5f0";
  } else {
    // Interior concave shell surface: glossy opalescent porcelain blue-grey
    baseCol = random(["#95a3b3", "#a8b6c4", "#7e8c9c"]);
    shadowCol = "#4f5c6b";
    litCol = "#dce6f0";
  }

  brush.noStroke();
  brush.wash(baseCol, 245);
  drawShapePoly(poly, 0, true);

  // Half-facet curvature shading across the shard
  let halfPoly = [poly[0], poly[1], poly[2], [sh.x, sh.y]];
  brush.wash(shadowCol, 95);
  drawShapePoly(halfPoly, 0, true);

  let litFacet = [poly[3 % numV], poly[4 % numV], [sh.x, sh.y]];
  brush.wash(litCol, 125);
  drawShapePoly(litFacet, 0, true);
  brush.noWash();

  // Fine cross-contour hatching & calcified pore stippling on the shell face
  for (let h = 0; h < 6; h++) {
    let t = (h + 1) / 7;
    let hx1 = lerp(poly[0][0], poly[2][0], t);
    let hy1 = lerp(poly[0][1], poly[2][1], t);
    let hx2 = lerp(poly[numV - 1][0], poly[3 % numV][0], t);
    let hy2 = lerp(poly[numV - 1][1], poly[3 % numV][1], t);
    brush.set("2H", shadowCol, 0.32);
    brush.line(hx1, hy1, hx2, hy2);
  }

  // 4. 3D Calcified Shell Edge Thickness (Chalk-white bevel vs. dark fracture line)
  for (let i = 0; i < numV; i++) {
    let p1 = poly[i];
    let p2 = poly[(i + 1) % numV];
    let edgeAng = atan2(p2[1] - p1[1], p2[0] - p1[0]);

    // Upper/left-facing edges catch pure white thickness bevel
    if (sin(edgeAng - 45) < 0.2) {
      let thickBevel = [
        p1,
        p2,
        [p2[0] - 2.8, p2[1] - 2.8],
        [p1[0] - 2.8, p1[1] - 2.8]
      ];
      brush.noStroke();
      brush.wash("#ffffff", 235);
      drawShapePoly(thickBevel, 0, true);
      brush.noWash();

      brush.set("rotring", "#ffffff", 0.65);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
      brush.set("rotring", "#33292c", 0.38);
      brush.line(p1[0] - 2.8, p1[1] - 2.8, p2[0] - 2.8, p2[1] - 2.8);
    } else {
      // Shadowed fracture edge
      brush.set("rotring", "#241c1f", 0.52);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }
  }

  // 5. Crisp Forensic Cracks along each Shard Edge & Interior Branching Fractures
  let numCracks = floor(random(2, 4));
  for (let c = 0; c < numCracks; c++) {
    let vIdx = floor(random(numV));
    let nextIdx = (vIdx + 1) % numV;
    // Start crack on a shard edge
    let startT = random(0.25, 0.75);
    let cx = lerp(poly[vIdx][0], poly[nextIdx][0], startT);
    let cy = lerp(poly[vIdx][1], poly[nextIdx][1], startT);

    let crackPts = [[cx, cy]];
    let inAng = atan2(sh.y - cy, sh.x - cx) + random(-25, 25);
    let segLen = sh.r * random(0.22, 0.35);

    for (let s = 1; s <= 4; s++) {
      inAng += (s % 2 === 0 ? 1 : -1) * random(14, 32);
      cx += cos(inAng) * segLen;
      cy += sin(inAng) * segLen;
      crackPts.push([cx, cy]);

      // Secondary micro-branch off the main crack
      if (s === 2) {
        let bAng = inAng + random(35, 65) * (random() < 0.5 ? 1 : -1);
        let bx = cx + cos(bAng) * (segLen * 0.85);
        let by = cy + sin(bAng) * (segLen * 0.85);
        brush.set("rotring", "#ffffff", 0.32);
        brush.line(cx + 1, cy - 1, bx + 1, by - 1);
        brush.set("rotring", "#1a1316", 0.32);
        brush.line(cx, cy, bx, by);
      }
    }

    // Stress-whitening highlight immediately beside the dark crack
    for (let k = 0; k < crackPts.length - 1; k++) {
      brush.set("rotring", "#ffffff", 0.42);
      brush.line(
        crackPts[k][0] + 1.2, crackPts[k][1] - 1.2,
        crackPts[k + 1][0] + 1.2, crackPts[k + 1][1] - 1.2
      );
      brush.set("rotring", "#1a1215", 0.45);
      brush.line(
        crackPts[k][0], crackPts[k][1],
        crackPts[k + 1][0], crackPts[k + 1][1]
      );
    }
  }

  // 6. Wet Glossy Yolk or Albumen Glaze Clinging to the Shard
  if (sh.yolkGlaze) {
    let gIdx = floor(random(numV));
    let gp = poly[gIdx];
    let glazePts = [
      gp,
      [lerp(gp[0], sh.x, 0.55) + random(-6, 6), lerp(gp[1], sh.y, 0.55) + random(-6, 6)],
      poly[(gIdx + 1) % numV]
    ];
    brush.noStroke();
    brush.wash(random(["#e87009", "#fca311", "#ffb81c"]), 195);
    drawShapePoly(glazePts, 0.3, true);
    brush.noWash();

    // Wet specular highlight on the yolk glaze
    brush.set("rotring", "#ffffff", 0.55);
    brush.line(
      lerp(glazePts[0][0], glazePts[1][0], 0.3),
      lerp(glazePts[0][1], glazePts[1][1], 0.3),
      lerp(glazePts[1][0], glazePts[2][0], 0.6),
      lerp(glazePts[1][1], glazePts[2][1], 0.6)
    );
  }
}

