function drawForegroundSprayAndDroplets() {
  brush.noField();

  // 1. Overlapping Foreground Action-Painting Whiplash Streaks (tying core & background together)
  let fgStreaks = [
    { a: -32, r1: 85, r2: 460, col: "#ffbe1a", wt: 0.85 },
    { a: -18, r1: 110, r2: 520, col: "#e87009", wt: 0.75 },
    { a: 24, r1: 95, r2: 440, col: "#fca311", wt: 0.8 },
    { a: 148, r1: 105, r2: 480, col: "#d0e0ed", wt: 0.75 },
    { a: -142, r1: 90, r2: 450, col: "#eef7ff", wt: 0.65 },
    { a: -68, r1: 115, r2: 420, col: "#96acc0", wt: 0.7 },
    { a: 62, r1: 120, r2: 430, col: "#151e29", wt: 0.75 },
    { a: -162, r1: 130, r2: 510, col: "#c4511f", wt: 0.65 }
  ];

  for (let st of fgStreaks) {
    let pts = [];
    let curve = random(-16, 16);
    for (let s = 0; s <= 7; s++) {
      let t = s / 7;
      let r = lerp(st.r1, st.r2, t);
      let a = st.a + sin(t * 180) * curve;
      let px = IX + cos(a) * r;
      let py = IY + sin(a) * r;
      py -= getWallZ(px, py) * 6;
      pts.push([px, py, map(t, 0, 1, 1.1, 0.1)]);
    }
    brush.set("dry_swipe", st.col, st.wt);
    safeSpline(pts, 0.45);
  }

  // 2. Airborne 3D Translucent Albumen Droplets (75 droplets)
  for (let i = 0; i < 75; i++) {
    let a = random(360);
    let d = random(115, 560);
    let dx = IX + cos(a) * d;
    let dy = IY + sin(a) * d;
    let dr = map(d, 115, 560, random(5, 13), random(2.5, 7));
    drawAlbumenDroplet(dx, dy, dr, a);
  }

  // 3. Airborne 3D Cadmium Yolk Droplets & High-Speed Teardrops (65 droplets)
  for (let i = 0; i < 65; i++) {
    // Concentrated more heavily in the right/upper-right/lower-right blast cones
    let a = random() < 0.65 ? random(-65, 65) : random(360);
    let d = random(95, 540);
    let dx = IX + cos(a) * d;
    let dy = IY + sin(a) * d;
    let dr = map(d, 95, 540, random(4.5, 12.5), random(2, 6.5));
    drawYolkDroplet(dx, dy, dr, a);
  }

  // 4. Fine Atomized Mist & Ballistic Needle Spatter
  for (let i = 0; i < 160; i++) {
    let a = random(360);
    let d = random(80, 580);
    let mx = IX + cos(a) * d;
    let my = IY + sin(a) * d;

    if (random() < 0.5) {
      // High-speed needle streak
      let len = random(8, 32);
      let c = random(["#ffffff", "#d8e6f2", "#ffbe1a", "#f2850b", "#141d28"]);
      brush.set("rotring", c, random(0.28, 0.5));
      brush.line(mx, my, mx + cos(a) * len, my + sin(a) * len);
    } else {
      // Atomized spray mist cluster
      let c = random(["#dce8f2", "#9bb0c4", "#ffd230", "#f0800c"]);
      brush.set("spray", c, random(0.35, 0.85));
      brush.line(mx, my, mx + cos(a) * 10, my + sin(a) * 10);
    }
  }
}

function drawAlbumenDroplet(x, y, r, angleDeg) {
  // Elongated teardrop polygon aligned with radial trajectory
  let pts = [];
  for (let i = 0; i < 8; i++) {
    let a = (i / 8) * 360;
    let stretch = cos(a) < 0 ? 1.55 : 0.95; // Tail points back toward impact center
    let lx = cos(a) * r * stretch;
    let ly = sin(a) * r * 0.78;
    let rx = x + lx * cos(angleDeg) - ly * sin(angleDeg);
    let ry = y + lx * sin(angleDeg) + ly * cos(angleDeg);
    pts.push([rx, ry]);
  }

  // Dark refracted shadow rim
  brush.noStroke();
  brush.wash("#141e29", 145);
  let shPts = pts.map(p => [p[0] - 1.5, p[1] + 2.5]);
  drawShapePoly(shPts, 0.35, true);

  // Translucent egg-white body
  brush.wash("#9eb3c4", 110);
  drawShapePoly(pts, 0.35, true);

  // Refracted caustic glow on lower-right interior
  brush.wash("#dcebf7", 160);
  brush.circle(x + 1, y + 1, r * 0.55, 0.2);
  brush.noWash();

  // Crisp pure white specular highlight dot on upper-left
  brush.set("rotring", "#ffffff", 0.65);
  brush.line(x - r * 0.35, y - r * 0.35, x + cos(angleDeg) * r * 0.35, y - r * 0.25);
}

function drawYolkDroplet(x, y, r, angleDeg) {
  let pts = [];
  for (let i = 0; i < 8; i++) {
    let a = (i / 8) * 360;
    let stretch = cos(a) < 0 ? 1.65 : 0.92;
    let lx = cos(a) * r * stretch;
    let ly = sin(a) * r * 0.82;
    let rx = x + lx * cos(angleDeg) - ly * sin(angleDeg);
    let ry = y + lx * sin(angleDeg) + ly * cos(angleDeg);
    pts.push([rx, ry]);
  }

  // Drop shadow
  brush.noStroke();
  brush.wash("#170d08", 165);
  let shPts = pts.map(p => [p[0] - 1.5, p[1] + 3]);
  drawShapePoly(shPts, 0.35, true);

  // Deep orange base
  brush.wash("#d45307", 230);
  drawShapePoly(pts, 0.35, true);

  // Bright cadmium yellow core
  brush.wash("#ffbe1a", 215);
  brush.circle(x, y, r * 0.68, 0.2);
  brush.noWash();

  // Wet gloss white pin-prick highlight
  brush.set("rotring", "#ffffff", 0.65);
  brush.line(x - r * 0.3, y - r * 0.3, x - r * 0.05, y - r * 0.35);
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(8472);
  noiseSeed(8472);

  // Custom brushes tailored for dry-marker scumbling, flat chisel marker, aggregate grit, and precision ink
  brush.add("dry_scumble", {
    type: "default",
    weight: 12,
    scatter: 2.2,
    sharpness: 0.65,
    grain: 42,
    opacity: 65,
    spacing: 0.55,
    pressure: [0.3, 1.1, 0.2],
    rotate: "random",
    noise: 0.9
  });

  brush.add("chisel_marker", {
    type: "custom",
    weight: 9,
    scatter: 0.04,
    opacity: 210,
    spacing: 0.18,
    pressure: [0.95, 1.0, 0.95],
    tip: (_m) => {
      _m.rotate(-18);
      _m.rect(-3.5, -1.1, 7, 2.2);
    },
    rotate: "none",
    markerTip: false,
    noise: 0.08
  });

  brush.add("flat_broad", {
    type: "custom",
    weight: 16,
    scatter: 0.08,
    opacity: 175,
    spacing: 0.22,
    pressure: [0.9, 1.0, 0.9],
    tip: (_m) => {
      _m.rotate(-12);
      _m.rect(-4, -1.5, 8, 3);
    },
    rotate: "none",
    markerTip: false,
    noise: 0.12
  });

  brush.add("aggregate_stipple", {
    type: "spray",
    weight: 5,
    scatter: 5.5,
    opacity: 195,
    spacing: 0.75,
    pressure: [1.0, 1.0],
    rotate: "random"
  });

  brush.add("micro_glare", {
    type: "default",
    weight: 1.4,
    scatter: 0.02,
    sharpness: 0.98,
    grain: 2,
    opacity: 255,
    spacing: 0.12,
    pressure: [0.9, 1.1, 0.8],
    rotate: "natural",
    noise: 0.1
  });

  // Heat shimmer vector field for the upper sun-baked asphalt
  brush.addField("heat_shimmer", (t, field) => {
    for (let col = 0; col < field.length; col++) {
      for (let row = 0; row < field[0].length; row++) {
        let nx = col * 0.14;
        let ny = row * 0.28;
        let wave = Math.sin(col * 0.45 + row * 0.2) * 5.5;
        let n = (noise(nx, ny, t) - 0.5) * 14;
        field[col][row] = wave + n;
      }
    }
    return field;
  });
}

