// GEOMETRY HELPERS FOR THE WATERMELON WEDGE (LOWER THIRD)
// ============================================================================

function getBottomRindCurve(t) {
  let x = lerp(245, 965, t);
  let arch = Math.sin(t * Math.PI);
  let asym = Math.sin(t * Math.PI * 2) * -14 + Math.sin(t * Math.PI * 3) * 8;
  let y = lerp(792, 804, t) + 182 * Math.pow(arch, 0.92) + asym;
  return { x, y };
}

function getRindTopCurve(t) {
  let b = getBottomRindCurve(t);
  let arch = Math.sin(t * Math.PI);
  let thickness = 12 + 38 * Math.pow(arch, 0.82);
  let x = lerp(256, 954, t);
  let y = b.y - thickness;
  return { x, y };
}

function getPithTopCurve(t) {
  let r = getRindTopCurve(t);
  let arch = Math.sin(t * Math.PI);
  let thickness = 7 + 21 * Math.pow(arch, 0.88);
  let x = lerp(266, 944, t);
  let y = r.y - thickness;
  return { x, y };
}

const TOP_PROFILE_PTS = [
