  { t: 0.16, x: 374, y: 698 },
  { t: 0.20, x: 398, y: 666 }, // Left lip of impact split
  { t: 0.23, x: 418, y: 712 }, // Deep impact cleft notch
  { t: 0.26, x: 434, y: 648 }, // Right lip of impact split
  { t: 0.35, x: 492, y: 594 },
  { t: 0.45, x: 554, y: 546 }, // Main noon-bleached apex peak
  { t: 0.52, x: 604, y: 552 }, // Upper bevel corner
  { t: 0.68, x: 718, y: 632 },
  { t: 0.84, x: 834, y: 708 },
  { t: 1.00, x: 944, y: 775 }
];

function getFleshTopProfile(t) {
  t = constrain(t, 0, 1);
  for (let i = 0; i < TOP_PROFILE_PTS.length - 1; i++) {
    let p0 = TOP_PROFILE_PTS[i];
    let p1 = TOP_PROFILE_PTS[i + 1];
    if (t >= p0.t && t <= p1.t) {
      let localT = (t - p0.t) / (p1.t - p0.t);
      return {
        x: lerp(p0.x, p1.x, localT),
        y: lerp(p0.y, p1.y, localT)
      };
    }
  }
  return TOP_PROFILE_PTS[TOP_PROFILE_PTS.length - 1];
}

// Maps normalized (u, v) on the red flesh: u in [0,1] along length, v in [0,1] from pith to top ridge
function mapFleshUV(u, v) {
  let bottom = getPithTopCurve(u);
  let top = getFleshTopProfile(u);
  return {
    x: lerp(bottom.x, top.x, v),
    y: lerp(bottom.y, top.y, v)
  };
}

// ============================================================================
// MAIN DRAW LOOP
// ============================================================================

function draw() {
  translate(-width / 2, -height / 2);
  background("#292a2d");

  // Always ensure a brush is active before any stroke operation
  brush.set("HB", "#1a1b1d", 1);

  // 1. Monochrome gritty charcoal asphalt with dry-marker scumbling & heat shimmer
  drawAsphaltGround();

  // 2. Network of sun-baked asphalt cracks & tar repairs
  drawAsphaltCracks();

  // 3. Wet syrup/water soak on asphalt & tight pitch-black sliver shadow directly underneath
  drawWetSoakAndNoonShadow();

  // 4. Dropped watermelon wedge (acid green rind, bleached pith, flat marker reds, white glare, black seeds)
  drawWatermelonRindAndPith();
  drawWatermelonFlesh();
  drawImpactFractureAndGlare();
  drawWatermelonSeeds();

  // 5. Broken-off impact chunks, loose seeds, and stark noon-lit juice beads on the asphalt
  drawBrokenChunksAndSplatter();

  noLoop();
}

// ============================================================================
// 1. ASPHALT GROUND (DRY-MARKER SCUMBLING, HEAT SHIMMER & STIPPLED AGGREGATE)
// ============================================================================

function drawAsphaltGround() {
  // Broad tonal zones of sun-bleached charcoal asphalt (foreshortened low-angle planes)
  let strataColors = ["#212225", "#2d2f33", "#383a3f", "#242529", "#313338", "#1d1e21"];
  for (let i = 0; i < 48; i++) {
    let y = map(i, 0, 47, -20, 1220);
    let h = map(y, 0, 1200, 18, 55) * random(0.7, 1.35);
    let col = random(strataColors);
    let x1 = random(-60, 200);
    let x2 = random(1000, 1260);
    let poly = new brush.Polygon([
      [x1, y],
      [x2, y + random(-8, 8)],
      [x2, y + h],
      [x1, y + h + random(-8, 8)]
    ]);
    poly.wash(col, random(35, 75));
  }

  // Dry-marker scumbling across the asphalt (perspective-scaled from horizon to foreground)
  let scumblePalette = ["#16171a", "#1f2024", "#2c2e33", "#3e4046", "#50535a", "#676b73"];
  for (let pass = 0; pass < scumblePalette.length; pass++) {
    let col = scumblePalette[pass];
    for (let i = 0; i < 95; i++) {
      let y = Math.pow(random(), 0.85) * 1220 - 10;
      let persp = map(y, 0, 1200, 0.35, 1.55);
      let x = random(-50, 1250);
      let len = random(70, 260) * persp;
      let ang = random(-4, 4);

      brush.set("dry_scumble", col, random(0.6, 1.4) * persp);
      brush.line(x, y, x + len * cos(ang), y + len * sin(ang));
    }
  }

  // Flat marker horizontal dragging for stark, gritty pavement texture
  let markerGrays = ["#18191c", "#25262a", "#3a3c42", "#4c4f56", "#737780"];
  for (let i = 0; i < 220; i++) {
    let y = random(0, 1200);
    let persp = map(y, 0, 1200, 0.3, 1.3);
    let x = random(-40, 1200);
    let len = random(30, 160) * persp;
    let col = random(markerGrays);
    brush.set(random() < 0.5 ? "chisel_marker" : "marker", col, random(0.4, 1.1) * persp);
    brush.line(x, y, x + len, y + random(-2, 2));
  }

  // Faint heat shimmer in the upper third (y < 430) where brutal noon sun warps the air
  brush.field("heat_shimmer");
  let shimmerCols = ["#484b52", "#636770", "#858994", "#aeb3bd", "#d4d8e0", "#222327"];
  for (let i = 0; i < 190; i++) {
    let y = random(0, 440);
    let x = random(-40, 1240);
    let fade = map(y, 0, 440, 1.0, 0.25);
    let col = shimmerCols[floor(random(shimmerCols.length))];
    let w = random(0.35, 1.05) * fade;
    brush.set(random() < 0.65 ? "dry_scumble" : "charcoal", col, w);
    brush.flowLine(x, y, random(60, 190), random() < 0.5 ? 0 : 180);
  }
  // Extra sun-bleached mirage streaks near the top edge
  for (let i = 0; i < 65; i++) {
    let y = random(0, 260);
    let x = random(-20, 1220);
    brush.set("chisel_marker", random() < 0.5 ? "#9ca0aa" : "#c7cbd4", random(0.25, 0.6));
    brush.flowLine(x, y, random(45, 130), 0);
  }
  brush.noField();

  // Stippled aggregate: multi-pass stone grit, bitumen specks, and sun-glinting quartz flecks
  let gritLayers = [
    { col: "#0d0e10", count: 280, wMin: 0.5, wMax: 1.4 }, // Deep bitumen pits
    { col: "#1a1b1f", count: 320, wMin: 0.6, wMax: 1.5 }, // Dark charcoal aggregate
    { col: "#45484f", count: 340, wMin: 0.5, wMax: 1.3 }, // Mid-gray crushed stone
    { col: "#7a7e87", count: 300, wMin: 0.4, wMax: 1.2 }, // Sunlit gray gravel
    { col: "#b5b9c2", count: 240, wMin: 0.3, wMax: 0.9 }, // Bleached limestone grit
    { col: "#e6e9f0", count: 160, wMin: 0.25, wMax: 0.7 }  // Glare-white silica glints
  ];

  for (let layer of gritLayers) {
    for (let i = 0; i < layer.count; i++) {
      let y = random(0, 1200);
      let persp = map(y, 0, 1200, 0.35, 1.45);
      let x = random(0, 1200);
      let w = random(layer.wMin, layer.wMax) * persp;
      if (random() < 0.45) {
        brush.set("aggregate_stipple", layer.col, w);
        brush.line(x, y, x + random(4, 18) * persp, y + random(-2, 2));
      } else {
        brush.set("cpencil", layer.col, w * 0.9);
        let dx = random(2, 7) * persp;
        let dy = random(-1.5, 1.5) * persp;
        brush.line(x, y, x + dx, y + dy);
      }
    }
  }

  // Coarser angular aggregate pebbles embedded in the foreground & mid-ground asphalt
  let pebblePalette = ["#121316", "#202226", "#585b63", "#8d9199", "#cfd3dc", "#f2f4f7"];
  for (let i = 0; i < 420; i++) {
    let y = map(Math.pow(random(), 0.7), 0, 1, 120, 1195);
    let persp = map(y, 120, 1200, 0.35, 1.35);
    let x = random(10, 1190);
    let col = random(pebblePalette);
    brush.set("chisel_marker", col, random(0.2, 0.55) * persp);
    let len = random(1.5, 5.5) * persp;
    brush.line(x, y, x + len, y + random(-1, 1));
  }
}

// ============================================================================
// 2. CRACKED CHARCOAL ASPHALT (TAR SNAKES, FRACTURES & SUN-BLEACHED LIPS)
// ============================================================================

function generateCrackPath(x1, y1, x2, y2, steps, roughness) {
  let pts = [];
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let bx = lerp(x1, x2, t);
    let by = lerp(y1, y2, t);
    let env = Math.sin(t * Math.PI);
    let n1 = (noise(bx * 0.008, by * 0.008, 10) - 0.5) * roughness * env;
    let n2 = (noise(bx * 0.035, by * 0.035, 25) - 0.5) * (roughness * 0.35);
    // Add sharp angular jogs typical of brittle asphalt
    let jagX = (random() - 0.5) * 6;
    let jagY = (random() - 0.5) * 8;
    pts.push({
      x: bx + n1 * 0.4 + jagX,
      y: by + n1 + n2 + jagY
    });
  }
  return pts;
}

function renderCrack(pts, baseWeight, hasTarHalo) {
  // 1. Optional dark bitumen/tar sealant overband or crumbled depression
  if (hasTarHalo) {
    for (let i = 0; i < pts.length - 1; i++) {
      let p0 = pts[i];
      let p1 = pts[i + 1];
      brush.set("dry_scumble", "#151619", baseWeight * random(1.1, 1.9));
      brush.line(p0.x, p0.y, p1.x, p1.y);
      if (random() < 0.6) {
        brush.set("chisel_marker", "#191a1e", baseWeight * random(0.7, 1.2));
        brush.line(p0.x + random(-3, 3), p0.y + random(-2, 2), p1.x + random(-3, 3), p1.y + random(-2, 2));
      }
    }
  }

  // 2. Sun-bleached upper/lower broken lip catching the brutal overhead noon light
  for (let i = 0; i < pts.length - 1; i++) {
    let p0 = pts[i];
    let p1 = pts[i + 1];
    let lipCol = random() < 0.45 ? "#b8bcc4" : "#7e828c";
    brush.set("cpencil", lipCol, baseWeight * random(0.45, 0.85));
    brush.line(p0.x + 1.5, p0.y + 2.2, p1.x + 1.5, p1.y + 2.2);

    if (random() < 0.35) {
      brush.set("micro_glare", "#e4e7ed", baseWeight * 0.35);
      brush.line(p0.x + 1, p0.y + 1.8, lerp(p0.x, p1.x, 0.6) + 1, lerp(p0.y, p1.y, 0.6) + 1.8);
    }
  }

  // 3. Crumbling secondary edge spalling in charcoal
  for (let i = 0; i < pts.length - 1; i++) {
    let p0 = pts[i];
    let p1 = pts[i + 1];
    brush.set("charcoal", "#121316", baseWeight * random(0.65, 1.15));
    brush.line(p0.x, p0.y, p1.x, p1.y);
  }

  // 4. Deep pitch-black void at the core of the crack
  for (let i = 0; i < pts.length - 1; i++) {
    let p0 = pts[i];
    let p1 = pts[i + 1];
    brush.set("rotring", "#040406", baseWeight * random(0.7, 1.25));
    brush.line(p0.x, p0.y, p1.x, p1.y);

    // Micro-void widenings along the fracture
    if (random() < 0.4) {
      brush.set("chisel_marker", "#050507", baseWeight * random(0.3, 0.55));
      brush.line(p0.x, p0.y, lerp(p0.x, p1.x, 0.7), lerp(p0.y, p1.y, 0.7));
    }
  }

  // 5. Loose dislodged grit pebbles inside and beside the crack
  for (let i = 1; i < pts.length - 1; i++) {
    if (random() < 0.55) {
      let p = pts[i];
      let ox = random(-10, 10);
      let oy = random(-8, 8);
      brush.set("rotring", random() < 0.5 ? "#d8dce3" : "#070709", random(0.4, 0.9));
      brush.line(p.x + ox, p.y + oy, p.x + ox + random(1.5, 4), p.y + oy + random(-1.5, 1.5));
    }
  }
}

function drawAsphaltCracks() {
  // Primary transverse fracture running right beneath the watermelon wedge
  let mainCrack1 = generateCrackPath(-20, 760, 480, 845, 28, 55);
  let mainCrack2 = generateCrackPath(480, 845, 860, 790, 22, 45);
  let mainCrack3 = generateCrackPath(860, 790, 1220, 875, 20, 48);
  renderCrack(mainCrack1, 1.35, true);
  renderCrack(mainCrack2, 1.4, true);
  renderCrack(mainCrack3, 1.3, true);

  // Branching fracture climbing toward upper-left into the heat-shimmer zone
  let branchUpLeft = generateCrackPath(345, 822, 65, 310, 32, 65);
  renderCrack(branchUpLeft, 1.0, true);

  // Sub-branch splitting toward upper center
  let branchMid = generateCrackPath(215, 560, 590, 415, 24, 50);
  renderCrack(branchMid, 0.75, false);

  // Foreground fracture descending from underneath the slice to bottom-right
  let branchDownRight = generateCrackPath(665, 818, 845, 1215, 26, 52);
  renderCrack(branchDownRight, 1.5, true);

  // Foreground left alligator-cracking network
  let branchDownLeft = generateCrackPath(295, 810, 140, 1190, 24, 48);
  renderCrack(branchDownLeft, 1.25, false);

  let crossLink = generateCrackPath(215, 995, 755, 1045, 28, 42);
  renderCrack(crossLink, 0.95, false);

  // Distant compressed horizontal crack in the upper asphalt
  let distantCrack = generateCrackPath(-10, 245, 1210, 215, 36, 28);
  renderCrack(distantCrack, 0.55, true);

  // Fine hairline fractures radiating near the impact zone
  for (let i = 0; i < 9; i++) {
    let sx = random(220, 960);
    let sy = random(580, 1060);
    let ang = random(0, 360);
    let len = random(45, 140);
    let hair = generateCrackPath(sx, sy, sx + cos(ang) * len, sy + sin(ang) * len, 10, 18);
    renderCrack(hair, random(0.45, 0.75), false);
  }
}

// ============================================================================
// 3. WET ASPHALT STAIN & TIGHT BLACK NOON SLIVER SHADOW
// ============================================================================

function drawWetSoakAndNoonShadow() {
  // Subtle dark wet moisture ring soaked into the porous asphalt immediately around the dropped fruit
  let soakPts = [];
  let steps = 44;
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let b = getBottomRindCurve(t);
    let spread = 14 + 22 * Math.sin(t * Math.PI) + random(-5, 7);
    soakPts.push([b.x + (t - 0.5) * 28, b.y + spread]);
  }
  for (let i = steps; i >= 0; i--) {
    let t = i / steps;
    let b = getBottomRindCurve(t);
    soakPts.push([b.x, b.y - 6]);
  }
  let soakPoly = new brush.Polygon(soakPts);
  soakPoly.wash("#141518", 165);

  // Textured dark wet asphalt edge (moisture darkens charcoal aggregate)
  for (let i = 0; i < 65; i++) {
    let t = random(0.02, 0.98);
    let b = getBottomRindCurve(t);
    let ox = random(-15, 15);
    let oy = random(2, 22 * Math.sin(t * Math.PI) + 8);
    brush.set("dry_scumble", "#101114", random(0.4, 0.9));
    brush.line(b.x + ox, b.y + oy, b.x + ox + random(10, 32), b.y + oy + random(-2, 2));
  }

  // TIGHT BLACK SLIVER SHADOW TUCKED DIRECTLY BENEATH THE WEDGE
  // Brutal overhead noon sun casts zero form shadow and only a razor-sharp occlusion sliver underneath
  let shadowPts = [];
  let shSteps = 60;
  for (let i = 0; i <= shSteps; i++) {
    let t = i / shSteps;
    let b = getBottomRindCurve(t);
    shadowPts.push([b.x, b.y - 3]);
  }
  for (let i = shSteps; i >= 0; i--) {
    let t = i / shSteps;
    let b = getBottomRindCurve(t);
    // Tucked tightly: only 9px to 24px deep directly under the curved rind overhang
    let sliverDepth = 7 + 17 * Math.pow(Math.sin(t * Math.PI), 0.75) + (noise(t * 25) - 0.5) * 6;
    shadowPts.push([b.x + (t - 0.5) * 8, b.y + sliverDepth]);
  }

  let shadowPoly = new brush.Polygon(shadowPts);
  shadowPoly.wash("#020203", 255);

  // Crisp jagged shadow edge biting into the asphalt aggregate
  for (let i = 0; i < shSteps; i++) {
    let t0 = i / shSteps;
    let t1 = (i + 1) / shSteps;
    let b0 = getBottomRindCurve(t0);
    let b1 = getBottomRindCurve(t1);
    let d0 = 6 + 15 * Math.pow(Math.sin(t0 * Math.PI), 0.75);
    let d1 = 6 + 15 * Math.pow(Math.sin(t1 * Math.PI), 0.75);

    brush.set("chisel_marker", "#030304", random(0.7, 1.25));
    brush.line(b0.x, b0.y + d0 * 0.5, b1.x, b1.y + d1 * 0.5);

    brush.set("rotring", "#000000", random(0.8, 1.4));
    brush.line(b0.x, b0.y + d0, b1.x + random(-2, 2), b1.y + d1 + random(-2, 2));
  }
}

// ============================================================================
// 4. WATERMELON RIND (ACID GREEN) & PITH (BLEACHED LIME-WHITE)
// ============================================================================

function drawWatermelonRindAndPith() {
  let steps = 64;

  // --- OUTER RIND POLYGON (BLOWN-OUT ACID GREEN) ---
  let rindPts = [];
  for (let i = 0; i <= steps; i++) {
    let p = getBottomRindCurve(i / steps);
    rindPts.push([p.x, p.y]);
  }
  for (let i = steps; i >= 0; i--) {
    let p = getRindTopCurve(i / steps);
    rindPts.push([p.x, p.y]);
  }
  let rindPoly = new brush.Polygon(rindPts);
  rindPoly.wash("#6eff00", 255);

  // Sweeping flat marker bands along the acid green rind
  let rindAcidCols = ["#7fff00", "#5ce600", "#99ff1a", "#47b800", "#b8ff33"];
  for (let pass = 0; pass < 7; pass++) {
    let v = map(pass, 0, 6, 0.12, 0.88);
    let col = rindAcidCols[pass % rindAcidCols.length];
    for (let i = 0; i < steps; i++) {
      let t0 = i / steps;
      let t1 = (i + 1) / steps;
      let b0 = getBottomRindCurve(t0);
      let r0 = getRindTopCurve(t0);
      let b1 = getBottomRindCurve(t1);
      let r1 = getRindTopCurve(t1);

      let x0 = lerp(b0.x, r0.x, v);
      let y0 = lerp(b0.y, r0.y, v);
      let x1 = lerp(b1.x, r1.x, v);
      let y1 = lerp(b1.y, r1.y, v);

      brush.set("chisel_marker", col, random(0.65, 1.15));
      brush.line(x0, y0, x1, y1);
    }
  }

  // Characteristic dark chlorophyll tiger-stripes & mottled bands on the outer rind
  let numStripes = 22;
  for (let s = 0; s < numStripes; s++) {
    let tCenter = map(s, 0, numStripes - 1, 0.04, 0.96) + random(-0.012, 0.012);
    let b = getBottomRindCurve(tCenter);
    let r = getRindTopCurve(tCenter);
    let stripeCol = s % 2 === 0 ? "#124d00" : "#1f7300";

    // Draw jagged radial/diagonal dark green rind markings
    for (let j = 0; j < 4; j++) {
      let dt = random(-0.014, 0.014);
      let bSub = getBottomRindCurve(constrain(tCenter + dt, 0.02, 0.98));
      let rSub = getRindTopCurve(constrain(tCenter + dt * 0.6, 0.02, 0.98));
      let vEnd = random(0.55, 0.92);
      let ex = lerp(bSub.x, rSub.x, vEnd);
      let ey = lerp(bSub.y, rSub.y, vEnd);

      brush.set("chisel_marker", stripeCol, random(0.55, 1.05));
      brush.line(bSub.x, bSub.y - 2, ex, ey);
    }
  }

  // Deep dark green bottom contact rim (still graphic and flat, no soft form gradient)
  for (let i = 0; i < steps; i++) {
    let t0 = i / steps;
    let t1 = (i + 1) / steps;
    let b0 = getBottomRindCurve(t0);
    let b1 = getBottomRindCurve(t1);
    brush.set("rotring", "#0c3800", 1.1);
    brush.line(b0.x, b0.y - 1, b1.x, b1.y - 1);
  }

  // --- PITH POLYGON (STARK SUN-BLEACHED WHITE-LIME BAND) ---
  let pithPts = [];
  for (let i = 0; i <= steps; i++) {
    let p = getRindTopCurve(i / steps);
    pithPts.push([p.x, p.y]);
  }
  for (let i = steps; i >= 0; i--) {
    let p = getPithTopCurve(i / steps);
    pithPts.push([p.x, p.y]);
  }
  let pithPoly = new brush.Polygon(pithPts);
  pithPoly.wash("#f2ffd6", 255);

  // Layer crisp neon-lime to glare-white marker passes across the pith
  let pithBands = [
    { v: 0.15, col: "#bfff00", w: 0.8 },
    { v: 0.38, col: "#dfff80", w: 0.9 },
    { v: 0.62, col: "#f5ffe6", w: 0.95 },
    { v: 0.85, col: "#ffffff", w: 1.0 }
  ];
  for (let band of pithBands) {
    for (let i = 0; i < steps; i++) {
      let t0 = i / steps;
      let t1 = (i + 1) / steps;
      let r0 = getRindTopCurve(t0);
      let p0 = getPithTopCurve(t0);
      let r1 = getRindTopCurve(t1);
      let p1 = getPithTopCurve(t1);

      let x0 = lerp(r0.x, p0.x, band.v);
      let y0 = lerp(r0.y, p0.y, band.v);
      let x1 = lerp(r1.x, p1.x, band.v);
      let y1 = lerp(r1.y, p1.y, band.v);

      brush.set("chisel_marker", band.col, band.w);
      brush.line(x0, y0, x1, y1);
    }
  }
}

// ============================================================================
// 5. WATERMELON FLESH (BLOWN & SATURATED FLAT MARKER REDS)
// ============================================================================

function drawWatermelonFlesh() {
  let steps = 70;
  let fleshPts = [];

  for (let i = 0; i <= steps; i++) {
    let p = getPithTopCurve(i / steps);
    fleshPts.push([p.x, p.y]);
  }
  for (let i = TOP_PROFILE_PTS.length - 1; i >= 0; i--) {
    let tp = TOP_PROFILE_PTS[i];
    fleshPts.push([tp.x, tp.y]);
  }

  // Solid blown-out crimson-red under-wash
  let fleshPoly = new brush.Polygon(fleshPts);
  fleshPoly.wash("#ff0a26", 255);

  // Flat graphic marker planes (cellular carpel zones, zero form-shadow)
  let flatRedPlanes = [
    // Left wing saturated scarlet
    { u0: 0.03, u1: 0.22, v0: 0.05, v1: 0.88, col: "#ff001e" },
    // Lower heart deep pure red
    { u0: 0.18, u1: 0.55, v0: 0.04, v1: 0.48, col: "#eb001b" },
    // Upper heart sun-bleached hot red-pink
    { u0: 0.30, u1: 0.58, v0: 0.42, v1: 0.94, col: "#ff2e4c" },
    // Mid-right vibrant marker crimson
    { u0: 0.50, u1: 0.82, v0: 0.08, v1: 0.72, col: "#ff0f2b" },
    // Right wing bright coral-red
    { u0: 0.75, u1: 0.97, v0: 0.06, v1: 0.85, col: "#ff2440" },
    // Right cut bevel face (reads via flat hue/value shift, not dark shadow)
    { u0: 0.48, u1: 0.98, v0: 0.82, v1: 1.00, col: "#ff4763" }
  ];

  for (let z of flatRedPlanes) {
    let p00 = mapFleshUV(z.u0, z.v0);
    let p10 = mapFleshUV(z.u1, z.v0);
    let p11 = mapFleshUV(z.u1, z.v1);
    let p01 = mapFleshUV(z.u0, z.v1);
    let zPoly = new brush.Polygon([
      [p00.x, p00.y],
      [p10.x, p10.y],
      [p11.x, p11.y],
      [p01.x, p01.y]
    ]);
    zPoly.wash(z.col, 230);
  }

  // Radial flat-marker strokes fanning from the heart/apex toward the rind
  let markerReds = ["#ff0022", "#e6001b", "#ff1a38", "#ff3853", "#d40018", "#ff526b"];
  let apex = mapFleshUV(0.46, 0.92);

  for (let i = 0; i < 165; i++) {
    let u = random(0.02, 0.98);
    let vStart = random(0.02, 0.65);
    let vEnd = constrain(vStart + random(0.18, 0.42), 0.05, 0.97);
    let p0 = mapFleshUV(u, vStart);
    let p1 = mapFleshUV(lerp(u, 0.46, 0.22), vEnd);

    let col = markerReds[floor(random(markerReds.length))];
    let bName = random() < 0.6 ? "chisel_marker" : "flat_broad";
    brush.set(bName, col, random(0.65, 1.35));
    brush.line(p0.x, p0.y, p1.x, p1.y);
  }

  // Horizontal/arcing marker strokes following the internal vascular rings of the melon
  for (let ring = 0; ring < 9; ring++) {
    let v = map(ring, 0, 8, 0.08, 0.84);
    for (let s = 0; s < 24; s++) {
      let u0 = s / 24;
      let u1 = (s + 1) / 24;
      if (v > 0.65 && u0 > 0.17 && u0 < 0.27) continue; // Respect impact cleft gap
      let p0 = mapFleshUV(u0, v + random(-0.02, 0.02));
      let p1 = mapFleshUV(u1, v + random(-0.02, 0.02));
      let col = random() < 0.35 ? "#ff4d67" : (random() < 0.5 ? "#ff001e" : "#cc0017");
      brush.set("chisel_marker", col, random(0.5, 1.05));
      brush.line(p0.x, p0.y, p1.x, p1.y);
    }
  }

  // Fibrous pink-red vascular strands & sugar-cell granularity across the flesh
  for (let i = 0; i < 240; i++) {
    let u = random(0.03, 0.97);
    let v = random(0.03, 0.94);
    let p0 = mapFleshUV(u, v);
    let p1 = mapFleshUV(constrain(u + random(-0.03, 0.03), 0.02, 0.98), constrain(v + random(0.03, 0.11), 0.02, 0.97));

    let cellCol = random() < 0.3 ? "#ff8598" : (random() < 0.6 ? "#b80015" : "#ff1f3d");
    brush.set("cpencil", cellCol, random(0.55, 1.15));
    brush.line(p0.x, p0.y, p1.x, p1.y);
  }

  // Bleeding transition fibers where wet red flesh meets the bleached white pith
  for (let i = 0; i < 95; i++) {
    let u = random(0.02, 0.98);
    let pPith = getPithTopCurve(u);
    let pFlesh = mapFleshUV(u, random(0.04, 0.14));
    let col = random() < 0.5 ? "#ff667d" : "#ffffff";
    brush.set("cpencil", col, random(0.5, 0.95));
    brush.line(pPith.x, pPith.y + 3, pFlesh.x, pFlesh.y);
  }
}

