function drawSingleSeed(x, y, angleDeg, scaleFactor, hasCavity) {
  push();
  translate(x, y);
  rotate(angleDeg);

  let L = 15 * scaleFactor;
  let W = 8.5 * scaleFactor;

  // Flat dark crimson seed-pocket cavity if embedded in the flesh
  if (hasCavity) {
    let cavPts = [
      [-L * 0.65, 0],
      [-L * 0.2, -W * 0.72],
      [L * 0.55, -W * 0.48],
      [L * 0.75, 0],
      [L * 0.55, W * 0.62],
      [-L * 0.2, W * 0.68]
    ];
    let cavPoly = new brush.Polygon(cavPts);
    cavPoly.wash("#8a0010", 255);

    // Wet white meniscus highlight hugging the seed pocket rim
    brush.set("micro_glare", "#ffffff", 0.95 * scaleFactor);
    brush.line(-L * 0.45, -W * 0.58, L * 0.4, -W * 0.42);
  }

  // Teardrop seed silhouette (pointed proximal tip at -L*0.55, rounded distal end at +L*0.55)
  let seedPts = [
    [-L * 0.58, 0],
    [-L * 0.22, -W * 0.36],
    [L * 0.18, -W * 0.52],
    [L * 0.48, -W * 0.34],
    [L * 0.58, 0],
    [L * 0.48, W * 0.34],
    [L * 0.18, W * 0.52],
    [-L * 0.22, W * 0.36]
  ];
  let sPoly = new brush.Polygon(seedPts);
  sPoly.wash("#07070a", 255);

  // Crisp ink contour & rich black lacquer core
  for (let i = 0; i < seedPts.length; i++) {
    let a = seedPts[i];
    let b = seedPts[(i + 1) % seedPts.length];
    brush.set("rotring", "#040406", 0.95 * scaleFactor);
    brush.line(a[0], a[1], b[0], b[1]);
  }
  brush.set("chisel_marker", "#0a0a0e", 0.6 * scaleFactor);
  brush.line(-L * 0.3, 0, L * 0.35, 0);

  // Stark glare-white noon reflection on the wet glossy black seed
  brush.set("micro_glare", "#ffffff", 1.15 * scaleFactor);
  brush.line(-L * 0.15, -W * 0.18, L * 0.32, -W * 0.16);
  brush.set("micro_glare", "#ffffff", 0.85 * scaleFactor);
  brush.line(L * 0.38, -W * 0.05, L * 0.44, W * 0.08);

  pop();
}

