// Safe polygon helper using beginShape/vertex/endShape as recommended
function drawPoly(pts, curvature = 0.08) {
  if (!pts || pts.length < 3) return;
  let clean = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    let dx = pts[i][0] - clean[clean.length - 1][0];
    let dy = pts[i][1] - clean[clean.length - 1][1];
    if (dx * dx + dy * dy > 0.4) clean.push(pts[i]);
  }
  if (clean.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < clean.length; i++) {
    brush.vertex(clean[i][0], clean[i][1]);
  }
  brush.endShape(true);
}

// Safe spline helper avoiding duplicate point tangent issues
function safeSpline(pts, curvature = 0.45) {
  if (!pts || pts.length < 2) return;
  let clean = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    let dx = pts[i][0] - clean[clean.length - 1][0];
    let dy = pts[i][1] - clean[clean.length - 1][1];
    if (dx * dx + dy * dy > 0.6) clean.push(pts[i]);
  }
  if (clean.length === 2) {
    brush.line(clean[0][0], clean[0][1], clean[1][0], clean[1][1]);
  } else if (clean.length >= 3) {
    brush.spline(clean, curvature);
  }
}

function eaveYAt(x) {
  let t = constrain((x - scene.MARGIN_X) / (1200 - 2 * scene.MARGIN_X), 0, 1);
  return lerp(scene.EAVE_Y_LEFT, scene.EAVE_Y_RIGHT, t);
}

function poleYAt(x) {
  return eaveYAt(x) + 18;
}

// Evaluate 3D-projected shriveled topography of a peeled persimmon
// u in [-1, 1] (left to right contour), v in [0, 1] (top crown under calyx to bottom pointed tip)
function evalPersimmon(p, u, v) {
  let vc = constrain(v, 0, 1);
  let uc = constrain(u, -1, 1);

  // Characteristic hoshigaki vertical silhouette:
  // Broad rounded shoulders near top, pinched shriveled waist around v=0.55,
  // slight lower belly, tapering to a pointed/acorn apex at v=1.0
  let shoulder = Math.pow(Math.sin(vc * Math.PI), 0.58);
  let topCrown = 0.34 * Math.exp(-Math.pow(vc / 0.14, 2));
  let waistPinch = 1.0 - p.pinch * Math.exp(-Math.pow((vc - 0.54) / 0.22, 2));
  let lowerBelly = 1.0 + 0.09 * Math.exp(-Math.pow((vc - 0.72) / 0.16, 2));
  let bottomPoint = 1.0 - 0.52 * Math.pow(vc, 3.2);

  let widthEnv = (shoulder * waistPinch * lowerBelly * bottomPoint + topCrown * (1 - vc)) * 0.96;

  // Longitudinal wrinkle rib modulation
  let ribFreq = p.numRibs * Math.PI;
  let ribEnv = Math.sin(vc * Math.PI) * (1.0 - 0.25 * Math.pow(vc, 2));
  let nVal = noise(p.seed + uc * 2.4, p.seed * 0.7 + vc * 3.2) - 0.5;
  let ribAngle = uc * ribFreq + p.ribPhase + nVal * 1.35;
  let ribWave = Math.cos(ribAngle); // +1 on ridge crest, -1 in wrinkle valley

  // Lateral s-curve twist of the drying fruit
  let spineCurve = p.asym * Math.pow(vc, 1.7) + 4.5 * Math.sin(vc * Math.PI * 1.5 + p.seed);

  // Horizontal radial displacement from ribs
  let rHoriz = p.rx * widthEnv * (1.0 + 0.055 * ribWave * ribEnv);
  // Subtle lateral warp of each meridian
  let meridianWarp = 4.2 * nVal * (1.0 - Math.abs(uc) * 0.5) * Math.sin(vc * Math.PI);

  let localX = uc * rHoriz + spineCurve * (1.0 - 0.25 * Math.abs(uc)) + meridianWarp;

  // Vertical position: crown is indented in center, bottom curves down to point,
  // and each rib scallops the contour vertically
  let baseH = (vc - 0.47) * 2.0 * p.ry;
  let crownDip = 7.5 * (1.0 - uc * uc) * Math.exp(-Math.pow(vc / 0.18, 2));
  let bottomDrop = 11.0 * Math.pow(1.0 - Math.abs(uc), 1.6) * Math.pow(vc, 2.4);
  let ribScallopY = 3.2 * ribWave * ribEnv * (vc - 0.35);

  let localY = baseH + crownDip + bottomDrop + ribScallopY;

  // Apply gentle hanging tilt
  let cosT = Math.cos(p.tilt);
  let sinT = Math.sin(p.tilt);
  let rx = localX * cosT - localY * sinT;
  let ry = localX * sinT + localY * cosT;

  return {
    x: p.cx + rx,
    y: p.cy + ry,
    ribWave: ribWave,
    widthEnv: widthEnv
  };
}

function buildScene() {
  // 6 rafters under the farmhouse eave
  let rafterXs = [135, 315, 495, 675, 855, 1035];
  for (let i = 0; i < rafterXs.length; i++) {
    let rx = rafterXs[i];
    let ey = eaveYAt(rx);
    scene.rafters.push({
      x: rx,
      y: ey - 58,
      w: 44,
      h: 52
    });
  }

  // 6 hanging strings in a staggered vertical rhythm across the 1200px width
  let stringX = [172, 344, 518, 692, 866, 1032];
  let stringYLists = [
    [325, 535, 750, 968],
    [278, 462, 650, 842, 1032],
    [345, 560, 775, 992],
    [286, 478, 672, 866, 1052],
    [330, 542, 758, 974],
    [292, 504, 720, 936]
  ];

  let pIndex = 0;
  for (let s = 0; s < stringX.length; s++) {
    let sx = stringX[s];
    let pyTop = poleYAt(sx);
    let yList = stringYLists[s];

    let strObj = {
      index: s,
      xBase: sx,
      yTop: pyTop - 13,
      yBottom: yList[yList.length - 1] + 95,
      swaySeed: 100 + s * 37.3,
      fruits: []
    };

    for (let k = 0; k < yList.length; k++) {
      let fy = yList[k] + random(-6, 6);
      let swayX = sx + 5.5 * Math.sin(fy * 0.007 + strObj.swaySeed) + random(-4, 4);

      let p = {
        id: pIndex++,
        stringIdx: s,
        cx: swayX,
        cy: fy,
        rx: random(57, 66),
        ry: random(63, 74),
        tilt: radians(random(-4.5, 4.5)),
        pinch: random(0.16, 0.27),
        asym: random(-7.5, 7.5),
        numRibs: int(random(11, 15)),
        ribPhase: random(0, TWO_PI),
        seed: random(10, 900),
        // Woodblock registration offsets (creates authentic paper-white gaps)
        regGap: [random(-6.0, -4.2), random(-4.0, -2.5)],
        regOrange: [0, 0],
        regRed: [random(3.2, 5.2), random(1.8, 3.4)],
        regIndigo: [random(5.5, 8.0), random(2.8, 4.8)],
        regCalyx: [random(-1.5, 1.5), random(-4.2, -2.5)]
      };

      // Precompute key polygons for woodblock batching
      p.polySilhouette = buildSilhouettePoly(p, 0, 0, 1.0);
      p.polyGapReserve = buildSilhouettePoly(p, p.regGap[0], p.regGap[1], 1.02);
      p.polySunGold = buildSunGoldPoly(p);
      p.polyOrange = buildOrangeBlockPoly(p);
      p.polyRed = buildRedBlockPoly(p);
      p.polyClaret = buildClaretBlockPoly(p);
      p.polyIndigo = buildIndigoBlockPoly(p);
      p.calyxData = buildCalyxData(p);

      strObj.fruits.push(p);
      scene.persimmons.push(p);
    }
    scene.strings.push(strObj);
  }
}

function buildSilhouettePoly(p, dx, dy, scaleM = 1.0) {
  let pts = [];
  let steps = 28;
  // Left contour top to bottom
  for (let i = 0; i <= steps; i++) {
    let v = i / steps;
    let pt = evalPersimmon(p, -1.0, v);
    pts.push([
      p.cx + (pt.x - p.cx) * scaleM + dx,
      p.cy + (pt.y - p.cy) * scaleM + dy
    ]);
  }
  // Right contour bottom to top
  for (let i = steps; i >= 0; i--) {
    let v = i / steps;
    let pt = evalPersimmon(p, 1.0, v);
    pts.push([
      p.cx + (pt.x - p.cx) * scaleM + dx,
      p.cy + (pt.y - p.cy) * scaleM + dy
    ]);
  }
  return pts;
}

// Sunlit golden-apricot block on left shoulder and ribs
function buildSunGoldPoly(p) {
  let pts = [];
  let steps = 22;
  for (let i = 0; i <= steps; i++) {
    let v = i / steps;
    let pt = evalPersimmon(p, -0.98, v);
    pts.push([pt.x - 1.5, pt.y - 1.0]);
  }
  for (let i = steps; i >= 0; i--) {
    let v = i / steps;
    // Jagged woodblock edge following ribs on sunlit side
    let jag = 0.18 * Math.sin(v * p.numRibs * Math.PI + p.ribPhase);
    let uRight = -0.15 + jag - 0.25 * Math.pow(v, 1.5);
    let pt = evalPersimmon(p, uRight, v);
    pts.push([pt.x, pt.y]);
  }
  return pts;
}

// Main Burnt Orange woodblock
function buildOrangeBlockPoly(p) {
  let pts = [];
  let steps = 24;
  for (let i = 0; i <= steps; i++) {
    let v = i / steps;
    let pt = evalPersimmon(p, -0.96, v);
    pts.push([pt.x + p.regOrange[0], pt.y + p.regOrange[1]]);
  }
  for (let i = steps; i >= 0; i--) {
    let v = i / steps;
    let jag = 0.14 * Math.cos(v * 9.0 + p.seed);
    let uRight = constrain(0.76 + jag, 0.45, 0.92);
    let pt = evalPersimmon(p, uRight, v);
    pts.push([pt.x + p.regOrange[0], pt.y + p.regOrange[1]]);
  }
  return pts;
}

// Vivid Persimmon Red woodblock (shifted slightly for off-registration, carved with wrinkle fingers)
function buildRedBlockPoly(p) {
  let pts = [];
  let steps = 28;
  // Left edge of red block weaves in and out of the longitudinal wrinkle valleys
  for (let i = 0; i <= steps; i++) {
    let v = 0.04 + 0.93 * (i / steps);
    let finger = 0.34 * Math.sin(v * 7.5 * Math.PI + p.seed);
    let uLeft = constrain(-0.42 + finger + 0.15 * Math.sin(v * Math.PI), -0.82, 0.15);
    let pt = evalPersimmon(p, uLeft, v);
    pts.push([pt.x + p.regRed[0], pt.y + p.regRed[1]]);
  }
  // Right edge of red block
  for (let i = steps; i >= 0; i--) {
    let v = 0.04 + 0.93 * (i / steps);
    let uRight = constrain(0.86 - 0.08 * Math.sin(v * 6.0), 0.55, 0.95);
    let pt = evalPersimmon(p, uRight, v);
    pts.push([pt.x + p.regRed[0], pt.y + p.regRed[1]]);
  }
  return pts;
}

// Deep Claret / Carmine block for pinched waist & central deep folds
function buildClaretBlockPoly(p) {
  let pts = [];
  let steps = 18;
  for (let i = 0; i <= steps; i++) {
    let v = 0.18 + 0.72 * (i / steps);
    let finger = 0.28 * Math.cos(v * 8.0 * Math.PI + p.ribPhase);
    let uLeft = -0.12 + finger;
    let pt = evalPersimmon(p, uLeft, v);
    pts.push([pt.x + p.regRed[0] + 1.5, pt.y + p.regRed[1] + 1.0]);
  }
  for (let i = steps; i >= 0; i--) {
    let v = 0.18 + 0.72 * (i / steps);
    let uRight = 0.68 + 0.12 * Math.sin(v * 5.0 * Math.PI);
    let pt = evalPersimmon(p, uRight, v);
    pts.push([pt.x + p.regRed[0] + 1.5, pt.y + p.regRed[1] + 1.0]);
  }
  return pts;
}

// Smoky Indigo Shadow Block on right side & underside, shifted by regIndigo
function buildIndigoBlockPoly(p) {
  let pts = [];
  let steps = 26;
  // Inner terminator edge of shadow block with carved wrinkle serrations
  for (let i = 0; i <= steps; i++) {
    let v = 0.03 + 0.96 * (i / steps);
    let serration = 0.22 * Math.sin(v * 8.5 * Math.PI + p.seed * 1.3);
    // Wraps further left near the top under calyx and near the bottom pointed apex
    let wrap = 0.42 - 0.35 * Math.pow(v - 0.48, 2) * 2.2;
    let uTerm = constrain(wrap + serration, -0.35, 0.72);
    let pt = evalPersimmon(p, uTerm, v);
    pts.push([pt.x + p.regIndigo[0], pt.y + p.regIndigo[1]]);
  }
  // Outer right contour of shadow block
  for (let i = steps; i >= 0; i--) {
    let v = 0.03 + 0.96 * (i / steps);
    let pt = evalPersimmon(p, 1.0, v);
    pts.push([pt.x + p.regIndigo[0], pt.y + p.regIndigo[1]]);
  }
  return pts;
}

// Dried 4-lobed woody calyx (heta) at the crown of each persimmon
function buildCalyxData(p) {
  let topPt = evalPersimmon(p, 0, 0.02);
  let cx = topPt.x + p.regCalyx[0];
  let cy = topPt.y - 5.0 + p.regCalyx[1];
  let w = p.rx * 0.68;
  let h = 15.0;

  // Curled multi-lobed silhouette of dried calyx
  let lobes = [];
  let nPts = 20;
  for (let i = 0; i < nPts; i++) {
    let ang = map(i, 0, nPts, 0, TWO_PI);
    // 4 curled woody leaves
    let lobeR = 1.0 + 0.32 * Math.cos(ang * 4 + p.seed) + 0.14 * Math.sin(ang * 3);
    let lx = cx + Math.cos(ang) * w * lobeR;
    let ly = cy + Math.sin(ang) * h * lobeR - 3.5 * Math.pow(Math.cos(ang), 2);
    lobes.push([lx, ly]);
  }

  // Reserve polygon slightly larger below to guarantee crisp paper-white gap under calyx
  let reserve = [];
  for (let i = 0; i < nPts; i++) {
    let ang = map(i, 0, nPts, 0, TWO_PI);
    let lobeR = 1.15 + 0.32 * Math.cos(ang * 4 + p.seed);
    reserve.push([
      cx + Math.cos(ang) * (w + 4.5) * lobeR - 1.5,
      cy + Math.sin(ang) * (h + 4.0) * lobeR + 1.5
    ]);
  }

  return {
    cx: cx,
    cy: cy,
    w: w,
    h: h,
    poly: lobes,
    reservePoly: reserve
  };
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(SEED);
  noiseSeed(SEED);

  // Add custom woodblock chisel/gouge brush for crisp carved relief marks
  brush.add("chisel", {
    type: "custom",
    weight: 2.2,
    scatter: 0.06,
    opacity: 210,
    spacing: 0.25,
    pressure: [0.6, 1.3, 0.5],
    tip: (_m) => {
      _m.rotate(30);
      _m.rect(-1.4, -0.45, 2.8, 0.9);
    },
    rotate: "natural",
    markerTip: false,
    noise: 0.35
  });

  buildScene();
}

function draw() {
  translate(-width / 2, -height / 2);

  // 1. Warm Washi Paper Ground
  background(PAL.paper);
  drawPaperFibers();

  // 2. Buff Ground Block & Cast Wall Shadows
  drawBuffGroundAndWallShadows();

  // 3. Farmhouse Eave & Bamboo Pole Blocks
  drawFarmhouseEave();

  // 4. Off-Registration Paper-White Reserves for Persimmons & Calyxes
  drawPaperWhiteReserves();

  // 5. Batched Persimmon Watercolor Woodblocks (Orange, Red, Claret, Indigo, Calyx)
  drawPersimmonWoodblocks();

  // 6. Pale Pencil Woodgrain Texture Showing Through Every Fill
  drawWoodgrainThroughAllBlocks();

  // 7. Obsessive Hyperreal Detail: Wrinkled Skins, Knife-Peel Facets, Sugar Bloom, Calyxes
  drawHyperrealPersimmons();

  // 8. Twisted Hemp Strings, Knots & Woody Stems
  drawStringsAndKnots();

  // 9. Print Margin Kento Registration Marks & Carved Red Hanko Seal
  drawPrintMarginDetails();

  noLoop();
}

// ---------------------------------------------------------------------------
// STEP 1: Subtle Washi Paper Fibers
// ---------------------------------------------------------------------------
function drawPaperFibers() {
  brush.noFill();
  brush.noHatch();
  brush.set("2H", "#e6d6bc", 0.22);
  for (let i = 0; i < 180; i++) {
    let x = random(20, 1180);
    let y = random(20, 1180);
    let a = random(0, 180);
    let len = random(18, 55);
    brush.line(x, y, x + cos(a) * len, y + sin(a) * len);
  }
}

// ---------------------------------------------------------------------------
// STEP 2: Buff Background Block & Cast Autumn Sun Shadows on Farmhouse Wall
// ---------------------------------------------------------------------------
function drawBuffGroundAndWallShadows() {
  let mx = scene.MARGIN_X;
  let my = scene.MARGIN_Y;
  let rightX = 1200 - mx;
  let botY = 1200 - my;

  brush.noStroke();

  // Main warm buff ground block (divided into 3 subtle woodblock plank zones)
  brush.fill(PAL.buffLight, 155);
  brush.fillBleed(0.06, "in");
  brush.fillTexture(0.55, 0.38);

  let yEaveL = eaveYAt(mx) - 4;
  let yEaveR = eaveYAt(rightX) - 4;
  drawPoly([
    [mx, yEaveL],
    [rightX, yEaveR],
    [rightX, botY],
    [mx, botY]
  ], 0.02);

  // Secondary warm ochre-buff tonal block on lower/right half of wall
  brush.fill(PAL.buffMid, 95);
  brush.fillBleed(0.08, "in");
  brush.fillTexture(0.6, 0.35);
  drawPoly([
    [mx + 6, yEaveL + 110],
    [rightX - 4, yEaveR + 65],
    [rightX - 4, botY - 4],
    [mx + 6, botY - 4]
  ], 0.03);

  // Diagonal cast shadow of the eave & bamboo pole across upper buff wall
  brush.fill(PAL.indigoCast, 72);
  brush.fillBleed(0.05, "in");
  brush.fillTexture(0.5, 0.42);
  drawPoly([
    [mx, yEaveL + 4],
    [rightX, yEaveR + 4],
    [rightX, yEaveR + 128],
    [620, yEaveL + 96],
    [mx, yEaveL + 68]
  ], 0.04);

  // Cast shadows of the hanging persimmons & strings on the buff wall behind them
  // Cold side sun from left/top-left casts shadows ~40px right and ~16px down
  let shadowDX = 40;
  let shadowDY = 16;

  brush.fill(PAL.indigoCast, 88);
  brush.fillBleed(0.07, "in");
  brush.fillTexture(0.55, 0.45);

  for (let i = 0; i < scene.persimmons.length; i++) {
    let p = scene.persimmons[i];
    // Clip shadow to right print margin
    let shPoly = [];
    for (let j = 0; j < p.polySilhouette.length; j += 2) {
      let sx = min(p.polySilhouette[j][0] + shadowDX, rightX - 3);
      let sy = min(p.polySilhouette[j][1] + shadowDY, botY - 3);
      shPoly.push([sx, sy]);
    }
    drawPoly(shPoly, 0.1);
  }

  brush.noFill();

  // Cast shadow lines of the vertical strings on the buff wall
  brush.set("charcoal", PAL.indigoCast, 0.75);
  for (let s = 0; s < scene.strings.length; s++) {
    let st = scene.strings[s];
    let sx = min(st.xBase + shadowDX, rightX - 6);
    brush.line(sx, st.yTop + shadowDY, sx + 3, min(st.yBottom + shadowDY, botY - 8));
  }
}

// ---------------------------------------------------------------------------
// STEP 3: Sienna Farmhouse Eave, Rafters (Taruki), & Hanging Bamboo Pole
// ---------------------------------------------------------------------------
function drawFarmhouseEave() {
  let mx = scene.MARGIN_X;
  let my = scene.MARGIN_Y;
  let rightX = 1200 - mx;
  let yL = scene.EAVE_Y_LEFT;
  let yR = scene.EAVE_Y_RIGHT;

  brush.noStroke();

  // 1. Deep smoky indigo under-roof shadow cavity at top
  brush.fill(PAL.indigoDeep, 225);
  brush.fillBleed(0.04, "in");
  brush.fillTexture(0.5, 0.45);
  drawPoly([
    [mx, my],
    [rightX, my],
    [rightX, yR - 54],
    [mx, yL - 54]
  ], 0.02);

  // Also dark indigo shadow strip immediately behind the bamboo pole
  for (let i = 0; i < scene.rafters.length; i++) {
    let rf = scene.rafters[i];
    // Cast shadow to the right of each projecting rafter
    drawPoly([
      [rf.x + rf.w + 3, rf.y + 4],
      [rf.x + rf.w + 52, rf.y + 18],
      [rf.x + rf.w + 46, rf.y + rf.h + 6],
      [rf.x + rf.w + 3, rf.y + rf.h + 2]
    ], 0.02);
  }

  // 2. Main horizontal sienna eave beam (fascia / keta)
  // Leave a 3.5px paper-white registration gap below the top indigo block!
  brush.fill(PAL.siennaMid, 205);
  brush.fillBleed(0.05, "in");
  brush.fillTexture(0.58, 0.48);
  drawPoly([
    [mx, yL - 50],
    [rightX - 4, yR - 50],
    [rightX - 4, yR - 4],
    [mx, yL - 4]
  ], 0.02);

  // Projecting rafter side blocks (sunlit left bevel)
  for (let i = 0; i < scene.rafters.length; i++) {
    let rf = scene.rafters[i];
    drawPoly([
      [rf.x - 14, rf.y - 12],
      [rf.x - 2, rf.y - 12],
      [rf.x - 2, rf.y + rf.h - 2],
      [rf.x - 14, rf.y + rf.h - 10]
    ], 0.02);
  }

  // 3. Sunlit burnt-orange / terracotta upper plank & rafter end-grain faces
  brush.fill(PAL.siennaSun, 195);
  brush.fillBleed(0.05, "in");
  brush.fillTexture(0.52, 0.42);
  drawPoly([
    [mx + 3, yL - 82],
    [rightX - 6, yR - 82],
    [rightX - 6, yR - 55],
    [mx + 3, yL - 55]
  ], 0.02);

  for (let i = 0; i < scene.rafters.length; i++) {
    let rf = scene.rafters[i];
    // End-grain square face with slight registration offset
    drawPoly([
      [rf.x + 2, rf.y],
      [rf.x + rf.w, rf.y - 1],
      [rf.x + rf.w, rf.y + rf.h - 2],
      [rf.x + 2, rf.y + rf.h - 1]
    ], 0.02);
  }

  // 4. Deep sienna-umber soffit underside block
  brush.fill(PAL.siennaDeep, 190);
  brush.fillBleed(0.04, "in");
  brush.fillTexture(0.5, 0.45);
  drawPoly([
    [mx + 5, yL - 22],
    [rightX, yR - 22],
    [rightX, yR + 2],
    [mx + 5, yL + 2]
  ], 0.02);

  // 5. Suspended horizontal Bamboo Pole (Take-zao)
  let pyL = poleYAt(mx);
  let pyR = poleYAt(rightX);
  // First wash a crisp paper-white top registration gap along the pole
  brush.noFill();
  brush.wash(PAL.paper, 250);
  drawPoly([
    [mx, pyL - 14],
    [rightX, pyR - 14],
    [rightX, pyR + 10],
    [mx, pyL + 10]
  ], 0.01);
  brush.noWash();

  // Sunlit top half of bamboo pole
  brush.fill(PAL.bambooLit, 205);
  brush.fillBleed(0.03, "in");
  brush.fillTexture(0.48, 0.4);
  drawPoly([
    [mx + 2, pyL - 10],
    [rightX - 2, pyR - 10],
    [rightX - 2, pyR + 3],
    [mx + 2, pyL + 3]
  ], 0.01);

  // Shadowed lower half of bamboo pole (indigo-umber)
  brush.fill(PAL.indigoMid, 195);
  brush.fillBleed(0.03, "in");
  brush.fillTexture(0.5, 0.45);
  drawPoly([
    [mx + 5, pyL + 1],
    [rightX, pyR + 1],
    [rightX, pyR + 12],
    [mx + 5, pyL + 12]
  ], 0.01);

  brush.noFill();

  // Carved details on rafters (end-grain concentric rings & cracks) and bamboo nodes
  for (let i = 0; i < scene.rafters.length; i++) {
    let rf = scene.rafters[i];
    let rcx = rf.x + rf.w * 0.52;
    let rcy = rf.y + rf.h * 0.52;

    // Paper-white registration gap along left & top of rafter face
    brush.set("chisel", PAL.paper, 0.9);
    brush.line(rf.x, rf.y - 1, rf.x + rf.w, rf.y - 2);
    brush.line(rf.x, rf.y - 1, rf.x, rf.y + rf.h);

    // End-grain heartwood growth rings
    brush.set("rotring", PAL.umberDark, 0.55);
    for (let r = 6; r <= 22; r += 5) {
      let ringPts = [];
      for (let a = 0; a < 360; a += 30) {
        let rx = constrain(rcx + cos(a) * r * 1.05, rf.x + 3, rf.x + rf.w - 3);
        let ry = constrain(rcy + sin(a) * r * 1.15, rf.y + 3, rf.y + rf.h - 3);
        ringPts.push([rx, ry]);
      }
      drawPoly(ringPts, 0.25);
    }
    // Radial wood check crack in end-grain
    brush.set("chisel", PAL.paper, 0.55);
    brush.line(rcx, rcy, rf.x + rf.w - 4, rcy - 6);
    brush.set("rotring", PAL.indigoInk, 0.65);
    brush.line(rcx, rcy, rf.x + 5, rcy + 10);

    // Keyblock outline of rafter
    brush.set("pen", PAL.umberDark, 0.85);
    brush.line(rf.x + 2, rf.y, rf.x + rf.w, rf.y);
    brush.line(rf.x + rf.w, rf.y, rf.x + rf.w, rf.y + rf.h);
    brush.line(rf.x + 2, rf.y + rf.h, rf.x + rf.w, rf.y + rf.h);
  }

  // Bamboo pole nodes (fushi) and straw hanging loops (wara-nawa)
  let nodeXs = [125, 355, 595, 835, 1065];
  for (let nx of nodeXs) {
    let ny = poleYAt(nx);
    brush.set("chisel", PAL.paper, 0.7);
    brush.line(nx - 3, ny - 11, nx - 3, ny + 11);
    brush.set("pen", PAL.umberDark, 0.95);
    brush.line(nx, ny - 12, nx - 1, ny + 12);
    brush.line(nx + 4, ny - 11, nx + 3, ny + 12);
  }

  // Coarse twisted straw ropes suspending the bamboo pole from the eave at two points
  let ropeXs = [235, 955];
  for (let rx of ropeXs) {
    let py = poleYAt(rx);
    let ey = eaveYAt(rx) - 52;
    brush.set("chisel", PAL.paper, 1.1);
    brush.line(rx - 6, ey, rx - 6, py + 12);
    for (let yy = ey; yy < py + 10; yy += 6) {
      brush.set("pen", PAL.bambooLit, 1.1);
      brush.line(rx - 4, yy, rx + 5, yy + 4);
      brush.set("rotring", PAL.umberDark, 0.8);
      brush.line(rx - 4, yy + 3, rx + 5, yy + 7);
    }
  }
}

// ---------------------------------------------------------------------------
// STEP 4: Paper-White Off-Registration Reserves
// ---------------------------------------------------------------------------
function drawPaperWhiteReserves() {
  brush.noStroke();
  brush.noFill();
  brush.wash(PAL.paper, 255);

  // Wash paper-white shifted to top-left for every persimmon, PLUS main silhouette
  // so the thin paper-white registration gap shines cleanly along sunlit edges
  for (let i = 0; i < scene.persimmons.length; i++) {
    let p = scene.persimmons[i];
    drawPoly(p.polyGapReserve, 0.12);
    drawPoly(p.polySilhouette, 0.12);
  }

  brush.noWash();
}

// ---------------------------------------------------------------------------
// STEP 5: Batched Persimmon Woodblock Watercolor Fills
// ---------------------------------------------------------------------------
function drawPersimmonWoodblocks() {
  brush.noStroke();

  // BLOCK 1: Sunlit Cadmium Gold-Apricot Block (left shoulder & sunlit ridges)
  brush.fill(PAL.goldSun, 185);
  brush.fillBleed(0.05, "in");
  brush.fillTexture(0.52, 0.42);
  for (let i = 0; i < scene.persimmons.length; i++) {
    drawPoly(scene.persimmons[i].polySunGold, 0.1);
  }

  // BLOCK 2: Vivid Burnt Orange Main Body Block
  brush.fill(PAL.orangeVivid, 195);
  brush.fillBleed(0.06, "in");
  brush.fillTexture(0.58, 0.48);
  for (let i = 0; i < scene.persimmons.length; i++) {
    drawPoly(scene.persimmons[i].polyOrange, 0.1);
  }

  // BLOCK 3: Saturated Persimmon Red Mid/Fold Block (shifted by regRed)
  brush.fill(PAL.redPersimmon, 190);
  brush.fillBleed(0.06, "in");
  brush.fillTexture(0.6, 0.5);
  for (let i = 0; i < scene.persimmons.length; i++) {
    drawPoly(scene.persimmons[i].polyRed, 0.08);
  }

  // BLOCK 4: Deep Claret / Burnt Carmine Crevice Block
  brush.fill(PAL.claret, 175);
  brush.fillBleed(0.05, "in");
  brush.fillTexture(0.55, 0.45);
  for (let i = 0; i < scene.persimmons.length; i++) {
    drawPoly(scene.persimmons[i].polyClaret, 0.08);
  }

  // BLOCK 5: Smoky Indigo Shadow Block (shifted by regIndigo)
  brush.fill(PAL.indigoMid, 210);
  brush.fillBleed(0.05, "in");
  brush.fillTexture(0.62, 0.52);
  for (let i = 0; i < scene.persimmons.length; i++) {
    drawPoly(scene.persimmons[i].polyIndigo, 0.09);
  }

  // BLOCK 6: Paper-white registration gap under each calyx, then Calyx Umber Block
  brush.noFill();
  brush.wash(PAL.paper, 255);
  for (let i = 0; i < scene.persimmons.length; i++) {
    drawPoly(scene.persimmons[i].calyxData.reservePoly, 0.15);
  }
  brush.noWash();

  brush.fill(PAL.umberDark, 215);
  brush.fillBleed(0.03, "in");
  brush.fillTexture(0.5, 0.5);
  for (let i = 0; i < scene.persimmons.length; i++) {
    drawPoly(scene.persimmons[i].calyxData.poly, 0.18);
  }

  brush.noFill();
}

// ---------------------------------------------------------------------------
// STEP 6: Pale Pencil Woodgrain Texture Showing Through Every Fill
// ---------------------------------------------------------------------------
function drawWoodgrainThroughAllBlocks() {
  let mx = scene.MARGIN_X;
  let my = scene.MARGIN_Y;
  let rightX = 1200 - mx;
  let botY = 1200 - my;

  brush.clip([mx, my, rightX, botY]);

  // A. Horizontal plank woodgrain with heartwood cathedrals across Eave & Buff Ground
  let knots = [
    { x: 310, y: 125, rx: 140, ry: 34 },
    { x: 820, y: 105, rx: 160, ry: 30 },
    { x: 420, y: 460, rx: 220, ry: 85 },
    { x: 790, y: 820, rx: 250, ry: 95 }
  ];

  for (let yBase = my + 4; yBase < botY; yBase += 5.5) {
    let inEave = yBase < 200;
    if (inEave) {
      brush.set("cpencil", PAL.woodGrainLight, random(0.28, 0.48));
    } else {
      brush.set("2H", (yBase % 11 < 5.5) ? PAL.paper : "#dcc198", random(0.26, 0.44));
    }

    let pts = [];
    for (let x = mx; x <= rightX; x += 28) {
      let dy = 9.0 * (noise(x * 0.0035, yBase * 0.012) - 0.5);
      // Cathedral ring deflection around plank knots
      for (let k of knots) {
        let dxK = (x - k.x) / k.rx;
        let dyK = (yBase - k.y) / k.ry;
        let d2 = dxK * dxK + dyK * dyK;
        if (d2 < 2.2) {
          dy += (yBase < k.y ? -1 : 1) * 14.0 * Math.exp(-d2 * 1.4) * Math.cos(Math.sqrt(d2) * 5.0);
        }
      }
      pts.push([x, yBase + dy]);
    }
    safeSpline(pts, 0.35);
  }

  // B. Prominent pale pencil woodgrain running right through each Persimmon's blocks!
  // Simulates the cherry-wood block grain (mokume) printing through the vivid orange, red & indigo ink
  for (let i = 0; i < scene.persimmons.length; i++) {
    let p = scene.persimmons[i];
    // Plank knot center near the persimmon for authentic cathedral grain arches
    let kx = p.cx + (i % 2 === 0 ? -18 : 18);
    let ky = p.cy + ((i % 3) - 1) * 20;

    // 19 grain lines spanning across the fruit width
    let nGrain = 19;
    for (let g = 0; g < nGrain; g++) {
      let uBase = map(g, 0, nGrain - 1, -0.92, 0.92);
      let isShadowSide = uBase > 0.38;

      // Pale buff/cream pencil over orange & red; pale slate/buff pencil over indigo shadow
      if (isShadowSide) {
        brush.set("cpencil", (g % 2 === 0) ? PAL.woodGrainLight : PAL.woodGrainIndigo, 0.34);
      } else {
        brush.set("cpencil", (g % 2 === 0) ? PAL.paperBright : PAL.woodGrainWarm, 0.38);
      }

      let gPts = [];
      for (let s = 0; s <= 12; s++) {
        let v = 0.05 + 0.9 * (s / 12);
        // Woodgrain flows vertically with a cathedral wave independent of the fruit's ribs
        let pt = evalPersimmon(p, uBase, v);
        let dxK = (pt.x - kx) / 36.0;
        let dyK = (pt.y - ky) / 48.0;
        let d2 = dxK * dxK + dyK * dyK;
        let grainWave = 5.5 * Math.sin(pt.y * 0.055 + g * 0.45 + p.seed)
                      + (uBase < 0 ? -1 : 1) * 6.5 * Math.exp(-d2);
        gPts.push([pt.x + grainWave * 0.45, pt.y]);
      }
      safeSpline(gPts, 0.4);
    }
  }

  brush.noClip();
}

// ---------------------------------------------------------------------------
// STEP 7: Obsessive Hyperreal Detail on Every Persimmon
// ---------------------------------------------------------------------------
function drawHyperrealPersimmons() {
  for (let i = 0; i < scene.persimmons.length; i++) {
    let p = scene.persimmons[i];
    renderSinglePersimmonDetail(p);
  }
}

function renderSinglePersimmonDetail(p) {
  let M = p.numRibs; // 11 to 14 longitudinal ribs

  // -------------------------------------------------------------------------
  // 1. Off-Registration Paper-White Block Gaps (Carved Relief Highlights)
  // -------------------------------------------------------------------------
  brush.set("chisel", PAL.paperBright, 0.95);
  let leftRimPts = [];
  for (let s = 0; s <= 16; s++) {
    let v = 0.03 + 0.92 * (s / 16);
    let pt = evalPersimmon(p, -0.99, v);
    leftRimPts.push([pt.x - 2.2, pt.y - 1.2]);
  }
  safeSpline(leftRimPts, 0.45);

  // Thin paper-white registration sliver along the boundary between orange and red/indigo blocks
  brush.set("chisel", PAL.paper, 0.6);
  let gapSeamPts = [];
  for (let s = 0; s <= 12; s++) {
    let v = 0.12 + 0.72 * (s / 12);
    let uSeam = 0.36 + 0.14 * Math.sin(v * 7.0 * Math.PI + p.seed);
    let pt = evalPersimmon(p, uSeam, v);
    gapSeamPts.push([pt.x + p.regRed[0] * 0.5, pt.y]);
  }
  safeSpline(gapSeamPts, 0.35);

  // -------------------------------------------------------------------------
  // 2. Transverse Knife-Peel Facets & Shriveled Skin Crinkles
  // (Before drying, persimmons are peeled in spiral bands; as they shrivel,
  // horizontal facet rings and micro-puckers cross the vertical ribs)
  // -------------------------------------------------------------------------
  let peelBands = 15;
  for (let b = 1; b < peelBands; b++) {
    let vBand = map(b, 0, peelBands, 0.07, 0.93);
    for (let r = 0; r < M; r++) {
      let u0 = map(r, 0, M, -0.92, 0.92);
      let u1 = map(r + 0.75, 0, M, -0.92, 0.92);
      let uMid = (u0 + u1) * 0.5;

      let p0 = evalPersimmon(p, u0, vBand);
      let pMid = evalPersimmon(p, uMid, vBand + 0.014 * Math.sin(r * 1.9 + b));
      let p1 = evalPersimmon(p, u1, vBand + 0.006);

      if (uMid < -0.15) {
        // Sunlit side: warm burnt-orange & golden micro-facets
        brush.set("2B", (b % 2 === 0) ? PAL.orangeBurnt : PAL.goldSun, 0.32);
      } else if (uMid < 0.38) {
        // Mid-tone: crimson / deep persimmon red micro-puckers
        brush.set("rotring", (b % 2 === 0) ? PAL.redDeep : PAL.claret, 0.34);
      } else {
        // Shadow side: smoky indigo & dark umber micro-wrinkles
        brush.set("rotring", (b % 2 === 0) ? PAL.indigoDeep : PAL.claret, 0.36);
      }
      safeSpline([
        [p0.x, p0.y],
        [pMid.x, pMid.y],
        [p1.x, p1.y]
      ], 0.4);
    }
  }

  // -------------------------------------------------------------------------
  // 3. Deep Longitudinal Wrinkle Valleys, Forking Y-Creases, & Sunlit Ridges
  // -------------------------------------------------------------------------
  for (let r = 0; r <= M; r++) {
    let uValley = map(r, 0, M, -0.94, 0.94);
    let uRidge = map(r + 0.5, 0, M, -0.94, 0.94);

    // A. Trace the deep longitudinal valley crease
    let valleyPts = [];
    let steps = 20;
    for (let s = 0; s <= steps; s++) {
      let v = 0.04 + 0.93 * (s / steps);
      // Wrinkles pinch and wiggle organically
      let wiggle = 0.032 * Math.sin(v * 8.0 * Math.PI + r * 1.7 + p.seed);
      let pt = evalPersimmon(p, constrain(uValley + wiggle, -0.98, 0.98), v);
      // Variable pressure: deeper in the pinched waist and upper shoulder
      let press = 0.5 + 0.85 * Math.sin(v * Math.PI) * (0.8 + 0.4 * Math.sin(v * 3 * Math.PI));
      valleyPts.push([pt.x, pt.y, press]);
    }

    // Color of the crevice depends on light zone
    if (uValley < -0.25) {
      brush.set("rotring", PAL.redDeep, 0.52);
      safeSpline(valleyPts, 0.45);
      // Warm shadow flank just to the right of the valley
      brush.set("2B", PAL.orangeBurnt, 0.38);
      brush.line(valleyPts[4][0] + 1.5, valleyPts[4][1], valleyPts[15][0] + 1.5, valleyPts[15][1]);
    } else if (uValley < 0.35) {
      brush.set("pen", PAL.claret, 0.58);
      safeSpline(valleyPts, 0.45);
      // Secondary dark ink accent in deepest pinched pockets
      brush.set("rotring", PAL.indigoInk, 0.42);
      safeSpline(valleyPts.slice(6, 15), 0.45);
    } else {
      brush.set("pen", PAL.indigoInk, 0.62);
      safeSpline(valleyPts, 0.45);
    }

    // B. Forking Y-creases & crow's-feet dimples branching off the main valley
    for (let f = 3; f < steps - 3; f += 4) {
      let vf = 0.04 + 0.93 * (f / steps);
      let ptStart = valleyPts[f];
      let dir = ((r + f) % 2 === 0) ? 1 : -1;
      let ptBranch = evalPersimmon(p, constrain(uValley + dir * 0.09, -0.96, 0.96), vf + 0.045);
      brush.set("rotring", uValley < 0.3 ? PAL.claret : PAL.indigoInk, 0.38);
      brush.line(ptStart[0], ptStart[1], ptBranch.x, ptBranch.y);
    }

    // C. Trace the raised Ridge Crest between valleys (catches raking cold sun + sugar bloom!)
    if (r < M) {
      let ridgePts = [];
      for (let s = 0; s <= steps; s++) {
        let v = 0.06 + 0.88 * (s / steps);
        let wiggle = 0.025 * Math.cos(v * 7.0 * Math.PI + r * 2.1 + p.seed);
        let pt = evalPersimmon(p, constrain(uRidge + wiggle, -0.95, 0.95), v);
        ridgePts.push([pt.x, pt.y]);
      }

      // Sunlit ridge glow on left and central ribs
      if (uRidge < 0.32) {
        brush.set("cpencil", uRidge < -0.15 ? PAL.goldSun : PAL.orangeVivid, 0.55);
        safeSpline(ridgePts, 0.45);
      }

      // ---------------------------------------------------------------------
      // 4. OBSESSIVE SUGAR BLOOM (Kona-fuki) Along Wrinkled Ridges & Pockets
      // Crystallized white/cream glucose frost clinging to the high ridges
      // and gathering in powdery patches across the shriveled skin
      // ---------------------------------------------------------------------
      for (let s = 1; s < steps; s++) {
        let v = 0.06 + 0.88 * (s / steps);
        // Sugar bloom is heaviest on upper shoulders (v~0.18-0.38) and waist ridges (v~0.48-0.78)
        let bloomDensity = noise(p.seed + r * 0.65, v * 4.5);
        if (bloomDensity > 0.34) {
          let rPt = ridgePts[s];
          let isLit = uRidge < 0.38;

          // Choose crystalline frost tone: warm chalk white, cool sky-lit frost, or shadow blue-frost
          let sugarCol = isLit
            ? ((s + r) % 3 === 0 ? PAL.sugarCool : PAL.sugarWhite)
            : PAL.sugarShadow;

          brush.set("cpencil", sugarCol, isLit ? random(0.42, 0.72) : random(0.32, 0.52));

          // Micro-hatched crystalline sugar strokes clinging across the ridge crest
          let span = map(bloomDensity, 0.34, 1.0, 2.2, 6.5);
          brush.line(rPt[0] - span * 0.6, rPt[1] - 1.2, rPt[0] + span * 0.4, rPt[1] + 1.2);

          if (bloomDensity > 0.52) {
            brush.set("2H", isLit ? PAL.paperBright : PAL.sugarCream, 0.48);
            brush.line(rPt[0] - 1.5, rPt[1] - 2.8, rPt[0] + 1.5, rPt[1] + 2.8);
            // Tiny powdery stipple clusters around the ridge
            let nx = rPt[0] + random(-4.5, 4.5);
            let ny = rPt[1] + random(-3.5, 3.5);
            brush.line(nx, ny, nx + 1.8, ny + 0.8);
          }
        }
      }
    }
  }

  // Additional concentrated sugar-bloom frost patches around the puckered crown & bottom apex
  brush.set("cpencil", PAL.sugarWhite, 0.52);
  for (let k = 0; k < 28; k++) {
    let u = random(-0.82, 0.45);
    let v = random() < 0.6 ? random(0.08, 0.32) : random(0.52, 0.86);
    let pt = evalPersimmon(p, u, v);
    brush.line(pt.x - 2.2, pt.y - 0.8, pt.x + 2.2, pt.y + 1.0);
  }

  // -------------------------------------------------------------------------
  // 5. Outer Keyblock Contour (Carved Woodblock Line with Variable Weight)
  // -------------------------------------------------------------------------
  // Sunlit left contour in deep burnt sienna/claret
  let leftContour = [];
  for (let s = 0; s <= 22; s++) {
    let v = s / 22;
    let pt = evalPersimmon(p, -1.0, v);
    leftContour.push([pt.x, pt.y, 0.55 + 0.4 * Math.sin(v * Math.PI)]);
  }
  brush.set("pen", PAL.siennaDeep, 0.68);
  safeSpline(leftContour, 0.45);

  // Shadowed right contour & pointed bottom apex in rich smoky indigo ink
  let rightContour = [];
  for (let s = 0; s <= 22; s++) {
    let v = s / 22;
    let pt = evalPersimmon(p, 1.0, v);
    rightContour.push([pt.x + p.regIndigo[0] * 0.35, pt.y + p.regIndigo[1] * 0.35, 0.65 + 0.55 * v]);
  }
  brush.set("pen", PAL.indigoInk, 0.82);
  safeSpline(rightContour, 0.45);

  // Bottom pointed tip puckers (where all longitudinal wrinkles converge)
  let tipPt = evalPersimmon(p, 0, 1.0);
  brush.set("rotring", PAL.indigoInk, 0.7);
  for (let u = -0.6; u <= 0.6; u += 0.3) {
    let pNear = evalPersimmon(p, u, 0.88);
    brush.line(pNear.x, pNear.y, tipPt.x, tipPt.y);
  }

  // -------------------------------------------------------------------------
  // 6. Hyperreal Dried Calyx (Heta) Details
  // -------------------------------------------------------------------------
  let cd = p.calyxData;
  // Crisp paper-white registration halo on top-left of calyx
  brush.set("chisel", PAL.paperBright, 0.85);
  safeSpline(cd.poly.slice(8, 17), 0.4);

  // Radial wood-fiber striations on the curled calyx lobes
  for (let a = 0; a < 360; a += 18) {
    let rad = (a % 90 < 45) ? cd.w * 0.95 : cd.w * 0.65;
    let ex = cd.cx + cos(a) * rad;
    let ey = cd.cy + sin(a) * (cd.h * 0.9);
    let isLitLobe = cos(a) < 0.2;
    brush.set("rotring", isLitLobe ? PAL.bambooLit : PAL.indigoInk, 0.45);
    brush.line(cd.cx + cos(a) * 4, cd.cy + sin(a) * 2, ex, ey);
  }

  // Curled dark keyblock outline of the 4-leaf calyx
  brush.set("pen", PAL.indigoInk, 0.78);
  drawPoly(cd.poly, 0.2);

  // Woody stem socket ring in center of calyx
  brush.set("rotring", PAL.bambooLit, 0.65);
  brush.circle(cd.cx - 1, cd.cy - 1, 5.5, 0.25);
  brush.set("pen", PAL.indigoInk, 0.75);
  brush.circle(cd.cx, cd.cy, 5.0, 0.2);
}

// ---------------------------------------------------------------------------
// STEP 8: Twisted Hemp Strings, Knots & Woody T-Stems (Tsuru)
// ---------------------------------------------------------------------------
function drawStringsAndKnots() {
  for (let s = 0; s < scene.strings.length; s++) {
    let st = scene.strings[s];
    let fruits = st.fruits;

    // Build segments of the hanging string between bamboo pole and each fruit's calyx
    let yPoints = [st.yTop];
    for (let k = 0; k < fruits.length; k++) {
      let cd = fruits[k].calyxData;
      yPoints.push(cd.cy - 4);
    }

    // Draw the vertical segments of twisted 2-ply hemp twine
    for (let seg = 0; seg < yPoints.length - 1; seg++) {
      let y1 = yPoints[seg];
      let y2 = yPoints[seg + 1];

      // If seg > 0, start below the upper persimmon's bottom tip unless string passes behind
      let startY = (seg === 0) ? y1 : evalPersimmon(fruits[seg - 1], 0, 0.98).y + 2;
      let endY = y2 - 10;

      if (endY > startY) {
        drawTwistedCord(st.xBase, startY, endY, st.swaySeed + seg * 19);
      }
    }

    // Top loop knot around the horizontal bamboo pole
    let py = poleYAt(st.xBase);
    drawPoleTieKnot(st.xBase, py);

    // At each persimmon: draw the woody T-stem (tsuru) and the tight hemp knot
    for (let k = 0; k < fruits.length; k++) {
      let p = fruits[k];
      let cd = p.calyxData;
      let stemX = cd.cx;
      let stemY = cd.cy - 1;

      // Woody stem rising from calyx socket + cross-bar of T-stem
      brush.set("chisel", PAL.paperBright, 0.8);
      brush.line(stemX - 4, stemY, stemX - 3, stemY - 19);

      brush.set("pen", PAL.umberDark, 1.25);
      brush.line(stemX, stemY, stemX + 1, stemY - 19);
      brush.set("cpencil", PAL.bambooLit, 0.85);
      brush.line(stemX - 1.5, stemY, stemX - 0.5, stemY - 18);

      // T-stem horizontal woody twig fragment at top of stem
      let tAngle = (k % 2 === 0) ? -16 : 14;
      let tx1 = stemX - cos(tAngle) * 11;
      let ty1 = (stemY - 17) - sin(tAngle) * 11;
      let tx2 = stemX + cos(tAngle) * 11;
      let ty2 = (stemY - 17) + sin(tAngle) * 11;
      brush.set("pen", PAL.umberDark, 1.15);
      brush.line(tx1, ty1, tx2, ty2);
      brush.set("cpencil", PAL.siennaSun, 0.7);
      brush.line(tx1, ty1 - 1.2, tx2, ty2 - 1.2);

      // Tightly wrapped hemp twine knot around the stem neck (3 horizontal coils)
      for (let c = 0; c < 3; c++) {
        let ky = stemY - 9 - c * 2.8;
        brush.set("chisel", PAL.paperBright, 0.75);
        brush.line(stemX - 6.5, ky - 0.5, stemX + 5.5, ky + 1.0);
        brush.set("rotring", PAL.umberDark, 0.75);
        brush.line(stemX - 6.0, ky + 1.0, stemX + 6.0, ky + 2.2);
      }

      // Frayed hemp fiber whiskers catching the cold side-light
      brush.set("2H", PAL.paperBright, 0.42);
      brush.line(stemX - 6, stemY - 12, stemX - 14, stemY - 16);
      brush.line(stemX + 5, stemY - 11, stemX + 13, stemY - 8);
    }

    // Short tail of twine hanging below the lowest persimmon on the string
    let lastFruit = fruits[fruits.length - 1];
    let botTip = evalPersimmon(lastFruit, 0, 1.0);
    drawTwistedCord(botTip.x, botTip.y + 2, botTip.y + 42, st.swaySeed + 99);
    // Frayed tassel at bottom end of string
    brush.set("rotring", PAL.umberDark, 0.45);
    brush.line(botTip.x, botTip.y + 42, botTip.x - 5, botTip.y + 52);
    brush.line(botTip.x, botTip.y + 42, botTip.x + 4, botTip.y + 54);
    brush.set("2H", PAL.paperBright, 0.45);
    brush.line(botTip.x - 1, botTip.y + 42, botTip.x - 7, botTip.y + 50);
  }
}

function drawTwistedCord(xBase, yStart, yEnd, seed) {
  // Paper-white registration gap along sunlit left edge of twine
  brush.set("chisel", PAL.paperBright, 0.85);
  let leftPts = [];
  let rightPts = [];
  for (let y = yStart; y <= yEnd; y += 8) {
    let sx = xBase + 3.5 * Math.sin(y * 0.012 + seed);
    leftPts.push([sx - 2.2, y]);
    rightPts.push([sx + 2.2, y]);
  }
  safeSpline(leftPts, 0.35);

  // Smoky indigo shadow line along right edge of twine
  brush.set("rotring", PAL.indigoDeep, 0.72);
  safeSpline(rightPts, 0.35);

  // Individual diagonal 2-ply hemp twists down the cord
  for (let y = yStart; y < yEnd - 4; y += 5.5) {
    let sx = xBase + 3.5 * Math.sin(y * 0.012 + seed);
    brush.set("cpencil", PAL.bambooLit, 0.65);
    brush.line(sx - 1.8, y, sx + 1.8, y + 3.5);
    brush.set("rotring", PAL.umberDark, 0.52);
    brush.line(sx - 1.8, y + 2.8, sx + 2.0, y + 6.0);
  }
}

function drawPoleTieKnot(x, py) {
  // Coiled hemp loop over the bamboo pole
  for (let dx = -4; dx <= 4; dx += 4) {
    brush.set("chisel", PAL.paperBright, 0.75);
    brush.line(x + dx - 1.5, py - 12, x + dx - 0.5, py + 12);
    brush.set("pen", PAL.umberDark, 0.75);
    brush.line(x + dx, py - 12, x + dx + 1, py + 12);
  }
}

