function safeLine(x1, y1, x2, y2) {
  let dx = x2 - x1;
  let dy = y2 - y1;
  if (dx * dx + dy * dy < 0.09) {
    x2 = x1 + 0.35;
    y2 = y1 + 0.2;
  }
  brush.line(x1, y1, x2, y2);
}

class SpatialGrid {
  constructor(w, h, cellSize) {
    this.cellSize = cellSize;
    this.cols = Math.ceil(w / cellSize) + 2;
    this.rows = Math.ceil(h / cellSize) + 2;
    this.cells = new Array(this.cols * this.rows);
    for (let i = 0; i < this.cells.length; i++) this.cells[i] = [];
  }

  _idx(x, y) {
    let c = Math.max(0, Math.min(this.cols - 1, Math.floor(x / this.cellSize)));
    let r = Math.max(0, Math.min(this.rows - 1, Math.floor(y / this.cellSize)));
    return r * this.cols + c;
  }

  insert(grain) {
    this.cells[this._idx(grain.x, grain.y)].push(grain);
  }

  query(x, y, radius) {
    let c0 = Math.max(0, Math.floor((x - radius) / this.cellSize));
    let c1 = Math.min(this.cols - 1, Math.floor((x + radius) / this.cellSize));
    let r0 = Math.max(0, Math.floor((y - radius) / this.cellSize));
    let r1 = Math.min(this.rows - 1, Math.floor((y + radius) / this.cellSize));
    let res = [];
    for (let r = r0; r <= r1; r++) {
      let rowOffset = r * this.cols;
      for (let c = c0; c <= c1; c++) {
        let arr = this.cells[rowOffset + c];
        for (let i = 0; i < arr.length; i++) res.push(arr[i]);
      }
    }
    return res;
  }
}

