// =============================================================================
// PHASE 2: DRY-BRUSH LIPAN PLASTER ARCS & GRANULATION
// =============================================================================
function drawFloorDryBrushAndGranulation() {
  // Traditional cow-dung and red-mud floors (lipan) are smeared by hand in overlapping sweeping arcs
  let sweeps = [];
  for (let i = 0; i < 48; i++) {
    let cx = random(-80, 1280);
    let cy = random(-80, 1280);
    let rad = random(140, 340);
    let startA = random(0, Math.PI * 2);
    let spanA = random(0.65, 1.35);
    let dir = random() < 0.5 ? 1 : -1;
    let colIdx = i % 5;
    sweeps.push({ cx, cy, rad, startA, spanA, dir, colIdx });
  }

  let sweepPalette = [
    { brush: "mud_scumble", col: "#120703", w: 1.1 },
    { brush: "mud_scumble", col: "#4F210F", w: 1.0 },
    { brush: "mud_drybrush", col: "#692D15", w: 0.95 },
    { brush: "mud_drybrush", col: "#261108", w: 1.0 },
    { brush: "mud_drybrush", col: "#5E341E", w: 0.85 }
  ];

  for (let c = 0; c < sweepPalette.length; c++) {
    let st = sweepPalette[c];
    brush.set(st.brush, st.col, st.w);
    for (let s of sweeps) {
      if (s.colIdx !== c) continue;
      let strands = 9;
      for (let k = 0; k < strands; k++) {
        let r = s.rad + (k - strands * 0.5) * 8.5 + random(-2, 2);
        let a0 = s.startA + random(-0.08, 0.08);
        let a1 = a0 + s.spanA * s.dir;
        let steps = 5;
        let px = s.cx + Math.cos(a0) * r;
        let py = s.cy + Math.sin(a0) * r;
        for (let step = 1; step <= steps; step++) {
          let t = step / steps;
          let ang = a0 + (a1 - a0) * t;
          let rr = r + Math.sin(t * Math.PI) * 6;
          let nx = s.cx + Math.cos(ang) * rr;
          let ny = s.cy + Math.sin(ang) * rr;
          safeLine(px, py, nx, ny);
          px = nx;
          py = ny;
        }
      }
    }
  }

  // Watercolour Pigment Granulation & Mineral Chaff / Grit
  let granColors = [
    { col: "#0D0502", count: 140, w: 1.05 },
    { col: "#36160A", count: 130, w: 0.95 },
    { col: "#632A13", count: 110, w: 0.9 },
    { col: "#7A4326", count: 75, w: 0.75 }
  ];
  for (let g of granColors) {
    brush.set("granulation_spray", g.col, g.w);
    for (let i = 0; i < g.count; i++) {
      let x = random(20, 1180);
      let y = random(20, 1180);
      let len = random(25, 85);
      let ang = random(0, Math.PI * 2);
      safeLine(x, y, x + Math.cos(ang) * len, y + Math.sin(ang) * len);
    }
  }

  // Fine organic chaff fibres embedded in the dried dung-mud plaster
  brush.set("2H", "#4A2715", 0.55);
  for (let i = 0; i < 220; i++) {
    let x = random(15, 1185);
    let y = random(15, 1185);
    let len = random(5, 14);
    let ang = random(0, Math.PI * 2);
    safeLine(x, y, x + Math.cos(ang) * len, y + Math.sin(ang) * len);
  }
  brush.set("2H", "#7D4C30", 0.45);
  for (let i = 0; i < 140; i++) {
    let x = random(15, 1185);
    let y = random(15, 1185);
    let len = random(4, 10);
    let ang = random(0, Math.PI * 2);
    safeLine(x, y, x + Math.cos(ang) * len, y + Math.sin(ang) * len);
  }
}

// =============================================================================
// PHASE 3: HAIRLINE SHRINKAGE CRACKS
// =============================================================================
function generateAndDrawCracks() {
  let primaryCracks = [];
  let secondaryCracks = [];

  // Seed primary desiccation fractures across the floor
  let seeds = [
    { x: 80, y: 210, a: 0.25, steps: 55 },
    { x: 310, y: 40, a: 1.35, steps: 60 },
    { x: 880, y: 50, a: 1.75, steps: 58 },
    { x: 1140, y: 310, a: 2.85, steps: 55 },
    { x: 1130, y: 860, a: 3.45, steps: 62 },
    { x: 820, y: 1150, a: -1.45, steps: 55 },
    { x: 260, y: 1140, a: -1.1, steps: 58 },
    { x: 50, y: 780, a: -0.2, steps: 56 },
    { x: 460, y: 480, a: 0.65, steps: 42 },
    { x: 740, y: 520, a: 2.35, steps: 44 },
    { x: 580, y: 760, a: -0.75, steps: 40 },
    { x: 240, y: 520, a: 0.9, steps: 38 },
    { x: 940, y: 660, a: 2.6, steps: 38 }
  ];

  function traceCrack(startX, startY, startAngle, maxSteps, stepLen, isPrimary) {
    let pts = [{ x: startX, y: startY }];
    let x = startX;
    let y = startY;
    let a = startAngle;
    for (let i = 0; i < maxSteps; i++) {
      let n = noise(x * 0.008, y * 0.008, i * 0.05);
      a += (n - 0.5) * 0.52 + random(-0.18, 0.18);
      let sl = stepLen * random(0.75, 1.25);
      x += Math.cos(a) * sl;
      y += Math.sin(a) * sl;
      if (x < 10 || x > 1190 || y < 10 || y > 1190) break;
      pts.push({ x, y });

      // Spawn secondary branching hairline cracks at ~95-115 degree mud-crack angles
      if (isPrimary && i > 4 && i < maxSteps - 5 && random() < 0.14) {
        let branchSign = random() < 0.5 ? 1 : -1;
        let branchAngle = a + branchSign * random(1.25, 1.85);
        secondaryCracks.push(traceCrack(x, y, branchAngle, Math.floor(random(10, 24)), stepLen * 0.72, false));
      } else if (!isPrimary && i > 3 && random() < 0.09) {
        let branchSign = random() < 0.5 ? 1 : -1;
        let branchAngle = a + branchSign * random(1.1, 1.7);
        secondaryCracks.push(traceCrack(x, y, branchAngle, Math.floor(random(5, 11)), stepLen * 0.6, false));
      }
    }
    return pts;
  }

  for (let s of seeds) {
    primaryCracks.push(traceCrack(s.x, s.y, s.a, s.steps, 14, true));
  }

  // Pass 1: Warm clay/sienna curled lip highlight on the lit side (+1.1, +1.3 px) of each crack
  brush.set("crack_lip", "#7A4326", 0.85);
  for (let pts of primaryCracks) {
    for (let i = 0; i < pts.length - 1; i++) {
      let taper = Math.sin((i / (pts.length - 1)) * Math.PI);
      if (taper > 0.2) {
        safeLine(pts[i].x + 1.1, pts[i].y + 1.3, pts[i + 1].x + 1.1, pts[i + 1].y + 1.3);
      }
    }
  }
  brush.set("crack_lip", "#63341C", 0.6);
  for (let pts of secondaryCracks) {
    for (let i = 0; i < pts.length - 1; i++) {
      safeLine(pts[i].x + 0.85, pts[i].y + 1.0, pts[i + 1].x + 0.85, pts[i + 1].y + 1.0);
    }
  }

  // Pass 2: Soft dark umber bevel along primary cracks
  brush.set("crack_lip", "#170A04", 1.15);
  for (let pts of primaryCracks) {
    for (let i = 0; i < pts.length - 1; i++) {
      safeLine(pts[i].x - 0.3, pts[i].y - 0.3, pts[i + 1].x - 0.3, pts[i + 1].y - 0.3);
    }
  }

  // Pass 3: Razor-sharp deepest umber-black fissure core
  brush.set("crack_fissure", "#070301", 0.95);
  for (let pts of primaryCracks) {
    for (let i = 0; i < pts.length - 1; i++) {
      safeLine(pts[i].x, pts[i].y, pts[i + 1].x, pts[i + 1].y);
    }
  }
  brush.set("crack_fissure", "#0B0502", 0.62);
  for (let pts of secondaryCracks) {
    for (let i = 0; i < pts.length - 1; i++) {
      safeLine(pts[i].x, pts[i].y, pts[i + 1].x, pts[i + 1].y);
    }
  }

  return primaryCracks.concat(secondaryCracks);
}

// =============================================================================
// PHASE 4: GENERATE WARLI SPIRAL RING & CLUSTERED TRIANGULAR FIGURE PILES
// =============================================================================
function generateRiceGrains(cracks) {
  let grid = new SpatialGrid(1200, 1200, 6.5);
  let grains = [];
  let crumbs = [];

  // Helper to place a single rice grain with physical collision/stacking awareness
  function tryAddGrain(x, y, theta, opts = {}) {
    if (x < 28 || x > 1172 || y < 28 || y > 1172) return false;

    let maxZ = opts.maxZ !== undefined ? opts.maxZ : 0;
    let minSep = opts.minSep !== undefined ? opts.minSep : 4.1;
    let isBroken = opts.isBroken || false;

    let nearby = grid.query(x, y, 9.5);
    let z = 0;
    let nudgedX = x;
    let nudgedY = y;
    let nudgedTheta = theta;

    for (let i = 0; i < nearby.length; i++) {
      let other = nearby[i];
      let dx = nudgedX - other.x;
      let dy = nudgedY - other.y;
      let d2 = dx * dx + dy * dy;

      if (d2 < minSep * minSep) {
        if (maxZ > 0 && other.z < maxZ && random() < 0.72) {
          // Climb on top of the lower grain inside clustered triangular piles
          z = Math.min(maxZ, Math.max(z, other.z + 0.65));
        } else {
          // Gently nudge side-by-side on the floor or reject if overcrowded
          let d = Math.sqrt(d2) || 0.1;
          if (d < minSep * 0.58) return false;
          nudgedX += (dx / d) * (minSep - d) * 0.65;
          nudgedY += (dy / d) * (minSep - d) * 0.65;
          // Subtle nematic alignment with neighbor grain
          let diffA = Math.atan2(Math.sin(other.theta - nudgedTheta), Math.cos(other.theta - nudgedTheta));
          nudgedTheta += diffA * 0.22;
        }
      }
    }

    // Re-verify floor collision if z == 0
    if (z === 0) {
      for (let i = 0; i < nearby.length; i++) {
        let other = nearby[i];
        if (other.z === 0) {
          let dx = nudgedX - other.x;
          let dy = nudgedY - other.y;
          if (dx * dx + dy * dy < (minSep * 0.78) * (minSep * 0.78)) return false;
        }
      }
    }

    let len = isBroken ? random(6.5, 9.2) : random(11.6, 15.2);
    let wScale = isBroken ? random(0.82, 0.96) : random(0.88, 1.12);
    let notchSide = random() < 0.5 ? 1 : -1;
    let shadeVar = Math.floor(random(3));

    let g = {
      x: nudgedX,
      y: nudgedY,
      theta: nudgedTheta,
      len,
      wScale,
      z: z + (opts.baseZ || 0),
      isBroken,
      notchSide,
      shadeVar
    };
    grid.insert(g);
    grains.push(g);
    return true;
  }

  // Helper to populate a triangular figure pile (Warli torso or pelvis triangle)
  function addTrianglePile(A, B, C, densityCount, pileCohesion) {
    let cx = (A.x + B.x + C.x) / 3;
    let cy = (A.y + B.y + C.y) / 3;
    let edges = [
      { p0: A, p1: B, ang: Math.atan2(B.y - A.y, B.x - A.x) },
      { p0: B, p1: C, ang: Math.atan2(C.y - B.y, C.x - B.x) },
      { p0: C, p1: A, ang: Math.atan2(A.y - C.y, A.x - C.x) }
    ];

    // 1. Crisp contour grains defining the triangular edges (with natural loose gaps)
    for (let e of edges) {
      let edgeLen = Math.hypot(e.p1.x - e.p0.x, e.p1.y - e.p0.y);
      let steps = Math.floor(edgeLen / 5.2);
      for (let i = 0; i <= steps; i++) {
        if (random() > pileCohesion * 0.92) continue;
        let t = i / Math.max(1, steps);
        let px = e.p0.x + (e.p1.x - e.p0.x) * t + random(-2.2, 2.2);
        let py = e.p0.y + (e.p1.y - e.p0.y) * t + random(-2.2, 2.2);
        // Pull slightly inward toward triangle centroid
        px = px * 0.88 + cx * 0.12;
        py = py * 0.88 + cy * 0.12;
        let ang = e.ang + random(-0.38, 0.38) + (random() < 0.5 ? 0 : Math.PI);
        tryAddGrain(px, py, ang, { maxZ: 0.7, minSep: 3.8 });
      }
    }

    // 2. Interior mounded grains (barycentric sampling concentrated toward center of pile)
    for (let i = 0; i < densityCount; i++) {
      let u = random();
      let v = random();
      if (u + v > 1) {
        u = 1 - u;
        v = 1 - v;
      }
      let w = 1 - u - v;
      // Bias slightly toward center for a natural 3D mounded pinch of rice
      let bias = random(0.0, 0.35);
      u = u * (1 - bias) + (1 / 3) * bias;
      v = v * (1 - bias) + (1 / 3) * bias;
      w = 1 - u - v;

      let px = u * A.x + v * B.x + w * C.x + random(-2.5, 2.5);
      let py = u * A.y + v * B.y + w * C.y + random(-2.5, 2.5);

      // Distance from centroid determines how high grains can mound (z up to 1.8 in center)
      let distFromCenter = Math.hypot(px - cx, py - cy);
      let maxZ = distFromCenter < 10 ? 1.8 : (distFromCenter < 18 ? 1.1 : 0.4);

      // Align partially with nearest edge or radial axis
      let baseAng = edges[i % 3].ang + random(-0.65, 0.65);
      if (random() < 0.5) baseAng += Math.PI;
      tryAddGrain(px, py, baseAng, { maxZ: maxZ * pileCohesion, minSep: 3.6 });
    }

    // 3. Halo of grains that rolled off the triangular pile onto the floor
    let haloCount = Math.floor(densityCount * 0.32);
    for (let i = 0; i < haloCount; i++) {
      let e = edges[i % 3];
      let t = random(-0.1, 1.1);
      let bx = e.p0.x + (e.p1.x - e.p0.x) * t;
      let by = e.p0.y + (e.p1.y - e.p0.y) * t;
      let outX = bx - cx;
      let outY = by - cy;
      let outLen = Math.hypot(outX, outY) || 1;
      let rollDist = random(3, 18) * (2.0 - pileCohesion);
      let px = bx + (outX / outLen) * rollDist + random(-4, 4);
      let py = by + (outY / outLen) * rollDist + random(-4, 4);
      let ang = Math.atan2(outY, outX) + random(-0.9, 0.9);
      tryAddGrain(px, py, ang, { maxZ: 0, minSep: 4.3, isBroken: random() < 0.12 });
    }
  }

  // Helper to build a complete Warli Figure out of spilled rice grains
  function buildWarliFigure(fx, fy, radAngle, scale, cohesion, hasBun, isTarpaPlayer = false) {
    let Rx = Math.cos(radAngle);
    let Ry = Math.sin(radAngle);
    let Tx = -Ry;
    let Ty = Rx;

    function toWorld(t, r) {
      return {
        x: fx + Tx * t * scale + Rx * r * scale,
        y: fy + Ty * t * scale + Ry * r * scale
      };
    }

    // Upper Torso Inverted Triangle (Waist apex -> Left & Right Shoulders)
    let A1 = toWorld(0, 1.5);
    let B1 = toWorld(-23.5, 36.5);
    let C1 = toWorld(23.5, 36.5);
    addTrianglePile(A1, B1, C1, Math.floor(92 * scale * cohesion), cohesion);

    // Lower Pelvis Upright Triangle (Waist apex -> Left & Right Hips)
    let A2 = toWorld(0, -1.5);
    let B2 = toWorld(-21.5, -35.5);
    let C2 = toWorld(21.5, -35.5);
    addTrianglePile(A2, B2, C2, Math.floor(86 * scale * cohesion), cohesion);

    // Waist pinch bridge (3-5 grains bridging the apexes)
    for (let i = 0; i < 6; i++) {
      let p = toWorld(random(-3.5, 3.5), random(-4, 4));
      tryAddGrain(p.x, p.y, radAngle + random(-0.4, 0.4), { maxZ: 1.2, minSep: 3.6 });
    }

    // Head Cluster (Circular mound of rice above the shoulders)
    let headCenter = toWorld(random(-1.5, 1.5), 52.5);
    let headCount = Math.floor(30 * scale);
    for (let i = 0; i < headCount; i++) {
      let r = Math.pow(random(), 0.65) * 10.5 * scale;
      let a = random(0, Math.PI * 2);
      let px = headCenter.x + Math.cos(a) * r;
      let py = headCenter.y + Math.sin(a) * r;
      tryAddGrain(px, py, a + Math.PI * 0.5 + random(-0.5, 0.5), {
        maxZ: r < 5.5 ? 1.3 : 0.4,
        minSep: 3.6
      });
    }

    // Neck trickle (2-3 grains)
    for (let i = 0; i < 3; i++) {
      let p = toWorld(random(-2, 2), 39 + i * 2.5);
      tryAddGrain(p.x, p.y, radAngle + random(-0.3, 0.3), { maxZ: 0.4, minSep: 3.8 });
    }

    // Optional Warli woman's hair bun (ambada) cluster
    if (hasBun) {
      let bunCenter = toWorld(-12.5, 54.0);
      for (let i = 0; i < 7; i++) {
        let r = random(0, 4.5) * scale;
        let a = random(0, Math.PI * 2);
        tryAddGrain(bunCenter.x + Math.cos(a) * r, bunCenter.y + Math.sin(a) * r, a + random(-0.4, 0.4), {
          maxZ: 0.6,
          minSep: 3.6
        });
      }
    }

    // Rhythmic Stepping Legs (bent at the knee in classic Warli dance rhythm)
    let legJoints = [
      [toWorld(-11, -35.5), toWorld(-16, -49), toWorld(-11, -63)],
      [toWorld(11, -35.5), toWorld(7, -49), toWorld(13, -63)]
    ];
    for (let leg of legJoints) {
      for (let seg = 0; seg < 2; seg++) {
        let p0 = leg[seg];
        let p1 = leg[seg + 1];
        let segAng = Math.atan2(p1.y - p0.y, p1.x - p0.x);
        let steps = 4;
        for (let s = 0; s <= steps; s++) {
          let t = s / steps;
          let px = p0.x + (p1.x - p0.x) * t + random(-2.0, 2.0);
          let py = p0.y + (p1.y - p0.y) * t + random(-2.0, 2.0);
          tryAddGrain(px, py, segAng + random(-0.32, 0.32), { maxZ: 0.3, minSep: 3.8 });
          if (random() < 0.45) {
            tryAddGrain(px + random(-3.5, 3.5), py + random(-3.5, 3.5), segAng + random(-0.5, 0.5), { maxZ: 0, minSep: 4.1 });
          }
        }
      }
    }

    // If this is the central Tarpa musician, add the curved Tarpa horn & arms holding it
    if (isTarpaPlayer) {
      let hornPts = [
        toWorld(6, 46),
        toWorld(22, 42),
        toWorld(38, 34),
        toWorld(54, 22),
        toWorld(68, 6)
      ];
      for (let i = 0; i < hornPts.length - 1; i++) {
        let p0 = hornPts[i];
        let p1 = hornPts[i + 1];
        let hAng = Math.atan2(p1.y - p0.y, p1.x - p0.x);
        let steps = 5 + i * 2;
        for (let s = 0; s < steps; s++) {
          let t = s / steps;
          let spread = (1.5 + i * 1.8) * scale;
          let px = p0.x + (p1.x - p0.x) * t + random(-spread, spread);
          let py = p0.y + (p1.y - p0.y) * t + random(-spread, spread);
          tryAddGrain(px, py, hAng + random(-0.35, 0.35), { maxZ: 0.8, minSep: 3.6 });
        }
      }
      // Arms reaching from shoulders to the Tarpa horn
      let armL = [B1, toWorld(-4, 38), hornPts[1]];
      let armR = [C1, toWorld(28, 32), hornPts[2]];
      for (let arm of [armL, armR]) {
        for (let i = 0; i < 2; i++) {
          let p0 = arm[i], p1 = arm[i + 1];
          let aAng = Math.atan2(p1.y - p0.y, p1.x - p0.x);
          for (let s = 0; s <= 4; s++) {
            let t = s / 4;
            tryAddGrain(
              p0.x + (p1.x - p0.x) * t + random(-2, 2),
              p0.y + (p1.y - p0.y) * t + random(-2, 2),
              aAng + random(-0.3, 0.3),
              { maxZ: 0.4, minSep: 3.8 }
            );
          }
        }
      }
    }

    return { leftShoulder: B1, rightShoulder: C1 };
  }

  // -------------------------------------------------------------------------
  // 1. CENTRAL TARPA PLAYER FIGURE IN THE EYE OF THE SPIRAL
  // -------------------------------------------------------------------------
  let cx = 600;
  let cy = 605;
  buildWarliFigure(cx - 14, cy + 8, -Math.PI * 0.38, 1.04, 0.95, false, true);

  // Small ritual central hearth/offering pinch of rice near the Tarpa player's feet
  for (let i = 0; i < 28; i++) {
    let r = random(0, 18);
    let a = random(0, Math.PI * 2);
    tryAddGrain(cx + 12 + Math.cos(a) * r, cy - 32 + Math.sin(a) * r, a + random(-0.6, 0.6), {
      maxZ: 0.6,
      minSep: 4.0
    });
  }

  // -------------------------------------------------------------------------
  // 2. SPIRAL RING CHOREOGRAPHY (13 DANCER STATIONS ALONG 1.68 TURNS)
  // -------------------------------------------------------------------------
  let rStart = 156;
  let rEnd = 478;
  let thetaStart = -Math.PI * 0.42;
  let totalTurns = 1.68;
  let deltaTheta = totalTurns * Math.PI * 2;

  function spiralPoint(u) {
    let th = thetaStart + u * deltaTheta;
    let r = rStart + Math.pow(u, 0.93) * (rEnd - rStart) + 6.5 * Math.sin(u * 18.0) + 4.0 * Math.cos(u * 29.0);
    return {
      x: cx + Math.cos(th) * r,
      y: cy + Math.sin(th) * r,
      r,
      th
    };
  }

  let numDancers = 13;
  let dancerNodes = [];
  for (let k = 0; k < numDancers; k++) {
    // Equal arc-length spacing along the Archimedean spiral
    let w = 0.045 + (k / (numDancers - 1)) * 0.91;
    let u = (Math.sqrt(rStart * rStart + w * (rEnd * rEnd - rStart * rStart)) - rStart) / (rEnd - rStart);
    let sp = spiralPoint(u);
    let sway = Math.sin(k * 1.85) * 0.11;
    let radAngle = sp.th + sway;
    let sc = map(sp.r, rStart, rEnd, 0.80, 1.06);
    // Alternate cohesion slightly so some figures are crisp mounds and a few are looser spills
    let cohesion = (k % 3 === 1) ? 0.82 : 0.96;
    let shoulders = buildWarliFigure(sp.x, sp.y, radAngle, sc, cohesion, k % 2 === 1, false);
    dancerNodes.push({ u, sp, sc, shoulders });
  }

  // -------------------------------------------------------------------------
  // 3. LINKED ARMS BETWEEN ADJACENT DANCERS ALONG THE SPIRAL
  // -------------------------------------------------------------------------
  for (let k = 0; k < dancerNodes.length - 1; k++) {
    let d0 = dancerNodes[k];
    let d1 = dancerNodes[k + 1];
    let pStart = d0.shoulders.leftShoulder;
    let pEnd = d1.shoulders.rightShoulder;

    // Midpoint dipped slightly inward along the spiral curve for the joined hands
    let uMid = (d0.u + d1.u) * 0.5;
    let spMid = spiralPoint(uMid);
    let handR = spMid.r + 14 * ((d0.sc + d1.sc) * 0.5);
    let pMid = {
      x: cx + Math.cos(spMid.th) * handR,
      y: cy + Math.sin(spMid.th) * handR
    };

    let steps = 22;
    for (let s = 0; s <= steps; s++) {
      let t = s / steps;
      let mt = 1 - t;
      let qx = mt * mt * pStart.x + 2 * mt * t * pMid.x + t * t * pEnd.x;
      let qy = mt * mt * pStart.y + 2 * mt * t * pMid.y + t * t * pEnd.y;
      let tx = 2 * mt * (pMid.x - pStart.x) + 2 * t * (pEnd.x - pMid.x);
      let ty = 2 * mt * (pMid.y - pStart.y) + 2 * t * (pEnd.y - pMid.y);
      let tang = Math.atan2(ty, tx);

      // Main linked-arm grain stream
      tryAddGrain(qx + random(-2.2, 2.2), qy + random(-2.2, 2.2), tang + random(-0.28, 0.28), {
        maxZ: 0.5,
        minSep: 3.8
      });
      // Companion grains along the arm & joined-hand cluster at t ~ 0.5
      let extraProb = Math.abs(t - 0.5) < 0.16 ? 0.85 : 0.42;
      if (random() < extraProb) {
        tryAddGrain(qx + random(-5.5, 5.5), qy + random(-5.5, 5.5), tang + random(-0.45, 0.45), {
          maxZ: 0.3,
          minSep: 4.0
        });
      }
    }
  }

  // -------------------------------------------------------------------------
  // 4. LOOSE SPIRAL RING STREAM & KINETIC SPILL TRAILS
  // -------------------------------------------------------------------------
  let spiralSamples = 1350;
  for (let i = 0; i < spiralSamples; i++) {
    let u = random(-0.04, 1.05);
    let sp = spiralPoint(Math.max(0, Math.min(1, u)));
    let th = thetaStart + u * deltaTheta;
    let r = rStart + u * (rEnd - rStart);
    let tang = th + Math.PI * 0.5;

    // Gaussian-like radial spread across the spiral band
    let bandSpread = (random(-1, 1) + random(-1, 1) + random(-1, 1)) * 24;
    let px = cx + Math.cos(th) * (r + bandSpread) + random(-6, 6);
    let py = cy + Math.sin(th) * (r + bandSpread) + random(-6, 6);

    tryAddGrain(px, py, tang + random(-0.75, 0.75), {
      maxZ: Math.abs(bandSpread) < 10 ? 0.5 : 0,
      minSep: 4.3,
      isBroken: random() < 0.11
    });
  }

  // Radial skitter/splash trails where grains bounced outward across the hard floor
  for (let tIdx = 0; tIdx < 18; tIdx++) {
    let u = random(0.05, 0.98);
    let sp = spiralPoint(u);
    let outSign = (u > 0.55 || random() < 0.65) ? 1 : -1;
    let skitterAngle = sp.th + outSign * random(0.25, 0.85);
    let numSkitter = Math.floor(random(8, 16));
    let sx = sp.x + Math.cos(sp.th) * outSign * 28;
    let sy = sp.y + Math.sin(sp.th) * outSign * 28;
    for (let k = 0; k < numSkitter; k++) {
      let stepD = 8 + k * 2.2 + random(-2, 3);
      sx += Math.cos(skitterAngle) * stepD;
      sy += Math.sin(skitterAngle) * stepD;
      skitterAngle += random(-0.12, 0.12);
      tryAddGrain(sx, sy, skitterAngle + random(-0.5, 0.5), {
        maxZ: 0,
        minSep: 4.5,
        isBroken: random() < 0.18
      });
    }
  }

  // Crack-trapped grains nestled along the floor fissures
  for (let cPts of cracks) {
    if (cPts.length < 4) continue;
    for (let i = 1; i < cPts.length - 1; i++) {
      if (random() < 0.18) {
        let p0 = cPts[i];
        let p1 = cPts[i + 1];
        let distFromCenter = Math.hypot(p0.x - cx, p0.y - cy);
        if (distFromCenter < 540 && random() < 0.65) {
          let cAng = Math.atan2(p1.y - p0.y, p1.x - p0.x);
          tryAddGrain(p0.x + random(-2.5, 2.5), p0.y + random(-2.5, 2.5), cAng + random(-0.22, 0.22), {
            maxZ: 0,
            minSep: 4.4,
            isBroken: random() < 0.28
          });
        }
      }
    }
  }

  // Isolated stray grains scattered across the floor for hyperreal observational tension
  for (let i = 0; i < 380; i++) {
    let ang = random(0, Math.PI * 2);
    let r = random(45, 560);
    let px = cx + Math.cos(ang) * r;
    let py = cy + Math.sin(ang) * r;
    tryAddGrain(px, py, random(0, Math.PI * 2), {
      maxZ: 0,
      minSep: 5.0,
      isBroken: random() < 0.16
    });
  }

  // Tiny chalky rice-starch crumbs & husk specks around the spills
  for (let i = 0; i < 340; i++) {
    let refG = grains[Math.floor(random(grains.length))];
    let cxSpeck = refG.x + random(-24, 24);
    let cySpeck = refG.y + random(-24, 24);
    if (cxSpeck > 25 && cxSpeck < 1175 && cySpeck > 25 && cySpeck < 1175) {
      crumbs.push({
        x: cxSpeck,
        y: cySpeck,
        len: random(1.2, 2.8),
        ang: random(0, Math.PI * 2)
      });
    }
  }

  return { grains, crumbs };
}

// =============================================================================
// PHASE 5: RENDER EVERY HYPERREAL RICE GRAIN BY HEIGHT TIER & ANATOMICAL PASS
// =============================================================================
function renderRiceGrains(grains, crumbs) {
  // Light source from top-left (-0.74, -0.67); shadows fall toward bottom-right (+0.74, +0.67)
  const lightX = -0.74;
  const lightY = -0.67;

  // Precompute exact anatomical endpoints for every grain
  let tiers = [[], [], []];
  for (let i = 0; i < grains.length; i++) {
    let g = grains[i];
    let ux = Math.cos(g.theta);
    let uy = Math.sin(g.theta);
    // Normal vector oriented so (nx, ny) ALWAYS points toward the top-left raking light
    let nx = -uy;
    let ny = ux;
    if (nx * lightX + ny * lightY < 0) {
      nx = -nx;
      ny = -ny;
    }

    let halfL = g.len * 0.5;
    // Tail (base) and Tip (translucent endosperm end)
    g.x0 = g.x - ux * halfL;
    g.y0 = g.y - uy * halfL;
    g.x1 = g.x + ux * halfL;
    g.y1 = g.y + uy * halfL;

    // Opaque starchy belly ends at ~76% of the grain length, leaving the tip 24% translucent!
    let opaqueFrac = g.isBroken ? 0.68 : 0.76;
    let notchShift = g.notchSide * 0.32 * g.wScale;
    g.xOpaque = g.x0 + (g.x1 - g.x0) * opaqueFrac + nx * notchShift;
    g.yOpaque = g.y0 + (g.y1 - g.y0) * opaqueFrac + ny * notchShift;

    g.ux = ux;
    g.uy = uy;
    g.nx = nx;
    g.ny = ny;

    let tIdx = g.z < 0.35 ? 0 : (g.z < 1.05 ? 1 : 2);
    tiers[tIdx].push(g);
  }

  // First: Render tiny broken starch crumbs on the floor
  brush.set("rice_shadow_core", "#0D0502", 0.55);
  for (let c of crumbs) {
    safeLine(
      c.x + 1.0, c.y + 1.2,
      c.x + 1.0 + Math.cos(c.ang) * c.len, c.y + 1.2 + Math.sin(c.ang) * c.len
    );
  }
  brush.set("rice_chalk_peak", "#EDE4D4", 0.65);
  for (let c of crumbs) {
    safeLine(
      c.x, c.y,
      c.x + Math.cos(c.ang) * c.len, c.y + Math.sin(c.ang) * c.len
    );
  }

  // Render grains tier by tier (bottom of pile -> middle -> top of pile)
  for (let t = 0; t < tiers.length; t++) {
    let list = tiers[t];
    if (list.length === 0) continue;

    // Shadow offset increases slightly with stack height z
    let sOffX = 1.85 + t * 0.65;
    let sOffY = 2.25 + t * 0.75;

    // PASS 1: Soft Dark Umber Cast Shadow
    brush.set("rice_shadow_soft", "#0E0502", 1.0);
    for (let i = 0; i < list.length; i++) {
      let g = list[i];
      safeLine(
        g.x0 + sOffX, g.y0 + sOffY,
        g.x1 + sOffX, g.y1 + sOffY
      );
    }

    // PASS 2: Crisp Ambient Occlusion Contact Crevice along the shaded flank
    brush.set("rice_shadow_core", "#070301", 0.92);
    for (let i = 0; i < list.length; i++) {
      let g = list[i];
      let aoX = -g.nx * 1.15 * g.wScale + 0.75;
      let aoY = -g.ny * 1.15 * g.wScale + 0.9;
      safeLine(
        g.x0 + g.ux * 1.1 + aoX, g.y0 + g.uy * 1.1 + aoY,
        g.x1 - g.ux * 1.1 + aoX, g.y1 - g.uy * 1.1 + aoY
      );
    }

