    // PASS 4: Opaque Pale Cream Under-Body (Tail to Embryo Notch at 0.76*L)
    brush.set("rice_cream_under", "#E0D5C3", 1.0);
    for (let i = 0; i < list.length; i++) {
      let g = list[i];
      safeLine(g.x0, g.y0, g.xOpaque, g.yOpaque);
