    // PASS 5: Shaded Warm-Cream Pencil Flank (reflecting warm bounce light from sienna floor)
    brush.set("rice_cream_pencil", "#CFC1AD", 0.92);
    for (let i = 0; i < list.length; i++) {
      let g = list[i];
      let shX = -g.nx * 0.55 * g.wScale;
      let shY = -g.ny * 0.55 * g.wScale;
      safeLine(
        g.x0 + g.ux * 0.6 + shX, g.y0 + g.uy * 0.6 + shY,
        g.xOpaque + shX, g.yOpaque + shY
      );
    }

    // PASS 6: Main Pale Cream Pencil Body (textured chalky pencil tooth)
    let creamTones = ["#E9DFCE", "#EFE7D8", "#E3D8C5"];
    for (let cVar = 0; cVar < 3; cVar++) {
      brush.set("rice_cream_pencil", creamTones[cVar], 0.98);
      for (let i = 0; i < list.length; i++) {
