        if (g.shadeVar !== cVar) continue;
        safeLine(
          g.x0 + g.ux * 0.4, g.y0 + g.uy * 0.4,
          g.xOpaque + g.ux * 0.5, g.yOpaque + g.uy * 0.5
        );
      }
    }

    // PASS 7: Translucent Tip Crystalline Rim & Embryo Notch Definition
    brush.set("rice_notch_detail", "#CFC5B7", 0.85);
    for (let i = 0; i < list.length; i++) {
      let g = list[i];
      let rimX = g.nx * 0.48 * g.wScale;
      let rimY = g.ny * 0.48 * g.wScale;
      safeLine(
        g.xOpaque - g.ux * 0.8 + rimX, g.yOpaque - g.uy * 0.8 + rimY,
        g.x1 - g.ux * 0.3 + rimX * 0.4, g.y1 - g.uy * 0.3 + rimY * 0.4
      );
    }

    brush.set("rice_notch_detail", "#877565", 0.78);
    for (let i = 0; i < list.length; i++) {
      let g = list[i];
      // Subtle embryo notch indentation at the transition to the translucent tip
      let nSideX = -g.nx * g.notchSide * 0.55 * g.wScale;
      let nSideY = -g.ny * g.notchSide * 0.55 * g.wScale;
      safeLine(
        g.xOpaque - g.ux * 0.6 + nSideX, g.yOpaque - g.uy * 0.6 + nSideY,
        g.x1 - g.ux * 0.7 + nSideX * 0.5, g.y1 - g.uy * 0.7 + nSideY * 0.5
      );
    }

    // PASS 8: Chalky White Pencil Starchy Belly & Upper Lit Ridge
    brush.set("rice_chalk_white", "#F7F4EC", 0.96);
    for (let i = 0; i < list.length; i++) {
      let g = list[i];
      let litX = g.nx * 0.42 * g.wScale;
      let litY = g.ny * 0.42 * g.wScale;
      safeLine(
        g.x0 + g.ux * 0.9 + litX, g.y0 + g.uy * 0.9 + litY,
        g.xOpaque - g.ux * 0.5 + litX, g.yOpaque - g.uy * 0.5 + litY
      );
    }

    // PASS 9: High-Contrast Pure Chalk White Specular Ridge
    brush.set("rice_chalk_peak", "#FFFFFF", 0.95);
    for (let i = 0; i < list.length; i++) {
      let g = list[i];
      let pkX = g.nx * 0.62 * g.wScale;
      let pkY = g.ny * 0.62 * g.wScale;
      safeLine(
        g.x0 + g.ux * 1.6 + pkX, g.y0 + g.uy * 1.6 + pkY,
        g.xOpaque - g.ux * 1.2 + pkX, g.yOpaque - g.uy * 1.2 + pkY
      );
    }
  }
}

// Hyperrealistic Iced Coffee with Kelvin–Helmholtz Cream & Espresso Billow Waves
