// Geometric helpers for the tapered cylindrical glass
function glassHalfWidth(y) {
  let t = constrain((y - GLASS.topY) / (GLASS.botY - GLASS.topY), 0, 1);
  return lerp(GLASS.rxTop, GLASS.rxBot, t);
}

function glassLeft(y) {
  return GLASS.cx - glassHalfWidth(y);
}

function glassRight(y) {
  return GLASS.cx + glassHalfWidth(y);
}

function liqLeft(y) {
  let wall = GLASS.wallThick + (y > GLASS.puntY - 30 ? map(y, GLASS.puntY - 30, GLASS.puntY, 0, 8, true) : 0);
  return glassLeft(y) + wall;
}

function liqRight(y) {
  let wall = GLASS.wallThick + (y > GLASS.puntY - 30 ? map(y, GLASS.puntY - 30, GLASS.puntY, 0, 8, true) : 0);
  return glassRight(y) - wall;
}

function glassRy(y) {
  let t = constrain((y - GLASS.topY) / (GLASS.botY - GLASS.topY), 0, 1);
  return lerp(GLASS.rimRy, GLASS.baseRy, t);
}

// Safe p5.brush shape and spline wrappers to prevent duplicate vertex issues
function cleanPoints(pts, minDist = 2.0) {
  if (!pts || pts.length === 0) return [];
  let out = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    let prev = out[out.length - 1];
    let dx = pts[i][0] - prev[0];
    let dy = pts[i][1] - prev[1];
    if (dx * dx + dy * dy >= minDist * minDist) {
      out.push(pts[i]);
    }
  }
  if (out.length > 2) {
    let first = out[0];
    let last = out[out.length - 1];
    if ( sq(first[0] - last[0]) + sq(first[1] - last[1]) < minDist * minDist ) {
      out.pop();
    }
  }
  return out;
}

function drawSafeShape(pts, curvature = 0.2, close = true) {
  let c = cleanPoints(pts, 2.2);
  if (c.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < c.length; i++) {
    brush.vertex(c[i][0], c[i][1]);
  }
  brush.endShape(close);
}

function drawSafeSpline(pts, curvature = 0.5) {
  let c = cleanPoints(pts, 2.2);
  if (c.length < 2) return;
  if (c.length === 2) {
    brush.line(c[0][0], c[0][1], c[1][0], c[1][1]);
    return;
  }
  brush.spline(c, curvature);
}

// Sutherland-Hodgman polygon clipping for ice cube optical refraction
function clipPolygonToConvex(subjectPoly, clipPoly) {
  let outputList = subjectPoly.slice();
  for (let i = 0; i < clipPoly.length; i++) {
    let inputList = outputList;
    outputList = [];
    if (inputList.length === 0) break;
    let A = clipPoly[i];
    let B = clipPoly[(i + 1) % clipPoly.length];
    let ex = B[0] - A[0];
    let ey = B[1] - A[1];

    let inside = (p) => (ex * (p[1] - A[1]) - ey * (p[0] - A[0])) >= 0;
    let intersect = (S, E) => {
      let dx = E[0] - S[0];
      let dy = E[1] - S[1];
      let denom = ex * dy - ey * dx;
      if (Math.abs(denom) < 1e-6) return S;
      let t = (ex * (A[1] - S[1]) - ey * (A[0] - S[0])) / denom;
      return [S[0] + t * dx, S[1] + t * dy];
    };

    let S = inputList[inputList.length - 1];
    for (let j = 0; j < inputList.length; j++) {
      let E = inputList[j];
      if (inside(E)) {
        if (!inside(S)) outputList.push(intersect(S, E));
        outputList.push(E);
      } else if (inside(S)) {
        outputList.push(intersect(S, E));
      }
      S = E;
    }
  }
  return outputList;
}

function pointInConvexPoly(pt, poly) {
  for (let i = 0; i < poly.length; i++) {
    let A = poly[i];
    let B = poly[(i + 1) % poly.length];
    if ((B[0] - A[0]) * (pt[1] - A[1]) - (B[1] - A[1]) * (pt[0] - A[0]) < 0) {
      return false;
    }
  }
  return true;
}

function clipPolylineToConvex(pts, clipPoly) {
  let segments = [];
  let current = [];
  for (let i = 0; i < pts.length; i++) {
    let p = pts[i];
    if (pointInConvexPoly(p, clipPoly)) {
      current.push(p);
    } else {
      if (current.length >= 2) segments.push(current);
      current = [];
    }
  }
  if (current.length >= 2) segments.push(current);
  return segments;
}

// Kelvin-Helmholtz fluid velocity field (Stuart vortex roll-up + background shear)
function khVelocity(x, y) {
  let shearCenter = 532 - 4 * Math.sin(((x - 405) / 390) * Math.PI);
  let dyShear = y - shearCenter;

  // Upper pale cream layer shears right (u > 0), lower dark espresso shears left (u < 0)
  let u = -0.44 * Math.tanh(dyShear / 25);
  let v = 0;

  // Primary Kelvin-Helmholtz vortex cores (clockwise breaking wave rotation)
  for (let i = 0; i < KH_VORTICES.length; i++) {
    let vt = KH_VORTICES[i];
    let dx = (x - vt.cx) / vt.rx;
    let dy = (y - vt.cy) / vt.ry;
    let r2 = dx * dx + dy * dy;
    let w = vt.omega * (0.78 * Math.exp(-r2 * 1.32) + 0.34 * Math.exp(-r2 * 0.52));
    // Clockwise rotation in screen space (y down): top moves right, right moves down
    u += -w * dy * vt.rx * 1.06;
    v +=  w * dx * vt.ry * 0.88;
  }

  // Secondary braid eddies
  for (let i = 0; i < KH_SUB_EDDIES.length; i++) {
    let se = KH_SUB_EDDIES[i];
    let dx = (x - se.cx) / se.rx;
    let dy = (y - se.cy) / se.ry;
    let r2 = dx * dx + dy * dy;
    if (r2 < 6) {
      let w = se.omega * Math.exp(-r2 * 1.4);
      u += -w * dy * se.rx;
      v +=  w * dx * se.ry;
    }
  }

  // Smooth wall damping near inner glass walls
  let xl = liqLeft(y) + 2;
  let xr = liqRight(y) - 2;
  let dWall = Math.min(x - xl, xr - x);
  let wallDamp = constrain(dWall / 25, 0, 1);
  wallDamp = wallDamp * wallDamp * (3 - 2 * wallDamp);

  // Smooth vertical damping away from the shear zone
  let dVert = Math.abs(y - 532);
  let vertDamp = constrain(1 - (dVert - 95) / 115, 0, 1);

  return { u: u * wallDamp * vertDamp, v: v * wallDamp * vertDamp };
}

// Advect a point (x0, y0) through the Kelvin-Helmholtz velocity field using RK2
function advectKH(x0, y0, steps = 28) {
  // Initial gentle shear-wave perturbation before vortex roll-up
  let wavePhase = ((x0 - 404) / 96.5) * TWO_PI;
  let vertEnv = Math.exp(-Math.abs(y0 - 532) / 68);
  let x = x0;
  let y = y0 - 7.5 * Math.sin(wavePhase) * vertEnv;

  for (let s = 0; s < steps; s++) {
    let v1 = khVelocity(x, y);
    let mx = x + 0.5 * v1.u;
    let my = y + 0.5 * v1.v;
    let v2 = khVelocity(mx, my);
    x += v2.u;
    y += v2.v;
  }
  return [x, y];
}

// Build a non-self-intersecting advected fluid layer polygon between yTop and yBot
function buildKHBandPolygon(yTop, yBot, numSamples = 78, steps = 23, xOffset = 0, yOffset = 0, scaleAround = null) {
  let topPts = [];
  let botPts = [];
  for (let i = 0; i <= numSamples; i++) {
    let t = i / numSamples;
    let xTop = lerp(liqLeft(yTop) + 2, liqRight(yTop) - 2, t);
    let xBot = lerp(liqLeft(yBot) + 2, liqRight(yBot) - 2, t);
    let pT = advectKH(xTop, yTop, steps);
    let pB = advectKH(xBot, yBot, steps);
    topPts.push(transformRefractedPt(pT, xOffset, yOffset, scaleAround));
    botPts.push(transformRefractedPt(pB, xOffset, yOffset, scaleAround));
  }
  let poly = [];
  for (let i = 0; i < topPts.length; i++) poly.push(topPts[i]);
  for (let i = botPts.length - 1; i >= 0; i--) poly.push(botPts[i]);
  return poly;
}

function transformRefractedPt(pt, dx, dy, scaleInfo) {
  let x = pt[0] + dx;
  let y = pt[1] + dy;
  if (scaleInfo) {
    x = scaleInfo.cx + (x - scaleInfo.cx) * scaleInfo.mag;
    y = scaleInfo.cy + (y - scaleInfo.cy) * scaleInfo.mag;
  }
  return [x, y];
}

function buildKHStreamline(y0, numSamples = 140, steps = 33, xMinFrac = 0, xMaxFrac = 1) {
  let pts = [];
  let xl = liqLeft(y0) + 2;
  let xr = liqRight(y0) - 2;
  for (let i = 0; i <= numSamples; i++) {
    let t = lerp(xMinFrac, xMaxFrac, i / numSamples);
    let x = lerp(xl, xr, t);
    pts.push(advectKH(x, y0, steps));
  }
  return pts;
}

// Build rounded-bevel octagonal polygon for an ice cube
function getIceCubePolygon(cube, inset = 0) {
  let hw = Math.max(8, cube.w * 0.5 - inset);
  let hh = Math.max(8, cube.h * 0.5 - inset);
  let bv = Math.min(hw * 0.45, Math.max(4, cube.bevel - inset * 0.4));
  let localPts = [
    [-hw + bv, -hh],
    [ hw - bv, -hh],
    [ hw,      -hh + bv],
    [ hw,       hh - bv],
    [ hw - bv,  hh],
    [-hw + bv,  hh],
    [-hw,       hh - bv],
    [-hw,      -hh + bv]
  ];
  let rad = (cube.ang * Math.PI) / 180;
  let ca = Math.cos(rad);
  let sa = Math.sin(rad);
  return localPts.map(([lx, ly]) => [
    cube.cx + lx * ca - ly * sa,
    cube.cy + lx * sa + ly * ca
  ]);
}

