  brush.noStroke();

  // Translucent glass interior air space (y = 142 to 208)
  let airPoly = [
    [glassLeft(GLASS.topY), GLASS.topY],
    [glassRight(GLASS.topY), GLASS.topY],
    [glassRight(GLASS.liqY), GLASS.liqY],
    [glassLeft(GLASS.liqY), GLASS.liqY]
  ];
  brush.wash("#ECEAE4", 95);
  drawSafeShape(airPoly, 0.05, true);
  brush.noWash();

  // Upper liquid zone (y = 208 to 545): Pale Ivory & Soft Pastel Cream
  const upperBands = [
    { y1: 208, y2: 350, col: "#F6F0E4", op: 155, bleed: 0.22 },
    { y1: 320, y2: 455, col: "#EFE3D0", op: 145, bleed: 0.26 },
    { y1: 425, y2: 538, col: "#E5D3BC", op: 140, bleed: 0.28 },
    { y1: 485, y2: 552, col: "#D7BE9F", op: 125, bleed: 0.32 }
  ];
  for (let b of upperBands) {
    let poly = [
      [liqLeft(b.y1), b.y1],
      [liqRight(b.y1), b.y1],
      [liqRight(b.y2), b.y2],
      [liqLeft(b.y2), b.y2]
    ];
    brush.fill(b.col, b.op);
    brush.fillBleed(b.bleed, "out");
    brush.fillTexture(0.42, 0.22);
    drawSafeShape(poly, 0.1, true);
  }

  // Lower liquid zone (y = 528 to 952): Raw Umber & Deep Espresso with warm bottom glow
  const lowerBands = [
    { y1: 525, y2: 615, col: "#7D583A", op: 145, bleed: 0.30 },
    { y1: 565, y2: 710, col: "#5A3B23", op: 165, bleed: 0.26 },
    { y1: 640, y2: 840, col: "#3F2615", op: 175, bleed: 0.22 },
    { y1: 770, y2: 935, col: "#321D0F", op: 170, bleed: 0.20 },
    // Warm amber-umber internal bounce glow near the crystal glass floor
    { y1: 885, y2: 952, col: "#7A4B28", op: 135, bleed: 0.28 },
    { y1: 918, y2: 952, col: "#9E683E", op: 110, bleed: 0.25 }
  ];
  for (let b of lowerBands) {
    let poly = [
      [liqLeft(b.y1), b.y1],
      [liqRight(b.y1), b.y1],
      [liqRight(b.y2), b.y2],
      [liqLeft(b.y2), b.y2]
    ];
    brush.fill(b.col, b.op);
    brush.fillBleed(b.bleed, "out");
    brush.fillTexture(0.5, 0.28);
    drawSafeShape(poly, 0.1, true);
  }

  // Deep espresso core shadow in the center-right of the lower half
  let corePoly = [
    [455, 575], [755, 570], [748, 885], [462, 890]
  ];
  brush.fill("#28160B", 115);
  brush.fillBleed(0.32, "out");
  brush.fillTexture(0.48, 0.25);
  drawSafeShape(corePoly, 0.35, true);
  brush.noFill();
}

// =============================================================================
// 3. RECENTLY POURED CREAM PLUME (Upper zone billowing clouds & trapped coffee veins)
// =============================================================================
function drawPouringCreamPlume() {
  brush.noStroke();

  // Pockets of translucent raw umber & pastel mocha trapped between the descending cream clouds
  const coffeePockets = [
    { cx: 438, cy: 335, rx: 32, ry: 45, col: "#9C7A5C", op: 95 },
    { cx: 538, cy: 315, rx: 28, ry: 52, col: "#8C684A", op: 105 },
    { cx: 652, cy: 342, rx: 36, ry: 48, col: "#926E4F", op: 100 },
    { cx: 748, cy: 360, rx: 28, ry: 42, col: "#A48264", op: 90 },
    { cx: 445, cy: 445, rx: 35, ry: 38, col: "#856042", op: 110 },
    { cx: 612, cy: 432, rx: 42, ry: 34, col: "#7E593B", op: 115 },
    { cx: 735, cy: 452, rx: 34, ry: 36, col: "#8A6445", op: 105 }
  ];
  for (let cp of coffeePockets) {
    let pts = [];
    for (let a = 0; a < 360; a += 30) {
      let rMod = 0.8 + 0.35 * noise(cp.cx * 0.02 + cos(a), cp.cy * 0.02 + sin(a));
      pts.push([cp.cx + cp.rx * rMod * cos(a), cp.cy + cp.ry * rMod * sin(a)]);
    }
    brush.fill(cp.col, cp.op);
    brush.fillBleed(0.35, "out");
    brush.fillTexture(0.5, 0.3);
    drawSafeShape(pts, 0.35, true);
  }

  // Luminous ivory & pastel cream pour clouds billowing downward toward the shear line
  const creamClouds = [
    { cx: 565, cy: 265, rx: 68, ry: 46, col: "#FAF6EE", op: 150 },
    { cx: 495, cy: 318, rx: 58, ry: 48, col: "#F6EFE2", op: 140 },
    { cx: 605, cy: 348, rx: 64, ry: 52, col: "#F4ECE0", op: 145 },
    { cx: 535, cy: 412, rx: 62, ry: 45, col: "#EFE3D1", op: 135 },
    { cx: 675, cy: 418, rx: 56, ry: 42, col: "#EDE0CC", op: 130 },
    { cx: 472, cy: 465, rx: 50, ry: 35, col: "#F2E7D7", op: 135 },
    { cx: 585, cy: 472, rx: 65, ry: 38, col: "#F5EDE0", op: 140 },
    { cx: 702, cy: 470, rx: 52, ry: 34, col: "#EFE2CF", op: 130 }
  ];
  for (let cc of creamClouds) {
    let pts = [];
    for (let a = 0; a < 360; a += 25) {
      let rMod = 0.82 + 0.32 * noise(cc.cx * 0.03 + cos(a), cc.cy * 0.03 + sin(a));
      pts.push([cc.cx + cc.rx * rMod * cos(a), cc.cy + cc.ry * rMod * sin(a)]);
    }
    brush.fill(cc.col, cc.op);
    brush.fillBleed(0.30, "out");
    brush.fillTexture(0.4, 0.22);
    drawSafeShape(pts, 0.35, true);
  }
  brush.noFill();

  // Delicate fluid veins of raw umber & ivory swirling around the pour column
  for (let i = 0; i < 18; i++) {
    let startX = random(425, 775);
    let startY = random(230, 465);
    let pts = [];
    let x = startX;
    let y = startY;
    for (let s = 0; s < 14; s++) {
      pts.push([x, y]);
      let ang = noise(x * 0.008, y * 0.008, i * 0.2) * 360;
      x += cos(ang) * 11;
      y += sin(ang) * 8 + 2.5;
      x = constrain(x, liqLeft(y) + 6, liqRight(y) - 6);
    }
    let isDark = i % 2 === 0;
    brush.set("fluid_silk", isDark ? "#8C6849" : "#FAF5EC", isDark ? 0.85 : 1.1);
    drawSafeSpline(pts, 0.5);
  }
}

// =============================================================================
// 4. KELVIN–HELMHOLTZ BILLOW CLOUDS (Centerpiece Fluid Shear Instability)
// =============================================================================
function drawKelvinHelmholtzBillows() {
  brush.noStroke();

  // 4A. Advected interlocking fluid layers (wet-on-wet watercolor bands)
  // Upper bands are ivory/cream rolling over to the right; lower bands are raw umber/espresso curling up & under
  const khLayers = [
    { y1: 468, y2: 496, steps: 20, col: "#F7F1E5", op: 150, bleed: 0.28 },
    { y1: 492, y2: 516, steps: 23, col: "#EDE0CC", op: 145, bleed: 0.32 },
    { y1: 510, y2: 528, steps: 25, col: "#D8BE9E", op: 138, bleed: 0.35 },
    { y1: 523, y2: 537, steps: 26, col: "#AE8868", op: 135, bleed: 0.38 },
    { y1: 531, y2: 546, steps: 26, col: "#7A5437", op: 155, bleed: 0.36 },
    { y1: 540, y2: 560, steps: 25, col: "#563720", op: 165, bleed: 0.32 },
    { y1: 554, y2: 582, steps: 22, col: "#3B2312", op: 170, bleed: 0.28 },
    { y1: 575, y2: 612, steps: 18, col: "#2D190C", op: 160, bleed: 0.25 }
  ];

  for (let layer of khLayers) {
    let poly = buildKHBandPolygon(layer.y1, layer.y2, 76, layer.steps);
    brush.fill(layer.col, layer.op);
    brush.fillBleed(layer.bleed, "out");
    brush.fillTexture(0.48, 0.28);
    drawSafeShape(poly, 0.22, true);
  }

  // 4B. Wet-on-wet watercolor blooms right along the curling wave crests & troughs
  for (let i = 0; i < KH_VORTICES.length; i++) {
    let vt = KH_VORTICES[i];
    // High breaking crest of raw umber bleeding into warm ivory
    let crestPt = advectKH(vt.cx - 18, 530, 24);
    brush.fill("#FAF4E8", 145);
    brush.fillBleed(0.42, "out");
    brush.fillTexture(0.45, 0.22);
    brush.circle(crestPt[0] - 4, crestPt[1] - 10, 26, 0.42);

    brush.fill("#6E4A2E", 140);
    brush.fillBleed(0.44, "out");
    brush.fillTexture(0.52, 0.30);
    brush.circle(crestPt[0] + 6, crestPt[1] + 4, 22, 0.45);

    // Deep espresso curl under the breaking wave lip
    let troughPt = advectKH(vt.cx + 18, 536, 24);
    brush.fill("#3B2312", 155);
    brush.fillBleed(0.36, "out");
    brush.fillTexture(0.48, 0.26);
    brush.circle(troughPt[0], troughPt[1] + 6, 24, 0.38);

    // Luminous pastel cream tongue spiraling into the vortex eye
    brush.fill("#F3E7D4", 150);
    brush.fillBleed(0.34, "out");
    brush.fillTexture(0.42, 0.22);
    brush.circle(vt.cx - 4, vt.cy - 2, 16, 0.35);
  }
  brush.noFill();

  // 4C. Soft wet-on-wet diffuser washes along the advected streamlines
  const washStreamlines = [
    { y0: 514, steps: 27, col: "#F6EFE2", w: 1.1 },
    { y0: 524, steps: 29, col: "#DFC8AC", w: 1.0 },
    { y0: 530, steps: 30, col: "#8C6545", w: 0.95 },
    { y0: 536, steps: 30, col: "#5E3D24", w: 1.0 },
    { y0: 544, steps: 28, col: "#3D2413", w: 1.1 }
  ];
  for (let ws of washStreamlines) {
    let pts = buildKHStreamline(ws.y0, 120, ws.steps);
    brush.set("soft_wash", ws.col, ws.w);
    drawSafeSpline(pts, 0.45);
  }

  // 4D. High-resolution spiral filaments winding 1.5 - 2 turns into each Kelvin-Helmholtz vortex core
  const filamentSpec = [
    { y0: 498, steps: 26, col: "#FAF6ED", w: 1.05, brushName: "fluid_silk" },
    { y0: 506, steps: 28, col: "#F3E8D7", w: 0.95, brushName: "fluid_silk" },
    { y0: 513, steps: 31, col: "#B38E6E", w: 0.75, brushName: "fluid_silk" },
    { y0: 518, steps: 33, col: "#F8F2E6", w: 1.10, brushName: "fluid_silk" },
    { y0: 522, steps: 35, col: "#8A6343", w: 0.85, brushName: "fluid_silk" },
    { y0: 526, steps: 37, col: "#FAF5EB", w: 1.15, brushName: "fluid_silk" },
    { y0: 529, steps: 38, col: "#684428", w: 0.95, brushName: "fluid_silk" },
    { y0: 532, steps: 39, col: "#F4E8D6", w: 1.00, brushName: "fluid_silk" },
    { y0: 535, steps: 39, col: "#4A2D18", w: 1.05, brushName: "fluid_silk" },
    { y0: 538, steps: 38, col: "#E5D2B8", w: 0.85, brushName: "fluid_silk" },
    { y0: 541, steps: 36, col: "#361F0F", w: 1.10, brushName: "fluid_silk" },
    { y0: 545, steps: 34, col: "#C9AD8E", w: 0.75, brushName: "fluid_silk" },
    { y0: 550, steps: 31, col: "#2D180B", w: 1.05, brushName: "fluid_silk" },
    { y0: 557, steps: 28, col: "#7D583A", w: 0.80, brushName: "fluid_silk" },
    { y0: 565, steps: 25, col: "#382010", w: 0.95, brushName: "fluid_silk" }
  ];

  for (let f of filamentSpec) {
    let pts = buildKHStreamline(f.y0, 155, f.steps);
    brush.set(f.brushName, f.col, f.w);
    drawSafeSpline(pts, 0.5);
  }

  // 4E. Dedicated tight spiral curls inside each of the 4 billow eyes for razor-sharp KH definition
  for (let i = 0; i < KH_VORTICES.length; i++) {
    let vt = KH_VORTICES[i];
    // Trace two interlocking spiral arms (ivory cream + dark raw umber) over 2.2 turns
    for (let arm = 0; arm < 2; arm++) {
      let spiralPts = [];
      let basePhase = arm * 180 + vt.phase * 57;
      for (let step = 0; step <= 42; step++) {
        let frac = step / 42; // 0 = outer crest, 1 = tight center eye
        let ang = basePhase + frac * 620; // clockwise spiral
        let rx = vt.rx * (0.92 * pow(1 - frac, 0.78) + 0.05);
        let ry = vt.ry * (0.88 * pow(1 - frac, 0.78) + 0.05);
        // Forward breaking-wave shear offset at the top of the wave
        let shearShift = -9 * sin(ang) * (1 - frac);
        let sx = vt.cx + rx * cos(ang) + shearShift;
        let sy = vt.cy + ry * sin(ang);
        spiralPts.push([sx, sy]);
      }
      if (arm === 0) {
        brush.set("fluid_silk", "#FAF5EC", 1.15);
        drawSafeSpline(spiralPts, 0.55);
        brush.set("cpencil", "#FFFDF8", 0.75);
        drawSafeSpline(spiralPts.slice(6, 36), 0.55);
      } else {
        brush.set("fluid_silk", "#482B16", 1.10);
        drawSafeSpline(spiralPts, 0.55);
        brush.set("cpencil", "#2E1A0B", 0.75);
        drawSafeSpline(spiralPts.slice(6, 36), 0.55);
      }
    }
  }

  // 4F. Fine spray mist & watercolor granulation along the turbulent edges
  let interfacePts = buildKHStreamline(531, 140, 32);
  let upperCrestPts = buildKHStreamline(519, 120, 29);
  let lowerTroughPts = buildKHStreamline(542, 120, 29);

  // Ivory cream mist diffusing into the raw umber crests
  brush.set("fine_mist", "#FAF4E8", 1.15);
  drawSafeSpline(upperCrestPts, 0.45);
  brush.set("spray", "#F2E5D2", 0.85);
  drawSafeSpline(interfacePts, 0.45);

  // Raw umber mist diffusing into the pale cream billows
  brush.set("fine_mist", "#6D492D", 1.05);
  drawSafeSpline(interfacePts, 0.45);
  brush.set("spray", "#4A2E19", 0.80);
  drawSafeSpline(lowerTroughPts, 0.45);

  // Delicate sinking tendrils of diluted raw umber & caramel below the billows (y = 565 to 740)
  for (let i = 0; i < 16; i++) {
    let tx = map(i, 0, 15, 422, 778) + random(-8, 8);
    let ty = random(565, 605);
    let tendril = [];
    for (let s = 0; s < 10; s++) {
      tendril.push([tx, ty]);
      tx += sin(ty * 3.5 + i * 25) * 3.5;
      ty += random(10, 16);
    }
    let col = i % 3 === 0 ? "#A88668" : (i % 2 === 0 ? "#7B5538" : "#261409");
    brush.set("fluid_silk", col, 0.65);
    drawSafeSpline(tendril, 0.5);
  }
}

// =============================================================================
// 5. ICE CUBES & OPTICAL WAVE REFRACTIONS
// =============================================================================
function drawIceCubesAndRefractions() {
  for (let idx = 0; idx < ICE_CUBES.length; idx++) {
    let cube = ICE_CUBES[idx];
    let outerPoly = getIceCubePolygon(cube, 0);
    let innerPoly = getIceCubePolygon(cube, cube.bevel);

    // 5A. Translucent crystal base glaze over the ice cube footprint
    brush.noStroke();
    brush.wash(cube.tint, cube.refractsKH ? 55 : 85);
    drawSafeShape(outerPoly, 0.08, true);
    brush.noWash();

    // 5B. If this ice cube straddles the Kelvin-Helmholtz zone, render the REFRACTED waves inside it!
    if (cube.refractsKH) {
      let scaleInfo = { cx: cube.cx, cy: cube.cy, mag: cube.mag };

      // Refracted watercolor bands (shifted & magnified by Snell's law through the ice block)
      const refractedBands = [
        { y1: 465, y2: 515, steps: 22, col: "#F8F3E8", op: 145 },
        { y1: 510, y2: 532, steps: 25, col: "#DFC8AC", op: 135 },
        { y1: 528, y2: 552, steps: 25, col: "#6D4A2F", op: 150 },
        { y1: 548, y2: 595, steps: 21, col: "#3D2413", op: 160 }
      ];

      for (let rb of refractedBands) {
        let rawPoly = buildKHBandPolygon(rb.y1, rb.y2, 54, rb.steps, cube.shiftX, cube.shiftY, scaleInfo);
        let clipped = clipPolygonToConvex(rawPoly, outerPoly);
        if (clipped.length >= 3) {
          brush.noStroke();
          brush.fill(rb.col, rb.op);
          brush.fillBleed(0.18, "in");
          brush.fillTexture(0.38, 0.22);
          drawSafeShape(clipped, 0.12, true);
          brush.noFill();
        }
      }

      // Refracted high-contrast KH spiral filaments clipped inside the ice cube
      const refractedLines = [
        { y0: 516, steps: 32, col: "#FFFFFF", w: 1.1 },
        { y0: 524, steps: 35, col: "#7A5437", w: 0.9 },
        { y0: 530, steps: 37, col: "#FAF5EB", w: 1.15 },
        { y0: 535, steps: 37, col: "#3A2211", w: 1.1 },
        { y0: 542, steps: 34, col: "#D8C0A4", w: 0.85 }
      ];

      for (let rl of refractedLines) {
        let rawPts = buildKHStreamline(rl.y0, 110, rl.steps).map(p =>
          transformRefractedPt(p, cube.shiftX, cube.shiftY, scaleInfo)
        );
        let segs = clipPolylineToConvex(rawPts, outerPoly);
        brush.set("fluid_silk", rl.col, rl.w);
        for (let seg of segs) {
          drawSafeSpline(seg, 0.45);
        }
      }

      // Secondary stepped refraction inside the angled bevel facets of the ice cube
      let bevelShiftPts = buildKHStreamline(531, 90, 30).map(p =>
        transformRefractedPt(p, -cube.shiftX * 0.7, cube.shiftY * 0.6, null)
      );
      let outerSegs = clipPolylineToConvex(bevelShiftPts, outerPoly);
      brush.set("cpencil", "#B8CED8", 0.85);
      for (let seg of outerSegs) {
        drawSafeSpline(seg, 0.4);
      }
    } else {
      // Upper ice cubes refract the pale ivory cream & soft coffee veins
      brush.noStroke();
      brush.fill("#FAF6EE", 95);
      brush.fillBleed(0.2, "in");
      brush.fillTexture(0.35, 0.2);
      drawSafeShape(innerPoly, 0.15, true);
      brush.noFill();
    }

    // 5C. Sculpted 3D Bevel Facets of the Ice Cube (soft pastel cool blue, lavender-grey, warm ivory, dark umber)
    brush.noStroke();
    // Top bevel facet (catches overhead cool sky & bright ivory light)
    let topFacet = [outerPoly[0], outerPoly[1], innerPoly[1], innerPoly[0]];
    brush.wash("#F4F8FA", 130);
    drawSafeShape(topFacet, 0.02, true);

    // Left bevel facet (luminous pastel sky-blue reflection)
    let leftFacet = [outerPoly[6], outerPoly[7], innerPoly[7], innerPoly[6]];
    brush.wash("#D4E3EB", 115);
    drawSafeShape(leftFacet, 0.02, true);

    // Right bevel facet (refracts warm raw umber & pastel lilac shadow)
    let rightFacet = [outerPoly[2], outerPoly[3], innerPoly[3], innerPoly[2]];
    let rightCol = cube.cy > 420 ? "#8C6B52" : "#C5D2DC";
    brush.wash(rightCol, 95);
    drawSafeShape(rightFacet, 0.02, true);

    // Bottom bevel facet (internal total reflection of the dark espresso below)
    let botFacet = [outerPoly[4], outerPoly[5], innerPoly[5], innerPoly[4]];
    let botCol = cube.cy > 360 ? "#5E4029" : "#AEBEC8";
    brush.wash(botCol, 110);
    drawSafeShape(botFacet, 0.02, true);
    brush.noWash();

    // 5D. Internal crystal fracture lines & trapped micro-air bubbles inside the ice core
    brush.set("2H", "#DCE8EF", 0.65);
    brush.line(
      cube.cx - cube.w * 0.18, cube.cy - cube.h * 0.12,
      cube.cx + cube.w * 0.15, cube.cy + cube.h * 0.16
    );
    brush.line(
      cube.cx + cube.w * 0.12, cube.cy - cube.h * 0.15,
      cube.cx - cube.w * 0.08, cube.cy + cube.h * 0.10
    );

    // Crisp rim contours & bright specular bevel ridge highlights
    brush.set("cpencil", "#9BB0BC", 0.7);
    drawSafeSpline([...outerPoly, outerPoly[0]], 0.18);

    brush.set("fluid_silk", "#EAF2F6", 0.85);
    drawSafeSpline([innerPoly[7], innerPoly[0], innerPoly[1], innerPoly[2]], 0.15);

    // Pinpoint specular highlights along the upper-left bevel ridges
    brush.set("pinpoint", "#FFFFFF", 1.15);
    drawSafeSpline([outerPoly[7], outerPoly[0], outerPoly[1]], 0.12);
    brush.set("pinpoint", "#FFFFFF", 0.9);
    brush.line(innerPoly[0][0], innerPoly[0][1], innerPoly[1][0], innerPoly[1][1]);
    brush.line(outerPoly[0][0], outerPoly[0][1], innerPoly[0][0], innerPoly[0][1]);
  }
}

// =============================================================================
// 6. GLASS STRUCTURE, HEAVY BASE, MENISCUS & CYLINDRICAL OPTICS
// =============================================================================
function drawGlassStructureAndOptics() {
  // 6A. Liquid surface meniscus at y = 208
  let menBackPts = [];
  let menFrontPts = [];
  let rxLiq = glassHalfWidth(GLASS.liqY) - GLASS.wallThick;
  for (let a = 180; a <= 360; a += 6) {
    menBackPts.push([GLASS.cx + rxLiq * cos(a), GLASS.liqY + GLASS.liqRy * sin(a)]);
  }
  for (let a = 0; a <= 180; a += 6) {
    menFrontPts.push([GLASS.cx + rxLiq * cos(a), GLASS.liqY + GLASS.liqRy * sin(a)]);
  }

  // Soft pastel cream surface ellipse with subtle ice-cube meniscus ripples
  brush.noStroke();
  brush.fill("#F8F3E8", 165);
  brush.fillBleed(0.15, "in");
  brush.fillTexture(0.3, 0.2);
  drawSafeShape([...menBackPts, ...menFrontPts], 0.2, true);
  brush.noFill();

  // Concave upturned meniscus rim where cream climbs the inner glass wall
  brush.set("fluid_silk", "#DFD5C5", 1.0);
  drawSafeSpline(menBackPts, 0.4);
  brush.set("fluid_silk", "#C8B8A4", 1.1);
  drawSafeSpline(menFrontPts, 0.4);
  brush.set("pinpoint", "#FFFFFF", 1.1);
  let menFrontHighlight = menFrontPts.map(p => [p[0], p[1] - 2.5]);
  drawSafeSpline(menFrontHighlight, 0.4);

  // 6B. Heavy Solid Crystal Glass Base (y = 952 to 1038)
  let xL_punt = glassLeft(GLASS.puntY);
  let xR_punt = glassRight(GLASS.puntY);
  let xL_bot  = glassLeft(GLASS.botY);
  let xR_bot  = glassRight(GLASS.botY);

  // Clear crystal body of the base
  let basePoly = [
    [xL_punt, GLASS.puntY],
    [xR_punt, GLASS.puntY],
    [xR_bot,  GLASS.botY],
    [xL_bot,  GLASS.botY]
  ];
  brush.noStroke();
  brush.wash("#E5EAE8", 175);
  drawSafeShape(basePoly, 0.05, true);
  brush.noWash();

  // Internal curved "punt" cushion where dark espresso meets the thick crystal floor
  let puntCurve = [];
  for (let a = 0; a <= 180; a += 8) {
    puntCurve.push([
      GLASS.cx + (xR_punt - GLASS.cx - 11) * cos(a),
      GLASS.puntY - 4 + 16 * sin(a)
    ]);
  }
  let puntBand = [
    ...puntCurve,
    ...puntCurve.slice().reverse().map(p => [p[0], p[1] + 18])
  ];
  brush.fill("#3D2312", 180);
  brush.fillBleed(0.2, "out");
  brush.fillTexture(0.4, 0.25);
  drawSafeShape(puntBand, 0.25, true);

  // Warm amber-sienna optical refraction band inside the upper crystal base
  let amberBand = [
    ...puntCurve.map(p => [p[0], p[1] + 14]),
    ...puntCurve.slice().reverse().map(p => [p[0], p[1] + 32])
  ];
  brush.fill("#9C673D", 145);
  brush.fillBleed(0.25, "out");
  brush.fillTexture(0.4, 0.2);
  drawSafeShape(amberBand, 0.25, true);

  // Luminous pastel celadon & ivory crystal cushion in the middle of the heavy base
  let crystalCushion = [
    [xL_punt + 16, 984],
    [xR_punt - 16, 984],
    [xR_bot - 18,  1018],
    [xL_bot + 18,  1018]
  ];
  brush.fill("#F4F7F5", 165);
  brush.fillBleed(0.22, "in");
  brush.fillTexture(0.3, 0.15);
  drawSafeShape(crystalCushion, 0.3, true);

  // Bottom resting rim ellipse of the glass (y = 1030..1038)
  let botEllipse = [];
  for (let a = 0; a < 360; a += 10) {
    botEllipse.push([
      GLASS.cx + (GLASS.rxBot - 4) * cos(a),
      GLASS.botY - 6 + GLASS.baseRy * sin(a)
    ]);
  }
  brush.fill("#6E5846", 125);
  brush.fillBleed(0.18, "in");
  brush.fillTexture(0.4, 0.25);
  drawSafeShape(botEllipse, 0.25, true);
  brush.noFill();

  // Crisp optical rings inside the heavy glass base
  brush.set("fluid_silk", "#2A160B", 1.15);
  drawSafeSpline(puntCurve, 0.4);
  brush.set("pinpoint", "#FFFFFF", 1.25);
  drawSafeSpline(puntCurve.map(p => [p[0], p[1] + 15]), 0.4);
  brush.set("fluid_silk", "#B5C8C2", 1.1);
  drawSafeSpline(puntCurve.map(p => [p[0], p[1] + 36]), 0.4);

  let botFrontArc = [];
  for (let a = 10; a <= 170; a += 6) {
    botFrontArc.push([
      GLASS.cx + (GLASS.rxBot - 2) * cos(a),
      GLASS.botY - 4 + GLASS.baseRy * sin(a)
    ]);
  }
  brush.set("fluid_silk", "#4D3D30", 1.1);
  drawSafeSpline(botFrontArc, 0.4);
  brush.set("pinpoint", "#FFFFFF", 1.2);
  drawSafeSpline(botFrontArc.map(p => [p[0], p[1] - 4]), 0.4);

  // 6C. Left & Right Glass Wall Thickness (11px crystal columns with internal refraction lines)
  brush.noStroke();
  let leftWallPoly = [
    [glassLeft(GLASS.topY), GLASS.topY],
    [glassLeft(GLASS.topY) + GLASS.wallThick, GLASS.topY],
    [glassLeft(GLASS.puntY) + GLASS.wallThick, GLASS.puntY],
    [glassLeft(GLASS.puntY), GLASS.puntY]
  ];
  let rightWallPoly = [
    [glassRight(GLASS.topY) - GLASS.wallThick, GLASS.topY],
    [glassRight(GLASS.topY), GLASS.topY],
    [glassRight(GLASS.puntY), GLASS.puntY],
    [glassRight(GLASS.puntY) - GLASS.wallThick, GLASS.puntY]
  ];
  brush.wash("#DCE6E3", 105);
  drawSafeShape(leftWallPoly, 0.02, true);
  drawSafeShape(rightWallPoly, 0.02, true);
  brush.noWash();

  // Outer & inner vertical glass wall contours
  brush.set("cpencil", "#8A9692", 0.9);
  brush.line(glassLeft(GLASS.topY), GLASS.topY, glassLeft(GLASS.botY), GLASS.botY);
  brush.line(glassRight(GLASS.topY), GLASS.topY, glassRight(GLASS.botY), GLASS.botY);

  // Dark internal refractive line along the inner glass wall
  brush.set("fluid_silk", "#5C4736", 0.75);
  brush.line(liqLeft(GLASS.liqY), GLASS.liqY, liqLeft(GLASS.puntY), GLASS.puntY);
  brush.line(liqRight(GLASS.liqY), GLASS.liqY, liqRight(GLASS.puntY), GLASS.puntY);

  // Brilliant vertical edge highlights inside the left & right glass walls
  brush.set("pinpoint", "#FFFFFF", 1.1);
  brush.line(glassLeft(GLASS.topY) + 4, GLASS.topY + 8, glassLeft(GLASS.botY) + 4, GLASS.botY - 12);
  brush.set("pinpoint", "#F5F9FA", 0.9);
  brush.line(glassRight(GLASS.topY) - 4, GLASS.topY + 8, glassRight(GLASS.botY) - 4, GLASS.botY - 12);

  // 6D. Cylindrical Vertical Studio Window Reflections across the glass surface
  for (let s = 0; s < 5; s++) {
    let offset = 28 + s * 6;
    let xTopL = glassLeft(GLASS.topY) + offset;
    let xBotL = glassLeft(GLASS.botY) + offset * 0.92;
    brush.set("glass_glaze", "#FFFFFF", 1.15 - s * 0.15);
    brush.line(xTopL, GLASS.topY + 14, xBotL, GLASS.botY - 22);
  }
  // Slender secondary reflection near the right rim
  for (let s = 0; s < 3; s++) {
    let offset = 22 + s * 5;
    let xTopR = glassRight(GLASS.topY) - offset;
    let xBotR = glassRight(GLASS.botY) - offset * 0.92;
    brush.set("glass_glaze", "#F2F7FA", 0.85 - s * 0.18);
    brush.line(xTopR, GLASS.topY + 16, xBotR, GLASS.botY - 26);
  }

  // 6E. Top Glass Rim at y = 142 (seen at eye level: shallow ellipse with double glass lip)
  let rimBack = [];
  let rimFront = [];
  for (let a = 180; a <= 360; a += 5) {
    rimBack.push([GLASS.cx + GLASS.rxTop * cos(a), GLASS.topY + GLASS.rimRy * sin(a)]);
  }
  for (let a = 0; a <= 180; a += 5) {
    rimFront.push([GLASS.cx + GLASS.rxTop * cos(a), GLASS.topY + GLASS.rimRy * sin(a)]);
  }

  brush.set("fluid_silk", "#9BA6A4", 1.0);
  drawSafeSpline(rimBack, 0.4);
  brush.set("pinpoint", "#FFFFFF", 0.95);
  drawSafeSpline(rimBack.map(p => [p[0], p[1] + 2.5]), 0.4);

  brush.set("fluid_silk", "#7A8482", 1.15);
  drawSafeSpline(rimFront, 0.4);
  brush.set("pinpoint", "#FFFFFF", 1.35);
  drawSafeSpline(rimFront.map(p => [p[0], p[1] - 3]), 0.4);
}

// =============================================================================
// 7. CONDENSATION BEADS, DRIP TRACKS & PINPOINT HIGHLIGHTS
// =============================================================================
function drawCondensationAndHighlights() {
  // 7A. Chilled exterior micro-condensation mist (velvety dewy sheen across the cold glass)
  for (let i = 0; i < 28; i++) {
    let my = map(i, 0, 27, GLASS.liqY + 12, GLASS.puntY - 10);
    let xl = glassLeft(my) + 8;
    let xr = glassRight(my) - 8;
    let col = my < 525 ? "#FAF6EE" : (my < 560 ? "#D6C0A6" : "#8C6B50");
    brush.set("fine_mist", col, 0.65);
    brush.line(xl, my, xr, my + random(-4, 4));
  }

  // 7B. Three vertical droplet slide tracks (where a heavy bead slid down, wiping the mist clear)
  const dripTracks = [
    { xFrac: 0.31, yStart: 390, yEnd: 512, rEnd: 6.8 },
    { xFrac: 0.68, yStart: 485, yEnd: 635, rEnd: 7.4 },
    { xFrac: 0.44, yStart: 620, yEnd: 765, rEnd: 6.5 }
  ];

  for (let dt of dripTracks) {
    let trackPts = [];
    for (let y = dt.yStart; y <= dt.yEnd; y += 8) {
      let x = lerp(glassLeft(y), glassRight(y), dt.xFrac) + sin(y * 2.5) * 1.8;
      trackPts.push([x, y]);
    }
    // Wiped clear trail shows darker/richer interior liquid + faint wet edge highlight
    let trailCol = dt.yStart < 510 ? "#E0CCB2" : "#2A170B";
    brush.set("fluid_silk", trailCol, 1.35);
    drawSafeSpline(trackPts, 0.4);
    brush.set("pinpoint", "#FFFDF9", 0.55);
    drawSafeSpline(trackPts.map(p => [p[0] - 2.2, p[1]]), 0.4);
  }

  // 7C. Generate non-overlapping condensation beads across the glass front
  let beads = [];

  // Place the 3 heavy terminal droplets at the bottom of the slide tracks first
  for (let dt of dripTracks) {
    let bx = lerp(glassLeft(dt.yEnd), glassRight(dt.yEnd), dt.xFrac) + sin(dt.yEnd * 2.5) * 1.8;
    beads.push({ x: bx, y: dt.yEnd + 2, r: dt.rEnd, elong: 1.25 });
  }

  // Populate ~115 hero & medium beads (r = 3.2 to 7.6 px) with minimum spacing
  let attempts = 0;
  while (beads.length < 118 && attempts < 1800) {
    attempts++;
    let by = random(GLASS.liqY + 14, GLASS.puntY - 8);
    // Concentrate slightly more beads near the cold upper-mid & shear zone
    let xl = glassLeft(by) + 10;
    let xr = glassRight(by) - 10;
    let bx = random(xl, xr);
    let br = random() < 0.28 ? random(5.2, 7.6) : random(3.0, 5.1);

    let ok = true;
    for (let other of beads) {
      let d2 = sq(bx - other.x) + sq(by - other.y);
      let minD = br + other.r + 3.5;
      if (d2 < minD * minD) {
        ok = false;
        break;
      }
    }
    if (ok) {
      beads.push({ x: bx, y: by, r: br, elong: random(1.0, 1.18) });
    }
  }

  // Also generate ~240 tiny micro-dewdrops (r = 1.3 to 2.5 px) in the spaces between hero beads
  let microBeads = [];
  for (let i = 0; i < 240; i++) {
    let by = random(GLASS.topY + 25, GLASS.botY - 25);
    let bx = random(glassLeft(by) + 7, glassRight(by) - 7);
    let br = random(1.3, 2.5);
    microBeads.push({ x: bx, y: by, r: br });
  }

  // Render micro-dewdrops (crisp dark shadow dot + pinpoint highlight dot)
  for (let mb of microBeads) {
    let isDarkZone = mb.y > 535 && mb.y < GLASS.puntY;
    let shCol = isDarkZone ? "#1C0E05" : "#9C8B7A";
    brush.set("cpencil", shCol, mb.r * 0.48);
    brush.line(mb.x + 0.5, mb.y + 0.8, mb.x + 1.2, mb.y + 1.4);

    brush.set("pinpoint", "#FFFFFF", mb.r * 0.55);
    brush.line(mb.x - 0.5, mb.y - 0.6, mb.x, mb.y - 0.2);
  }

  // Render hero & medium condensation beads with full hyperrealistic optical anatomy:
  // 1. Cast shadow below-right
  // 2. Dark upper-left internal lens refraction crescent
  // 3. Luminous lower-right internal caustic glow
  // 4. Razor-sharp upper-left pinpoint specular highlight
  for (let b of beads) {
    let r = b.r;
    let ry = r * b.elong;
    let inCream = b.y < 518;
    let inShear = b.y >= 518 && b.y <= 558;

    let shadowCol  = inCream ? "#A3917E" : (inShear ? "#4A301C" : "#180C04");
    let lensDark   = inCream ? "#8E7B68" : (inShear ? "#3B2312" : "#160A03");
    let causticCol = inCream ? "#FFFDF8" : (inShear ? "#F5E2C8" : "#D49B6A");

    // 1. Soft external cast shadow below-right of the droplet
    let shPoly = [];
    for (let a = 0; a < 360; a += 45) {
      shPoly.push([b.x + r * 0.35 + r * 0.85 * cos(a), b.y + ry * 0.42 + ry * 0.85 * sin(a)]);
    }
    brush.noStroke();
    brush.wash(shadowCol, inCream ? 85 : 135);
    drawSafeShape(shPoly, 0.25, true);

    // 2. Droplet body & upper-left darkened lens refraction
    let dropPoly = [];
    for (let a = 0; a < 360; a += 36) {
      dropPoly.push([b.x + r * cos(a), b.y + ry * sin(a)]);
    }
    brush.wash(lensDark, inCream ? 95 : 145);
    drawSafeShape(dropPoly, 0.28, true);

    // 3. Lower-right internal caustic focus crescent
    let causticPoly = [];
    for (let a = -25; a <= 135; a += 32) {
      causticPoly.push([b.x + r * 0.15 + r * 0.72 * cos(a), b.y + ry * 0.18 + ry * 0.72 * sin(a)]);
    }
    for (let a = 135; a >= -25; a -= 32) {
      causticPoly.push([b.x + r * 0.05 + r * 0.28 * cos(a), b.y + ry * 0.08 + ry * 0.28 * sin(a)]);
    }
    brush.wash(causticCol, inCream ? 185 : 165);
    drawSafeShape(causticPoly, 0.2, true);
    brush.noWash();

    // Subtle crisp lower-right caustic rim stroke
    brush.set("cpencil", causticCol, 0.55);
    brush.arc(b.x, b.y, r * 0.82, 15, 115);

    // 4. Razor-sharp pinpoint white highlight on the upper-left of the bead
    let hx = b.x - r * 0.34;
    let hy = b.y - ry * 0.34;
    brush.set("pinpoint", "#FFFFFF", constrain(r * 0.28, 0.85, 1.85));
    brush.line(hx - 0.6, hy - 0.4, hx + 0.7, hy + 0.5);

    // Secondary tiny internal bounce glint at the very bottom edge on larger beads
    if (r > 5.0) {
      brush.set("pinpoint", "#FFF8EC", 0.65);
      brush.line(b.x + r * 0.18, b.y + ry * 0.62, b.x + r * 0.28, b.y + ry * 0.58);
    }
  }
}

