// Primary Isometric Axis: angle 40 deg through Origin (578, 552)
const ORIGIN = { x: 578, y: 552 };
const AXIS_MAIN_DEG = 40;
const AXIS_SEQ_DEG = -26;

function isoMainPt(s, offsetPerp = 0) {
  let rad = radians(AXIS_MAIN_DEG);
  let perp = radians(AXIS_MAIN_DEG - 90);
  return {
    x: ORIGIN.x + cos(rad) * s + cos(perp) * offsetPerp,
    y: ORIGIN.y + sin(rad) * s + sin(perp) * offsetPerp
  };
}

function isoSeqPt(t, offsetPerp = 0) {
  let rad = radians(AXIS_SEQ_DEG);
  let perp = radians(AXIS_SEQ_DEG - 90);
  return {
    x: ORIGIN.x + cos(rad) * t + cos(perp) * offsetPerp,
    y: ORIGIN.y + sin(rad) * t + sin(perp) * offsetPerp
  };
}

function resetBrushState() {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.noField();
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(42719);
  noiseSeed(1842);

  // Add a fine coloured-pencil detail brush for crisp vesicle & pore highlights
  brush.add("cpencil_fine", {
    type: "default",
    weight: 0.45,
    scatter: 0.12,
    sharpness: 0.78,
    grain: 14,
    opacity: 210,
    spacing: 0.15,
    pressure: [0.6, 1.15, 0.5],
    noise: 0.35
  });
}

function draw() {
  translate(-width / 2, -height / 2);

  // 1. Warm grey drafting vellum ground & architectural border
  drawVellumGround();

  // 2. Faint isometric construction lines, ellipses, and bounding geometry
  drawConstructionGeometry();

  // 3. Background dashed axis segments (behind botanical elements)
  drawBackExplosionAxes();

  // 4. Station 1: Detached Calyx & Upper Split Peel Shell (pocked oily rind)
  const ptCalyx = isoMainPt(-455);
  const ptUpperPeel = isoMainPt(-310);
  drawUpperPeelShell(ptUpperPeel.x, ptUpperPeel.y);
  drawCalyxLinkAndButton(ptCalyx.x, ptCalyx.y, ptUpperPeel.x, ptUpperPeel.y);

  // 5. Station 2: Free-floating Pith Web (columella & vascular bundle cage)
  const ptPithWeb = isoMainPt(-115);
  drawPithWeb(ptPithWeb.x, ptPithWeb.y);

  // 6. Station 3: Lower-left & central radial exploded segments
  drawRadialLowerSegments();

  // 7. Station 4: Ordered Isometric Sequence of Segments + Glistening Vesicles + Seed
  drawOrderedSegmentSequence();

  // 8. Station 5: Lower Split Peel Shell (cupped interior spongy albedo view)
  const ptLowerPeel = isoMainPt(365);
  drawLowerPeelShell(ptLowerPeel.x, ptLowerPeel.y);

  // 9. Foreground dashed axis connectors, ruled graphite leader lines & blank callouts
  drawForegroundAxesAndCallouts(ptCalyx, ptUpperPeel, ptPithWeb, ptLowerPeel);

  noLoop();
}

// ============================================================================
// 1. VELLUM GROUND & ARCHITECTURAL BORDER
// ============================================================================
function drawVellumGround() {
  background(PAL.vellumBg);
  resetBrushState();

  // Warm central vellum luminosity
  brush.noStroke();
  brush.fillBleed(0.08, "out");
  brush.fillTexture(0.35, 0.15);
  brush.fill(PAL.vellumLight, 65);
  brush.circle(600, 560, 480, 0.05);

  brush.fill(PAL.vellumWarm, 45);
  brush.circle(620, 520, 340, 0.08);

  // Subtle corner toning
  brush. wash(PAL.vellumDark, 28);
  brush.rect(0, 0, 1200, 70, "corner");
  brush.rect(0, 1130, 1200, 70, "corner");
  brush.noWash();
  brush.noFill();

  // Fine vellum paper tooth using sparse 2H cross-grain and subtle spray
  brush.set("spray", PAL.vellumDark, 0.6);
  for (let i = 0; i < 45; i++) {
    let x1 = random(60, 1140);
    let y1 = random(60, 1140);
    let ang = random(-15, 15);
    brush.line(x1, y1, x1 + cos(ang) * random(80, 220), y1 + sin(ang) * random(80, 220));
  }

  brush.set("spray", PAL.vellumLight, 0.5);
  for (let i = 0; i < 35; i++) {
    let x1 = random(80, 1120);
    let y1 = random(80, 1120);
    brush.line(x1, y1, x1 + random(-140, 140), y1 + random(-40, 40));
  }

  // Ruled drafting sheet borders
  resetBrushState();
  brush.set("2H", PAL.graphiteMid, 0.55);
  brush.rect(38, 38, 1124, 1124, "corner");
  brush.set("2H", PAL.graphiteFaint, 0.38);
  brush.rect(46, 46, 1108, 1108, "corner");

  // Grid reference tick marks along sheet border
  brush.set("2H", PAL.graphiteMid, 0.45);
  for (let pos = 150; pos <= 1050; pos += 150) {
    brush.line(pos, 38, pos, 46);
    brush.line(pos, 1154, pos, 1162);
    brush.line(38, pos, 46, pos);
    brush.line(1154, pos, 1162, pos);
  }

  // Corner registration crosshairs
  const corners = [[72, 72], [1128, 72], [72, 1128], [1128, 1128]];
  for (let [cx, cy] of corners) {
    brush.set("2H", PAL.graphiteMid, 0.4);
    brush.line(cx - 12, cy, cx + 12, cy);
    brush.line(cx, cy - 12, cx, cy + 12);
    brush.circle(cx, cy, 6, 0.02);
  }

  // Minimal geometric scale & isometric triad key at bottom-left (no text)
  drawDraftingKey(112, 1072);
}

function drawDraftingKey(kx, ky) {
  resetBrushState();
  // Isometric triad icon
  brush.set("2H", PAL.graphiteMid, 0.5);
  brush.circle(kx, ky - 42, 22, 0.02);
  brush.circle(kx, ky - 42, 4, 0.01);
  let angles = [AXIS_MAIN_DEG, AXIS_SEQ_DEG, -90, AXIS_MAIN_DEG + 180];
  for (let a of angles) {
    brush.line(kx, ky - 42, kx + cos(a) * 30, ky - 42 + sin(a) * 30);
  }

  // Graduated graphic scale bar
  let bx = kx - 24;
  let by = ky + 10;
  brush.set("2H", PAL.graphiteMid, 0.48);
  brush.rect(bx, by, 160, 8, "corner");
  brush.line(bx, by + 4, bx + 160, by + 4);
  for (let i = 0; i <= 8; i++) {
    let tx = bx + i * 20;
    brush.line(tx, by - 4, tx, by + 12);
    if (i < 8 && i % 2 === 0) {
      brush.noStroke();
      brush.wash(PAL.graphiteMid, 95);
      brush.rect(tx, by, 20, 4, "corner");
      brush.noWash();
      brush.set("2H", PAL.graphiteMid, 0.45);
    }
  }
}

// ============================================================================
// 2. FAINT CONSTRUCTION GEOMETRY
// ============================================================================
function drawConstructionGeometry() {
  resetBrushState();

  // Faint background isometric grid lines across the vellum
  brush.set("2H", PAL.graphiteFaint, 0.28);
  for (let offset = -360; offset <= 360; offset += 120) {
    let p1 = isoMainPt(-520, offset);
    let p2 = isoMainPt(520, offset);
    brush.line(p1.x, p1.y, p2.x, p2.y);
  }
  for (let s = -450; s <= 450; s += 150) {
    let p1 = isoMainPt(s, -420);
    let p2 = isoMainPt(s, 420);
    brush.line(p1.x, p1.y, p2.x, p2.y);
  }

  // Extended primary polar axis & conjugate sequence axis (faint continuous hairlines)
  let mStart = isoMainPt(-520);
  let mEnd = isoMainPt(510);
  brush.set("2H", PAL.graphiteMid, 0.35);
  brush.line(mStart.x, mStart.y, mEnd.x, mEnd.y);

  let sStart = isoSeqPt(-380);
  let sEnd = isoSeqPt(520);
  brush.line(sStart.x, sStart.y, sEnd.x, sEnd.y);

  // Secondary parallel sequence tracks (top and bottom datum rails for fanned segments)
  for (let off of [-76, 76, 152]) {
    let r1 = isoSeqPt(20, off);
    let r2 = isoSeqPt(495, off);
    brush.set("2H", PAL.graphiteFaint, 0.32);
    brush.line(r1.x, r1.y, r2.x, r2.y);
  }

  // Isometric datum ellipses perpendicular to main axis
  const ellipseStations = [
    { s: -310, rx: 122, ry: 78, dashed: false },
    { s: -115, rx: 86, ry: 55, dashed: true },
    { s: 0, rx: 145, ry: 92, dashed: false },
    { s: 0, rx: 68, ry: 43, dashed: true },
    { s: 365, rx: 128, ry: 82, dashed: false }
  ];

  for (let st of ellipseStations) {
    let c = isoMainPt(st.s);
    if (st.dashed) {
      drawTiltedDashedEllipse(c.x, c.y, st.rx, st.ry, AXIS_MAIN_DEG - 90, 48, "2H", PAL.graphiteMid, 0.38);
    } else {
      drawTiltedEllipse(c.x, c.y, st.rx, st.ry, AXIS_MAIN_DEG - 90, 64, "2H", PAL.graphiteFaint, 0.34);
    }
    // Major and minor axis ticks on the ellipse
    let a1 = AXIS_MAIN_DEG - 90;
    let a2 = AXIS_MAIN_DEG;
    brush.set("2H", PAL.graphiteFaint, 0.34);
    brush.line(c.x - cos(a1) * (st.rx + 14), c.y - sin(a1) * (st.rx + 14),
               c.x + cos(a1) * (st.rx + 14), c.y + sin(a1) * (st.rx + 14));
    brush.line(c.x - cos(a2) * (st.ry + 14), c.y - sin(a2) * (st.ry + 14),
               c.x + cos(a2) * (st.ry + 14), c.y + sin(a2) * (st.ry + 14));
  }

  // 10 radial carpel division rays on the central Origin datum plane
  for (let i = 0; i < 10; i++) {
    let th = i * 36 + 12;
    let pOuter = pointOnTiltedEllipse(ORIGIN.x, ORIGIN.y, 165, 105, AXIS_MAIN_DEG - 90, th);
    brush.set("2H", PAL.graphiteFaint, 0.3);
    brush.line(ORIGIN.x, ORIGIN.y, pOuter.x, pOuter.y);
  }

  // Construction bounding boxes around the ordered segment sequence stations
  const seqSteps = [105, 225, 348, 468];
  for (let t of seqSteps) {
    let sc = isoSeqPt(t, -12);
    drawIsometricDiamondBox(sc.x, sc.y, 62, 108, -18, "2H", PAL.graphiteFaint, 0.3);
  }

  // Construction datum around the single seed at (960, 505)
  drawTiltedEllipse(960, 505, 44, 28, -28, 36, "2H", PAL.graphiteFaint, 0.32);
  brush.set("2H", PAL.graphiteFaint, 0.32);
  brush.line(900, 535, 1020, 475);
  brush.line(935, 455, 985, 555);
}

function pointOnTiltedEllipse(cx, cy, rx, ry, rotDeg, paramDeg) {
  let lx = cos(paramDeg) * rx;
  let ly = sin(paramDeg) * ry;
  return {
    x: cx + lx * cos(rotDeg) - ly * sin(rotDeg),
    y: cy + lx * sin(rotDeg) + ly * cos(rotDeg)
  };
}

function drawTiltedEllipse(cx, cy, rx, ry, rotDeg, steps, brushName, col, weight) {
  resetBrushState();
  brush.set(brushName, col, weight);
  let pts = [];
  for (let i = 0; i <= steps; i++) {
    let p = pointOnTiltedEllipse(cx, cy, rx, ry, rotDeg, (i / steps) * 360);
    pts.push([p.x, p.y]);
  }
  brush.spline(pts, 0.3);
}

function drawTiltedDashedEllipse(cx, cy, rx, ry, rotDeg, numDashes, brushName, col, weight) {
  resetBrushState();
  brush.set(brushName, col, weight);
  let stepDeg = 360 / numDashes;
  for (let i = 0; i < numDashes; i++) {
    let a1 = i * stepDeg;
    let a2 = a1 + stepDeg * 0.58;
    let p1 = pointOnTiltedEllipse(cx, cy, rx, ry, rotDeg, a1);
    let p2 = pointOnTiltedEllipse(cx, cy, rx, ry, rotDeg, a2);
    brush.line(p1.x, p1.y, p2.x, p2.y);
  }
}

function drawIsometricDiamondBox(cx, cy, w, h, rotDeg, brushName, col, weight) {
  resetBrushState();
  brush.set(brushName, col, weight);
  let corners = [[-w, -h], [w, -h], [w, h], [-w, h]];
  let rPts = corners.map(([lx, ly]) => ({
    x: cx + lx * cos(rotDeg) - ly * sin(rotDeg),
    y: cy + lx * sin(rotDeg) + ly * cos(rotDeg)
  }));
  for (let i = 0; i < 4; i++) {
    let n = (i + 1) % 4;
    brush.line(rPts[i].x, rPts[i].y, rPts[n].x, rPts[n].y);
  }
}

function drawDashedLine(x1, y1, x2, y2, dashLen, gapLen, brushName, col, weight, centerDot = false) {
  resetBrushState();
  brush.set(brushName, col, weight);
  let d = dist(x1, y1, x2, y2);
  if (d < 1) return;
  let ux = (x2 - x1) / d;
  let uy = (y2 - y1) / d;
  let pos = 0;
  while (pos < d) {
    let segEnd = min(pos + dashLen, d);
    brush.line(x1 + ux * pos, y1 + uy * pos, x1 + ux * segEnd, y1 + uy * segEnd);
    if (centerDot && segEnd + gapLen * 0.5 < d) {
      let dotP = segEnd + gapLen * 0.5;
      brush.line(x1 + ux * (dotP - 1.2), y1 + uy * (dotP - 1.2),
                 x1 + ux * (dotP + 1.2), y1 + uy * (dotP + 1.2));
    }
    pos += dashLen + gapLen;
  }
}

function drawBackExplosionAxes() {
  // Dashed explosion trajectories connecting origin to all stations
  let p1 = isoMainPt(-455);
  let p2 = isoMainPt(365);
  drawDashedLine(p1.x, p1.y, p2.x, p2.y, 14, 9, "HB", PAL.graphiteDark, 0.55, true);

  let s1 = isoSeqPt(-290);
  let s2 = isoSeqPt(475);
  drawDashedLine(s1.x, s1.y, s2.x, s2.y, 12, 8, "HB", PAL.graphiteDark, 0.52, true);

  // Radial dashed trajectories to lower-left segments
  drawDashedLine(ORIGIN.x, ORIGIN.y, 355, 720, 10, 7, "2H", PAL.graphiteDark, 0.48, false);
  drawDashedLine(ORIGIN.x, ORIGIN.y, 465, 655, 10, 7, "2H", PAL.graphiteDark, 0.48, false);
  drawDashedLine(ORIGIN.x, ORIGIN.y, 608, 690, 10, 7, "2H", PAL.graphiteDark, 0.48, false);

  // Offset dashed datum from sequence Step 3/4 to the hovering single seed
  let pStep3 = isoSeqPt(348, -12);
  drawDashedLine(pStep3.x, pStep3.y, 885, 425, 9, 6, "2H", PAL.graphiteDark, 0.48, false);
  drawDashedLine(885, 425, 960, 505, 9, 6, "2H", PAL.graphiteDark, 0.48, false);
}

// ============================================================================
// 4. STATION 1: UPPER SPLIT PEEL SHELL & DETACHED CALYX
// ============================================================================
function drawUpperPeelShell(cx, cy) {
  resetBrushState();

  // Outer 4-lobed split dome silhouette
  // We first draw the shadowed inner cavity visible at the lower-right open rim & tear notches
  let innerRimPts = [];
  for (let a = -55; a <= 135; a += 10) {
    let p = pointOnTiltedEllipse(cx + 12, cy + 14, 104, 66, AXIS_MAIN_DEG - 90, a);
    innerRimPts.push([p.x, p.y]);
  }
  for (let a = 135; a >= -55; a -= 10) {
    let p = pointOnTiltedEllipse(cx - 8, cy - 6, 82, 48, AXIS_MAIN_DEG - 90, a);
    innerRimPts.push([p.x, p.y]);
  }
  let innerPoly = new brush.Polygon(innerRimPts);
  innerPoly.wash(PAL.pithWarm, 190);
  innerPoly.fill(PAL.pithShadow, 85, 0.04, 0.3);

  // Build the 4-lobed outer peel dome contour
  let domePts = [];
  const numPts = 72;
  for (let i = 0; i < numPts; i++) {
    let ang = (i / numPts) * 360;
    // Create 4 organic split notches at angles 25, 115, 205, 295
    let notch1 = exp(-pow(angleDiff(ang, 28) / 11, 2)) * 28;
    let notch2 = exp(-pow(angleDiff(ang, 118) / 10, 2)) * 22;
    let notch3 = exp(-pow(angleDiff(ang, 212) / 12, 2)) * 16;
    let notch4 = exp(-pow(angleDiff(ang, 302) / 10, 2)) * 20;

    // Slight organic bulge on the 4 petal lobes
    let lobeBulge = sin(ang * 4) * 5;
    let rx = 126 - notch1 - notch2 - notch3 - notch4 + lobeBulge;
    let ry = 88 - (notch1 + notch2 + notch3 + notch4) * 0.68 + lobeBulge * 0.6;

    // Dome arching upward-left toward (-140 deg)
    let domeLift = (sin(ang + 135) - 0.2) * 18;
    let p = pointOnTiltedEllipse(cx - 8, cy - 10, rx, ry, AXIS_MAIN_DEG - 90, ang);
    domePts.push([p.x - domeLift * 0.45, p.y - domeLift * 0.55]);
  }

  // Draw creamy-white spongy albedo thickness along the lower/notched rim before the orange epicarp
  let albedoEdgePts = domePts.map(([px, py], idx) => {
    let ang = (idx / numPts) * 360;
    // Rim thickness visible on the front-facing hemisphere (-45 to 155 deg)
    let frontFactor = max(0, sin(ang - 35));
    return [px + frontFactor * 6.5, py + frontFactor * 5.8];
  });
  let albedoPoly = new brush.Polygon(albedoEdgePts);
  albedoPoly.wash(PAL.pithIvory, 235);

  // Base opaque wash of soft pastel apricot-tangerine for the epicarp
  let domePoly = new brush.Polygon(domePts);
  domePoly.wash(PAL.rindApricot, 240);
  domePoly.fill(PAL.rindTangerine, 110, 0.03, 0.35);

  // Layered coloured-pencil form shading across the dome
  // 1) Core shadow zone (lower-right curve of dome)
  let shadowPts = [];
  for (let a = -30; a <= 130; a += 12) {
    let p = pointOnTiltedEllipse(cx + 8, cy + 8, 108, 72, AXIS_MAIN_DEG - 90, a);
    shadowPts.push([p.x, p.y]);
  }
  for (let a = 130; a >= -30; a -= 12) {
    let p = pointOnTiltedEllipse(cx - 18, cy - 16, 62, 42, AXIS_MAIN_DEG - 90, a);
    shadowPts.push([p.x, p.y]);
  }
  let shadowPoly = new brush.Polygon(shadowPts);
  shadowPoly.fill(PAL.rindCoral, 95, 0.05, 0.4);
  brush.hatchStyle("cpencil", PAL.rindTerra, 0.65);
  shadowPoly.hatch(3.5, AXIS_MAIN_DEG - 35, { rand: 0.08 });

  // 2) Cool pastel lavender-sage reflected light along the very edge of the lower-right rim
  resetBrushState();
  brush.set("cpencil", PAL.rindCoolRefl, 0.9);
  for (let a = -15; a <= 105; a += 4) {
    if (abs(angleDiff(a, 28)) < 12) continue;
    let p1 = pointOnTiltedEllipse(cx - 5, cy - 7, 114, 78, AXIS_MAIN_DEG - 90, a);
    let p2 = pointOnTiltedEllipse(cx - 5, cy - 7, 118, 81, AXIS_MAIN_DEG - 90, a + 3);
    brush.line(p1.x, p1.y, p2.x, p2.y);
  }

  // 3) Luminous peach & melon crown on the upper-left lit hemisphere
  let crownPts = [];
  for (let i = 0; i < 36; i++) {
    let a = (i / 36) * 360;
    let p = pointOnTiltedEllipse(cx - 28, cy - 26, 74, 52, AXIS_MAIN_DEG - 90, a);
    crownPts.push([p.x, p.y]);
  }
  let crownPoly = new brush.Polygon(crownPts);
  crownPoly.wash(PAL.rindPeach, 150);
  brush.hatchStyle("cpencil", PAL.rindMelon, 0.7);
  crownPoly.hatch(3.2, AXIS_MAIN_DEG + 45, { rand: 0.06 });

  // 4) Fine directional coloured-pencil meridian strokes following the 3D dome curvature
  resetBrushState();
  let apexX = cx - 34;
  let apexY = cy - 30;
  for (let i = 0; i < 68; i++) {
    let ang = (i / 68) * 360;
    // Skip deep inside tear notches
    let inNotch = (abs(angleDiff(ang, 28)) < 7 || abs(angleDiff(ang, 118)) < 6 ||
                   abs(angleDiff(ang, 212)) < 7 || abs(angleDiff(ang, 302)) < 6);
    if (inNotch) continue;

    let edgePt = domePts[floor((i / 68) * numPts) % numPts];
    let midX = lerp(apexX, edgePt[0], 0.55) + cos(ang - 90) * 6;
    let midY = lerp(apexY, edgePt[1], 0.55) + sin(ang - 90) * 6;

    let isLit = cos(ang - 215) > 0;
    let strokeCol = isLit ? (i % 2 === 0 ? PAL.rindPeach : PAL.rindApricot)
                          : (i % 2 === 0 ? PAL.rindCoral : PAL.rindTerra);
    brush.set("cpencil", strokeCol, 0.55);
    brush.spline([
      [lerp(apexX, midX, 0.22), lerp(apexY, midY, 0.22), 0.5],
      [midX, midY, 0.9],
      [lerp(midX, edgePt[0], 0.92), lerp(midY, edgePt[1], 0.92), 0.5]
    ], 0.35);
  }

  // 5) POCKED OILY RIND TEXTURE: ~260 dimpled oil glands following surface perspective
  renderOilGlandPores(cx - 10, cy - 12, 116, 78, apexX, apexY, domePts);

  // 6) Spongy white albedo edge detailing & torn pith fibres at the 4 split notches
  resetBrushState();
  for (let idx = 0; idx < numPts; idx++) {
    let ang = (idx / numPts) * 360;
    let nextIdx = (idx + 1) % numPts;
    let p1 = domePts[idx];
    let p2 = domePts[nextIdx];
    let ap1 = albedoEdgePts[idx];
    let ap2 = albedoEdgePts[nextIdx];

    if (dist(p1[0], p1[1], ap1[0], ap1[1]) > 1.8) {
      brush.set("cpencil", PAL.pithCream, 0.75);
      brush.line(ap1[0], ap1[1], ap2[0], ap2[1]);
      brush.set("cpencil_fine", PAL.white, 0.65);
      brush.line(p1[0], p1[1], ap1[0], ap1[1]);
      brush.set("2H", PAL.pithShadow, 0.4);
      brush.line(ap1[0], ap1[1], ap2[0], ap2[1]);
    }
    // Crisp outer contour in coloured pencil
    brush.set("cpencil", ang > 140 && ang < 310 ? PAL.rindCoral : PAL.rindDeep, 0.48);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // Torn fibrous white pith threads protruding slightly from the V-notches
  const notchAngles = [28, 118, 212, 302];
  for (let na of notchAngles) {
    let idx = floor(((na + 360) % 360) / 360 * numPts);
    let np = domePts[idx];
    brush.set("cpencil_fine", PAL.pithIvory, 0.55);
    for (let f = -2; f <= 2; f++) {
      let fa = na + f * 8;
      brush.line(np[0], np[1], np[0] + cos(fa) * random(7, 13), np[1] + sin(fa) * random(7, 13));
    }
  }

  // 7) Apical stem scar ring on the upper-left crown of the dome
  drawStemScarOnRind(apexX, apexY);
}

function renderOilGlandPores(cx, cy, rx, ry, apexX, apexY, boundaryPts) {
  resetBrushState();
  // Golden-angle phyllotaxis spiral distribution over the dome for natural pore spacing
  const numPores = 250;
  for (let i = 4; i < numPores; i++) {
    let rNorm = sqrt(i / numPores) * 0.94;
    let theta = i * 137.508;

    let px = cx + cos(theta) * rx * rNorm;
    let py = cy + sin(theta) * ry * rNorm;

    // Check if inside any of the 4 tear notches
    let ang = (atan2(py - cy, px - cx) + 360) % 360;
    if ((abs(angleDiff(ang, 28)) < 11 && rNorm > 0.68) ||
        (abs(angleDiff(ang, 118)) < 10 && rNorm > 0.72) ||
        (abs(angleDiff(ang, 212)) < 11 && rNorm > 0.75) ||
        (abs(angleDiff(ang, 302)) < 10 && rNorm > 0.72)) {
      continue;
    }

    // Distance to light source (upper-left)
    let dLight = dist(px, py, apexX - 18, apexY - 18);
    let poreSize = map(rNorm, 0, 1, 2.4, 1.5);

    // 1. Concave dimple shadow (darker coral/terracotta dot/short stroke on upper-left of pore)
    let darkCol = dLight < 55 ? PAL.rindCoral : (dLight < 95 ? PAL.rindTerra : PAL.rindDeep);
    brush.set("cpencil_fine", darkCol, poreSize * 0.55);
    brush.line(px - 0.9, py - 0.7, px + 0.7, py + 0.5);

    // 2. Specular oil-gland rim highlight on lower-right lip of dimple
    if (dLight < 68) {
      // High-gloss specular zone: crisp bright white & cream pinpricks
      brush.set("cpencil_fine", PAL.white, poreSize * 0.65);
      brush.line(px + 0.8, py + 0.8, px + 2.1, py + 1.4);
    } else if (dLight < 115) {
      brush.set("cpencil_fine", PAL.rindMelon, poreSize * 0.5);
      brush.line(px + 0.7, py + 0.7, px + 1.7, py + 1.2);
    }
  }

  // Broad glistening oil-sheen specular cluster on the crown of the dome
  for (let k = 0; k < 28; k++) {
    let a = random(0, 360);
    let r = random(8, 36);
    let hx = apexX - 10 + cos(a) * r * 1.1;
    let hy = apexY - 8 + sin(a) * r * 0.8;
    brush.set("cpencil_fine", PAL.white, random(0.7, 1.25));
    brush.line(hx, hy, hx + random(1.8, 4.2), hy + random(1.2, 2.8));
  }
}

function drawStemScarOnRind(ax, ay) {
  resetBrushState();
  // Recessed pale-ochre & cream navel/calyx socket
  let scarPts = [];
  for (let i = 0; i < 16; i++) {
    let a = (i / 16) * 360;
    let p = pointOnTiltedEllipse(ax, ay, 14, 9.5, AXIS_MAIN_DEG - 90, a);
    scarPts.push([p.x, p.y]);
  }
  let scarPoly = new brush.Polygon(scarPts);
  scarPoly.wash(PAL.pithWarm, 230);

  brush.set("cpencil_fine", PAL.rindDeep, 0.55);
  for (let i = 0; i < 16; i++) {
    let p1 = scarPts[i];
    let p2 = scarPts[(i + 1) % 16];
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
  // Tiny radial vascular dots inside the stem socket
  brush.set("cpencil_fine", PAL.calyxDeep, 0.6);
  for (let i = 0; i < 8; i++) {
    let a = i * 45;
    brush.line(ax + cos(a) * 3, ay + sin(a) * 2, ax + cos(a) * 7, ay + sin(a) * 5);
  }
  brush.set("cpencil_fine", PAL.pithIvory, 0.7);
  brush.circle(ax, ay, 3.5, 0.1);
}

function drawCalyxLinkAndButton(cx, cy, peelX, peelY) {
  let scarX = peelX - 34;
  let scarY = peelY - 30;
  // Dashed connector between calyx button and stem scar on upper peel
  drawDashedLine(cx, cy, scarX, scarY, 8, 6, "HB", PAL.graphiteDark, 0.55, false);

  resetBrushState();
  // 5-pointed star calyx (pastel sage green & woody ochre)
  let starPts = [];
  for (let i = 0; i < 10; i++) {
    let a = i * 36 - 20;
    let r = i % 2 === 0 ? 22 : 9.5;
    let p = pointOnTiltedEllipse(cx, cy, r * 1.15, r * 0.82, AXIS_MAIN_DEG - 90, a);
    starPts.push([p.x, p.y]);
  }
  let starPoly = new brush.Polygon(starPts);
  starPoly.wash(PAL.calyxSage, 235);
  starPoly.fill(PAL.calyxOlive, 110, 0.03, 0.3);

  // Shaded sepal tips and woody pedicel stub
  resetBrushState();
  for (let i = 0; i < 10; i++) {
    let p1 = starPts[i];
    let p2 = starPts[(i + 1) % 10];
    brush.set("cpencil_fine", PAL.calyxDeep, 0.55);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
    if (i % 2 === 0) {
      brush.set("cpencil_fine", PAL.calyxOlive, 0.6);
      brush.line(cx, cy, p1[0], p1[1]);
    }
  }

  // Short woody stem cylinder rising toward (-140 deg)
  let stemTopX = cx - 12;
  let stemTopY = cy - 10;
  brush.set("cpencil", PAL.calyxOchre, 1.8);
  brush.line(cx, cy, stemTopX, stemTopY);
  brush.set("cpencil_fine", PAL.calyxDeep, 0.6);
  brush.line(cx + 2, cy + 2, stemTopX + 2, stemTopY + 2);
  brush.set("cpencil_fine", PAL.pithIvory, 0.75);
  brush.circle(stemTopX, stemTopY, 4.5, 0.08);
}

// ============================================================================
// 5. STATION 2: FREE-FLOATING PITH WEB (COLUMELLA & VASCULAR BUNDLE CAGE)
// ============================================================================
function drawPithWeb(cx, cy) {
  resetBrushState();

  // Axis endpoints of the central pith column (tilted along main axis 40 deg)
  let topPole = { x: cx - cos(AXIS_MAIN_DEG) * 44, y: cy - sin(AXIS_MAIN_DEG) * 44 };
  let botPole = { x: cx + cos(AXIS_MAIN_DEG) * 44, y: cy + sin(AXIS_MAIN_DEG) * 44 };

  // 1) Back-hemisphere meridian vascular arches (darker warm greige so they recede in 3D)
  for (let i = 0; i < 6; i++) {
    let ang = map(i, 0, 5, 165, 345);
    let eqPt = pointOnTiltedEllipse(cx, cy, 82, 54, AXIS_MAIN_DEG - 90, ang);
    drawFibrousArch(topPole, eqPt, botPole, PAL.pithShadowDeep, PAL.pithWarm, 0.52, true);
  }

  // 2) Central twisted columella bundle (spongy white core column with flared crown & base)
  for (let s = -4; s <= 4; s++) {
    let off = s * 2.4;
    let perp = AXIS_MAIN_DEG - 90;
    let p1 = { x: topPole.x + cos(perp) * off * 1.7, y: topPole.y + sin(perp) * off * 1.7 };
    let pMid = { x: cx + cos(perp) * off * 0.75 + random(-2, 2), y: cy + sin(perp) * off * 0.75 + random(-2, 2) };
    let p2 = { x: botPole.x + cos(perp) * off * 1.9, y: botPole.y + sin(perp) * off * 1.9 };

    // Shadow under-stroke
    brush.set("cpencil", PAL.pithShadow, 0.75);
    brush.spline([[p1.x + 1.5, p1.y + 1.5], [pMid.x + 1.5, pMid.y + 1.5], [p2.x + 1.5, p2.y + 1.5]], 0.4);

    // Cream & bright white fibrous core strands
    brush.set("cpencil", s < 0 ? PAL.white : PAL.pithIvory, 0.85);
    brush.spline([[p1.x, p1.y], [pMid.x, pMid.y], [p2.x, p2.y]], 0.4);
  }

  // 3) Radial septal filaments radiating from the central column
  for (let r = 0; r < 14; r++) {
    let t = random(0.2, 0.8);
    let ax = lerp(topPole.x, botPole.x, t);
    let ay = lerp(topPole.y, botPole.y, t);
    let ang = random(0, 360);
    let eqPt = pointOnTiltedEllipse(cx, cy, random(45, 78), random(28, 50), AXIS_MAIN_DEG - 90, ang);
    brush.set("cpencil_fine", PAL.pithShadow, 0.42);
    brush.line(ax + 1, ay + 1, eqPt.x + 1, eqPt.y + 1);
    brush.set("cpencil_fine", PAL.pithIvory, 0.5);
    brush.line(ax, ay, eqPt.x, eqPt.y);
  }

  // 4) Front-hemisphere meridian vascular arches & lacy branching net
  let frontEqPts = [];
  for (let i = 0; i < 7; i++) {
    let ang = map(i, 0, 6, -15, 160);
    let eqPt = pointOnTiltedEllipse(cx, cy, 86, 56, AXIS_MAIN_DEG - 90, ang);
    frontEqPts.push(eqPt);
    drawFibrousArch(topPole, eqPt, botPole, PAL.pithShadow, PAL.white, 0.72, false);
  }

  // Secondary diagonal cross-strands forming the delicate citrus albedo mesh between front ribs
  for (let i = 0; i < frontEqPts.length - 1; i++) {
    let a = frontEqPts[i];
    let b = frontEqPts[i + 1];
    for (let k = 0; k < 5; k++) {
      let u1 = random(0.2, 0.85);
      let u2 = constrain(u1 + random(-0.22, 0.22), 0.15, 0.9);
      let pA = sampleArchPoint(topPole, a, botPole, u1);
      let pB = sampleArchPoint(topPole, b, botPole, u2);
      let mid = {
        x: (pA.x + pB.x) * 0.5 + random(-4, 4),
        y: (pA.y + pB.y) * 0.5 + random(-4, 4)
      };
      brush.set("cpencil_fine", PAL.pithShadow, 0.42);
      brush.spline([[pA.x + 1, pA.y + 1], [mid.x + 1, mid.y + 1], [pB.x + 1, pB.y + 1]], 0.35);
      brush.set("cpencil_fine", PAL.white, 0.55);
      brush.spline([[pA.x, pA.y], [mid.x, mid.y], [pB.x, pB.y]], 0.35);
    }
  }

  // Flared fibrous tufts at the top and bottom poles of the pith cage
  for (let pole of [topPole, botPole]) {
    for (let j = 0; j < 12; j++) {
      let a = random(0, 360);
      let len = random(8, 18);
      brush.set("cpencil_fine", PAL.pithShadow, 0.45);
      brush.line(pole.x + 1, pole.y + 1, pole.x + cos(a) * len + 1, pole.y + sin(a) * len + 1);
      brush.set("cpencil_fine", PAL.white, 0.65);
      brush.line(pole.x, pole.y, pole.x + cos(a) * len, pole.y + sin(a) * len);
    }
  }
}

function sampleArchPoint(topP, midP, botP, t) {
  // Quadratic Bezier interpolation through topP -> control -> botP passing near midP at t=0.5
  let ctrlX = 2 * midP.x - 0.5 * (topP.x + botP.x);
  let ctrlY = 2 * midP.y - 0.5 * (topP.y + botP.y);
  let u = 1 - t;
  return {
    x: u * u * topP.x + 2 * u * t * ctrlX + t * t * botP.x,
    y: u * u * topP.y + 2 * u * t * ctrlY + t * t * botP.y
  };
}

function drawFibrousArch(topP, midP, botP, shadowCol, lightCol, weight, isBack) {
  resetBrushState();
  let ptsShadow = [];
  let ptsLight = [];
  let ptsWisp = [];
  for (let s = 0; s <= 10; s++) {
    let t = s / 10;
    let p = sampleArchPoint(topP, midP, botP, t);
    let jitterX = sin(s * 55) * 1.6;
    let jitterY = cos(s * 48) * 1.6;
    ptsShadow.push([p.x + jitterX + 1.4, p.y + jitterY + 1.4]);
    ptsLight.push([p.x + jitterX, p.y + jitterY]);
    ptsWisp.push([p.x - jitterX * 1.1, p.y - jitterY * 1.1]);
  }
  brush.set("cpencil_fine", shadowCol, weight * 0.9);
  brush.spline(ptsShadow, 0.35);

  brush.set("cpencil", isBack ? PAL.pithCream : lightCol, weight);
  brush.spline(ptsLight, 0.35);

  if (!isBack) {
    brush.set("cpencil_fine", PAL.pithIvory, weight * 0.7);
    brush.spline(ptsWisp, 0.4);
  }
}

// ============================================================================
// 6 & 7. MANDARIN SEGMENTS (RADIAL RING + ORDERED ISOMETRIC SEQUENCE + SEED)
// ============================================================================
function drawRadialLowerSegments() {
  // Three radial segments in the lower-left / bottom of the central ring
  // 1) Far lower-left (355, 720): Dorsal curved back covered in netted white pith strands
  drawMandarinSegment(355, 720, 1.02, 22, "dorsal_back");

  // 2) Mid lower-left (468, 658): Wedge side view showing flat radial septum & inner core notch
  drawMandarinSegment(468, 658, 0.98, 8, "wedge_side");

  // 3) Lower-center (608, 690): Wedge side view tilted along the bottom of the ring
  drawMandarinSegment(608, 690, 0.96, -14, "wedge_side");
}

function drawOrderedSegmentSequence() {
  // Ordered isometric sequence fanning outward toward the upper-right along AXIS_SEQ_DEG (-26 deg)
  const p1 = isoSeqPt(105, -12);
  const p2 = isoSeqPt(225, -12);
  const p3 = isoSeqPt(348, -12);
  const p4 = isoSeqPt(468, -12);

  // Step 1: Intact carpel segment with papery translucent membrane & pith veining
  drawMandarinSegment(p1.x, p1.y, 0.98, -18, "intact_iso");

  // Step 2: Semi-translucent segment with internal juice vesicles glowing through membrane
  drawMandarinSegment(p2.x, p2.y, 1.0, -18, "translucent_iso");

  // Step 3: Segment with papery carpel membrane peeled open & curled back
  drawMandarinSegment(p3.x, p3.y, 1.02, -18, "peeled_open");

  // Step 4: Fully dissected segment composed of glistening, jewel-like pulp vesicles
  drawMandarinSegment(p4.x, p4.y, 1.04, -18, "naked_vesicles");

  // Loose detached glistening juice vesicles hovering between Step 3/4 and the Seed
  drawSingleVesicle(902, 412, 26, 9.5, -35, PAL.vesicleCoral, PAL.vesicleGold);
  drawSingleVesicle(926, 434, 24, 8.8, -18, PAL.vesicleSalmon, PAL.vesicleApricot);
  drawSingleVesicle(882, 444, 21, 8.0, -48, PAL.vesicleCoral, PAL.rindMelon);

  // Hovering Single Seed at (960, 505)
  drawSingleSeed(960, 505, -28);
}

function transformSegPt(cx, cy, scaleFactor, rotDeg, lx, ly) {
  let sx = lx * scaleFactor;
  let sy = ly * scaleFactor;
  return {
    x: cx + sx * cos(rotDeg) - sy * sin(rotDeg),
    y: cy + sx * sin(rotDeg) + sy * cos(rotDeg)
  };
}

function drawMandarinSegment(cx, cy, sc, rotDeg, mode) {
  resetBrushState();

  // Canonical kidney/crescent-wedge coordinates of a mandarin segment in local space:
  // Outer dorsal curve on the right (+x up to +48), inner straight/notched chord on the left (-x around -22),
  // top pole around (0, -82), bottom pole around (0, +82).
  let dorsalOutline = [];
  let wedgeFacePts = [];

  const steps = 28;
  // Build outer dorsal curve from top pole (-82) to bottom pole (+82)
  for (let i = 0; i <= steps; i++) {
    let t = map(i, 0, steps, -90, 90);
    let lx = cos(t) * 52 - 4;
    let ly = sin(t) * 84;
    let p = transformSegPt(cx, cy, sc, rotDeg, lx, ly);
    dorsalOutline.push([p.x, p.y]);
    wedgeFacePts.push([p.x, p.y]);
  }

  // Build inner ventral edge (with characteristic central seed-notch indentation) from bottom to top
  let innerEdgeLocal = [
    [-6, 80],
    [-20, 62],
    [-24, 32],
    [-17, 6],   // central seed/columella notch
    [-17, -6],
    [-24, -32],
    [-20, -62],
    [-6, -80]
  ];

  // For 3D thickness, add a second ridge line between the flat septum face and curved dorsal back
  let ridgePts = [];
  for (let i = 0; i <= steps; i++) {
    let t = map(i, 0, steps, -90, 90);
    let lx = cos(t) * 28 - 8;
    let ly = sin(t) * 80;
    let p = transformSegPt(cx, cy, sc, rotDeg, lx, ly);
    ridgePts.push([p.x, p.y]);
  }

  for (let [lx, ly] of innerEdgeLocal) {
    let p = transformSegPt(cx, cy, sc, rotDeg, lx, ly);
    wedgeFacePts.push([p.x, p.y]);
  }

  if (mode === "naked_vesicles") {
    drawNakedVesicleSegment(cx, cy, sc, rotDeg);
    return;
  }

  // 1) Base wash & watercolor fill of the segment body
  let segPoly = new brush.Polygon(wedgeFacePts);
  segPoly.wash(PAL.rindApricot, 235);
  segPoly.fill(PAL.rindCoral, 105, 0.03, 0.35);

  // 2) Shaded dorsal back band (between ridgePts and dorsalOutline)
  let dorsalBandPts = [...dorsalOutline, ...ridgePts.slice().reverse()];
  let dorsalPoly = new brush.Polygon(dorsalBandPts);
  dorsalPoly.fill(PAL.rindTerra, 90, 0.04, 0.35);
  brush.hatchStyle("cpencil", PAL.rindCoral, 0.6);
  dorsalPoly.hatch(3.2, rotDeg + 25, { rand: 0.06 });

  // 3) Mode-specific internal & surface rendering
  if (mode === "dorsal_back") {
    // Rich apricot & peach rounding across the plump back + dense lacy white albedo pith net
    dorsalPoly.wash(PAL.rindPeach, 120);
    renderSubsurfaceVesicleHints(cx, cy, sc, rotDeg, 0.45);
    renderSegmentPithNet(cx, cy, sc, rotDeg, 1.0);
  } else if (mode === "wedge_side" || mode === "intact_iso") {
    // Flat radial septum face with translucent milky-peach sheen & delicate pith veins
    let septumPts = [...ridgePts, ...innerEdgeLocal.map(([lx, ly]) => {
      let p = transformSegPt(cx, cy, sc, rotDeg, lx, ly);
      return [p.x, p.y];
    })];
    let septumPoly = new brush.Polygon(septumPts);
    septumPoly.wash(PAL.rindMelon, 145);
    renderSubsurfaceVesicleHints(cx, cy, sc, rotDeg, 0.65);
    renderTranslucentMembraneSheen(cx, cy, sc, rotDeg, ridgePts, wedgeFacePts);
    renderSegmentPithNet(cx, cy, sc, rotDeg, 0.65);
  } else if (mode === "translucent_iso") {
    // Higher clarity of internal teardrop vesicles glowing through thin taut membrane
    renderPackedVesicles(cx, cy, sc, rotDeg, false);
    // Semi-transparent milky-white membrane veil over the vesicles
    segPoly.wash(PAL.pithIvory, 78);
    renderTranslucentMembraneSheen(cx, cy, sc, rotDeg, ridgePts, wedgeFacePts);
    renderSegmentPithNet(cx, cy, sc, rotDeg, 0.45);
  } else if (mode === "peeled_open") {
    // Full glistening vesicles inside, with upper/left papery membrane flap peeled back!
    renderPackedVesicles(cx, cy, sc, rotDeg, true);
    renderPeeledMembraneFlap(cx, cy, sc, rotDeg);
    renderSegmentPithNet(cx, cy, sc, rotDeg, 0.4);
  }

  // 4) Crisp coloured-pencil contour & torn white pith fringe along the inner edge
  resetBrushState();
  for (let i = 0; i < wedgeFacePts.length; i++) {
    let p1 = wedgeFacePts[i];
    let p2 = wedgeFacePts[(i + 1) % wedgeFacePts.length];
    brush.set("cpencil_fine", i < steps ? PAL.rindDeep : PAL.pithCream, 0.55);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // Torn white vascular threads along the inner ventral notch
  for (let i = 1; i < innerEdgeLocal.length - 1; i++) {
    let [lx, ly] = innerEdgeLocal[i];
    let p = transformSegPt(cx, cy, sc, rotDeg, lx, ly);
    let pOut = transformSegPt(cx, cy, sc, rotDeg, lx - random(5, 11), ly + random(-4, 4));
    brush.set("cpencil_fine", PAL.pithShadow, 0.42);
    brush.line(p.x + 1, p.y + 1, pOut.x + 1, pOut.y + 1);
    brush.set("cpencil_fine", PAL.white, 0.62);
    brush.line(p.x, p.y, pOut.x, pOut.y);
  }
}

function renderSubsurfaceVesicleHints(cx, cy, sc, rotDeg, intensity) {
  resetBrushState();
  // Subtle teardrop cells visible beneath the translucent carpel membrane
  for (let row = -66; row <= 66; row += 10) {
    let maxW = sqrt(max(0, 1 - pow(row / 80, 2))) * 44;
    for (let col = -12; col < maxW - 8; col += 13) {
      let lx1 = col + random(-2, 2);
      let ly1 = row + random(-2, 2);
      let lx2 = lx1 + 10;
      let ly2 = ly1 * 0.92;
      let p1 = transformSegPt(cx, cy, sc, rotDeg, lx1, ly1);
      let p2 = transformSegPt(cx, cy, sc, rotDeg, lx2, ly2);

      brush.set("cpencil_fine", PAL.vesicleSalmon, 0.55 * intensity);
      brush.line(p1.x, p1.y, p2.x, p2.y);

      brush.set("cpencil_fine", PAL.rindMelon, 0.65 * intensity);
      brush.line(p1.x + 0.8, p1.y - 0.8, p2.x + 0.8, p2.y - 0.8);
    }
  }
}

function renderTranslucentMembraneSheen(cx, cy, sc, rotDeg, ridgePts, wedgeFacePts) {
  resetBrushState();
  // Silky diagonal sheen strokes across the taut papery septum membrane
  for (let y = -62; y <= 62; y += 9) {
    let maxW = sqrt(max(0, 1 - pow(y / 80, 2))) * 26;
    let p1 = transformSegPt(cx, cy, sc, rotDeg, -16, y - 4);
    let p2 = transformSegPt(cx, cy, sc, rotDeg, maxW - 4, y + 5);
    brush.set("cpencil_fine", PAL.pithIvory, 0.52);
    brush.line(p1.x, p1.y, p2.x, p2.y);
  }
  // Bright white highlight along the 3D ridge where the septum meets the dorsal arch
  brush.set("cpencil", PAL.white, 0.72);
  let ridgeSub = ridgePts.slice(5, ridgePts.length - 5);
  brush.spline(ridgeSub, 0.35);
}

function renderSegmentPithNet(cx, cy, sc, rotDeg, coverage) {
  resetBrushState();
  // Branching white dorsal vascular strands wrapping around the curved back of the segment
  let startY = -68;
  let endY = 68;
  let stepY = coverage > 0.8 ? 11 : 16;

  for (let ly = startY; ly <= endY; ly += stepY) {
    let outerX = sqrt(max(0, 1 - pow(ly / 82, 2))) * 50 - 3;
    let innerX = coverage > 0.8 ? -16 : 8;
    let midX = lerp(innerX, outerX, 0.52);
    let midY = ly + random(-6, 6);

    let pA = transformSegPt(cx, cy, sc, rotDeg, outerX, ly);
    let pM = transformSegPt(cx, cy, sc, rotDeg, midX, midY);
    let pB = transformSegPt(cx, cy, sc, rotDeg, innerX, ly + random(-8, 8));

    // Micro-shadow under pith strand
    brush.set("cpencil_fine", PAL.pithShadow, 0.45);
    brush.spline([[pA.x + 1.2, pA.y + 1.2], [pM.x + 1.2, pM.y + 1.2], [pB.x + 1.2, pB.y + 1.2]], 0.35);

    // Creamy white pith filament
    brush.set("cpencil_fine", PAL.white, 0.68);
    brush.spline([[pA.x, pA.y], [pM.x, pM.y], [pB.x, pB.y]], 0.35);

    // Forking sub-vein
    let pFork = transformSegPt(cx, cy, sc, rotDeg, lerp(midX, innerX, 0.8), midY + (ly > 0 ? -9 : 9));
    brush.set("cpencil_fine", PAL.pithIvory, 0.5);
    brush.line(pM.x, pM.y, pFork.x, pFork.y);
  }
}

function renderPackedVesicles(cx, cy, sc, rotDeg, highSpecularity) {
  // Render dozens of individual teardrop pulp vesicles inside the segment contour
  for (let row = -70; row <= 70; row += 9.5) {
    let spanX = sqrt(max(0, 1 - pow(row / 82, 2))) * 48;
    // Two interlocking ranks of teardrop vesicles (outer rank attached to dorsal wall, inner rank)
    let ranks = spanX > 26 ? [
      { x0: spanX - 4, x1: spanX * 0.35 - 6 },
      { x0: spanX * 0.42 - 4, x1: -15 }
    ] : [
      { x0: spanX - 4, x1: -12 }
    ];

    for (let rIdx = 0; rIdx < ranks.length; rIdx++) {
      let rk = ranks[rIdx];
      let pBase = transformSegPt(cx, cy, sc, rotDeg, rk.x0, row + (rIdx * 4 - 2));
      let pTip = transformSegPt(cx, cy, sc, rotDeg, rk.x1, row * 0.86);
      let len = dist(pBase.x, pBase.y, pTip.x, pTip.y);
      let ang = atan2(pTip.y - pBase.y, pTip.x - pBase.x);
      let vx = (pBase.x + pTip.x) * 0.5;
      let vy = (pBase.y + pTip.y) * 0.5;

      let baseCol = (abs(row) < 28 && rIdx === 1) ? PAL.vesicleSalmon : PAL.vesicleCoral;
      let glowCol = rIdx === 0 ? PAL.vesicleGold : PAL.vesicleApricot;
      drawSingleVesicle(vx, vy, len * 1.08, 7.2 * sc, ang, baseCol, glowCol, highSpecularity);
    }
  }
}

function renderPeeledMembraneFlap(cx, cy, sc, rotDeg) {
  resetBrushState();
  // Lower half of segment still covered by translucent membrane; upper flap curled back to the left
  let flapPts = [
    [-16, 12],
    [22, 18],
    [32, 48],
    [14, 74],
    [-8, 78],
    [-22, 52],
    [-20, 18]
  ].map(([lx, ly]) => {
    let p = transformSegPt(cx, cy, sc, rotDeg, lx, ly);
    return [p.x, p.y];
  });
  let lowerVeil = new brush.Polygon(flapPts);
  lowerVeil.wash(PAL.pithIvory, 130);

  // Curled upper membrane sheet peeling away to the left (-x)
  let curlPts = [
    [-16, 12],
    [-38, -2],
    [-50, -32],
    [-36, -64],
    [-10, -76],
    [-18, -36]
  ].map(([lx, ly]) => {
    let p = transformSegPt(cx, cy, sc, rotDeg, lx, ly);
    return [p.x, p.y];
  });
  let curlPoly = new brush.Polygon(curlPts);
  curlPoly.wash(PAL.pithCream, 175);
  curlPoly.fill(PAL.pithShadow, 65, 0.03, 0.25);

  resetBrushState();
  brush.set("cpencil_fine", PAL.pithShadow, 0.5);
  brush.spline([...curlPts, curlPts[0]], 0.35);
  brush.set("cpencil", PAL.white, 0.75);
  brush.spline(curlPts.slice(0, 4), 0.35);
}

function drawNakedVesicleSegment(cx, cy, sc, rotDeg) {
  resetBrushState();
  // Faint warm coral glow behind the packed vesicle cluster
  let bgPts = [];
  for (let i = 0; i < 24; i++) {
    let a = (i / 24) * 360;
    let p = transformSegPt(cx, cy, sc, rotDeg, cos(a) * 32 + 6, sin(a) * 74);
    bgPts.push([p.x, p.y]);
  }
  let bgPoly = new brush.Polygon(bgPts);
  bgPoly.wash(PAL.vesicleSalmon, 120);

  // Render ~52 individual glistening teardrop vesicles fanned out slightly at the edges
  for (let row = -74; row <= 74; row += 8.8) {
    let spanX = sqrt(max(0, 1 - pow(row / 82, 2))) * 50;
    let fanSpread = row * 0.08; // Slight exploded fan at top and bottom poles

    let ranks = spanX > 24 ? [
      { x0: spanX, x1: spanX * 0.38 - 4, w: 7.6 },
      { x0: spanX * 0.45, x1: -16, w: 7.0 }
    ] : [
      { x0: spanX, x1: -12, w: 6.8 }
    ];

    for (let rIdx = 0; rIdx < ranks.length; rIdx++) {
      let rk = ranks[rIdx];
      let pBase = transformSegPt(cx, cy, sc, rotDeg, rk.x0 + rIdx * 2, row + fanSpread);
      let pTip = transformSegPt(cx, cy, sc, rotDeg, rk.x1, row * 0.84 - fanSpread * 0.5);
      let len = dist(pBase.x, pBase.y, pTip.x, pTip.y);
      let ang = atan2(pTip.y - pBase.y, pTip.x - pBase.x);
      let vx = (pBase.x + pTip.x) * 0.5;
      let vy = (pBase.y + pTip.y) * 0.5;

      let baseCol = (int(abs(row)) + rIdx) % 3 === 0 ? PAL.vesicleRuby
                  : ((int(abs(row)) + rIdx) % 2 === 0 ? PAL.vesicleSalmon : PAL.vesicleCoral);
      let glowCol = rIdx === 0 ? PAL.vesicleGold : PAL.vesicleApricot;
      drawSingleVesicle(vx, vy, len * 1.12, rk.w * sc, ang, baseCol, glowCol, true);
    }
  }

  // Delicate dorsal vascular thread still linking the outer bases of the vesicles
  let dorsalSpine = [];
  for (let i = 0; i <= 16; i++) {
    let t = map(i, 0, 16, -82, 82);
    let lx = cos(t) * 51 - 2;
    let ly = sin(t) * 82;
    let p = transformSegPt(cx, cy, sc, rotDeg, lx, ly);
    dorsalSpine.push([p.x, p.y]);
  }
  resetBrushState();
  brush.set("cpencil_fine", PAL.pithCream, 0.65);
  brush.spline(dorsalSpine, 0.35);
}

function drawSingleVesicle(cx, cy, len, wid, angDeg, baseCol, glowCol, highSpecularity = true) {
  resetBrushState();
  let halfL = len * 0.5;
  let halfW = wid * 0.5;

  // Plump teardrop shape in local coordinates (pointed stalk at -halfL, rounded belly at +0.18*len)
  let localPts = [
    [-halfL, 0],
    [-halfL * 0.3, -halfW * 0.65],
    [halfL * 0.25, -halfW],
    [halfL * 0.82, -halfW * 0.58],
    [halfL, 0],
    [halfL * 0.82, halfW * 0.58],
    [halfL * 0.25, halfW],
    [-halfL * 0.3, halfW * 0.65]
  ];

  let worldPts = localPts.map(([lx, ly]) => [
    cx + lx * cos(angDeg) - ly * sin(angDeg),
    cy + lx * sin(angDeg) + ly * cos(angDeg)
  ]);

  // 1. Translucent pastel coral/salmon vesicle body
  let vPoly = new brush.Polygon(worldPts);
  vPoly.wash(baseCol, 225);

  // 2. Luminous pale gold / apricot inner belly glow (subsurface scattering)
  let bellyPts = [
    [-halfL * 0.1, -halfW * 0.35],
    [halfL * 0.35, -halfW * 0.65],
    [halfL * 0.72, 0],
    [halfL * 0.35, halfW * 0.45]
  ].map(([lx, ly]) => [
    cx + lx * cos(angDeg) - ly * sin(angDeg),
    cy + lx * sin(angDeg) + ly * cos(angDeg)
  ]);
  let bellyPoly = new brush.Polygon(bellyPts);
  bellyPoly.wash(glowCol, 185);

  // 3. Coloured-pencil contour shading on the lower flank of the vesicle
  resetBrushState();
  brush.set("cpencil_fine", PAL.rindDeep, 0.46);
  brush.spline([worldPts[4], worldPts[5], worldPts[6], worldPts[7], worldPts[0]], 0.3);

  // 4. Razor-sharp glistening white specular highlight along the upper curved ridge
  if (highSpecularity) {
    let h1 = {
      x: cx + (-halfL * 0.05) * cos(angDeg) - (-halfW * 0.52) * sin(angDeg),
      y: cy + (-halfL * 0.05) * sin(angDeg) + (-halfW * 0.52) * cos(angDeg)
    };
    let h2 = {
      x: cx + (halfL * 0.58) * cos(angDeg) - (-halfW * 0.48) * sin(angDeg),
      y: cy + (halfL * 0.58) * sin(angDeg) + (-halfW * 0.48) * cos(angDeg)
    };
    brush.set("cpencil_fine", PAL.white, 0.82);
    brush.line(h1.x, h1.y, h2.x, h2.y);

    // Pinpoint specular sparkle near the plump tip
    let sp = {
      x: cx + (halfL * 0.72) * cos(angDeg) - (-halfW * 0.22) * sin(angDeg),
      y: cy + (halfL * 0.72) * sin(angDeg) + (-halfW * 0.22) * cos(angDeg)
    };
    brush.set("cpencil_fine", PAL.white, 1.05);
    brush.line(sp.x, sp.y, sp.x + 1.2, sp.y + 0.8);
  }
}

function drawSingleSeed(cx, cy, rotDeg) {
  resetBrushState();
  // Plump teardrop citrus seed with pointed micropylar beak at left (-x) and rounded chalaza at right (+x)
  let seedLocal = [
    [-30, 0],     // pointed beak
    [-18, -8],
    [-2, -14.5],
    [14, -13.5],
    [25, -7.5],
    [28, 0],      // rounded chalaza end
    [24, 8.5],
    [12, 14.5],
    [-4, 15.0],
    [-19, 7.5]
  ];

  let seedWorld = seedLocal.map(([lx, ly]) => [
    cx + lx * cos(rotDeg) - ly * sin(rotDeg),
    cy + lx * sin(rotDeg) + ly * cos(rotDeg)
  ]);

  let seedPoly = new brush.Polygon(seedWorld);
  seedPoly.wash(PAL.seedCream, 245);
  seedPoly.fill(PAL.seedPistachio, 95, 0.03, 0.3);

  // Lower turn-of-form shadow in warm almond-ochre
  let shadowLocal = [
    [-24, 2],
    [0, 5],
    [22, 2],
    [26, 0],
    [24, 8.5],
    [12, 14.5],
    [-4, 15.0],
    [-19, 7.5]
  ].map(([lx, ly]) => [
    cx + lx * cos(rotDeg) - ly * sin(rotDeg),
    cy + lx * sin(rotDeg) + ly * cos(rotDeg)
  ]);
  let seedShadowPoly = new brush.Polygon(shadowLocal);
  seedShadowPoly.fill(PAL.seedMid, 120, 0.03, 0.35);

  // Longitudinal seed-coat ridges & chalazal pistachio blush
  resetBrushState();
  for (let r = -9; r <= 9; r += 3.5) {
    let p1 = {
      x: cx + (-22) * cos(rotDeg) - (r * 0.4) * sin(rotDeg),
      y: cy + (-22) * sin(rotDeg) + (r * 0.4) * cos(rotDeg)
    };
    let pMid = {
      x: cx + (4) * cos(rotDeg) - (r * 1.1) * sin(rotDeg),
      y: cy + (4) * sin(rotDeg) + (r * 1.1) * cos(rotDeg)
    };
    let p2 = {
      x: cx + (23) * cos(rotDeg) - (r * 0.5) * sin(rotDeg),
      y: cy + (23) * sin(rotDeg) + (r * 0.5) * cos(rotDeg)
    };
    let col = r > 2 ? PAL.seedShadow : (r < -2 ? PAL.pithIvory : PAL.seedPistachio);
    brush.set("cpencil_fine", col, 0.55);
    brush.spline([[p1.x, p1.y], [pMid.x, pMid.y], [p2.x, p2.y]], 0.35);
  }

  // Crisp contour & glossy highlight along upper ridge of seed
  brush.set("cpencil_fine", PAL.seedShadow, 0.58);
  brush.spline([...seedWorld, seedWorld[0]], 0.3);

  let h1 = {
    x: cx + (-12) * cos(rotDeg) - (-7) * sin(rotDeg),
    y: cy + (-12) * sin(rotDeg) + (-7) * cos(rotDeg)
  };
  let h2 = {
    x: cx + (15) * cos(rotDeg) - (-8) * sin(rotDeg),
    y: cy + (15) * sin(rotDeg) + (-8) * cos(rotDeg)
  };
  brush.set("cpencil", PAL.white, 0.85);
  brush.line(h1.x, h1.y, h2.x, h2.y);
}

// ============================================================================
// 8. STATION 5: LOWER SPLIT PEEL SHELL (CUPPED INTERIOR ALBEDO VIEW)
// ============================================================================
function drawLowerPeelShell(cx, cy) {
  resetBrushState();

  const numPts = 72;
  let outerLipPts = [];
  let innerBowlPts = [];

  for (let i = 0; i < numPts; i++) {
    let ang = (i / numPts) * 360;
    // 4 torn split notches between the cupped lobes
    let n1 = exp(-pow(angleDiff(ang, 18) / 11, 2)) * 26;
    let n2 = exp(-pow(angleDiff(ang, 108) / 11, 2)) * 24;
    let n3 = exp(-pow(angleDiff(ang, 198) / 12, 2)) * 28;
    let n4 = exp(-pow(angleDiff(ang, 288) / 10, 2)) * 22;
    let notch = n1 + n2 + n3 + n4;
    let lobeWave = cos(ang * 4) * 4;

    let rx = 132 - notch + lobeWave;
    let ry = 90 - notch * 0.68 + lobeWave * 0.6;

    // Cupped bowl depression
    let pIn = pointOnTiltedEllipse(cx, cy, rx - 7, ry - 5, AXIS_MAIN_DEG - 90, ang);
    innerBowlPts.push([pIn.x, pIn.y]);

    // Visible outer orange rind belly wrapping underneath the lower-right hemisphere (-45 to 165 deg)
    let underWrap = max(0, sin(ang - 30)) * 26 + 5;
    let pOut = pointOnTiltedEllipse(cx + underWrap * 0.42, cy + underWrap * 0.52, rx, ry, AXIS_MAIN_DEG - 90, ang);
    outerLipPts.push([pOut.x, pOut.y]);
  }

  // 1) Visible outer pocked orange rind underside (lower-right curved belly of the cup)
  let outerRindPoly = new brush.Polygon(outerLipPts);
  outerRindPoly.wash(PAL.rindTangerine, 240);
  outerRindPoly.fill(PAL.rindCoral, 120, 0.03, 0.35);

  // Oil-gland pores on the visible outer rind lip
  resetBrushState();
  for (let i = 0; i < numPts; i++) {
    let ang = (i / numPts) * 360;
    if (sin(ang - 30) > 0.15) {
      let pIn = innerBowlPts[i];
      let pOut = outerLipPts[i];
      for (let k = 0; k < 3; k++) {
        let t = random(0.25, 0.88);
        let px = lerp(pIn[0], pOut[0], t) + random(-2, 2);
        let py = lerp(pIn[1], pOut[1], t) + random(-2, 2);
        brush.set("cpencil_fine", PAL.rindDeep, 0.65);
        brush.line(px, py, px + 1.1, py + 0.8);
        brush.set("cpencil_fine", PAL.rindMelon, 0.6);
        brush.line(px + 0.9, py - 0.6, px + 2.0, py);
      }
    }
  }

  // 2) Interior spongy cream-peach albedo bowl
  let innerPoly = new brush.Polygon(innerBowlPts);
  innerPoly.wash(PAL.pithIvory, 245);
  innerPoly.fill(PAL.pithCream, 115, 0.04, 0.45);

  // Interior concave bowl shading (shadowed on upper-left inner wall, lit on lower-right inner floor)
  let innerShadowPts = [];
  for (let a = 135; a <= 325; a += 10) {
    let p = pointOnTiltedEllipse(cx - 6, cy - 6, 98, 66, AXIS_MAIN_DEG - 90, a);
    innerShadowPts.push([p.x, p.y]);
  }
  for (let a = 325; a >= 135; a -= 10) {
    let p = pointOnTiltedEllipse(cx + 8, cy + 8, 28, 18, AXIS_MAIN_DEG - 90, a);
    innerShadowPts.push([p.x, p.y]);
  }
  let innerShadowPoly = new brush.Polygon(innerShadowPts);
  innerShadowPoly.fill(PAL.pithWarm, 115, 0.05, 0.45);
  brush.hatchStyle("cpencil", PAL.pithShadow, 0.55);
  innerShadowPoly.hatch(3.6, AXIS_MAIN_DEG + 15, { rand: 0.09 });

  // Soft pastel peach subsurface glow in the thin floor of the peel cup
  let glowPts = [];
  for (let i = 0; i < 24; i++) {
    let a = (i / 24) * 360;
    let p = pointOnTiltedEllipse(cx + 10, cy + 8, 62, 42, AXIS_MAIN_DEG - 90, a);
    glowPts.push([p.x, p.y]);
  }
  let glowPoly = new brush.Polygon(glowPts);
  glowPoly.fill(PAL.rindPeach, 48, 0.06, 0.35);

  // 3) 10 radial vascular veins & concave segment-cradle ribs inside the albedo bowl
  resetBrushState();
  let centerHub = { x: cx + 6, y: cy + 5 };
  for (let r = 0; r < 10; r++) {
    let ang = r * 36 + 8;
    let idx = floor(((ang + 360) % 360) / 360 * numPts);
    let rimPt = innerBowlPts[idx];
    let midPt = {
      x: lerp(centerHub.x, rimPt[0], 0.55) + cos(ang + 90) * 5,
      y: lerp(centerHub.y, rimPt[1], 0.55) + sin(ang + 90) * 5
    };

    brush.set("cpencil_fine", PAL.pithShadow, 0.52);
    brush.spline([[centerHub.x + 1.2, centerHub.y + 1.2], [midPt.x + 1.2, midPt.y + 1.2], [rimPt[0] * 0.9 + centerHub.x * 0.1, rimPt[1] * 0.9 + centerHub.y * 0.1]], 0.35);

    brush.set("cpencil", PAL.white, 0.72);
    brush.spline([[centerHub.x, centerHub.y], [midPt.x, midPt.y], [rimPt[0] * 0.92 + centerHub.x * 0.08, rimPt[1] * 0.92 + centerHub.y * 0.08]], 0.35);

    // Fine branching albedo reticulation inside each lobe
    for (let b = 0; b < 3; b++) {
      let u = map(b, 0, 2, 0.35, 0.78);
      let bx = lerp(centerHub.x, rimPt[0], u);
      let by = lerp(centerHub.y, rimPt[1], u);
      let sideAng = ang + (b % 2 === 0 ? 22 : -22);
      brush.set("cpencil_fine", PAL.pithShadow, 0.38);
      brush.line(bx, by, bx + cos(sideAng) * 16, by + sin(sideAng) * 12);
      brush.set("cpencil_fine", PAL.white, 0.52);
      brush.line(bx - 0.8, by - 0.8, bx + cos(sideAng) * 16 - 0.8, by + sin(sideAng) * 12 - 0.8);
    }
  }

  // Spongy white albedo stipple texture & central blossom-end pith tuft
  for (let s = 0; s < 110; s++) {
    let a = random(0, 360);
    let rad = random(10, 75);
    let p = pointOnTiltedEllipse(cx, cy, rad * 1.15, rad * 0.78, AXIS_MAIN_DEG - 90, a);
    brush.set("cpencil_fine", s % 2 === 0 ? PAL.white : PAL.pithShadow, 0.55);
    brush.line(p.x, p.y, p.x + random(-2.5, 2.5), p.y + random(-2.5, 2.5));
  }

  // Central fuzzy white pith tuft stub at the bottom of the bowl
  for (let t = 0; t < 16; t++) {
    let a = t * 22.5;
    let len = random(6, 14);
    brush.set("cpencil_fine", PAL.pithShadow, 0.5);
    brush.line(centerHub.x + 1, centerHub.y + 1, centerHub.x + cos(a) * len + 1, centerHub.y + sin(a) * len + 1);
    brush.set("cpencil", PAL.white, 0.8);
    brush.line(centerHub.x, centerHub.y, centerHub.x + cos(a) * len, centerHub.y + sin(a) * len);
  }

  // Crisp torn rim contour & orange rind lip edge
  for (let i = 0; i < numPts; i++) {
    let p1 = innerBowlPts[i];
    let p2 = innerBowlPts[(i + 1) % numPts];
    brush.set("cpencil", PAL.white, 0.72);
    brush.line(p1[0], p1[1], p2[0], p2[1]);

    let o1 = outerLipPts[i];
    let o2 = outerLipPts[(i + 1) % numPts];
    brush.set("cpencil_fine", PAL.rindDeep, 0.52);
    brush.line(o1[0], o1[1], o2[0], o2[1]);
  }
}

