function drawRuledLeaderCallout(tx, ty, ex, ey, cx, cy) {
  resetBrushState();
  const r = 15.5;

  // Direction from elbow (ex, ey) to callout center (cx, cy)
  let d = dist(ex, ey, cx, cy);
  let ux = (cx - ex) / max(1, d);
  let uy = (cy - ey) / max(1, d);
  let rimX = cx - ux * r;
  let rimY = cy - uy * r;

  // Faint vellum halo along leader line so it reads crisply over colored pencil passages
  brush.set("2H", PAL.vellumLight, 1.15);
  brush.line(tx, ty, ex, ey);
  brush.line(ex, ey, rimX, rimY);

  // Crisp ruled graphite leader line (target -> elbow -> circle rim)
  brush.set("HB", PAL.graphiteDark, 0.52);
  brush.line(tx, ty, ex, ey);
  brush.line(ex, ey, rimX, rimY);

  // Small target anchor dot & crisp ring on the botanical specimen
  brush.noStroke();
  brush.wash(PAL.graphiteSharp, 230);
  brush.circle(tx, ty, 2.8, 0.02);
  brush.noWash();

  brush.set("2H", PAL.vellumLight, 0.65);
  brush.circle(tx, ty, 5.2, 0.02);
  brush.set("HB", PAL.graphiteDark, 0.42);
  brush.circle(tx, ty, 4.2, 0.02);

  // Blank callout circle filled with clean vellum wash & double-stroked in graphite
  brush.noStroke();
  brush.wash(PAL.vellumWarm, 245);
  brush.circle(cx, cy, r, 0.02);
  brush.noWash();

  // Subtle internal construction ticks at 0/90/180/270 deg on the callout rim
  brush.set("2H", PAL.graphiteFaint, 0.3);
  brush.line(cx - r - 3, cy, cx - r + 2, cy);
  brush.line(cx + r - 2, cy, cx + r + 3, cy);
  brush.line(cx, cy - r - 3, cx, cy - r + 2);
  brush.line(cx, cy + r - 2, cx, cy + r + 3);

  // Crisp hand-drafted graphite callout ring
  brush.set("HB", PAL.graphiteDark, 0.58);
  brush.circle(cx, cy, r, 0.03);
  brush.set("2H", PAL.graphiteSharp, 0.38);
  brush.circle(cx, cy, r, 0.02);
}

function angleDiff(a, b) {
  let d = (a - b + 540) % 360 - 180;
  return d;
}

