// ============================================================================
// GEOMETRY & 3D SURFACE PARAMETRIZATION OF THE SKIFF AND TARPAULIN
// ============================================================================

function catmullRom(p0, p1, p2, p3, t) {
  let t2 = t * t;
  let t3 = t2 * t;
  let x = 0.5 * (
    (2 * p1[0]) +
    (-p0[0] + p2[0]) * t +
    (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * t2 +
    (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * t3
  );
  let y = 0.5 * (
    (2 * p1[1]) +
    (-p0[1] + p2[1]) * t +
    (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * t2 +
    (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * t3
  );
  return [x, y];
}

function evalCurve(pts, u) {
  u = constrain(u, 0, 1);
  let n = pts.length - 1;
  let scaled = u * n;
  let idx = min(floor(scaled), n - 1);
  let t = scaled - idx;
  let p0 = pts[max(0, idx - 1)];
  let p1 = pts[idx];
  let p2 = pts[min(n, idx + 1)];
  let p3 = pts[min(n, idx + 2)];
  return catmullRom(p0, p1, p2, p3, t);
}

// Ridge pole curve (v = 0.0)
const RIDGE_PTS = [
  [162, 248],
  [365, 286],
  [590, 304],
  [825, 356],
  [1042, 404]
];

// Near starboard gunwale curve (v = 0.42)
const GUNWALE_PTS = [
  [164, 266],
  [325, 396],
  [565, 458],
  [815, 474],
  [1082, 462]
];

// Scalloped tarpaulin hem baseline (v = 1.0)
const HEM_PTS = [
  [166, 514],
  [265, 636],
  [395, 706],
  [540, 748],
  [695, 752],
  [845, 718],
  [970, 664],
  [1076, 588]
];

// Wooden keel & stem bottom profile
const KEEL_PTS = [
  [168, 514],
  [215, 755],
  [345, 810],
  [565, 842],
  [795, 816],
  [978, 742],
  [1036, 682]
];

function getScallopOffset(u) {
  // Finds local position between adjacent grommets to create upward catenary scallop
  for (let i = 0; i < GROMMET_U.length - 1; i++) {
    let u0 = GROMMET_U[i];
    let u1 = GROMMET_U[i + 1];
    if (u >= u0 && u <= u1) {
      let lt = (u - u0) / (u1 - u0);
      // Catenary arch upward between grommets, sharp pull-down at grommets
      return -pow(sin(lt * 180), 0.85) * 18;
    }
  }
  return 0;
}

function getRibSag(u, v) {
  // Subtle sag of the tarpaulin between internal boat frames/crutches
  for (let i = 0; i < RIB_U.length - 1; i++) {
    let u0 = RIB_U[i];
    let u1 = RIB_U[i + 1];
    if (u >= u0 && u <= u1) {
      let lt = (u - u0) / (u1 - u0);
      let sagFactor = sin(lt * 180);
      // Roof sags more than the tight gunwale
      let vWeight = 1.0 - abs(v - 0.22) * 1.1;
      return sagFactor * max(0, vWeight) * 11;
    }
  }
  return 0;
}

// Maps normalized tarpaulin coordinates (u in [0,1], v in [0,1]) to 2D canvas coordinates
function tarpPoint(u, v, jitterAmp = 0) {
  u = constrain(u, 0, 1);
  v = constrain(v, 0, 1.04);

  let rPt = evalCurve(RIDGE_PTS, u);
  let gPt = evalCurve(GUNWALE_PTS, u);
  let hPt = evalCurve(HEM_PTS, u);

  // Apply hem scallop near bottom edge
  let scallop = getScallopOffset(u) * pow(constrain((v - 0.35) / 0.65, 0, 1), 1.6);
  hPt[1] += scallop;

  let x, y;
  let gunwaleV = 0.42;

  if (v <= gunwaleV) {
    // Upper sloping roof plane (from ridge pole to near gunwale)
    let t = v / gunwaleV;
    // Slight inward drape curve on roof slope
    let easeT = pow(t, 0.94);
    x = lerp(rPt[0], gPt[0], easeT);
    y = lerp(rPt[1], gPt[1], easeT) + sin(t * 180) * 8 * (1 - 0.4 * abs(u - 0.5));
  } else {
    // Lower hull flank plane (from near gunwale down to scalloped grommet hem)
    let t = (v - gunwaleV) / (1.0 - gunwaleV);
    // Outward hull belly curve in 3/4 view
    let bowFactor = 1.0 - u * 0.5;
    x = lerp(gPt[0], hPt[0], t) - sin(t * 180) * 10 * bowFactor;
    y = lerp(gPt[1], hPt[1], t);
  }

  // Add subtle sag between ribs/thwarts
  y += getRibSag(u, v);

  // Add deterministic cloth wobble if requested
  if (jitterAmp > 0) {
    let n1 = noise(u * 12 + 10, v * 12 + 20) - 0.5;
    let n2 = noise(u * 12 + 70, v * 12 + 80) - 0.5;
    x += n1 * jitterAmp * 2.0;
    y += n2 * jitterAmp * 2.0;
  }

  return [x, y];
}

// ============================================================================
// DRAWING HELPERS (SAFE WRAPPERS FOR P5.BRUSH)
// ============================================================================

function drawPolyShape(pts, curvature = 0.08, closeShape = true) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closeShape);
}

function buildPatchBoundary(u0, u1, v0, v1, stepsU = 8, stepsV = 8, edgeWobble = 4.5, seedOff = 0) {
  let pts = [];
  // Top edge: u0 -> u1 at v0
  for (let i = 0; i <= stepsU; i++) {
    let t = i / stepsU;
    let u = lerp(u0, u1, t);
    let wobV = (noise(u * 18 + seedOff, v0 * 18 + 11) - 0.5) * 0.014;
    let p = tarpPoint(u, v0 + wobV, edgeWobble);
    pts.push(p);
  }
  // Right edge: v0 -> v1 at u1
  for (let i = 1; i <= stepsV; i++) {
    let t = i / stepsV;
    let v = lerp(v0, v1, t);
    let wobU = (noise(u1 * 18 + seedOff, v * 18 + 37) - 0.5) * 0.010;
    let p = tarpPoint(u1 + wobU, v, edgeWobble);
    pts.push(p);
  }
  // Bottom edge: u1 -> u0 at v1
  for (let i = 1; i <= stepsU; i++) {
    let t = i / stepsU;
    let u = lerp(u1, u0, t);
    let wobV = (noise(u * 18 + seedOff, v1 * 18 + 63) - 0.5) * 0.014;
    let p = tarpPoint(u, v1 + wobV, edgeWobble);
    pts.push(p);
  }
  // Left edge: v1 -> v0 at u0
  for (let i = 1; i < stepsV; i++) {
    let t = i / stepsV;
    let v = lerp(v1, v0, t);
    let wobU = (noise(u0 * 18 + seedOff, v * 18 + 89) - 0.5) * 0.010;
    let p = tarpPoint(u0 + wobU, v, edgeWobble);
    pts.push(p);
  }
  return pts;
}

