// ============================================================================
// 3 & 10. HYPERREALIST SHINGLE PEBBLES (BACKGROUND & FOREGROUND PASSES)
// ============================================================================

function drawShinglePebbles(passType) {
  // Palette of coastal shingle pebbles (soft pastel greys, greige, slate, chalk, muted ochre)
  const pebblePalettes = [
    { col: "#9ea2a6", op: 135 },
    { col: "#b8b4ac", op: 140 },
    { col: "#81868c", op: 140 },
    { col: "#cfd1cf", op: 145 },
    { col: "#a9aeb5", op: 135 },
    { col: "#6b7077", op: 145 },
    { col: "#c4bcb2", op: 135 }
  ];

  let pebbles = [];
  let count = passType === "background" ? 210 : 95;

  for (let i = 0; i < count; i++) {
    let y = passType === "background"
      ? random(640, 930)
      : random(810, 1185);

    // Avoid generating background pebbles deep inside the covered hull area
    if (passType === "background" && y < 745 && random() < 0.75) continue;

    let x = random(15, 1185);
    // Perspective scaling: pebbles grow larger toward bottom foreground
    let depthScale = map(y, 640, 1190, 0.32, 1.45);
    let rx = random(9, 24) * depthScale;
    let ry = rx * random(0.52, 0.78);
    let ang = random(-22, 22);

    // Darken pebbles that sit directly inside the hull's cast shadow
    let inHullShadow = (x > 150 && x < 1060 && y > 720 && y < 885);
    let palIdx = inHullShadow ? floor(random(2, 6)) : floor(random(pebblePalettes.length));

    let pts = [];
    let numV = 7;
    for (let v = 0; v < numV; v++) {
      let a = (v / numV) * 360;
      let rMod = random(0.86, 1.14);
      let px = cos(a) * rx * rMod;
      let py = sin(a) * ry * rMod;
      // Rotate slightly
      let rotX = px * cos(ang) - py * sin(ang);
      let rotY = px * sin(ang) + py * cos(ang);
      pts.push([x + rotX, y + rotY]);
    }

    pebbles.push({ x, y, rx, ry, pts, palIdx, inHullShadow, depthScale });
  }

  // Batch fills by palette index for fast watercolor caching
  brush.noStroke();
  brush.noHatch();
  for (let pIdx = 0; pIdx < pebblePalettes.length; pIdx++) {
    let pal = pebblePalettes[pIdx];
    brush.fill(pal.col, pal.op);
    brush.fillBleed(0.12, "out");
    brush.fillTexture(0.5, 0.45);
    for (let pb of pebbles) {
      if (pb.palIdx === pIdx) {
        drawPolyShape(pb.pts, 0.25);
      }
    }
  }
  brush.noFill();

  // Draw crisp lower-edge shadow crescents, top highlights & quartz veins on pebbles
  for (let pb of pebbles) {
    // Lower shadow crescent
    brush.set("2B", pb.inHullShadow ? "#26292e" : "#4a4e54", 0.55 + pb.depthScale * 0.35);
    let p2 = pb.pts[1];
    let p3 = pb.pts[2];
    let p4 = pb.pts[3];
    let p5 = pb.pts[4];
    brush.spline([p2, p3, p4, p5], 0.35);

    // Top highlight or white quartz vein on larger stones
    if (pb.depthScale > 0.65 && random() < 0.65) {
      brush.set("cpencil", "#eceae4", 0.55);
      brush.line(
        pb.x - pb.rx * 0.45,
        pb.y - pb.ry * 0.35,
        pb.x + pb.rx * 0.35,
        pb.y - pb.ry * 0.15
      );
    }
  }

  // Extra fine stipple & small shingle interstitial crevices
  brush.set("HB", "#585c62", 0.55);
  let dotCount = passType === "background" ? 260 : 140;
  for (let i = 0; i < dotCount; i++) {
    let y = passType === "background" ? random(645, 920) : random(830, 1185);
    let x = random(20, 1180);
    let s = map(y, 640, 1190, 2, 7);
    brush.line(x, y, x + s, y + random(-1.5, 1.5));
  }
}

// ============================================================================
// 4. TIMBER HAUL-OUT SKIDS / SLEEPERS UNDER THE KEEL
// ============================================================================

function drawTimberSkids() {
  const skids = [
    { x: 245, y: 785, w: 125, h: 28, ang: 14, col: "#766c60" },
    { x: 560, y: 838, w: 145, h: 32, ang: 11, col: "#6b6257" },
    { x: 895, y: 768, w: 130, h: 26, ang: 9, col: "#746a5e" }
  ];

  for (let sk of skids) {
    let dx = cos(sk.ang) * (sk.w / 2);
    let dy = sin(sk.ang) * (sk.w / 2);
    let topPts = [
      [sk.x - dx, sk.y - dy],
      [sk.x + dx, sk.y + dy],
      [sk.x + dx - 8, sk.y + dy + sk.h],
      [sk.x - dx - 8, sk.y - dy + sk.h]
    ];

    // Shadow on shingle
    brush.noStroke();
    brush.fill("#35383d", 140);
    brush.fillBleed(0.2, "out");
    drawPolyShape([
      [topPts[3][0] - 6, topPts[3][1] + 2],
      [topPts[2][0] + 12, topPts[2][1] + 4],
      [topPts[2][0] + 6, topPts[2][1] + 16],
      [topPts[3][0] - 10, topPts[3][1] + 12]
    ], 0.08);

    // Timber body wash
    brush.fill(sk.col, 175);
    brush.fillBleed(0.12, "in");
    brush.fillTexture(0.65, 0.55);
    drawPolyShape(topPts, 0.04);
    brush.noFill();

    // Wood grain & checks
    brush.set("2B", "#3d3630", 0.7);
    drawPolyShape(topPts, 0.04, true);
    for (let g = 0.2; g <= 0.8; g += 0.2) {
      let gx1 = lerp(topPts[0][0], topPts[3][0], g);
      let gy1 = lerp(topPts[0][1], topPts[3][1], g);
      let gx2 = lerp(topPts[1][0], topPts[2][0], g);
      let gy2 = lerp(topPts[1][1], topPts[2][1], g);
      brush.line(gx1, gy1, gx2, gy2);
    }
  }
}

// ============================================================================
// 5. EXPOSED LOWER WOODEN CLINKER SKIFF HULL
// ============================================================================

function drawWoodenSkiffHull() {
  // Build 6 curved clinker strakes between the tarpaulin hem zone and the keel
  const numStrakes = 6;
  const uSteps = 28;

  const strakeColors = [
    { col: "#a7bdb9", op: 145 }, // Upper exposed strake with faded pastel seafoam paint
    { col: "#949c98", op: 155 }, // Weathered grey-blue paint & silvered wood
    { col: "#8a7f72", op: 165 }, // Driftwood taupe-grey oak
    { col: "#786d61", op: 170 }, // Mid bilge strake
    { col: "#63594f", op: 180 }, // Lower tar-stained strake
    { col: "#4c453e", op: 190 }  // Garboard strake & keel shadow
  ];

  // Precompute strake curves
  let strakeCurves = [];
  for (let s = 0; s <= numStrakes; s++) {
    let t = s / numStrakes;
    let curve = [];
    for (let i = 0; i <= uSteps; i++) {
      let u = i / uSteps;
      // Top of exposed hull starts slightly above the scalloped tarp hem so no gap appears
      let topPt = evalCurve(HEM_PTS, u);
      topPt[1] -= 22;
      let botPt = evalCurve(KEEL_PTS, u);

      let x = lerp(topPt[0], botPt[0], t) + sin(t * 180) * 6 * (1 - u * 0.5);
      let y = lerp(topPt[1], botPt[1], pow(t, 0.92));
      curve.push([x, y]);
    }
    strakeCurves.push(curve);
  }

  // Fill each clinker strake
  brush.noStroke();
  brush.noHatch();
  for (let s = 0; s < numStrakes; s++) {
    let upper = strakeCurves[s];
    let lower = strakeCurves[s + 1];
    let poly = [...upper, ...lower.slice().reverse()];

    brush.fill(strakeColors[s].col, strakeColors[s].op);
    brush.fillBleed(0.14, "in");
    brush.fillTexture(0.65, 0.55);
    drawPolyShape(poly, 0.04);
  }

  // Peeling pastel seafoam & chalk-blue paint patches on the forward strakes
  const paintFlakes = [
    { u0: 0.03, u1: 0.18, s0: 0.1, s1: 0.45, col: "#b8cecb", op: 130 },
    { u0: 0.22, u1: 0.36, s0: 0.15, s1: 0.48, col: "#c4d4d1", op: 115 },
    { u0: 0.44, u1: 0.58, s0: 0.2, s1: 0.52, col: "#a3b8b6", op: 110 },
    { u0: 0.72, u1: 0.88, s0: 0.12, s1: 0.42, col: "#b5c5c3", op: 120 }
  ];
  for (let pf of paintFlakes) {
    let p0 = evalCurve(HEM_PTS, pf.u0);
    let p1 = evalCurve(HEM_PTS, pf.u1);
    let k0 = evalCurve(KEEL_PTS, pf.u0);
    let k1 = evalCurve(KEEL_PTS, pf.u1);
    let pts = [
      [lerp(p0[0], k0[0], pf.s0), lerp(p0[1] - 18, k0[1], pf.s0)],
      [lerp(p1[0], k1[0], pf.s0), lerp(p1[1] - 18, k1[1], pf.s0)],
      [lerp(p1[0], k1[0], pf.s1), lerp(p1[1] - 18, k1[1], pf.s1)],
      [lerp(p0[0], k0[0], pf.s1), lerp(p0[1] - 18, k0[1], pf.s1)]
    ];
    brush.fill(pf.col, pf.op);
    brush.fillBleed(0.18, "out");
    drawPolyShape(pts, 0.08);
  }
  brush.noFill();

  // Draw wood grain splines, lapstrake plank shadows, and copper clinker rivets
  for (let s = 1; s <= numStrakes; s++) {
    let curve = strakeCurves[s];

    // Lap shadow under each overlapping clinker plank
    brush.set("2B", "#2b2623", 1.1);
    brush.spline(curve, 0.3);

    brush.set("rotring", "#1e1a18", 0.65);
    let offsetCurve = curve.map(p => [p[0], p[1] + 2.2]);
    brush.spline(offsetCurve, 0.3);

    // Highlight along upper plank bevel
    if (s < numStrakes) {
      brush.set("cpencil", "#b8afa2", 0.55);
      let hiCurve = curve.map(p => [p[0], p[1] - 1.8]);
      brush.spline(hiCurve, 0.3);
    }

    // Fine wood grain lines inside the plank
    let prevCurve = strakeCurves[s - 1];
    brush.set("2H", "#524a42", 0.45);
    for (let g = 0.3; g <= 0.7; g += 0.35) {
      let gPts = [];
      for (let i = 0; i <= uSteps; i += 2) {
        let x = lerp(prevCurve[i][0], curve[i][0], g);
        let y = lerp(prevCurve[i][1], curve[i][1], g) + random(-1.5, 1.5);
        gPts.push([x, y]);
      }
      brush.spline(gPts, 0.25);
    }

    // Copper/iron clinker rivet dots along each plank lap
    brush.set("rotring", "#2b2522", 0.85);
    for (let i = 1; i < uSteps; i++) {
      let pt = curve[i];
      let prevPt = prevCurve[i];
      let rx = lerp(pt[0], prevPt[0], 0.28);
      let ry = lerp(pt[1], prevPt[1], 0.28);
      brush.line(rx - 1.2, ry, rx + 1.2, ry + 0.5);
    }
  }

  // Heavy oak bow stem post & keel bar
  let stemPoly = [
    [154, 495], [174, 495],
    [195, 650], [228, 765],
    [350, 816], [346, 830],
    [212, 778], [176, 655]
  ];
  brush.noStroke();
  brush.fill("#665c52", 185);
  brush.fillBleed(0.08, "in");
  drawPolyShape(stemPoly, 0.05);
  brush.noFill();

  brush.set("2B", "#2e2824", 1.15);
  drawPolyShape(stemPoly, 0.05, true);
}

