function drawTarpOverhangShadow() {
  // Continuous soft shadow just below the scalloped bottom hem of the tarpaulin
  let shadowPtsTop = [];
  let shadowPtsBot = [];
  let steps = 48;
  for (let i = 0; i <= steps; i++) {
    let u = i / steps;
    let p = tarpPoint(u, 1.0, 2.0);
    shadowPtsTop.push([p[0], p[1] - 3]);
    shadowPtsBot.push([p[0] + 4, p[1] + 22 + sin(u * 540) * 4]);
