  let poly = [...shadowPtsTop, ...shadowPtsBot.reverse()];

  brush.noStroke();
  brush.fill("#232930", 125);
  brush.fillBleed(0.22, "out");
  brush.fillTexture(0.5, 0.4);
  drawPolyShape(poly, 0.06);
  brush.noFill();
}

