function drawBoroTarpaulinSystem() {
  const patches = getBoroPatches();

  // Precompute geometry for all patches
  for (let p of patches) {
    p.pts = buildPatchBoundary(p.u0, p.u1, p.v0, p.v1, 8, 8, 4.2, p.seed);
    // Inner tone glaze polygon (upper sun-bleached or lower shaded half)
    let vMid = lerp(p.v0, p.v1, 0.55);
    p.upperPts = buildPatchBoundary(p.u0 + 0.008, p.u1 - 0.008, p.v0 + 0.015, vMid, 5, 4, 3.0, p.seed + 50);
  }

  // -------------------------------------------------------------------------
  // PASS A: Patch Drop Shadows & Layered Watercolor Fills
  // -------------------------------------------------------------------------
  for (let p of patches) {
    // 1. Subtle dark overlap shadow beneath each patch edge
    brush.noStroke();
    brush.noHatch();
    let shadowPts = p.pts.map(pt => [pt[0] + 3.5, pt[1] + 4.5]);
    brush.fill("#1e2633", p.isRust ? 75 : 52);
    brush.fillBleed(0.18, "out");
    brush.fillTexture(0.45, 0.35);
    drawPolyShape(shadowPts, 0.08);

    // 2. Primary watercolor fill of the patch
    brush.fill(p.col, p.op);
    brush.fillBleed(p.isRust ? 0.26 : 0.32, "out");
    brush.fillTexture(0.72, 0.58);
    drawPolyShape(p.pts, 0.08);

    // 3. Secondary overlapping watercolor glaze for mottled boro depth
    brush.fill(p.col2, p.isRust ? 115 : 85);
    brush.fillBleed(0.38, "in");
    brush.fillTexture(0.68, 0.48);
    drawPolyShape(p.upperPts, 0.10);

    // Extra rich terracotta fold glaze on the single rust-orange square
    if (p.isRust) {
      let lowerRustPts = buildPatchBoundary(p.u0 + 0.01, p.u1 - 0.01, 0.62, p.v1 - 0.01, 5, 4, 2.5, 777);
      brush.fill(p.colShadow, 95);
      brush.fillBleed(0.32, "in");
      brush.fillTexture(0.75, 0.6);
      drawPolyShape(lowerRustPts, 0.08);
    }
  }
  brush.noFill();

  // -------------------------------------------------------------------------
  // PASS B: 3D Draping Volume Shading (Roof Sky-Sheen, Gunwale Ridge & Fold Valleys)
  // -------------------------------------------------------------------------
  drawTarp3DVolumeGlazes();

  // -------------------------------------------------------------------------
  // PASS C: Salt Stains & Evaporative Tide Blooms
  // -------------------------------------------------------------------------
  drawSaltStains();

  // -------------------------------------------------------------------------
  // PASS D: Woven Canvas Texture, Sun-Bleached Creases & Dry-Brush Frayed Edges
  // -------------------------------------------------------------------------
  for (let p of patches) {
    drawPatchWeaveAndFraying(p);
  }

  drawSunBleachedCreases();

  // -------------------------------------------------------------------------
  // PASS E: Pen-Drawn Boro Sashiko Running Stitches & Cross-Mending
  // -------------------------------------------------------------------------
  for (let p of patches) {
    drawPatchStitches(p);
  }
}

function drawTarp3DVolumeGlazes() {
  brush.noStroke();
  brush.noHatch();

  // 1. Soft overcast sky-sheen along the upper roof slope (v: 0.0 .. 0.36)
  let roofSheenPts = buildPatchBoundary(0.02, 0.96, 0.01, 0.34, 16, 4, 2.0, 401);
  brush.fill("#e6ebf0", 42);
  brush.fillBleed(0.45, "in");
  brush.fillTexture(0.5, 0.25);
  drawPolyShape(roofSheenPts, 0.08);

  // 2. Deep soft shadow valleys in the sagging troughs between grommets & thwarts
  const foldValleys = [
    { u0: 0.05, u1: 0.14, v0: 0.44, v1: 0.96 },
    { u0: 0.19, u1: 0.28, v0: 0.42, v1: 0.95 },
    { u0: 0.32, u1: 0.40, v0: 0.46, v1: 0.96 },
    { u0: 0.47, u1: 0.56, v0: 0.44, v1: 0.96 },
    { u0: 0.61, u1: 0.70, v0: 0.44, v1: 0.95 },
    { u0: 0.74, u1: 0.83, v0: 0.45, v1: 0.95 },
    { u0: 0.86, u1: 0.95, v0: 0.46, v1: 0.94 }
  ];

  brush.fill("#233044", 52);
  brush.fillBleed(0.42, "out");
  brush.fillTexture(0.65, 0.4);
  for (let fv of foldValleys) {
    let pTop = tarpPoint( lerp(fv.u0, fv.u1, 0.5), fv.v0 );
    let pLeft = tarpPoint(fv.u0, fv.v1);
    let pRight = tarpPoint(fv.u1, fv.v1);
    drawPolyShape([pTop, pRight, pLeft], 0.15);
  }
  brush.noFill();
}

function drawSaltStains() {
  // Irregular crusty white/ecru salt stain blooms & watermarks along lower flank and bow
  const saltZones = [
    { u0: 0.02, u1: 0.16, v0: 0.52, v1: 0.88, op: 65 },
    { u0: 0.18, u1: 0.33, v0: 0.66, v1: 0.96, op: 70 },
    { u0: 0.34, u1: 0.46, v0: 0.68, v1: 0.92, op: 60 }, // Overlaps lower corner of rust-orange square
    { u0: 0.49, u1: 0.65, v0: 0.64, v1: 0.95, op: 65 },
    { u0: 0.68, u1: 0.85, v0: 0.62, v1: 0.94, op: 60 },
    { u0: 0.22, u1: 0.40, v0: 0.12, v1: 0.38, op: 50 },
    { u0: 0.58, u1: 0.75, v0: 0.15, v1: 0.42, op: 55 }
  ];

  brush.noStroke();
  brush.noHatch();
  for (let i = 0; i < saltZones.length; i++) {
    let sz = saltZones[i];
    let pts = buildPatchBoundary(sz.u0, sz.u1, sz.v0, sz.v1, 7, 6, 9.5, 600 + i * 17);
    brush.fill("#eaedea", sz.op);
    brush.fillBleed(0.38, "out");
    // High borderIntensity creates the classic watercolor salt-ring tide line
    brush.fillTexture(0.82, 0.88);
    drawPolyShape(pts, 0.22);
  }
  brush.noFill();

  // Dry-brush salt ring tide contours and granular salt crust
  for (let i = 0; i < saltZones.length; i++) {
    let sz = saltZones[i];
    let pts = buildPatchBoundary(sz.u0, sz.u1, sz.v0, sz.v1, 9, 7, 8.5, 600 + i * 17);
    brush.set("chalk_crease", "#f2f4f0", 0.65);
    drawPolyShape(pts, 0.22, true);

    brush.set("spray", "#f4f5f2", 0.75);
    let pA = tarpPoint(sz.u0, lerp(sz.v0, sz.v1, 0.5));
    let pB = tarpPoint(sz.u1, lerp(sz.v0, sz.v1, 0.5));
    brush.line(pA[0], pA[1], pB[0], pB[1]);
  }
}

function drawPatchWeaveAndFraying(p) {
  // 1. Subtle woven canvas warp & weft lines following the 3D surface of the patch
  let warpSteps = p.isRust ? 14 : 9;
  let weftSteps = p.isRust ? 14 : 8;

  let weaveLight = p.isRust ? "#ebb29b" : "#dce6ef";
  let weaveDark = p.isRust ? "#8f4029" : "#26364d";

  // Horizontal warp threads (along u)
  brush.set("2H", weaveLight, p.isRust ? 0.52 : 0.38);
  for (let i = 1; i < weftSteps; i++) {
    let v = lerp(p.v0 + 0.012, p.v1 - 0.012, i / weftSteps);
    let p1 = tarpPoint(p.u0 + 0.008, v);
    let pMid = tarpPoint(lerp(p.u0, p.u1, 0.5), v);
    let p2 = tarpPoint(p.u1 - 0.008, v);
    brush.spline([p1, pMid, p2], 0.25);
  }

  // Vertical weft threads (along v)
  brush.set("2H", weaveDark, p.isRust ? 0.48 : 0.35);
  for (let i = 1; i < warpSteps; i++) {
    let u = lerp(p.u0 + 0.008, p.u1 - 0.008, i / warpSteps);
    let p1 = tarpPoint(u, p.v0 + 0.012);
    let pMid = tarpPoint(u, lerp(p.v0, p.v1, 0.5));
    let p2 = tarpPoint(u, p.v1 - 0.012);
    brush.spline([p1, pMid, p2], 0.25);
  }

  // 2. Irregular raw fabric contour around the patch
  brush.set("HB", p.isRust ? "#7d3420" : "#25344a", 0.65);
  drawPolyShape(p.pts, 0.08, true);

  // 3. Dry-brush fraying along all 4 edges of the patch!
  let nPts = p.pts.length;
  let frayCol1 = p.isRust ? "#f0c2ae" : "#e3e8ec";
  let frayCol2 = p.isRust ? "#d47b5f" : p.col2;

  for (let i = 0; i < nPts; i++) {
    let a = p.pts[i];
    let b = p.pts[(i + 1) % nPts];
    let segDist = dist(a[0], a[1], b[0], b[1]);
    let numFrays = floor(segDist / (p.isRust ? 4.5 : 7.5));

    let dx = b[0] - a[0];
    let dy = b[1] - a[1];
    let len = max(1, sqrt(dx * dx + dy * dy));
    // Outward normal
    let nx = dy / len;
    let ny = -dx / len;

    for (let f = 0; f < numFrays; f++) {
      let t = (f + random(0.1, 0.9)) / max(1, numFrays);
      let fx = lerp(a[0], b[0], t);
      let fy = lerp(a[1], b[1], t);

      let frayLen = random(4, p.isRust ? 14 : 10);
      let jitterAng = random(-28, 28);
      let outX = nx * cos(jitterAng) - ny * sin(jitterAng);
      let outY = nx * sin(jitterAng) + ny * cos(jitterAng);

      brush.set("fray_fiber", f % 2 === 0 ? frayCol1 : frayCol2, random(0.45, 0.85));
      brush.line(
        fx - outX * 2,
        fy - outY * 2,
        fx + outX * frayLen,
        fy + outY * frayLen
      );
    }
  }
}

function drawSunBleachedCreases() {
  // Long tension folds & sun-bleached ridge creases across the tarpaulin
  // 1. Main sweeping gunwale ridge crease (v = 0.42)
  let gunwaleCrease = [];
  for (let i = 0; i <= 32; i++) {
    gunwaleCrease.push(tarpPoint(i / 32, 0.42, 1.5));
  }
  brush.set("chalk_crease", "#eef2f5", 1.15);
  brush.spline(gunwaleCrease, 0.35);

  brush.set("cpencil", "#f5f7f8", 0.8);
  brush.spline(gunwaleCrease.map(p => [p[0], p[1] - 1.5]), 0.35);

  brush.set("2B", "#2b3b52", 0.75);
  brush.spline(gunwaleCrease.map(p => [p[0], p[1] + 2.5]), 0.35);

  // 2. Top ridge pole highlight crease (v = 0.01)
  let ridgeCrease = [];
  for (let i = 0; i <= 28; i++) {
    ridgeCrease.push(tarpPoint(i / 28, 0.015, 1.2));
  }
  brush.set("chalk_crease", "#f2f4f6", 1.05);
  brush.spline(ridgeCrease, 0.3);

  // 3. Radiating tension creases from each hem grommet up toward gunwale & roof crutches
  for (let i = 0; i < GROMMET_U.length; i++) {
    let gu = GROMMET_U[i];
    // Left and right diagonal tension lines from each grommet
    let targets = [
      { u: constrain(gu - 0.07, 0.01, 0.99), v: 0.42 },
      { u: constrain(gu + 0.06, 0.01, 0.99), v: 0.42 },
      { u: constrain(gu - 0.03, 0.02, 0.98), v: 0.04 }
    ];

    for (let tgt of targets) {
      let pStart = tarpPoint(gu, 0.98);
      let pMid = tarpPoint(lerp(gu, tgt.u, 0.5), lerp(0.98, tgt.v, 0.5) + random(-0.03, 0.03));
      let pEnd = tarpPoint(tgt.u, tgt.v);

      // Dark fold shadow trough
      brush.set("2B", "#223044", 0.65);
      brush.spline([
        [pStart[0] + 2, pStart[1]],
        [pMid[0] + 2, pMid[1] + 1],
        [pEnd[0] + 1, pEnd[1]]
      ], 0.3);

      // Sun-bleached crest highlight right beside the trough
      brush.set("chalk_crease", "#edf2f6", 0.75);
      brush.spline([pStart, pMid, pEnd], 0.3);

      brush.set("cpencil", "#f4f6f8", 0.55);
      brush.spline([pStart, pMid, pEnd], 0.3);
    }
  }
}

// ============================================================================
// PEN-DRAWN BORO RUNNING STITCHES & SASHIKO MENDING
// ============================================================================

function drawRunningStitchLine(p1, p2, threadCol, stitchLen = 6.5, gapLen = 4.5) {
  let d = dist(p1[0], p1[1], p2[0], p2[1]);
  if (d < 6) return;
  let step = stitchLen + gapLen;
  let count = floor(d / step);
  let dx = (p2[0] - p1[0]) / d;
  let dy = (p2[1] - p1[1]) / d;
  // Normal for slight hand-stitched irregularity
  let nx = -dy;
  let ny = dx;

  for (let i = 0; i < count; i++) {
    let d0 = i * step + random(-0.6, 0.6);
    let d1 = d0 + stitchLen + random(-0.8, 0.8);
    if (d1 > d) break;

    let wob = random(-0.9, 0.9);
    let x0 = p1[0] + dx * d0 + nx * wob;
    let y0 = p1[1] + dy * d0 + ny * wob;
    let x1 = p1[0] + dx * d1 + nx * wob;
    let y1 = p1[1] + dy * d1 + ny * wob;

    // Tiny needle-hole pinhole & thread shadow in dark ink
    brush.set("rotring", "#182230", 0.55);
    brush.line(x0, y0 + 1.0, x1, y1 + 1.0);

    // Visible sashiko running stitch thread on top
    brush.set("sashiko_thread", threadCol, 0.78);
    brush.line(x0, y0, x1, y1);
  }
}

function drawWhippedSeamEdge(p1, p2, threadCol, spacing = 8.5) {
  let d = dist(p1[0], p1[1], p2[0], p2[1]);
  if (d < 8) return;
  let count = floor(d / spacing);
  let dx = (p2[0] - p1[0]) / d;
  let dy = (p2[1] - p1[1]) / d;
  let nx = -dy;
  let ny = dx;

  for (let i = 1; i < count; i++) {
    let distAlong = i * spacing + random(-1, 1);
    let cx = p1[0] + dx * distAlong;
    let cy = p1[1] + dy * distAlong;
    let slant = random(-1.8, 1.8);
    let halfLen = random(3.8, 5.5);

    let x0 = cx - nx * halfLen + dx * slant;
    let y0 = cy - ny * halfLen + dy * slant;
    let x1 = cx + nx * halfLen - dx * slant;
    let y1 = cy + ny * halfLen - dy * slant;

    brush.set("rotring", "#1a2433", 0.5);
    brush.line(x0 + 0.8, y0 + 0.8, x1 + 0.8, y1 + 0.8);

    brush.set("sashiko_thread", threadCol, 0.72);
    brush.line(x0, y0, x1, y1);
  }
}

function drawPatchStitches(p) {
  // 1. Perimeter running stitch inset slightly from the raw frayed edge
  let insetU0 = p.u0 + 0.007;
  let insetU1 = p.u1 - 0.007;
  let insetV0 = p.v0 + 0.014;
  let insetV1 = p.v1 - 0.014;

  let cTL = tarpPoint(insetU0, insetV0);
  let cTM = tarpPoint(lerp(insetU0, insetU1, 0.5), insetV0);
  let cTR = tarpPoint(insetU1, insetV0);
  let cRM = tarpPoint(insetU1, lerp(insetV0, insetV1, 0.5));
  let cBR = tarpPoint(insetU1, insetV1);
  let cBM = tarpPoint(lerp(insetU0, insetU1, 0.5), insetV1);
  let cBL = tarpPoint(insetU0, insetV1);
  let cLM = tarpPoint(insetU0, lerp(insetV0, insetV1, 0.5));

  // Draw perimeter running stitches along all 4 sides
  drawRunningStitchLine(cTL, cTM, p.threadCol, 6.5, 4.2);
  drawRunningStitchLine(cTM, cTR, p.threadCol, 6.5, 4.2);
  drawRunningStitchLine(cTR, cRM, p.threadCol, 6.5, 4.2);
  drawRunningStitchLine(cRM, cBR, p.threadCol, 6.5, 4.2);
  drawRunningStitchLine(cBR, cBM, p.threadCol, 6.5, 4.2);
  drawRunningStitchLine(cBM, cBL, p.threadCol, 6.5, 4.2);
  drawRunningStitchLine(cBL, cLM, p.threadCol, 6.5, 4.2);
  drawRunningStitchLine(cLM, cTL, p.threadCol, 6.5, 4.2);

  // 2. Specialized Boro / Sashiko interior darning patterns
  if (p.stitchType === "boro_rows" || p.isRust) {
    let numRows = p.isRust ? 9 : 5;
    for (let r = 1; r < numRows; r++) {
      let v = lerp(insetV0 + 0.015, insetV1 - 0.015, r / numRows);
      // On the rust patch, concentrate sashiko rows in upper/left zones and leave lower right breathing room
      let uStart = insetU0 + 0.008;
      let uEnd = p.isRust && r > 5 ? lerp(insetU0, insetU1, 0.62) : insetU1 - 0.008;
      let pLeft = tarpPoint(uStart, v);
      let pMid = tarpPoint(lerp(uStart, uEnd, 0.5), v);
      let pRight = tarpPoint(uEnd, v);
      drawRunningStitchLine(pLeft, pMid, p.threadCol, 5.5, 4.0);
      drawRunningStitchLine(pMid, pRight, p.threadCol, 5.5, 4.0);
    }
  }

  if (p.stitchType === "cross_mend" || p.isRust) {
    // Whipped overcast stitches locking the raw overlap seam down
    let rawTL = tarpPoint(p.u0, p.v0);
    let rawTR = tarpPoint(p.u1, p.v0);
    let rawBL = tarpPoint(p.u0, p.v1);
    let rawBR = tarpPoint(p.u1, p.v1);
    drawWhippedSeamEdge(rawTL, rawTR, p.threadCol, 9.0);
    drawWhippedSeamEdge(rawBL, rawBR, p.threadCol, 9.5);
    if (p.isRust) {
      drawWhippedSeamEdge(rawTL, rawBL, p.threadCol, 9.0);
      drawWhippedSeamEdge(rawTR, rawBR, p.threadCol, 9.0);

      // Double inner perimeter track on the focal rust-orange square
      let in2TL = tarpPoint(p.u0 + 0.015, p.v0 + 0.028);
      let in2TR = tarpPoint(p.u1 - 0.015, p.v0 + 0.028);
      let in2BR = tarpPoint(p.u1 - 0.015, p.v1 - 0.028);
      let in2BL = tarpPoint(p.u0 + 0.015, p.v1 - 0.028);
      drawRunningStitchLine(in2TL, in2TR, "#26364f", 6.0, 4.0);
      drawRunningStitchLine(in2TR, in2BR, "#26364f", 6.0, 4.0);
      drawRunningStitchLine(in2BR, in2BL, "#26364f", 6.0, 4.0);
      drawRunningStitchLine(in2BL, in2TL, "#26364f", 6.0, 4.0);
    }
  }
}

