function drawGrommetRing(x, y, radius = 9.5) {
  // 1. Radial canvas puckers around the grommet
  brush.set("2B", "#1e2a3a", 0.55);
  for (let a = 0; a < 360; a += 40) {
    let r1 = radius + 1.5;
    let r2 = radius + random(6, 13);
    brush.line(
      x + cos(a) * r1, y + sin(a) * r1,
      x + cos(a) * r2, y + sin(a) * r2
    );
  }

  // 2. Brass/oxidized iron outer ring & dark inner hole
  brush.noStroke();
  brush.fill("#7d7665", 210);
  brush.fillBleed(0.04, "in");
  brush.circle(x, y, radius, 0.08);

  brush.fill("#22252a", 235);
  brush.circle(x, y, radius * 0.52, 0.06);
  brush.noFill();

  // 3. Crisp pen & highlight rim contours
  brush.set("rotring", "#1a1d22", 0.75);
  brush.circle(x, y, radius, 0.08);
  brush.circle(x, y, radius * 0.54, 0.06);

  brush.set("cpencil", "#e8e2d3", 0.65);
  brush.arc(x, y, radius * 0.8, 200, 340);
}

function drawTwistedRope(pts, thickness = 1.0) {
  if (!pts || pts.length < 2) return;

  // 1. Soft drop shadow of the rope on the canvas/hull/shingle beneath
  let shadowPts = pts.map(p => [p[0] + 4.5, p[1] + 5.5]);
  brush.set("charcoal", "#1f2630", 1.15 * thickness);
  brush.spline(shadowPts, 0.35);

  // 2. Base hemp/manila rope core
  brush.set("cpencil", "#b5a284", 1.45 * thickness);
  brush.spline(pts, 0.35);

  brush.set("HB", "#dfd4be", 0.9 * thickness);
  let hiPts = pts.map(p => [p[0] - 0.8, p[1] - 0.8]);
  brush.spline(hiPts, 0.35);

  // 3. Individual diagonal twisted 3-strand ply segments along the curve
  for (let i = 0; i < pts.length - 1; i++) {
    let a = pts[i];
    let b = pts[i + 1];
    let d = dist(a[0], a[1], b[0], b[1]);
    let steps = max(1, floor(d / 6.5));
    let dx = (b[0] - a[0]) / d;
    let dy = (b[1] - a[1]) / d;
    let nx = -dy;
    let ny = dx;

    for (let s = 0; s < steps; s++) {
      let t = (s + 0.5) / steps;
      let cx = lerp(a[0], b[0], t);
      let cy = lerp(a[1], b[1], t);
      let w = 2.6 * thickness;

      // Diagonal twist line & dark crease between strands
      brush.set("rotring", "#4a3e2e", 0.55);
      brush.line(
        cx - nx * w - dx * 2.2, cy - ny * w - dy * 2.2,
        cx + nx * w + dx * 2.2, cy + ny * w + dy * 2.2
      );
    }
  }
}

function drawRopeKnot(x, y, scaleSz = 1.0, hasTails = true) {
  // Multi-loop bulky bowline / reef knot at grommet or lashing junction
  let r = 8.5 * scaleSz;

  // Knot shadow
  brush.noStroke();
  brush.fill("#1e242d", 130);
  brush.fillBleed(0.15, "out");
  brush.circle(x + 3, y + 4, r * 1.2, 0.15);
  brush.noFill();

  // Overlapping hemp wraps
  const wraps = [
    [[x - r, y - r * 0.4], [x, y - r * 0.8], [x + r, y + r * 0.2]],
    [[x - r * 0.8, y + r * 0.5], [x + r * 0.2, y], [x + r * 0.9, y - r * 0.5]],
    [[x - r * 0.3, y - r * 0.9], [x - r * 0.4, y + r * 0.2], [x + r * 0.4, y + r * 0.9]]
  ];

  for (let w of wraps) {
    brush.set("cpencil", "#c7b699", 1.35 * scaleSz);
    brush.spline(w, 0.4);
    brush.set("rotring", "#3d3325", 0.6 * scaleSz);
    brush.spline(w.map(p => [p[0] + 1.2, p[1] + 1.2]), 0.4);
    brush.set("cpencil", "#ebe3d1", 0.7 * scaleSz);
    brush.spline(w.map(p => [p[0] - 0.8, p[1] - 0.8]), 0.4);
  }

  // Frayed rope tail tassels hanging from the knot
  if (hasTails) {
    let tail1 = [
      [x + 2, y + 4],
      [x + 10 * scaleSz, y + 22 * scaleSz],
      [x + 6 * scaleSz, y + 42 * scaleSz]
    ];
    drawTwistedRope(tail1, 0.75 * scaleSz);

    // Unravelled brushy hemp fibers at the end of the tail
    let tip = tail1[2];
    for (let f = 0; f < 9; f++) {
      brush.set("fray_fiber", f % 2 === 0 ? "#e8dfc9" : "#9c8a6e", 0.75);
      brush.line(tip[0], tip[1], tip[0] + random(-9, 9), tip[1] + random(6, 16));
    }
  }
}

function drawGrommetsAndRopes() {
  // 1. Collect hem grommet coordinates
  let hemGrommets = [];
  for (let i = 0; i < GROMMET_U.length; i++) {
    let u = GROMMET_U[i];
    let pt = tarpPoint(u, 0.965);
    hemGrommets.push({ u, x: pt[0], y: pt[1] });
  }

  // 2. Collect mid-tarpaulin boro patch grommets (including corners of the rust-orange square!)
  const midGrommets = [
    tarpPoint(0.20, 0.58),
    tarpPoint(0.362, 0.485), // Top-left corner of the rust-orange square
    tarpPoint(0.474, 0.485), // Top-right corner of the rust-orange square
    tarpPoint(0.362, 0.738), // Bottom-left corner of the rust-orange square
    tarpPoint(0.65, 0.52),
    tarpPoint(0.79, 0.46),
    [130, 468]               // Port bow hood corner grommet
  ];

  // 3. Draw cross-tarpaulin lashing ropes (thrown over the ridge & laced between mid-grommets)
  const overTarpRopes = [
    // Forward breast lashing from port bow hood across stem to fore grommets
    [
      [130, 468],
      tarpPoint(0.03, 0.55),
      tarpPoint(0.11, 0.72),
      [hemGrommets[1].x, hemGrommets[1].y]
    ],
    // Lashing over the forward-mid ridge down through the rust-orange square's grommets!
    [
      tarpPoint(0.28, 0.00),
      tarpPoint(0.32, 0.24),
      tarpPoint(0.362, 0.485),
      tarpPoint(0.362, 0.738),
      [hemGrommets[3].x, hemGrommets[3].y]
    ],
    // Diagonal lashing tying the top-right corner of the rust-orange square to midships
    [
      tarpPoint(0.474, 0.485),
      tarpPoint(0.56, 0.50),
      tarpPoint(0.65, 0.52),
      [hemGrommets[5].x, hemGrommets[5].y]
    ],
    // Aft-quarter over-ridge lashing rope
    [
      tarpPoint(0.72, 0.00),
      tarpPoint(0.76, 0.25),
      tarpPoint(0.79, 0.46),
      [hemGrommets[6].x, hemGrommets[6].y]
    ]
  ];

  for (let rPts of overTarpRopes) {
    drawTwistedRope(rPts, 1.0);
  }

  // 4. Zig-zag & vertical tie-down ropes from hem grommets under the keel & to shingle anchors
  for (let i = 0; i < hemGrommets.length; i++) {
    let g = hemGrommets[i];
    let kPt = evalCurve(KEEL_PTS, g.u);

    // Vertical/angled tie-down passing under the keel / timber skids
    let anchorX = kPt[0] + random(-18, 22);
    let anchorY = kPt[1] + random(10, 28);
    drawTwistedRope([
      [g.x, g.y],
      [lerp(g.x, anchorX, 0.5) + random(-6, 6), lerp(g.y, anchorY, 0.5)],
      [anchorX, anchorY]
    ], 0.95);

    // Diagonal lacing between adjacent grommets and keel
    if (i < hemGrommets.length - 1) {
      let gNext = hemGrommets[i + 1];
      let midKeel = evalCurve(KEEL_PTS, lerp(g.u, gNext.u, 0.5));
      drawTwistedRope([
        [g.x, g.y],
        [midKeel[0], midKeel[1] - 4],
        [gNext.x, gNext.y]
      ], 0.82);
    }
  }

  // Long bow painter / anchor hawser stretching from the bow stem down onto the foreground shingle
  let bowHawser = [
    [164, 514],
    [138, 635],
    [108, 775],
    [145, 915],
    [235, 985],
    [295, 972]
  ];
  drawTwistedRope(bowHawser, 1.35);

  // Coiled rope loops resting on the foreground shingle at the end of the bow hawser
  for (let c = 0; c < 3; c++) {
    let cx = 275 + c * 12;
    let cy = 975 + c * 6;
    let coilPts = [
      [cx - 38, cy - 8],
      [cx, cy - 22],
      [cx + 42, cy - 4],
      [cx + 12, cy + 16],
      [cx - 32, cy + 10],
      [cx - 38, cy - 8]
    ];
    drawTwistedRope(coilPts, 1.05);
  }

  // 5. Render the metallic grommet rings and bulky knots on top of the rope entry points
  for (let i = 0; i < hemGrommets.length; i++) {
    let g = hemGrommets[i];
    drawGrommetRing(g.x, g.y, 9.5);
    drawRopeKnot(g.x, g.y + 4, 0.9, i % 2 === 1);
  }

  for (let i = 0; i < midGrommets.length; i++) {
    let mg = midGrommets[i];
    drawGrommetRing(mg[0], mg[1], 8.5);
    drawRopeKnot(mg[0], mg[1] + 2, 0.85, true);
  }
}

