    { u: 0.48, v: 0.74, dx: 16,  dy: 28, col: "#e89c82" },
    { u: 0.35, v: 0.62, dx: -22, dy: 14, col: "#f4efe4" },
    { u: 0.21, v: 0.35, dx: 18,  dy: 24, col: "#dce4ec" },
    { u: 0.55, v: 0.44, dx: -14, dy: 28, col: "#ebe7df" },
    { u: 0.68, v: 0.65, dx: 20,  dy: 22, col: "#dce5ed" },
    { u: 0.14, v: 0.58, dx: -16, dy: 25, col: "#f0ece2" },
    { u: 0.82, v: 0.52, dx: 15,  dy: 24, col: "#e8e4da" }
