// Hyperrealism in p5.brush: Drying Clay Mask & Living Skin in Raking Light
// Palette: Umber, Bone, Dusty Ochre, Grey-Ochre, Flushed Rose, Sepia Ink

const SEED = 7482;

// Raking light direction from upper-right (grazing across the cheek toward the left)
const LIGHT_3D = (() => {
  let lx = 0.87, ly = -0.26, lz = 0.42;
  let len = Math.hypot(lx, ly, lz);
  return { x: lx / len, y: ly / len, z: lz / len };
})();

const LIGHT_2D = (() => {
  let len = Math.hypot(LIGHT_3D.x, LIGHT_3D.y);
  return { x: LIGHT_3D.x / len, y: LIGHT_3D.y / len };
})();

// Master Earth & Skin Palette
const PALETTE = {
