  // Living skin watercolor glazes (flushed rose, peach-ochre, warm umber)
  skinBase: ["#e4baa2", "#d89f86", "#cfa488"],
  skinRose: ["#ce7b68", "#be6453", "#b05243", "#da8e7b"],
  skinShadow: ["#8c5543", "#6e3e2f", "#532c20"],
