// ---------------------------------------------------------------------------
// ANATOMICAL CURVES & 3D FACIAL TOPOGRAPHY
// ---------------------------------------------------------------------------

// Closed eyelid slit (palpebral fissure): medial (265, 354) -> lateral (835, 326)
function getEyelidSlitY(x) {
  let t = constrain((x - 265) / 570, 0, 1);
  let base = 354 * (1 - t) + 326 * t;
  let bow = 74 * Math.pow(Math.sin(Math.PI * t), 1.15) - 9 * Math.sin(2 * Math.PI * t);
  return base + bow;
}

// Supratarsal fold (upper eyelid crease): arches upward over the eyeball globe
function getUpperCreaseY(x) {
  let t = constrain((x - 245) / 615, 0, 1);
  let base = 310 * (1 - t) + 292 * t;
  let arch = -70 * Math.pow(Math.sin(Math.PI * t), 0.95) - 7 * Math.sin(2 * Math.PI * t);
  return base + arch;
}

// Lower eyelid fold (infraorbital crease)
function getLowerCreaseY(x) {
  let t = constrain((x - 275) / 555, 0, 1);
  let base = 378 * (1 - t) + 356 * t;
  let bow = 92 * Math.pow(Math.sin(Math.PI * t), 1.12);
  return base + bow;
}

// Eyebrow lower border arch
function getBrowY(x) {
  let t = constrain((x - 230) / 680, 0, 1);
  let base = 160 * (1 - t) + 168 * t;
  let arch = -64 * Math.sin(Math.PI * Math.pow(t, 1.15));
  return base + arch;
}

// Smooth Gaussian helper
function gauss2D(x, y, cx, cy, rx, ry, angleDeg = 0) {
  let rad = (angleDeg * Math.PI) / 180;
  let dx = x - cx, dy = y - cy;
  let ux = dx * Math.cos(rad) + dy * Math.sin(rad);
  let uy = -dx * Math.sin(rad) + dy * Math.cos(rad);
  let d2 = (ux * ux) / (rx * rx) + (uy * uy) / (ry * ry);
  return Math.exp(-d2);
}

// Analytical 3D elevation of the face (in virtual pixels z)
function getFaceElevation(x, y) {
  let z = 0;

  // 1. Broad facial cylinder sloping away at left (nasal side) and far right (temple)
  z += 90 * gauss2D(x, y, 640, 650, 680, 750, -5);

  // 2. Malar eminence (the lush prominence of the cheekbone & cheek dome)
  z += 155 * gauss2D(x, y, 665, 705, 430, 390, -14);
  z += 55 * gauss2D(x, y, 860, 560, 280, 230, -22); // Zygomatic arch toward temple

  // 3. Nasal bridge & side-wall on the left side of the canvas
  z += 120 * gauss2D(x, y, 35, 390, 175, 480, 8);

  // 4. Nasojugal groove (tear trough) & nasolabial valley separating nose and cheek
  z -= 42 * gauss2D(x, y, 225, 485, 130, 210, 28);
  z -= 35 * gauss2D(x, y, 185, 840, 140, 280, 14);

  // 5. Orbital socket recession & spherical eyeball mound beneath the closed lid
  z -= 38 * gauss2D(x, y, 545, 315, 310, 185, -4);
  z += 64 * gauss2D(x, y, 555, 332, 165, 112, -3); // Eyeball convexity

  // 6. Upper eyelid crease groove & lower eyelid cushion (pretarsal fullness)
  if (x > 230 && x < 880) {
    let yc = getUpperCreaseY(x);
    let dc = Math.abs(y - yc);
    z -= 16 * Math.exp(-(dc * dc) / (22 * 22));
    // Fold overhang just above crease
    if (y < yc) z += 10 * Math.exp(-((yc - y - 14) ** 2) / (26 * 26));

    let yl = getEyelidSlitY(x);
    let dl = Math.abs(y - yl);
    z -= 8 * Math.exp(-(dl * dl) / (9 * 9)); // Palpebral cleft

    // Lower lid cushion between slit and infraorbital crease
    let ylow = getLowerCreaseY(x);
    let ymid = 0.55 * yl + 0.45 * ylow;
    z += 12 * Math.exp(-((y - ymid) ** 2) / (28 * 28));
    z -= 9 * Math.exp(-((y - ylow) ** 2) / (20 * 20));
  }

  // 7. Brow bone ridge along top
  z += 52 * gauss2D(x, y, 575, 115, 420, 115, -3);

  return z;
}

// Surface normal & local illumination under raking light
function getFaceNormal(x, y) {
  let eps = 3.0;
  let dzdx = (getFaceElevation(x + eps, y) - getFaceElevation(x - eps, y)) / (2 * eps);
  let dzdy = (getFaceElevation(x, y + eps) - getFaceElevation(x, y - eps)) / (2 * eps);
  // Scale z-gradient for strong sculptural raking relief
  let sx = -dzdx * 1.45;
  let sy = -dzdy * 1.45;
  let sz = 1.0;
  let len = Math.hypot(sx, sy, sz);
  return { x: sx / len, y: sy / len, z: sz / len };
}

function getIllumination(x, y) {
  let n = getFaceNormal(x, y);
  let dot = n.x * LIGHT_3D.x + n.y * LIGHT_3D.y + n.z * LIGHT_3D.z;
  return constrain(dot, 0, 1);
}

// Signed Distance Function for the clay mask boundary around the orbital opening
// < 0: bare orbital skin around the closed eye
// > 0: clay-masked face (cheek, nasal bridge, temple, upper brow margin)
function getMaskSDF(x, y) {
  let cx = 556, cy = 320;
  let rad = (-3.5 * Math.PI) / 180;
  let dx = x - cx, dy = y - cy;
  let ux = dx * Math.cos(rad) + dy * Math.sin(rad);
  let uy = -dx * Math.sin(rad) + dy * Math.cos(rad);

  // Asymmetric orbital opening: wider laterally, dipping below infraorbital crease
  let rx = ux < 0 ? 355 : 385;
  let ry = uy < 0 ? 185 : 196;

  // Slight anatomical pinch near medial canthus and tear trough
  if (ux < -120 && uy > 0) {
    ry += 24 * Math.sin(constrain((-ux - 120) / 220, 0, 1) * Math.PI);
  }

  let normDist = Math.hypot(ux / rx, uy / ry);
  let pixelDist = (normDist - 1.0) * 265;

  // Hand-spread organic clay border perturbation
  let n1 = (noise(x * 0.008 + 10, y * 0.008 + 20) - 0.5) * 38;
  let n2 = (noise(x * 0.025 + 50, y * 0.025 + 70) - 0.5) * 16;
  let n3 = (noise(x * 0.07 + 90, y * 0.07 + 30) - 0.5) * 7;

  return pixelDist + n1 + n2 + n3;
}

// ---------------------------------------------------------------------------
// CRAQUELURE NETWORK GENERATOR (Relaxed Voronoi + 90° T-Junction Subdivisions)
// ---------------------------------------------------------------------------

function clipPolygonHalfPlane(poly, px, py, nx, ny) {
  if (poly.length === 0) return [];
  let out = [];
  for (let i = 0; i < poly.length; i++) {
    let cur = poly[i];
    let prev = poly[(i + poly.length - 1) % poly.length];
    let dCur = (cur[0] - px) * nx + (cur[1] - py) * ny;
    let dPrev = (prev[0] - px) * nx + (prev[1] - py) * ny;

    if (dCur <= 0) {
      if (dPrev > 0) {
        let t = dPrev / (dPrev - dCur);
        out.push([prev[0] + t * (cur[0] - prev[0]), prev[1] + t * (cur[1] - prev[1])]);
      }
      out.push(cur);
    } else if (dPrev <= 0) {
      let t = dPrev / (dPrev - dCur);
      out.push([prev[0] + t * (cur[0] - prev[0]), prev[1] + t * (cur[1] - prev[1])]);
    }
  }
  return out;
}

function polygonCentroidAndArea(pts) {
  let area = 0, cx = 0, cy = 0;
  for (let i = 0; i < pts.length; i++) {
    let p0 = pts[i], p1 = pts[(i + 1) % pts.length];
    let cross = p0[0] * p1[1] - p1[0] * p0[1];
    area += cross;
    cx += (p0[0] + p1[0]) * cross;
    cy += (p0[1] + p1[1]) * cross;
  }
  area *= 0.5;
  if (Math.abs(area) < 1e-3) {
    let sx = 0, sy = 0;
    for (let p of pts) { sx += p[0]; sy += p[1]; }
    return { cx: sx / pts.length, cy: sy / pts.length, area: 0 };
  }
  return { cx: cx / (6 * area), cy: cy / (6 * area), area: Math.abs(area) };
}

function buildCraquelurePlates() {
  // 1. Adaptive seed placement: finer plates near orbital border, broader on central cheek
  let seeds = [];
  let y = -45;
  while (y < 1255) {
    let x = -45;
    while (x < 1255) {
      let sdf = getMaskSDF(x, y);
      let step = sdf < 80 ? map(constrain(sdf, -20, 80), -20, 80, 27, 48) : 50;
      // Slightly smaller plates over high curvature of nasal bridge and upper cheekbone
      if (x < 240) step *= 0.85;
      if (y > 950) step *= 1.1;

      if (sdf > -28) {
        let jx = x + random(-step * 0.42, step * 0.42);
        let jy = y + random(-step * 0.42, step * 0.42);
        if (getMaskSDF(jx, jy) > -24) {
          seeds.push({ x: jx, y: jy });
        }
      }
      x += step;
    }
    y += 40;
  }

  // Helper to compute bounded Voronoi cells
  const computeCells = (pts) => {
    let cells = [];
    for (let i = 0; i < pts.length; i++) {
      let si = pts[i];
      let rad = 140;
      let poly = [
        [si.x - rad, si.y - rad],
        [si.x + rad, si.y - rad],
        [si.x + rad, si.y + rad],
        [si.x - rad, si.y + rad]
      ];

      // Find nearby seeds
      let neighbors = [];
      for (let j = 0; j < pts.length; j++) {
        if (i === j) continue;
        let dx = pts[j].x - si.x, dy = pts[j].y - si.y;
        let d2 = dx * dx + dy * dy;
        if (d2 < 240 * 240) neighbors.push({ j, d2, dx, dy });
      }
      neighbors.sort((a, b) => a.d2 - b.d2);
      let count = Math.min(neighbors.length, 24);

      for (let k = 0; k < count; k++) {
        let nb = neighbors[k];
        let mx = si.x + nb.dx * 0.5;
        let my = si.y + nb.dy * 0.5;
        let len = Math.sqrt(nb.d2);
        poly = clipPolygonHalfPlane(poly, mx, my, nb.dx / len, nb.dy / len);
        if (poly.length < 3) break;
      }
      cells.push(poly);
    }
    return cells;
  };

  // 1 pass of Lloyd relaxation for natural 5- and 6-sided drought-baked polygons
  let rawCells = computeCells(seeds);
  for (let i = 0; i < seeds.length; i++) {
    if (rawCells[i].length >= 3) {
      let info = polygonCentroidAndArea(rawCells[i]);
      seeds[i].x = lerp(seeds[i].x, info.cx, 0.65);
      seeds[i].y = lerp(seeds[i].y, info.cy, 0.65);
    }
  }
  rawCells = computeCells(seeds);

  // 2. Subdivide ~52% of larger Voronoi cells with 90-degree secondary T-junction fractures
  let allPlates = [];
  for (let i = 0; i < rawCells.length; i++) {
    let poly = rawCells[i];
    if (poly.length < 3) continue;
    let info = polygonCentroidAndArea(poly);
    let sdf = getMaskSDF(info.cx, info.cy);
    if (sdf < -2) continue;

    // Near the thin orbital margin, randomly omit a few tiny cells to create flaky islands
    if (sdf < 18 && random() < map(sdf, -2, 18, 0.72, 0.12)) continue;

    // Decide whether to split this plate with a secondary crack (creates 90-deg T-junctions)
    if (info.area > 1350 && sdf > 22 && random() < 0.55) {
      let ang = noise(info.cx * 0.006, info.cy * 0.006) * Math.PI * 2 + random(-0.4, 0.4);
      let nx = Math.cos(ang), ny = Math.sin(ang);
      let off = random(-6, 6);
      let px = info.cx + nx * off, py = info.cy + ny * off;

      let halfA = clipPolygonHalfPlane(poly, px, py, nx, ny);
      let halfB = clipPolygonHalfPlane(poly, px, py, -nx, -ny);

      if (halfA.length >= 3 && halfB.length >= 3) {
        allPlates.push({ rawPoly: halfA, isSub: true, splitNormal: [nx, ny], splitPt: [px, py] });
        allPlates.push({ rawPoly: halfB, isSub: true, splitNormal: [-nx, -ny], splitPt: [px, py] });
        continue;
      }
    }
    allPlates.push({ rawPoly: poly, isSub: false });
  }

  // 3. Designate 5 small "detached/missing flake windows" on the cheek where bare skin shows
  const missingTargets = [
    [618, 568],
    [475, 625],
    [738, 665],
    [408, 522],
    [555, 768]
  ];
  let missingIndices = new Set();
  for (let target of missingTargets) {
    let bestIdx = -1, bestD = 999999;
    for (let i = 0; i < allPlates.length; i++) {
      let info = polygonCentroidAndArea(allPlates[i].rawPoly);
      let d = Math.hypot(info.cx - target[0], info.cy - target[1]);
      if (d < bestD && info.area < 2600) {
        bestD = d;
        bestIdx = i;
      }
    }
    if (bestIdx >= 0 && bestD < 65) missingIndices.add(bestIdx);
  }

  // 4. Shrink plates inward to open the crack network & crinkle edges organically
  let finalPlates = [];
  let missingWindows = [];

  for (let idx = 0; idx < allPlates.length; idx++) {
    let item = allPlates[idx];
    let poly = item.rawPoly;
    let info = polygonCentroidAndArea(poly);
    let cx = info.cx, cy = info.cy;
    let sdf = getMaskSDF(cx, cy);

    if (missingIndices.has(idx)) {
      missingWindows.push({ poly, cx, cy, area: info.area });
      continue;
    }

    // Tension factor: cracks are widest over the convex apple of the cheek
    let cheekTension = gauss2D(cx, cy, 585, 685, 360, 310, -10);
    let baseInset = map(cheekTension, 0, 1, 1.8, 5.6);

    // Near the thin orbital edge, plates shrink into delicate flakes
    if (sdf < 32) {
      baseInset = map(constrain(sdf, 0, 32), 0, 32, 3.6, 2.4);
    }

    // Inset each edge of the polygon along its inward normal
    let shrunk = poly.map(p => [p[0], p[1]]);
    for (let i = 0; i < poly.length; i++) {
      let p0 = poly[i];
      let p1 = poly[(i + 1) % poly.length];
      let dx = p1[0] - p0[0], dy = p1[1] - p0[1];
      let len = Math.hypot(dx, dy);
      if (len < 1e-3) continue;

      // Outward normal of CCW polygon edge
      let ox = dy / len, oy = -dx / len;
      // Ensure (ox, oy) points outward from centroid
      if ((p0[0] - cx) * ox + (p0[1] - cy) * oy < 0) {
        ox = -ox; oy = -oy;
      }

      // Check if this edge is the secondary T-junction split line (tighter crack)
      let isSecondaryEdge = false;
      if (item.isSub && item.splitNormal) {
        let dotSplit = ox * item.splitNormal[0] + oy * item.splitNormal[1];
        let mx = 0.5 * (p0[0] + p1[0]), my = 0.5 * (p0[1] + p1[1]);
        let distLine = Math.abs((mx - item.splitPt[0]) * item.splitNormal[0] + (my - item.splitPt[1]) * item.splitNormal[1]);
        if (dotSplit > 0.92 && distLine < 3.0) isSecondaryEdge = true;
      }

      let edgeNoise = 0.65 + 0.75 * noise((p0[0] + p1[0]) * 0.012, (p0[1] + p1[1]) * 0.012);
      let inset = isSecondaryEdge ? baseInset * 0.36 * edgeNoise : baseInset * edgeNoise;

      let px = p0[0] - ox * inset;
      let py = p0[1] - oy * inset;
      shrunk = clipPolygonHalfPlane(shrunk, px, py, ox, oy);
      if (shrunk.length < 3) break;
    }

    if (shrunk.length < 3) continue;
    let shrunkInfo = polygonCentroidAndArea(shrunk);
    if (shrunkInfo.area < 45) continue;

    // Subdivide and crinkle each side for brittle mineral fracture geometry
    let crinkled = [];
    let edgesMeta = [];

    for (let i = 0; i < shrunk.length; i++) {
      let a = shrunk[i];
      let b = shrunk[(i + 1) % shrunk.length];
      let dx = b[0] - a[0], dy = b[1] - a[1];
      let len = Math.hypot(dx, dy);
      if (len < 2) continue;

      let ox = dy / len, oy = -dx / len;
      if ((a[0] - shrunkInfo.cx) * ox + (a[1] - shrunkInfo.cy) * oy < 0) {
        ox = -ox; oy = -oy;
      }

      let segPts = [a];
      let steps = len > 24 ? 3 : 2;
      for (let s = 1; s < steps; s++) {
        let t = s / steps;
        let mx = lerp(a[0], b[0], t);
        let my = lerp(a[1], b[1], t);
        let j = (noise(mx * 0.08 + idx * 0.1, my * 0.08) - 0.5) * min(3.2, len * 0.11);
        let pt = [mx + ox * j, my + oy * j];
        segPts.push(pt);
      }
      for (let k = 0; k < segPts.length; k++) crinkled.push(segPts[k]);
      segPts.push(b);

      edgesMeta.push({
        pts: segPts,
        ox, oy,
        len,
        lightDot: ox * LIGHT_2D.x + oy * LIGHT_2D.y
      });
    }

    if (crinkled.length >= 3) {
      finalPlates.push({
        pts: crinkled,
        rawPoly: poly,
        cx: shrunkInfo.cx,
        cy: shrunkInfo.cy,
        area: shrunkInfo.area,
        sdf,
        illum: getIllumination(shrunkInfo.cx, shrunkInfo.cy),
        edges: edgesMeta
      });
    }
  }

  return { plates: finalPlates, missingWindows };
}

