function drawOrganicBlob(cx, cy, rx, ry, rotDeg, ptsCount = 14, wobble = 0.18) {
  let rad = (rotDeg * Math.PI) / 180;
  brush.beginShape(0.45);
  for (let i = 0; i < ptsCount; i++) {
    let a = (i / ptsCount) * Math.PI * 2;
    let n = 1 + (noise(cx * 0.01 + Math.cos(a) * 1.5, cy * 0.01 + Math.sin(a) * 1.5) - 0.5) * wobble * 2;
    let lx = Math.cos(a) * rx * n;
    let ly = Math.sin(a) * ry * n;
    let vx = cx + lx * Math.cos(rad) - ly * Math.sin(rad);
    let vy = cy + lx * Math.sin(rad) + ly * Math.cos(rad);
    brush.vertex(vx, vy);
  }
  brush.endShape(true);
}

