  // Batch 3: Warm umber & sienna shadow glazes (left nasal bridge, tear trough, eye socket crease)
  brush.fill(PALETTE.skinShadow[0], 95);
  brush.fillBleed(0.24, "out");
  brush.fillTexture(0.52, 0.35);
  drawOrganicBlob(165, 580, 185, 420, 12);  // Left raking-light shadow slope
  drawOrganicBlob(270, 485, 140, 190, 25);  // Tear trough shadow
  drawOrganicBlob(480, 252, 240, 52, -4);   // Supratarsal sulcus shadow
  drawOrganicBlob(310, 960, 280, 220, 18);  // Lower-left cheek termination shadow

  brush.fill(PALETTE.skinShadow[1], 85);
  brush.fillBleed(0.2, "out");
  drawOrganicBlob(195, 315, 95, 125, 15);   // Deep medial orbital pocket
  drawOrganicBlob(495, 248, 175, 32, -3);   // Deepest fold of upper lid crease
  drawOrganicBlob(545, 405, 210, 26, -3);   // Shadow along the closed lash line

  // Batch 4: Luminous bone-peach highlights where raking light strikes eyeball & high cheek
  brush.fill(PALETTE.skinGlow[0], 110);
