function renderSkinPoresAndMicroTexture(missingWindows) {
  // 1. Delicate Langer's lines / skin micro-facets around the unmasked orbital zone
  for (let i = 0; i < 420; i++) {
    let x = random(200, 910);
    let y = random(150, 525);
    let sdf = getMaskSDF(x, y);
    if (sdf > 18) continue;

    // Exclude the immediate moist caruncle
    if (Math.hypot(x - 270, y - 354) < 22) continue;

    // Flow angle follows eyelid curves
    let t = constrain((x - 265) / 570, 0, 1);
    let dy = 326 - 354 + (y < 340 ? -110 : 120) * Math.cos(Math.PI * t);
    let ang = (Math.atan2(dy, 570) * 180) / Math.PI + random(-12, 12);

    let len = random(6, 18);
    let col = y < 310 ? "#8f5847" : (random() < 0.5 ? "#b56d5b" : "#9c5c4b");
    brush.set("2H", col, random(0.16, 0.28));
    brush.flowLine(x, y, len, ang);

    // Subtle cross-facet of skin triangles on lower lid & tear trough
    if (y > 365 && random() < 0.45) {
      brush.set("2H", "#c98573", 0.16);
      brush.flowLine(x, y, len * 0.65, ang + random(32, 52));
    }
  }

  // 2. Pore-detailed living skin across the cheek (visible through cracks & flake windows!)
  // Pores are tiny dimples with an umber shadow crescent on the right (away from light)
  // and a dewy bone-rose glint on the left lip (facing the raking light).
  for (let i = 0; i < 2400; i++) {
    let x = random(110, 1080);
    let y = random(380, 1140);

    // Focus pores on the lower orbital border, high cheekbone, and crack zones
    let sdf = getMaskSDF(x, y);
    if (sdf < -65) continue; // Upper eyelid skin is ultra-smooth (almost poreless)

    // Higher density near the malar zone and inside missing-flake windows
    let malarWeight = gauss2D(x, y, 560, 640, 380, 340, -10);
    if (random() > 0.25 + 0.75 * malarWeight && sdf > 35) continue;

    let poreSize = map(malarWeight, 0, 1, 1.4, 3.2) * random(0.75, 1.25);
    let shadowCol = random() < 0.6 ? "#6e3b2c" : "#542a1e";

    // Tiny pore dimple (shadow crescent on upper-right wall)
    brush.set("rotring", shadowCol, random(0.22, 0.38));
    brush.line(x, y, x + poreSize * 0.7, y - poreSize * 0.45);
    brush.line(x + poreSize * 0.7, y - poreSize * 0.45, x + poreSize * 0.4, y + poreSize * 0.55);

    // Dewy specular rim on the lower-left lip catching the raking light
    if (getIllumination(x, y) > 0.35 && random() < 0.55) {
      brush.set("2H", "#f7e8d6", random(0.18, 0.28));
      brush.line(x - poreSize * 0.45, y + poreSize * 0.1, x - poreSize * 0.1, y + poreSize * 0.65);
    }
  }

  // Extra dense, hyper-detailed pores & skin sheen inside the 5 peeled-flake windows
  for (let win of missingWindows) {
    let count = Math.floor(win.area / 22);
    for (let k = 0; k < count; k++) {
      let rx = win.cx + random(-28, 28);
      let ry = win.cy + random(-28, 28);
      let s = random(1.8, 3.4);
      brush.set("rotring", "#5e3022", random(0.26, 0.42));
      brush.line(rx, ry, rx + s * 0.75, ry - s * 0.35);
      brush.set("cpencil", "#a85242", 0.24);
      brush.line(rx - s * 0.3, ry, rx + s * 0.4, ry + s * 0.5);
      if (random() < 0.7) {
        brush.set("rotring", "#fbf0e3", 0.22);
        brush.line(rx - s * 0.55, ry + s * 0.15, rx - s * 0.15, ry + s * 0.65);
      }
    }
  }
}

function renderClosedEyeDetails() {
  // 1. Sculptural shading along the Supratarsal Crease (Upper Eyelid Fold)
  for (let pass = 0; pass < 14; pass++) {
    let offset = map(pass, 0, 13, -14, 10);
    let distFactor = 1 - Math.abs(offset + 1) / 16;
    let pts = [];
    for (let x = 248; x <= 855; x += 22) {
      let y = getUpperCreaseY(x) + offset + (noise(x * 0.03, pass) - 0.5) * 3.5;
      let p = Math.sin(constrain((x - 248) / 607, 0, 1) * Math.PI) * distFactor;
      pts.push([x, y, constrain(p * 1.3, 0.15, 1.2)]);
    }
    let col = offset < -2 ? "#734434" : (offset < 3 ? "#361e15" : "#8f5745");
    let br = Math.abs(offset) < 3 ? "rotring" : "cpencil";
    let w = Math.abs(offset) < 3 ? 0.42 : 0.32;
    brush.set(br, col, w);
    brush.spline(pts, 0.5);
  }

  // Crisp bone-rose skin highlight along the upper lip of the supratarsal fold (lit side)
  let creaseLitPts = [];
  for (let x = 440; x <= 820; x += 24) {
    let y = getUpperCreaseY(x) - 16 + (noise(x * 0.02, 99) - 0.5) * 2;
    creaseLitPts.push([x, y, Math.sin(((x - 440) / 380) * Math.PI)]);
  }
  brush.set("cpencil", "#f4e2ce", 0.45);
  brush.spline(creaseLitPts, 0.5);

  // 2. Lower Eyelid Crease (Infraorbital Fold) & Tear Trough Modeling
  for (let pass = 0; pass < 8; pass++) {
    let offset = map(pass, 0, 7, -6, 8);
    let pts = [];
    for (let x = 280; x <= 815; x += 25) {
      let y = getLowerCreaseY(x) + offset + (noise(x * 0.025, pass + 20) - 0.5) * 3;
      let p = Math.sin(((x - 280) / 535) * Math.PI);
      pts.push([x, y, p * 0.9]);
    }
    let col = Math.abs(offset) < 2.5 ? "#7a4737" : "#a66754";
    brush.set("cpencil", col, 0.28);
    brush.spline(pts, 0.5);
  }

  // 3. Medial Canthus (Tear Duct / Lacrimal Caruncle) at (270, 354)
  brush.noStroke();
  brush.fill("#a8473b", 150);
  brush.fillBleed(0.1, "out");
  drawOrganicBlob(276, 355, 16, 10, 12, 10, 0.1);
  brush.fill("#d47364", 140);
  drawOrganicBlob(281, 354, 10, 6, 8, 10, 0.08);
  brush.noFill();

  // Deep umber shadow pocket framing the caruncle
  brush.set("rotring", "#24140d", 0.45);
  brush.spline([[256, 352, 0.4], [266, 344, 1.0], [286, 345, 0.7], [302, 352, 0.3]], 0.5);
  brush.spline([[258, 354, 0.5], [270, 364, 1.0], [292, 365, 0.6], [308, 362, 0.2]], 0.5);

  // Wet tear-film specular glints on the caruncle and lower lid margin
  brush.set("rotring", "#fffaf2", 0.55);
  brush.line(276, 351, 283, 350);
  brush.line(287, 357, 293, 358);
  brush.set("rotring", "#f8ece0", 0.38);
  brush.line(310, 364, 326, 368);

  // 4. Palpebral Fissure (Closed Eyelid Line) & Lit Waterline Margin
  // Moist grey-rose upper lid margin just above the lash roots
  for (let pass = 0; pass < 4; pass++) {
    let pts = [];
    for (let x = 295; x <= 825; x += 20) {
      let y = getEyelidSlitY(x) - 5.5 + pass * 1.4;
      pts.push([x, y, 0.9]);
    }
    brush.set("cpencil", pass < 2 ? "#e8cab6" : "#b87664", 0.35);
    brush.spline(pts, 0.5);
  }

  // Deep sepia-umber palpebral cleft where upper and lower lids meet
  for (let pass = 0; pass < 6; pass++) {
    let offset = (pass - 2.5) * 1.1;
    let pts = [];
    for (let x = 266; x <= 838; x += 18) {
      let y = getEyelidSlitY(x) + offset + (noise(x * 0.05, pass + 40) - 0.5) * 1.4;
      let p = Math.sin(constrain((x - 266) / 572, 0, 1) * Math.PI);
      pts.push([x, y, 0.4 + p * 0.9]);
    }
    let col = Math.abs(offset) < 1.5 ? "#180d08" : "#3a2117";
    let br = Math.abs(offset) < 1.5 ? "rotring" : "2B";
    brush.set(br, col, Math.abs(offset) < 1.5 ? 0.52 : 0.35);
    brush.spline(pts, 0.5);
  }

  // 5. Lush Sweeping Eyelashes + Raking-Light Cast Shadows on Lower Lid!
  let lashPositions = [];
  for (let x = 304; x <= 822; x += 5.2) {
    lashPositions.push(x + random(-1.8, 1.8));
  }

  // Pass A: Soft warm-umber cast shadows thrown down-left by the raking light
  for (let idx = 0; idx < lashPositions.length; idx++) {
    let x0 = lashPositions[idx];
    let t = (x0 - 304) / 518;
    let y0 = getEyelidSlitY(x0);

    let len = (28 + 62 * Math.pow(Math.sin(Math.PI * Math.pow(t, 0.82)), 0.78)) * random(0.84, 1.14);
    let baseAngle = map(t, 0, 1, 112, 56) + random(-5, 5);
    let rad = (baseAngle * Math.PI) / 180;

    // Shadow is displaced down-left onto the lower eyelid cushion
    let sx0 = x0 - 4, sy0 = y0 + 4;
    let sx1 = sx0 + Math.cos(rad + 0.14) * len * 0.48 - 7;
    let sy1 = sy0 + Math.sin(rad + 0.14) * len * 0.48 + 7;
    let sx2 = sx0 + Math.cos(rad + 0.05) * len * 0.96 - 14;
    let sy2 = sy0 + Math.sin(rad + 0.05) * len * 0.96 + 12;

    brush.set("cpencil", idx % 2 === 0 ? "#7a4a3a" : "#63382a", random(0.22, 0.34));
    brush.spline([[sx0, sy0, 0.7], [sx1, sy1, 0.5], [sx2, sy2, 0.08]], 0.5);
  }

  // Pass B: Fine lower eyelashes emerging beneath the cleft
  for (let x0 = 325; x0 <= 805; x0 += 13) {
    let lx = x0 + random(-3, 3);
    let t = (lx - 325) / 480;
    let ly = getEyelidSlitY(lx) + 3.5;
    let len = (14 + 20 * Math.sin(Math.PI * t)) * random(0.8, 1.2);
    let ang = map(t, 0, 1, 118, 66) + random(-8, 8);
    let rad = (ang * Math.PI) / 180;

    let x1 = lx + Math.cos(rad + 0.1) * len * 0.5;
    let y1 = ly + Math.sin(rad + 0.1) * len * 0.5;
    let x2 = lx + Math.cos(rad - 0.08) * len;
    let y2 = ly + Math.sin(rad - 0.08) * len;

    brush.set("rotring", "#3d2419", random(0.22, 0.32));
    brush.spline([[lx, ly, 0.75], [x1, y1, 0.45], [x2, y2, 0.05]], 0.5);
  }

  // Pass C: Primary & secondary upper eyelashes (with natural tip convergence & lit sheen)
  for (let idx = 0; idx < lashPositions.length; idx++) {
    let x0 = lashPositions[idx];
    let t = (x0 - 304) / 518;
    let y0 = getEyelidSlitY(x0) - random(0, 2.5);

    let len = (30 + 64 * Math.pow(Math.sin(Math.PI * Math.pow(t, 0.82)), 0.75)) * random(0.85, 1.15);
    let baseAngle = map(t, 0, 1, 110, 52) + random(-4, 4);
    let rad = (baseAngle * Math.PI) / 180;

    // Gentle S-curve bowing down then lifting slightly at the tip
    let x1 = x0 + Math.cos(rad + 0.12) * len * 0.52;
    let y1 = y0 + Math.sin(rad + 0.12) * len * 0.52;

    // Subtle tip clumping in groups of 3
    let clumpPull = Math.sin(idx * 2.1) * 5.5;
    let x2 = x0 + Math.cos(rad - 0.06) * len + clumpPull;
    let y2 = y0 + Math.sin(rad - 0.06) * len;

    let col = idx % 3 === 0 ? "#160b07" : (idx % 3 === 1 ? "#28160e" : "#3a2218");
    brush.set("rotring", col, random(0.32, 0.52));
    brush.spline([[x0, y0, 1.1], [x1, y1, 0.65], [x2, y2, 0.06]], 0.5);

    // Raking-light golden-umber sheen on outer-right eyelashes
    if (t > 0.45 && idx % 3 === 0) {
      brush.set("rotring", "#78533d", 0.22);
      brush.spline([[x0 + 1, y0, 0.5], [x1 + 1, y1, 0.35], [x2 + 1, y2, 0.05]], 0.5);
    }
  }

  // 6. Eyebrow Hairs Along the Upper Orbital Arch (partially matted with clay at the top)
  for (let x0 = 250; x0 <= 885; x0 += 6.5) {
    let bx = x0 + random(-2.5, 2.5);
    let t = (bx - 250) / 635;
    let by = getBrowY(bx) + random(-14, 22);
    if (getMaskSDF(bx, by) > 26) continue;

    let len = random(28, 48);
    let ang = map(t, 0, 1, -18, 22) + random(-7, 7);
    let rad = (ang * Math.PI) / 180;
    let x1 = bx + Math.cos(rad) * len * 0.5;
    let y1 = by + Math.sin(rad) * len * 0.5;
    let x2 = bx + Math.cos(rad + 0.12) * len;
    let y2 = by + Math.sin(rad + 0.12) * len;

    let col = random() < 0.65 ? "#2e1c14" : "#4d3326";
    brush.set("rotring", col, random(0.28, 0.44));
    brush.spline([[bx, by, 0.9], [x1, y1, 0.6], [x2, y2, 0.08]], 0.45);
  }
}

// ---------------------------------------------------------------------------
// LAYER 3, 4 & 5: CLAY MASK PLATES, CHARCOAL MASS, CURLED EDGES & SEPIA CRACKS
// ---------------------------------------------------------------------------

function selectClayPlateColor(plate) {
  let il = plate.illum;
  let n = noise(plate.cx * 0.007, plate.cy * 0.007);

  if (il > 0.64) {
    let idx = Math.floor(n * PALETTE.clayLit.length) % PALETTE.clayLit.length;
    return PALETTE.clayLit[idx];
  } else if (il > 0.42) {
    if (n > 0.55) {
      let idx = Math.floor(n * 10) % PALETTE.clayWarmOchre.length;
      return PALETTE.clayWarmOchre[idx];
    }
    let idx = Math.floor(n * PALETTE.clayMid.length) % PALETTE.clayMid.length;
    return PALETTE.clayMid[idx];
  } else {
    let idx = Math.floor(constrain(map(il, 0.08, 0.42, 3.8, 0), 0, 3));
    return PALETTE.clayShadow[idx];
  }
}

function renderClayCraquelure(plates, missingWindows) {
  // -------------------------------------------------------------------------
  // STEP 1: Drop Shadows Cast by Lifted Clay Edges onto the Living Skin Below
  // -------------------------------------------------------------------------
  // Because raking light comes from upper-right (LIGHT_2D = (0.96, -0.28)),
  // every plate shifts its cast shadow down-left (-LIGHT_2D) into the cracks!
  brush.noStroke();
  brush.noHatch();
  brush.noMass();

  for (let plate of plates) {
    // Shadow offset is stronger on the cheek dome where plates are thicker and curled
    let curlHeight = plate.sdf < 28 ? 2.8 : map(plate.illum, 0, 1, 4.2, 6.5);
    let sx = -LIGHT_2D.x * curlHeight;
    let sy = -LIGHT_2D.y * curlHeight;

    for (let edge of plate.edges) {
      // Edges facing down-left (lightDot < 0.25) cast a crisp overhang shadow into the fissure
      if (edge.lightDot < 0.28 && edge.len > 4) {
        let pts = edge.pts;
        for (let k = 0; k < pts.length - 1; k++) {
          let a = pts[k], b = pts[k + 1];
          // Deep umber drop shadow band inside the crack
          brush.set("2B", PALETTE.sepiaInk, map(curlHeight, 2.5, 6.5, 0.55, 1.05));
          brush.line(a[0] + sx * 0.45, a[1] + sy * 0.45, b[0] + sx * 0.45, b[1] + sy * 0.45);

          // Soft warm-sepia penumbra on the glowing skin
          brush.set("cpencil", PALETTE.sepiaWarm, 0.55);
          brush.line(a[0] + sx * 0.85, a[1] + sy * 0.85, b[0] + sx * 0.85, b[1] + sy * 0.85);
        }
      }
    }
  }

  // Extra dramatic overhang cliff shadows inside the 5 missing-flake skin windows
  for (let win of missingWindows) {
    let pts = win.poly;
    for (let i = 0; i < pts.length; i++) {
      let a = pts[i], b = pts[(i + 1) % pts.length];
      let dx = b[0] - a[0], dy = b[1] - a[1];
      let len = Math.hypot(dx, dy);
      if (len < 2) continue;
      // Inward normal into the missing window
      let ix = -dy / len, iy = dx / len;
      if ((win.cx - a[0]) * ix + (win.cy - a[1]) * iy < 0) { ix = -ix; iy = -iy; }

      // If the surrounding clay wall is on the upper-right of the window, it casts a wide shadow
      if (ix * (-LIGHT_2D.x) + iy * (-LIGHT_2D.y) > 0.05) {
        for (let d = 1.5; d <= 7.5; d += 1.8) {
          let col = d < 4.5 ? PALETTE.umberDeep : PALETTE.sepiaWarm;
          brush.set(d < 4.5 ? "rotring" : "cpencil", col, d < 4.5 ? 0.65 : 0.48);
          brush.line(a[0] - LIGHT_2D.x * d, a[1] - LIGHT_2D.y * d, b[0] - LIGHT_2D.x * d, b[1] - LIGHT_2D.y * d);
        }
      }
    }
  }

  // -------------------------------------------------------------------------
  // STEP 2: Opaque Clay Plate Base Washes + Soft Charcoal Mass & Hatching
  // -------------------------------------------------------------------------
  // Sort plates slightly from right to left so raking relief overlaps naturally
  let sortedPlates = plates.slice().sort((a, b) => b.cx - a.cx);

  for (let i = 0; i < sortedPlates.length; i++) {
    let plate = sortedPlates[i];
    let polyObj = new brush.Polygon(plate.pts);
    let baseCol = selectClayPlateColor(plate);

    // 1. Solid opaque clay base wash (masks the underlying skin watercolor except in cracks)
    let washOpacity = plate.sdf < 22 ? map(plate.sdf, 0, 22, 185, 242) : 246;
    polyObj.wash(baseCol, washOpacity);

    // 2. Soft charcoal mass & dry-media hatching to build parched clay texture
    let il = plate.illum;
    let massCol = il > 0.58 ? "#c2b49a" : (il > 0.36 ? "#8e816b" : "#594f40");

    if (plate.area > 750 && i % 2 === 0) {
      // Expressive dry charcoal mass pass
      brush.mass("charcoal", massCol, {
        precision: 0.62,
        strength: 0.22,
        gradient: 0.42,
        outline: false
      });
      polyObj.mass();
      brush.noMass();
    } else if (plate.area > 220) {
      // Fine dry-media charcoal/graphite directional grain across the plate
      let hatchAngle = -18 + (noise(plate.cx * 0.01, plate.cy * 0.01) - 0.5) * 35;
      let hatchSpacing = map(constrain(plate.area, 220, 3200), 220, 3200, 6.5, 10.5);
      brush.hatchStyle("charcoal", massCol, 0.28);
      polyObj.hatch(hatchSpacing, hatchAngle, { rand: 0.14, gradient: 0.48 });
      brush.noHatch();
    }
  }

  // -------------------------------------------------------------------------
  // STEP 3: Concave Saucer Shading, Curled Bone Rim Highlights & Sepia Cracks
  // -------------------------------------------------------------------------
  for (let plate of sortedPlates) {
    let cx = plate.cx, cy = plate.cy;

    for (let edge of plate.edges) {
      let pts = edge.pts;
      let ox = edge.ox, oy = edge.oy;
      let lDot = edge.lightDot;

      // A. Left / Lower-Left Edges (lDot < -0.1):
      // As this edge curls UPWARD toward the viewer, its inner concave slope faces
      // directly into the upper-right raking light -> catches a bright BONE highlight!
      if (lDot < -0.08) {
        let rimStrength = map(constrain(-lDot, 0.08, 1.0), 0.08, 1.0, 0.3, 1.0);
        let boneCol = plate.illum > 0.35 ? PALETTE.boneRim : PALETTE.boneSoft;

        for (let k = 0; k < pts.length - 1; k++) {
          let a = pts[k], b = pts[k + 1];
          // Soft chalky bone bevel just inside the curled rim
          brush.set("charcoal", boneCol, (0.32 + 0.36 * rimStrength) * (plate.illum * 0.5 + 0.5));
          brush.line(a[0] - ox * 2.4, a[1] - oy * 2.4, b[0] - ox * 2.4, b[1] - oy * 2.4);

          // Razor-sharp parched bone crest right on the lifted lip
          if (plate.illum > 0.25) {
            brush.set("rotring", PALETTE.boneRim, 0.28 + 0.28 * rimStrength);
            brush.line(a[0] - ox * 0.9, a[1] - oy * 0.9, b[0] - ox * 0.9, b[1] - oy * 0.9);
          }

          // Crisp sepia ink undercut line at the base of the curled cliff
          brush.set("rotring", PALETTE.sepiaMid, 0.26);
          brush.line(a[0] + ox * 0.4, a[1] + oy * 0.4, b[0] + ox * 0.4, b[1] + oy * 0.4);
        }
      }

      // B. Right / Upper-Right Edges (lDot >= -0.08):
      // As this edge curls upward, its inner saucer dip tilts away from the light (dusty umber shadow),
      // while its outer thickness cliff faces the raking light and overhangs the dark crack crevice!
      else {
        let cliffStrength = map(constrain(lDot, 0, 1), 0, 1, 0.35, 1.0);
        for (let k = 0; k < pts.length - 1; k++) {
          let a = pts[k], b = pts[k + 1];

          // Subtle concave saucer shadow just inside the right curled rim
          brush.set("cpencil", PALETTE.clayShadow[2], 0.32 * cliffStrength);
          brush.line(a[0] - ox * 2.6, a[1] - oy * 2.6, b[0] - ox * 2.6, b[1] - oy * 2.6);

          // Thin lit rim along the top of the right-hand cliff
          if (plate.illum > 0.42 && lDot > 0.25) {
            brush.set("cpencil", PALETTE.boneSoft, 0.25);
            brush.line(a[0] - ox * 0.6, a[1] - oy * 0.6, b[0] - ox * 0.6, b[1] - oy * 0.6);
          }

          // Crisp dark sepia ink drawing the fracture crevice beneath the overhanging edge
          brush.set("rotring", PALETTE.sepiaInk, 0.34 + 0.26 * cliffStrength);
          brush.line(a[0] + ox * 0.6, a[1] + oy * 0.6, b[0] + ox * 0.6, b[1] + oy * 0.6);
        }
      }
    }

    // -----------------------------------------------------------------------
    // STEP 4: Internal Hairline Micro-Cracks & Surface Pitting on Clay Plates
    // -----------------------------------------------------------------------
    if (plate.area > 550 && random() < 0.68) {
      // Pick an edge midpoint and propagate a crisp sepia hairline crack part-way across the plate
      let startEdge = random(plate.edges);
      let pStart = startEdge.pts[Math.floor(startEdge.pts.length / 2)];
      let dirX = cx - pStart[0] + random(-14, 14);
      let dirY = cy - pStart[1] + random(-14, 14);
      let dLen = Math.hypot(dirX, dirY);

      if (dLen > 6) {
        let reach = random(0.45, 0.92);
        let mx = pStart[0] + dirX * reach * 0.5 + random(-3.5, 3.5);
        let my = pStart[1] + dirY * reach * 0.5 + random(-3.5, 3.5);
        let ex = pStart[0] + dirX * reach;
        let ey = pStart[1] + dirY * reach;

        // Hairline sepia ink crack
        brush.set("rotring", PALETTE.sepiaMid, random(0.2, 0.34));
        brush.spline([[pStart[0], pStart[1], 0.85], [mx, my, 0.5], [ex, ey, 0.08]], 0.35);

        // Tiny bone highlight along the down-light lip of the hairline crack
        if (plate.illum > 0.35) {
          brush.set("2H", PALETTE.boneRim, 0.22);
          brush.line(pStart[0] - LIGHT_2D.x * 1.1, pStart[1] - LIGHT_2D.y * 1.1, mx - LIGHT_2D.x * 1.1, my - LIGHT_2D.y * 1.1);
        }
      }
    }

    // Fine chalky mineral pits & dry clay crumbs on the plate surface
    let pitCount = Math.floor(plate.area / 280);
    for (let p = 0; p < pitCount; p++) {
      let px = cx + random(-14, 14);
      let py = cy + random(-14, 14);
      brush.set("2H", random() < 0.5 ? PALETTE.clayShadow[3] : PALETTE.boneSoft, 0.22);
      brush.line(px, py, px + random(-2, 2), py + random(-2, 2));
    }
  }
}

// ---------------------------------------------------------------------------
// LAYER 6: FEATHERED ORBITAL MASK BORDER & CRUMBLING CLAY FLAKES
// ---------------------------------------------------------------------------

function renderFeatheredMaskBorder() {
  // Along getMaskSDF(x, y) in [-16, +26], draw thin chalky dry smears and tiny lifting crumbs
  // where the clay mask was smoothed around the eye socket and has dried into a powdery crust.
  for (let i = 0; i < 620; i++) {
    let angle = random(0, Math.PI * 2);
    let rx = (angle > Math.PI * 0.5 && angle < Math.PI * 1.5) ? 355 : 385;
    let ry = angle > Math.PI ? 185 : 196;

    let baseX = 556 + Math.cos(angle) * rx + random(-24, 24);
    let baseY = 320 + Math.sin(angle) * ry + random(-24, 24);
    if (baseX < 20 || baseX > 1180 || baseY < 20 || baseY > 1180) continue;

    let sdf = getMaskSDF(baseX, baseY);
    if (sdf < -22 || sdf > 30) continue;

    let il = getIllumination(baseX, baseY);
    let tangentDeg = ((angle + Math.PI * 0.5) * 180) / Math.PI + random(-18, 18);

    // Powdery dry clay residue smear
    let smearCol = il > 0.5 ? PALETTE.boneSoft : (il > 0.3 ? PALETTE.clayMid[0] : PALETTE.clayShadow[1]);
    brush.set("charcoal", smearCol, random(0.22, 0.42));
    brush.flowLine(baseX, baseY, random(8, 22), tangentDeg);

    // Tiny curled crust crumb with a micro drop shadow
    if (sdf > -8 && random() < 0.45) {
      let s = random(2.5, 5.5);
      brush.set("rotring", PALETTE.sepiaMid, 0.28);
      brush.line(baseX - LIGHT_2D.x * 1.5, baseY - LIGHT_2D.y * 1.5, baseX + s, baseY + s * 0.5);
      brush.set("rotring", PALETTE.boneRim, 0.32);
      brush.line(baseX, baseY, baseX + s * 0.8, baseY + s * 0.3);
    }
  }
}

// ---------------------------------------------------------------------------
// P5.JS SETUP & DRAW
// ---------------------------------------------------------------------------

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(SEED);
  noiseSeed(SEED);
}

function draw() {
  translate(-width / 2, -height / 2);
  background(PALETTE.ground);

  // Build the drought-baked polygonal craquelure geometry across the 3D face
  const { plates, missingWindows } = buildCraquelurePlates();

  // 1. Luminous watercolor glazes for the living skin (orbital zone + under all cheek cracks)
  renderLivingSkinWatercolors();

  // 2. Hyper-detailed skin pores, Langer's lines, and the closed eye with lash shadows
  renderSkinPoresAndMicroTexture(missingWindows);
  renderClosedEyeDetails();

  // 3. Clay plates with cast shadows, soft charcoal mass, curled bone rims & sepia ink cracks
  renderClayCraquelure(plates, missingWindows);

  // 4. Powdery feathered clay margin & micro-crumbs around the orbital opening
  renderFeatheredMaskBorder();

  noLoop();
}

// Hyperrealistic Raw Squid on a Glossy White Enamel Tray
// Underglaze Cobalt Blue on Porcelain — p5.js + p5.brush

const PALETTE = {
  porcelain: "#f8faff",
  glazeMist: "#e6effb",
  waterPale: "#d2e2f7",
  washLight: "#b3ccee",
  washMid: "#82a8de",
  cobaltSoft: "#527ec4",
  cobaltMid: "#2f59a3",
  cobaltDeep: "#183978",
  navyPool: "#0c214f",
  abyssal: "#051029"
};

// Tray coordinate system (diagonal & cropped)
const TRAY = {
  cx: 635,
  cy: 625,
  ang: 40.5 * (Math.PI / 180),
  bedHalfW: 365,
  bedMinS: -555,
  bedMaxS: 780,
  cornerR: 125,
  bevelW: 68,
  rimW: 32
};

function trayToWorld(s, n) {
  const c = Math.cos(TRAY.ang);
  const sn = Math.sin(TRAY.ang);
  return [
    TRAY.cx + s * c - n * sn,
    TRAY.cy + s * sn + n * c
  ];
}

// Squid spine coordinate system (t = 0 at posterior apex, t = 1 at collar, t = 1.28 at arm crown)
function squidSpine(t) {
  const ax = 198, ay = 178;
  const cx = 628, cy = 586;
  const dx = cx - ax, dy = cy - ay;
  const baseAng = Math.atan2(dy, dx);
  const nx = -Math.sin(baseAng);
  const ny = Math.cos(baseAng);

  const bx = ax + dx * t;
  const by = ay + dy * t;
  const arch = Math.sin(t * Math.PI * 1.12) * 16 - (t > 1 ? Math.pow(t - 1, 1.5) * 18 : 0);
  const localAng = baseAng + Math.cos(t * Math.PI * 1.12) * 0.085;

  return {
    x: bx + nx * arch,
    y: by + ny * arch,
    ang: localAng,
    nx: -Math.sin(localAng),
    ny: Math.cos(localAng),
    tx: Math.cos(localAng),
    ty: Math.sin(localAng)
  };
}

function squidPoint(t, n, offX = 0, offY = 0) {
  const sp = squidSpine(t);
  return [sp.x + sp.nx * n + offX, sp.y + sp.ny * n + offY];
}

// Half-width of the conical muscular mantle (t in [0, 1])
function mantleHalfWidth(t, side = 1) {
  if (t <= 0) return 1.5;
  if (t >= 1) return 72 * (side > 0 ? 1.06 : 0.95);
  const env = Math.pow(t, 0.56) * Math.sin(Math.pow(t, 0.68) * Math.PI * 0.83) * 104;
  const collarFlare = t > 0.84 ? Math.pow((t - 0.84) / 0.16, 1.9) * 15 : 0;
  const asym = side > 0 ? 1.07 : 0.94; // Slightly broader on lower-left tray contact side
  return (env + collarFlare + 2) * asym;
}

// Half-width of the rhomboid fins (t in [0.01, 0.58])
function finSpan(t, side = 1) {
  if (t < 0.01 || t > 0.58) return mantleHalfWidth(t, side);
  const u = (t - 0.01) / 0.57;
  // Heart/rhomboid profile with gentle anterior lobe and undulating margin
  const dome = Math.sin(Math.pow(u, 0.78) * Math.PI);
  const lobe = u > 0.65 ? Math.sin(((u - 0.65) / 0.35) * Math.PI) * 18 : 0;
  const wave = Math.sin(u * Math.PI * 3.0) * 6 * side;
  const span = ( side > 0 ? 182 : 172 ) * Math.pow(dome, 0.85) + lobe + wave;
  return mantleHalfWidth(t, side) * 0.65 + span;
}

// Safe polygon helper for p5.brush
function drawPoly(pts, curvature = 0.5) {
  if (!pts || pts.length < 3) return;
  const clean = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    const prev = clean[clean.length - 1];
    const dx = pts[i][0] - prev[0];
    const dy = pts[i][1] - prev[1];
    if (dx * dx + dy * dy > 5) clean.push(pts[i]);
  }
  if (clean.length < 3) return;
  const first = clean[0];
  const last = clean[clean.length - 1];
  if ((first[0] - last[0]) ** 2 + (first[1] - last[1]) ** 2 <= 5) clean.pop();
  if (clean.length < 3) return;

  brush.beginShape(curvature);
  for (let i = 0; i < clean.length; i++) {
    brush.vertex(clean[i][0], clean[i][1]);
  }
  brush.endShape(true);
}

// Safe spline helper for p5.brush
function drawSpline(pts, curvature = 0.5) {
  if (!pts || pts.length < 2) return;
  const clean = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    const prev = clean[clean.length - 1];
    const dx = pts[i][0] - prev[0];
    const dy = pts[i][1] - prev[1];
    if (dx * dx + dy * dy > 4) clean.push(pts[i]);
  }
  if (clean.length < 2) return;
  if (clean.length === 2) {
    brush.line(clean[0][0], clean[0][1], clean[1][0], clean[1][1]);
  } else {
    brush.spline(clean, curvature);
  }
}

// Evaluate Catmull-Rom spline along control points
function evalCurve(ctrlPts, u) {
  const n = ctrlPts.length - 1;
  const segF = Math.max(0, Math.min(n - 0.0001, u * n));
  const idx = Math.floor(segF);
  const t = segF - idx;

  const p0 = ctrlPts[Math.max(0, idx - 1)];
  const p1 = ctrlPts[idx];
  const p2 = ctrlPts[Math.min(n, idx + 1)];
  const p3 = ctrlPts[Math.min(n, idx + 2)];

  const t2 = t * t;
  const t3 = t2 * t;

  const x = 0.5 * (
    (2 * p1[0]) +
    (-p0[0] + p2[0]) * t +
    (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * t2 +
    (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * t3
  );
  const y = 0.5 * (
    (2 * p1[1]) +
    (-p0[1] + p2[1]) * t +
    (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * t2 +
    (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * t3
  );

  const dx = 0.5 * (
    (-p0[0] + p2[0]) +
    2 * (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * t +
    3 * (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * t2
  );
  const dy = 0.5 * (
    (-p0[1] + p2[1]) +
    2 * (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * t +
    3 * (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * t2
  );
  const len = Math.hypot(dx, dy) || 1;
  return {
    x, y,
    tx: dx / len, ty: dy / len,
    nx: -dy / len, ny: dx / len
  };
}

