function armHalfWidth(arm, u) {
  if (arm.isClub) {
    // Slender stalk that widens into a lance-shaped tentacular club at u in [0.64, 0.94]
    const stalk = arm.baseW * 0.5 * (1 - u * 0.35);
    let club = 0;
    if (u > 0.62 && u < 0.97) {
      const cu = (u - 0.62) / 0.35;
      club = Math.sin(Math.pow(cu, 0.75) * Math.PI) * 13.5;
    }
    const tipTaper = u > 0.92 ? (1 - (u - 0.92) / 0.08) : 1;
    return Math.max(1.2, (stalk + club) * tipTaper);
  } else {
    // Muscular arm tapering smoothly to a fine coiled tip
    return Math.max(1.2, arm.baseW * 0.5 * Math.pow(1 - u, 0.78) + 0.8);
  }
}

function buildArmRibbon(arm, uStart, uEnd, steps, nShiftFn, widthScale = 1.0, offX = 0, offY = 0) {
  const leftPts = [];
  const rightPts = [];
  for (let i = 0; i <= steps; i++) {
    const u = uStart + (uEnd - uStart) * (i / steps);
    const c = evalCurve(arm.pts, u);
    const hw = armHalfWidth(arm, u) * widthScale;
    const shift = nShiftFn ? nShiftFn(u, hw) : 0;
    leftPts.push([c.x + c.nx * (shift + hw) + offX, c.y + c.ny * (shift + hw) + offY]);
    rightPts.push([c.x + c.nx * (shift - hw) + offX, c.y + c.ny * (shift - hw) + offY]);
  }
  return leftPts.concat(rightPts.reverse());
}

// Generate points along the tray's rounded-rectangle boundary at a given radial offset
function buildTrayBoundary(offset, sMin, sMax, sideSign, steps = 40) {
  const pts = [];
  const r = TRAY.cornerR + offset;
  const halfW = TRAY.bedHalfW + offset;
  const sCornerCenter = TRAY.bedMinS + TRAY.cornerR;

  for (let i = 0; i <= steps; i++) {
    const u = i / steps;
    const s = sMin + (sMax - sMin) * u;
    let n;
    if (s < sCornerCenter) {
      const ds = Math.min(r, sCornerCenter - s);
      n = sideSign * ((halfW - r) + Math.sqrt(Math.max(0, r * r - ds * ds)));
    } else {
      n = sideSign * halfW;
    }
    pts.push(trayToWorld(s, n));
  }
  return pts;
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(74);
  noiseSeed(74);

  // Custom brushes for crisp porcelain specular glints and ultra-fine underglaze cobalt ink
  brush.add("underglaze_needle", {
    type: "default",
    weight: 0.32,
    scatter: 0.04,
    sharpness: 0.88,
    grain: 5,
    opacity: 210,
    spacing: 0.12,
    pressure: [0.5, 1.15, 0.4],
    noise: 0.25
  });

  brush.add("wet_glint", {
    type: "marker",
    weight: 1.6,
    scatter: 0.02,
    opacity: 245,
    spacing: 0.1,
    pressure: [0.2, 1.0, 0.2],
    markerTip: false,
    noise: 0.1
  });

  background(PALETTE.porcelain);
}

function draw() {
  translate(-width / 2, -height / 2);

  const arms = getTentaclesData();

  // =========================================================================
  // 1. GLOSSY WHITE ENAMEL TRAY, MOULDED BEVEL & UNDERGLAZE COBALT RIM
  // =========================================================================
  drawEnamelTray();

  // =========================================================================
  // 2. FAINT POOLED-WATER REFLECTION & TRAY LIQUID PUDDLES
  // =========================================================================
  drawPooledWaterAndReflections(arms);

  // =========================================================================
  // 3. GRADED COBALT WASHES (FINS, TRANSLUCENT MANTLE, HEAD, TENTACLES)
  // =========================================================================
  drawGradedCobaltWashes(arms);

  // =========================================================================
  // 4. SQUID EYES & DEEP COLLAR CAVITY
  // =========================================================================
  drawHeadAndEyes();

  // =========================================================================
  // 5. FINE BLUE PEN LINES (FINS, MANTLE RINGS, TENTACLES & SUCKERS)
  // =========================================================================
  drawFinePenDetails(arms);

  // =========================================================================
  // 6. CHROMATOPHORE SPECKLES (GRADED COBALT STIPPLING)
  // =========================================================================
  drawChromatophores(arms);

  // =========================================================================
  // 7. WET GLASSY SHEEN & UNTOUCHED PORCELAIN HIGHLIGHTS
  // =========================================================================
  drawWetGlassySheen(arms);

  noLoop();
}

// ---------------------------------------------------------------------------
// LAYER 1: ENAMEL TRAY
// ---------------------------------------------------------------------------
function drawEnamelTray() {
  brush.noStroke();
  brush.noHatch();

  const offBevel = TRAY.bevelW;
  const offRim = TRAY.bevelW + TRAY.rimW;
  const offTable = offRim + 220;

  // 1A. Cool twilight shadow outside the tray on the tabletop (cropped corners)
  brush.fill(PALETTE.waterPale, 85);
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.35, 0.2);

  // Upper-right & top-left exterior table shadow
  const extUpperInner = buildTrayBoundary(offRim, -555 - offRim, 720, -1, 45);
  const extUpperOuter = buildTrayBoundary(offTable, -555 - offTable, 720, -1, 45).reverse();
  drawPoly(extUpperInner.concat(extUpperOuter), 0.3);

  // Lower-left exterior table shadow
  const extLowerInner = buildTrayBoundary(offRim, -555 - offRim, 720, 1, 45);
  const extLowerOuter = buildTrayBoundary(offTable, -555 - offTable, 720, 1, 45).reverse();
  drawPoly(extLowerInner.concat(extLowerOuter), 0.3);

  // Deeper shadow directly under the rolled tray rim
  brush.fill(PALETTE.washMid, 95);
  brush.fillBleed(0.22, "out");
  const rimShadowU1 = buildTrayBoundary(offRim, -555 - offRim, 700, -1, 40);
  const rimShadowU2 = buildTrayBoundary(offRim + 26, -555 - offRim - 26, 700, -1, 40).reverse();
  drawPoly(rimShadowU1.concat(rimShadowU2), 0.3);

  const rimShadowL1 = buildTrayBoundary(offRim, -555 - offRim, 700, 1, 40);
  const rimShadowL2 = buildTrayBoundary(offRim + 36, -555 - offRim - 36, 700, 1, 40).reverse();
  drawPoly(rimShadowL1.concat(rimShadowL2), 0.3);

  // 1B. Sloped Inner Bevel of the Enamel Tray (with untouched white reflection gaps!)
  brush.fill(PALETTE.waterPale, 95);
  brush.fillBleed(0.18, "out");
  brush.fillTexture(0.25, 0.15);

  // Top-left curved corner bevel (split to leave a crisp white corner reflection)
  const bevTL1 = buildTrayBoundary(2, -552, -370, -1, 24);
  const bevTL2 = buildTrayBoundary(offBevel - 4, -552 - offBevel + 4, -370, -1, 24).reverse();
  drawPoly(bevTL1.concat(bevTL2), 0.4);

  // Upper-right long bevel shading (from s = -260 to 680, leaving -370..-260 pure white)
  const bevUR1 = buildTrayBoundary(4, -260, 680, -1, 32);
  const bevUR2 = buildTrayBoundary(offBevel - 4, -260, 680, -1, 32).reverse();
  drawPoly(bevUR1.concat(bevUR2), 0.4);

  // Lower-left bevel shading (split into two segments so glossy tray light cuts across at s = -80..40)
  const bevLLa1 = buildTrayBoundary(4, -530, -90, 1, 26);
  const bevLLa2 = buildTrayBoundary(offBevel - 4, -530 - offBevel + 10, -90, 1, 26).reverse();
  drawPoly(bevLLa1.concat(bevLLa2), 0.4);

  const bevLLb1 = buildTrayBoundary(4, 45, 720, 1, 30);
  const bevLLb2 = buildTrayBoundary(offBevel - 4, 45, 720, 1, 30).reverse();
  drawPoly(bevLLb1.concat(bevLLb2), 0.4);

  // Deeper cobalt glaze along the upper-left curved bevel shadow
  brush.fill(PALETTE.washMid, 80);
  brush.fillBleed(0.15, "out");
  const bevDeep1 = buildTrayBoundary(18, -545, -120, 1, 28);
  const bevDeep2 = buildTrayBoundary(offBevel - 6, -545 - offBevel + 16, -120, 1, 28).reverse();
  drawPoly(bevDeep1.concat(bevDeep2), 0.4);

  // 1C. Underglaze Cobalt Rolled Rim of the Enamel Tray
  // Base cobalt wash of the rim
  brush.fill(PALETTE.cobaltMid, 155);
  brush.fillBleed(0.12, "out");
  brush.fillTexture(0.45, 0.35);

  const rimUpper1 = buildTrayBoundary(offBevel, -555 - offBevel, 720, -1, 48);
  const rimUpper2 = buildTrayBoundary(offRim, -555 - offRim, 720, -1, 48).reverse();
  drawPoly(rimUpper1.concat(rimUpper2), 0.35);

  const rimLower1 = buildTrayBoundary(offBevel, -555 - offBevel, 720, 1, 48);
  const rimLower2 = buildTrayBoundary(offRim, -555 - offRim, 720, 1, 48).reverse();
  drawPoly(rimLower1.concat(rimLower2), 0.35);

  // Pooled navy edge along the inner & outer lip of the rolled rim (leaving a highlight band in the middle)
  brush.fill(PALETTE.navyPool, 185);
  brush.fillBleed(0.08, "in");
  const rimLipU1 = buildTrayBoundary(offBevel, -555 - offBevel, 720, -1, 45);
  const rimLipU2 = buildTrayBoundary(offBevel + 11, -555 - offBevel - 11, 720, -1, 45).reverse();
  drawPoly(rimLipU1.concat(rimLipU2), 0.35);

  const rimLipL1 = buildTrayBoundary(offBevel, -555 - offBevel, 720, 1, 45);
  const rimLipL2 = buildTrayBoundary(offBevel + 12, -555 - offBevel - 12, 720, 1, 45).reverse();
  drawPoly(rimLipL1.concat(rimLipL2), 0.35);

  const rimOuterL1 = buildTrayBoundary(offRim - 9, -555 - offRim + 9, 720, 1, 45);
  const rimOuterL2 = buildTrayBoundary(offRim, -555 - offRim, 720, 1, 45).reverse();
  drawPoly(rimOuterL1.concat(rimOuterL2), 0.35);

  // Fine moulded tray crease lines
  brush.noFill();
  brush.set("rotring", PALETTE.cobaltSoft, 0.45);
  drawSpline(buildTrayBoundary(0, -550, -380, -1, 20), 0.4);
  drawSpline(buildTrayBoundary(0, -240, 680, -1, 28), 0.4);
  drawSpline(buildTrayBoundary(0, -540, -100, 1, 24), 0.4);
  drawSpline(buildTrayBoundary(0, 55, 700, 1, 28), 0.4);

  brush.set("rotring", PALETTE.navyPool, 0.7);
  drawSpline(buildTrayBoundary(offBevel, -555 - offBevel, 720, -1, 45), 0.4);
  drawSpline(buildTrayBoundary(offBevel, -555 - offBevel, 720, 1, 45), 0.4);
  drawSpline(buildTrayBoundary(offRim, -555 - offRim, 720, -1, 45), 0.4);
  drawSpline(buildTrayBoundary(offRim, -555 - offRim, 720, 1, 45), 0.4);
}

// ---------------------------------------------------------------------------
// LAYER 2: POOLED WATER & FAINT REFLECTION ON GLOSSY TRAY
// ---------------------------------------------------------------------------
function drawPooledWaterAndReflections(arms) {
  brush.noStroke();
  brush.noHatch();

  // 2A. Faint pooled-water reflection shifted down-left (+22, +32) on the glossy enamel bed
  const refOffX = 20, refOffY = 32;
  brush.fill(PALETTE.waterPale, 78);
  brush.fillBleed(0.38, "out");
  brush.fillTexture(0.28, 0.15);

  // Reflected mantle & lower-left fin silhouette
  const refMantlePts = [];
  for (let i = 0; i <= 26; i++) {
    const t = i / 26;
    const w = t < 0.56 ? finSpan(t, 1) * 0.92 : mantleHalfWidth(t, 1) * 1.15;
    refMantlePts.push(squidPoint(t, w, refOffX, refOffY));
  }
  for (let i = 26; i >= 0; i--) {
    const t = i / 26;
    refMantlePts.push(squidPoint(t, 0, refOffX, refOffY));
  }
  drawPoly(refMantlePts, 0.5);

  // Reflected upper-right fin puddle
  const refFinUR = [];
  for (let i = 1; i <= 18; i++) {
    const t = 0.02 + (i / 18) * 0.54;
    refFinUR.push(squidPoint(t, -finSpan(t, -1) * 0.9, refOffX * 0.7, refOffY * 0.7));
  }
  for (let i = 18; i >= 1; i--) {
    const t = 0.02 + (i / 18) * 0.54;
    refFinUR.push(squidPoint(t, -mantleHalfWidth(t, -1) * 0.5, refOffX * 0.7, refOffY * 0.7));
  }
  drawPoly(refFinUR, 0.5);

  // Reflected arms on the wet tray surface
  for (let a = 0; a < arms.length; a++) {
    const poly = buildArmRibbon(
      arms[a], 0.05, 0.96, 20,
      () => 0,
      1.35,
      refOffX * 0.85, refOffY * 0.95
    );
    drawPoly(poly, 0.5);
  }

  // Slightly deeper reflection pool beneath the head, eye, and collar
  brush.fill(PALETTE.washLight, 88);
  brush.fillBleed(0.32, "out");
  const refHeadPts = [];
  for (let i = 0; i <= 16; i++) {
    const ang = (i / 16) * Math.PI * 2;
    const rx = 88 + Math.sin(ang * 3) * 14;
    const ry = 62 + Math.cos(ang * 2) * 12;
    const c = squidPoint(1.08, 42, refOffX, refOffY);
    refHeadPts.push([c[0] + Math.cos(ang) * rx, c[1] + Math.sin(ang) * ry]);
  }
  drawPoly(refHeadPts, 0.6);

  // 2B. Translucent pooled water puddles with crisp capillary meniscus borders
  const puddles = [
    // Puddle around lower-left fin and mid-mantle
    (function () {
      const pts = [];
      for (let i = 0; i <= 24; i++) {
        const t = 0.06 + (i / 24) * 0.86;
        const base = t < 0.56 ? finSpan(t, 1) : mantleHalfWidth(t, 1);
        const swell = 26 + Math.sin(i * 0.7) * 14 + (t > 0.52 && t < 0.78 ? 24 : 0);
        pts.push(squidPoint(t, base + swell));
      }
      for (let i = 24; i >= 0; i--) {
        const t = 0.06 + (i / 24) * 0.86;
        pts.push(squidPoint(t, mantleHalfWidth(t, 1) * 0.5));
      }
      return pts;
    })(),
    // Puddle around upper-right fin and anterior mantle edge
    (function () {
      const pts = [];
      for (let i = 0; i <= 20; i++) {
        const t = 0.08 + (i / 20) * 0.76;
        const base = t < 0.56 ? finSpan(t, -1) : mantleHalfWidth(t, -1);
        const swell = 18 + Math.cos(i * 0.85) * 10;
        pts.push(squidPoint(t, -(base + swell)));
      }
      for (let i = 20; i >= 0; i--) {
        const t = 0.08 + (i / 20) * 0.76;
        pts.push(squidPoint(t, -mantleHalfWidth(t, -1) * 0.5));
      }
      return pts;
    })(),
    // Puddle beneath the curled left tentacle club
    (function () {
      const pts = [];
      const cx = 425, cy = 935;
      for (let i = 0; i < 20; i++) {
        const a = (i / 20) * Math.PI * 2;
        const r = 78 + Math.sin(a * 3 + 0.5) * 18 + Math.cos(a * 2) * 14;
        pts.push([cx + Math.cos(a) * r * 1.15, cy + Math.sin(a) * r * 0.85]);
      }
      return pts;
    })(),
    // Puddle beneath the right tentacle loop
    (function () {
      const pts = [];
      const cx = 965, cy = 925;
      for (let i = 0; i < 20; i++) {
        const a = (i / 20) * Math.PI * 2;
        const r = 82 + Math.cos(a * 3 - 0.4) * 20 + Math.sin(a * 2) * 12;
        pts.push([cx + Math.cos(a) * r * 0.95, cy + Math.sin(a) * r * 1.15]);
      }
      return pts;
    })()
  ];

  brush.fill(PALETTE.glazeMist, 90);
  brush.fillBleed(0.14, "in");
  brush.fillTexture(0.22, 0.45);
  for (let p of puddles) {
    drawPoly(p, 0.55);
  }

  // Capillary water-edge meniscus lines (broken for realism)
  brush.noFill();
  brush.set("underglaze_needle", PALETTE.washMid, 0.65);
  for (let p of puddles) {
    const halfLen = Math.floor(p.length * 0.52);
    for (let s = 0; s < halfLen - 3; s += 5) {
      drawSpline(p.slice(s, s + 4), 0.5);
    }
  }
}

// ---------------------------------------------------------------------------
// LAYER 3: GRADED COBALT WASHES (SQUID BODY, FINS & TENTACLES)
// ---------------------------------------------------------------------------
function drawGradedCobaltWashes(arms) {
  brush.noStroke();
  brush.noHatch();

  // =========================================================================
  // BATCH 1: PALE WASH-BLUE (#b3ccee) — Translucent base of fins, mantle & arms
  // Note: We carefully reserve an UNTOUCHED PORCELAIN-WHITE strip along the
  // dorsal illumination ridge of the mantle (n in [-30, -8])!
  // =========================================================================
  brush.fill(PALETTE.washLight, 110);
  brush.fillBleed(0.22, "out");
  brush.fillTexture(0.38, 0.28);

  // 1. Lower-left rhomboid fin base wash
  const finLowerPts = [];
  for (let i = 0; i <= 24; i++) {
    const t = 0.01 + (i / 24) * 0.57;
    finLowerPts.push(squidPoint(t, finSpan(t, 1)));
  }
  for (let i = 24; i >= 0; i--) {
    const t = 0.01 + (i / 24) * 0.57;
    finLowerPts.push(squidPoint(t, mantleHalfWidth(t, 1) * 0.72));
  }
  drawPoly(finLowerPts, 0.5);

  // 2. Upper-right rhomboid fin base wash (leaving anterior edge highlight)
  const finUpperPts = [];
  for (let i = 0; i <= 22; i++) {
    const t = 0.01 + (i / 22) * 0.53;
    finUpperPts.push(squidPoint(t, -finSpan(t, -1) * 0.96));
  }
  for (let i = 22; i >= 0; i--) {
    const t = 0.01 + (i / 22) * 0.53;
    finUpperPts.push(squidPoint(t, -mantleHalfWidth(t, -1) * 0.75));
  }
  drawPoly(finUpperPts, 0.5);

  // 3. Mantle main shaded cylinder (from n = -8 across spine to lower edge n = +mantleHalfWidth)
  const mantleMainPts = [];
  for (let i = 0; i <= 28; i++) {
    const t = i / 28;
    mantleMainPts.push(squidPoint(t, mantleHalfWidth(t, 1)));
  }
  for (let i = 28; i >= 0; i--) {
    const t = i / 28;
    // Border of the untouched white dorsal highlight!
    const hiBorder = -mantleHalfWidth(t, -1) * 0.14 + Math.sin(t * 14) * 2.5;
    mantleMainPts.push(squidPoint(t, hiBorder));
  }
  drawPoly(mantleMainPts, 0.5);

  // 4. Mantle upper-right rim strip (between dorsal highlight n = -0.46*W and outer contour n = -W)
  const mantleUpperRimPts = [];
  for (let i = 1; i <= 26; i++) {
    const t = i / 26;
    mantleUpperRimPts.push(squidPoint(t, -mantleHalfWidth(t, -1)));
  }
  for (let i = 26; i >= 1; i--) {
    const t = i / 26;
    const hiUpper = -mantleHalfWidth(t, -1) * 0.44 + Math.cos(t * 12) * 2.0;
    mantleUpperRimPts.push(squidPoint(t, hiUpper));
  }
  drawPoly(mantleUpperRimPts, 0.5);

  // 5. Head & Siphon base wash (leaving a glossy white highlight on the upper-right head dome)
  const headBasePts = [];
  for (let i = 0; i <= 16; i++) {
    const t = 0.98 + (i / 16) * 0.30;
    const wL = 62 * (1 - (t - 0.98) * 0.6) + (t > 1.08 && t < 1.22 ? 14 : 0);
    headBasePts.push(squidPoint(t, wL));
  }
  for (let i = 16; i >= 0; i--) {
    const t = 0.98 + (i / 16) * 0.30;
    const wU = -12 + Math.sin((t - 0.98) * 10) * 5;
    headBasePts.push(squidPoint(t, wU));
  }
  drawPoly(headBasePts, 0.5);

  // Siphon (funnel) peeking out beneath lower-left collar at t = 0.96..1.10
  const siphonPts = [
    squidPoint(0.95, 62),
    squidPoint(1.01, 94),
    squidPoint(1.08, 92),
    squidPoint(1.11, 64),
    squidPoint(1.02, 52)
  ];
  drawPoly(siphonPts, 0.45);

  // 6. All 8 arms & 2 tentacles pale wash-blue base (offset slightly so upper edge stays white)
  for (let a = 0; a < arms.length; a++) {
    const poly = buildArmRibbon(
      arms[a], 0.0, 0.99, 28,
      (u, hw) => hw * 0.18,
      0.92
    );
    drawPoly(poly, 0.5);
  }

  // =========================================================================
  // BATCH 2: MID COBALT WASH (#82a8de & #527ec4) — Internal translucency,
  // fin margin pooling, mantle core form, and tentacle shading
  // =========================================================================
  brush.fill(PALETTE.washMid, 125);
  brush.fillBleed(0.20, "out");
  brush.fillTexture(0.42, 0.32);

  // Internal visceral mass & buried gladius (translucent glow inside the mantle)
  const visceralPts = [];
  for (let i = 2; i <= 22; i++) {
    const t = (i / 24) * 0.92;
    visceralPts.push(squidPoint(t, mantleHalfWidth(t, 1) * 0.54));
  }
  for (let i = 22; i >= 2; i--) {
    const t = (i / 24) * 0.92;
    visceralPts.push(squidPoint(t, -mantleHalfWidth(t, -1) * 0.06));
  }
  drawPoly(visceralPts, 0.55);

  // Outer margin washes on both fins
  const finEdgeL = [];
  for (let i = 1; i <= 22; i++) {
    const t = 0.02 + (i / 22) * 0.54;
    finEdgeL.push(squidPoint(t, finSpan(t, 1)));
  }
  for (let i = 22; i >= 1; i--) {
    const t = 0.02 + (i / 22) * 0.54;
    finEdgeL.push(squidPoint(t, finSpan(t, 1) * 0.62));
  }
  drawPoly(finEdgeL, 0.5);

  const finEdgeU = [];
  for (let i = 1; i <= 20; i++) {
    const t = 0.02 + (i / 20) * 0.51;
    finEdgeU.push(squidPoint(t, -finSpan(t, -1)));
  }
  for (let i = 20; i >= 1; i--) {
    const t = 0.02 + (i / 20) * 0.51;
    finEdgeU.push(squidPoint(t, -finSpan(t, -1) * 0.66));
  }
  drawPoly(finEdgeU, 0.5);

  // Richer cobalt wash (#527ec4) for core cylinder shadow & tentacle volume
  brush.fill(PALETTE.cobaltSoft, 125);
  brush.fillBleed(0.16, "out");
  brush.fillTexture(0.45, 0.38);

  // Mantle core cylinder shadow (n from +0.25*W to +0.86*W, leaving reflected tray light at +0.86..1.0*W)
  const mantleCorePts = [];
  for (let i = 1; i <= 26; i++) {
    const t = i / 26;
    mantleCorePts.push(squidPoint(t, mantleHalfWidth(t, 1) * 0.88));
  }
  for (let i = 26; i >= 1; i--) {
    const t = i / 26;
    mantleCorePts.push(squidPoint(t, mantleHalfWidth(t, 1) * 0.26));
  }
  drawPoly(mantleCorePts, 0.5);

  // Fin-to-mantle muscular junction shadows
  const finJuncL = [];
  for (let i = 1; i <= 20; i++) {
    const t = 0.02 + (i / 20) * 0.54;
    finJuncL.push(squidPoint(t, mantleHalfWidth(t, 1) * 1.16));
  }
  for (let i = 20; i >= 1; i--) {
    const t = 0.02 + (i / 20) * 0.54;
    finJuncL.push(squidPoint(t, mantleHalfWidth(t, 1) * 0.78));
  }
  drawPoly(finJuncL, 0.5);

  const finJuncU = [];
  for (let i = 1; i <= 20; i++) {
    const t = 0.02 + (i / 20) * 0.52;
    finJuncU.push(squidPoint(t, -mantleHalfWidth(t, -1) * 1.12));
  }
  for (let i = 20; i >= 1; i--) {
    const t = 0.02 + (i / 20) * 0.52;
    finJuncU.push(squidPoint(t, -mantleHalfWidth(t, -1) * 0.78));
  }
  drawPoly(finJuncU, 0.5);

  // Head core shadow & arm shaded undersides
  const headCorePts = [];
  for (let i = 0; i <= 14; i++) {
    const t = 1.0 + (i / 14) * 0.27;
    headCorePts.push(squidPoint(t, 52 * (1 - (t - 1.0) * 0.4)));
  }
  for (let i = 14; i >= 0; i--) {
    const t = 1.0 + (i / 14) * 0.27;
    headCorePts.push(squidPoint(t, 10));
  }
  drawPoly(headCorePts, 0.5);

  for (let a = 0; a < arms.length; a++) {
    const poly = buildArmRibbon(
      arms[a], 0.02, 0.99, 26,
      (u, hw) => hw * 0.42,
      0.56
    );
    drawPoly(poly, 0.5);
  }

  // =========================================================================
  // BATCH 3: DEEP UNDERGLAZE COBALT (#2f59a3 & #183978) — Pooled pigment at
  // edges of fins, mantle crease, collar lip, and tentacular clubs
  // =========================================================================
  brush.fill(PALETTE.cobaltMid, 145);
  brush.fillBleed(0.12, "in");
  brush.fillTexture(0.52, 0.45);

  // Pooled cobalt along the outer rim of the lower-left fin
  const finPoolL = [];
  for (let i = 1; i <= 22; i++) {
    const t = 0.02 + (i / 22) * 0.53;
    finPoolL.push(squidPoint(t, finSpan(t, 1)));
  }
  for (let i = 22; i >= 1; i--) {
    const t = 0.02 + (i / 22) * 0.53;
    finPoolL.push(squidPoint(t, finSpan(t, 1) - 16 * Math.sin((i / 22) * Math.PI)));
  }
  drawPoly(finPoolL, 0.5);

  // Pooled cobalt along the posterior rim of the upper-right fin
  const finPoolU = [];
  for (let i = 1; i <= 18; i++) {
    const t = 0.01 + (i / 18) * 0.42;
    finPoolU.push(squidPoint(t, -finSpan(t, -1)));
  }
  for (let i = 18; i >= 1; i--) {
    const t = 0.01 + (i / 18) * 0.42;
    finPoolU.push(squidPoint(t, -(finSpan(t, -1) - 13 * Math.sin((i / 18) * Math.PI))));
  }
  drawPoly(finPoolU, 0.5);

  // Deep shadow along the lower mantle contour and collar flare
  const mantleDeepEdge = [];
  for (let i = 2; i <= 26; i++) {
    const t = i / 26;
    mantleDeepEdge.push(squidPoint(t, mantleHalfWidth(t, 1) * 1.03));
  }
  for (let i = 26; i >= 2; i--) {
    const t = i / 26;
    mantleDeepEdge.push(squidPoint(t, mantleHalfWidth(t, 1) * 0.72));
  }
  drawPoly(mantleDeepEdge, 0.5);

  // Deep cobalt pooling along the undersides and curled tips of all tentacles
  brush.fill(PALETTE.cobaltDeep, 160);
  brush.fillBleed(0.10, "in");
  for (let a = 0; a < arms.length; a++) {
    const poly = buildArmRibbon(
      arms[a], 0.08, 0.99, 24,
      (u, hw) => hw * 0.68,
      0.36
    );
    drawPoly(poly, 0.5);

    // Extra dense pooling on the broadened tentacular clubs
    if (arms[a].isClub) {
      const clubPool = buildArmRibbon(
        arms[a], 0.64, 0.96, 16,
        (u, hw) => hw * 0.25 * arms[a].suckerSide,
        0.52
      );
      drawPoly(clubPool, 0.5);
    }
  }

  // =========================================================================
  // BATCH 4: DENSE POOLED NAVY (#0c214f) — Contact shadows & pooled edges
  // =========================================================================
  brush.fill(PALETTE.navyPool, 175);
  brush.fillBleed(0.09, "out");
  brush.fillTexture(0.55, 0.5);

  // Contact shadow under posterior apex and lower-left fin edge
  const navyFinEdge = [];
  for (let i = 0; i <= 18; i++) {
    const t = (i / 18) * 0.48;
    navyFinEdge.push(squidPoint(t, finSpan(t, 1) + 4));
  }
  for (let i = 18; i >= 0; i--) {
    const t = (i / 18) * 0.48;
    navyFinEdge.push(squidPoint(t, finSpan(t, 1) - 6));
  }
  drawPoly(navyFinEdge, 0.5);

  // Contact shadow directly under the belly of the mantle (t = 0.50..0.98)
  const navyBelly = [];
  for (let i = 0; i <= 18; i++) {
    const t = 0.50 + (i / 18) * 0.48;
    navyBelly.push(squidPoint(t, mantleHalfWidth(t, 1) + 6));
  }
  for (let i = 18; i >= 0; i--) {
    const t = 0.50 + (i / 18) * 0.48;
    navyBelly.push(squidPoint(t, mantleHalfWidth(t, 1) - 8));
  }
  drawPoly(navyBelly, 0.5);
}

// ---------------------------------------------------------------------------
// LAYER 4: HEAD, COLLAR CAVITY & GELATINOUS SQUID EYES
// ---------------------------------------------------------------------------
function drawHeadAndEyes() {
  brush.noStroke();
  brush.noHatch();

  // 4A. Deep pooled navy inside the mantle collar opening (t = 0.96..1.04)
  brush.fill(PALETTE.navyPool, 210);
  brush.fillBleed(0.08, "in");
  const collarCavity = [];
  for (let i = 0; i <= 14; i++) {
    const u = -1 + (i / 14) * 2;
    const n = u * 70;
    const t = 0.99 + (1 - u * u) * 0.04;
    collarCavity.push(squidPoint(t, n));
  }
  for (let i = 14; i >= 0; i--) {
    const u = -1 + (i / 14) * 2;
    const n = u * 66;
    const t = 0.965 + (1 - u * u) * 0.02;
    collarCavity.push(squidPoint(t, n));
  }
  drawPoly(collarCavity, 0.45);

  // 4B. Prominent Lower-Left Squid Eye (at t = 1.13, n = +38)
  const eyeL = squidPoint(1.13, 38);

  // Translucent orbital bulge shadow around the eye
  brush.fill(PALETTE.cobaltSoft, 120);
  brush.fillBleed(0.15, "out");
  const orbitPts = [];
  for (let i = 0; i < 16; i++) {
    const a = (i / 16) * Math.PI * 2;
    orbitPts.push([eyeL[0] + Math.cos(a) * 28, eyeL[1] + Math.sin(a) * 23]);
  }
  drawPoly(orbitPts, 0.6);

  // Metallic dark cobalt iris ring
  brush.fill(PALETTE.cobaltDeep, 195);
  brush.fillBleed(0.06, "in");
  const irisPts = [];
  for (let i = 0; i < 16; i++) {
    const a = (i / 16) * Math.PI * 2;
    irisPts.push([eyeL[0] + Math.cos(a) * 19, eyeL[1] + Math.sin(a) * 17]);
  }
  drawPoly(irisPts, 0.6);

  // Abyssal navy-black pupil (with a wedge reserved on upper-right for specular highlight)
  brush.fill(PALETTE.abyssal, 235);
  brush.fillBleed(0.03, "in");
  const pupilPts = [];
  for (let i = 0; i < 16; i++) {
    const a = (i / 16) * Math.PI * 2;
    const r = (a > -0.9 && a < 0.3) ? 6 : 12.5;
    pupilPts.push([eyeL[0] + Math.cos(a) * r, eyeL[1] + Math.sin(a) * r]);
  }
  drawPoly(pupilPts, 0.55);

  // 4C. Upper-Right Eye in Three-Quarter Profile (at t = 1.11, n = -44)
  const eyeU = squidPoint(1.11, -44);
  brush.fill(PALETTE.cobaltDeep, 175);
  const eyeUPts = [];
  for (let i = 0; i < 14; i++) {
    const a = (i / 14) * Math.PI * 2;
    eyeUPts.push([eyeU[0] + Math.cos(a) * 15, eyeU[1] + Math.sin(a) * 11]);
  }
  drawPoly(eyeUPts, 0.55);

  brush.fill(PALETTE.abyssal, 225);
  const pupilUPts = [];
  for (let i = 0; i < 12; i++) {
    const a = (i / 12) * Math.PI * 2;
    pupilUPts.push([eyeU[0] - 2 + Math.cos(a) * 8.5, eyeU[1] - 1 + Math.sin(a) * 6.5]);
  }
  drawPoly(pupilUPts, 0.55);
}

// ---------------------------------------------------------------------------
// LAYER 5: FINE BLUE PEN LINES (FINS, MANTLE, TENTACLES & SUCKERS)
// ---------------------------------------------------------------------------
function drawFinePenDetails(arms) {
  brush.noFill();
  brush.noHatch();

  // 5A. Delicate Radial Muscle Striations in Both Rhomboid Fins
  const numFinRays = 58;
  for (let i = 1; i < numFinRays; i++) {
    const u = i / numFinRays;
    const t = 0.02 + u * 0.54;

    // Lower-left fin ray
    const wBaseL = mantleHalfWidth(t, 1) * 0.74;
    const wTipL = finSpan(t, 1) * 0.98;
    if (wTipL - wBaseL > 8) {
      const p0 = squidPoint(t, wBaseL);
      const p1 = squidPoint(t + 0.014 * Math.sin(u * Math.PI), (wBaseL + wTipL) * 0.52);
      const p2 = squidPoint(t + 0.006, wTipL);
      brush.set("underglaze_needle", i % 3 === 0 ? PALETTE.cobaltMid : PALETTE.cobaltSoft, 0.36);
      drawSpline([p0, p1, p2], 0.45);
    }

    // Upper-right fin ray
    const wBaseU = mantleHalfWidth(t, -1) * 0.76;
    const wTipU = finSpan(t, -1) * 0.97;
    if (wTipU - wBaseU > 8) {
      const q0 = squidPoint(t, -wBaseU);
      const q1 = squidPoint(t + 0.012 * Math.sin(u * Math.PI), -(wBaseU + wTipU) * 0.52);
      const q2 = squidPoint(t + 0.005, -wTipU);
      brush.set("underglaze_needle", i % 3 === 0 ? PALETTE.cobaltMid : PALETTE.washMid, 0.32);
      drawSpline([q0, q1, q2], 0.45);
    }
  }

  // Crisp undulating fin contours (double-lined at the translucent membrane edge)
  const finContourL = [];
  const finInnerRimL = [];
  for (let i = 0; i <= 32; i++) {
    const t = 0.005 + (i / 32) * 0.57;
    const sp = finSpan(t, 1);
    finContourL.push(squidPoint(t, sp));
    finInnerRimL.push(squidPoint(t, sp - 3.5));
  }
  brush.set("rotring", PALETTE.navyPool, 0.58);
  drawSpline(finContourL, 0.5);
  brush.set("underglaze_needle", PALETTE.cobaltMid, 0.35);
  drawSpline(finInnerRimL, 0.5);

  const finContourU = [];
  const finInnerRimU = [];
  for (let i = 0; i <= 32; i++) {
    const t = 0.005 + (i / 32) * 0.56;
    const sp = finSpan(t, -1);
    finContourU.push(squidPoint(t, -sp));
    finInnerRimU.push(squidPoint(t, -(sp - 3.2)));
  }
  brush.set("rotring", PALETTE.cobaltDeep, 0.52);
  drawSpline(finContourU, 0.5);
  brush.set("underglaze_needle", PALETTE.cobaltSoft, 0.32);
  drawSpline(finInnerRimU, 0.5);

  // 5B. Mantle Contours, Internal Gladius Line, and Subtle Transverse Muscle Rings
  const mantleLowerOutline = [];
  const mantleUpperOutline = [];
  const finJunctionLineL = [];
  const finJunctionLineU = [];

  for (let i = 0; i <= 34; i++) {
    const t = i / 34;
    mantleLowerOutline.push(squidPoint(t, mantleHalfWidth(t, 1)));
    mantleUpperOutline.push(squidPoint(t, -mantleHalfWidth(t, -1)));
    if (t <= 0.57) {
      finJunctionLineL.push(squidPoint(t, mantleHalfWidth(t, 1) * 0.78));
      finJunctionLineU.push(squidPoint(t, -mantleHalfWidth(t, -1) * 0.78));
    }
  }

  brush.set("rotring", PALETTE.navyPool, 0.65);
  drawSpline(mantleLowerOutline, 0.5);
  brush.set("rotring", PALETTE.cobaltMid, 0.45);
  drawSpline(mantleUpperOutline, 0.5);

  brush.set("underglaze_needle", PALETTE.cobaltDeep, 0.48);
  drawSpline(finJunctionLineL, 0.5);
  drawSpline(finJunctionLineU, 0.5);

  // Faint buried dorsal gladius (chitinous pen) running down the spine
  const gladiusPts = [];
  for (let i = 0; i <= 24; i++) {
    const t = (i / 24) * 0.94;
    gladiusPts.push(squidPoint(t, 3));
  }
  brush.set("2H", PALETTE.cobaltSoft, 0.42);
  drawSpline(gladiusPts, 0.5);

  // Subtle curved cross-contour muscle rings on the shaded lower half of the mantle
  brush.set("underglaze_needle", PALETTE.washMid, 0.28);
  for (let i = 2; i < 28; i++) {
    const t = i / 29;
    const wL = mantleHalfWidth(t, 1);
    const ringPts = [
      squidPoint(t - 0.008, wL * 0.08),
      squidPoint(t + 0.008, wL * 0.42),
      squidPoint(t + 0.005, wL * 0.78),
      squidPoint(t - 0.006, wL * 0.96)
    ];
    drawSpline(ringPts, 0.5);
  }

  // Crisp Collar Rim & Siphon Pen Contours
  const collarLipFront = [];
  const collarLipBack = [];
  for (let i = 0; i <= 18; i++) {
    const u = -1 + (i / 18) * 2;
    const n = u * 74;
    const tFront = 0.965 + (1 - u * u) * 0.025;
    const tBack = 0.995 + (1 - u * u) * 0.042;
    collarLipFront.push(squidPoint(tFront, n));
    collarLipBack.push(squidPoint(tBack, n * 0.92));
  }
  brush.set("rotring", PALETTE.navyPool, 0.68);
  drawSpline(collarLipFront, 0.5);
  brush.set("rotring", PALETTE.cobaltDeep, 0.52);
  drawSpline(collarLipBack, 0.5);

  // Siphon outline
  brush.set("rotring", PALETTE.cobaltDeep, 0.48);
  drawSpline([
    squidPoint(0.96, 64),
    squidPoint(1.01, 94),
    squidPoint(1.08, 92),
    squidPoint(1.11, 64)
  ], 0.45);

  // Eyelid skin folds around the squid eyes
  const eyeL = squidPoint(1.13, 38);
  const lidPts1 = [];
  const lidPts2 = [];
  for (let i = 0; i <= 14; i++) {
    const a = -0.6 + (i / 14) * Math.PI * 1.45;
    lidPts1.push([eyeL[0] + Math.cos(a) * 21, eyeL[1] + Math.sin(a) * 18.5]);
    lidPts2.push([eyeL[0] + Math.cos(a + Math.PI) * 22, eyeL[1] + Math.sin(a + Math.PI) * 19.5]);
  }
  brush.set("rotring", PALETTE.navyPool, 0.58);
  drawSpline(lidPts1, 0.5);
  brush.set("underglaze_needle", PALETTE.cobaltMid, 0.42);
  drawSpline(lidPts2, 0.5);

  // 5C. Tentacles & Arms Contours + Detailed Suckers (Acetabula)
  const suckerCupsWash = [];
  const suckerRings = [];

  for (let a = 0; a < arms.length; a++) {
    const arm = arms[a];
    const upperEdge = [];
    const lowerEdge = [];
    const steps = 34;

    for (let i = 0; i <= steps; i++) {
      const u = i / steps;
      const c = evalCurve(arm.pts, u);
      const hw = armHalfWidth(arm, u);
      upperEdge.push([c.x - c.nx * hw, c.y - c.ny * hw]);
      lowerEdge.push([c.x + c.nx * hw, c.y + c.ny * hw]);
    }

    // Upper illuminated edge (fine crisp cobalt line)
    brush.set("underglaze_needle", PALETTE.cobaltMid, 0.42);
    drawSpline(upperEdge, 0.5);

    // Lower shaded edge (rich dark navy pen line)
    brush.set("rotring", PALETTE.navyPool, 0.62);
    drawSpline(lowerEdge, 0.5);

    // Compute anatomical sucker placements along the ventral surface
    const uStart = arm.isClub ? 0.62 : 0.08;
    const uEnd = 0.96;
    const count = arm.isClub ? 24 : 22;

    for (let s = 0; s < count; s++) {
      const su = uStart + (uEnd - uStart) * (s / count);
      const c = evalCurve(arm.pts, su);
      const hw = armHalfWidth(arm, su);

      // Staggered biserial rows (or quadriserial on tentacular clubs)
      const rowToggle = (s % 2 === 0) ? 1 : -1;
      const sideOffset = arm.suckerSide * hw * (0.62 + rowToggle * 0.24);
      const sx = c.x + c.nx * sideOffset;
      const sy = c.y + c.ny * sideOffset;

      let cupR;
      if (arm.isClub) {
        const clubU = (su - 0.62) / 0.34;
        cupR = (1.6 + Math.sin(clubU * Math.PI) * 3.8) * (s % 2 === 0 ? 1.05 : 0.78);
      } else {
        cupR = Math.max(1.3, (4.8 * Math.pow(1 - su, 0.68)) * (s % 2 === 0 ? 1.0 : 0.82));
      }

      // Pedicle (tiny muscular stalk attaching sucker cup to arm margin)
      const pedX = c.x + c.nx * (arm.suckerSide * hw * 0.35);
      const pedY = c.y + c.ny * (arm.suckerSide * hw * 0.35);

      suckerRings.push({ sx, sy, cupR, pedX, pedY, nx: c.nx * arm.suckerSide, ny: c.ny * arm.suckerSide });

      // Collect cup shadow polygon for larger suckers
      if (cupR > 2.2) {
        const cupPoly = [];
        for (let k = 0; k < 8; k++) {
          const ang = (k / 8) * Math.PI * 2;
          cupPoly.push([
            sx + Math.cos(ang) * cupR * 0.95,
            sy + Math.sin(ang) * cupR * 0.85
          ]);
        }
        suckerCupsWash.push(cupPoly);
      }
    }
  }

  // Batch-fill the soft cobalt cup shadows inside the larger suckers
  brush.noStroke();
  brush.fill(PALETTE.washMid, 115);
  brush.fillBleed(0.05, "in");
  for (let poly of suckerCupsWash) {
    drawPoly(poly, 0.5);
  }

  // Draw the fine blue pen rings, pedicles, and inner acetabular cavities for all suckers
  brush.noFill();
  for (let sk of suckerRings) {
    // Tiny pedicle stalk
    brush.set("underglaze_needle", PALETTE.cobaltMid, 0.32);
    brush.line(sk.pedX, sk.pedY, sk.sx, sk.sy);

    // Muscular outer sucker ring
    brush.set("rotring", PALETTE.cobaltDeep, sk.cupR > 3.0 ? 0.45 : 0.32);
    brush.circle(sk.sx, sk.sy, sk.cupR, 0.15);

    // Dark inner chitinous ring / cup cavity
    if (sk.cupR > 2.0) {
      brush.set("rotring", PALETTE.navyPool, 0.38);
      brush.circle(sk.sx + sk.nx * 0.4, sk.sy + sk.ny * 0.4, sk.cupR * 0.42, 0.1);
    }
  }
}

// ---------------------------------------------------------------------------
// LAYER 6: CHROMATOPHORE SPECKLES (GRADED COBALT STIPPLING)
// ---------------------------------------------------------------------------
function drawChromatophores(arms) {
  // Chromatophores are pigment sacs distributed across the dorsal mantle,
  // head crown, fin junctions, and aboral surfaces of the arms.
  const expandedMid = [];
  const expandedDeep = [];
  const contractedDots = [];

  // Helper to create tiny organic chromatophore spot polygon
  function makeSpotPoly(x, y, rx, ry, rot) {
    const pts = [];
    const c = Math.cos(rot), s = Math.sin(rot);
    for (let k = 0; k < 6; k++) {
      const a = (k / 6) * Math.PI * 2;
      const lx = Math.cos(a) * rx * (0.85 + random(0.3));
      const ly = Math.sin(a) * ry * (0.85 + random(0.3));
      pts.push([x + lx * c - ly * s, y + lx * s + ly * c]);
    }
    return pts;
  }

  // 6A. Mantle & Fin Chromatophores
  for (let i = 0; i < 680; i++) {
    const t = Math.pow(random(), 0.92) * 0.98;
    const wMaxL = mantleHalfWidth(t, 1);
    const wMaxU = mantleHalfWidth(t, -1);

    // Gaussian-like concentration near dorsal spine & upper-mid mantle
    const uRand = (random() + random() + random()) / 3 - 0.46;
    const n = uRand * (wMaxL + wMaxU);

    // Keep the core of the dorsal specular highlight strip mostly clean!
    const inHighlight = (n > -wMaxU * 0.40 && n < -wMaxU * 0.14 && t > 0.08 && t < 0.92);
    if (inHighlight && random() < 0.88) continue;

    const pt = squidPoint(t, n);
    const sp = squidSpine(t);
    const dNorm = Math.abs(n) / Math.max(10, wMaxL);

    if (random() < 0.22 && !inHighlight && dNorm < 0.65) {
      // Expanded chromatophore (tiny cobalt wash/spot)
      const r = random(2.1, 4.4) * (1 - dNorm * 0.35);
      if (random() < 0.55) {
        expandedMid.push(makeSpotPoly(pt[0], pt[1], r * 1.2, r * 0.85, sp.ang));
      } else {
        expandedDeep.push(makeSpotPoly(pt[0], pt[1], r, r * 0.8, sp.ang));
      }
    } else {
      // Contracted chromatophore (pinpoint dark cobalt / navy speckle)
      contractedDots.push({
        x: pt[0],
        y: pt[1],
        ang: sp.ang,
        len: random(0.8, 2.4),
        w: random(0.32, 0.72),
        dark: dNorm < 0.45 || random() < 0.45
      });
    }
  }

  // Fin surface speckles (denser near mantle junction and posterior apex, sparse in center)
  for (let i = 0; i < 260; i++) {
    const t = 0.02 + random(0.53);
    const side = random() < 0.54 ? 1 : -1;
    const mW = mantleHalfWidth(t, side) * 0.75;
    const fW = finSpan(t, side);
    if (fW <= mW + 5) continue;

    // Bias toward junction or outer rim
    const bias = random() < 0.65 ? Math.pow(random(), 1.8) : 1 - Math.pow(random(), 2.2) * 0.35;
    const n = side * (mW + (fW - mW) * bias);
    const pt = squidPoint(t, n);
    const sp = squidSpine(t);

    if (random() < 0.16) {
      const r = random(1.8, 3.2);
      expandedMid.push(makeSpotPoly(pt[0], pt[1], r, r * 0.8, sp.ang));
    } else {
      contractedDots.push({
        x: pt[0],
        y: pt[1],
        ang: sp.ang,
        len: random(0.7, 1.8),
        w: random(0.28, 0.55),
        dark: bias > 0.8 || random() < 0.35
      });
    }
  }

  // Head & Arm dorsal chromatophores
  for (let i = 0; i < 160; i++) {
    const t = 0.98 + random(0.29);
    const n = random(-28, 42);
    const pt = squidPoint(t, n);
    if (random() < 0.25) {
      const r = random(2.0, 3.8);
      expandedDeep.push(makeSpotPoly(pt[0], pt[1], r, r * 0.85, 0.7));
    } else {
      contractedDots.push({
        x: pt[0],
        y: pt[1],
        ang: 0.75,
        len: random(0.9, 2.2),
        w: random(0.35, 0.68),
        dark: true
      });
    }
  }

  for (let a = 0; a < arms.length; a++) {
    const arm = arms[a];
    const dotsCount = arm.isClub ? 55 : 42;
    for (let i = 0; i < dotsCount; i++) {
      const u = random(0.02, 0.92);
      const c = evalCurve(arm.pts, u);
      const hw = armHalfWidth(arm, u);
      const nOff = random(-hw * 0.7, hw * 0.75);
      const x = c.x + c.nx * nOff;
      const y = c.y + c.ny * nOff;
      contractedDots.push({
        x, y,
        ang: Math.atan2(c.ty, c.tx),
        len: random(0.7, 1.9),
        w: random(0.3, 0.6),
        dark: random() < 0.55
      });
    }
  }

  // Render expanded chromatophore spots in two color batches
  brush.noStroke();
  brush.noHatch();

  brush.fill(PALETTE.cobaltSoft, 140);
  brush.fillBleed(0.06, "out");
  for (let p of expandedMid) {
    drawPoly(p, 0.5);
  }

  brush.fill(PALETTE.cobaltDeep, 165);
  brush.fillBleed(0.04, "in");
  for (let p of expandedDeep) {
    drawPoly(p, 0.5);
  }

  // Render contracted pinpoint chromatophores
  brush.noFill();
  for (let d of contractedDots) {
    brush.set("rotring", d.dark ? PALETTE.navyPool : PALETTE.cobaltMid, d.w);
    const dx = Math.cos(d.ang) * d.len * 0.5;
    const dy = Math.sin(d.ang) * d.len * 0.5;
    brush.line(d.x - dx, d.y - dy, d.x + dx, d.y + dy);
  }
}

// ---------------------------------------------------------------------------
// LAYER 7: WET GLASSY SHEEN & PORCELAIN-WHITE SPECULAR HIGHLIGHTS
// ---------------------------------------------------------------------------
function drawWetGlassySheen(arms) {
  brush.noFill();
  brush.noHatch();

  // 7A. Razor-sharp wet highlights on the gelatinous cornea of the squid eyes
  const eyeL = squidPoint(1.13, 38);
  brush.set("wet_glint", PALETTE.porcelain, 1.35);
  drawSpline([
    [eyeL[0] - 9, eyeL[1] - 9],
    [eyeL[0] - 2, eyeL[1] - 12],
    [eyeL[0] + 6, eyeL[1] - 9],
    [eyeL[0] + 10, eyeL[1] - 2]
  ], 0.5);

  // Secondary pinpoint corneal catchlight
  brush.set("wet_glint", PALETTE.porcelain, 1.1);
  brush.line(eyeL[0] - 7, eyeL[1] + 5, eyeL[0] - 4, eyeL[1] + 7);

  // Upper-right profile eye catchlight
  const eyeU = squidPoint(1.11, -44);
  brush.set("wet_glint", PALETTE.porcelain, 1.05);
  drawSpline([
    [eyeU[0] - 6, eyeU[1] - 7],
    [eyeU[0] + 1, eyeU[1] - 8],
    [eyeU[0] + 6, eyeU[1] - 4]
  ], 0.5);

  // 7B. Wet specular sheen along the dorsal ridge of the mantle, collar lip & head
  brush.set("wet_glint", PALETTE.porcelain, 1.5);
  for (let seg = 0; seg < 5; seg++) {
    const t0 = 0.08 + seg * 0.17;
    const t1 = t0 + 0.12;
    const pts = [];
    for (let k = 0; k <= 6; k++) {
      const t = t0 + (t1 - t0) * (k / 6);
      const n = -mantleHalfWidth(t, -1) * 0.28 + Math.sin(t * 20) * 1.5;
      pts.push(squidPoint(t, n));
    }
    drawSpline(pts, 0.5);
  }

  // Glossy wet glint along the flared lip of the mantle collar
  brush.set("wet_glint", PALETTE.porcelain, 1.2);
  drawSpline([
    squidPoint(0.975, -38),
    squidPoint(0.985, -14),
    squidPoint(0.988, 12),
    squidPoint(0.980, 34)
  ], 0.5);

  // Wet highlights along the anterior ridges of both rhomboid fins
  brush.set("wet_glint", PALETTE.porcelain, 1.0);
  drawSpline([
    squidPoint(0.22, finSpan(0.22, 1) * 0.55),
    squidPoint(0.32, finSpan(0.32, 1) * 0.65),
    squidPoint(0.42, finSpan(0.42, 1) * 0.58)
  ], 0.5);

  drawSpline([
    squidPoint(0.18, -finSpan(0.18, -1) * 0.52),
    squidPoint(0.28, -finSpan(0.28, -1) * 0.62),
    squidPoint(0.38, -finSpan(0.38, -1) * 0.55)
  ], 0.5);

  // 7C. Wet ridge highlights along the curling tentacles & arms
  for (let a = 0; a < arms.length; a++) {
    const arm = arms[a];
    brush.set("wet_glint", PALETTE.porcelain, arm.isClub ? 0.85 : 1.05);
    for (let b = 0; b < 3; b++) {
      const u0 = 0.08 + b * 0.28;
      const u1 = u0 + 0.18;
      const glintPts = [];
      for (let k = 0; k <= 5; k++) {
        const u = u0 + (u1 - u0) * (k / 5);
        const c = evalCurve(arm.pts, u);
        const hw = armHalfWidth(arm, u);
        glintPts.push([c.x - c.nx * hw * 0.35, c.y - c.ny * hw * 0.35]);
      }
      drawSpline(glintPts, 0.5);
    }
  }

  // 7D. High-gloss specular reflection streaks on the rolled enamel tray rim & pooled water
  brush.set("wet_glint", PALETTE.porcelain, 1.45);
  const rimCrestOff = TRAY.bevelW + TRAY.rimW * 0.46;
  drawSpline(buildTrayBoundary(rimCrestOff, -540 - rimCrestOff, -120, -1, 22), 0.4);
  drawSpline(buildTrayBoundary(rimCrestOff, -40, 520, -1, 24), 0.4);
  drawSpline(buildTrayBoundary(rimCrestOff, -520 - rimCrestOff, -160, 1, 22), 0.4);
  drawSpline(buildTrayBoundary(rimCrestOff, -60, 580, 1, 26), 0.4);

  // Crisp glossy tray reflection streaks cutting through the faint water reflection
  brush.set("wet_glint", PALETTE.porcelain, 1.15);
  const sheenStreaks = [
    [trayToWorld(-220, 145), trayToWorld(-80, 145)],
    [trayToWorld(-140, 185), trayToWorld(45, 185)],
    [trayToWorld(60, 110), trayToWorld(230, 110)],
    [trayToWorld(180, 210), trayToWorld(380, 210)]
  ];
  for (let st of sheenStreaks) {
    brush.line(st[0][0], st[0][1], st[1][0], st[1][1]);
  }
}

