  });

  brush.add("vesicle_core", {
    type: "default",
    weight: 0.62,
    scatter: 0.08,
    sharpness: 0.42,
    grain: 0.45,
    opacity: 62,
    spacing: 0.14,
    pressure: [0.08, 1.25, 0.08],
