function draw() {
  translate(-width / 2, -height / 2);

  // Precompute slice centers and anatomical geometry
  for (let i = 0; i < SLICES.length; i++) {
    let s = SLICES[i];
    s.cx = CX + RING_R * cos(s.angle);
    s.cy = CY + RING_R * sin(s.angle);
    buildSliceAnatomy(s, i);
  }

  // 1. Flat grey board with subtle backlit sub-illumination
  drawGreyBoardAndBacklight();

  // 2. Didactic chart under-drawing (visible on board & faintly under slices)
  drawDidacticChartUnderlay();

  // 3. Sub-surface chromatic halo & contact shadow beneath each slice
  drawSubsurfaceHalos();

  // 4. Citrus outer rind (flavedo) & white pith (albedo) discs
  drawRindAndPithLayers();

  // 5. Translucent watercolor glazes inside every segment (locule)
  drawSegmentWatercolorGlazes();

  // 6. Hyperreal juice vesicles, membranes, columella cores & cut seeds
  for (let i = 0; i < SLICES.length; i++) {
    drawSliceInternalHyperrealism(SLICES[i], i);
  }

  // 7. Escaped juice beads & wet meniscus highlights on the grey board
  drawJuiceDropletsAndMeniscus();

  // 8. Ruled pencil annotations, pigment swatches & plate typography
  drawMarginaliaAndAnnotations();

  noLoop();
}

// ============================================================================
// ANATOMY BUILDER
// ============================================================================
function buildSliceAnatomy(s, idx) {
  let nSeg = s.segments;
  s.segData = [];
  let angles = [];
  let totalWeight = 0;
  let weights = [];

  for (let k = 0; k < nSeg; k++) {
    let w = 1 + random(-0.11, 0.11);
    weights.push(w);
    totalWeight += w;
  }

  let acc = random(0, 360);
  s.baseRot = acc;
  for (let k = 0; k < nSeg; k++) {
    let span = (weights[k] / totalWeight) * 360;
    let a1 = acc;
    let a2 = acc + span;
    let mid = (a1 + a2) * 0.5;
    // Angular padding for the radial septum wall between segments
    let padOuter = 1.9 + (10 / nSeg) * 0.3;
    let padInner = 5.2;
    let rOuter = s.r - s.rindThick - s.pithThick + random(-1.2, 1.2);
    let rInner = s.coreR + random(1.5, 4.0);

    // Navel orange has a small secondary infolding on one side
    if (s.navel && k === 0) {
      rInner += 12;
    }

    s.segData.push({
      k,
      a1,
      a2,
      mid,
      span,
      padOuter,
      padInner,
      rOuter,
      rInner,
      hasSeed: false,
      seedSubmerged: false
    });
    acc = a2;
  }

  // Assign seeds to specific segments realistically
  if (s.seeds > 0) {
    let indices = [];
    for (let k = 0; k < nSeg; k++) indices.push(k);
    // Shuffle
    for (let k = indices.length - 1; k > 0; k--) {
      let j = floor(random(k + 1));
      let tmp = indices[k];
      indices[k] = indices[j];
      indices[j] = tmp;
    }
    for (let m = 0; m < s.seeds; m++) {
      let seg = s.segData[indices[m]];
      seg.hasSeed = true;
      seg.seedSubmerged = m % 2 === 1;
      seg.seedR = seg.rInner + (seg.rOuter - seg.rInner) * random(0.14, 0.28);
      seg.seedAngle = seg.mid + random(-seg.span * 0.12, seg.span * 0.12);
      seg.seedLen = random(9.5, 13.5);
      seg.seedWid = random(4.8, 6.6);
    }
  }
}

// Helper for organic slice radius at any polar angle around slice center
function getSliceOuterR(s, theta, idx) {
  let lobing = sin((theta - s.baseRot) * s.segments) * s.scallop;
  let n =
    (noise(idx * 17 + cos(theta) * 1.3 + 2, idx * 31 + sin(theta) * 1.3 + 2) -
      0.5) *
    4.6;
  return s.r + lobing + n;
}

// ============================================================================
// 1. FLAT GREY BOARD & SUB-ILLUMINATION
// ============================================================================
function drawGreyBoardAndBacklight() {
  // Base warm-cool architectural grey board
  background("#c8c4ba");

  // Outer vignette & slate board shading
  brush.noStroke();
  brush.fillTexture(0.55, 0.25);
  brush.fillBleed(0.35, "in");
  brush.fill("#b4b0a5", 45);
  brush.rect(20, 20, 1160, 1160, "corner");

  // Backlit lightbox glow centered under the citrus ring
  brush.fillBleed(0.45, "out");
  brush.fillTexture(0.35, 0.15);
  brush.fill("#e3dfd3", 85);
  brush.circle(CX, CY, 475, 0.08);

  brush.fill("#f0ece0", 90);
  brush.circle(CX, CY, 415, 0.06);

  // Darker grey inner hub slightly dimmer than the ring itself
  brush.fill("#cfcbc0", 65);
  brush.circle(CX, CY, 195, 0.06);
  brush.noFill();

  // Subtle fine stone/slate grain across the board
  brush.noField();
  for (let i = 0; i < 95; i++) {
    let x1 = random(35, 1165);
    let y1 = random(35, 1165);
    let len = random(60, 220);
    let ang = random(-8, 8);
    let col = i % 2 === 0 ? "#b8b4a9" : "#d8d4c9";
    brush.set("board_grain", col, random(0.6, 1.3));
    brush.line(x1, y1, x1 + len * cos(ang), y1 + len * sin(ang));
  }

  // Micro-pitted limestone pencil texture
  brush.set("2H", "#9e9a8f", 0.18);
  for (let i = 0; i < 160; i++) {
    let rx = random(40, 1160);
    let ry = random(40, 1160);
    brush.line(rx, ry, rx + random(1.5, 4.5), ry + random(-1.5, 1.5));
  }
}

// ============================================================================
// 2. DIDACTIC CHART UNDER-DRAWING
// ============================================================================
function drawDidacticChartUnderlay() {
  brush.noFill();
  brush.noField();

  // Outer ruled frame
  brush.set("2H", "#7c7970", 0.28);
  brush.rect(28, 28, 1144, 1144, "corner");
  brush.set("2H", "#8f8b82", 0.18);
  brush.rect(34, 34, 1132, 1132, "corner");

  // Concentric technical circles
  const rings = [
    { r: 478, w: 0.26, col: "#78756c" },
    { r: 468, w: 0.2, col: "#858178" },
    { r: 326, w: 0.22, col: "#8c887e" },
    { r: 192, w: 0.22, col: "#7c7970" },
    { r: 182, w: 0.16, col: "#8c887e" },
    { r: 46, w: 0.18, col: "#827e75" },
    { r: 12, w: 0.22, col: "#6e6b63" }
  ];
  for (let rg of rings) {
    brush.set("2H", rg.col, rg.w);
    brush.circle(CX, CY, rg.r, 0.008);
  }

  // Degree tick marks around outer graduated ring (R = 468..478)
  for (let d = 0; d < 360; d += 2) {
    let a = d - 90;
    let isMajor = d % 40 === 0;
    let isTen = d % 10 === 0;
    let r1 = 468;
    let r2 = isMajor ? 484 : isTen ? 478 : 473;
    brush.set("2H", isMajor ? "#59564f" : "#878379", isMajor ? 0.32 : 0.17);
    brush.line(
      CX + r1 * cos(a),
      CY + r1 * sin(a),
      CX + r2 * cos(a),
      CY + r2 * sin(a)
    );
  }

  // Inner degree ticks around central hub (R = 182..192)
  for (let d = 0; d < 360; d += 5) {
    let a = d - 90;
    let isStation = d % 40 === 0;
    let r1 = isStation ? 176 : 182;
    let r2 = 192;
    brush.set("2H", isStation ? "#615e56" : "#8f8b81", isStation ? 0.28 : 0.15);
    brush.line(
      CX + r1 * cos(a),
      CY + r1 * sin(a),
      CX + r2 * cos(a),
      CY + r2 * sin(a)
    );
  }

  // Complementary chord network inside the central hub (connecting station i to i+4 and i+5)
  for (let i = 0; i < 9; i++) {
    let a1 = SLICES[i].angle;
    let a2 = SLICES[(i + 4) % 9].angle;
    let x1 = CX + 176 * cos(a1);
    let y1 = CY + 176 * sin(a1);
    let x2 = CX + 176 * cos(a2);
    let y2 = CY + 176 * sin(a2);
    drawDashedPencilLine(x1, y1, x2, y2, 7, 5, "#878379", 0.18);
  }

  // Radial station axes passing right under the slices (so they show faintly through the fruit!)
  for (let i = 0; i < 9; i++) {
    let a = SLICES[i].angle;
    brush.set("2H", "#7d7970", 0.22);
    brush.line(
      CX + 46 * cos(a),
      CY + 46 * sin(a),
      CX + 484 * cos(a),
      CY + 484 * sin(a)
    );

    // Small station node circle on inner hub ring
    let nx = CX + 176 * cos(a);
    let ny = CY + 176 * sin(a);
    brush.set("rotring", "#5c5951", 0.24);
    brush.circle(nx, ny, 3.2, 0.02);

    // Degree label inside hub
    let tx = CX + 154 * cos(a);
    let ty = CY + 154 * sin(a) - 3.5;
    let degStr = nf(SLICES[i].deg, 3) + "°";
    drawTextBrush(degStr, tx, ty, 5.8, "#636058", 0.2, "center");
  }

  // Central compass crosshair & notation
  brush.set("rotring", "#5e5b53", 0.24);
  brush.line(CX - 22, CY, CX + 22, CY);
  brush.line(CX, CY - 22, CX, CY + 22);
  drawTextBrush("COMPLEMENTARY", CX, CY - 72, 6.2, "#69655d", 0.2, "center");
  drawTextBrush("DIOPTRE AXIS", CX, CY + 64, 6.2, "#69655d", 0.2, "center");
}

function drawDashedPencilLine(x1, y1, x2, y2, dashLen, gapLen, col, weight) {
  let d = dist(x1, y1, x2, y2);
  let steps = floor(d / (dashLen + gapLen));
  brush.set("2H", col, weight);
  for (let i = 0; i < steps; i++) {
    let t1 = (i * (dashLen + gapLen)) / d;
    let t2 = min(1, (i * (dashLen + gapLen) + dashLen) / d);
    brush.line(
      lerp(x1, x2, t1),
      lerp(y1, y2, t1),
      lerp(x1, x2, t2),
      lerp(y1, y2, t2)
    );
  }
}

// ============================================================================
// 3. SUB-SURFACE BACKLIT HALOS & WET CONTACT SHADOWS
// ============================================================================
function drawSubsurfaceHalos() {
  brush.noStroke();
  for (let i = 0; i < SLICES.length; i++) {
    let s = SLICES[i];

    // Chromatic subsurface glow bleeding onto the grey board
    brush.fillBleed(0.38, "out");
    brush.fillTexture(0.35, 0.15);
    brush.fill(s.palette.halo, 62);
    brush.circle(s.cx, s.cy, s.r + 14, 0.08);

    // Bright backlit core beneath the slice pulp
    brush.fillBleed(0.15, "out");
    brush.fill("#fcf9ef", 195);
    brush.circle(s.cx, s.cy, s.r - 2, 0.04);
  }
  brush.noFill();

  // Thin wet contact shadow around the outer perimeter of each slice
  for (let i = 0; i < SLICES.length; i++) {
    let s = SLICES[i];
    brush.set("2B", "#787368", 0.42);
    brush.beginShape(0.35);
    for (let a = 0; a < 360; a += 8) {
      let r = getSliceOuterR(s, a, i) + 2.2;
      // Slightly heavier shadow on the outer radial side away from center light
      let shift = 1.6;
      let sx = s.cx + shift * cos(s.angle) + r * cos(a);
      let sy = s.cy + shift * sin(s.angle) + r * sin(a);
      brush.vertex(sx, sy);
    }
    brush.endShape(true);
  }
}

// ============================================================================
// 4. OUTER RIND (FLAVEDO) & WHITE PITH (ALBEDO)
// ============================================================================
function drawRindAndPithLayers() {
  for (let i = 0; i < SLICES.length; i++) {
    let s = SLICES[i];

    // Soft creamy-ivory albedo pith base shape
    brush.noStroke();
    brush.fillBleed(0.06, "in");
    brush.fillTexture(0.35, 0.25);
    brush.fill(s.palette.pith, 235);
    brush.beginShape(0.35);
    for (let a = 0; a < 360; a += 6) {
      let r = getSliceOuterR(s, a, i) - s.rindThick * 0.4;
      brush.vertex(s.cx + r * cos(a), s.cy + r * sin(a));
    }
    brush.endShape(true);
    brush.noFill();

    // Subtle spongy shadow ring inside the thick part of the pith (blocking backlight slightly)
    let pithMidR = s.r - s.rindThick - s.pithThick * 0.45;
    brush.set("charcoal", s.palette.pithShadow, 0.55);
    for (let a = 0; a < 360; a += 10) {
      let a2 = a + 8;
      let r1 = getSliceOuterR(s, a, i) - s.rindThick - s.pithThick * 0.42;
      let r2 = getSliceOuterR(s, a2, i) - s.rindThick - s.pithThick * 0.42;
      brush.line(
        s.cx + r1 * cos(a),
        s.cy + r1 * sin(a),
        s.cx + r2 * cos(a2),
        s.cy + r2 * sin(a2)
      );
    }

    // Inner pith glowing rim right against the translucent pulp
    brush.set("backlit_spark", "#fffdf6", 0.9);
    brush.beginShape(0.3);
    for (let a = 0; a < 360; a += 8) {
      let r = getSliceOuterR(s, a, i) - s.rindThick - s.pithThick + 1.2;
      brush.vertex(s.cx + r * cos(a), s.cy + r * sin(a));
    }
    brush.endShape(true);

    // Outer zest / flavedo ring (inner warm band + outer dense skin)
    brush.set("cpencil", s.palette.rindInner, s.rindThick * 0.28);
    brush.beginShape(0.35);
    for (let a = 0; a < 360; a += 5) {
      let r = getSliceOuterR(s, a, i) - s.rindThick * 0.55;
      brush.vertex(s.cx + r * cos(a), s.cy + r * sin(a));
    }
    brush.endShape(true);

    brush.set("HB", s.palette.rindOuter, s.rindThick * 0.22);
    brush.beginShape(0.35);
    for (let a = 0; a < 360; a += 5) {
      let r = getSliceOuterR(s, a, i) - s.rindThick * 0.15;
      brush.vertex(s.cx + r * cos(a), s.cy + r * sin(a));
    }
    brush.endShape(true);

    // Essential oil glands (tiny translucent/dark punctate dots along the zest)
    for (let a = 0; a < 360; a += 3.5) {
      let rOil =
        getSliceOuterR(s, a, i) - s.rindThick * random(0.25, 0.85);
      let ox = s.cx + rOil * cos(a);
      let oy = s.cy + rOil * sin(a);
      brush.set(
        "rotring",
        random() < 0.65 ? s.palette.rindOuter : s.palette.washLight,
        random(0.2, 0.36)
      );
      brush.line(ox, oy, ox + 0.6, oy + 0.6);
    }
  }
}

// ============================================================================
// 5. TRANSLUCENT SEGMENT WATERCOLOR GLAZES
// ============================================================================
function drawSegmentWatercolorGlazes() {
  brush.noStroke();

  // Pass 1: Luminous backlit base glaze across each segment wedge
  for (let i = 0; i < SLICES.length; i++) {
    let s = SLICES[i];
    brush.fillBleed(0.08, "in");
    brush.fillTexture(0.42, 0.28);
    brush.fill(s.palette.washLight, 145);

    for (let seg of s.segData) {
      drawSegmentPolygon(s, seg, i, 1.0, 1.0);
    }
  }

  // Pass 2: Mid-tone pigment glaze pooled toward outer pericarp & side walls
  for (let i = 0; i < SLICES.length; i++) {
    let s = SLICES[i];
    brush.fillBleed(0.16, "in");
    brush.fillTexture(0.55, 0.42);
    brush.fill(s.palette.washMid, 118);

    for (let seg of s.segData) {
      drawSegmentPolygon(s, seg, i, 0.98, 0.25);
    }
  }

  // Pass 3: Deep peripheral pigment crescent near the outer segment wall
  for (let i = 0; i < SLICES.length; i++) {
    let s = SLICES[i];
    brush.fillBleed(0.22, "in");
    brush.fillTexture(0.6, 0.45);
    brush.fill(s.palette.washDeep, 88);

    for (let seg of s.segData) {
      drawOuterCrescentPolygon(s, seg, i);
    }
  }

  brush.noFill();
}

function drawSegmentPolygon(s, seg, sliceIdx, outerFrac, innerFrac) {
  let aStart = seg.a1 + seg.padOuter;
  let aEnd = seg.a2 - seg.padOuter;
  let aStartIn = seg.a1 + seg.padInner;
  let aEndIn = seg.a2 - seg.padInner;
  if (aEnd <= aStart) return;

  let rIn = lerp(seg.rOuter, seg.rInner, innerFrac);

  brush.beginShape(0.28);
  // Inner apex arc
  let midAngle = (aStartIn + aEndIn) * 0.5;
  brush.vertex(
    s.cx + rIn * cos(midAngle - (aEndIn - aStartIn) * 0.28),
    s.cy + rIn * sin(midAngle - (aEndIn - aStartIn) * 0.28)
  );
  // Left radial wall stepping outward
  let rMid1 = lerp(rIn, seg.rOuter, 0.55);
  brush.vertex(
    s.cx + rMid1 * cos(aStart + 0.8),
    s.cy + rMid1 * sin(aStart + 0.8)
  );

  // Outer curved wall along the albedo pith
  let steps = 5;
  for (let m = 0; m <= steps; m++) {
    let t = m / steps;
    let ang = lerp(aStart, aEnd, t);
    // Round off the two outer corners slightly
    let cornerRound = sin(t * 180);
    let rOut =
      (getSliceOuterR(s, ang, sliceIdx) - s.rindThick - s.pithThick) *
        outerFrac -
      (1 - cornerRound) * 3.2;
    brush.vertex(s.cx + rOut * cos(ang), s.cy + rOut * sin(ang));
  }

  // Right radial wall stepping inward
  brush.vertex(
    s.cx + rMid1 * cos(aEnd - 0.8),
    s.cy + rMid1 * sin(aEnd - 0.8)
  );
  brush.vertex(
    s.cx + rIn * cos(midAngle + (aEndIn - aStartIn) * 0.28),
    s.cy + rIn * sin(midAngle + (aEndIn - aStartIn) * 0.28)
  );
  brush.endShape(true);
}

function drawOuterCrescentPolygon(s, seg, sliceIdx) {
  let aStart = seg.a1 + seg.padOuter + 1.2;
  let aEnd = seg.a2 - seg.padOuter - 1.2;
  if (aEnd <= aStart) return;

  brush.beginShape(0.32);
  let steps = 5;
  for (let m = 0; m <= steps; m++) {
    let t = m / steps;
    let ang = lerp(aStart, aEnd, t);
    let cornerRound = sin(t * 180);
    let rOut =
      getSliceOuterR(s, ang, sliceIdx) -
      s.rindThick -
      s.pithThick -
      (1 - cornerRound) * 3.0;
    brush.vertex(s.cx + rOut * cos(ang), s.cy + rOut * sin(ang));
  }
  for (let m = steps; m >= 0; m--) {
    let t = m / steps;
    let ang = lerp(aStart, aEnd, t);
    let bandDepth = lerp(0.52, 0.72, abs(t - 0.5) * 2);
    if (s.bloodMottle) bandDepth = random(0.38, 0.74);
    let rIn = lerp(seg.rInner, seg.rOuter, bandDepth);
    brush.vertex(s.cx + rIn * cos(ang), s.cy + rIn * sin(ang));
  }
  brush.endShape(true);
}

// ============================================================================
// 6. INTERNAL HYPERREALISM: JUICE VESICLES, MEMBRANES, COLUMELLA & SEEDS
// ============================================================================
function drawSliceInternalHyperrealism(s, sliceIdx) {
  brush.noFill();
  brush.noField();

  // Faintly echo the underlying ruled chart axis line through the translucent pulp!
  let axisA = s.angle;
  brush.set("2H", s.palette.vesicleC, 0.16);
  brush.line(
    s.cx - (s.r - 16) * cos(axisA),
    s.cy - (s.r - 16) * sin(axisA),
    s.cx + (s.r - 16) * cos(axisA),
    s.cy + (s.r - 16) * sin(axisA)
  );

  // Draw submerged seeds FIRST so vesicles partially veil them
  for (let seg of s.segData) {
    if (seg.hasSeed && seg.seedSubmerged) {
      drawSeedCrossSection(s, seg, true);
    }
  }

  // Render packed fusiform juice vesicles inside every segment
  for (let seg of s.segData) {
    let aStart = seg.a1 + seg.padOuter + 1.1;
    let aEnd = seg.a2 - seg.padOuter - 1.1;
    let span = aEnd - aStart;
    if (span <= 2) continue;

    // Number of radial columns of vesicles in this segment
    let cols = floor(map(s.r, 85, 116, 13, 19));

    for (let c = 0; c <= cols; c++) {
      let u = c / cols; // 0..1 across segment angular width
      let angOuter = lerp(aStart, aEnd, u);
      let edgeFactor = sin(u * 180); // 0 at walls, 1 in middle of segment

      let rWall =
        getSliceOuterR(s, angOuter, sliceIdx) -
        s.rindThick -
        s.pithThick -
        (1 - edgeFactor) * 2.8;
      let rApex = seg.rInner + (1 - edgeFactor) * 5.5;

      // Vesicles angle slightly inward toward the central axis of the segment (herringbone fan)
      let angMid =
        angOuter + (seg.mid - angOuter) * 0.22 + random(-1.2, 1.2);
      let angInner =
        angOuter + (seg.mid - angOuter) * 0.45 + random(-1.8, 1.8);

      // Split radial span into 2 interlocking tiers of teardrop vesicles
      let splitFrac = random(0.46, 0.62);
      let rSplit = lerp(rApex, rWall, splitFrac);

      // --- OUTER TIER VESICLE (attached to outer pericarp wall) ---
      let p1x = s.cx + (rWall - 0.8) * cos(angOuter);
      let p1y = s.cy + (rWall - 0.8) * sin(angOuter);
      let p2x = s.cx + lerp(rSplit, rWall, 0.52) * cos((angOuter + angMid) * 0.5);
      let p2y = s.cy + lerp(rSplit, rWall, 0.52) * sin((angOuter + angMid) * 0.5);
      let p3x = s.cx + (rSplit - 2.0) * cos(angMid);
      let p3y = s.cy + (rSplit - 2.0) * sin(angMid);

      let colOuter = pickVesicleColor(s, u, 0.8, c);
      brush.set("vesicle_glaze", colOuter, random(0.85, 1.25));
      brush.spline(
        [
          [p1x, p1y, 0.15],
          [p2x, p2y, 1.35],
          [p3x, p3y, 0.15]
        ],
        0.35
      );

      // Richer pigment core inside outer vesicle
      if (c % 2 === 0 || s.bloodMottle) {
        let colCore =
          s.bloodMottle && random() < 0.55
            ? s.palette.vesicleC
            : s.palette.vesicleA;
        brush.set("vesicle_core", colCore, random(0.7, 1.05));
        brush.line(
          lerp(p1x, p2x, 0.25),
          lerp(p1y, p2y, 0.25),
          lerp(p2x, p3x, 0.75),
          lerp(p2y, p3y, 0.75)
        );
      }

      // --- INNER TIER VESICLE (reaching toward central columella) ---
      if (edgeFactor > 0.15) {
        let rInStart = rSplit + random(1.5, 4.0);
        let q1x = s.cx + rInStart * cos(angMid);
        let q1y = s.cy + rInStart * sin(angMid);
        let q2x =
          s.cx +
          lerp(rApex, rInStart, 0.5) * cos((angMid + angInner) * 0.5);
        let q2y =
          s.cy +
          lerp(rApex, rInStart, 0.5) * sin((angMid + angInner) * 0.5);
        let q3x = s.cx + (rApex + 1.5) * cos(angInner);
        let q3y = s.cy + (rApex + 1.5) * sin(angInner);

        let colInner = pickVesicleColor(s, u, 0.3, c);
        brush.set("vesicle_glaze", colInner, random(0.75, 1.1));
        brush.spline(
          [
            [q1x, q1y, 0.15],
            [q2x, q2y, 1.25],
            [q3x, q3y, 0.12]
          ],
          0.35
        );
      }

      // --- INTERSTITIAL MEMBRANE VEIN (delicate darker capillary wall between sacs) ---
      if (c % 2 === 1) {
        brush.set("cpencil", s.palette.vesicleC, 0.18);
        brush.line(p1x, p1y, p3x, p3y);
      }

      // --- BACKLIT SPECULAR FILAMENT (glowing light refracted inside vesicle sac) ---
      if (c % 2 === 0) {
        brush.set("backlit_spark", s.palette.spark, random(0.65, 1.05));
        brush.line(
          lerp(p1x, p2x, 0.45),
          lerp(p1y, p2y, 0.45),
          lerp(p2x, p3x, 0.65),
          lerp(p2y, p3y, 0.65)
        );
      }
      if (edgeFactor > 0.28 && c % 3 === 0) {
        let lR1 = lerp(rApex, rSplit, 0.72);
        let lR2 = lerp(rApex, rSplit, 0.25);
        brush.set("backlit_spark", "#fffef7", random(0.75, 1.15));
        brush.line(
          s.cx + lR1 * cos(angMid),
          s.cy + lR1 * sin(angMid),
          s.cx + lR2 * cos(angInner),
          s.cy + lR2 * sin(angInner)
        );
      }
    }

    // Perimeter outline of each segment pocket (locular membrane wall)
    drawLoculeWallDetail(s, seg, sliceIdx);
  }

  // Radial septa (creamy-white pith spokes dividing the segments)
  drawRadialSeptaAndColumella(s, sliceIdx);

  // Surface-transected (sharp cut) seeds on top of vesicles
  for (let seg of s.segData) {
    if (seg.hasSeed && !seg.seedSubmerged) {
      drawSeedCrossSection(s, seg, false);
    }
  }
}

function pickVesicleColor(s, u, radialT, colIdx) {
  if (s.bloodMottle) {
    // Blood orange: intense crimson-garnet at periphery & streaks, golden-ruby inside
    if (radialT > 0.55) {
      return random() < 0.65 ? s.palette.vesicleC : s.palette.vesicleA;
    } else {
      return random() < 0.5 ? s.palette.vesicleB : s.palette.vesicleA;
    }
  }
  if (s.caraMottle) {
    if (radialT > 0.55) {
      return colIdx % 2 === 0 ? s.palette.vesicleA : s.palette.vesicleC;
    }
    return s.palette.vesicleB;
  }
  if (radialT > 0.55) {
    return colIdx % 3 === 0 ? s.palette.vesicleC : s.palette.vesicleA;
  }
  return colIdx % 2 === 0 ? s.palette.vesicleB : s.palette.vesicleA;
}

function drawLoculeWallDetail(s, seg, sliceIdx) {
  let aStart = seg.a1 + seg.padOuter;
  let aEnd = seg.a2 - seg.padOuter;
  if (aEnd <= aStart) return;

  // Crisp pigment meniscus where pulp meets the surrounding pith membrane
  brush.set("cpencil", s.palette.vesicleC, 0.24);
  brush.beginShape(0.28);
  for (let m = 0; m <= 6; m++) {
    let t = m / 6;
    let ang = lerp(aStart, aEnd, t);
    let cornerRound = sin(t * 180);
    let rOut =
      getSliceOuterR(s, ang, sliceIdx) -
      s.rindThick -
      s.pithThick -
      (1 - cornerRound) * 3.0;
    brush.vertex(s.cx + rOut * cos(ang), s.cy + rOut * sin(ang));
  }
  brush.endShape(false);
}

function drawRadialSeptaAndColumella(s, sliceIdx) {
  for (let seg of s.segData) {
    let a = seg.a1;
    let rOut = getSliceOuterR(s, a, sliceIdx) - s.rindThick - s.pithThick + 2;
    let rIn = s.coreR * 0.75;

    let x1 = s.cx + rIn * cos(a);
    let y1 = s.cy + rIn * sin(a);
    let x2 = s.cx + rOut * cos(a);
    let y2 = s.cy + rOut * sin(a);

    // Glowing creamy pith membrane spoke
    brush.set("vesicle_glaze", s.palette.pith, 1.35);
    brush.line(x1, y1, x2, y2);

    // Central structural vein inside the septum
    brush.set("2H", s.palette.pithShadow, 0.22);
    brush.line(x1, y1, x2, y2);

    // Bright backlit rim along one side of the membrane
    let perpX = -sin(a) * 1.1;
    let perpY = cos(a) * 1.1;
    brush.set("backlit_spark", "#fffef7", 0.85);
    brush.line(x1 + perpX, y1 + perpY, x2 + perpX, y2 + perpY);
  }

  // Central columella (fibrous pith core)
  brush.noStroke();
  brush.fillBleed(0.08, "out");
  brush.fillTexture(0.3, 0.2);
  brush.fill(s.palette.pith, 240);
  brush.beginShape(0.35);
  for (let k = 0; k < s.segData.length; k++) {
    let aSeptum = s.segData[k].a1;
    let aMid = s.segData[k].mid;
    let rStarOut = s.coreR + 3.2;
    let rStarIn = s.coreR - 1.5;
    brush.vertex(
      s.cx + rStarOut * cos(aSeptum),
      s.cy + rStarOut * sin(aSeptum)
    );
    brush.vertex(s.cx + rStarIn * cos(aMid), s.cy + rStarIn * sin(aMid));
  }
  brush.endShape(true);

  // If tangerine (hollow core), paint the small shadowy central cavity
  if (s.hollowCore) {
    brush.fill("#8c7d6a", 180);
    brush.circle(s.cx, s.cy, s.coreR * 0.48, 0.22);
  }
  brush.noFill();

  // Tiny vascular bundle dots arranged in a ring inside the central core
  for (let k = 0; k < s.segData.length; k++) {
    let aDot = s.segData[k].a1 + random(-3, 3);
    let rDot = s.coreR * 0.68;
    let dx = s.cx + rDot * cos(aDot);
    let dy = s.cy + rDot * sin(aDot);
    brush.set("rotring", s.palette.rindInner, 0.28);
    brush.line(dx, dy, dx + 0.7, dy + 0.7);
  }

  // If Navel orange, draw the small embryonic secondary whorl
  if (s.navel) {
    let na = s.segData[0].mid;
    let nx = s.cx + (s.coreR + 5) * cos(na);
    let ny = s.cy + (s.coreR + 5) * sin(na);
    brush.set("cpencil", s.palette.rindInner, 0.35);
    brush.circle(nx, ny, 4.5, 0.15);
    brush.set("backlit_spark", "#fffdf5", 0.75);
    brush.circle(nx, ny, 6.2, 0.12);
  }
}

function drawSeedCrossSection(s, seg, isSubmerged) {
  let sx = s.cx + seg.seedR * cos(seg.seedAngle);
  let sy = s.cy + seg.seedR * sin(seg.seedAngle);
  let dir = seg.seedAngle; // pointed tip faces inward toward center
  let L = seg.seedLen;
  let W = seg.seedWid;

  let ux = cos(dir);
  let uy = sin(dir);
  let px = -uy;
  let py = ux;

  if (isSubmerged) {
    // Soft blurry dark olive-umber silhouette beneath the translucent vesicles
    brush.noStroke();
    brush.fillBleed(0.25, "out");
    brush.fill("#52452c", 95);
    brush.beginShape(0.35);
    brush.vertex(sx - ux * L * 0.55, sy - uy * L * 0.55);
    brush.vertex(
      sx - ux * L * 0.05 + px * W * 0.5,
      sy - uy * L * 0.05 + py * W * 0.5
    );
    brush.vertex(sx + ux * L * 0.45, sy + uy * L * 0.45);
    brush.vertex(
      sx - ux * L * 0.05 - px * W * 0.5,
      sy - uy * L * 0.05 - py * W * 0.5
    );
    brush.endShape(true);
    brush.noFill();
    return;
  }

  // Sharp transected seed: outer seed coat (testa) + dense creamy cotyledon interior
  brush.noStroke();
  brush.fillBleed(0.04, "in");
  brush.fill("#f7f2e1", 245);
  brush.beginShape(0.32);
  brush.vertex(sx - ux * L * 0.55, sy - uy * L * 0.55);
  brush.vertex(
    sx + ux * L * 0.08 + px * W * 0.52,
    sy + uy * L * 0.08 + py * W * 0.52
  );
  brush.vertex(sx + ux * L * 0.48, sy + uy * L * 0.48);
  brush.vertex(
    sx + ux * L * 0.08 - px * W * 0.52,
    sy + uy * L * 0.08 - py * W * 0.52
  );
  brush.endShape(true);
  brush.noFill();

  // Seed coat rim (dark olive-brown outer husk)
  brush.set("rotring", "#544329", 0.34);
  brush.beginShape(0.32);
  brush.vertex(sx - ux * L * 0.56, sy - uy * L * 0.56);
  brush.vertex(
    sx + ux * L * 0.08 + px * W * 0.54,
    sy + uy * L * 0.08 + py * W * 0.54
  );
  brush.vertex(sx + ux * L * 0.49, sy + uy * L * 0.49);
  brush.vertex(
    sx + ux * L * 0.08 - px * W * 0.54,
    sy + uy * L * 0.08 - py * W * 0.54
  );
  brush.endShape(true);

  // Subtle cotyledon split line & wet highlight
  brush.set("2H", "#b0a284", 0.2);
  brush.line(
    sx - ux * L * 0.35,
    sy - uy * L * 0.35,
    sx + ux * L * 0.3,
    sy + uy * L * 0.3
  );
  brush.set("backlit_spark", "#ffffff", 0.8);
  brush.line(
    sx + px * W * 0.18,
    sy + py * W * 0.18,
    sx + ux * L * 0.22 + px * W * 0.15,
    sy + uy * L * 0.22 + py * W * 0.15
  );
}

// ============================================================================
// 7. ESCAPED JUICE DROPLETS & WET MENISCUS SHEEN
// ============================================================================
function drawJuiceDropletsAndMeniscus() {
  for (let i = 0; i < SLICES.length; i++) {
    let s = SLICES[i];

    // Glistening wet meniscus arcs hugging the outer rind on the grey board
    for (let m = 0; m < 4; m++) {
      let aStart = random(0, 360);
      let aSpan = random(14, 28);
      brush.set("backlit_spark", "#fffef9", 0.85);
      brush.beginShape(0.3);
      for (let a = aStart; a <= aStart + aSpan; a += 4) {
        let r = getSliceOuterR(s, a, i) + 1.4;
        brush.vertex(s.cx + r * cos(a), s.cy + r * sin(a));
      }
      brush.endShape(false);
    }

    // 4-5 tiny escaped translucent juice droplets on the board around each slice
    let numDrops = 5;
    for (let d = 0; d < numDrops; d++) {
      let ang = s.angle + random(-55, 55) + d * 68;
      let distFromEdge = random(7, 26);
      let rDropPos = getSliceOuterR(s, ang, i) + distFromEdge;
      let dx = s.cx + rDropPos * cos(ang);
      let dy = s.cy + rDropPos * sin(ang);
      let dropR = random(1.8, 4.4);

      // Tinted translucent droplet wash
      brush.noStroke();
      brush.fillBleed(0.05, "in");
      brush.fill(s.palette.washLight, 155);
      brush.circle(dx, dy, dropR, 0.08);
      brush.noFill();

      // Thin shadow crescent on side facing the slice
      brush.set("2H", "#6e6a60", 0.22);
      brush.arc(dx, dy, dropR, ang + 120, ang + 240);

      // Pinpoint caustic highlight on side away from the slice
      let hx = dx + dropR * 0.38 * cos(ang);
      let hy = dy + dropR * 0.38 * sin(ang);
      brush.set("backlit_spark", "#ffffff", 0.9);
      brush.line(hx, hy, hx + 0.8, hy + 0.8);
    }
  }
}

// ============================================================================
// 8. RULED PENCIL ANNOTATIONS, SWATCHES & DIDACTIC METADATA
// ============================================================================
function drawMarginaliaAndAnnotations() {
  brush.noField();

  for (let i = 0; i < SLICES.length; i++) {
    let s = SLICES[i];
    let lb = s.label;

    // Anchor point on the outer perimeter of the degree ring (R = 484)
    let ax = CX + 484 * cos(s.angle);
    let ay = CY + 484 * sin(s.angle);

    // Small target tick at anchor
    brush.set("rotring", "#4f4c45", 0.26);
    brush.circle(ax, ay, 2.2, 0.01);

    // Ruled leader line from degree ring to elbow, then horizontal shelf
    let shelfEndX = lb.align === "left" ? lb.lx + 198 : lb.lx - 198;
    brush.set("2H", "#57544c", 0.24);
    brush.line(ax, ay, lb.elbowX, lb.elbowY);
    brush.line(lb.elbowX, lb.elbowY, shelfEndX, lb.ly);

    // Tiny watercolor pigment swatch square next to the annotation block
    let swX = lb.align === "left" ? lb.lx : lb.lx - 13;
    let swY = lb.ly - 21;
    brush.noStroke();
    brush.fillBleed(0.08, "in");
    brush.fillTexture(0.4, 0.3);
    brush.fill(s.palette.washMid, 195);
    brush.rect(swX, swY, 13, 13, "corner");
    brush.noFill();

    brush.set("rotring", "#4f4c45", 0.22);
    brush.rect(swX, swY, 13, 13, "corner");

    // Text offset past the swatch box
    let tx = lb.align === "left" ? lb.lx + 19 : lb.lx - 19;

    // Line 1 (above shelf): Station numeral, degree & common name
    let headerStr = s.id + ". " + nf(s.deg, 3) + "° " + s.name;
    drawTextBrush(headerStr, tx, lb.ly - 17, 7.2, "#3d3b35", 0.26, lb.align);

    // Line 2 (below shelf): Latin binomial & pigment/locule note
    let subStr = s.latin + " / " + s.note;
    drawTextBrush(subStr, lb.lx, lb.ly + 6, 5.4, "#666259", 0.19, lb.align);
  }

  // Top-left didactic plate title block
  brush.set("2H", "#6b685f", 0.22);
  brush.line(52, 54, 415, 54);
  brush.line(52, 96, 330, 96);
  drawTextBrush(
    "PLATE IV : CHROMATIC CARPOLOGY WHEEL",
    52,
    62,
    8.5,
    "#3d3b35",
    0.28,
    "left"
  );
  drawTextBrush(
    "BACKLIT TRANSVERSE CITRUS SECTIONS (D = 2.0 MM)",
    52,
    79,
    5.8,
    "#636058",
    0.2,
    "left"
  );

  // Top-right optical & complementary specification block
  brush.set("2H", "#6b685f", 0.22);
  brush.line(835, 54, 1148, 54);
  brush.line(885, 96, 1148, 96);
  drawTextBrush(
    "SUB-ILLUMINATED WATERCOLOUR GLAZE",
    1148,
    62,
    7.2,
    "#3d3b35",
    0.24,
    "right"
  );
  drawTextBrush(
    "OPPOSITE CHORDS = COMPLEMENTARY PAIRS",
    1148,
    79,
    5.6,
    "#636058",
    0.19,
    "right"
  );

  // Bottom-center metric scale bar (between Navel and Tangerine callouts)
  let sbX = 485;
  let sbY = 1138;
  let sbW = 230;
  brush.set("rotring", "#4f4c45", 0.24);
  brush.rect(sbX, sbY, sbW, 5, "corner");
  for (let k = 0; k <= 5; k++) {
    let kx = sbX + (k / 5) * sbW;
    brush.line(kx, sbY - 3, kx, sbY + 8);
    drawTextBrush(
      str(k * 10),
      kx,
      sbY - 12,
      5.2,
      "#59564e",
      0.19,
      "center"
    );
    if (k < 5 && k % 2 === 0) {
      brush.line(
        kx,
        sbY + 2.5,
        kx + sbW / 5,
        sbY + 2.5
      );
    }
  }
  drawTextBrush(
    "SCALE IN MILLIMETRES (1 : 1)",
    600,
    1152,
    5.4,
    "#615e56",
    0.19,
    "center"
  );
}

// ============================================================================
// CUSTOM VECTOR PENCIL TYPOGRAPHY ENGINE
// ============================================================================
function drawTextBrush(
  str,
  x,
  y,
  charH,
  col = "#4a4740",
  weight = 0.22,
  align = "left"
) {
  let charW = charH * 0.62;
  let gap = charH * 0.28;
  let step = charW + gap;
  let totalW = str.length * step - gap;

  let startX = x;
  if (align === "center") startX = x - totalW * 0.5;
  else if (align === "right") startX = x - totalW;

  brush.set("rotring", col, weight);
  let upper = str.toUpperCase();

  for (let i = 0; i < upper.length; i++) {
    let ch = upper[i];
    if (ch === " ") continue;
    let strokes = FONT_STROKES[ch];
    if (!strokes) continue;

    let cx = startX + i * step;
    for (let s of strokes) {
      let x1 = cx + (s[0] / 4) * charW;
      let y1 = y + (s[1] / 6) * charH;
      let x2 = cx + (s[2] / 4) * charW;
      let y2 = y + (s[3] / 6) * charH;
      brush.line(x1, y1, x2, y2);
    }
  }
}

// ============================================================================
// HYPERREALISTIC WORN PAPERBACK SPINES AS KENTE CLOTH STRIPS
// Medium: Dense, burnished coloured pencil (p5.js 2.x + p5.brush)
// Canvas: 1200 x 1200 WEBGL
// ============================================================================

const PAL = {
  // Kente Golds (Primary Luminous Accent)
  goldBright: "#F5C547",
  goldRich:   "#DF9B26",
  goldDeep:   "#AD6D11",
  goldPale:   "#FBE39B",

  // Monochrome Anchors: Obsidian, Lamp Black, Warm Charcoal
  blackDeep:  "#121116",
  blackRich:  "#1C1A21",
  charcoal:   "#2D2A34",
  slate:      "#464252",

  // Kente Emeralds
  emeraldDeep: "#0B3B28",
  emeraldRich: "#166343",
  emeraldBright: "#25855C",

  // Kente Crimsons
  crimsonDeep: "#5E1114",
  crimsonRich: "#961F22",
  crimsonBright: "#BF3630",

  // Kente Indigos ("a little indigo")
  indigoDeep:  "#141D3D",
  indigoRich:  "#233366",
  indigoBright: "#384E8A",

  // Aged Paperback Stock, Exposed Cardboard, Laminate & Sun Dust
  boardLight:  "#D6C5A5",
  boardMid:    "#B59F7B",
  boardDark:   "#7D6B4E",
  sticker:     "#EDE4D1",
  stickerOld:  "#D8CBB2",
  laminate:    "#FAF7F0",
  sunBleach:   "#DECBA8",
  woodDark:    "#171210",
  woodMid:     "#2A201B",
  woodHighlight: "#4A372B"
};

let spines = [];

// --- Color Utility Helpers ---
function hexToRgb(hex) {
  let c = hex.replace("#", "");
  if (c.length === 3) {
    c = c[0] + c[0] + c[1] + c[1] + c[2] + c[2];
  }
  let num = parseInt(c, 16);
  return [(num >> 16) & 255, (num >> 8) & 255, num & 255];
}

function rgbToHex(r, g, b) {
  let cl = (v) => Math.max(0, Math.min(255, Math.round(v)));
  return (
    "#" +
    ((1 << 24) + (cl(r) << 16) + (cl(g) << 8) + cl(b))
      .toString(16)
      .slice(1)
  );
}

function mixHex(hex1, hex2, t) {
  let a = constrain(t, 0, 1);
  let c1 = hexToRgb(hex1);
  let c2 = hexToRgb(hex2);
  return rgbToHex(
    c1[0] + (c2[0] - c1[0]) * a,
    c1[1] + (c2[1] - c1[1]) * a,
    c1[2] + (c2[2] - c1[2]) * a
  );
}

function shadeHex(hex, amt) {
  if (amt >= 0) {
    return mixHex(hex, "#FFF9EB", amt);
  } else {
    return mixHex(hex, "#0A090D", -amt);
  }
}

// Applies top-down UV sun-fading and cylindrical across-spine shading
function getBurnishedColor(baseHex, y, topY, sliceShade, spineShadeBias) {
  // Sun fading strongest in top 220px of each spine
  let distFromTop = Math.max(0, y - topY);
  let sunFactor = Math.pow(constrain(1.0 - distFromTop / 230.0, 0, 1), 1.55);

  let col = baseHex;
  if (sunFactor > 0.01) {
    // Bleach pigments toward dusty warm ochre-parchment at the top
    col = mixHex(col, PAL.sunBleach, sunFactor * 0.44);
  }

  let totalShade = sliceShade + spineShadeBias;
  return shadeHex(col, totalShade);
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);

  randomSeed(7819);
  noiseSeed(7819);

  // Custom brushes for waxy coloured pencil burnish & razor-fine laminate fractures
  brush.add("burnish", {
    type: "default",
    weight: 1.6,
    scatter: 0.28,
    sharpness: 0.22,
    grain: 0.35,
    opacity: 72,
    spacing: 0.32,
    pressure: [0.5, 1.25, 0.45],
    noise: 0.35
  });

  brush.add("microcrack", {
    type: "default",
    weight: 0.42,
    scatter: 0.06,
    sharpness: 0.88,
    grain: 0.65,
    opacity: 185,
    spacing: 0.22,
    pressure: [0.35, 1.05, 0.25],
    noise: 0.65
  });

  brush.add("wax_grain", {
    type: "default",
    weight: 0.95,
    scatter: 0.42,
    sharpness: 0.48,
    grain: 0.72,
    opacity: 105,
    spacing: 0.38,
    pressure: [0.6, 1.0, 0.6],
    noise: 0.75
  });

  generateBookshelfData();
}

function generateBookshelfData() {
  spines = [];
  let curX = -14;
  let idx = 0;

  // Kente strip colorway archetypes (Gold accent threading through all)
  const schemes = [
    // 0: Obsidian & Royal Asante Gold with Crimson/Emerald weft
    {
      main: PAL.blackRich,
      sec: PAL.goldRich,
      acc1: PAL.goldBright,
      acc2: PAL.crimsonRich,
      acc3: PAL.emeraldRich,
      dark: PAL.blackDeep
    },
    // 1: Burnished Gold & Charcoal with Emerald & Crimson bands
    {
      main: PAL.goldRich,
      sec: PAL.blackRich,
      acc1: PAL.goldBright,
      acc2: PAL.emeraldDeep,
      acc3: PAL.crimsonRich,
      dark: PAL.charcoal
    },
    // 2: Deep Emerald, Gold & Black weave
    {
      main: PAL.emeraldDeep,
      sec: PAL.goldBright,
      acc1: PAL.emeraldRich,
      acc2: PAL.blackRich,
      acc3: PAL.crimsonRich,
      dark: PAL.blackDeep
    },
    // 3: Crimson, Gold & Obsidian strip
    {
      main: PAL.crimsonRich,
      sec: PAL.goldBright,
      acc1: PAL.blackRich,
      acc2: PAL.goldRich,
      acc3: PAL.indigoDeep,
      dark: PAL.crimsonDeep
    },
    // 4: Charcoal-Black & Gold Monochrome with touch of Indigo
    {
      main: PAL.charcoal,
      sec: PAL.goldBright,
      acc1: PAL.blackDeep,
      acc2: PAL.indigoRich,
      acc3: PAL.goldRich,
      dark: PAL.blackDeep
    },
    // 5: Indigo, Gold & Black Ewe strip
    {
      main: PAL.indigoDeep,
      sec: PAL.goldBright,
      acc1: PAL.indigoRich,
      acc2: PAL.blackRich,
      acc3: PAL.crimsonBright,
      dark: PAL.blackDeep
    }
  ];

  // Rhythmic scheme sequence so gold & black anchor the weave
  const schemeOrder = [0, 1, 2, 0, 3, 4, 1, 5, 0, 2, 1, 3, 0, 4, 2, 1, 3, 5, 0, 1, 4, 2, 3, 0, 1, 2, 4];

  while (curX < 1214) {
    let w = Math.round(random(38, 64));
    if (curX + w > 1218) w = 1218 - curX;
    if (w < 30) w = 34;

    // Staggered book heights evoking stitched Kente strips
    let waveOffset = Math.sin(idx * 0.85) * 22 + Math.cos(idx * 1.7) * 14;
    let topY = Math.round(constrain(108 + waveOffset + random(-14, 14), 68, 152));
    let botY = Math.round(1092 + random(-5, 7));

    let scheme = schemes[schemeOrder[idx % schemeOrder.length]];
    let protrusion = random(0, 1); // Forward pull on the shelf
    let shadeBias = map(protrusion, 0, 1, -0.07, 0.05);

    // Staggered phase for horizontal Kente weft bands
    let bandShift = (idx % 3 === 0) ? -28 : (idx % 3 === 1 ? 18 : -6);
    bandShift += Math.round(random(-12, 12));

    let blocks = buildSpineBlocks(topY, botY, w, scheme, bandShift, idx);
    let cracks = buildSpineCracks(topY, botY, w);
    let frays = buildLaminateFrays(topY, botY, w);
    let sticker = buildSticker(topY, botY, w, idx, scheme);

    spines.push({
      idx,
      x: curX,
      w,
      topY,
      botY,
      scheme,
      protrusion,
      shadeBias,
      blocks,
      cracks,
      frays,
      sticker
    });

    curX += w;
    idx++;
  }
}

function buildSpineBlocks(topY, botY, w, sc, bandShift, spineIdx) {
  let blocks = [];
  let totalH = botY - topY;

  // Define staggered Kente rhythmic template proportions
  // Alternates between broad field blocks and tight compound weft stripe clusters
  let cursor = topY;

  // 1. Top Header Band (often sun-faded series crown)
  let h1 = constrain(Math.round(52 + bandShift * 0.5 + random(-8, 10)), 34, 78);
  blocks.push(makeBlock(cursor, h1, sc.main, "solid_with_bar", sc));
  cursor += h1;

  // 2. Upper Kente Weft Cluster ("Aban" multi-stripe)
  let cluster1H = addWeftCluster(blocks, cursor, sc, 1, spineIdx);
  cursor += cluster1H;

  // 3. Upper-Mid Title / Geometric Cartouche Block
  let h2 = constrain(Math.round(totalH * 0.21 + bandShift * 0.6 + random(-15, 15)), 135, 225);
  let pat2 = (spineIdx % 2 === 0) ? "cartouche" : "split_vertical";
  blocks.push(makeBlock(cursor, h2, sc.sec, pat2, sc));
  cursor += h2;

  // 4. Mid Kente Weft Cluster (staggered checker / triple bars)
  let cluster2H = addWeftCluster(blocks, cursor, sc, 2, spineIdx);
  cursor += cluster2H;

  // 5. Center Belly Block (Deep anchor block with geometric inlay)
  let h3 = constrain(Math.round(totalH * 0.22 - bandShift * 0.4 + random(-14, 16)), 140, 235);
  let pat3 = (spineIdx % 3 === 0) ? "kente_grid" : (spineIdx % 3 === 1 ? "abstract_rects" : "twin_columns");
  blocks.push(makeBlock(cursor, h3, sc.dark, pat3, sc));
  cursor += h3;

  // 6. Lower-Mid Weft Cluster
  let cluster3H = addWeftCluster(blocks, cursor, sc, 3, spineIdx);
  cursor += cluster3H;

  // 7. Lower Field Block
  let remaining = botY - cursor;
  let footClusterH = 66 + (spineIdx % 3) * 14;
  let h4 = Math.max(48, remaining - footClusterH);
  let col4 = (spineIdx % 2 === 0) ? sc.acc2 : sc.main;
  blocks.push(makeBlock(cursor, h4, col4, "abstract_rects", sc));
  cursor += h4;

  // 8. Foot Tail Band (Publisher colophon zone down to botY)
  let tailRem = botY - cursor;
  if (tailRem > 28) {
    let stripA = Math.round(tailRem * 0.28);
    let stripB = Math.round(tailRem * 0.22);
    let stripC = tailRem - stripA - stripB;
    blocks.push(makeBlock(cursor, stripA, sc.acc1, "weft_ticks", sc));
    blocks.push(makeBlock(cursor + stripA, stripB, sc.dark, "plain", sc));
    blocks.push(makeBlock(cursor + stripA + stripB, stripC, sc.main, "colophon_box", sc));
  } else if (tailRem > 0) {
    blocks.push(makeBlock(cursor, tailRem, sc.dark, "plain", sc));
  }

  return blocks;
}

function makeBlock(y, h, color, pattern, sc) {
  return {
    y,
    h: Math.max(4, h),
    color,
    pattern,
    acc1: sc.acc1,
    acc2: sc.acc2,
    acc3: sc.acc3,
    sec: sc.sec,
    dark: sc.dark
  };
}

function addWeftCluster(blocks, startY, sc, variant, spineIdx) {
  let cur = startY;
  let bands = [];

  if (variant === 1) {
    bands = [
      { h: 9, c: sc.acc1, p: "plain" },
      { h: 7, c: sc.dark, p: "plain" },
      { h: 16, c: sc.acc2, p: (spineIdx % 2 === 0) ? "weft_ticks" : "plain" },
      { h: 7, c: sc.dark, p: "plain" },
      { h: 10, c: sc.acc1, p: "plain" },
      { h: 8, c: sc.acc3, p: "plain" }
    ];
  } else if (variant === 2) {
    bands = [
      { h: 8, c: sc.dark, p: "plain" },
      { h: 11, c: sc.acc1, p: "plain" },
      { h: 22, c: sc.acc3, p: "checker_band" },
      { h: 11, c: sc.acc1, p: "plain" },
      { h: 8, c: sc.dark, p: "plain" },
      { h: 12, c: sc.acc2, p: "weft_ticks" },
      { h: 8, c: sc.acc1, p: "plain" }
    ];
  } else {
    bands = [
      { h: 10, c: sc.acc1, p: "plain" },
      { h: 8, c: sc.dark, p: "plain" },
      { h: 14, c: sc.sec, p: "weft_ticks" },
      { h: 8, c: sc.dark, p: "plain" },
      { h: 14, c: sc.acc2, p: "plain" },
      { h: 9, c: sc.acc1, p: "plain" }
    ];
  }

  for (let b of bands) {
    let bh = Math.max(5, b.h + Math.round(random(-1, 2)));
    blocks.push(makeBlock(cur, bh, b.c, b.p, sc));
    cur += bh;
  }
  return cur - startY;
}

function buildSpineCracks(topY, botY, w) {
  let numCracks = w > 52 ? Math.floor(random(2, 4.6)) : Math.floor(random(1, 3.2));
  let cracks = [];
  for (let i = 0; i < numCracks; i++) {
    let frac = map(i + 0.5, 0, numCracks, 0.2, 0.8) + random(-0.07, 0.07);
    let baseX = constrain(frac, 0.16, 0.84) * w;
    let startY = topY + (random() < 0.65 ? 2 : random(30, 220));
    let endY = botY - (random() < 0.65 ? 2 : random(30, 220));
    let pts = [];
    let steps = Math.floor((endY - startY) / 22);
    let curOffset = 0;
    for (let s = 0; s <= steps; s++) {
      let py = startY + (s / steps) * (endY - startY);
      curOffset = constrain(curOffset + random(-1.1, 1.1), -2.8, 2.8);
      pts.push({ dx: baseX + curOffset, y: py, strength: random(0.45, 1.0) });
    }
    cracks.push(pts);
  }
  return cracks;
}

function buildLaminateFrays(topY, botY, w) {
  let frays = [];
  let count = Math.floor(random(4, 8));
  for (let i = 0; i < count; i++) {
    let side = random() < 0.5 ? "left" : "right";
    let fy = random(topY + 18, botY - 35);
    let fh = random(18, 56);
    let fw = random(4, Math.min(13, w * 0.26));
    frays.push({ side, y: fy, h: fh, w: fw });
  }
  return frays;
}

function buildSticker(topY, botY, w, idx, sc) {
  if (random() > 0.74) return null;
  let kind = idx % 4; // 0: rectangular price tag, 1: library band, 2: round dot, 3: peeled ghost
  let sy = (kind === 1)
    ? botY - random(78, 125)
    : (random() < 0.72 ? botY - random(90, 250) : topY + random(90, 210));
  let sw = (kind === 1) ? w * 0.78 : constrain(w * random(0.52, 0.72), 20, 44);
  let sh = (kind === 0) ? random(16, 26) : (kind === 1 ? random(24, 34) : random(18, 28));
  let sx = (w - sw) * 0.5 + random(-3, 3);
  let tilt = random(-2.2, 2.2);
  let dogEar = random() < 0.65 ? (random() < 0.5 ? "tr" : "bl") : "none";
  let barCol = (idx % 2 === 0) ? PAL.crimsonRich : ((idx % 3 === 0) ? PAL.indigoRich : PAL.goldDeep);

  return { kind, dx: sx, y: sy, w: sw, h: sh, tilt, dogEar, barCol };
}

// ============================================================================
// MAIN DRAW PASS
// ============================================================================
function draw() {
  translate(-width / 2, -height / 2);
  background(PAL.blackDeep);

  // Ensure a brush is always active before any operation
  brush.set("cpencil", PAL.blackDeep, 1);

  // 1. Draw Upper Shelf Overhang & Deep Shadow Recess (y = 0 to 165)
  drawUpperShelfAndRecess();

  // 2. Draw Recessed Book Page Blocks & Headcaps above each spine
  drawBookTopEdges();

  // 3. Render Each Paperback Spine Strip (Base Cylindrical Washes + Woven Hatching)
  for (let i = 0; i < spines.length; i++) {
    drawSpineBaseAndBlocks(spines[i], i);
  }

  // 4. Render Coloured Pencil Burnishing, Creased Spine Cracks, Frayed Laminate & Stickers
  for (let i = 0; i < spines.length; i++) {
    drawSpineSurfaceRealism(spines[i], i);
  }

  // 5. Draw Deep Stitched Crevices & Cast Shadows Between Spines
  drawInterSpineSeams();

  // 6. Draw Worn Wooden Shelf Ledge & Lower Shelf Book Tops (y = 1090 to 1200)
  drawBottomShelfAndLowerRow();

  noLoop();
}

// ============================================================================
// 1. UPPER SHELF & SHADOW RECESS
// ============================================================================
function drawUpperShelfAndRecess() {
  brush.noField();

  // Dark recess wash behind book tops
  brush.noStroke();
  brush.wash("#0B0A0E", 255);
  brush.rect(0, 0, 1200, 175);
  brush.noWash();

  // Upper wooden shelf underside lip (y = 0 to 28)
  brush.noStroke();
  brush.wash(PAL.woodDark, 250);
  brush.rect(0, 0, 1200, 28);
  brush.wash(PAL.woodMid, 180);
  brush.rect(0, 18, 1200, 10);
  brush.noWash();

  // Horizontal wood grain coloured pencil strokes along upper shelf lip
  for (let y = 3; y <= 27; y += 3) {
    let col = (y > 18) ? PAL.woodHighlight : "#211915";
    brush.set("cpencil", col, 0.8);
    brush.line(0, y + random(-0.5, 0.5), 1200, y + random(-0.5, 0.5));
  }

  // Dense charcoal shading inside the shelf recess
  brush.hatchStyle("charcoal", "#09080C", 0.9);
  brush.hatch(6, 8, { rand: 0.1 });
  brush.noStroke();
  brush.rect(0, 26, 1200, 130);
  brush.noHatch();
}

// ============================================================================
// 2. BOOK TOP EDGES & DUSTY PAGE BLOCKS IN RECESS
// ============================================================================
function drawBookTopEdges() {
  for (let i = 0; i < spines.length; i++) {
    let sp = spines[i];
    let x = sp.x;
    let w = sp.w;
    let ty = sp.topY;
    let recessH = Math.min(44, ty - 28);
    if (recessH <= 6) continue;

    let topBackY = ty - recessH;

    // Dusty receding page block between cover boards
    let pageCol = shadeHex(PAL.boardMid, -0.38 + sp.shadeBias);
    let pageDeep = shadeHex(PAL.boardDark, -0.58);

    brush.noStroke();
    brush.wash(pageDeep, 245);
    brush.rect(x + 3, topBackY, Math.max(4, w - 6), recessH * 0.55);
    brush.wash(pageCol, 245);
    brush.rect(x + 3, topBackY + recessH * 0.45, Math.max(4, w - 6), recessH * 0.55 + 2);
    brush.noWash();

    // Vertical compressed page-edge striations in pencil
    let step = Math.max(2.5, w / 12);
    for (let px = x + 4; px < x + w - 4; px += step) {
      let pCol = ( random() < 0.5 ) ? "#4A3F31" : "#6B5C47";
      brush.set("2B", pCol, 0.55);
      brush.line(px, ty - 1, px + 3, topBackY + 4);
    }

    // Left and right cover board edges sticking slightly above page block
    let boardEdgeCol = getBurnishedColor(sp.scheme.main, ty, ty, -0.15, sp.shadeBias);
    brush.set("cpencil", boardEdgeCol, 0.9);
    brush.line(x + 1.5, ty + 2, x + 4, topBackY + 3);
    brush.line(x + w - 1.5, ty + 2, x + w - 4, topBackY + 3);

    // Concave dark shadow right behind the spine headcap lip
    brush.set("charcoal", "#121016", 0.75);
    brush.line(x + 3, ty - 2, x + w - 3, ty - 2);
  }
}

// ============================================================================
// 3. SPINE BASE CYLINDRICAL WASHES, INLAY BLOCKS & WOVEN HATCHING
// ============================================================================
function drawSpineBaseAndBlocks(sp, idx) {
  let x = sp.x;
  let w = sp.w;
  let ty = sp.topY;

  // 5 cylindrical shading slices across each spine width:
  // [left seam shadow, left-center convex highlight, mid local, right roll, right seam shadow]
  const sliceFracs = [0.0, 0.13, 0.38, 0.68, 0.85, 1.0];
  const sliceShades = [-0.28, +0.15, +0.02, -0.12, -0.32];

  // Check if left/right neighbor protrudes further forward and casts a shadow
  let leftCast = (idx > 0 && spines[idx - 1].protrusion > sp.protrusion + 0.15) ? -0.14 : 0;
  let rightCast = (idx < spines.length - 1 && spines[idx + 1].protrusion > sp.protrusion + 0.15) ? -0.12 : 0;

  for (let b of sp.blocks) {
    let by = b.y;
    let bh = b.h;
    if (bh <= 1) continue;

    // A. Draw 5 cylindrical vertical sub-slices with sun-faded wash
    brush.noStroke();
    for (let s = 0; s < 5; s++) {
      let sx = x + w * sliceFracs[s];
      let sw = w * (sliceFracs[s + 1] - sliceFracs[s]) + 0.8;
      let extraCast = (s === 0) ? leftCast : (s === 4 ? rightCast : 0);
      let c = getBurnishedColor(b.color, by + bh * 0.5, ty, sliceShades[s] + extraCast, sp.shadeBias);
      brush.wash(c, 248);
      brush.rect(sx, by, Math.max(1.5, sw), bh + 0.6);
    }
    brush.noWash();

    // B. Draw Kente / Abstract Paperback Geometric Sub-Rectangles (No Text!)
    drawBlockPattern(x, by, w, bh, b, sp);

    // C. Woven Coloured-Pencil Hatching over the block
    // Alternate vertical warp hatch on tall blocks and horizontal weft hatch on narrow bands
    let isWeftBand = bh < 34;
    let hatchAngle = isWeftBand ? random(-1.5, 1.5) : 90 + random(-1.5, 1.5);
    let hatchDist = isWeftBand ? 3.2 : 4.2;
    let hatchCol = getBurnishedColor(
      shadeHex(b.color, isWeftBand ? 0.1 : -0.12),
      by + bh * 0.5,
      ty,
      0,
      sp.shadeBias
    );

    if (w > 6 && bh > 5) {
      brush.hatchStyle("cpencil", hatchCol, 0.62);
      brush.hatch(hatchDist, hatchAngle, { rand: 0.07 });
      brush.noStroke();
      brush.rect(x + 1.5, by + 0.5, Math.max(3, w - 3), Math.max(3, bh - 1));
      brush.noHatch();
    }

    // Crisp coloured-pencil seam line at the horizontal band boundary
    let seamCol = getBurnishedColor(shadeHex(b.color, -0.25), by, ty, 0, sp.shadeBias);
    brush.set("cpencil", seamCol, 0.55);
    brush.line(x + 1.5, by, x + w - 1.5, by);
  }
}

// Renders pure geometric rectangles & Kente inlays inside spine blocks (no readable text)
function drawBlockPattern(x, y, w, h, b, sp) {
  let ty = sp.topY;
  let pat = b.pattern;
  if (pat === "plain") return;

  let paintRect = (rx, ry, rw, rh, hexCol, shadeOffset = 0) => {
    if (rw < 2 || rh < 2) return;
    // Split inner rectangle into 2 tonal halves (left highlight, right mid-shadow) so it curves with the spine
    let wLeft = rw * 0.45;
    let wRight = rw - wLeft;
    let c1 = getBurnishedColor(hexCol, ry + rh * 0.5, ty, 0.11 + shadeOffset, sp.shadeBias);
    let c2 = getBurnishedColor(hexCol, ry + rh * 0.5, ty, -0.09 + shadeOffset, sp.shadeBias);
    brush.noStroke();
    brush.wash(c1, 245);
    brush.rect(rx, ry, Math.max(1.5, wLeft + 0.5), rh);
    brush.wash(c2, 245);
    brush.rect(rx + wLeft, ry, Math.max(1.5, wRight), rh);
    brush.noWash();
  };

  if (pat === "weft_ticks") {
    // Alternating vertical Kente weft teeth ("ntomaban") across the horizontal stripe
    let step = Math.max(5, Math.round(w / 7));
    let tickCol = (b.color === b.acc1) ? b.dark : b.acc1;
    for (let tx = x + 4; tx < x + w - 5; tx += step * 2) {
      paintRect(tx, y + 1.5, Math.min(step, x + w - 3 - tx), Math.max(2, h - 3), tickCol);
    }
  } else if (pat === "checker_band") {
    // Two-row staggered Kente checkerboard band
    let cols = Math.max(4, Math.floor(w / 8));
    let cw = (w - 6) / cols;
    let ch = Math.max(2.5, (h - 2) / 2);
    for (let r = 0; r < 2; r++) {
      for (let c = 0; c < cols; c++) {
        if ((r + c) % 2 === 0) {
          paintRect(x + 3 + c * cw, y + 1 + r * ch, cw + 0.3, ch + 0.3, b.acc1);
        }
      }
    }
  } else if (pat === "solid_with_bar") {
    // Abstract rectangular crown bar inside top block
    let padX = w * 0.16;
    let barH = Math.min(14, h * 0.32);
    paintRect(x + padX, y + h * 0.36, w - padX * 2, barH, b.acc1);
    if (h > 48) {
      paintRect(x + padX * 1.3, y + h * 0.36 + barH + 5, w - padX * 2.6, Math.max(4, barH * 0.5), b.acc2);
    }
  } else if (pat === "cartouche") {
    // Framed modernist paperback / Kente cartouche with stacked geometric colour blocks
    let mx = x + w * 0.14;
    let mw = w * 0.72;
    let my = y + h * 0.12;
    let mh = h * 0.76;
    paintRect(mx, my, mw, mh, b.dark);
    paintRect(mx + 3, my + 3, mw - 6, mh - 6, b.color, -0.04);

    // Abstract colour rectangles inside cartouche (evoking woven blocks / title geometry)
    let inX = mx + 6;
    let inW = mw - 12;
    paintRect(inX, my + mh * 0.14, inW, mh * 0.16, b.acc1);
    paintRect(inX, my + mh * 0.36, inW * 0.65, mh * 0.11, b.acc3);
    paintRect(inX + inW * 0.7, my + mh * 0.36, inW * 0.3, mh * 0.11, b.acc2);
    paintRect(inX, my + mh * 0.54, inW, mh * 0.24, b.dark);
    paintRect(inX + 3, my + mh * 0.60, inW - 6, mh * 0.12, b.acc1);
  } else if (pat === "split_vertical") {
    // Kente twin-warp split block with central geometric bridge
    let halfW = (w - 6) * 0.5;
    paintRect(x + 3, y + 6, halfW, h - 12, b.acc2);
    paintRect(x + 3 + halfW, y + 6, halfW, h - 12, b.dark);
    // Horizontal golden bridge bars across the split
    let bridgeY = y + h * 0.32;
    paintRect(x + 6, bridgeY, w - 12, 12, b.acc1);
    paintRect(x + 6, bridgeY + 18, w - 12, 8, b.acc3);
    paintRect(x + 6, bridgeY + 32, w - 12, 12, b.acc1);
  } else if (pat === "kente_grid") {
    // Tapestry grid of staggered colour blocks ("Adweneasa" motif)
    let marginX = w * 0.15;
    let gw = w - marginX * 2;
    let gy = y + h * 0.12;
    let gh = h * 0.76;
    let rows = 5;
    let cols = 2;
    let cellW = gw / cols;
    let cellH = gh / rows;
    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        let cellCol = ((r + c) % 2 === 0) ? b.acc1 : ((r % 2 === 0) ? b.acc2 : b.acc3);
        paintRect(
          x + marginX + c * cellW + 1,
          gy + r * cellH + 1,
          cellW - 2,
          cellH - 2,
          cellCol
        );
      }
    }
  } else if (pat === "twin_columns") {
    // Vertical warp bars with staggered horizontal ticks
    let colW = (w - 10) / 3;
    paintRect(x + 5, y + 10, colW - 1, h - 20, b.acc1);
    paintRect(x + 5 + colW, y + 10, colW - 1, h - 20, b.acc2);
    paintRect(x + 5 + colW * 2, y + 10, colW - 1, h - 20, b.acc1);
    // Central dark band interrupting the bars
    paintRect(x + 4, y + h * 0.42, w - 8, h * 0.16, b.dark);
    paintRect(x + 7, y + h * 0.47, w - 14, h * 0.06, b.acc3);
  } else if (pat === "abstract_rects") {
    // Clean modernist abstract rectangles of colour (replacing text blocks)
    let pad = w * 0.16;
    let rw = w - pad * 2;
    paintRect(x + pad, y + h * 0.16, rw, Math.min(18, h * 0.14), b.acc1);
    paintRect(x + pad, y + h * 0.35, rw * 0.75, Math.min(11, h * 0.09), b.sec);
    paintRect(x + pad, y + h * 0.50, rw * 0.9, Math.min(11, h * 0.09), b.acc2);
    if (h > 110) {
      paintRect(x + pad, y + h * 0.68, rw, Math.min(22, h * 0.16), b.dark);
      paintRect(x + pad + 4, y + h * 0.72, rw - 8, Math.min(10, h * 0.08), b.acc1);
    }
  } else if (pat === "colophon_box") {
    // Small publisher emblem rectangle near foot of spine
    let bw = Math.min(22, w * 0.46);
    let bh = Math.min(24, h * 0.58);
    let bx = x + (w - bw) * 0.5;
    let by = y + (h - bh) * 0.5;
    paintRect(bx, by, bw, bh, b.acc1);
    paintRect(bx + 3, by + 3, bw - 6, bh - 6, b.dark);
    paintRect(bx + 6, by + 6, bw - 12, bh - 12, b.acc2);
  }
}

// ============================================================================
// 4. COLOURED PENCIL BURNISHING, SPINE CRACKS, FRAYED LAMINATE & STICKERS
// ============================================================================
function drawSpineSurfaceRealism(sp, idx) {
  let x = sp.x;
  let w = sp.w;
  let ty = sp.topY;
  let by = sp.botY;

  // A. Waxy Coloured-Pencil Burnish Highlight along the convex spine ridge (x + 0.25*w)
  let ridgeX = x + w * 0.26;
  for (let pass = 0; pass < 4; pass++) {
    let px = ridgeX + (pass - 1.5) * (w * 0.045);
    let burnCol = (pass === 1 || pass === 2) ? PAL.goldPale : "#FFF8E8";
    brush.set("burnish", burnCol, 0.78);
    brush.line(px, ty + 6, px, by - 6);
  }

  // B. Sun-Bleached Dusty Coloured-Pencil Glaze across the top 190px of each spine
  let sunZoneH = 185;
  for (let sy = ty + 2; sy < ty + sunZoneH; sy += 6.5) {
    let t = (sy - ty) / sunZoneH;
    let weight = map(t, 0, 1, 0.95, 0.25);
    let dustCol = (t < 0.35) ? "#EFE3C8" : PAL.sunBleach;
    brush.set("burnish", dustCol, weight);
    brush.line(x + 2, sy + random(-1, 1), x + w - 2, sy + random(-1, 1));
  }

  // C. Deep Cylindrical Edge Shading in 2B & Coloured Pencil along Left & Right Spine Turn
  for (let k = 0; k < 3; k++) {
    let lx = x + 1.2 + k * 1.7;
    let rx = x + w - 1.2 - k * 1.7;
    let wgt = map(k, 0, 2, 0.95, 0.45);
    brush.set("2B", PAL.blackDeep, wgt);
    brush.line(lx, ty + 2, lx, by - 2);
    brush.line(rx, ty + 2, rx, by - 2);
  }

  // D. Creased Vertical Spine Cracks (Reading Creases in Cardstock & Ink)
  for (let crack of sp.cracks) {
    for (let i = 0; i < crack.length - 1; i++) {
      let p1 = crack[i];
      let p2 = crack[i + 1];
      let cx1 = x + p1.dx;
      let cx2 = x + p2.dx;

      // Dark hairline indentation shadow on left of crease
      brush.set("microcrack", "#16131A", 0.75 * p1.strength);
      brush.line(cx1 - 0.9, p1.y, cx2 - 0.9, p2.y);

      // Exposed fibrous buff/cream paper core along the split ink
      let fiberCol = (p1.y - ty < 160) ? "#F5EEDF" : PAL.boardLight;
      brush.set("microcrack", fiberCol, 0.92 * p1.strength);
      brush.line(cx1, p1.y, cx2, p2.y);

      // Occasional tiny diagonal stress crow's-feet branching off the reading crease
      if (random() < 0.28) {
        let dir = random() < 0.5 ? -1 : 1;
        brush.set("microcrack", fiberCol, 0.65);
        brush.line(cx1, p1.y, cx1 + dir * random(2.5, 5.5), p1.y + random(3, 7));
      }
    }
  }

  // E. Frayed Laminate (Peeling Cellophane Film & Delaminated Air Blisters)
  for (let fr of sp.frays) {
    let isLeft = fr.side === "left";
    let edgeX = isLeft ? x + 0.8 : x + w - 0.8;
    let innerX = isLeft ? edgeX + fr.w : edgeX - fr.w;
    let midY = fr.y + fr.h * 0.5;

    // Milky translucent air pocket under lifted film (diagonal fine strokes)
    let steps = Math.max(3, Math.floor(fr.h / 4.5));
    for (let s = 0; s <= steps; s++) {
      let t = s / steps;
      let py = fr.y + t * fr.h;
      let span = Math.sin(t * 180) * fr.w;
      let targetX = isLeft ? edgeX + span : edgeX - span;
      brush.set("microcrack", "#F7F3E8", 0.55);
      brush.line(edgeX, py, targetX, py + (isLeft ? 2 : -2));
    }

    // Crisp silvery-white peel boundary line + micro shadow underneath lifted film
    brush.set("microcrack", "#1A1720", 0.6);
    brush.line(edgeX, fr.y, innerX + (isLeft ? 0.8 : -0.8), midY);
    brush.line(innerX + (isLeft ? 0.8 : -0.8), midY, edgeX, fr.y + fr.h);

    brush.set("microcrack", "#FFFDF9", 0.95);
    brush.line(edgeX, fr.y, innerX, midY);
    brush.line(innerX, midY, edgeX, fr.y + fr.h);
  }

  // F. Battered Headcap & Frayed Cardboard at Top & Bottom of Spine
  drawWornHeadAndTail(sp);

  // G. Tiny Bookstore / Library Stickers (or Peeled Sticker Ghost)
  if (sp.sticker) {
    drawSpineSticker(sp, sp.sticker);
  }
}

function drawWornHeadAndTail(sp) {
  let x = sp.x;
  let w = sp.w;
  let ty = sp.topY;
  let by = sp.botY;

  // Exposed raw cardboard chips at top corners and central pull-notch
  brush.noStroke();
  brush.wash(PAL.boardMid, 240);
  brush.rect(x + 1, ty, 6, 4.5);
  brush.rect(x + w - 7, ty, 6, 4.5);
  brush.wash(PAL.boardLight, 235);
  brush.rect(x + w * 0.32, ty, w * 0.36, 3.2);
  brush.noWash();

  // Fibrous cardboard layers and frayed laminate threads at the headcap
  for (let i = 0; i < 7; i++) {
    let fx = x + 2 + (i / 6) * (w - 4);
    let c = (i % 2 === 0) ? PAL.boardLight : PAL.boardDark;
    brush.set("microcrack", c, 0.85);
    brush.line(fx, ty, fx + random(-3, 3), ty + random(2.5, 6.5));
  }
  // Peeling laminate highlight just below the frayed top edge
  brush.set("microcrack", "#FFFDF8", 0.9);
  brush.line(x + 3, ty + 4.2, x + w * 0.45, ty + 5.8);
  brush.line(x + w * 0.52, ty + 4.8, x + w - 3, ty + 3.8);

  // Scuffed cardboard wear along bottom shelf edge (botY)
  for (let i = 0; i < 6; i++) {
    let bx = x + 2 + (i / 5) * (w - 4);
    brush.set("microcrack", PAL.boardMid, 0.8);
    brush.line(bx, by, bx + random(-2.5, 2.5), by - random(2, 5));
  }
}

function drawSpineSticker(sp, st) {
  let sx = sp.x + st.dx;
  let sy = st.y;
  let sw = st.w;
  let sh = st.h;

  if (st.kind === 3) {
    // Peeled sticker ghost: sticky yellowed residue + torn white paper corner scrap
    brush.hatchStyle("cpencil", "#B8A684", 0.65);
    brush.hatch(3.2, 22, { rand: 0.15 });
    brush.noStroke();
    brush.rect(sx, sy, sw, sh);
    brush.noHatch();

    brush.set("microcrack", "#6E5F47", 0.65);
    brush.rect(sx, sy, sw, sh);

    // Torn white corner remnant still stuck to spine
    brush.noStroke();
    brush.wash(PAL.sticker, 245);
    brush.rect(sx + 1, sy + 1, sw * 0.38, sh * 0.45);
    brush.noWash();
    brush.set("microcrack", "#FFFDF9", 0.85);
    brush.line(sx + 1, sy + sh * 0.45, sx + sw * 0.38, sy + 1);
    return;
  }

  if (st.kind === 2) {
    // Tiny circular color-coded inventory dot sticker
    let r = Math.min(sw, sh) * 0.36;
    let cx = sp.x + sp.w * 0.5 + random(-3, 3);
    let cy = sy + sh * 0.5;

    // Micro drop shadow
    brush.noStroke();
    brush.wash("#121015", 220);
    brush.circle(cx + 1.2, cy + 1.4, r, 0.05);

    // Aged paper rim + inner coloured dot
    brush.wash(PAL.sticker, 250);
    brush.circle(cx, cy, r, 0.05);
    brush.wash(st.barCol, 240);
    brush.circle(cx, cy, Math.max(2, r - 2.2), 0.05);
    brush.noWash();

    // Burnished pencil highlight on sticker
    brush.set("microcrack", "#FFFDF8", 0.8);
    brush.arc(cx, cy, r, 200, 320);
    return;
  }

  // Rectangular Bookstore Tag (kind 0) or Library Classification Band (kind 1)
  push();
  translate(sx + sw * 0.5, sy + sh * 0.5);
  rotate(st.tilt);
  translate(-sw * 0.5, -sh * 0.5);

  // 1. Cast shadow under sticker
  brush.noStroke();
  brush.wash("#0E0C12", 225);
  brush.rect(1.4, 1.8, sw, sh);

  // 2. Aged cream sticker paper body (shaded slightly at edges)
  brush.wash(PAL.stickerOld, 250);
  brush.rect(0, 0, sw, sh);
  brush.wash(PAL.sticker, 250);
  brush.rect(1.5, 1, Math.max(2, sw - 4), Math.max(2, sh - 2));

  // 3. Abstract colour blocks on the sticker (no text!)
  if (st.kind === 0) {
    // Price tag with thin coloured header rule and tiny abstract blocks
    brush.wash(st.barCol, 235);
    brush.rect(2, 2, Math.max(2, sw - 4), Math.max(2.5, sh * 0.22));
    brush.wash("#38343E", 210);
    brush.rect(3, sh * 0.45, Math.max(2, sw * 0.48), Math.max(2, sh * 0.16));
    brush.rect(3, sh * 0.70, Math.max(2, sw * 0.68), Math.max(2, sh * 0.14));
  } else {
    // Library classification band with top & bottom Kente colour rules
    brush.wash(st.barCol, 240);
    brush.rect(1, 1.5, Math.max(2, sw - 2), 4.5);
    brush.wash(PAL.goldRich, 240);
    brush.rect(1, sh - 5.5, Math.max(2, sw - 2), 4);
    brush.wash("#2E2B36", 220);
    brush.rect(sw * 0.22, sh * 0.36, Math.max(2, sw * 0.56), Math.max(2, sh * 0.26));
  }
  brush.noWash();

  // 4. Fine pencil grain across sticker surface
  brush.hatchStyle("cpencil", "#C9BCA2", 0.5);
  brush.hatch(3, 0, { rand: 0.05 });
  brush.noStroke();
  brush.rect(1, 1, Math.max(2, sw - 2), Math.max(2, sh - 2));
  brush.noHatch();

  // 5. Peeling / dog-eared sticker corner casting a tiny triangular shadow
  if (st.dogEar === "tr") {
    let cs = Math.min(6.5, sw * 0.25, sh * 0.38);
    brush.noStroke();
    brush.wash("#18151E", 235);
    brush.rect(sw - cs, 0, cs, cs);
    brush.noWash();
    brush.set("microcrack", "#FFFDF9", 0.95);
    brush.line(sw - cs, 0, sw, cs);
    brush.line(sw - cs, 0, sw - cs * 0.85, cs * 0.85);
  } else if (st.dogEar === "bl") {
    let cs = Math.min(6.5, sw * 0.25, sh * 0.38);
    brush.noStroke();
    brush.wash("#18151E", 235);
    brush.rect(0, sh - cs, cs, cs);
    brush.noWash();
    brush.set("microcrack", "#FFFDF9", 0.95);
    brush.line(0, sh - cs, cs, sh);
  }

  // Crisp paper highlight along top & left sticker edge
  brush.set("microcrack", "#FFFDF8", 0.8);
  brush.line(0, 0, sw - 2, 0);
  brush.line(0, 0, 0, sh - 2);

  pop();
}

// ============================================================================
// 5. DEEP STITCHED CREVICES BETWEEN SPINES
// ============================================================================
function drawInterSpineSeams() {
  for (let i = 0; i < spines.length - 1; i++) {
    let leftSp = spines[i];
    let rightSp = spines[i + 1];
    let seamX = rightSp.x;
    let topSeam = Math.min(leftSp.topY, rightSp.topY);
    let botSeam = Math.max(leftSp.botY, rightSp.botY);

    // Deep shadow in the upper notch between offset book heights
    let highY = Math.min(leftSp.topY, rightSp.topY);
    let lowY = Math.max(leftSp.topY, rightSp.topY);
    if (lowY - highY > 2) {
      let sideX = (leftSp.topY < rightSp.topY) ? seamX : seamX - 6;
      brush.noStroke();
      brush.wash("#09080C", 230);
      brush.rect(sideX, highY, 6, lowY - highY);
      brush.noWash();
    }

    // Razor-deep vertical groove where two paperback covers press together
    brush.set("charcoal", "#07060A", 0.95);
    brush.line(seamX, Math.max(leftSp.topY, rightSp.topY), seamX, botSeam);

    brush.set("microcrack", "#050407", 1.1);
    brush.line(seamX, topSeam, seamX, botSeam);

    // Subtle stitched-look Kente tension ticks where frayed cover hinges meet
    for (let y = Math.max(leftSp.topY, rightSp.topY) + 14; y < botSeam - 14; y += random(26, 52)) {
      brush.set("microcrack", "#26212E", 0.65);
      brush.line(seamX - 1.5, y, seamX + 1.5, y + 1.5);
    }
  }
}

// ============================================================================
// 6. WOODEN SHELF LEDGE & LOWER ROW PEEK (y = 1090 to 1200)
// ============================================================================
function drawBottomShelfAndLowerRow() {
  let shelfTop = 1092;
  let shelfBot = 1138;

  // Base wooden shelf edge wash
  brush.noStroke();
  brush.wash(PAL.woodDark, 255);
  brush.rect(0, shelfTop, 1200, 1200 - shelfTop);
  brush.wash(PAL.woodMid, 235);
  brush.rect(0, shelfTop + 3, 1200, 18);
  brush.noWash();

  // Subtle warm gold/crimson/emerald colour reflections cast onto the polished wood lip
  for (let sp of spines) {
    let footBlock = sp.blocks[sp.blocks.length - 1];
    let reflCol = mixHex(footBlock.color, PAL.woodMid, 0.68);
    brush.noStroke();
    brush.wash(reflCol, 150);
    brush.rect(sp.x, shelfTop + 2, sp.w, 12);
    brush.noWash();

    // Dark grounding shadow directly beneath each book base
    brush.set("charcoal", "#060508", 1.0);
    brush.line(sp.x, sp.botY + 1, sp.x + sp.w, sp.botY + 1);
  }

  // Horizontal wood grain in burnished coloured pencil along shelf lip
  for (let y = shelfTop + 2; y < shelfBot; y += 2.8) {
    let t = (y - shelfTop) / (shelfBot - shelfTop);
    let col = (t < 0.25) ? PAL.woodHighlight : (t < 0.65 ? PAL.woodMid : "#120E0C");
    brush.set("cpencil", col, 0.78);
    brush.line(0, y + random(-0.6, 0.6), 1200, y + random(-0.6, 0.6));
  }

  // Top bevel highlight on wooden shelf edge
  brush.set("burnish", "#6E5544", 0.65);
  brush.line(0, shelfTop + 3.5, 1200, shelfTop + 3.5);

  // Deep shadow under shelf lip (y = 1138 to 1200)
  brush.noStroke();
  brush.wash("#08070B", 255);
  brush.rect(0, shelfBot, 1200, 1200 - shelfBot);
  brush.noWash();

  // Lower shelf book tops peeking up at the very bottom of the frame (y = 1152 to 1200)
  let lx = -8;
  let lIdx = 0;
  while (lx < 1210) {
    let lw = Math.round(random(40, 62));
    let lty = Math.round(random(1152, 1176));
    let lCol = (lIdx % 3 === 0) ? PAL.goldRich : (lIdx % 3 === 1 ? PAL.crimsonRich : PAL.emeraldDeep);
    let fadedCol = mixHex(lCol, PAL.sunBleach, 0.35);

    // Receding page block in shadow
    brush.noStroke();
    brush.wash("#3B3328", 230);
    brush.rect(lx + 3, lty - 12, Math.max(4, lw - 6), 12);

    // Sun-faded top of lower spine
    brush.wash(shadeHex(fadedCol, -0.25), 245);
    brush.rect(lx, lty, lw, 1200 - lty);
    brush.wash(shadeHex(fadedCol, 0.08), 245);
    brush.rect(lx + lw * 0.16, lty, lw * 0.35, 1200 - lty);
    brush.noWash();

    // Coloured pencil vertical grain & frayed headcap on lower row
    brush.hatchStyle("cpencil", shadeHex(fadedCol, -0.15), 0.6);
    brush.hatch(4, 90, { rand: 0.08 });
    brush.noStroke();
    brush.rect(lx + 1, lty + 1, Math.max(3, lw - 2), Math.max(3, 1200 - lty - 1));
    brush.noHatch();

    brush.set("microcrack", PAL.boardLight, 0.85);
    brush.line(lx + 2, lty, lx + lw - 2, lty + 1);
    brush.set("charcoal", "#050408", 1.0);
    brush.line(lx, lty, lx, 1200);

    lx += lw;
    lIdx++;
  }
}

