    spacing: 0.25,
    pressure: [0.3, 1.0, 0.3],
    noise: 0.4
  });
}

function drawPoly(pts, curvature = 0.08, closeShape = true) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closeShape);
}

function sampleBezier(p0, p1, p2, p3, steps) {
  let out = [];
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let mt = 1 - t;
    let x = mt * mt * mt * p0[0] + 3 * mt * mt * t * p1[0] + 3 * mt * t * t * p2[0] + t * t * t * p3[0];
    let y = mt * mt * mt * p0[1] + 3 * mt * mt * t * p1[1] + 3 * mt * t * t * p2[1] + t * t * t * p3[1];
    out.push([x, y]);
  }
  return out;
}

function getLeekSpine(t) {
  // t from 0 (root crown at 245, 905) to 1 (upper leaf junction at 332, 425)
  let p0 = [245, 905];
  let p1 = [262, 755];
  let p2 = [292, 585];
  let p3 = [332, 425];
  let mt = 1 - t;
  let x = mt * mt * mt * p0[0] + 3 * mt * mt * t * p1[0] + 3 * mt * t * t * p2[0] + t * t * t * p3[0];
  let y = mt * mt * mt * p0[1] + 3 * mt * mt * t * p1[1] + 3 * mt * t * t * p2[1] + t * t * t * p3[1];
  let dx = 3 * mt * mt * (p1[0] - p0[0]) + 6 * mt * t * (p2[0] - p1[0]) + 3 * t * t * (p3[0] - p2[0]);
  let dy = 3 * mt * mt * (p1[1] - p0[1]) + 6 * mt * t * (p2[1] - p1[1]) + 3 * t * t * (p3[1] - p2[1]);
  let len = Math.hypot(dx, dy) || 1;
  let nx = -dy / len; // points left-up
  let ny = dx / len;
  // Radius tapers gently then flares slightly at leaf sheaths
  let r = 31 * (1 - 0.16 * t) + 3.5 * Math.sin(t * Math.PI * 1.4);
  return { x, y, nx, ny, r, tx: dx / len, ty: dy / len };
}

function draw() {
  translate(-width / 2, -height / 2);

  // =========================================================================
  // 1. VAST QUIET FIELD OF PALE CELADON-GREY WALL & COUNTER PLANE
  // =========================================================================
  background("#dde3de");
  brush.noField();

  // Subtle atmospheric celadon watercolor washes across the wall
  brush.noStroke();
  brush.fillBleed(0.42, "out");
  brush.fillTexture(0.38, 0.14);

  brush.fill("#d2dad4", 24);
  drawPoly([[-40, -40], [1240, -40], [1240, 916], [-40, 916]], 0);

  brush.fill("#c8d2cc", 20);
  drawPoly([[60, 40], [740, 30], [680, 916], [40, 916]], 0.05);

  brush.fill("#e6ece7", 28);
  drawPoly([[520, 60], [1180, 60], [1180, 880], [460, 740]], 0.08);

  // Lower counter plane (cool pale stone-celadon)
  brush.fill("#e4e9e5", 45);
  drawPoly([[-40, 916], [1240, 916], [1240, 1240], [-40, 1240]], 0);

  brush.fill("#cfd7d2", 26);
  drawPoly([[-40, 916], [760, 916], [620, 1080], [-40, 1080]], 0);

  // Subtle paper grain & quiet air in the negative space
  brush.set("needle2H", "#b8c2bc", 0.35);
  for (let i = 0; i < 65; i++) {
    let gx = random(40, 1160);
    let gy = random(40, 1160);
    brush.line(gx, gy, gx + random(-4, 4), gy + random(-1, 1));
  }

  // Razor-clean architectural horizon line where counter meets celadon wall
  brush.set("needle2H", "#8f9b95", 0.55);
  brush.line(0, 916, 1200, 916);
  brush.set("needle2H", "#f2f6f3", 0.45);
  brush.line(0, 917.2, 1200, 917.2);

  // =========================================================================
  // 2. CAST SHADOWS ON COUNTER & WALL (SOFT GLAZED WATERCOLOUR)
  // =========================================================================
  brush.noStroke();
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.32, 0.18);

  // Faint vertical wall shadow cast by dish rack & leek on the left
  brush.fill("#b7c2bc", 32);
  drawPoly([[95, 890], [210, 690], [295, 695], [395, 895], [360, 916], [95, 916]], 0.12);

  // Dish rack & leek shadow on counter surface
  brush.fill("#a4b0aa", 48);
  drawPoly([[62, 926], [425, 918], [495, 954], [385, 988], [55, 968]], 0.1);

  brush.fill("#8c9892", 52);
  drawPoly([[80, 938], [390, 926], [425, 956], [335, 976], [72, 958]], 0.08);

  // Soft cast shadow under the red rubber band
  brush.fill("#87928d", 62);
  drawPoly([[342, 882], [456, 896], [464, 912], [388, 914], [338, 894]], 0.15);

  // Faint warm red reflection bleed on the counter under the rubber band
  brush.fill("#c95a52", 26);
  drawPoly([[365, 892], [452, 898], [455, 910], [372, 908]], 0.15);

  // =========================================================================
  // 3. BACK CHROME DISH RACK RIBS (BEHIND LEEK & LADLE)
  // =========================================================================
  // Helper to draw a precision 3D chrome wire path
  function drawChromeWire(pts, thickness = 3.6, isDarkBg = false) {
    // 1. Mid-tone steel body
    brush.set("marker", "#9aa6a1", thickness * 0.42);
    brush.spline(pts, 0.25);

    // 2. Dark reflected core along bottom/right edge
    let darkPts = pts.map(p => [p[0] + thickness * 0.24, p[1] + thickness * 0.28]);
    brush.set("crispHB", "#313b38", 0.95);
    brush.spline(darkPts, 0.25);

    // 3. Secondary internal slate reflection
    let midPts = pts.map(p => [p[0] - thickness * 0.05, p[1] + thickness * 0.08]);
    brush.set("needle2H", "#525f5b", 0.85);
    brush.spline(midPts, 0.25);

    // 4. Upper-left crisp graphite edge
    let topPts = pts.map(p => [p[0] - thickness * 0.28, p[1] - thickness * 0.28]);
    brush.set("needle2H", "#485450", 0.68);
    brush.spline(topPts, 0.25);

    // 5. Razor-sharp paper-white specular highlight along upper-left ridge
    let specPts = pts.map(p => [p[0] - thickness * 0.14, p[1] - thickness * 0.15]);
    brush.set("needle2H", "#f9fcf9", 0.95);
    brush.spline(specPts, 0.25);
  }

  // Back horizontal rail of the dish rack
  drawChromeWire([
    [88, 868],
    [185, 861],
    [295, 854],
    [392, 848]
  ], 3.8);

  // Back legs and left vertical corner post
  drawChromeWire([[92, 845], [90, 902], [88, 946]], 4.2);
  drawChromeWire([[390, 848], [390, 888], [390, 922]], 3.8);

  // 5 Arched Plate-Divider Chrome Ribs (back-to-front / left-to-right)
  // Rib 1 & 2 (leftmost, behind leek)
  const ribX = [122, 174, 228, 286, 348];
  for (let i = 0; i < 3; i++) {
    let bx = ribX[i];
    let by = 866 - i * 4;
    let archPts = [
      [bx - 12, by],
      [bx - 8, by - 95],
      [bx + 14, by - 178],
      [bx + 44, by - 168],
      [bx + 54, by - 80],
      [bx + 48, by + 52]
    ];
    drawChromeWire(archPts, 3.4);
  }

  // =========================================================================
  // 4. SHIN (HEAVEN LINE): THE TALL LEEK LEANING SKYWARD
  // =========================================================================
  // Build the exact contour of the lower blanched stalk & sheath transition
  let leftStalk = [];
  let rightStalk = [];
  let steps = 40;
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let s = getLeekSpine(t);
    leftStalk.push([s.x + s.nx * s.r, s.y + s.ny * s.r]);
    rightStalk.push([s.x - s.nx * s.r, s.y - s.ny * s.r]);
  }

  // ---- 4A. UPPER ARCHITECTURAL FLAG LEAVES (GLAUCOUS BLUISH BLOOM) ----
  // Leaf 1: Back-right leaf curving out to (505, 225)
  let leafBackRight = [
    [318, 495],
    [362, 395],
    [418, 302],
    [475, 242],
    [512, 222],
    [486, 268],
    [432, 348],
    [378, 445],
    [336, 515]
  ];

  // Leaf 2: Lower-right folded sheath leaf tipping out toward Soe (538, 352)
  let leafMidRight = [
    [312, 535],
    [372, 452],
    [438, 388],
    [502, 355],
    [542, 348],
    [504, 378],
    [442, 428],
    [376, 498],
    [325, 565]
  ];

  // Leaf 3: Left arching flag leaf with crisp folded keel & drooping tip
  let leafLeftUpper = [
    [295, 535],
    [275, 430],
    [252, 325],
    [234, 242],
    [216, 208],
    [186, 245], // folded drooping tip
    [206, 226],
    [224, 262],
    [242, 355],
    [268, 465],
    [298, 558]
  ];

  // Leaf 4: SHIN PRIMARY SKYWARD LEAF (reaches high to 442, 108)
  // Divided into left lit face and right shaded V-trough face for razor-clean 3D V-section
  let shinKeel = sampleBezier([304, 495], [336, 355], [378, 212], [442, 108], 32);
  let shinLeftMargin = sampleBezier([294, 488], [312, 345], [352, 205], [442, 108], 32);
  let shinRightMargin = sampleBezier([332, 505], [366, 368], [404, 228], [442, 108], 32);

  let shinLeftFace = [...shinKeel, ...shinLeftMargin.slice().reverse()];
  let shinRightFace = [...shinKeel, ...shinRightMargin.slice().reverse()];

  // Watercolour glazing for leaves: cool celadon-slate & dusty glaucous blue
  brush.noStroke();
  brush.fillBleed(0.12, "in");
  brush.fillTexture(0.42, 0.26);

  // Glaze back-right leaf
  brush.fill("#58736e", 135);
  drawPoly(leafBackRight, 0.08);
  brush.fill("#3d5450", 95);
  drawPoly(leafBackRight.slice(2, 8), 0.08);

  // Glaze mid-right leaf
  brush.fill("#66827d", 140);
  drawPoly(leafMidRight, 0.08);
  brush.fill("#465e5a", 90);
  drawPoly([leafMidRight[0], leafMidRight[1], leafMidRight[2], leafMidRight[7], leafMidRight[8]], 0.06);

  // Glaze left arching leaf
  brush.fill("#6e8a85", 130);
  drawPoly(leafLeftUpper, 0.06);
  // Dark shadow under the folded-over tip at (186, 245)
  brush.fill("#394f4c", 145);
  drawPoly([[234, 242], [216, 208], [182, 252], [202, 264], [224, 248]], 0.05);

  // Glaze primary Shin skyward leaf (bright glaucous left keel face, deeper slate-blue right trough)
  brush.fill("#7f9b96", 135);
  drawPoly(shinLeftFace, 0.02);
  brush.fill("#4d6763", 155);
  drawPoly(shinRightFace, 0.02);

  // ---- 4B. LOWER BLANCHED STALK & GLAUCOUS SHEATH TRANSITION ----
  // Base ivory-celadon wash over entire stalk cylinder
  let fullStalkPoly = [...leftStalk, ...rightStalk.slice().reverse()];
  brush.fillBleed(0.08, "in");
  brush.fillTexture(0.32, 0.18);
  brush.fill("#eef3ef", 190);
  drawPoly(fullStalkPoly, 0.02);

  // Cylindrical core shadow along right-center of the white shank
  let shadowBand = [];
  for (let i = 0; i <= steps; i++) {
    let s = getLeekSpine(i / steps);
    shadowBand.push([s.x - s.nx * (s.r * 0.12), s.y - s.ny * (s.r * 0.12)]);
  }
  for (let i = steps; i >= 0; i--) {
    let s = getLeekSpine(i / steps);
    shadowBand.push([s.x - s.nx * (s.r * 0.82), s.y - s.ny * (s.r * 0.82)]);
  }
  brush.fill("#c2cdc7", 115);
  drawPoly(shadowBand, 0.02);

  // Graduated glaucous blue-green sheath chevrons wrapping the upper half of the stalk (t = 0.45..1.0)
  for (let layer = 0; layer < 4; layer++) {
    let tStart = 0.42 + layer * 0.11;
    let sheathPoly = [];
    for (let i = Math.floor(tStart * steps); i <= steps; i++) {
      let s = getLeekSpine(i / steps);
      sheathPoly.push([s.x + s.nx * s.r, s.y + s.ny * s.r]);
    }
    for (let i = steps; i >= Math.floor(tStart * steps); i--) {
      let s = getLeekSpine(i / steps);
      sheathPoly.push([s.x - s.nx * s.r, s.y - s.ny * s.r]);
    }
    // Add V-shaped chevron notch at the bottom of each sheath wrap
    let sBot = getLeekSpine(tStart + 0.05);
    sheathPoly.push([sBot.x, sBot.y - 18]);

    let cols = ["#9ab0ab", "#7b9691", "#5f7b76", "#4b6661"];
    brush.fill(cols[layer], 82);
    drawPoly(sheathPoly, 0.04);
  }

  // Waxy epicuticular "bluish bloom" over the leek sheath and leaves
  brush.set("bloomShader", "#cadbd8", 1.25);
  for (let i = 0; i < 28; i++) {
    let t1 = random(0.48, 0.96);
    let t2 = min(1.0, t1 + random(0.08, 0.18));
    let u = random(-0.75, 0.65);
    let s1 = getLeekSpine(t1);
    let s2 = getLeekSpine(t2);
    brush.line(
      s1.x + s1.nx * s1.r * u,
      s1.y + s1.ny * s1.r * u,
      s2.x + s2.nx * s2.r * u,
      s2.y + s2.ny * s2.r * u
    );
  }
  // Bluish bloom on upper leaves
  for (let i = 6; i < 26; i += 2) {
    brush.line(shinKeel[i][0] + 4, shinKeel[i][1], shinKeel[i + 3][0] + 5, shinKeel[i + 3][1]);
  }

  // ---- 4C. FINE GRAPHITE VENATION, RIBS & RAZOR-CLEAN CONTOURS ----
  // Longitudinal vascular striations along the cylindrical stalk (foreshortened spacing near edges)
  for (let k = -12; k <= 12; k++) {
    let u = Math.sin((k / 12) * (Math.PI / 2)); // cosine-bunched near cylinder edges
    let ribPts = [];
    for (let i = 0; i <= 24; i++) {
      let t = i / 24;
      let s = getLeekSpine(t);
      ribPts.push([s.x + s.nx * s.r * u, s.y + s.ny * s.r * u]);
    }
    let col = u < -0.15 ? "#7a8883" : u > 0.35 ? "#a7b4ae" : "#94a29c";
    let w = Math.abs(u) > 0.75 ? 0.52 : 0.32;
    brush.set("needle2H", col, w);
    brush.spline(ribPts, 0.2);
  }

  // Chevron sheath overlap lines on the stalk
  for (let c = 0; c < 5; c++) {
    let tc = 0.44 + c * 0.1;
    let sL = getLeekSpine(tc);
    let sM = getLeekSpine(tc + 0.06);
    let sR = getLeekSpine(tc - 0.01);
    brush.set("needle2H", "#4d615d", 0.58);
    brush.spline([
      [sL.x + sL.nx * sL.r, sL.y + sL.ny * sL.r],
      [sM.x - sM.nx * sM.r * 0.1, sM.y - sM.ny * sM.r * 0.1],
      [sR.x - sR.nx * sR.r, sR.y - sR.ny * sR.r]
    ], 0.18);
  }

  // Parallel venation & razor-clean edges on the flag leaves
  for (let v = 1; v <= 5; v++) {
    let f = v / 6;
    let veinL = [];
    let veinR = [];
    for (let i = 0; i < shinKeel.length; i++) {
      veinL.push([
        lerp(shinKeel[i][0], shinLeftMargin[i][0], f),
        lerp(shinKeel[i][1], shinLeftMargin[i][1], f)
      ]);
      veinR.push([
        lerp(shinKeel[i][0], shinRightMargin[i][0], f),
        lerp(shinKeel[i][1], shinRightMargin[i][1], f)
      ]);
    }
    brush.set("needle2H", "#4d6561", 0.32);
    brush.spline(veinL, 0.2);
    brush.set("needle2H", "#324643", 0.36);
    brush.spline(veinR, 0.2);
  }

  // Venation on secondary leaves
  for (let f = 0.25; f <= 0.75; f += 0.25) {
    brush.set("needle2H", "#3f5552", 0.34);
    brush.spline([
      [lerp(318, 336, f), lerp(495, 515, f)],
      [lerp(362, 432, f), lerp(395, 348, f)],
      [lerp(418, 486, f), lerp(302, 268, f)],
      [512, 222]
    ], 0.25);

    brush.spline([
      [lerp(312, 325, f), lerp(535, 565, f)],
      [lerp(372, 442, f), lerp(452, 428, f)],
      [lerp(438, 504, f), lerp(388, 378, f)],
      [542, 348]
    ], 0.25);

    brush.spline([
      [lerp(295, 298, f), lerp(535, 558, f)],
      [lerp(252, 242, f), lerp(325, 355, f)],
      [216, 208]
    ], 0.25);
  }

  // Razor-sharp outer graphite contours & luminous keel highlights
  brush.set("crispHB", "#374744", 0.65);
  brush.spline(leftStalk, 0.2);
  brush.spline(rightStalk, 0.2);
  brush.spline(shinLeftMargin, 0.2);
  brush.spline(shinRightMargin, 0.2);
  brush.spline(shinKeel, 0.2);
  brush.spline(leafBackRight, 0.15);
  brush.spline(leafMidRight, 0.15);
  brush.spline(leafLeftUpper, 0.12);

  // Paper-white razor highlight along the central keel fold of Shin leaf
  let keelHi = shinKeel.map(p => [p[0] - 0.9, p[1] - 0.5]);
  brush.set("needle2H", "#f2f7f5", 0.75);
  brush.spline(keelHi, 0.2);

  // ---- 4D. BASAL PLATE & SOIL-FLECKED FIBROUS ROOTS ----
  let sBase = getLeekSpine(0);
  // Basal root plate swelling at (245, 905)
  brush.noStroke();
  brush.fillBleed(0.15, "out");
  brush.fill("#8c8275", 150);
  drawPoly([
    [sBase.x - 30, sBase.y - 6],
    [sBase.x + 31, sBase.y + 8],
    [sBase.x + 26, sBase.y + 20],
    [sBase.x - 26, sBase.y + 8]
  ], 0.15);

  // Dense tangle of 68 fibrous roots with organic kinks & soil flecks
  const rootColors = ["#3d3730", "#595046", "#73695d", "#2a2520", "#8c8274"];
  for (let r = 0; r < 68; r++) {
    let frac = (r / 67) * 2 - 1; // -1 to 1 across basal plate
    let rx0 = sBase.x - frac * 27 + random(-2, 2);
    let ry0 = sBase.y + frac * 6 + random(2, 10);
    let rLen = random(28, 76) * (1 - 0.35 * Math.abs(frac));
    let rPts = [[rx0, ry0]];
    let cx = rx0;
    let cy = ry0;
    let segs = 5;
    for (let s = 1; s <= segs; s++) {
      cx += (frac * 5.5) + random(-6.5, 6.5);
      cy += (rLen / segs) + random(-2, 3.5);
      rPts.push([cx, cy]);
    }
    let col = rootColors[r % rootColors.length];
    let w = random(0.32, 0.75);
    brush.set(r % 3 === 0 ? "crispHB" : "needle2H", col, w);
    brush.spline(rPts, 0.35);
  }

  // Soil flecks clinging to roots and scattered in tiny crumbs on the counter below
  brush.noStroke();
  for (let f = 0; f < 48; f++) {
    let onCounter = f > 30;
    let fx = onCounter ? random(195, 295) : sBase.x + random(-28, 28);
    let fy = onCounter ? random(935, 974) : sBase.y + random(6, 58);
    let sz = random(1.2, 3.4);
    brush.fill(f % 2 === 0 ? "#241f1b" : "#453c34", random(165, 235));
    drawPoly([
      [fx - sz, fy],
      [fx, fy - sz * 0.8],
      [fx + sz * 1.1, fy + sz * 0.3],
      [fx - sz * 0.3, fy + sz * 0.9]
    ], 0.1);
  }

  // =========================================================================
  // 5. SOE (MAN LINE): STAINLESS STEEL LADLE ANGLING MID-HEIGHT
  // =========================================================================
  // The ladle's long flat-bar handle starts hooked under the lower-left rack wire at (172, 912),
  // rises at ~40° through the tall right-most rack arch at (398, 675), and cantilevers its
  // large mirror-polished hemispherical bowl out at mid-height around (505, 565).

  // ---- 5A. LADLE HANDLE & HOOKED END ----
  // Hooked terminal at bottom-left (172, 912)
  let handleLeftEdge = [
    [168, 916],
    [245, 832],
    [340, 730],
    [425, 638],
    [458, 600]
  ];
  let handleRightEdge = [
    [178, 924],
    [256, 840],
    [352, 739],
    [438, 648],
    [474, 614]
  ];
  let handlePoly = [...handleLeftEdge, ...handleRightEdge.slice().reverse()];

  // Base watercolor wash for brushed steel handle
  brush.noStroke();
  brush.fillBleed(0.04, "in");
  brush.fillTexture(0.25, 0.15);
  brush.fill("#cfd8d3", 210);
  drawPoly(handlePoly, 0.05);

  // Dark slate reflection band along right half of handle shaft
  let handleDarkBand = [
    [173, 920],
    [251, 836],
    [346, 735],
    [432, 643],
    [468, 608],
    ...handleRightEdge.slice().reverse()
  ];
  brush.fill("#46524e", 175);
  drawPoly(handleDarkBand, 0.05);

  // Flared triangular neck flange where handle joins the bowl
  let neckFlange = [
    [445, 614],
    [468, 582],
    [486, 604],
    [464, 624]
  ];
  brush.fill("#7f8c87", 190);
  drawPoly(neckFlange, 0.08);

  // Crisp graphite edges & specular ridge of handle
  brush.set("crispHB", "#2b3431", 0.72);
  brush.spline(handleLeftEdge, 0.2);
  brush.spline(handleRightEdge, 0.2);

  let handleSpec = handleLeftEdge.map(p => [p[0] + 2.4, p[1] + 2.2]);
  brush.set("needle2H", "#ffffff", 0.95);
  brush.spline(handleSpec, 0.2);

  // Hooked tip at bottom-left (168, 916)
  drawChromeWire([
    [173, 920],
    [156, 934],
    [144, 926],
    [150, 908],
    [165, 902]
  ], 3.8);

  // ---- 5B. LADLE BOWL AT MID-HEIGHT WITH WARPED ANAMORPHIC REFLECTIONS ----
  // Bowl geometry:
  // Tilted elliptical opening centered at (492, 550), major radius a = 78, minor radius b = 38, angle = -38 deg.
  // Deep hemispherical outer belly curving down-right to (562, 608).
  const bowlCx = 492;
  const bowlCy = 550;
  const rimA = 78;
  const rimB = 36;
  const rimAng = -38;

  function rimPt(deg, scaleA = 1, scaleB = 1, offsetN = 0) {
    let rad = deg * (Math.PI / 180);
    let lx = Math.cos(rad) * rimA * scaleA;
    let ly = Math.sin(rad) * rimB * scaleB + offsetN;
    let ca = Math.cos(rimAng * Math.PI / 180);
    let sa = Math.sin(rimAng * Math.PI / 180);
    return [
      bowlCx + lx * ca - ly * sa,
      bowlCy + lx * sa + ly * ca
    ];
  }

  // Build outer hemispherical belly contour (from left rim -180 deg around bottom-right to right rim 0 deg)
  let bowlOuterContour = [];
  for (let d = 180; d >= 0; d -= 6) {
    bowlOuterContour.push(rimPt(d));
  }
  // Now curve around the deep spherical bottom belly from 0 deg (top-right rim) to 180 deg (bottom-left rim)
  let bellyArc = sampleBezier(
    rimPt(0),
    [602, 545],
    [552, 668],
    rimPt(180),
    32
  );
  let fullBowlBody = [...bowlOuterContour, ...bellyArc.slice(1, -1)];

  // 1. Base mirror steel ground of the bowl
  brush.noStroke();
  brush.fillBleed(0.03, "in");
  brush.fillTexture(0.22, 0.12);
  brush.fill("#d5ded9", 225);
  drawPoly(fullBowlBody, 0.04);

  // 2. Concave interior of the ladle bowl (visible inside the elliptical rim)
  let rimEllipse = [];
  for (let d = 0; d < 360; d += 8) {
    rimEllipse.push(rimPt(d, 0.96, 0.93));
  }
  brush.fill("#86938e", 195);
  drawPoly(rimEllipse, 0.05);

  // Inner concave shadow on upper-left wall of bowl interior
  let innerDarkZone = [];
  for (let d = 155; d <= 335; d += 10) {
    innerDarkZone.push(rimPt(d, 0.94, 0.9));
  }
  innerDarkZone.push(rimPt(290, 0.45, 0.35, 14));
  innerDarkZone.push(rimPt(210, 0.55, 0.45, 16));
  brush.fill("#2b3532", 185);
  drawPoly(innerDarkZone, 0.08);

  // Inner concave bright caustic reflection on lower-right curve of interior
  let innerBrightZone = [];
  for (let d = -25; d <= 145; d += 12) {
    innerBrightZone.push(rimPt(d, 0.9, 0.85));
  }
  innerBrightZone.push(rimPt(80, 0.35, 0.25, 10));
  innerBrightZone.push(rimPt(15, 0.45, 0.35, 8));
  brush.fill("#f7faf8", 210);
  drawPoly(innerBrightZone, 0.08);

  // 3. WARPED ANAMORPHIC REFLECTIONS ON CONVEX OUTER BELLY OF LADLE
  // Helper for spherical latitude/longitude point on the outer belly
  // u in [0, 1] from left rim (180 deg) to right rim (0 deg)
  // v in [0, 1] from front rim edge down to bottom belly contour
  function bellyGridPt(u, v) {
    let topP = rimPt(180 * (1 - u));
    let idx = Math.min(bellyArc.length - 1, Math.floor((1 - u) * (bellyArc.length - 1)));
    let botP = bellyArc[idx];
    // Bulge outward spherically in the middle
    let bulge = Math.sin(u * Math.PI) * Math.sin(v * Math.PI) * 18;
    return [
      lerp(topP[0], botP[0], v) + bulge * 0.62,
      lerp(topP[1], botP[1], v) + bulge * 0.78
    ];
  }

  function makeBellyBand(u0, u1, v0, v1, stepsU = 14) {
    let pts = [];
    for (let i = 0; i <= stepsU; i++) {
      let u = lerp(u0, u1, i / stepsU);
      pts.push(bellyGridPt(u, v0));
    }
    for (let i = stepsU; i >= 0; i--) {
      let u = lerp(u0, u1, i / stepsU);
      pts.push(bellyGridPt(u, v1));
    }
    return pts;
  }

  // Band A: Bright skylight reflection just below the front rim
  brush.fill("#f8fbf9", 215);
  drawPoly(makeBellyBand(0.08, 0.92, 0.06, 0.24), 0.06);

  // Band B: Warped dark horizon of kitchen counter & chrome rack wires sweeping across mid-belly
  brush.fill("#222b29", 205);
  drawPoly(makeBellyBand(0.03, 0.96, 0.32, 0.56), 0.06);

  // Band C: Secondary slate reflection below dark horizon
  brush.fill("#53615d", 165);
  drawPoly(makeBellyBand(0.06, 0.94, 0.54, 0.74), 0.06);

  // Band D: Warped glaucous blue-green reflection of the tall leek on the left curve of the ladle!
  brush.fill("#4e6d68", 175);
  drawPoly(makeBellyBand(0.04, 0.36, 0.14, 0.68), 0.08);
  brush.fill("#7fa19b", 150);
  drawPoly(makeBellyBand(0.10, 0.26, 0.18, 0.52), 0.08);

  // Band E: Warped vermilion-red glint of the rubber band reflected in the lower-left belly of the ladle!
  brush.fill("#c93028", 185);
  drawPoly(makeBellyBand(0.18, 0.44, 0.68, 0.80, 10), 0.1);

  // Band F: Bright counter reflection along the lower-right outer rim of the hemisphere
  brush.fill("#eef3ef", 205);
  drawPoly(makeBellyBand(0.22, 0.92, 0.78, 0.94), 0.06);

  // 4. Fine graphite contour hatching & warped wire reflections across the ladle bowl
  for (let w = 0; w < 5; w++) {
    let uMid = 0.15 + w * 0.14;
    let wireRefl = [];
    for (let j = 0; j <= 10; j++) {
      let v = 0.25 + (j / 10) * 0.58;
      let u = uMid + Math.sin(j * 0.35) * 0.06;
      wireRefl.push(bellyGridPt(u, v));
    }
    brush.set("needle2H", "#1c2422", 0.55);
    brush.spline(wireRefl, 0.25);
  }

  // Fine spherical form lines along the steel belly
  for (let v = 0.15; v <= 0.88; v += 0.09) {
    let latCurve = [];
    for (let i = 0; i <= 16; i++) {
      latCurve.push(bellyGridPt(i / 16, v));
    }
    brush.set("needle2H", v > 0.3 && v < 0.6 ? "#18201e" : "#6d7b76", 0.35);
    brush.spline(latCurve, 0.2);
  }

  // Razor-sharp double-line rolled steel rim of the ladle bowl
  let outerRimLoop = [];
  let innerRimLoop = [];
  let specRimLoop = [];
  for (let d = 0; d <= 360; d += 6) {
    outerRimLoop.push(rimPt(d, 1.0, 1.0));
    innerRimLoop.push(rimPt(d, 0.94, 0.91));
    specRimLoop.push(rimPt(d, 0.97, 0.955));
  }
  brush.set("crispHB", "#232c29", 0.75);
  brush.spline(outerRimLoop, 0.2);
  brush.set("needle2H", "#384440", 0.6);
  brush.spline(innerRimLoop, 0.2);
  brush.set("needle2H", "#ffffff", 1.05);
  brush.spline(specRimLoop, 0.2);

  // Outer belly contour in razor-sharp 2B/HB graphite
  brush.set("crispHB", "#1f2725", 0.82);
  brush.spline(bellyArc, 0.25);

  // Blazing specular highlight crescents on the convex steel bowl
  let hiCrescent1 = [];
  for (let i = 2; i <= 13; i++) {
    hiCrescent1.push(bellyGridPt(i / 16, 0.14));
  }
  brush.set("crispHB", "#ffffff", 1.25);
  brush.spline(hiCrescent1, 0.25);

  // Two tiny spot-weld dimples on the ladle neck flange
  brush.set("needle2H", "#2c3633", 0.65);
  brush.circle(462, 603, 2.2, 0.1);
  brush.circle(469, 595, 2.2, 0.1);

  // =========================================================================
  // 6. FOREGROUND CHROME DISH RACK WIRES (ANCHORING LEEK & LADLE)
  // =========================================================================
  // Arched ribs #4 and #5 in front of the leek and cradling the ladle neck
  for (let i = 3; i < 5; i++) {
    let bx = ribX[i];
    let by = 866 - i * 4;
    let archPts = [
      [bx - 12, by],
      [bx - 8, by - 95],
      [bx + 14, by - 178],
      [bx + 44, by - 168],
      [bx + 54, by - 80],
      [bx + 48, by + 52]
    ];
    drawChromeWire(archPts, 3.6);
  }

  // Transverse base grid wires running from back rail to front rail
  for (let g = 0; g < 7; g++) {
    let t = g / 6;
    let xBack = lerp(102, 378, t);
    let yBack = lerp(867, 849, t);
    let xFront = lerp(96, 396, t);
    let yFront = lerp(936, 912, t);
    drawChromeWire([
      [xBack, yBack],
      [lerp(xBack, xFront, 0.5), lerp(yBack, yFront, 0.5) + 4],
      [xFront, yFront]
    ], 3.1);
  }

  // Front horizontal upper & lower rails of the chrome dish rack
  drawChromeWire([
    [82, 892],
    [195, 884],
    [308, 875],
    [418, 866]
  ], 4.2);

  drawChromeWire([
    [84, 938],
    [196, 929],
    [310, 920],
    [408, 912]
  ], 4.0);

  // Front-left & front-right vertical corner posts with dark rubber feet on counter
  drawChromeWire([[84, 868], [84, 915], [84, 958]], 4.4);
  drawChromeWire([[408, 848], [408, 895], [408, 938]], 4.2);

  // Projecting right-side low wire finger (where the red rubber band is anchored)
  drawChromeWire([
    [348, 872],
    [364, 862],
    [358, 852],
    [336, 858]
  ], 3.4);

  // Small dark rubberized feet at base of rack corners
  brush.noStroke();
  brush.fill("#232927", 230);
  drawPoly([[79, 952], [89, 952], [89, 964], [79, 964]], 0.05);
  drawPoly([[403, 932], [413, 932], [413, 944], [403, 944]], 0.05);
  drawPoly([[84, 940], [92, 940], [92, 950], [84, 950]], 0.05);

  // Warm red reflection glint on the front-right chrome rail next to the rubber band
  brush.set("crispHB", "#c92b23", 0.95);
  brush.line(346, 872, 378, 869);
  brush.line(406, 882, 406, 904);

  // =========================================================================
  // 7. HIKAE (EARTH LINE): THE SINGLE RED RUBBER BAND RESTING LOW
  // =========================================================================
  // Anchored over the low right-projecting wire finger at (356, 856) and draping
  // down-right onto the counter edge at (452, 898) in a relaxed, square-cut elastic figure-8 loop.

  // Back/lower strand of the rubber band loop (passes from wire hook through twist to right loop)
  let bandBackTop = sampleBezier([352, 857], [376, 878], [412, 898], [450, 895], 24);
  let bandBackBot = sampleBezier([350, 863], [374, 884], [410, 905], [452, 902], 24);
  let bandBackSide = sampleBezier([350, 867], [374, 889], [410, 910], [450, 907], 24);

  // Front/upper strand of the rubber band loop (arches from wire hook over the twist to right tip)
  let bandFrontTop = sampleBezier([356, 851], [392, 856], [432, 872], [454, 892], 24);
  let bandFrontBot = sampleBezier([354, 857], [390, 863], [428, 879], [450, 898], 24);
  let bandFrontSide = sampleBezier([354, 861], [389, 868], [426, 884], [448, 903], 24);

  // Left turn around the chrome wire at (352, 856)
  let bandLeftTurn = [
    [356, 851],
    [346, 853],
    [344, 860],
    [350, 867],
    [356, 862],
    [354, 857]
  ];

  // Right turn resting on the counter at (452, 898)
  let bandRightTurn = [
    [454, 892],
    [461, 897],
    [459, 904],
    [450, 907],
    [446, 901],
    [450, 895]
  ];

  brush.noStroke();
  brush.fillBleed(0.04, "in");
  brush.fillTexture(0.28, 0.18);

  // 1. Deep crimson-alizarin underside thickness of the back strand
  brush.fill("#6e1310", 225);
  drawPoly([...bandBackBot, ...bandBackSide.slice().reverse()], 0.04);

  // 2. Lit vermilion top face of the back strand
  brush.fill("#c7261e", 215);
  drawPoly([...bandBackTop, ...bandBackBot.slice().reverse()], 0.04);

  // 3. Left & right loop turns
  brush.fill("#b01e17", 225);
  drawPoly(bandLeftTurn, 0.08);
