  // 4. Deep crimson side-wall thickness of the front overlapping strand
  brush.fill("#801511", 230);
  drawPoly([...bandFrontBot, ...bandFrontSide.slice().reverse()], 0.04);

  // 5. Vivid cadmium-vermilion top face of the front strand (the primary red accent)
  brush.fill("#de3328", 230);
  drawPoly([...bandFrontTop, ...bandFrontBot.slice().reverse()], 0.04);

  // 6. Second glaze pass on the center of the front ribbon for luminous saturation
  brush.fill("#e84236", 120);
  drawPoly([...bandFrontTop.slice(4, 18), ...bandFrontBot.slice(4, 18).reverse()], 0.04);

  // 7. Crisp square-cut rubber edge highlights & fine graphite definition
