// ============================================================================
//SAFE WRAPPERS FOR P5.BRUSH PRIMITIVES
// ============================================================================

function drawPolyPath(pts, curvature = 0.28) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

function fillShape(pts, col, opacity, bleed = 0.08, tex = 0.35, curvature = 0.28) {
  brush.noStroke();
  brush.noWash();
  brush.noHatch();
  brush.fill(col, opacity);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, 0.25);
  drawPolyPath(pts, curvature);
  brush.noFill();
}

function washShape(pts, col, opacity, curvature = 0.28) {
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  brush.wash(col, opacity);
  drawPolyPath(pts, curvature);
  brush.noWash();
}

function rectCorners(x, y, w, h) {
  return [[x, y], [x + w, y], [x + w, y + h], [x, y + h]];
}

function strokeSegment(bName, col, weight, x1, y1, x2, y2) {
  brush.noFill();
  brush.noWash();
  brush.set(bName, col, weight);
  brush.line(x1, y1, x2, y2);
}

function strokeCurve(bName, col, weight, pts, curvature = 0.5) {
  brush.noFill();
  brush.noWash();
  brush.set(bName, col, weight);
  brush.spline(pts, curvature);
}

function inPoly(x, y, poly) {
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    let xi = poly[i][0], yi = poly[i][1];
    let xj = poly[j][0], yj = poly[j][1];
    let intersect = ((yi > y) !== (yj > y)) &&
                    (x < (xj - xi) * (y - yi) / ((yj - yi) || 0.0001) + xi);
    if (intersect) inside = !inside;
  }
  return inside;
}

function distSq(x1, y1, x2, y2) {
  let dx = x1 - x2, dy = y1 - y2;
  return dx * dx + dy * dy;
}

