function draw() {
  translate(-width / 2, -height / 2);
  background("#e5917b");

  // 1. Broad Salmon Outer Margin Base & Paper Grain
  drawSalmonMarginBase();

  // 2. Flat Jade-Green Miniature Ground
  drawJadeGround();

  // 3. Clip to Inner Miniature Window for Portrait
  brush.clip([176, 176, 1024, 1024]);

  // 4. Horns (curved Pahari Zebu horns at the crown)
  drawHorns();

  // 5. Neck & Dewlap Folds
  drawNeckAndDewlap();

  // 6. Velvety Ears (left and right)
  drawEars();

  // 7. Cranium, Forehead, Cheeks, Grey Mottling & Strand-by-Strand Fur
  drawHeadAndFur();

  // 8. Wet Pink Nostrils & Dewy Muzzle Cushion
  drawWetPinkMuzzle();

  // 9. Soulful Dark Eyes & Long Sweeping Eyelashes
  drawEyesAndEyelashes();

  // 10. Lush Marigold Garland Slung Beneath the Jaw
  drawMarigoldGarland();

  // 11. Final Whiskers & Devotional Highlights
  drawWhiskersAndFinalTouches();

  brush.noClip();

  // 12. Slender Saffron-and-Crimson Inner Border
  drawPahariBorders();

  // 13. Scattered Tiny Floral Sprigs (Buti) on Salmon Margin
  drawMarginFloralSprigs();

  noLoop();
}

