function drawSalmonMarginBase() {
  // Layered warm salmon-terracotta washes on handmade wasli paper
  washShape(rectCorners(0, 0, 1200, 1200), "#e48f79", 255, 0);
  fillShape(rectCorners(12, 12, 1176, 1176), "#ea9c87", 95, 0.04, 0.45, 0);
  fillShape(rectCorners(25, 25, 1150, 1150), "#df856e", 55, 0.04, 0.35, 0);

  // Subtle paper fiber texture in the outer margin areas
  brush.set("pardaz_stipple", "#c96e58", 0.9);
  for (let i = 0; i < 180; i++) {
    let side = i % 4;
    let x, y;
    if (side === 0) { x = random(15, 1185); y = random(15, 125); }
    else if (side === 1) { x = random(15, 1185); y = random(1075, 1185); }
    else if (side === 2) { x = random(15, 125); y = random(125, 1075); }
    else { x = random(1075, 1185); y = random(125, 1075); }
    brush.line(x, y, x + random(-8, 8), y + random(-8, 8));
  }

  brush.set("pardaz_stipple", "#f7bca8", 0.8);
  for (let i = 0; i < 140; i++) {
    let side = i % 4;
    let x, y;
    if (side === 0) { x = random(15, 1185); y = random(15, 125); }
    else if (side === 1) { x = random(15, 1185); y = random(1075, 1185); }
    else if (side === 2) { x = random(15, 125); y = random(125, 1075); }
    else { x = random(1075, 1185); y = random(125, 1075); }
    brush.line(x, y, x + random(-6, 6), y + random(-6, 6));
  }
}

function drawJadeGround() {
