// 7. HEAD ANATOMY, GREY MOTTLING & STRAND-BY-STRAND FUR
// ============================================================================

// Analytical fur vector field for the cow's face (including the central forehead whorl)
function getCowFurAngle(x, y) {
  let wx = 588, wy = 456; // Central forehead spiral cowlick/whorl
  let dx = x - wx, dy = y - wy;
  let d = sqrt(dx * dx + dy * dy);

  // Radial angle from forehead whorl with subtle clockwise swirl at core
  let radialAng = atan2(dy, dx) + 22 * exp(-d / 52);

  if (y < 365) {
    // Poll / Crown tuft: sweeps upward and fans gracefully left/right toward horns
    let pollAng = -90 + (x - 588) * 0.52;
    let blend = constrain(map(y, 310, 365, 0, 1), 0, 1);
    return lerpAngleDeg(pollAng, radialAng, blend);
  }

  if (y > 515) {
    // Nasal bridge and cheeks: streams downward along the bridge and fans across maxilla/cheeks
    let sideOffset = (x - 588);
    let streamAng = 90 - sideOffset * 0.24;
    if (abs(sideOffset) > 55) {
      // Cheek sweep curving down and slightly inward toward jaw/chin
      streamAng = 90 + sideOffset * 0.18;
    }
    if (y > 815) {
      // Chin whorl under lower lip
      streamAng = 90 + sideOffset * 0.45;
    }
    let blend = constrain(map(y, 465, 555, 0, 1), 0, 1);
    return lerpAngleDeg(radialAng, streamAng, blend);
  }

  // Deflect smoothly around left and right eye orbits
  let dLeftEye = sqrt(distSq(x, y, 486, 482));
  if (dLeftEye < 62) {
    let tang = atan2(y - 482, x - 486) + (y < 482 ? -75 : 75);
    return lerpAngleDeg(radialAng, tang, constrain(map(dLeftEye, 25, 62, 0.85, 0), 0, 0.85));
  }
  let dRightEye = sqrt(distSq(x, y, 692, 484));
  if (dRightEye < 62) {
    let tang = atan2(y - 484, x - 692) + (y < 484 ? 75 : -75);
    return lerpAngleDeg(radialAng, tang, constrain(map(dRightEye, 25, 62, 0.85, 0), 0, 0.85));
  }

  return radialAng;
}

function lerpAngleDeg(a, b, t) {
  let diff = ((b - a + 540) % 360) - 180;
  return a + diff * t;
}

// Compute local mottling intensity (0..1) for faint grey spots under the white fur
function getMottlingIntensity(x, y) {
  let m = 0;
  for (let i = 0; i < mottlingPatches.length; i++) {
    let p = mottlingPatches[i];
    let ndx = (x - p.x) / p.rx;
    let ndy = (y - p.y) / p.ry;
    let d2 = ndx * ndx + ndy * ndy;
    if (d2 < 1.6) {
      m = max(m, p.str * exp(-d2 * 1.8));
    }
  }
  // Fine organic noise modulation for spotclusters
  let n = noise(x * 0.035, y * 0.035);
  return constrain(m * (0.55 + 0.75 * n), 0, 1);
}

function drawHeadAndFur() {
  // 1. Base luminous pearl-white underpainting of the head
  washShape(headPoly, "#eaebe8", 255, 0.3);
  fillShape(headPoly, "#f7f4ec", 210, 0.04, 0.3, 0.3);

  // 2. Sculptural 3D anatomical shading planes (side cheeks, eye sockets, maxilla, chin)
  // Left side plane of skull & cheek hollow
  fillShape([
    [478, 392], [532, 425], [538, 535], [528, 675], [510, 835],
    [484, 814], [468, 746], [478, 676], [458, 616], [440, 548], [432, 488], [440, 446]
  ], "#b8c0c8", 135, 0.12, 0.4, 0.35);

  // Right side plane of skull & cheek hollow
  fillShape([
    [698, 392], [644, 425], [638, 535], [648, 675], [666, 835],
    [692, 814], [708, 746], [698, 676], [718, 616], [736, 548], [744, 488], [736, 446]
  ], "#aeb7c0", 145, 0.12, 0.4, 0.35);

  // Subtle frontal depression above the eyes and along the sides of the nasal bridge
  fillShape([
    [515, 465], [552, 475], [545, 655], [495, 665], [490, 550]
  ], "#9ea7b2", 95, 0.14, 0.4, 0.35);

  fillShape([
    [661, 465], [624, 475], [631, 655], [681, 665], [686, 550]
  ], "#98a1ac", 105, 0.14, 0.4, 0.35);

  // Lower chin & jaw pocket beneath the muzzle
  fillShape([
    [492, 815], [588, 828], [684, 815], [654, 858], [588, 870], [522, 858]
  ], "#7c848e", 165, 0.08, 0.35, 0.35);

  // Bright devotional light plane along the crown, forehead dome, and nasal bridge
  fillShape([
    [542, 304], [634, 304], [645, 425], [624, 525],
    [628, 678], [548, 678], [552, 525], [531, 425]
  ], "#ffffff", 210, 0.1, 0.2, 0.35);

  // 3. Faint Grey Mottling Washes & Fine Watercolor Stippling (Pardaz)
  for (let p of mottlingPatches) {
    if (!inPoly(p.x, p.y, headPoly)) continue;
    let pts = [];
    for (let a = 0; a < 360; a += 45) {
      let rMod = 0.8 + 0.35 * noise(p.x + cos(a), p.y + sin(a));
      pts.push([p.x + cos(a) * p.rx * rMod, p.y + sin(a) * p.ry * rMod]);
    }
    fillShape(pts, "#868f99", floor(p.str * 95), 0.15, 0.45, 0.4);
  }

  // Fine watercolour stippling across the hide to build velvety skin texture and dappled mottling
  for (let i = 0; i < 1600; i++) {
    let x = random(432, 744);
    let y = random(294, 865);
    if (!inPoly(x, y, headPoly) || inPoly(x, y, muzzlePoly)) continue;

    let mot = getMottlingIntensity(x, y);
    let dBridge = abs(x - 588);
    let col;
    if (mot > 0.38 && random() < mot * 1.1) {
      col = random(["#6d7680", "#838c96", "#9aa2ac"]);
    } else if (dBridge > 72) {
      col = random(["#9ba3ad", "#b4bcc4", "#cfd5dc"]);
    } else {
      col = random(["#d8dce0", "#ebe8e0", "#ffffff"]);
    }
    strokeSegment("pardaz_stipple", col, random(0.55, 0.95),
      x, y, x + random(-3, 3), y + random(-3, 3));
  }

  // 4. STRAND-BY-STRAND FUR PASS (3,800 hair-thin strokes following anatomical growth)
  // Pass A: Under-layer shadow & mid-tone fur (2H & HB graphite feel)
  for (let i = 0; i < 1900; i++) {
    let x = random(432, 744);
    let y = random(292, 868);
    if (!inPoly(x, y, headPoly)) continue;
    // Leave central wet muzzle bare, but allow fine overlap at the top edge (y < 706)
    if (y > 704 && inPoly(x, y, muzzlePoly) && y < 825) continue;

    // Avoid inner eyeball openings
    if (distSq(x, y, 486, 482) < 620 || distSq(x, y, 692, 484) < 620) continue;

    let ang = getCowFurAngle(x, y) + random(-5, 5);
    let dWhorl = sqrt(distSq(x, y, 588, 456));
    let len = y < 345 ? random(14, 24) : (dWhorl < 28 ? random(5, 10) : random(8, 16));
    if (y > 665 && y < 715) len = random(5, 10); // Short velvety muzzle transition hairs

    let mot = getMottlingIntensity(x, y);
    let dBridge = abs(x - 588);
    let col;

    if (mot > 0.42 && random() < 0.75) {
      col = random(["#5c646e", "#727b84", "#8a939c"]);
    } else if (y > 820) {
      col = random(["#545c66", "#6e7780", "#8e969e", "#c99b68"]);
    } else if (dBridge > 68) {
      col = random(["#7e8791", "#969fa8", "#b2bac2", "#cfd4da"]);
    } else {
      col = random(["#b8bfc7", "#d0d5da", "#e5e2da"]);
    }

    let x2 = x + cos(ang) * len;
    let y2 = y + sin(ang) * len;
    let bName = random() < 0.5 ? "2H" : "pardaz_micro";
    strokeSegment(bName, col, random(0.45, 0.85), x, y, x2, y2);
  }

  // Pass B: Luminous top-coat white & ivory fur strands (strand-by-strand brilliance)
  for (let i = 0; i < 2100; i++) {
    let x = random(432, 744);
    let y = random(290, 866);
    if (!inPoly(x, y, headPoly)) continue;
    if (y > 706 && inPoly(x, y, muzzlePoly) && y < 825) continue;
    if (distSq(x, y, 486, 482) < 620 || distSq(x, y, 692, 484) < 620) continue;

    let ang = getCowFurAngle(x, y) + random(-4, 4);
    let dWhorl = sqrt(distSq(x, y, 588, 456));
    let len = y < 345 ? random(13, 25) : (dWhorl < 26 ? random(4, 9) : random(7, 15));
    if (y > 665 && y < 715) len = random(4, 9);

    let mot = getMottlingIntensity(x, y);
    let dBridge = abs(x - 588);
    let col;

    if (dBridge < 52 && y < 685 && mot < 0.35) {
      col = random(["#ffffff", "#ffffff", "#faf6ee", "#f2ede2"]);
    } else if (mot > 0.48 && random() < 0.5) {
      col = random(["#9aa2ac", "#b5bdc4", "#dce0e4"]);
    } else {
      col = random(["#ffffff", "#f7f3eb", "#e6e3dc", "#d4d9df"]);
    }

    let mx = x + cos(ang) * len * 0.5 + random(-1, 1);
    let my = y + sin(ang) * len * 0.5 + random(-1, 1);
    let x2 = x + cos(ang) * len;
    let y2 = y + sin(ang) * len;
    strokeCurve("pardaz_hair", col, random(0.55, 1.05), [[x, y], [mx, my], [x2, y2]], 0.45);
  }

  // Pass C: Extra-detailed central forehead whorl (cowlick) & fluffy poll crown tuft
  for (let i = 0; i < 220; i++) {
    let r = random(2, 48);
    let a = random(0, 360);
    let x = 588 + cos(a) * r;
    let y = 456 + sin(a) * r;
    let fAng = getCowFurAngle(x, y);
    let len = map(r, 0, 48, 5, 14);
    let col = r < 14
      ? random(["#68707a", "#8e96a0", "#ffffff", "#f5f0e6"])
      : random(["#ffffff", "#faf6ee", "#cfd5dc"]);
    strokeSegment("pardaz_hair", col, random(0.5, 0.95),
      x, y, x + cos(fAng) * len, y + sin(fAng) * len);
  }

  // Fluffy crown tuft hairs rising along the top of the poll (y ~ 292)
  for (let i = 0; i < 160; i++) {
    let x = random(520, 656);
    let y = random(290, 326);
    let ang = -90 + (x - 588) * 0.55 + random(-10, 10);
    let len = random(14, 26);
    let col = random(["#ffffff", "#faf6ee", "#e8e2d5", "#c5cbd2"]);
    strokeCurve("pardaz_hair", col, random(0.65, 1.1), [
      [x, y],
      [x + cos(ang) * len * 0.5, y + sin(ang) * len * 0.5],
      [x + cos(ang) * len, y + sin(ang) * len]
    ], 0.5);
  }
}

