  // Deeper coral-rose & plum-pink anatomical volume on lower and side muzzle
  fillShape([
    [470, 744], [525, 765], [588, 775], [651, 765], [706, 744],
    [696, 798], [666, 830], [625, 840], [588, 836],
    [551, 840], [510, 830], [480, 798]
  ], "#d17685", 165, 0.1, 0.4, 0.35);

  // Lower margin shadow of upper lip and central philtrum cleft
  fillShape([
    [495, 808], [550, 818], [588, 812], [626, 818], [681, 808],
    [666, 830], [625, 840], [588, 836], [551, 840], [510, 830]
  ], "#8f3848", 185, 0.08, 0.4, 0.35);

  // Soft sunlit pink dome across upper-center nose pad
  fillShape([
    [535, 696], [641, 696], [648, 755], [588, 768], [528, 755]
  ], "#fad4da", 170, 0.1, 0.25, 0.4);

  // 2. Mottled grey-pink mucocutaneous junction along upper border (y = 682..722)
  let junctionSpots = [
    { x: 505, y: 704, r: 9, c: "#6e6870" },
    { x: 528, y: 696, r: 12, c: "#787078" },
    { x: 552, y: 702, r: 8, c: "#8a7882" },
    { x: 576, y: 693, r: 10, c: "#706870" },
    { x: 604, y: 695, r: 11, c: "#756d75" },
    { x: 628, y: 703, r: 9, c: "#85747d" },
    { x: 652, y: 697, r: 13, c: "#6b636b" },
    { x: 676, y: 708, r: 10, c: "#7d6e76" },
    { x: 488, y: 722, r: 8, c: "#8c7580" },
    { x: 688, y: 724, r: 9, c: "#8c7580" }
  ];
  for (let s of junctionSpots) {
    let pts = [];
    for (let a = 0; a < 360; a += 60) {
      pts.push([s.x + cos(a) * s.r * random(0.8, 1.2), s.y + sin(a) * s.r * random(0.7, 1.1)]);
    }
    fillShape(pts, s.c, 150, 0.12, 0.4, 0.4);
  }

  // 3. Pebbled wet skin texture (nasolabial dermatoglyphics)
  for (let i = 0; i < 680; i++) {
    let x = random(474, 702);
    let y = random(694, 834);
    if (!inPoly(x, y, muzzlePoly)) continue;
    // Skip nostril centers
    if (distSq(x, y, 514, 754) < 750 || distSq(x, y, 662, 754) < 750) continue;

    let col = y < 765
      ? random(["#c96b7b", "#de8a98", "#f7d4da", "#b85c6c"])
      : random(["#a84a5b", "#c46474", "#e8a5b0", "#7d2d3c"]);
    strokeSegment("pardaz_stipple", col, random(0.5, 0.85),
      x, y, x + random(-2.5, 2.5), y + random(-2.5, 2.5));
  }

  // Central philtrum groove (vertical indentation dividing upper lip)
  strokeCurve("pardaz_hair", "#7a2938", 1.2, [[588, 725], [588, 782], [588, 835]], 0.3);
  strokeCurve("wet_gloss", "#fce2e6", 0.75, [[590, 735], [590, 782], [590, 828]], 0.3);

  // Fine white hairs overlapping the upper pink muzzle border
  for (let i = 0; i < 260; i++) {
    let x = random(476, 700);
    let y = random(682, 714);
    let ang = 90 + (x - 588) * 0.22 + random(-8, 8);
    let len = random(6, 14);
    let col = random(["#ffffff", "#f5f0e8", "#d4cfd4", "#9e969c"]);
    strokeSegment("pardaz_hair", col, random(0.55, 0.95),
      x, y, x + cos(ang) * len, y + sin(ang) * len);
  }

  // 4. LEFT AND RIGHT WET NOSTRILS (Comma-shaped cavities with fleshy alar wings)
  for (let side = -1; side <= 1; side += 2) {
    let nx = side === -1 ? 512 : 664;
    let ny = 754;

    // Outer shaded vestibule of nostril
    let vestibule = side === -1
      ? [[480, 732], [505, 716], [538, 728], [548, 758], [532, 792], [496, 798], [476, 768]]
      : [[696, 732], [671, 716], [638, 728], [628, 758], [644, 792], [680, 798], [700, 768]];
    fillShape(vestibule, "#9e3b4c", 185, 0.08, 0.4, 0.38);

    // Deep crimson-plum cavity
    let cavityMid = side === -1
      ? [[486, 736], [508, 722], [534, 736], [540, 764], [524, 786], [496, 786], [482, 762]]
      : [[690, 736], [668, 722], [642, 736], [636, 764], [652, 786], [680, 786], [694, 762]];
    washShape(cavityMid, "#4f101d", 240, 0.38);

    // Pitch-dark wet interior aperture (comma crescent)
    let aperture = side === -1
      ? [[490, 742], [508, 728], [528, 740], [522, 762], [532, 778], [512, 782], [490, 764]]
      : [[686, 742], [668, 728], [648, 740], [654, 762], [644, 778], [664, 782], [686, 764]];
    washShape(aperture, "#170307", 255, 0.35);

    // Fleshy pink medial alar fold curling into the inner side of the nostril
    let alarWing = side === -1
      ? [[520, 730], [542, 736], [546, 758], [530, 768], [516, 752]]
      : [[656, 730], [634, 736], [630, 758], [646, 768], [660, 752]];
    fillShape(alarWing, "#e694a2", 220, 0.05, 0.3, 0.4);
    fillShape(alarWing, "#fad2d9", 140, 0.04, 0.2, 0.4);

    // Wet specular highlights on nostril rims & alar wing
    strokeCurve("wet_gloss", "#ffffff", 1.15, side === -1
      ? [[522, 740], [534, 748], [528, 762]]
      : [[654, 740], [642, 748], [648, 762]], 0.5);

    // Glistening moisture pool at the lower rim of each nostril
    strokeCurve("wet_gloss", "#ffffff", 1.35, side === -1
      ? [[494, 778], [512, 786], [530, 780]]
      : [[682, 778], [664, 786], [646, 780]], 0.5);

    strokeCurve("pardaz_hair", "#ffdbe2", 0.9, side === -1
      ? [[486, 740], [482, 760], [494, 782]]
      : [[690, 740], [694, 760], [682, 782]], 0.5);
  }

  // 5. Dewy specular moisture beads across the wet pink nose pad & lower lip
  for (let i = 0; i < 95; i++) {
    let x = random(485, 690);
    let y = random(708, 826);
    if (distSq(x, y, 512, 754) < 850 || distSq(x, y, 664, 754) < 850) continue;
    let len = random(1.5, 4.5);
    let col = random() < 0.45 ? "#ffffff" : "#ffe6eb";
    strokeSegment("wet_gloss", col, random(0.45, 0.95), x, y, x + len, y + random(-1, 1));
  }

  // Wet glistening highlight along the lower lip margin
  strokeCurve("wet_gloss", "#ffffff", 1.1, [[535, 832], [588, 835], [641, 832]], 0.4);
}

