// 9. SOULFUL DARK EYES & LONG SWEEPING EYELASHES
// ============================================================================

function drawEyesAndEyelashes() {
  for (let side = -1; side <= 1; side += 2) {
    let cx = side === -1 ? 488 : 688;
    let cy = 482;

    // 1. Orbital socket shading (soft slate-grey recess around eyelids)
    let socketPts = side === -1
      ? [[442, 462], [482, 440], [532, 474], [536, 506], [492, 524], [448, 498]]
      : [[734, 462], [694, 440], [644, 474], [640, 506], [684, 524], [728, 498]];
    fillShape(socketPts, "#7c848e", 145, 0.1, 0.4, 0.38);

    // 2. Concentric wrinkled eyelid folds (characteristic of sacred Indian cows)
    for (let f = 1; f <= 4; f++) {
      let offY = f * 6.5;
      let uPts = side === -1
        ? [[446, 472 - offY * 0.5], [484, 452 - offY], [528, 484 - offY * 0.4]]
        : [[730, 472 - offY * 0.5], [692, 452 - offY], [648, 484 - offY * 0.4]];
      strokeCurve("2H", f <= 2 ? "#495058" : "#767e88", 0.85, uPts, 0.5);
      // Soft highlight ridge between eyelid folds
      strokeCurve("pardaz_hair", "#f2efe8", 0.8, [
        [uPts[0][0], uPts[0][1] + 2.5],
        [uPts[1][0], uPts[1][1] + 2.5],
        [uPts[2][0], uPts[2][1] + 2.5]
      ], 0.5);
    }

    // Lower eyelid creases
    for (let f = 1; f <= 3; f++) {
      let offY = f * 6;
      let lPts = side === -1
        ? [[450, 484 + offY * 0.5], [488, 504 + offY], [530, 498 + offY * 0.4]]
        : [[726, 484 + offY * 0.5], [688, 504 + offY], [646, 498 + offY * 0.4]];
      strokeCurve("2H", f === 1 ? "#495058" : "#7e8690", 0.75, lPts, 0.5);
    }

    // 3. Dark pigmented eyelid rim (natural kohl rim)
    let rimPts = side === -1
      ? [[446, 474], [468, 456], [502, 460], [532, 492], [504, 506], [468, 498]]
      : [[730, 474], [708, 456], [674, 460], [644, 492], [672, 506], [708, 498]];
    washShape(rimPts, "#1f181b", 255, 0.35);

    // 4. Eyeball (deep liquid obsidian-umber iris and pupil)
    let eyeOpen = side === -1
      ? [[452, 475], [472, 461], [500, 464], [524, 490], [500, 501], [470, 494]]
      : [[724, 475], [704, 461], [676, 464], [652, 490], [676, 501], [706, 494]];
    washShape(eyeOpen, "#2e1812", 255, 0.38);

    // Warm chestnut-amber lower iris glow
    let lowerGlow = side === -1
      ? [[464, 484], [488, 482], [514, 490], [498, 499], [472, 493]]
      : [[712, 484], [688, 482], [662, 490], [678, 499], [704, 493]];
    fillShape(lowerGlow, "#6e3820", 180, 0.05, 0.2, 0.4);

    // Deep pitch-black pupil & upper iris shadow
    let pupilPts = side === -1
      ? [[458, 474], [474, 462], [500, 465], [516, 484], [494, 490], [468, 486]]
      : [[718, 474], [702, 462], [676, 465], [660, 484], [682, 490], [708, 486]];
    washShape(pupilPts, "#0c0708", 255, 0.38);

    // Medial tear caruncle (tiny wet rose-pink corner at inner eye)
    let tearDuct = side === -1
      ? [[518, 486], [530, 492], [520, 498]]
      : [[658, 486], [646, 492], [656, 498]];
    washShape(tearDuct, "#b85a68", 230, 0.3);

    // 5. Crisp wet corneal reflections (sky & devotional light catchlights)
    let hx = side === -1 ? 476 : 684;
    let hy = 471;
    // Soft jade-blue sky sheen on upper cornea
    washShape([
      [hx - 6, hy - 3], [hx + 8, hy - 2], [hx + 6, hy + 5], [hx - 7, hy + 4]
    ], "#cbeae4", 160, 0.2);
    // Brilliant white primary catchlight
    strokeSegment("wet_gloss", "#ffffff", 1.6, hx - 4, hy - 1, hx + 4, hy + 1);
    strokeSegment("wet_gloss", "#ffffff", 1.1, hx + 11, hy + 3, hx + 13, hy + 4);

    // Glistening tear film along lower eyelid margin
    strokeCurve("wet_gloss", "#f2f7f5", 0.85, side === -1
      ? [[466, 495], [492, 501], [518, 494]]
      : [[710, 495], [684, 501], [658, 494]], 0.4);

    // 6. LONG SWEEPING EYELASHES (strand by strand, dark roots to silvery-cream tips)
    let numLashes = 34;
    for (let i = 0; i < numLashes; i++) {
      let t = i / (numLashes - 1);
      // Sample along upper eyelid arch
      let lx, ly;
      if (side === -1) {
        lx = lerp(448, 522, t);
        ly = lerp(474, 488, t) - sin(t * 180) * 17;
      } else {
        lx = lerp(728, 654, t);
        ly = lerp(474, 488, t) - sin(t * 180) * 17;
      }

      // Eyelashes sweep outward and gently downward/upward at the tips
      let lashLen = map(sin(t * 170), 0, 1, 14, 34) * random(0.88, 1.12);
      let baseAng = side === -1
        ? lerp(195, 135, t) + random(-5, 5)
        : lerp(-15, 45, t) + random(-5, 5);

      let mx = lx + cos(baseAng) * lashLen * 0.55;
      let my = ly + sin(baseAng) * lashLen * 0.55 + 3;
      let ex = lx + cos(baseAng + side * 12) * lashLen;
      let ey = ly + sin(baseAng + side * 12) * lashLen + 2;

      // Dark root shadow of eyelash
      strokeCurve("eyelash_fine", "#1c1618", 0.9, [
        [lx, ly], [mx, my], [(mx + ex) * 0.5, (my + ey) * 0.5]
      ], 0.45);

      // Luminous silvery-cream / white eyelash shaft & tip
      let tipCol = random(["#ffffff", "#faf5eb", "#e6dfd3", "#cfc7bc"]);
      strokeCurve("eyelash_fine", tipCol, random(0.65, 1.0), [
        [lx + cos(baseAng) * 3, ly + sin(baseAng) * 3],
        [mx, my],
        [ex, ey]
      ], 0.5);
    }

    // Delicate lower eyelashes
    for (let i = 0; i < 16; i++) {
      let t = i / 15;
      let lx = side === -1 ? lerp(456, 516, t) : lerp(720, 660, t);
      let ly = lerp(486, 496, t) + sin(t * 180) * 9;
      let ang = side === -1 ? lerp(145, 100, t) : lerp(35, 80, t);
      let len = random(8, 16);
      strokeCurve("pardaz_hair", random(["#f5efe6", "#cfc8be", "#7a726c"]), 0.6, [
        [lx, ly],
        [lx + cos(ang) * len * 0.5, ly + sin(ang) * len * 0.5],
        [lx + cos(ang) * len, ly + sin(ang) * len]
      ], 0.4);
    }
  }
}

// ============================================================================
// 10. LUSH MARIGOLD GARLAND SLUNG BENEATH THE JAW
// ============================================================================

function drawMarigoldGarland() {
  // Garland catenary path slung beneath the jaw & looping across the throat
  let upperLoop = [];
  let numUpper = 11;
  for (let i = 0; i < numUpper; i++) {
    let t = i / (numUpper - 1);
    let ang = lerp(172, 8, t);
    let x = 600 + cos(ang) * 186;
    let y = 716 + sin(ang) * 192;
    let r = map(sin(t * 180), 0, 1, 34, 46);
    upperLoop.push({ x, y, r, tier: 1 });
  }

  // Secondary lower festoon strand cradling beneath the primary garland
  let lowerLoop = [];
  let numLower = 7;
  for (let i = 0; i < numLower; i++) {
    let t = i / (numLower - 1);
    let ang = lerp(148, 32, t);
    let x = 600 + cos(ang) * 165;
    let y = 785 + sin(ang) * 182;
    let r = map(sin(t * 180), 0, 1, 32, 43);
    lowerLoop.push({ x, y, r, tier: 0 });
  }

  let allBlooms = lowerLoop.concat(upperLoop);

  // 1. Deep cast shadow of the garland onto the white dewlap
  for (let b of allBlooms) {
    let shPts = [];
    for (let a = 0; a < 360; a += 40) {
      shPts.push([b.x + 6 + cos(a) * (b.r + 8), b.y + 14 + sin(a) * (b.r + 8)]);
    }
    fillShape(shPts, "#364048", 95, 0.14, 0.35, 0.4);
  }

  // 2. Emerald marigold leaves & sepals tucked around the garland
  for (let i = 0; i < allBlooms.length; i++) {
    let b = allBlooms[i];
    for (let k = 0; k < 3; k++) {
      let la = random(0, 360);
      let lx = b.x + cos(la) * (b.r * 0.78);
      let ly = b.y + sin(la) * (b.r * 0.78);
      let lLen = random(24, 38);
      let lWid = random(8, 13);
      let px = -sin(la) * lWid;
      let py = cos(la) * lWid;
      let tx = lx + cos(la) * lLen;
      let ty = ly + sin(la) * lLen;

      let leafPoly = [
        [lx, ly],
        [(lx + tx) * 0.5 + px, (ly + ty) * 0.5 + py],
        [tx, ty],
        [(lx + tx) * 0.5 - px, (ly + ty) * 0.5 - py]
      ];
      washShape(leafPoly, "#143820", 235, 0.3);
      fillShape(leafPoly, "#285c36", 160, 0.05, 0.3, 0.3);
      // Leaf midrib vein
      strokeSegment("pardaz_hair", "#6ca675", 0.75, lx, ly, tx, ty);
    }
  }

  // 3. Sacred Crimson & Gold Silk Tassel hanging from the bottom center of the garland
  let tx = 596, ty = 968;
  washShape([
    [tx - 10, ty], [tx + 10, ty], [tx + 22, 1024], [tx - 22, 1024]
  ], "#8f161c", 240, 0.2);
  for (let i = 0; i < 36; i++) {
    let sx = tx + random(-8, 8);
    let ex = tx + random(-20, 20);
    let col = random(["#b81d24", "#d9323a", "#f5b82e", "#700e13"]);
    strokeSegment("pardaz_hair", col, 0.9, sx, ty, ex, 1024);
  }
  // Gold zari binding ring on tassel
  for (let y = ty - 2; y <= ty + 10; y += 3) {
    strokeSegment("gouache_petal", "#f7c137", 1.1, tx - 11, y, tx + 11, y);
  }

  // 4. Render each Marigold Blossom in hyperreal Pahari detail
  // Sort so central and upper blossoms overlap naturally
  allBlooms.sort((a, b) => (a.tier - b.tier) || (a.y - b.y));

  for (let idx = 0; idx < allBlooms.length; idx++) {
    let b = allBlooms[idx];
    // Alternate slightly between deep vermilion-orange marigolds and golden-saffron marigolds
    let isGold = (idx % 2 === 0);
    drawSingleMarigold(b.x, b.y, b.r, isGold);
  }
}

function drawSingleMarigold(cx, cy, radius, isGold) {
  // Base dark crimson-rust crevice shadow of the globular flower head
  let basePts = [];
  for (let a = 0; a < 360; a += 20) {
    let r = radius * (0.94 + 0.08 * sin(a * 5));
    basePts.push([cx + cos(a) * r, cy + sin(a) * r]);
  }
  washShape(basePts, isGold ? "#8a220a" : "#6b1407", 250, 0.35);

  // Palettes for the 4 concentric tiers of ruffled marigold petals
  let tierPalettes = isGold
    ? [
        ["#b8350e", "#d44d12", "#9e2609"], // Outer shadow tier
        ["#e86814", "#f58216", "#d95610"], // Mid-outer tier
        ["#fa9f1b", "#fcb426", "#f28c18"], // Mid-inner sunlit tier
        ["#ffd13b", "#ffe566", "#f7b520"]  // Inner crown & central ruffle
      ]
    : [
        ["#851a08", "#a3260c", "#6e1206"], // Outer shadow tier
        ["#c73c10", "#de5014", "#b02e0c"], // Mid-outer tier
        ["#ed6a15", "#f7841a", "#d95412"], // Mid-inner sunlit tier
        ["#fca822", "#ffc738", "#f08c19"]  // Inner crown & central ruffle
      ];

  // Draw ruffled, cupped petals from outer ring to center
  let rings = [
    { rFrac: 0.92, count: 22, pLen: radius * 0.32, pal: tierPalettes[0] },
    { rFrac: 0.70, count: 18, pLen: radius * 0.28, pal: tierPalettes[1] },
    { rFrac: 0.46, count: 14, pLen: radius * 0.24, pal: tierPalettes[2] },
    { rFrac: 0.22, count: 9,  pLen: radius * 0.18, pal: tierPalettes[3] }
  ];

  for (let rIdx = 0; rIdx < rings.length; rIdx++) {
    let ring = rings[rIdx];
    let ringR = radius * ring.rFrac;

    for (let i = 0; i < ring.count; i++) {
      let a = (i * 360 / ring.count) + rIdx * 17 + random(-6, 6);
      // Shift slightly toward upper-left devotional light source
      let px = cx + cos(a) * ringR - 1.5;
      let py = cy + sin(a) * ringR - 2.0;

      // Each marigold petal is a crinkled, scalloped fan/crescent
      let tang = a + 90;
      let w = ring.pLen * random(0.48, 0.68);
      let h = ring.pLen * random(0.45, 0.65);

      let x1 = px + cos(tang) * w;
      let y1 = py + sin(tang) * w;
      let x2 = px + cos(a) * h + cos(tang) * (w * 0.35);
      let y2 = py + sin(a) * h + sin(tang) * (w * 0.35);
      let x3 = px + cos(a) * h - cos(tang) * (w * 0.35);
      let y3 = py + sin(a) * h - sin(tang) * (w * 0.35);
      let x4 = px - cos(tang) * w;
      let y4 = py - sin(tang) * w;

      // Dark crevice shadow under each ruffled petal fold
      strokeCurve("gouache_petal", isGold ? "#7a1c08" : "#591005", 1.25, [
        [x1, y1 + 2], [x2, y2 + 2], [x3, y3 + 2], [x4, y4 + 2]
      ], 0.5);

      // Vibrant gouache petal body
      let pCol = random(ring.pal);
      strokeCurve("gouache_petal", pCol, random(1.15, 1.55), [
        [x1, y1], [x2, y2], [x3, y3], [x4, y4]
      ], 0.55);

      // Crisp sunlit saffron/gold edge highlight along the crinkled rim of the petal
      let rimCol = isGold
        ? (rIdx >= 2 ? "#fff29e" : "#ffd247")
        : (rIdx >= 2 ? "#ffe066" : "#fca624");
      strokeCurve("pardaz_hair", rimCol, 0.85, [
        [x1, y1], [x2, y2], [x3, y3], [x4, y4]
      ], 0.55);
    }
  }

  // Tightly packed central floret bud
  for (let i = 0; i < 8; i++) {
    let a = i * 45 + random(-10, 10);
    let x1 = cx + cos(a) * 3;
    let y1 = cy + sin(a) * 3;
    let x2 = cx + cos(a + 70) * 8;
    let y2 = cy + sin(a + 70) * 8;
    strokeSegment("gouache_petal", isGold ? "#ffe875" : "#ffba2e", 0.95, x1, y1, x2, y2);
    strokeSegment("pardaz_micro", "#751908", 0.7, x1, y1 + 1.5, x2, y2 + 1.5);
  }
}

// ============================================================================
// 11. WHISKERS & DEVOTIONAL HIGHLIGHTS
// ============================================================================

function drawWhiskersAndFinalTouches() {
  // Sparse, delicate sensory vibrissae (whiskers) around the snout, chin, and upper brow
  let whiskerRoots = [
    { x: 478, y: 722, ang: 168, len: 42 },
    { x: 472, y: 758, ang: 162, len: 52 },
    { x: 478, y: 792, ang: 154, len: 48 },
    { x: 496, y: 822, ang: 145, len: 38 },
    { x: 698, y: 722, ang: 12,  len: 42 },
    { x: 704, y: 758, ang: 18,  len: 52 },
    { x: 698, y: 792, ang: 26,  len: 48 },
    { x: 680, y: 822, ang: 35,  len: 38 },
    // Tactile brow hairs above eyes
    { x: 478, y: 442, ang: 215, len: 36 },
    { x: 492, y: 438, ang: 225, len: 32 },
    { x: 698, y: 442, ang: -35, len: 36 },
    { x: 684, y: 438, ang: -45, len: 32 }
  ];

  for (let w of whiskerRoots) {
    let mx = w.x + cos(w.ang) * w.len * 0.5;
    let my = w.y + sin(w.ang) * w.len * 0.5 + 4;
    let ex = w.x + cos(w.ang) * w.len;
    let ey = w.y + sin(w.ang) * w.len + 12;
    strokeCurve("eyelash_fine", "#ffffff", 0.72, [[w.x, w.y], [mx, my], [ex, ey]], 0.5);
  }
}

