  }

  // 4. Delicate Crimson & Emerald Creeper Vine along the Saffron Band
  for (let pos = 168; pos <= 1012; pos += 28) {
    let dir = ((pos / 28) % 2 === 0) ? 1 : -1;
    // Top & bottom saffron vine segment
    strokeCurve("rotring", "#7a181d", 0.55, [
      [pos, 164 - dir * 3], [pos + 14, 164 + dir * 3], [pos + 28, 164 - dir * 3]
    ], 0.5);
    strokeSegment("gouache_petal", "#a81d24", 0.75, pos + 14, 164 - dir * 2, pos + 16, 164 - dir * 2);

    strokeCurve("rotring", "#7a181d", 0.55, [
