function drawFrameBox(inset, col, bName, weight) {
  let x1 = inset, y1 = inset, x2 = 1200 - inset, y2 = 1200 - inset;
  strokeSegment(bName, col, weight, x1, y1, x2, y1);
  strokeSegment(bName, col, weight, x2, y1, x2, y2);
  strokeSegment(bName, col, weight, x2, y2, x1, y2);
  strokeSegment(bName, col, weight, x1, y2, x1, y1);
}

function drawBorderFloret(x, y) {
  strokeSegment("wet_gloss", "#ffd859", 0.85, x - 3.5, y, x - 2, y);
  strokeSegment("wet_gloss", "#ffd859", 0.85, x + 2, y, x + 3.5, y);
  strokeSegment("wet_gloss", "#ffd859", 0.85, x, y - 3.5, x, y - 2);
  strokeSegment("wet_gloss", "#ffd859", 0.85, x, y + 2, x, y + 3.5);
  strokeSegment("wet_gloss", "#fff8eb", 0.75, x - 0.5, y, x + 0.5, y);
}

