function drawMarginFloralSprigs() {
  let sprigCoords = [];

  // Top & Bottom Margin Sprigs (2 staggered rows for lyrical Pahari rhythm)
  for (let i = 0; i < 9; i++) {
    let x = map(i, 0, 8, 66, 1134);
    let yTop = (i % 2 === 0) ? 54 : 78;
    let yBot = (i % 2 === 0) ? 1146 : 1122;
    sprigCoords.push({ x: x, y: yTop, tilt: (i % 2 === 0 ? -12 : 12), variant: i % 3 });
    sprigCoords.push({ x: x, y: yBot, tilt: (i % 2 === 0 ? 14 : -14), variant: (i + 1) % 3 });
  }

  // Left & Right Margin Sprigs (between corners)
  for (let i = 1; i < 8; i++) {
    let y = map(i, 0, 8, 66, 1134);
    let xLeft = (i % 2 === 0) ? 54 : 78;
    let xRight = (i % 2 === 0) ? 1146 : 1122;
    sprigCoords.push({ x: xLeft, y: y, tilt: (i % 2 === 0 ? -15 : 15), variant: (i + 2) % 3 });
    sprigCoords.push({ x: xRight, y: y, tilt: (i % 2 === 0 ? 15 : -15), variant: i % 3 });
  }

  for (let s of sprigCoords) {
    drawTinyFloralSprig(s.x, s.y, s.tilt, s.variant);
  }
}

function drawTinyFloralSprig(cx, cy, tilt, variant) {
  let stemAng = -90 + tilt;

  // Slender curved stem in dark olive-green & gold
  let bx = cx - cos(stemAng) * 16;
  let by = cy - sin(stemAng) * 16;
  let mx = cx + cos(stemAng + 14) * 2;
  let my = cy + sin(stemAng + 14) * 2;
  let tx = cx + cos(stemAng) * 14;
  let ty = cy + sin(stemAng) * 14;

  strokeCurve("rotring", "#245436", 0.75, [[bx, by], [mx, my], [tx, ty]], 0.5);
  strokeCurve("pardaz_hair", "#d4a438", 0.55, [[bx + 1, by], [mx + 1, my], [tx + 1, ty]], 0.5);

  // Two side branchlets for tiny buds
  let lx = mx + cos(stemAng - 42) * 12;
  let ly = my + sin(stemAng - 42) * 12;
  let rx = mx + cos(stemAng + 46) * 11;
  let ry = my + sin(stemAng + 46) * 11;
  strokeSegment("rotring", "#245436", 0.6, mx, my, lx, ly);
  strokeSegment("rotring", "#245436", 0.6, mx, my + 3, rx, ry);

  // 4 Tiny Emerald Leaves at the base of the stem
  let leafAngles = [stemAng - 65, stemAng + 68, stemAng - 110, stemAng + 112];
  for (let i = 0; i < leafAngles.length; i++) {
    let la = leafAngles[i];
    let sx = (i < 2) ? mx : (bx + mx) * 0.5;
    let sy = (i < 2) ? my : (by + my) * 0.5;
    let lLen = (i < 2) ? 9 : 7;
    let ex = sx + cos(la) * lLen;
    let ey = sy + sin(la) * lLen;
    strokeSegment("gouache_petal", "#1e5c3a", 0.9, sx, sy, ex, ey);
    strokeSegment("pardaz_micro", "#7bc488", 0.55, sx, sy, ex, ey);
  }

  // Blossom color palette based on variant (Ivory-Crimson, Carmine-Gold, Saffron-Ruby)
  let petalCol, centerCol, budCol;
  if (variant === 0) {
    petalCol = "#fff8eb"; centerCol = "#b81d26"; budCol = "#d93842";
  } else if (variant === 1) {
    petalCol = "#b81d26"; centerCol = "#ffd447"; budCol = "#fff8eb";
  } else {
    petalCol = "#f7b229"; centerCol = "#9e161e"; budCol = "#fff8eb";
  }

  // Main 5-petaled miniature blossom at stem apex (tx, ty)
  for (let p = 0; p < 5; p++) {
    let pa = stemAng + p * 72;
    let px1 = tx + cos(pa) * 2.5;
    let py1 = ty + sin(pa) * 2.5;
    let px2 = tx + cos(pa) * 6.5;
    let py2 = ty + sin(pa) * 6.5;
    strokeSegment("gouache_petal", petalCol, 1.05, px1, py1, px2, py2);
    strokeSegment("rotring", "#5c181b", 0.35, px1, py1, px2, py2);
  }
  // Jewel center of blossom
  strokeSegment("wet_gloss", centerCol, 0.95, tx - 0.8, ty, tx + 0.8, ty);

  // Two tiny side buds at (lx, ly) and (rx, ry)
  strokeSegment("gouache_petal", budCol, 0.85, lx, ly, lx + cos(stemAng - 42) * 3.5, ly + sin(stemAng - 42) * 3.5);
  strokeSegment("gouache_petal", budCol, 0.85, rx, ry, rx + cos(stemAng + 46) * 3.5, ry + sin(stemAng + 46) * 3.5);
}

