// ============================================================================
// PART 1: 3D SCULPTURAL CLOTH ENGINE & DEPTH / SHADOW BUFFERS
// ============================================================================

function initClothBuffers() {
  const N = W * H;
  zBuf = new Float32Array(N);
  nzBuf = new Float32Array(N);
  shadeBuf = new Float32Array(N);
  castBuf = new Float32Array(N);
  curvBuf = new Float32Array(N);
  layerBuf = new Int8Array(N);

  for (let i = 0; i < N; i++) {
    zBuf[i] = -1e6;
    nzBuf[i] = 1.0;
    shadeBuf[i] = 0.0;
    castBuf[i] = 0.0;
    curvBuf[i] = 0.0;
    layerBuf[i] = -1;
  }

  const SN = SW * SH;
  sZBuf = new Float32Array(SN);
  sShadowBuf = new Float32Array(SN);
  sAOBuf = new Float32Array(SN);
  for (let i = 0; i < SN; i++) sZBuf[i] = -1e6;
}

// Evaluate a single sculptural fold primitive at (u, v)
function evalFoldPrimitive(u, v, f, out) {
  const dx = f.u1 - f.u0;
  const dy = f.v1 - f.v0;
  const len = Math.hypot(dx, dy);
  const tx = dx / len;
  const ty = dy / len;
  const nx = -ty;
  const ny = tx;

  const s = ((u - f.u0) * tx + (v - f.v0) * ty) / len;
  if (s < -0.22 || s > 1.22) return;

  // Smooth longitudinal envelope
  let env = 1.0;
  if (s < 0.12) {
    const k = Math.max(0, (s + 0.22) / 0.34);
    env = k * k * (3 - 2 * k);
  } else if (s > 0.88) {
    const k = Math.max(0, (1.22 - s) / 0.34);
    env = k * k * (3 - 2 * k);
  }

  const sClamped = Math.max(0, Math.min(1, s));
  const w = f.w0 + (f.w1 - f.w0) * sClamped;
  const h = (f.h0 + (f.h1 - f.h0) * sClamped) * env;

  const bendOff = f.bend * 4.0 * sClamped * (1.0 - sClamped);
  const d = (u - f.u0) * nx + (v - f.v0) * ny - bendOff;
  const t = d / w;

  if (Math.abs(t) > 3.2) return;

  const t2 = t * t;
  const signLean = f.lean >= 0 ? 1 : -1;

  // Asymmetric ridge height + valley trough on leaning side
  const asym = 1.0 - 0.18 * f.lean * t / (1.0 + 0.35 * t2);
  const ridge = h * Math.exp(-t2 * (0.95 + 0.28 * f.pinch) * asym);
  const dt = t - 1.12 * signLean;
  const trough = -f.trough * h * Math.exp(-dt * dt * 1.65);
  const dz = ridge + trough;

  // Lateral displacement: pulls fabric into the pinch and leans the crest over the valley
  const overhangDisp = f.lean * h * 0.56 * Math.exp(-t2 * 0.88);
  const pinchPull = -f.pinch * w * 0.24 * t * Math.exp(-t2 * 1.15);
  const shift = overhangDisp + pinchPull;

  out.x += shift * nx;
  out.y += shift * ny;
  out.z += dz;
  // Track local valley concavity for ambient occlusion in creases
  out.concavity += Math.max(0, -trough * 1.6 + (Math.abs(t - 0.72 * signLean) < 0.55 ? h * 0.22 * Math.exp(-Math.pow((t - 0.72 * signLean) / 0.38, 2)) : 0));
}

// Lower boundary of Layer 1 (Turned-Down Top Sheet Cuff)
function getCuffEdgeV(u) {
  return (
    430 -
    36 * Math.sin(u * 0.0041 + 0.35) +
    54 * Math.sin(u * 0.0026 - 1.05) +
    18 * Math.cos(u * 0.0082 + 0.2)
  );
}

// Lower boundary of Layer 0 (Dented Pillow Edge)
function getPillowEdgeV(u) {
  const dentPull = -30 * Math.exp(-Math.pow((u - 535) / 155, 2));
  return (
    262 +
    46 * Math.sin(u * 0.0031 + 0.25) +
    dentPull +
    20 * Math.sin(u * 0.0074 - 0.65)
  );
}

// Evaluate 3D position (x, y, z) for a given cloth layer and UV coordinate
function evalClothPos(layer, u, v, out) {
  out.x = u;
  out.y = v;
  out.z = 0;
  out.concavity = 0;
  out.valid = true;

  if (layer === 2) {
    // LAYER 2: Main Rumpled Sheet
    for (let i = 0; i < MAIN_FOLDS.length; i++) {
      evalFoldPrimitive(u, v, MAIN_FOLDS[i], out);
    }
    // Gentle organic cotton undulation
    const n1 = noise(u * 0.0032 + 10, v * 0.0032 + 20) - 0.5;
    const n2 = noise(u * 0.0085 + 40, v * 0.0085 + 50) - 0.5;
    out.z += n1 * 28 + n2 * 9;
    out.x += n1 * 12;
    out.y += n2 * 8;
  } else if (layer === 1) {
    // LAYER 1: Turned-Down Top Sheet Cuff
    const vEdge = getCuffEdgeV(u);
    const dist = vEdge - v;
    if (dist < -4 || v < 140) {
      out.valid = false;
      return;
    }
    out.z = 84;
    for (let i = 0; i < CUFF_FOLDS.length; i++) {
      evalFoldPrimitive(u, v, CUFF_FOLDS[i], out);
    }
    const n1 = noise(u * 0.004 + 70, v * 0.004 + 30) - 0.5;
    out.z += n1 * 18;

    // 3D rolled lower lip where the top sheet folds back over itself
    const rollZone = 46.0;
    if (dist < rollZone) {
      const rt = Math.max(0, Math.min(1, 1.0 - dist / rollZone));
      out.y -= 15.0 * Math.pow(rt, 2.3);
      out.z += 22.0 * Math.sin(rt * Math.PI * 0.85) - 36.0 * Math.pow(rt, 2.7);
      out.concavity += 28.0 * Math.pow(rt, 2.0);
    }
  } else if (layer === 0) {
    // LAYER 0: Dented Pillow Edge at Top
    const vEdge = getPillowEdgeV(u);
    const dist = vEdge - v;
    if (dist < -3) {
      out.valid = false;
      return;
    }
    const loftT = Math.max(0, Math.min(1, (dist + 3) / 270.0));
    // Plump pillow volume
    out.z = 152 + 96 * Math.sqrt(loftT) * (1.0 - 0.14 * loftT * loftT);

    // Head dent depression centered at (535, 92) with surrounding displaced down bolsters
    const rx = (u - 535) / 215.0;
    const ry = (v - 92) / 155.0;
    const r2 = rx * rx + ry * ry;
    const dent = -82.0 * Math.exp(-r2 * 1.48);
    const bolster = 36.0 * r2 * Math.exp(-r2 * 0.92);
    out.z += dent + bolster;
    out.x -= rx * 24.0 * Math.exp(-r2 * 1.3);
    out.y -= ry * 18.0 * Math.exp(-r2 * 1.3);
    if (r2 < 1.1) {
      out.concavity += 34.0 * Math.exp(-r2 * 1.5);
    }

    // Radial seam puckers radiating from the head dent
    for (let i = 0; i < PILLOW_GATHERS.length; i++) {
      evalFoldPrimitive(u, v, PILLOW_GATHERS[i], out);
    }

    // Corded piping / rolled seam along the lower pillow border
    const seamZone = 32.0;
    if (dist < seamZone) {
      const st = Math.max(0, Math.min(1, 1.0 - dist / seamZone));
      // Subtle corded piping bead right at st ~ 0.72..0.95
      const piping = 7.5 * Math.exp(-Math.pow((st - 0.78) / 0.13, 2));
      out.z += 14.0 * Math.sin(st * Math.PI * 0.8) - 34.0 * Math.pow(st, 2.5) + piping;
      out.y -= 10.0 * Math.pow(st, 2.2);
      out.concavity += 24.0 * Math.pow(st, 1.8);
    }
  }
}

// Reusable scratch objects for finite-difference normal evaluation
const _p0 = { x: 0, y: 0, z: 0, concavity: 0, valid: false };
const _pu = { x: 0, y: 0, z: 0, concavity: 0, valid: false };
const _pv = { x: 0, y: 0, z: 0, concavity: 0, valid: false };

function evalClothSurface(layer, u, v) {
  const eps = 1.5;
  evalClothPos(layer, u, v, _p0);
  if (!_p0.valid) return null;
  evalClothPos(layer, u + eps, v, _pu);
  evalClothPos(layer, u, v + eps, _pv);
  if (!_pu.valid || !_pv.valid) return null;

  const tux = (_pu.x - _p0.x) / eps;
  const tuy = (_pu.y - _p0.y) / eps;
  const tuz = (_pu.z - _p0.z) / eps;

  const tvx = (_pv.x - _p0.x) / eps;
  const tvy = (_pv.y - _p0.y) / eps;
  const tvz = (_pv.z - _p0.z) / eps;

  // Cross product Tu x Tv (z points out of screen toward viewer)
  let nx = tuy * tvz - tuz * tvy;
  let ny = tuz * tvx - tux * tvz;
  let nz = tux * tvy - tuy * tvx;
  const invLen = 1.0 / (Math.hypot(nx, ny, nz) || 1.0);
  nx *= invLen;
  ny *= invLen;
  nz *= invLen;

  return {
    x: _p0.x,
    y: _p0.y,
    z: _p0.z,
    nx,
    ny,
    nz,
    concavity: _p0.concavity
  };
}

// Rasterize all 3 cloth layers into the 1200x1200 Z-buffer
function rasterizeAllClothLayers() {
  // Morning light from upper-left-front (intimate, soft angled morning light)
  const lx = -0.44;
  const ly = -0.52;
  const lz = 0.732;

  const layers = [
    { id: 2, uMin: -90, uMax: 1290, vMin: 210, vMax: 1290, step: 1.8 },
    { id: 1, uMin: -80, uMax: 1280, vMin: 160, vMax: 525,  step: 1.6 },
    { id: 0, uMin: -80, uMax: 1280, vMin: -50, vMax: 335,  step: 1.6 }
  ];

  for (let L = 0; L < layers.length; L++) {
    const cfg = layers[L];
    const st = cfg.step;
    for (let v = cfg.vMin; v <= cfg.vMax; v += st) {
      for (let u = cfg.uMin; u <= cfg.uMax; u += st) {
        const s = evalClothSurface(cfg.id, u, v);
        if (!s || s.nz <= 0.01) continue;

        const ix = Math.round(s.x);
        const iy = Math.round(s.y);
        if (ix < 0 || ix >= W || iy < 0 || iy >= H) continue;

        // Splat a 2x2 neighborhood so steep foreshortened slopes leave zero pinhole gaps
        for (let dy = 0; dy <= 1; dy++) {
          const py = iy + dy;
          if (py >= H) continue;
          const rowOff = py * W;
          for (let dx = 0; dx <= 1; dx++) {
            const px = ix + dx;
            if (px >= W) continue;
            const idx = rowOff + px;
            if (s.z > zBuf[idx]) {
              zBuf[idx] = s.z;
              nzBuf[idx] = s.nz;
              layerBuf[idx] = cfg.id;
              curvBuf[idx] = Math.min(1.0, s.concavity / 45.0);

              // Direct Lambertian + grazing rim darkness
              const ndotl = Math.max(0, s.nx * lx + s.ny * ly + s.nz * lz);
              const diffuseShadow = Math.pow(1.0 - ndotl, 1.35);
              const grazing = Math.pow(1.0 - Math.min(1.0, s.nz), 1.85);
              shadeBuf[idx] = Math.min(1.0, diffuseShadow * 0.72 + grazing * 0.34);
            }
          }
        }
      }
    }
  }

  // Downsample zBuf to 600x600 sZBuf for fast ray-marched cast shadows
  for (let sy = 0; sy < SH; sy++) {
    const y2 = sy * 2;
    for (let sx = 0; sx < SW; sx++) {
      const x2 = sx * 2;
      sZBuf[sy * SW + sx] = zBuf[y2 * W + x2];
    }
  }
}

// Compute ray-marched 3D cast shadows and crevice ambient occlusion on the 600x600 grid
function computeShadowsAndAO() {
  // Ray direction toward the morning light source in half-res pixel space
  const rdx = -0.58;
  const rdy = -0.68;
  const rdz = 1.72; // z height step per half-res pixel step

  for (let sy = 0; sy < SH; sy++) {
    for (let sx = 0; sx < SW; sx++) {
      const sIdx = sy * SW + sx;
      const z0 = sZBuf[sIdx];
      if (z0 < -1e4) continue;

      // 1. Soft ray-marched cast shadow (18 steps)
      let maxPenumbra = 0.0;
      for (let step = 2; step <= 36; step += 2) {
        const tx = Math.round(sx + rdx * step);
        const ty = Math.round(sy + rdy * step);
        if (tx < 0 || tx >= SW || ty < 0 || ty >= SH) break;
        const tz = sZBuf[ty * SW + tx];
        const rayZ = z0 + rdz * step;
        const diff = tz - rayZ;
        if (diff > 1.5) {
          const pen = Math.min(1.0, diff / (14.0 + step * 0.9));
          if (pen > maxPenumbra) maxPenumbra = pen;
        }
      }
      sShadowBuf[sIdx] = maxPenumbra;

      // 2. Screen-space horizon ambient occlusion in deep fold troughs
      let ao = 0.0;
      const dirs = [
        [1, 0], [-1, 0], [0, 1], [0, -1],
        [0.7, 0.7], [-0.7, 0.7], [0.7, -0.7], [-0.7, -0.7]
      ];
      for (let d = 0; d < 8; d++) {
        const vx = dirs[d][0];
        const vy = dirs[d][1];
        for (let r = 3; r <= 12; r += 4) {
          const nx = Math.min(SW - 1, Math.max(0, Math.round(sx + vx * r)));
          const ny = Math.min(SH - 1, Math.max(0, Math.round(sy + vy * r)));
          const dz = sZBuf[ny * SW + nx] - z0;
          if (dz > 2.0) {
            ao += Math.min(1.0, dz / (r * 4.5));
          }
        }
      }
      sAOBuf[sIdx] = Math.min(1.0, ao / 10.0);
    }
  }
}

// Smooth & combine direct shading, cast shadows, and valley AO into shadeBuf
function bakeFinalShadingBuffer() {
  for (let y = 0; y < H; y++) {
    const sy = Math.min(SH - 1, y >> 1);
    const rowOff = y * W;
    const sRowOff = sy * SW;
    for (let x = 0; x < W; x++) {
      const sx = Math.min(SW - 1, x >> 1);
      const idx = rowOff + x;
      const sIdx = sRowOff + sx;

      const cast = sShadowBuf[sIdx];
      const ao = sAOBuf[sIdx];
      const curv = curvBuf[idx];
      const base = shadeBuf[idx];

      castBuf[idx] = cast;
      // Unified shadow value S in [0, 1]
      const combined = Math.min(
        1.0,
        base * 0.64 + cast * 0.42 + ao * 0.35 + curv * 0.28
      );
      shadeBuf[idx] = combined;
    }
  }
}

// Query visibility and shading of a 3D cloth point
function projectUV(layer, u, v) {
  const s = evalClothSurface(layer, u, v);
  if (!s || s.nz <= 0.035) return null;

  const ix = Math.round(s.x);
  const iy = Math.round(s.y);
  if (ix < 0 || ix >= W || iy < 0 || iy >= H) return null;

  const idx = iy * W + ix;
  // Occlusion test against the Z-buffer (with small tolerance for local slope)
  const tol = 3.2 + (1.0 - s.nz) * 4.5;
  if (s.z < zBuf[idx] - tol) return null;

  return {
    x: s.x,
    y: s.y,
    z: s.z,
    nz: s.nz,
    shade: shadeBuf[idx],
    cast: castBuf[idx],
    concavity: curvBuf[idx]
  };
}

// ============================================================================
// PART 2: MORNING-SOFT DUSKY TWILIGHT UNDERTONES & COTTON WARMTH
// ============================================================================

function renderTwilightUndertones() {
  brush.noStroke();
  brush.noHatch();

  // Sample shadow basins on a coarse grid and batch soft watercolor washes by tone
  const lightBasins = [];
  const midBasins = [];
  const deepBasins = [];

  const step = 34;
  for (let y = 24; y < H - 24; y += step) {
    for (let x = 24; x < W - 24; x += step) {
      const idx = y * W + x;
      const s = shadeBuf[idx];
      if (s > 0.34) {
        const jx = x + random(-10, 10);
        const jy = y + random(-10, 10);
        const rad = step * random(0.78, 1.25);
        if (s > 0.68) {
          deepBasins.push([jx, jy, rad]);
        } else if (s > 0.50) {
          midBasins.push([jx, jy, rad]);
        } else {
          lightBasins.push([jx, jy, rad]);
        }
      }
    }
  }

  // Batch 1: Soft dusky twilight mauve-cream halftone wash
  brush.fill(PALETTE.twilightWashLight, 18);
  brush.fillBleed(0.32, "out");
  brush.fillTexture(0.35, 0.15);
  for (let i = 0; i < lightBasins.length; i++) {
    const b = lightBasins[i];
    brush.circle(b[0], b[1], b[2], 0.35);
  }

  // Batch 2: Medium dusky rose-taupe fold shadow wash
  brush.fill(PALETTE.twilightWashMid, 22);
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.4, 0.2);
  for (let i = 0; i < midBasins.length; i++) {
    const b = midBasins[i];
    brush.circle(b[0], b[1], b[2], 0.35);
  }

  // Batch 3: Deep twilight madder-plum crevice wash
  brush.fill(PALETTE.twilightWashDeep, 26);
  brush.fillBleed(0.22, "out");
  brush.fillTexture(0.45, 0.25);
  for (let i = 0; i < deepBasins.length; i++) {
    const b = deepBasins[i];
    brush.circle(b[0], b[1], b[2] * 0.85, 0.35);
  }

  brush.noFill();
}

function renderCottonGrainHighlights() {
  // Subtle warm cream luminous washes on the sunlit crowns of the folds
  brush.noStroke();
  brush.fill(PALETTE.creamHighlight, 28);
  brush.fillBleed(0.25, "out");
  brush.fillTexture(0.25, 0.1);

  const step = 48;
  for (let y = 36; y < H - 36; y += step) {
    for (let x = 36; x < W - 36; x += step) {
      const idx = y * W + x;
      if (shadeBuf[idx] < 0.16 && nzBuf[idx] > 0.78) {
        brush.circle(x + random(-12, 12), y + random(-12, 12), step * 0.9, 0.3);
      }
    }
  }
  brush.noFill();
}

// ============================================================================
// PART 3: FORM-FOLLOWING COPPERPLATE CROSSHATCHING ON THE 3D CLOTH
// ============================================================================

// Draw a projected stroke segment list with pressure modulation
function emitProjectedStroke(pts) {
  if (pts.length < 2) return;
  if (pts.length === 2) {
    brush.line(pts[0][0], pts[0][1], pts[1][0], pts[1][1]);
  } else {
    brush.spline(pts, 0.25);
  }
}

// Trace a geodesic UV line across a cloth layer, breaking whenever occluded or outside shadow threshold
function traceFormContourLine(layer, uStart, vStart, du, dv, steps, minShade, maxShade, weightScale) {
  let active = [];
  for (let i = 0; i <= steps; i++) {
    const u = uStart + du * i;
    const v = vStart + dv * i;
    const p = projectUV(layer, u, v);

    if (p && p.shade >= minShade && p.shade <= maxShade) {
      // Modulate pen pressure by how deep into the shadow range this point sits
      const tShade = Math.min(1.0, (p.shade - minShade) / Math.max(0.12, 0.75 - minShade));
      const grazingBoost = Math.pow(1.0 - p.nz, 0.7) * 0.35;
      const pressure = (0.32 + 0.85 * tShade + grazingBoost) * weightScale;

      if (active.length === 0) {
        active.push([p.x, p.y, pressure]);
      } else {
        const prev = active[active.length - 1];
        const dist = Math.hypot(p.x - prev[0], p.y - prev[1]);
        if (dist > 28) {
          // Discontinuity across a fold jump -> flush current segment
          emitProjectedStroke(active);
          active = [[p.x, p.y, pressure]];
        } else if (dist >= 5.5 || i === steps) {
          active.push([p.x, p.y, pressure]);
        }
      }
    } else {
      if (active.length >= 2) emitProjectedStroke(active);
      active = [];
    }
  }
  if (active.length >= 2) emitProjectedStroke(active);
}

function renderClothFormHatching() {
  brush.noFill();
  brush.noHatch();

  const layers = [
    { id: 2, uMin: -80, uMax: 1280, vMin: 220, vMax: 1280 },
    { id: 1, uMin: -70, uMax: 1270, vMin: 165, vMax: 520 },
    { id: 0, uMin: -70, uMax: 1270, vMin: -40, vMax: 330 }
  ];

  // PASS 1: Light Halftone Cross-Contour Engraving (Follows horizontal/weft drape across folds)
  // Soft madder-rose ink, engages wherever shade >= 0.19
  brush.set("copperplate", PALETTE.madderSoft, 0.75);
  for (let L = 0; L < layers.length; L++) {
    const cfg = layers[L];
    const vSpacing = 4.2;
    const uStep = 5.0;
    const steps = Math.ceil((cfg.uMax - cfg.uMin) / uStep);
    for (let v = cfg.vMin; v <= cfg.vMax; v += vSpacing) {
      traceFormContourLine(cfg.id, cfg.uMin, v, uStep, 0, steps, 0.19, 1.0, 0.85);
    }
  }

  // PASS 2: Mid-Tone Warp Crosshatching (Follows longitudinal fold direction)
  // Classic madder-red ink, engages wherever shade >= 0.34
  brush.set("copperplate", PALETTE.madderMid, 0.82);
  for (let L = 0; L < layers.length; L++) {
    const cfg = layers[L];
    const uSpacing = 4.4;
    const vStep = 5.0;
    const steps = Math.ceil((cfg.vMax - cfg.vMin) / vStep);
    for (let u = cfg.uMin; u <= cfg.uMax; u += uSpacing) {
      traceFormContourLine(cfg.id, u, cfg.vMin, 0, vStep, steps, 0.34, 1.0, 0.92);
    }
  }

  // PASS 3: Deep Fold Diagonal Bias Crosshatching (+38 deg in UV space)
  // Rich madder-carmine ink, engages in deep fold flanks & cast shadows (shade >= 0.49)
  brush.set("rotring", PALETTE.madderRich, 0.42);
  for (let L = 0; L < layers.length; L++) {
    const cfg = layers[L];
    const diagSpacing = 3.8;
    const stepLen = 4.5;
    const du = stepLen * 0.78;
    const dv = stepLen * 0.62;
    const diagSpan = (cfg.uMax - cfg.uMin) + (cfg.vMax - cfg.vMin);
    const maxSteps = Math.ceil((cfg.vMax - cfg.vMin) / dv);
    for (let offset = -diagSpan * 0.5; offset <= diagSpan; offset += diagSpacing) {
      const u0 = cfg.uMin + offset;
      const v0 = cfg.vMin;
      traceFormContourLine(cfg.id, u0, v0, du, dv, maxSteps, 0.49, 1.0, 1.0);
    }
  }

  // PASS 4: Crevice & Core Shadow Counter-Diagonal Engraving (-38 deg in UV space)
  // Deepest dusky madder-wine ink, engages in deep creases & under overhangs (shade >= 0.63)
  brush.set("rotring", PALETTE.madderDeep, 0.46);
  for (let L = 0; L < layers.length; L++) {
    const cfg = layers[L];
    const diagSpacing = 3.2;
    const stepLen = 4.2;
    const du = -stepLen * 0.78;
    const dv = stepLen * 0.62;
    const diagSpan = (cfg.uMax - cfg.uMin) + (cfg.vMax - cfg.vMin);
    const maxSteps = Math.ceil((cfg.vMax - cfg.vMin) / dv);
    for (let offset = 0; offset <= diagSpan * 1.2; offset += diagSpacing) {
      const u0 = cfg.uMin + offset;
      const v0 = cfg.vMin;
      traceFormContourLine(cfg.id, u0, v0, du, dv, maxSteps, 0.63, 1.0, 1.1);
    }
  }
}

// ============================================================================
// PART 4: PROCEDURAL 18TH-CENTURY TOILE DE JOUY COPPERPLATE GENERATOR
// ============================================================================

// A Toile de Jouy tile is a collection of UV polylines: { pts: [[u,v],...], role: string }
function buildMasterToileTile() {
  const strokes = [];

  function addPoly(pts, role = "mid") {
    if (pts && pts.length >= 2) strokes.push({ pts, role });
  }

  function addSeg(u1, v1, u2, v2, role = "mid") {
    strokes.push({ pts: [[u1, v1], [u2, v2]], role });
  }

  function addArc(cx, cy, rx, ry, a0, a1, steps, role = "mid", wobble = 0) {
    const pts = [];
    for (let i = 0; i <= steps; i++) {
      const t = i / steps;
      const a = (a0 + (a1 - a0) * t) * (Math.PI / 180);
      const wb = wobble ? Math.sin(t * Math.PI * 6 + cx) * wobble : 0;
      pts.push([cx + (rx + wb) * Math.cos(a), cy + (ry + wb) * Math.sin(a)]);
    }
    addPoly(pts, role);
  }

  // Helper: Engraved scalloped foliage cluster (authentic Toile de Jouy "feuillage")
  function buildFoliageCluster(cx, cy, rx, ry, lobes, tiltDeg, role = "mid") {
    const tilt = tiltDeg * (Math.PI / 180);
    const cosT = Math.cos(tilt);
    const sinT = Math.sin(tilt);

    function rot(x, y) {
      return [cx + x * cosT - y * sinT, cy + x * sinT + y * cosT];
    }

    // 1. Scalloped outer leaf lobes (upper/outer rim)
    for (let i = 0; i < lobes; i++) {
      const t0 = -Math.PI * 0.92 + (i / lobes) * Math.PI * 1.65;
      const t1 = -Math.PI * 0.92 + ((i + 1) / lobes) * Math.PI * 1.65;
      const tm = (t0 + t1) * 0.5;
      const lobePts = [];
      for (let k = 0; k <= 4; k++) {
        const tk = t0 + (t1 - t0) * (k / 4);
        const swell = 1.0 + 0.22 * Math.sin((k / 4) * Math.PI);
        lobePts.push(rot(rx * swell * Math.cos(tk), ry * swell * Math.sin(tk)));
      }
      addPoly(lobePts, role);

      // Tiny inner leaf vein tick on every second lobe
      if (i % 2 === 0) {
        const pIn = rot(rx * 0.58 * Math.cos(tm), ry * 0.58 * Math.sin(tm));
        const pOut = rot(rx * 0.95 * Math.cos(tm), ry * 0.95 * Math.sin(tm));
        addSeg(pIn[0], pIn[1], pOut[0], pOut[1], "light");
      }
    }

    // 2. Shaded underside crescent hatching (classic copperplate tree shading)
    const hatchCount = Math.floor(rx * 0.55);
    for (let h = 0; h < hatchCount; h++) {
      const f = (h / Math.max(1, hatchCount - 1)) * 2.0 - 1.0; // -1..1
      const x0 = f * rx * 0.85;
      const yBot = ry * Math.sqrt(Math.max(0, 1.0 - f * f * 0.85)) * 0.85;
      const yTop = yBot - ry * (0.38 + 0.25 * (1.0 - f * f));
      const p1 = rot(x0, yTop);
      const p2 = rot(x0 + rx * 0.08, yBot);
      addSeg(p1[0], p1[1], p2[0], p2[1], "dark");
    }
  }

  // Helper: Engraved grassy pastoral knoll with terraced hachures & wild tufts
  function buildPastoralMound(cx, cy, width, depth, terraces) {
    for (let t = 0; t < terraces; t++) {
      const f = t / terraces;
      const ty = cy + f * depth;
      const tw = width * (0.72 + 0.28 * Math.sin(f * Math.PI + 0.4));
      const tx = cx + (f - 0.4) * 18 * Math.sin(t * 2.1);

      // Undulating terrace contour line
      const contour = [];
      const steps = 16;
      for (let i = 0; i <= steps; i++) {
        const s = (i / steps) * 2 - 1;
        const px = tx + s * tw * 0.5;
        const py = ty + Math.sin(s * Math.PI * 1.5 + t) * 4.5 - (1 - s * s) * 6.0;
        contour.push([px, py]);
      }
      addPoly(contour, "dark");

      // Vertical/curved earth hachures hanging below the terrace lip
      const hCount = Math.floor(tw * 0.24);
      for (let h = 0; h <= hCount; h++) {
        const s = (h / hCount) * 2 - 1;
        if (Math.abs(s) > 0.94) continue;
        const px = tx + s * tw * 0.5;
        const py = ty + Math.sin(s * Math.PI * 1.5 + t) * 4.5 - (1 - s * s) * 6.0;
        const hLen = (7 + 6 * (1 - s * s)) * (0.7 + 0.3 * Math.sin(h * 1.7));
        addSeg(px, py, px + s * 2.5, py + hLen, "mid");
      }

      // Tufts of grass & broad-leaf pastoral weeds along the terrace
      for (let g = -1; g <= 1; g += 2) {
        const gx = tx + g * tw * (0.22 + 0.12 * (t % 2));
        const gy = ty - 3;
        for (let b = -2; b <= 2; b++) {
          const ang = (-90 + b * 22 + g * 10) * (Math.PI / 180);
          const blen = 9 + (2 - Math.abs(b)) * 3.5;
          addPoly([
            [gx, gy],
            [gx + Math.cos(ang) * blen * 0.5, gy + Math.sin(ang) * blen * 0.5],
            [gx + Math.cos(ang + b * 0.12) * blen, gy + Math.sin(ang + b * 0.12) * blen]
          ], "mid");
        }
      }
    }
  }

  // Helper: Towering Gnarled Oak or Elm Tree with bark bracelets & lush canopy
  function buildEngravedTree(baseX, baseY, scale, leanDir) {
    const s = scale;
    // 1. Trunk & Root Buttresses
    const trunkH = 128 * s;
    const topX = baseX + leanDir * 24 * s;
    const topY = baseY - trunkH;

    // Left and right trunk contours with root flares
    const leftBark = [];
    const rightBark = [];
    const tSteps = 14;
    for (let i = 0; i <= tSteps; i++) {
      const f = i / tSteps;
      const curveX = baseX + leanDir * 24 * s * Math.pow(f, 1.35) + Math.sin(f * Math.PI * 1.5) * 6 * s * leanDir;
      const curveY = baseY - f * trunkH;
      const halfW = (11.5 * (1 - 0.52 * f) + 9.0 * Math.pow(1 - f, 3.5)) * s;
      leftBark.push([curveX - halfW, curveY]);
      rightBark.push([curveX + halfW, curveY]);

      // Cylindrical cross-contour bark hatching rings
      if (i > 0 && i < tSteps) {
        const rings = 2;
        for (let r = 0; r < rings; r++) {
          const rf = f + (r / rings) * (1 / tSteps);
          const ry = baseY - rf * trunkH;
          const rx = baseX + leanDir * 24 * s * Math.pow(rf, 1.35) + Math.sin(rf * Math.PI * 1.5) * 6 * s * leanDir;
          const rw = (11.0 * (1 - 0.52 * rf) + 7.0 * Math.pow(1 - rf, 3.5)) * s;
          addArc(rx + rw * 0.12, ry, rw * 0.85, 3.2 * s, 15, 155, 5, "dark");
        }
      }
    }
    addPoly(leftBark, "dark");
    addPoly(rightBark, "dark");

    // Longitudinal bark fissures
    for (let k = -1; k <= 1; k++) {
      const fiss = [];
      for (let i = 0; i <= 8; i++) {
        const f = i / 8;
        const cx = baseX + leanDir * 24 * s * Math.pow(f, 1.35) + k * 3.8 * s * (1 - 0.4 * f);
        const cy = baseY - f * trunkH * 0.92;
        fiss.push([cx, cy]);
      }
      addPoly(fiss, "mid");
    }

    // 2. Main Spreading Boughs
    const boughs = [
      { dx: -52 * s, dy: -42 * s, w: 5.5 * s },
      { dx: 48 * s,  dy: -48 * s, w: 5.5 * s },
      { dx: -14 * s, dy: -68 * s, w: 4.8 * s }
    ];
    for (let b = 0; b < boughs.length; b++) {
      const bg = boughs[b];
      addPoly([
        [topX, topY + 12 * s],
        [topX + bg.dx * 0.5, topY + bg.dy * 0.45],
        [topX + bg.dx, topY + bg.dy]
      ], "dark");
      addPoly([
        [topX + 3.5 * s, topY + 12 * s],
        [topX + bg.dx * 0.5 + 2.5 * s, topY + bg.dy * 0.45 + 2 * s],
        [topX + bg.dx + 1.5 * s, topY + bg.dy + 1.5 * s]
      ], "dark");
    }

    // 3. Billowing Canopy of Scalloped Foliage Masses (16 bouffants)
    const canopyClusters = [
      [-68, -32, 30, 19, 8, -14],
      [-40, -48, 34, 21, 9, -8],
      [-8,  -56, 36, 22, 9, 2],
      [28,  -50, 34, 21, 9, 10],
      [60,  -34, 30, 19, 8, 16],
      [-54, -68, 32, 20, 8, -10],
      [-20, -80, 38, 23, 10, -2],
      [18,  -78, 36, 22, 9, 6],
      [50,  -64, 30, 19, 8, 12],
      [-32, -102, 34, 21, 9, -4],
      [6,   -104, 35, 21, 9, 4],
      [-10, -120, 28, 17, 7, 0],
      // Lower hanging boughs
      [-82, -12, 24, 15, 7, -18],
      [76,  -14, 24, 15, 7, 18]
    ];

    for (let c = 0; c < canopyClusters.length; c++) {
      const cl = canopyClusters[c];
      buildFoliageCluster(
        topX + cl[0] * s,
        topY + cl[1] * s,
        cl[2] * s,
        cl[3] * s,
        cl[4],
        cl[5],
        c % 3 === 0 ? "dark" : "mid"
      );
    }
  }

  // ==========================================================================
  // VIGNETTE A: THE GRAND RUINED CLASSICAL ARCH, OAK TREE, SHEPHERDS & SHEEP
  // Centered around (u = 235, v = 230) in the 620x580 master tile
  // ==========================================================================
  const ax = 235;
  const ay = 225;

  // 1. Towering Oak Tree rising behind the left side of the ruined arch
  buildEngravedTree(ax - 74, ay + 68, 1.04, -1);

  // 2. The Classical Ruined Roman Archway
  const archSpan = 56;
  const pierW = 28;
  const pierTopY = ay - 12;
  const pierBotY = ay + 78;

  // Left Pier & Right Pier cut-stone ashlar masonry courses
  const courses = 9;
  const courseH = (pierBotY - pierTopY) / courses;
  for (let side = -1; side <= 1; side += 2) {
    const px = side < 0 ? ax - archSpan - pierW : ax + archSpan;
    // Molded stone plinth at base
    addPoly([
      [px - 4, pierBotY],
      [px + pierW + 4, pierBotY],
      [px + pierW + 4, pierBotY + 7],
      [px - 4, pierBotY + 7],
      [px - 4, pierBotY]
    ], "dark");

    for (let c = 0; c < courses; c++) {
      const cy0 = pierTopY + c * courseH;
      const cy1 = cy0 + courseH;
      // Right pier upper outer edge is partially crumbled in picturesque ruin
      const crumble = (side > 0 && c < 3) ? (3 - c) * 5.5 : 0;
      const xLeft = px;
      const xRight = px + pierW - crumble;

      // Horizontal mortar joint
      addSeg(xLeft, cy0, xRight, cy0, "dark");
      // Outer & inner vertical pier edges
      addSeg(xLeft, cy0, xLeft, cy1, "dark");
      addSeg(xRight, cy0, xRight, cy1, "dark");
      // Alternating vertical block joint
      const midJointX = xLeft + (c % 2 === 0 ? 0.55 : 0.38) * (xRight - xLeft);
      addSeg(midJointX, cy0, midJointX, cy1, "mid");

      // Ruled architectural engraving shading across each stone course
      for (let h = 2; h < courseH - 1; h += 2.6) {
        const shadeStart = side < 0 ? xLeft + 8 : xLeft + 2;
        addSeg(shadeStart, cy0 + h, xRight - 1, cy0 + h, side > 0 ? "dark" : "mid");
      }
    }

    // Impost cornice capital at the top of each pier
    addPoly([
      [px - 5, pierTopY - 6],
      [px + pierW + 5, pierTopY - 6],
      [px + pierW + 3, pierTopY],
      [px - 3, pierTopY],
      [px - 5, pierTopY - 6]
    ], "dark");
