  // Semicircular Voussoir Arch Ring & 3D Coffered Vault Intrados
  const rIn = archSpan;
  const rOut = archSpan + 22;
  const depthX = 16; // 3D vault depth offset
  const depthY = 8;

  // Front arch intrados and extrados
  addArc(ax, pierTopY - 6, rIn, rIn, 180, 360, 28, "dark");
  addArc(ax, pierTopY - 6, rOut, rOut, 180, 342, 26, "dark"); // Crumbled on far right

  // Radial voussoir stone joints (13 wedge blocks + projecting keystone)
  for (let v = 0; v <= 13; v++) {
