    const isKeystone = (v === 6 || v === 7);
    const rOuter = isKeystone ? rOut + 5 : rOut;
    addSeg(
      ax + rIn * Math.cos(ang),
      pierTopY - 6 + rIn * Math.sin(ang),
      ax + rOuter * Math.cos(ang),
      pierTopY - 6 + rOuter * Math.sin(ang),
