  // 3D Recessed Vault Soffit (Intrados perspective ring + dense curved vault crosshatching)
  addArc(ax + depthX, pierTopY - 6 + depthY, rIn, rIn * 0.94, 192, 360, 24, "dark");
  // Back right inner pier edge visible inside the arch opening
  addSeg(ax - rIn + depthX, pierTopY - 6 + depthY, ax - rIn + depthX, pierBotY - 4, "dark");
  for (let y = pierTopY + depthY; y < pierBotY - 4; y += 3.0) {
    addSeg(ax - rIn + 1, y, ax - rIn + depthX, y + 2, "dark");
  }
  // Curved vault soffit hatching between front intrados and back intrados
  for (let a = 190; a <= 356; a += 3.5) {
    const rad = a * (Math.PI / 180);
    const x1 = ax + rIn * Math.cos(rad);
    const y1 = pierTopY - 6 + rIn * Math.sin(rad);
    const x2 = ax + depthX + rIn * Math.cos(rad);
    const y2 = pierTopY - 6 + depthY + rIn * 0.94 * Math.sin(rad);
    addSeg(x1, y1, x2, y2, "dark");
  }

  // Crumbled Classical Entablature & Ruin Ivy on top of the Arch
  const entY = pierTopY - rOut - 8;
  addPoly([
    [ax - rOut - 8, entY + 14],
    [ax - rOut - 8, entY],
    [ax + 18, entY],
    [ax + 28, entY + 6],
    [ax + 42, entY + 15],
    [ax + 54, entY + 26]
  ], "dark");
  for (let h = entY + 3; h < entY + 14; h += 2.8) {
    addSeg(ax - rOut - 6, h, ax + 22 + (h - entY) * 1.4, h, "mid");
  }
  // Sprouting ruin foliage & trailing ivy garlands over the broken masonry
  buildFoliageCluster(ax - 35, entY - 6, 22, 12, 6, -8, "mid");
  buildFoliageCluster(ax + 12, entY - 3, 24, 13, 7, 12, "dark");
  for (let iv = 0; iv < 8; iv++) {
    const vx = ax + 36 + iv * 4.5;
    const vy = entY + 14 + iv * 5.2 + Math.sin(iv) * 3;
    addArc(vx, vy, 4.2, 2.8, 0, 260, 4, "mid");
  }

  // Distant Receding Classical Colonnade visible through the arch opening
  const colX1 = ax - 18;
  const colX2 = ax + 14;
  const colTop = pierTopY + 14;
  const colBot = pierBotY + 2;
  for (let cx of [colX1, colX2]) {
    addSeg(cx - 4.5, colTop, cx - 4.5, colBot, "mid");
    addSeg(cx + 4.5, colTop, cx + 4.5, colBot, "mid");
    addSeg(cx - 1.5, colTop, cx - 1.5, colBot, "light");
    addSeg(cx + 1.5, colTop, cx + 1.5, colBot, "light");
    // Corinthian capital
    addPoly([[cx - 7, colTop - 5], [cx + 7, colTop - 5], [cx + 5, colTop], [cx - 5, colTop], [cx - 7, colTop - 5]], "mid");
  }
  // Broken lintel connecting the two interior columns
  addPoly([[colX1 - 9, colTop - 11], [colX2 + 12, colTop - 11], [colX2 + 9, colTop - 5], [colX1 - 9, colTop - 5]], "mid");

  // 3. The Shepherd & Shepherdess with Grazing Sheep beneath the Arch
  const figY = pierBotY + 10;

  // --- THE SEATED SHEPHERDESS (left-center of foreground knoll) ---
  const shx = ax - 24;
  const shy = figY - 6;
