  addArc(shx, shy - 32, 9.5, 4.2, 165, 375, 8, "dark"); // Hat brim
  addArc(shx, shy - 34, 5.5, 4.0, 180, 360, 6, "dark"); // Hat crown
  addArc(shx + 0.5, shy - 29.5, 4.2, 4.8, 0, 360, 8, "dark"); // Head oval
  // Laced Bodice & Fichu Shawl
  addPoly([[shx - 5.5, shy - 24], [shx + 5.5, shy - 24], [shx + 4.0, shy - 11], [shx - 3.8, shy - 11], [shx - 5.5, shy - 24]], "dark");
  addPoly([[shx - 6.5, shy - 22], [shx + 0.5, shy - 16], [shx + 6.5, shy - 22]], "mid"); // Fichu kerchief
  for (let ly = shy - 20; ly < shy - 12; ly += 2.2) {
    addSeg(shx - 3.5, ly, shx + 3.5, ly, "mid"); // Corset lacing
  }
  // Outstretched arm holding a floral wreath
  addPoly([[shx + 5, shy - 22], [shx + 13, shy - 17], [shx + 20, shy - 20]], "dark");
  addArc(shx + 22, shy - 20, 4.5, 4.5, 0, 360, 7, "mid"); // Floral wreath
  // Voluminous Draped Skirt & Petticoat over the grassy knoll
  addPoly([
    [shx - 4, shy - 11],
    [shx - 20, shy + 10],
    [shx - 10, shy + 15],
    [shx + 6, shy + 16],
    [shx + 19, shy + 12],
    [shx + 12, shy - 3],
    [shx + 4, shy - 11]
  ], "dark");
  // Engraved drapery folds radiating down her skirt
  for (let f = -4; f <= 4; f++) {
    addPoly([
      [shx + f * 0.9, shy - 10],
      [shx + f * 2.6 - 1, shy + 1],
      [shx + f * 3.8 - 1, shy + 13]
    ], f % 2 === 0 ? "dark" : "mid");
  }
  // Scalloped petticoat flounce at hem
  for (let s = -16; s <= 14; s += 5) {
    addArc(shx + s, shy + 14.5, 2.8, 1.8, 0, 180, 4, "dark");
  }

  // --- THE STANDING SHEPHERD WITH CROOK (right-center of foreground) ---
  const spx = ax + 22;
  const spy = figY - 14;
  // Tricorne / Wide-brimmed Pastoral Hat & Head
  addArc(spx, spy - 38, 9.0, 3.5, 160, 380, 8, "dark");
