  addPoly([[spx - 6, spy - 6], [spx - 8, spy + 8], [spx - 6, spy + 22]], "dark");
  addPoly([[spx - 2, spy - 6], [spx - 4, spy + 8], [spx - 3, spy + 22]], "dark");
  addPoly([[spx + 1, spy - 6], [spx + 5, spy + 7], [spx + 8, spy + 21]], "dark");
