  // Arm & Tall Shepherd's Crook (Houlette)
  addPoly([[spx - 6, spy - 26], [spx - 14, spy - 19], [spx - 19, spy - 23]], "dark");
  addSeg(spx + 14, spy - 50, spx + 6, spy + 22, "dark"); // Long wooden staff
  addArc(spx + 15.5, spy - 52, 4.2, 6.0, -120, 140, 7, "dark"); // Curved iron shepherd's crook!

  // --- THE FLOCK OF SHEEP (3 woolly sheep resting & grazing) ---
  function buildSheep(sx, sy, facing, standing) {
    // Plump oval body
    addArc(sx, sy, 14, 9, 0, 360, 12, "dark", 0.9);
    // Curly fleece C-scrolls inside the body
    for (let row = -1; row <= 1; row++) {
