        const cx = sx + col * 4.2 + (row % 2) * 2.0;
        const cy = sy + row * 3.2;
        if ((cx - sx) * (cx - sx) / 160 + (cy - sy) * (cy - sy) / 65 < 0.85) {
          addArc(cx, cy, 2.4, 2.0, 20, 250, 4, row >= 0 ? "dark" : "mid");
        }
