    }
    // Head, ear, and tapered muzzle
    const hx = sx + facing * 15;
    const hy = standing ? sy - 5 : sy - 6;
    addPoly([
      [sx + facing * 10, sy - 5],
      [hx, hy - 4],
      [hx + facing * 6.5, hy - 0.5],
      [hx + facing * 5.0, hy + 2.5],
      [sx + facing * 11, sy + 1]
    ], "dark");
    // Floppy sheep ear
    addPoly([[hx - facing * 1, hy - 3], [hx - facing * 5, hy - 1], [hx - facing * 2, hy + 0.5]], "dark");
    // Legs
    if (standing) {
      for (let l of [-8, -4, 5, 9]) {
        addSeg(sx + l, sy + 7, sx + l + facing * 1, sy + 17, "dark");
      }
    } else {
      // Tucked forelegs
      addPoly([[sx + facing * 6, sy + 8], [sx + facing * 12, sy + 10], [sx + facing * 7, sy + 11]], "dark");
    }
  }

  buildSheep(ax - 58, figY + 12, 1, false);
  buildSheep(ax + 2,  figY + 18, -1, false);
  buildSheep(ax + 54, figY + 10, -1, true);

