  buildPastoralMound(ax + 4, pierBotY + 16, 255, 65, 5);

  // ==========================================================================
  // VIGNETTE B: CLASSICAL URN MONUMENT, RUSTIC BRIDGE, WEEPING WILLOW & FLUTE PLAYER
  // Centered around (u = 535, v = 490) in the 620x580 master tile
