  addArc(ux, uy - 54, 15, 16, 0, 360, 16, "dark"); // Urn body
  addPoly([[ux - 17, uy - 56], [ux + 17, uy - 56], [ux + 15, uy - 52], [ux - 15, uy - 52], [ux - 17, uy - 56]], "dark"); // Rim molding
  // Gadrooned flutes on urn belly + floral swag garland
  for (let g = -11; g <= 11; g += 3.5) {
    addSeg(ux + g * 0.6, uy - 41, ux + g, uy - 52, "mid");
  }
  addArc(ux, uy - 54, 16, 9, 15, 165, 8, "dark"); // Draped swag

  // 3. Rustic Single-Arch Stone Bridge & Rippling Stream
  const brx = bx + 12;
