  // ==========================================================================
  // VIGNETTE C: CONNECTING ROCOCO FLORAL SPRAYS, PASTORAL TROPHY & BIRDS
  // Bridges the open cotton ground at (515, 155) and (155, 495)
  // ==========================================================================
  function buildFloralBouquetAndTrophy(tx, ty, scale) {
    const s = scale;
    // Crossed Shepherd's Crook and Ribbon-Tied Flower Basket
    addSeg(tx - 38 * s, ty + 28 * s, tx + 38 * s, ty - 34 * s, "dark");
    addArc(tx + 41 * s, ty - 37 * s, 5 * s, 7 * s, -110, 150, 7, "dark");
    addSeg(tx - 32 * s, ty - 28 * s, tx + 34 * s, ty + 28 * s, "dark"); // Crossed rustic rake/pipe

