    addArc(tx, ty, 18 * s, 14 * s, 0, 180, 10, "dark");
    addSeg(tx - 19 * s, ty, tx + 19 * s, ty, "dark");
    // Basket weave cross-hatching
    for (let w = -14; w <= 14; w += 4) {
      addSeg(tx + w * s, ty, tx + w * 0.7 * s, ty + 12 * s, "mid");
    }
    for (let h = 3; h <= 11; h += 3.5) {
      addSeg(tx - 15 * s, ty + h * s, tx + 15 * s, ty + h * s, "mid");
    }

    // Blooming Madder Roses & Acanthus Scrolls spilling from the basket
    const roses = [[-10, -8, 8], [4, -10, 9], [14, -5, 7], [-2, -20, 7.5]];
    for (let r of roses) {
      const rx = tx + r[0] * s;
      const ry = ty + r[1] * s;
      const rad = r[2] * s;
      // Concentric engraved rose petals
      addArc(rx, ry, rad, rad * 0.88, 0, 360, 10, "dark", 0.8);
      addArc(rx, ry, rad * 0.62, rad * 0.55, 20, 340, 8, "mid");
      addArc(rx, ry, rad * 0.30, rad * 0.28, 0, 300, 6, "dark");
      for (let p = 0; p < 6; p++) {
        const a = (p / 6) * Math.PI * 2;
        addSeg(rx + Math.cos(a) * rad * 0.35, ry + Math.sin(a) * rad * 0.35, rx + Math.cos(a) * rad * 0.92, ry + Math.sin(a) * rad * 0.92, "mid");
      }
    }

    // Trailing floral stems & serrated rose leaves
    for (let dir = -1; dir <= 1; dir += 2) {
      const stem = [];
      for (let k = 0; k <= 8; k++) {
        const kf = k / 8;
        const sx = tx + dir * (16 + kf * 46) * s;
        const sy = ty - 6 * s + Math.sin(kf * Math.PI * 1.6) * 18 * s * dir;
        stem.push([sx, sy]);
        if (k >= 2 && k <= 7) {
          // Leaf pair along the trailing vine
          const ldir = (k % 2 === 0 ? 1 : -1);
          addArc(sx + dir * 4 * s, sy + ldir * 5 * s, 7 * s, 3.5 * s, -20, 200, 5, "mid");
          addSeg(sx, sy, sx + dir * 8 * s, sy + ldir * 7 * s, "mid");
        }
      }
      addPoly(stem, "dark");
    }

    // Fluttering Ribbon Bow beneath the basket
    addArc(tx - 9 * s, ty + 16 * s, 8 * s, 4 * s, 110, 350, 6, "dark");
    addArc(tx + 9 * s, ty + 16 * s, 8 * s, 4 * s, 190, 430, 6, "dark");
    addPoly([[tx - 3 * s, ty + 16 * s], [tx - 12 * s, ty + 32 * s], [tx - 18 * s, ty + 38 * s]], "mid");
    addPoly([[tx + 3 * s, ty + 16 * s], [tx + 12 * s, ty + 32 * s], [tx + 18 * s, ty + 38 * s]], "mid");
  }

  buildFloralBouquetAndTrophy(515, 165, 1.0);
  buildFloralBouquetAndTrophy(150, 495, 0.92);

  // Graceful Birds in Flight between the vignettes
  const birds = [[395, 95, 1.0], [425, 78, 0.8], [95, 360, 0.9]];
  for (let b of birds) {
    const bx0 = b[0], by0 = b[1], bs = b[2];
    addArc(bx0 - 7 * bs, by0, 8 * bs, 5 * bs, 200, 350, 5, "dark");
    addArc(bx0 + 7 * bs, by0, 8 * bs, 5 * bs, 190, 340, 5, "dark");
    addSeg(bx0 - 3 * bs, by0 + 1 * bs, bx0 + 3 * bs, by0 + 3 * bs, "dark");
  }

  return {
    tileW: 620,
    tileH: 580,
    strokes
  };
}

// ============================================================================
// PART 5: PROJECTING THE TOILE DE JOUY PATTERN ONTO THE 3D DRAPERY FOLDS
// ============================================================================

// Transform pattern coordinates (pu, pv) to cloth layer coordinates (u, v)
function mapPatternToClothUV(layer, pu, pv) {
  if (layer === 2) {
    // Main sheet: angled slightly (+7 deg) so vignettes sweep across the diagonal folds
    const ang = 7.0 * (Math.PI / 180);
    const cosA = Math.cos(ang);
    const sinA = Math.sin(ang);
    const u = 235 + pu * cosA - pv * sinA;
    const v = 395 + pu * sinA + pv * cosA;
    return [u, v];
  } else if (layer === 1) {
    // Turned-down top sheet cuff: inverted & rotated (-152 deg) because the sheet is folded back!
    const ang = -152.0 * (Math.PI / 180);
    const cosA = Math.cos(ang);
    const sinA = Math.sin(ang);
    const u = 620 + pu * cosA - pv * sinA;
    const v = 460 + pu * sinA + pv * cosA;
    return [u, v];
  } else {
    // Dented pillow at top: gently angled (-11 deg) pillowcase print
    const ang = -11.0 * (Math.PI / 180);
    const cosA = Math.cos(ang);
    const sinA = Math.sin(ang);
    const u = 285 + pu * cosA - pv * sinA;
    const v = -35 + pu * sinA + pv * cosA;
    return [u, v];
  }
}

function renderProjectedToilePattern(masterToile) {
  const { tileW, tileH, strokes } = masterToile;

  // Collect projected stroke fragments into 3 madder tonal buckets so we batch brush.set() calls:
  // Bucket 0: Sunlit crown madder (#98293A)
  // Bucket 1: Mid-tone fold madder (#7D1B2B)
  // Bucket 2: Deep fold & core shadow madder (#5E111F)
  const buckets = {
    light: [[], [], []],
    mid:   [[], [], []],
    dark:  [[], [], []]
  };

  const layerConfigs = [
    { id: 2, colMin: -1, colMax: 2, rowMin: -1, rowMax: 2 },
    { id: 1, colMin: -1, colMax: 2, rowMin: -1, rowMax: 1 },
    { id: 0, colMin: -1, colMax: 2, rowMin: -1, rowMax: 1 }
  ];

  for (let L = 0; L < layerConfigs.length; L++) {
    const cfg = layerConfigs[L];
    for (let col = cfg.colMin; col <= cfg.colMax; col++) {
      // Classic Toile de Jouy half-drop repeat shift on odd columns
      const halfDrop = (Math.abs(col) % 2) * (tileH * 0.5);
      for (let row = cfg.rowMin; row <= cfg.rowMax; row++) {
        const offU = col * tileW;
        const offV = row * tileH + halfDrop;

        // Quick bounding check on tile center
        const [cu, cv] = mapPatternToClothUV(cfg.id, offU + tileW * 0.5, offV + tileH * 0.5);
        if (cu < -450 || cu > 1650 || cv < -450 || cv > 1650) continue;

        for (let sIdx = 0; sIdx < strokes.length; sIdx++) {
          const st = strokes[sIdx];
          const pts = st.pts;
          const role = st.role;

          // Subdivide UV polyline so long lines bend smoothly over 3D folds and clip accurately at creases
          let active = [];
          let sumShade = 0;
          let countShade = 0;

          for (let i = 0; i < pts.length; i++) {
            const [u0, v0] = mapPatternToClothUV(cfg.id, pts[i][0] + offU, pts[i][1] + offV);

            if (i > 0) {
              const [uPrev, vPrev] = mapPatternToClothUV(cfg.id, pts[i - 1][0] + offU, pts[i - 1][1] + offV);
              const segDist = Math.hypot(u0 - uPrev, v0 - vPrev);
              const subSteps = Math.max(1, Math.ceil(segDist / 3.5));

              for (let k = 1; k <= subSteps; k++) {
                const f = k / subSteps;
                const su = uPrev + (u0 - uPrev) * f;
                const sv = vPrev + (v0 - vPrev) * f;
                const p = projectUV(cfg.id, su, sv);

                if (p) {
                  // Foreshortening & shadow pressure modulation
                  const pWeight = (0.55 + 0.55 * Math.sqrt(p.nz)) * (0.85 + 0.45 * p.shade);
                  if (active.length > 0) {
                    const last = active[active.length - 1];
                    if (Math.hypot(p.x - last[0], p.y - last[1]) > 22) {
                      if (active.length >= 2) {
                        const avgS = sumShade / Math.max(1, countShade);
                        const bIdx = avgS > 0.52 ? 2 : (avgS > 0.26 ? 1 : 0);
                        buckets[role][bIdx].push(active);
                      }
                      active = [];
                      sumShade = 0;
                      countShade = 0;
                    }
                  }
                  active.push([p.x, p.y, pWeight]);
                  sumShade += p.shade;
                  countShade++;
                } else {
                  if (active.length >= 2) {
                    const avgS = sumShade / Math.max(1, countShade);
                    const bIdx = avgS > 0.52 ? 2 : (avgS > 0.26 ? 1 : 0);
                    buckets[role][bIdx].push(active);
                  }
                  active = [];
                  sumShade = 0;
                  countShade = 0;
                }
              }
            } else {
              const p = projectUV(cfg.id, u0, v0);
              if (p) {
                const pWeight = (0.55 + 0.55 * Math.sqrt(p.nz)) * (0.85 + 0.45 * p.shade);
                active.push([p.x, p.y, pWeight]);
                sumShade += p.shade;
                countShade++;
              }
            }
          }

          if (active.length >= 2) {
            const avgS = sumShade / Math.max(1, countShade);
            const bIdx = avgS > 0.52 ? 2 : (avgS > 0.26 ? 1 : 0);
            buckets[role][bIdx].push(active);
          }
        }
      }
    }
  }

  // Draw all projected Toile de Jouy strokes batched by role & local fold shadow depth
  const colors = [PALETTE.madderMid, PALETTE.madderRich, PALETTE.madderDeep];

  // 1. Fine interior detail lines ("light")
  for (let b = 0; b < 3; b++) {
    brush.set("copperplate", b === 0 ? PALETTE.madderSoft : colors[b], 0.72);
    const list = buckets.light[b];
    for (let i = 0; i < list.length; i++) emitProjectedStroke(list[i]);
  }

  // 2. Medium engraving lines ("mid")
  for (let b = 0; b < 3; b++) {
    brush.set("rotring", colors[b], 0.44);
    const list = buckets.mid[b];
    for (let i = 0; i < list.length; i++) emitProjectedStroke(list[i]);
  }

  // 3. Primary copperplate contours & dark architectural/foliage hatches ("dark")
  const darkColors = [PALETTE.madderRich, PALETTE.madderDeep, PALETTE.madderAbyss];
  for (let b = 0; b < 3; b++) {
    brush.set("rotring", darkColors[b], 0.54);
    const list = buckets.dark[b];
    for (let i = 0; i < list.length; i++) emitProjectedStroke(list[i]);
  }
}

// ============================================================================
// PART 6: CREASE-HUGGING ACCENTS, PILLOW PIPING & GRAZING STIPPLE
// ============================================================================

function renderFoldCreaseAccents() {
  brush.noFill();
  brush.noHatch();

  // 1. Trace the corded lower seam of the dented pillow (Layer 0) & rolled cuff lip (Layer 1)
  brush.set("rotring", PALETTE.madderDeep, 0.50);

  // Pillow piping & seam gather accents
  for (let offset = 2; offset <= 14; offset += 4) {
    let active = [];
    for (let u = -40; u <= 1240; u += 4) {
      const v = getPillowEdgeV(u) - offset;
      const p = projectUV(0, u, v);
      if (p) {
        active.push([p.x, p.y, 0.65 + 0.6 * p.shade]);
      } else {
        if (active.length >= 2) emitProjectedStroke(active);
        active = [];
      }
    }
    if (active.length >= 2) emitProjectedStroke(active);
  }

  // Turned-down sheet cuff rolled lip shadow lines
  for (let offset = 2; offset <= 14; offset += 4) {
    let active = [];
    for (let u = -40; u <= 1240; u += 4) {
      const v = getCuffEdgeV(u) - offset;
      const p = projectUV(1, u, v);
      if (p && p.shade > 0.25) {
        active.push([p.x, p.y, 0.55 + 0.65 * p.shade]);
      } else {
        if (active.length >= 2) emitProjectedStroke(active);
        active = [];
      }
    }
    if (active.length >= 2) emitProjectedStroke(active);
  }

  // 2. Deepest Occlusion Crease Accents (where zBuf has a sharp cliff between overlapping folds)
  brush.set("rotring", PALETTE.madderAbyss, 0.48);
  const step = 4;
  for (let y = 16; y < H - 16; y += step) {
    for (let x = 16; x < W - 16; x += step) {
      const idx = y * W + x;
      const z0 = zBuf[idx];
      const dzX = zBuf[idx + step] - z0;
      const dzY = zBuf[(y + step) * W + x] - z0;
      const jump = Math.hypot(dzX, dzY);

      // Where one fold overhangs another (jump > 24px), place short crease-hugging shadow ticks
      if (jump > 24 && jump < 220 && shadeBuf[idx] > 0.42) {
        const tx = -dzY / jump;
        const ty = dzX / jump;
        const len = random(4.5, 9.5);
        brush.line(x - tx * len * 0.5, y - ty * len * 0.5, x + tx * len * 0.5, y + ty * len * 0.5);
      }
    }
  }

  // 3. Delicate Copperplate Stipple & Broken Flicks along the Morning-Light Terminators
  brush.set("drypoint", PALETTE.madderFaint, 0.68);
  for (let y = 14; y < H - 14; y += 7) {
    for (let x = 14; x < W - 14; x += 7) {
      const idx = y * W + x;
      const s = shadeBuf[idx];
      // Terminator zone where light halftone transitions into bare warm cream highlight
      if (s >= 0.13 && s <= 0.24 && random() < 0.52) {
        const gx = shadeBuf[idx + 2] - shadeBuf[idx - 2];
        const gy = shadeBuf[(y + 2) * W + x] - shadeBuf[(y - 2) * W + x];
        const ang = Math.atan2(gy, gx) + Math.PI * 0.5;
        const jx = x + random(-2.5, 2.5);
        const jy = y + random(-2.5, 2.5);
        const d = random(1.8, 3.8);
        brush.line(jx, jy, jx + Math.cos(ang) * d, jy + Math.sin(ang) * d);
      }
    }
  }
}

// Hyperrealist Encaustic Still Life: Cultured Butter on Scarred Oak
// Rendered with p5.js v2 + p5.brush

const B_TL = [-140, 530];
const B_TR = [820, 330];
const B_BR = [1380, 590];
const B_BL = [490, 1030];

const B_BL_BOT = [490, 1140];
const B_TL_BOT = [-140, 630];
const B_BR_BOT = [1380, 690];

// Butter Slab 3D Vertices
const T_BL = [330, 490];
const T_BR = [690, 405];
const T_FR = [845, 510];
const T_FL = [480, 610];

const BOT_BL = [338, 665];
const BOT_FL = [478, 795];
const BOT_FR = [835, 680];
const BOT_BR = [685, 575]; // internal/back corner for subsurface calculations

function lerpPt(a, b, t) {
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t];
}

function bilerp(p00, p10, p11, p01, u, v) {
  const top = lerpPt(p00, p10, u);
  const bot = lerpPt(p01, p11, u);
  return lerpPt(top, bot, v);
}

function jitterPt(pt, amtX, amtY = amtX) {
  return [pt[0] + random(-amtX, amtX), pt[1] + random(-amtY, amtY)];
}

function resetBrush() {
  brush.noStroke();
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.noField();
}

function drawPoly(pts, curv = 0.12) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

function makeQuadPatch(p00, p10, p11, p01, u0, u1, v0, v1, subdiv = 4, jitter = 3) {
  const pts = [];
  for (let i = 0; i <= subdiv; i++) {
    const u = lerp(u0, u1, i / subdiv);
    pts.push(jitterPt(bilerp(p00, p10, p11, p01, u, v0), jitter));
  }
  for (let i = 1; i <= subdiv; i++) {
    const v = lerp(v0, v1, i / subdiv);
    pts.push(jitterPt(bilerp(p00, p10, p11, p01, u1, v), jitter));
  }
  for (let i = 1; i <= subdiv; i++) {
    const u = lerp(u1, u0, i / subdiv);
    pts.push(jitterPt(bilerp(p00, p10, p11, p01, u, v1), jitter));
  }
  for (let i = 1; i < subdiv; i++) {
    const v = lerp(v1, v0, i / subdiv);
    pts.push(jitterPt(bilerp(p00, p10, p11, p01, u0, v), jitter));
  }
  return pts;
}

// Displaced ragged edge profile along the front-left vertical ridge & back-left edge
function getRaggedFL(v) {
  const base = lerpPt(T_FL, BOT_FL, v);
  const n1 = (noise(v * 8.5, 11.2) - 0.5) * 18;
  const n2 = (noise(v * 28.0, 3.7) - 0.5) * 7;
  const step = v > 0.35 ? sin(v * 950) * 3.5 : 0;
  return [base[0] + n1 + n2 + step, base[1] + (noise(v * 14, 9.1) - 0.5) * 5];
}

function getRaggedBL(v) {
  const base = lerpPt(T_BL, BOT_BL, v);
  const n1 = (noise(v * 7.2, 41.5) - 0.5) * 14;
  const n2 = (noise(v * 24.0, 18.3) - 0.5) * 6;
  return [base[0] + n1 + n2, base[1] + (noise(v * 12, 5.4) - 0.5) * 4];
}

