// ---------------------------------------------------------------------------
// 1. DIM WARM WINDOW LIGHT & ENCAUSTIC BACKGROUND
// ---------------------------------------------------------------------------
function drawAtmosphericBacklight() {
  resetBrush();

  // Deep smoked umber ground washes
  const bgLayers = [
    { col: "#1c150f", op: 160, x: 600, y: 300, w: 1250, h: 700 },
    { col: "#291f15", op: 110, x: 380, y: 240, w: 850, h: 560 },
    { col: "#3d2e1e", op: 85, x: 310, y: 190, w: 680, h: 460 },
    { col: "#544028", op: 65, x: 260, y: 150, w: 520, h: 360 },
    { col: "#6e5435", op: 45, x: 220, y: 120, w: 380, h: 270 }
  ];

  for (let l of bgLayers) {
    resetBrush();
    brush.fill(l.col, l.op);
    brush.fillBleed(0.45, "out");
    brush.fillTexture(0.65, 0.25);
    const pts = [];
    for (let a = 0; a < 360; a += 30) {
      const radX = (l.w / 2) * (0.85 + 0.3 * noise(cos(a) + 1, sin(a) + 1, l.x * 0.01));
      const radY = (l.h / 2) * (0.85 + 0.3 * noise(sin(a) + 2, cos(a) + 2, l.y * 0.01));
      pts.push([l.x + cos(a) * radX, l.y + sin(a) * radY]);
    }
    drawPoly(pts, 0.25);
  }

  // Slanted rays of dim window light (from upper-left ~32 degrees)
  resetBrush();
  for (let i = 0; i < 95; i++) {
    const t = i / 95;
    const x0 = random(-80, 750);
    const y0 = random(-60, 380);
    const len = random(180, 520);
    const ang = 32 + random(-4, 4);
    const distFromBeam = abs((x0 - 260) * 0.6 - (y0 - 140) * 0.8);
    const col = distFromBeam < 220
      ? random(["#6e5435", "#574229", "#82643f", "#42321f"])
      : random(["#241b12", "#1a130d", "#302418", "#140f0a"]);
    brush.set("wax_glaze", col, random(0.8, 2.2));
    const p1 = [x0, y0];
    const p2 = [x0 + cos(ang) * len * 0.5, y0 + sin(ang) * len * 0.5 + random(-10, 10)];
    const p3 = [x0 + cos(ang) * len, y0 + sin(ang) * len];
    brush.spline([p1, p2, p3], 0.2);
  }

  // Scraped encaustic texture in the upper dark studio background
  for (let i = 0; i < 65; i++) {
    const x = random(0, 1200);
    const y = random(0, 540);
    const len = random(70, 220);
    const ang = random([-2, 0, 2, 88, 90, 32]);
    const col = x < 680 && y < 380
      ? random(["#4a3823", "#614a2f", "#332618"])
      : random(["#1c150e", "#261d14", "#120d09"]);
    brush.set("knife_scrape", col, random(0.6, 1.4));
    brush.line(x, y, x + cos(ang) * len, y + sin(ang) * len);
  }
}

