// 2. SCARRED OAK BOARD (LAYERED WAX PATINA, GRAIN & INCISED SCRATCHES)
// ---------------------------------------------------------------------------
function drawScarredOakBoard() {
  resetBrush();

  // Warm raw-oak underlayer (revealed where scraped back)
  brush.wash("#5e462d", 230);
  drawPoly([B_TL, B_TR, B_BR, B_BL], 0.02);

  // Front-left and front-right board thickness slabs
  resetBrush();
  brush.wash("#1f160f", 245);
  drawPoly([B_TL, B_BL, B_BL_BOT, B_TL_BOT], 0.02);

  resetBrush();
  brush.wash("#140e09", 250);
  drawPoly([B_BL, B_BR, B_BR_BOT, B_BL_BOT], 0.02);

  // Dark smoked oak watercolor glazes batched by tone
  const darkPatches = [
    { u0: 0.0, u1: 0.45, v0: 0.45, v1: 1.0, col: "#261c13", op: 140 },
    { u0: 0.4, u1: 1.0, v0: 0.35, v1: 1.0, col: "#1f170f", op: 155 },
    { u0: 0.55, u1: 1.0, v0: 0.0, v1: 0.55, col: "#291e14", op: 130 },
    { u0: 0.0, u1: 0.32, v0: 0.0, v1: 0.55, col: "#36281b", op: 110 },
    { u0: 0.2, u1: 0.85, v0: 0.65, v1: 1.0, col: "#2e2217", op: 120 }
  ];

  for (let p of darkPatches) {
    resetBrush();
    brush.fill(p.col, p.op);
    brush.fillBleed(0.35, "in");
    brush.fillTexture(0.7, 0.35);
    drawPoly(makeQuadPatch(B_TL, B_TR, B_BR, B_BL, p.u0, p.u1, p.v0, p.v1, 5, 10), 0.15);
  }

  // Backlit warm oak glow behind and to the left of the butter slab
  const litBoardPatches = [
    { u0: 0.12, u1: 0.68, v0: 0.02, v1: 0.38, col: "#6e5337", op: 95 },
    { u0: 0.20, u1: 0.58, v0: 0.05, v1: 0.28, col: "#8c6b48", op: 85 },
    { u0: 0.25, u1: 0.50, v0: 0.06, v1: 0.22, col: "#a8845b", op: 65 }
  ];

  for (let p of litBoardPatches) {
    resetBrush();
    brush.fill(p.col, p.op);
    brush.fillBleed(0.4, "out");
    brush.fillTexture(0.55, 0.2);
    drawPoly(makeQuadPatch(B_TL, B_TR, B_BR, B_BL, p.u0, p.u1, p.v0, p.v1, 5, 8), 0.18);
  }

  // Scraped-back wax passages on the oak board revealing raw ochre-sienna wood underneath
  resetBrush();
  for (let i = 0; i < 85; i++) {
    const u = random(0.05, 0.92);
    const v = random(0.08, 0.92);
    const du = random(0.06, 0.18);
    const dv = random(-0.02, 0.02);
    const p1 = bilerp(B_TL, B_TR, B_BR, B_BL, u, v);
    const p2 = bilerp(B_TL, B_TR, B_BR, B_BL, constrain(u + du * 0.5, 0, 1), constrain(v + dv * 0.5, 0, 1));
    const p3 = bilerp(B_TL, B_TR, B_BR, B_BL, constrain(u + du, 0, 1), constrain(v + dv, 0, 1));

    const isBacklit = u > 0.15 && u < 0.65 && v < 0.42;
    const col = isBacklit
      ? random(["#8f6e49", "#a68258", "#6e5336", "#b89366"])
      : random(["#4d3925", "#5e462e", "#3b2b1c", "#6b5035"]);
    brush.set("knife_scrape", col, random(0.6, 1.5));
    brush.spline([p1, [p2[0], p2[1] + random(-3, 3)], p3], 0.2);
  }

  // Sweeping oak wood grain & knots mapped in perspective
  const knot1 = { u: 0.24, v: 0.62, r: 0.075 };
  const knot2 = { u: 0.78, v: 0.46, r: 0.065 };

  for (let row = 0; row < 240; row++) {
    const vBase = map(row, 0, 239, 0.01, 0.99);
    const segs = 14;
    const pts = [];
    for (let s = 0; s <= segs; s++) {
      const u = s / segs;
      let v = vBase + (noise(u * 3.2, vBase * 6.0) - 0.5) * 0.035;

      // Deflect grain organically around oak knots
      for (let k of [knot1, knot2]) {
        const du = u - k.u;
        const dv = v - k.v;
        const d = sqrt(du * du + dv * dv * 1.8);
        if (d < k.r * 2.2) {
          const push = (1 - d / (k.r * 2.2)) * 0.042 * (dv >= 0 ? 1 : -1);
          v += push;
        }
      }
      pts.push(bilerp(B_TL, B_TR, B_BR, B_BL, u, constrain(v, 0.005, 0.995)));
    }

    const isDarkRing = row % 3 === 0;
    const col = isDarkRing
      ? random(["#140e09", "#1c140d", "#0f0a06", "#261b12"])
      : (vBase < 0.38 ? random(["#785c3d", "#5e472f", "#91704b"]) : random(["#3b2c1d", "#4a3724", "#2e2216"]));
    const w = isDarkRing ? random(0.55, 1.15) : random(0.4, 0.85);
    brush.set(isDarkRing ? "2B" : "stria_blade", col, w);
    brush.spline(pts, 0.35);
  }

  // Draw the two dark oak knots & concentric growth rings
  for (let k of [knot1, knot2]) {
    const center = bilerp(B_TL, B_TR, B_BR, B_BL, k.u, k.v);
    for (let r = 28; r > 3; r -= 4) {
      const ringPts = [];
      for (let a = 0; a < 360; a += 30) {
        const radX = r * 1.45 * (0.9 + 0.2 * noise(cos(a), sin(a), r));
        const radY = r * 0.68 * (0.9 + 0.2 * noise(sin(a), cos(a), r));
        ringPts.push([center[0] + cos(a - 18) * radX, center[1] + sin(a - 18) * radY]);
      }
      brush.set("2B", r < 14 ? "#0d0905" : "#21170f", random(0.6, 1.2));
      drawPoly(ringPts, 0.3);
    }
  }

  // Deep oak pores and medullary rays
  for (let i = 0; i < 380; i++) {
    const u = random(0.02, 0.98);
    const v = random(0.02, 0.98);
    const du = random(0.008, 0.028);
    const p1 = bilerp(B_TL, B_TR, B_BR, B_BL, u, v);
    const p2 = bilerp(B_TL, B_TR, B_BR, B_BL, min(1, u + du), v + random(-0.002, 0.002));
    brush.set("incise_needle", random(["#0d0906", "#17100a", "#241910"]), random(0.5, 1.0));
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // Board front thickness vertical end-grain, saw marks & bevel highlight
  for (let i = 0; i < 160; i++) {
    const t = i / 160;
    const topPt = lerpPt(B_TL, B_BL, t);
    const botPt = lerpPt(B_TL_BOT, B_BL_BOT, t);
    brush.set("2B", random(["#120c07", "#2b1f14", "#3d2c1d", "#0a0704"]), random(0.6, 1.3));
    brush.line(topPt[0] + random(-2, 2), topPt[1], botPt[0] + random(-4, 4), botPt[1]);
  }
  for (let i = 0; i < 180; i++) {
    const t = i / 180;
    const topPt = lerpPt(B_BL, B_BR, t);
    const botPt = lerpPt(B_BL_BOT, B_BR_BOT, t);
    brush.set("2B", random(["#0a0704", "#17100a", "#241911"]), random(0.6, 1.3));
    brush.line(topPt[0] + random(-2, 2), topPt[1], botPt[0] + random(-4, 4), botPt[1]);
  }

  // Worn front bevel edge catching broken warm light
  for (let i = 0; i < 75; i++) {
    const t0 = random(0.05, 0.92);
    const t1 = min(0.98, t0 + random(0.02, 0.08));
    const pA = i < 40 ? lerpPt(B_TL, B_BL, t0) : lerpPt(B_BL, B_BR, t0);
    const pB = i < 40 ? lerpPt(B_TL, B_BL, t1) : lerpPt(B_BL, B_BR, t1);
    const col = i < 40 ? random(["#6e5438", "#876947", "#4f3b27"]) : random(["#4d3926", "#634b32", "#38291b"]);
    brush.set("knife_scrape", col, random(0.4, 0.9));
    brush.line(pA[0], pA[1], pB[0], pB[1]);
  }

  // INCISED KNIFE SCARS & SCRATCHED LINES ON THE OAK BOARD
  // Concentrated in the cutting zone around and in front of the butter slab
  for (let i = 0; i < 310; i++) {
    const inCenter = random() < 0.75;
    const u0 = inCenter ? random(0.18, 0.86) : random(0.04, 0.95);
    const v0 = inCenter ? random(0.22, 0.88) : random(0.06, 0.94);

    // Knife cut angles: mostly diagonal chopping/slicing trajectories
    const angleChoice = random();
    let du, dv;
    if (angleChoice < 0.45) {
      du = random(0.04, 0.22);
      dv = random(0.03, 0.18);
    } else if (angleChoice < 0.8) {
      du = random(0.05, 0.24);
      dv = random(-0.14, -0.02);
    } else {
      du = random(-0.04, 0.04);
      dv = random(0.06, 0.22);
    }

    const pStart = bilerp(B_TL, B_TR, B_BR, B_BL, u0, v0);
    const pMid = bilerp(B_TL, B_TR, B_BR, B_BL, u0 + du * 0.5, v0 + dv * 0.5);
    const pEnd = bilerp(B_TL, B_TR, B_BR, B_BL, constrain(u0 + du, 0.01, 0.99), constrain(v0 + dv, 0.01, 0.99));
    const curveMid = [pMid[0] + random(-4, 4), pMid[1] + random(-4, 4)];

    // Dark incised groove
    brush.set("incise_needle", random(["#0a0704", "#140e08", "#1f160d"]), random(0.45, 1.1));
    brush.spline([pStart, curveMid, pEnd], 0.15);

    // Adjacent raised/scraped wood fiber lip catching the light
    if (random() < 0.68) {
      const hiCol = (v0 < 0.45 && u0 < 0.65)
        ? random(["#b89872", "#cfb08a", "#9c7d58"])
        : random(["#7d6244", "#967856", "#ab8c68", "#614b33"]);
      brush.set("incise_needle", hiCol, random(0.35, 0.85));
      brush.spline([
        [pStart[0] + 1.2, pStart[1] + 1.4],
        [curveMid[0] + 1.2, curveMid[1] + 1.4],
        [pEnd[0] + 1.2, pEnd[1] + 1.4]
      ], 0.15);
    }
  }
}

