    [320, 660], [480, 795], [520, 875], [340, 760], [275, 690]
  ];
  resetBrush();
  brush.fill("#785519", 60);
  brush.fillBleed(0.4, "out");
  brush.fillTexture(0.5, 0.2);
  drawPoly(causticPoly2, 0.25);

  // Primary cast shadow extending to front-right from the backlit slab
  const shadowOuter = [
    [478, 795], [835, 680], [1075, 765], [1025, 865], [635, 945], [470, 830]
  ];
