  const shadowCore = [
    [478, 795], [835, 680], [955, 725], [895, 790], [565, 865], [472, 810]
  ];
  resetBrush();
  brush.fill("#0c0804", 185);
  brush.fillBleed(0.25, "in");
  brush.fillTexture(0.6, 0.35);
  drawPoly(shadowCore, 0.15);

  // Golden transmitted light heart inside the cast shadow (subsurface caustic)
  const causticHeart = [
    [610, 755], [820, 690], [910, 730], [790, 795], [625, 810]
  ];
  resetBrush();
  brush.fill("#6b4910", 90);
  brush.fillBleed(0.4, "out");
  brush.fillTexture(0.5, 0.15);
