    const pR = lerpPt(BOT_FL, BOT_FR, t);
    brush.set("charcoal", "#080503", random(0.9, 1.8));
    brush.line(pL[0] - 2, pL[1] + 1, pL[0] + 12, pL[1] + 6);
    brush.line(pR[0] - 2, pR[1] + 1, pR[0] + 16, pR[1] + 5);
  }
}

// ---------------------------------------------------------------------------
// 4. CULTURED BUTTER SLAB: LAYERED WAX UNDERLAYERS & TRANSLUCENT GLAZES
// ---------------------------------------------------------------------------
function drawButterUnderlayersAndGlazes() {
  resetBrush();

  // Build ragged outer boundary for the left cut face
  const leftFacePoly = [];
  for (let i = 0; i <= 16; i++) leftFacePoly.push(lerpPt(T_BL, T_FL, i / 16));
  for (let i = 1; i <= 20; i++) leftFacePoly.push(getRaggedFL(i / 20));
  for (let i = 1; i <= 16; i++) leftFacePoly.push(lerpPt(BOT_FL, BOT_BL, i / 16));
  for (let i = 19; i >= 1; i--) leftFacePoly.push(getRaggedBL(i / 20));

  // Build boundary for the front-right face
  const rightFacePoly = [];
  for (let i = 0; i <= 20; i++) rightFacePoly.push(getRaggedFL(i / 20));
  for (let i = 1; i <= 16; i++) rightFacePoly.push(lerpPt(BOT_FL, BOT_FR, i / 16));
  for (let i = 1; i <= 16; i++) rightFacePoly.push(lerpPt(BOT_FR, T_FR, i / 16));
  for (let i = 1; i < 16; i++) rightFacePoly.push(lerpPt(T_FR, T_FL, i / 16));

  // Top face boundary
  const topFacePoly = [T_BL, T_BR, T_FR, T_FL];

  // Step 4A: Solid opaque/waxy base washes so dark wood lines don't show through
  resetBrush();
  brush.wash("#ebb42c", 242);
  drawPoly(leftFacePoly, 0.05);

  resetBrush();
  brush.wash("#c9891d", 242);
  drawPoly(rightFacePoly, 0.05);

  resetBrush();
  brush.wash("#f7d65c", 245);
  drawPoly(topFacePoly, 0.05);

  // Step 4B: Dry-media wax masses (underlayer body in honey, buttercup, and cream)
  resetBrush();
  brush.mass("wax_glaze", "#d4901a", { precision: 0.65, strength: 0.75, gradient: 0.35, outline: false });
  drawPoly(makeQuadPatch(T_FL, T_FR, BOT_FR, BOT_FL, 0.02, 0.98, 0.02, 0.95, 5, 4), 0.1);

  resetBrush();
  brush.mass("wax_glaze", "#f2be35", { precision: 0.7, strength: 0.8, gradient: 0.3, outline: false });
  drawPoly(makeQuadPatch(T_BL, T_FL, BOT_FL, BOT_BL, 0.02, 0.98, 0.02, 0.95, 5, 4), 0.1);

  resetBrush();
  brush.mass("wax_glaze", "#fae17a", { precision: 0.75, strength: 0.8, gradient: 0.25, outline: false });
  drawPoly(makeQuadPatch(T_BL, T_BR, T_FR, T_FL, 0.02, 0.98, 0.02, 0.98, 5, 4), 0.1);

  // Step 4C: Translucent Watercolor/Wax Glazes batched by color family
  // 1) Deep Honey Glazes (core shadow & internal depth)
  const honeyGlazes = [
    makeQuadPatch(T_FL, T_FR, BOT_FR, BOT_FL, 0.0, 0.65, 0.45, 1.0, 5, 6),
    makeQuadPatch(T_FL, T_FR, BOT_FR, BOT_FL, 0.35, 1.0, 0.55, 1.0, 5, 6),
    makeQuadPatch(T_BL, T_FL, BOT_FL, BOT_BL, 0.25, 1.0, 0.62, 1.0, 5, 6)
  ];
  for (let g of honeyGlazes) {
    resetBrush();
    brush.fill("#a86811", 85);
    brush.fillBleed(0.32, "in");
    brush.fillTexture(0.65, 0.3);
    drawPoly(g, 0.18);
  }

  // 2) Glowing Buttercup Glazes (subsurface scattering where window light penetrates the fat)
  const buttercupGlazes = [
    makeQuadPatch(T_BL, T_BR, T_FR, T_FL, 0.05, 0.92, 0.08, 0.78, 5, 6),
    makeQuadPatch(T_BL, T_FL, BOT_FL, BOT_BL, 0.0, 0.85, 0.0, 0.68, 5, 6),
    makeQuadPatch(T_FL, T_FR, BOT_FR, BOT_FL, 0.0, 0.95, 0.0, 0.48, 5, 6),
    makeQuadPatch(T_BL, T_BR, T_FR, T_FL, 0.25, 0.98, 0.30, 0.92, 5, 6)
  ];
  for (let g of buttercupGlazes) {
    resetBrush();
    brush.fill("#f5bc24", 95);
    brush.fillBleed(0.38, "out");
    brush.fillTexture(0.55, 0.22);
    drawPoly(g, 0.2);
  }

  // 3) Luminous Backlit Gold Glazes (upper subsurface rim)
  const backlitGlazes = [
    makeQuadPatch(T_BL, T_BR, T_FR, T_FL, 0.0, 0.88, 0.0, 0.38, 5, 5),
    makeQuadPatch(T_BL, T_FL, BOT_FL, BOT_BL, 0.0, 0.55, 0.0, 0.42, 5, 5)
  ];
  for (let g of backlitGlazes) {
    resetBrush();
    brush.fill("#ffe261", 105);
    brush.fillBleed(0.35, "out");
    brush.fillTexture(0.45, 0.18);
    drawPoly(g, 0.2);
  }

  // 4) Soft Luminous Cream Skin Glazes (fused outer wax skin over the golden core)
  const creamGlazes = [
    makeQuadPatch(T_BL, T_BR, T_FR, T_FL, 0.02, 0.65, 0.02, 0.52, 5, 5),
    makeQuadPatch(T_FL, T_FR, BOT_FR, BOT_FL, 0.08, 0.88, 0.18, 0.82, 5, 6),
    makeQuadPatch(T_FL, T_FR, BOT_FR, BOT_FL, 0.22, 0.95, 0.35, 0.92, 5, 6),
    makeQuadPatch(T_BL, T_FL, BOT_FL, BOT_BL, 0.12, 0.78, 0.15, 0.72, 5, 5)
  ];
  for (let g of creamGlazes) {
    resetBrush();
    brush.fill("#faecc0", 90);
    brush.fillBleed(0.28, "in");
    brush.fillTexture(0.5, 0.25);
    drawPoly(g, 0.18);
  }
}

// ---------------------------------------------------------------------------
// 5. THE RAGGED CUT EDGE & FRACTURED FRONT-LEFT FACE
// ---------------------------------------------------------------------------
function drawRaggedCutFace() {
  resetBrush();

  // Upper sheared zone on Front-Left face (vertical knife-cut tracks before the snap fracture)
  for (let i = 0; i < 65; i++) {
    const u = random(0.02, 0.96);
    const v0 = random(0.01, 0.18);
    const v1 = random(0.38, 0.65);
    const pA = bilerp(T_BL, T_FL, BOT_FL, BOT_BL, u, v0);
    const pB = bilerp(T_BL, T_FL, BOT_FL, BOT_BL, u, (v0 + v1) * 0.5);
    const pC = bilerp(T_BL, T_FL, BOT_FL, BOT_BL, u, v1);

    const col = u < 0.35
      ? random(["#fff3b8", "#ffe070", "#f7ca44"])
      : random(["#f5c438", "#e3a21e", "#fae496", "#c98516"]);
    brush.set(random() < 0.5 ? "knife_scrape" : "wax_glaze", col, random(0.45, 1.1));
    brush.spline([pA, [pB[0] + random(-2, 2), pB[1]], pC], 0.15);
  }

  // Lower & border Ragged Fractured Cleavage (stepped, crumbly crystalline butter planes)
  for (let i = 0; i < 110; i++) {
    const u = random() < 0.45 ? random(0.75, 1.04) : (random() < 0.35 ? random(-0.04, 0.25) : random(0.05, 0.95));
    const v = random(0.22, 0.98);
    const wU = random(0.04, 0.14);
    const hV = random(0.03, 0.11);

    const c00 = bilerp(T_BL, T_FL, BOT_FL, BOT_BL, u, v);
    const c10 = bilerp(T_BL, T_FL, BOT_FL, BOT_BL, u + wU, v + random(-0.02, 0.02));
    const c11 = bilerp(T_BL, T_FL, BOT_FL, BOT_BL, u + wU + random(-0.03, 0.03), v + hV);
    const c01 = bilerp(T_BL, T_FL, BOT_FL, BOT_BL, u + random(-0.03, 0.03), v + hV);

    // Shadow crevice under each ragged flake
    brush.set("stria_blade", random(["#8a540b", "#a66811", "#bf7c17"]), random(0.7, 1.4));
    brush.spline([c01, [(c01[0] + c11[0]) * 0.5, (c01[1] + c11[1]) * 0.5 + 3], c11], 0.2);

    // Waxy facet body
    const facetCol = u < 0.3
      ? random(["#ffea8a", "#fae06b", "#fff5c2"])
      : (v > 0.7 ? random(["#d6941c", "#e8ac28", "#c27e14", "#f0cb6e"]) : random(["#f5c53b", "#fae078", "#e3a21e", "#fff0b3"]));
    brush.set("knife_scrape", facetCol, random(0.6, 1.35));
    brush.spline([c00, [(c00[0] + c10[0]) * 0.5, (c00[1] + c10[1]) * 0.5], c10], 0.15);

    // Crisp backlit top-left edge on the ragged flake
    if (random() < 0.65) {
      brush.set("incise_needle", random(["#fff8d6", "#ffffff", "#ffea85"]), random(0.5, 1.0));
      brush.line(c00[0], c00[1], c10[0], c10[1]);
    }
  }

  // Prominent ragged vertical cleavage along the central corner ridge (T_FL -> BOT_FL)
  for (let i = 0; i < 48; i++) {
    const v0 = i / 48;
    const v1 = (i + 1) / 48;
    const p0 = getRaggedFL(v0);
    const p1 = getRaggedFL(v1);
    const offset = random(-9, 9);
    const pMid = [(p0[0] + p1[0]) * 0.5 + offset, (p0[1] + p1[1]) * 0.5];

    // Deep honey tuck on the right of the jagged overhang
    brush.set("stria_blade", random(["#8f570d", "#ad6e14", "#c98518"]), random(0.8, 1.5));
    brush.spline([[p0[0] + 3, p0[1]], [pMid[0] + 4, pMid[1] + 2], [p1[0] + 3, p1[1]]], 0.2);

    // Bright translucent buttercup-cream highlight on the jagged ridge itself
    brush.set("stria_blade", random(["#fff7cf", "#ffea88", "#ffffff", "#f7d358"]), random(0.8, 1.6));
    brush.spline([p0, pMid, p1], 0.2);
  }

  // Back-left vertical edge (T_BL -> BOT_BL) glowing with direct window backlight
  for (let i = 0; i < 42; i++) {
    const v0 = i / 42;
    const v1 = (i + 1) / 42;
    const p0 = getRaggedBL(v0);
    const p1 = getRaggedBL(v1);
    const pMid = [(p0[0] + p1[0]) * 0.5 + random(-5, 3), (p0[1] + p1[1]) * 0.5];

    // Subsurface golden halo just inside the edge
    brush.set("wax_glaze", "#ffcf40", random(0.8, 1.5));
    brush.line(p0[0] + 6, p0[1], p1[0] + 6, p1[1]);

    // Intense backlit rim
    brush.set("stria_blade", random(["#fffbe0", "#ffffff", "#ffef9e"]), random(0.9, 1.7));
    brush.spline([p0, pMid, p1], 0.2);
  }
}

// ---------------------------------------------------------------------------
// 6. FRONT-RIGHT FACE: LAYERED WAX, SCRAPED UNDERLAYERS & KNIFE STRIATIONS
// ---------------------------------------------------------------------------
function drawFrontRightFaceAndStriations() {
  resetBrush();

  // Broad fused encaustic glazes & scraped-back passages revealing honey/buttercup underlayers
  for (let i = 0; i < 120; i++) {
    const u0 = random(0.03, 0.85);
    const v0 = random(0.04, 0.94);
    const du = random(0.08, 0.26);
    const dv = random(-0.04, 0.04);

    const p1 = bilerp(T_FL, T_FR, BOT_FR, BOT_FL, u0, v0);
    const p2 = bilerp(T_FL, T_FR, BOT_FR, BOT_FL, min(0.98, u0 + du * 0.5), constrain(v0 + dv * 0.5, 0.02, 0.98));
    const p3 = bilerp(T_FL, T_FR, BOT_FR, BOT_FL, min(0.99, u0 + du), constrain(v0 + dv, 0.02, 0.98));

    // Determine whether this stroke is outer cream skin, scraped buttercup, or deep honey underlayer
    let col;
    const r = random();
    if (v0 < 0.28) {
      // Upper subsurface glow zone
      col = r < 0.55 ? random(["#f5c338", "#ffd452", "#ebae24"]) : random(["#fae8b0", "#fff3cc"]);
    } else if (r < 0.38) {
      // Scraped-back window revealing golden honey & buttercup underlayer
      col = random(["#c48118", "#db9921", "#ebb028", "#b06f12"]);
    } else {
      // Chilled cream & honey-ivory wax skin
      col = random(["#f2dfaa", "#faecc4", "#e6cf94", "#dec282", "#fff5d6"]);
    }

    const br = random() < 0.45 ? "knife_scrape" : "wax_glaze";
    brush.set(br, col, random(0.65, 1.55));
    brush.spline([p1, [p2[0], p2[1] + random(-3, 3)], p3], 0.2);
  }

  // Distinct scraped-back recesses (horizontally & diagonally gouged wax windows)
  const scrapeZones = [
    { u0: 0.14, u1: 0.52, v0: 0.25, v1: 0.42 },
    { u0: 0.48, u1: 0.86, v0: 0.46, v1: 0.64 },
    { u0: 0.08, u1: 0.38, v0: 0.65, v1: 0.82 }
  ];

  for (let z of scrapeZones) {
    for (let s = 0; s < 22; s++) {
      const v = lerp(z.v0, z.v1, s / 22);
      const pA = bilerp(T_FL, T_FR, BOT_FR, BOT_FL, z.u0 + random(-0.02, 0.02), v);
      const pB = bilerp(T_FL, T_FR, BOT_FR, BOT_FL, (z.u0 + z.u1) * 0.5, v + random(-0.01, 0.01));
      const pC = bilerp(T_FL, T_FR, BOT_FR, BOT_FL, z.u1 + random(-0.02, 0.02), v);
      const col = s < 5
        ? "#ad6d12" // top shadow ridge of scrape
        : (s > 18 ? "#fff3c4" : random(["#d9951c", "#ebae26", "#c78316", "#f2c035"]));
      brush.set(s < 5 || s > 18 ? "stria_blade" : "knife_scrape", col, random(0.5, 1.1));
      brush.spline([pA, pB, pC], 0.15);
    }
  }

  // Faint parallel knife striations across the Front-Right face
  for (let i = 0; i < 85; i++) {
    const vBase = map(i, 0, 84, 0.03, 0.96);
    const uStart = random(0.01, 0.25);
    const uEnd = random(0.65, 0.99);
    const pts = [];
    const steps = 8;
    for (let k = 0; k <= steps; k++) {
      const u = lerp(uStart, uEnd, k / steps);
      const wave = sin(u * 180 + i * 7) * 0.008;
      pts.push(bilerp(T_FL, T_FR, BOT_FR, BOT_FL, u, constrain(vBase + wave, 0.01, 0.99)));
    }
    const isHi = i % 2 === 0;
    const col = isHi
      ? (vBase < 0.35 ? "#fff4c2" : "#fcf0cc")
      : (vBase < 0.35 ? "#d4911a" : "#bf7f19");
    brush.set("stria_blade", col, random(0.35, 0.75));
    brush.spline(pts, 0.25);
  }
}

// ---------------------------------------------------------------------------
// 7. TOP FACE: BACKLIT TRANSLUCENCY, SCRAPED TROUGH & KNIFE STRIATIONS
// ---------------------------------------------------------------------------
function drawTopFaceAndScrapedTrough() {
  resetBrush();

  // Undisturbed chilled top plateau (back-left & front-left margins of top plane)
  for (let i = 0; i < 75; i++) {
    const u0 = random(0.01, 0.78);
    const v0 = random(0.02, 0.95);
    const du = random(0.06, 0.22);
    const p1 = bilerp(T_BL, T_BR, T_FR, T_FL, u0, v0);
    const p2 = bilerp(T_BL, T_BR, T_FR, T_FL, min(0.98, u0 + du * 0.5), v0 + random(-0.03, 0.03));
    const p3 = bilerp(T_BL, T_BR, T_FR, T_FL, min(0.99, u0 + du), v0 + random(-0.04, 0.04));

    const col = v0 < 0.28
      ? random(["#fff9db", "#ffef9e", "#ffffff", "#fae278"])
      : random(["#fae69e", "#f5d465", "#fff4c4", "#ebd58d"]);
    brush.set("wax_glaze", col, random(0.6, 1.4));
    brush.spline([p1, p2, p3], 0.2);
  }

  // THE SCRAPED CONCAVE KNIFE TROUGH (sweeping from u=0.14..0.92, v=0.24..0.78 toward the curl)
  // Exposes fresh, moist, translucent buttercup and honey fat beneath the cream skin
  const troughRows = 64;
  for (let r = 0; r <= troughRows; r++) {
    const tRow = r / troughRows; // 0 = back edge of scrape, 1 = front edge of scrape
    const vStart = lerp(0.24, 0.76, tRow);
    const vEnd = lerp(0.28, 0.84, tRow);
    const uStart = 0.14 + sin(tRow * 180) * 0.04;
    const uEnd = 0.90;

    const pts = [];
    const steps = 10;
    for (let s = 0; s <= steps; s++) {
      const st = s / steps;
      const u = lerp(uStart, uEnd, st);
      const v = lerp(vStart, vEnd, st);
      const basePt = bilerp(T_BL, T_BR, T_FR, T_FL, u, v);
      // Concave dip in the middle of the scrape path
      const dip = sin(st * 180) * sin(tRow * 180) * 7.5;
      pts.push([basePt[0], basePt[1] + dip]);
    }

    // Color across the concave trough: deep honey-buttercup in the center, cream ridges at borders
    let col;
    if (tRow < 0.08 || tRow > 0.92) {
      // Raised displaced butter burr along the borders of the knife path
      col = tRow < 0.08 ? random(["#c78516", "#db9b21"]) : random(["#fffbeb", "#ffffff", "#fff2ba"]);
    } else if (tRow > 0.3 && tRow < 0.72) {
      // Translucent golden-buttercup interior of the fresh scrape
      col = (r % 3 === 0)
        ? random(["#e09d1c", "#d18b15", "#ebb026"])
        : random(["#f7c93e", "#ffd954", "#ffe680", "#f2bc2b"]);
    } else {
      col = (r % 2 === 0)
        ? random(["#f5cf53", "#fae07a", "#e8ad24"])
        : random(["#fff1b0", "#fae694", "#f2c641"]);
    }

    brush.set((r % 2 === 0) ? "stria_blade" : "knife_scrape", col, (r % 2 === 0) ? random(0.45, 0.85) : random(0.6, 1.1));
    brush.spline(pts, 0.25);
  }

  // Raised waxy burr / ridge along the front and back lip of the knife scrape
  for (let side of [0.23, 0.78]) {
    const lipPts = [];
    for (let s = 0; s <= 12; s++) {
      const st = s / 12;
      const u = lerp(0.13, 0.88, st);
      const v = side + (noise(u * 6, side * 10) - 0.5) * 0.03;
      lipPts.push(bilerp(T_BL, T_BR, T_FR, T_FL, u, v));
    }
    brush.set("stria_blade", "#ffffff", 1.1);
    brush.spline(lipPts, 0.25);
    brush.set("incise_needle", "#bd7c15", 0.7);
    brush.spline(lipPts.map(p => [p[0], p[1] + 2.2]), 0.25);
  }

  // Luminous backlit rim along the back-top edge (T_BL -> T_BR)
  for (let i = 0; i < 36; i++) {
    const u0 = i / 36;
    const u1 = (i + 1) / 36;
    const p0 = lerpPt(T_BL, T_BR, u0);
    const p1 = lerpPt(T_BL, T_BR, u1);
    const pMid = [(p0[0] + p1[0]) * 0.5, (p0[1] + p1[1]) * 0.5 + random(-2.5, 2.5)];

    brush.set("wax_glaze", "#ffe46b", 1.2);
    brush.line(p0[0], p0[1] + 5, p1[0], p1[1] + 5);

    brush.set("stria_blade", random(["#ffffff", "#fffbe0", "#fff4b8"]), random(0.9, 1.6));
    brush.spline([p0, pMid, p1], 0.2);
  }
}

// ---------------------------------------------------------------------------
// 8. THE LIFTED KNIFE CURL (SCULPTURAL TRANSLUCENT SPIRAL AT RIGHT CORNER)
// ---------------------------------------------------------------------------
function drawLiftedKnifeCurl() {
  resetBrush();

  // Parametric 3D-projected spiral curl rising from the right end of the scraped trough
  // Base origin on top face around (705, 480) -> arches up to (775, 368) -> curls into (780, 445)
  const cx = 776;
  const cy = 442;

  function curlSpiralPt(thetaDeg, axialShift = 0) {
    // thetaDeg goes from 0 (outermost base attachment) to 560 (inner spiral tip)
    const t = thetaDeg / 560;
    const radX = lerp(82, 14, pow(t, 0.82));
    const radY = lerp(68, 12, pow(t, 0.82));
    const ang = -155 + thetaDeg; // starts at bottom-left (-155 deg), arches over top (-90..0), spirals in
    // Perspective axial offset along the cylinder of the curl (back-left to front-right)
    const axX = axialShift * 42;
    const axY = axialShift * 26;
    return [
      cx + cos(ang) * radX + axX,
      cy + sin(ang) * radY + axY
    ];
  }

  // 8A. Subsurface amber-honey shadow cast by the curl onto the right corner of the butter
  const curlShadowPoly = [
    [695, 485], [765, 445], [842, 495], [835, 535], [755, 535], [690, 505]
  ];
  brush.fill("#8f560b", 115);
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.55, 0.25);
  drawPoly(curlShadowPoly, 0.2);

  // 8B. Outer & Inner Ribbon Shell Base Wash (opaque golden-ivory body so background doesn't bleed through)
  const shellPoly = [];
  for (let th = 0; th <= 230; th += 12) shellPoly.push(curlSpiralPt(th, -0.55));
  for (let th = 230; th >= 0; th -= 12) shellPoly.push(curlSpiralPt(th, 0.55));
  resetBrush();
  brush.wash("#f7d559", 248);
  drawPoly(shellPoly, 0.15);

  // Inner spiral drum fill
  const corePoly = [];
  for (let th = 160; th <= 520; th += 18) corePoly.push(curlSpiralPt(th, 0.45));
  resetBrush();
  brush.wash("#c47f15", 245);
  drawPoly(corePoly, 0.2);

  // 8C. Deep Honey & Glowing Buttercup Interior of the Spiral Tunnel
  for (let th = 190; th < 540; th += 5) {
    const pBack = curlSpiralPt(th, -0.25);
    const pMid = curlSpiralPt(th + 15, 0.12);
    const pFront = curlSpiralPt(th, 0.48);

    const depthT = map(th, 190, 540, 0, 1);
    const col = depthT > 0.55
      ? random(["#784507", "#8f540a", "#a8660f"])
      : random(["#b87414", "#d48d19", "#e8a622", "#f5c238"]);
    brush.set("wax_glaze", col, random(0.65, 1.3));
    brush.spline([pBack, pMid, pFront], 0.2);
  }

  // 8D. Translucent Backlit Glazes on the Arching Outer Ribbon
  const ribbonGlaze = [];
  for (let th = 10; th <= 215; th += 15) ribbonGlaze.push(curlSpiralPt(th, -0.52));
  for (let th = 215; th >= 10; th -= 15) ribbonGlaze.push(curlSpiralPt(th, 0.52));
  resetBrush();
  brush.fill("#ffe36e", 110);
  brush.fillBleed(0.3, "out");
  brush.fillTexture(0.45, 0.2);
  drawPoly(ribbonGlaze, 0.2);

  // 8E. Cross-Contour Waxy Ribbons & Longitudinal Knife Striations Wrapping Around the Curl
  const strips = 38;
  for (let s = 0; s <= strips; s++) {
    const ax = map(s, 0, strips, -0.56, 0.56);
    // Feathered irregular outer length per strip
    const maxTh = 235 + sin(s * 32) * 12;
    const pts = [];
    for (let th = -8; th <= maxTh; th += 14) {
      const p = curlSpiralPt(max(0, th), ax);
      if (th < 15) {
        // Blend smoothly into the scraped trough on the top face
        const blend = map(th, -8, 15, 0, 1);
        const troughAnchor = bilerp(T_BL, T_BR, T_FR, T_FL, 0.78, map(s, 0, strips, 0.30, 0.78));
        pts.push(lerpPt(troughAnchor, p, blend));
      } else {
        pts.push(p);
      }
    }

    // Lighting along the curl: brightest backlit translucency near the back-left edge (ax < 0) and top crown
    let col;
    if (ax < -0.25) {
      col = random(["#fffbe3", "#ffffff", "#ffef9e", "#fae273"]);
    } else if (ax > 0.32) {
      col = random(["#f5d056", "#e3a520", "#fae69b", "#cf8c17"]);
    } else {
      col = (s % 2 === 0)
        ? random(["#fff7cf", "#ffea8a", "#fae070"])
        : random(["#f2be30", "#e6a822", "#f7ce46"]);
    }

    brush.set((s % 2 === 0) ? "stria_blade" : "knife_scrape", col, (s % 2 === 0) ? random(0.5, 0.95) : random(0.6, 1.15));
    brush.spline(pts, 0.3);
  }

  // 8F. Natural Transverse Stress Fissures / Cracks across the Outer Bend of the Cold Butter Curl
  const fissureAngles = [38, 68, 96, 128, 158, 188];
  for (let fa of fissureAngles) {
    const ax0 = random(-0.55, -0.15);
    const ax1 = ax0 + random(0.35, 0.68);
    const f1 = curlSpiralPt(fa, ax0);
    const f2 = curlSpiralPt(fa + random(-4, 4), (ax0 + ax1) * 0.5);
    const f3 = curlSpiralPt(fa, min(0.55, ax1));

    // Warm honey-gold crevice inside the stress crack
    brush.set("incise_needle", "#b06e10", random(0.6, 1.0));
    brush.spline([f1, f2, f3], 0.15);

    // Bright backlit lip on the lower edge of the fissure
    brush.set("stria_blade", "#fffdf0", random(0.6, 1.1));
    brush.spline([[f1[0] + 1.5, f1[1] + 1.8], [f2[0] + 1.5, f2[1] + 1.8], [f3[0] + 1.5, f3[1] + 1.8]], 0.15);
  }

  // 8G. Crisp Front & Back Spiral Edges (Defining the rolled sheet thickness)
  // Back-left edge (silhouette against the dark studio background, glowing with rim light)
  const backSpiralPts = [];
  for (let th = 0; th <= 220; th += 10) {
    const p = curlSpiralPt(th, -0.56);
    backSpiralPts.push([p[0] + random(-1.5, 1.5), p[1] + random(-1.5, 1.5)]);
  }
  brush.set("stria_blade", "#ffffff", 1.5);
  brush.spline(backSpiralPts, 0.25);

  // Front-right spiral rim (coiling all the way into the center of the roll)
  const frontSpiralPts = [];
  const shadowSpiralPts = [];
  for (let th = 8; th <= 545; th += 10) {
    const p = curlSpiralPt(th, 0.56 * lerp(1, 0.25, th / 545));
    const jit = [p[0] + random(-1.2, 1.2), p[1] + random(-1.2, 1.2)];
    frontSpiralPts.push(jit);
    shadowSpiralPts.push([jit[0] - 2.5, jit[1] + 2.2]);
  }
  // Dark honey interior shadow hugging the inside of the spiral rim
  brush.set("stria_blade", "#8a5209", 1.25);
  brush.spline(shadowSpiralPts, 0.28);

  // Golden mid-rim
  brush.set("knife_scrape", "#f7cc45", 0.95);
  brush.spline(frontSpiralPts, 0.28);

  // Translucent ivory-white edge highlight on the coiled sheet rim
  brush.set("stria_blade", "#fffbeb", 1.2);
  brush.spline(frontSpiralPts, 0.28);
}

// ---------------------------------------------------------------------------
// 9. COLD-CONDENSATION BLOOM & MICRO-MOISTURE BEADS
// ---------------------------------------------------------------------------
function drawCondensationBloomAndBeads() {
  resetBrush();

  // Velvety condensation bloom mist across the chilled, unscraped surfaces
  for (let i = 0; i < 60; i++) {
    const face = random();
    let pt;
    if (face < 0.55) {
      // Front-right chilled face
      pt = bilerp(T_FL, T_FR, BOT_FR, BOT_FL, random(0.08, 0.92), random(0.22, 0.92));
    } else if (face < 0.82) {
      // Left ragged face mid-zone
      pt = bilerp(T_BL, T_FL, BOT_FL, BOT_BL, random(0.15, 0.85), random(0.18, 0.78));
    } else {
      // Unscraped front-left plateau of top face
      pt = bilerp(T_BL, T_BR, T_FR, T_FL, random(0.05, 0.48), random(0.55, 0.94));
    }
    brush.set("bloom_mist", random(["#fffdf5", "#f5eedc", "#ffffff", "#ebe1c7"]), random(0.7, 1.6));
    brush.line(pt[0], pt[1], pt[0] + random(-18, 18), pt[1] + random(-10, 10));
  }

  // Individual cold-condensation moisture micro-beads (sweat droplets on cultured butter)
  for (let i = 0; i < 115; i++) {
    const face = random();
    let pt;
    if (face < 0.58) {
      pt = bilerp(T_FL, T_FR, BOT_FR, BOT_FL, random(0.06, 0.94), random(0.16, 0.92));
    } else if (face < 0.82) {
      pt = bilerp(T_BL, T_FL, BOT_FL, BOT_BL, random(0.08, 0.88), random(0.12, 0.75));
    } else {
      pt = bilerp(T_BL, T_BR, T_FR, T_FL, random(0.04, 0.55), random(0.06, 0.32));
    }

    const rad = random(1.2, 4.2);

    // 1) Tiny dark honey cast shadow below-right of the droplet
    brush.set("incise_needle", "#9e6310", map(rad, 1.2, 4.2, 0.45, 0.95));
    brush.arc(pt[0] + rad * 0.35, pt[1] + rad * 0.4, rad, 15, 145);

    // 2) Refracted golden light inside the bottom-right belly of the droplet
    brush.set("incise_needle", "#ffe46b", map(rad, 1.2, 4.2, 0.4, 0.85));
    brush.line(pt[0] + rad * 0.1, pt[1] + rad * 0.2, pt[0] + rad * 0.5, pt[1] + rad * 0.1);

    // 3) Crisp white specular pinpoint on upper-left of the droplet
    brush.set("incise_needle", "#ffffff", map(rad, 1.2, 4.2, 0.55, 1.2));
    brush.line(pt[0] - rad * 0.35, pt[1] - rad * 0.35, pt[0] - rad * 0.1, pt[1] - rad * 0.45);
  }
}

// ---------------------------------------------------------------------------
// 10. DETACHED BUTTER CRUMBS, SMEARS & FINAL LUMINOUS HIGHLIGHTS
// ---------------------------------------------------------------------------
function drawCrumbsAndFinalHighlights() {
  resetBrush();

  // Translucent waxy butter smear on the scarred oak board near the front-left & front-right base
  for (let i = 0; i < 28; i++) {
    const isLeft = i < 16;
    const basePt = isLeft
      ? lerpPt(BOT_BL, BOT_FL, random(-0.05, 1.05))
      : lerpPt(BOT_FL, BOT_FR, random(0.0, 0.85));
    const sx = basePt[0] + random(-35, 45);
    const sy = basePt[1] + random(6, 48);
    const len = random(14, 38);
    brush.set("knife_scrape", random(["#d99b26", "#f0c248", "#fae392", "#b87b16"]), random(0.4, 0.9));
    brush.line(sx, sy, sx + len, sy - len * 0.25);
  }

  // Detached crumbly butter fragments resting on the oak board
  const crumbZones = [
    { x: 315, y: 695, r: 45, count: 14 },
    { x: 455, y: 815, r: 55, count: 18 },
    { x: 790, y: 725, r: 50, count: 12 }
  ];

  for (let cz of crumbZones) {
    for (let c = 0; c < cz.count; c++) {
      const cx = cz.x + random(-cz.r, cz.r);
      const cy = cz.y + random(-cz.r * 0.55, cz.r * 0.55);
      const sz = random(3.5, 13.0);

      const crumbPts = [];
      for (let a = 0; a < 360; a += 60) {
        const rr = sz * random(0.65, 1.25);
        crumbPts.push([cx + cos(a) * rr, cy + sin(a) * rr * 0.72]);
      }

      // Tiny cast shadow on the oak board
      resetBrush();
      brush.set("2B", "#0a0704", random(0.7, 1.3));
      brush.line(cx - sz * 0.4, cy + sz * 0.55, cx + sz * 1.1, cy + sz * 0.65);

      // Golden translucent crumb body
      resetBrush();
      brush.wash(random(["#ebb128", "#f7cc45", "#d9961b"]), 235);
      drawPoly(crumbPts, 0.15);

      // Creamy backlit top edge on each crumb
      resetBrush();
      brush.set("incise_needle", random(["#fff9d6", "#ffffff", "#ffea85"]), random(0.55, 1.1));
      brush.line(crumbPts[3][0], crumbPts[3][1], crumbPts[4][0], crumbPts[4][1]);
    }
  }

  // Final high-key specular glints along the most luminous backlit wax ridges
  resetBrush();
  const glints = [
    [lerpPt(T_BL, T_BR, 0.15), lerpPt(T_BL, T_BR, 0.42)],
    [lerpPt(T_BL, T_BR, 0.52), lerpPt(T_BL, T_BR, 0.78)],
    [lerpPt(T_BL, T_FL, 0.08), lerpPt(T_BL, T_FL, 0.35)],
    [[725, 405], [768, 376]],
    [[768, 376], [812, 386]]
  ];
  for (let g of glints) {
    brush.set("incise_needle", "#ffffff", 1.15);
    const mid = [(g[0][0] + g[1][0]) * 0.5, (g[0][1] + g[1][1]) * 0.5 - 1.5];
    brush.spline([g[0], mid, g[1]], 0.2);
  }
}

// Hyperrealist Geological Cross-Section of a Lifted Square of Lasagne
// Medium: Dense burnished coloured pencil (sienna, cadmium red, ivory, caramel)
// with cool slate/indigo undertones, steam-fogged background, and inked marginalia.

let H = []; // Horizon y-coordinates across x
const X0 = 150;
const X1 = 1050;
const W_SEC = X1 - X0;
const N_PTS = 90;
const DX = W_SEC / N_PTS;

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(4219);
  noiseSeed(4219);

  // Custom waxy burnishing coloured pencil brush
  brush.add("burnish_pencil", {
    type: "default",
    weight: 1.5,
    scatter: 0.32,
    sharpness: 0.42,
    grain: 0.58,
    opacity: 145,
    spacing: 0.24,
    pressure: [0.55, 1.25, 0.5],
    rotate: "natural",
    noise: 0.45
  });

  // Custom sharp coloured pencil point for fine detail & specular rims
  brush.add("wax_detail", {
    type: "default",
    weight: 0.7,
    scatter: 0.14,
    sharpness: 0.78,
    grain: 0.65,
    opacity: 195,
    spacing: 0.18,
    pressure: [0.4, 1.1, 0.35],
    rotate: "natural",
    noise: 0.3
  });

  // Soft misty coloured-pencil broad side stroke for steam & glazing
  brush.add("slate_glaze", {
    type: "default",
    weight: 3.2,
    scatter: 0.85,
    sharpness: 0.22,
    grain: 0.72,
    opacity: 65,
    spacing: 0.35,
    pressure: [0.3, 1.0, 0.3],
    rotate: "natural",
    noise: 0.6
  });
}

function draw() {
  translate(-width / 2, -height / 2);
  brush.noField();

  // 1. Cool archival paper ground
  background("#f1f4f8");
  drawPaperGrain();

  // 2. Build geological horizon profiles (H[0] top crust to H[9] basal contact)
  buildStrataHorizons();

  // 3. Steam-fogged cool background fading upward into blank paper
  drawSteamFogBackground();

  // 4. Basal lifted spatula/datum contact shadow & cool steel blade
  drawBasalContact();

  // 5. Render the main geological strata (underpainting + dense burnished coloured pencil)
  drawStrataUnderpainting();

  // Stratum I: Lower Pasta Sheet (H8 to H9)
  drawPastaSheet(8, 9, { thrustX: -1, crispRight: false });

  // Stratum II: Lower Bolognese Band (H7 to H8)
  drawBologneseBand(7, 8, 72, "lower");

  // Stratum III: Lower Ricotta & Béchamel Seam (H6 to H7)
  drawRicottaSeam(6, 7, "lower");

  // Stratum IV: Middle Pasta Sheet (H5 to H6) with geological thrust-overlap
  drawPastaSheet(5, 6, { thrustX: 320, crispRight: false });

  // Stratum V: Middle Bolognese Band (H4 to H5)
  drawBologneseBand(4, 5, 88, "middle");

  // Stratum VI: Upper Ricotta & Mozzarella Seam (H3 to H4) with diapir intrusions
  drawRicottaSeam(3, 4, "upper");

  // Stratum VII: Upper Pasta Sheet (H2 to H3) with thrust-overlap & baked right curl
  drawPastaSheet(2, 3, { thrustX: 690, crispRight: true });

  // Stratum VIII: Uppermost Bolognese & Cream Mingling Zone (H1 to H2)
  drawBologneseBand(1, 2, 58, "upper");

  // Stratum IX: Browned & Blistered Cheese Crust (H0 to H1)
  drawBrownedCrust(0, 1);

  // 6. Oozing Intrusions (Diapirs, Dikes & Lateral Cut-Edge Extrusions)
  drawOozingIntrusions();

  // 7. Bubbled Voids (Cut Steam & Air Vesicles across Crust, Ricotta & Ragù)
  drawBubbledVoids();

  // 8. Final Optical Burnishing, Knife-Cut Striations & Specular Glazes
  drawFinalBurnishAndKnifeMarks();

  // 9. Inked Geological Marginalia, Tick Marks & Hatched Legend Swatches (No Words)
  drawGeologicalMarginalia();

  noLoop();
}

// ---------------------------------------------------------------------------
// GEOMETRY & HELPERS
// ---------------------------------------------------------------------------

function getX(i) {
  return X0 + i * DX;
}

function interpH(hIdx, x) {
  let t = constrain((x - X0) / W_SEC, 0, 1) * N_PTS;
  let i0 = floor(t);
  let i1 = min(N_PTS, i0 + 1);
  let frac = t - i0;
  return lerp(H[hIdx][i0], H[hIdx][i1], frac);
}

function drawClosedShape(pts, curvature = 0.15) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

function buildStrataPolygon(hTop, hBot, leftBulge = 0, rightBulge = 0) {
  let pts = [];
  for (let i = 0; i <= N_PTS; i++) {
    pts.push([getX(i), H[hTop][i]]);
  }
  // Right cut wall with optional viscous bulge
  let yRTop = H[hTop][N_PTS];
  let yRBot = H[hBot][N_PTS];
  if (abs(rightBulge) > 0.5) {
    pts.push([X1 + rightBulge * 0.7, lerp(yRTop, yRBot, 0.28)]);
    pts.push([X1 + rightBulge, lerp(yRTop, yRBot, 0.55)]);
    pts.push([X1 + rightBulge * 0.65, lerp(yRTop, yRBot, 0.82)]);
  }
  for (let i = N_PTS; i >= 0; i--) {
    pts.push([getX(i), H[hBot][i]]);
  }
  // Left cut wall with optional viscous bulge
  let yLTop = H[hTop][0];
  let yLBot = H[hBot][0];
  if (abs(leftBulge) > 0.5) {
    pts.push([X0 - leftBulge * 0.65, lerp(yLTop, yLBot, 0.82)]);
    pts.push([X0 - leftBulge, lerp(yLTop, yLBot, 0.55)]);
    pts.push([X0 - leftBulge * 0.7, lerp(yLTop, yLBot, 0.28)]);
  }
  return pts;
}

function buildStrataHorizons() {
  for (let k = 0; k <= 9; k++) H[k] = [];

  for (let i = 0; i <= N_PTS; i++) {
    let x = getX(i);
    let u = i / N_PTS; // 0..1

    // H0: Top of browned cheese crust (blistered scoria caprock)
    let dome1 = -24 * exp(-pow((u - 0.14) / 0.065, 2));
    let dome2 = -31 * exp(-pow((u - 0.37) / 0.08, 2));
    let dome3 = -27 * exp(-pow((u - 0.64) / 0.075, 2));
    let dome4 = -29 * exp(-pow((u - 0.86) / 0.06, 2));
    let edgeCurl = -14 * exp(-pow((u - 0.99) / 0.035, 2)) - 8 * exp(-pow((u - 0.01) / 0.03, 2));
    let n0 = (noise(u * 6.5, 1.1) - 0.5) * 14;
    H[0][i] = 420 + dome1 + dome2 + dome3 + dome4 + edgeCurl + n0;

    // H1: Base of cheese crust / top of upper bolognese
    let sag1 = 12 * exp(-pow((u - 0.25) / 0.06, 2)) + 14 * exp(-pow((u - 0.52) / 0.07, 2));
    let n1 = (noise(u * 5.2, 2.3) - 0.5) * 12;
    H[1][i] = 456 + sag1 + n1 - 10 * exp(-pow((u - 0.99) / 0.04, 2));

    // H2: Top of upper pasta sheet (gentle fold + right baked curl)
    let fold2 = 10 * sin(u * 360 * 1.5 - 20) + (noise(u * 3.8, 3.7) - 0.5) * 8;
    let rightLift = -22 * exp(-pow((u - 1.0) / 0.07, 2));
    H[2][i] = 510 + fold2 + rightLift;

    // H3: Base of upper pasta sheet (~21px thick)
    let thickP3 = 21 + (noise(u * 4.5, 4.1) - 0.5) * 3.5;
    // Slight step at thrust fault u ≈ 0.6
    let step3 = (u > 0.58 && u < 0.64) ? 5 * sin((u - 0.58) / 0.06 * 180) : 0;
    H[3][i] = H[2][i] + thickP3 + step3;

    // H4: Base of upper ricotta seam (pinch-and-swell boudinage + diapir lobe at u=0.24 & u=0.76)
    let boudin = 14 * cos(u * 360 * 2.0) + (noise(u * 4.2, 5.5) - 0.5) * 12;
    let diapirDown1 = 32 * exp(-pow((u - 0.24) / 0.042, 2));
    let diapirDown2 = 24 * exp(-pow((u - 0.77) / 0.038, 2));
    let pinchMid = -16 * exp(-pow((u - 0.49) / 0.07, 2));
    H[4][i] = 584 + boudin + diapirDown1 + diapirDown2 + pinchMid;

    // H5: Top of middle pasta sheet (broad syncline in middle)
    let syncline = 14 * sin(u * 180) + (noise(u * 3.5, 6.8) - 0.5) * 9;
    // Upward diapir push from below at u = 0.53
    let pushUp = -11 * exp(-pow((u - 0.53) / 0.055, 2));
    H[5][i] = 668 + syncline + pushUp;

    // H6: Base of middle pasta sheet (~22px thick)
    let thickP6 = 22 + (noise(u * 4.0, 7.4) - 0.5) * 3.5;
    let step6 = (u > 0.16 && u < 0.22) ? 5 * sin((u - 0.16) / 0.06 * 180) : 0;
    H[6][i] = H[5][i] + thickP6 + step6;

    // H7: Base of lower ricotta & béchamel seam (with upward flame intrusions of ragù at u=0.12, u=0.53, u=0.85)
    let flame1 = -24 * exp(-pow((u - 0.13) / 0.035, 2));
    let flame2 = -30 * exp(-pow((u - 0.53) / 0.045, 2));
    let flame3 = -20 * exp(-pow((u - 0.85) / 0.035, 2));
    let lobeDown = 18 * exp(-pow((u - 0.35) / 0.055, 2)) + 15 * exp(-pow((u - 0.69) / 0.05, 2));
    let n7 = (noise(u * 4.8, 8.2) - 0.5) * 10;
    H[7][i] = 752 + flame1 + flame2 + flame3 + lobeDown + n7;

    // H8: Top of lower pasta sheet
    let wave8 = 5 * sin(u * 360 * 2.5) + (noise(u * 4.0, 9.1) - 0.5) * 5;
    H[8][i] = 822 + wave8;

    // H9: Basal contact (flat lifted base resting on steel lifter)
    let wave9 = (noise(u * 3.2, 10.4) - 0.5) * 2.5;
    H[9][i] = 845 + wave9;
  }
}

// ---------------------------------------------------------------------------
// 1. PAPER GRAIN & 3. STEAM-FOGGED COOL BACKGROUND
// ---------------------------------------------------------------------------

function drawPaperGrain() {
  brush.noFill();
  brush.noHatch();
  // Subtle cool architectural paper tooth
  for (let i = 0; i < 220; i++) {
    let x = random(40, 1160);
    let y = random(40, 1160);
    let len = random(18, 65);
    brush.set("2H", i % 2 === 0 ? "#dfe5ee" : "#e7ecf2", random(0.25, 0.5));
    brush.line(x, y, x + len, y + random(-2, 2));
  }
}

function drawSteamFogBackground() {
  // Cool slate-blue & Payne's grey fog behind the hot crust, fading upward into blank paper
  let bands = [
    { yTop: 350, yBot: 425, col: "#2e3e52", op: 88 },
    { yTop: 305, yBot: 365, col: "#41556b", op: 72 },
    { yTop: 260, yBot: 320, col: "#5b7188", op: 55 },
    { yTop: 215, yBot: 275, col: "#7c92a8", op: 40 },
    { yTop: 170, yBot: 230, col: "#a3b6c8", op: 26 },
    { yTop: 130, yBot: 185, col: "#cad6e3", op: 14 }
  ];

  brush.noStroke();
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.45, 0.15);

  for (let b of bands) {
    brush.fill(b.col, b.op);
    let pts = [];
    for (let i = 0; i <= 30; i++) {
      let x = lerp(X0, X1, i / 30);
      let wave = (noise(i * 0.25, b.yTop * 0.01) - 0.5) * 18;
      pts.push([x, b.yTop + wave]);
    }
    for (let i = 30; i >= 0; i--) {
      let x = lerp(X0, X1, i / 30);
      let yBottom = b.yBot > 400 ? interpH(0, x) + 8 : b.yBot + (noise(i * 0.25, b.yBot * 0.01) - 0.5) * 14;
      pts.push([x, yBottom]);
    }
    drawClosedShape(pts, 0.2);
  }
  brush.noFill();

  // Dense coloured-pencil horizontal & diagonal atmospheric shading fading upward
  let slateCols = ["#1f2c3d", "#2c3d52", "#3f536b", "#576e87", "#748ca6", "#9bb0c4", "#c2d0de", "#e0e7f0"];
  for (let row = 0; row < 150; row++) {
    let t = row / 149; // 0 at bottom (crust), 1 at top (blank paper)
    let yBase = lerp(412, 118, pow(t, 0.88));
    // Skip more strokes as we approach top blank paper
    if (random() < pow(t, 1.45) * 0.72) continue;

    let cIdx = constrain(floor(t * slateCols.length + random(-0.6, 0.6)), 0, slateCols.length - 1);
    let col = slateCols[cIdx];
    let segs = floor(map(t, 0, 1, 7, 2));

    for (let s = 0; s < segs; s++) {
      let xStart = random(X0 + 2, X1 - 95);
      let segLen = random(45, 115) * (1 - t * 0.35);
      let xEnd = min(X1 - 2, xStart + segLen);
      let y1 = yBase + random(-6, 6);
      let y2 = y1 + random(-4, 4);

      // Clip above the crust horizon
      let crustY = interpH(0, (xStart + xEnd) * 0.5);
      if (y1 > crustY + 4) continue;

      let bName = t < 0.45 ? "burnish_pencil" : "cpencil";
      let w = map(t, 0, 1, 1.35, 0.45) * random(0.8, 1.2);
      brush.set(bName, col, w);
      brush.line(xStart, y1, xEnd, y2);
    }
  }

  // Rising steam plumes & condensation wisps (burnished cool ivory & silver-blue pencil)
  let plumeCenters = [215, 310, 435, 555, 680, 795, 925, 1005];
  for (let pc of plumeCenters) {
    let nStrands = floor(random(16, 26));
    for (let s = 0; s < nStrands; s++) {
      let x0 = pc + random(-38, 38);
      let y0 = interpH(0, constrain(x0, X0, X1)) - random(2, 14);
      let heightSteam = random(110, 285);
      let pts = [];
      let steps = 9;
      for (let k = 0; k <= steps; k++) {
        let f = k / steps;
        let drift = sin(f * 240 + pc * 0.4 + s * 15) * (12 + f * 26) + (noise(pc * 0.02, f * 2.5, s) - 0.5) * 28;
        let px = constrain(x0 + drift, X0 + 4, X1 - 4);
        let py = y0 - f * heightSteam;
        let pressure = sin(f * 180) * (1 - f * 0.45);
        pts.push([px, py, max(0.15, pressure)]);
      }
      let steamCol = random(["#f1f5f9", "#e2eaf2", "#cbd8e6", "#f7f4ee", "#b2c4d6"]);
      brush.set(s % 3 === 0 ? "slate_glaze" : "cpencil", steamCol, random(0.55, 1.25));
      brush.spline(pts, 0.45);
    }
  }
}

// ---------------------------------------------------------------------------
// 4. BASAL CONTACT & LIFTED SPATULA BLADE
// ---------------------------------------------------------------------------

function drawBasalContact() {
  // Cool steel lifter plate directly beneath the lifted square of lasagne (H9)
  let bladeTop = 846;
  let bladeBot = 858;

  brush.noStroke();
  brush.wash("#232d3b", 210);
  brush.rect(X0 - 18, bladeTop, W_SEC + 36, bladeBot - bladeTop, "corner");
  brush.noWash();

  // Burnished cool steel reflections along the lifter blade
  let steelCols = ["#161e29", "#344457", "#63788f", "#9eb2c7", "#dce6f0", "#495b70"];
  for (let i = 0; i < 75; i++) {
    let x1 = random(X0 - 18, X1 - 30);
    let x2 = min(X1 + 18, x1 + random(35, 160));
    let y = random(bladeTop + 0.5, bladeBot - 0.5);
    brush.set("wax_detail", random(steelCols), random(0.5, 1.1));
    brush.line(x1, y, x2, y);
  }

  // Thin caramelized sienna/cadmium oil contact film between pasta and steel
  for (let i = 0; i < N_PTS; i++) {
    let x1 = getX(i);
    let x2 = getX(i + 1);
    let y = H[9][i];
    brush.set("wax_detail", i % 2 === 0 ? "#6b2312" : "#b84a1e", 0.9);
    brush.line(x1, y, x2, y + 1);
  }

  // Subtle cool cast shadow on the paper right under the lifted blade
  for (let k = 0; k < 45; k++) {
    let x1 = random(X0 - 14, X1 - 40);
    let x2 = min(X1 + 14, x1 + random(30, 120));
    let y = bladeBot + random(1, 9);
    brush.set("cpencil", "#9aa9ba", map(y, bladeBot, bladeBot + 10, 0.9, 0.25));
    brush.line(x1, y, x2, y);
  }
}

// ---------------------------------------------------------------------------
// 5. STRATA UNDERPAINTING (WATERCOLOR / WASH BASE FOR BURNISHING)
// ---------------------------------------------------------------------------

function drawStrataUnderpainting() {
  brush.noStroke();
  brush.fillBleed(0.06, "in");
  brush.fillTexture(0.35, 0.2);

  // Pasta sheets base wash (warm ivory-semolina)
  let pastaPairs = [[8, 9], [5, 6], [2, 3]];
  for (let pair of pastaPairs) {
    brush.wash("#e6d8b5", 225);
    drawClosedShape(buildStrataPolygon(pair[0], pair[1], 0, 0), 0.1);
    brush.noWash();
  }

  // Ricotta seams base wash (cool porcelain-ivory)
  let ricottaPairs = [[6, 7, 10, 11], [3, 4, 12, 13]];
  for (let r of ricottaPairs) {
    brush.wash("#dfe5ed", 230);
    drawClosedShape(buildStrataPolygon(r[0], r[1], r[2], r[3]), 0.15);
    brush.noWash();
  }

  // Bolognese bands base wash (rich sienna & cadmium red)
  let raguPairs = [[7, 8, 14, 15, "#872617"], [4, 5, 16, 16, "#962b1b"], [1, 2, 11, 12, "#a3311e"]];
  for (let b of raguPairs) {
    brush.wash(b[4], 235);
    drawClosedShape(buildStrataPolygon(b[0], b[1], b[2], b[3]), 0.15);
    brush.noWash();
  }

  // Browned cheese crust base wash (caramel & sienna)
  brush.wash("#c4712b", 230);
  drawClosedShape(buildStrataPolygon(0, 1, 6, 8), 0.2);
  brush.noWash();
}

// ---------------------------------------------------------------------------
// PASTA SHEETS (BURNISHED IVORY, CARAMEL & SIENNA LAMINATIONS)
// ---------------------------------------------------------------------------

function drawPastaSheet(hTop, hBot, opts) {
  // 1. Sauce-soaked top & bottom margin rims + luminous ivory al-dente core
  let nLayers = 11;
  for (let l = 0; l <= nLayers; l++) {
    let f = l / nLayers; // 0 at top contact, 0.5 in core, 1.0 at bottom contact
    let distFromCenter = abs(f - 0.5) * 2; // 0 in center, 1 at edges

    // Color progression: caramel/sienna rim -> cool buff -> bright burnished ivory core
    let col;
    if (distFromCenter > 0.78) {
      col = f < 0.5 ? "#9c4722" : "#7d583a";
    } else if (distFromCenter > 0.52) {
      col = "#c9ab79";
    } else if (distFromCenter > 0.25) {
      col = "#e5d7b5";
    } else {
      col = "#f7f2e4";
    }

    // Draw continuous segmented horizontal coloured-pencil laminations following the bed
    for (let i = 0; i < N_PTS; i += 2) {
      let iNext = min(N_PTS, i + 2);
      let x1 = getX(i);
      let x2 = getX(iNext);
      let y1 = lerp(H[hTop][i], H[hBot][i], f) + random(-0.8, 0.8);
      let y2 = lerp(H[hTop][iNext], H[hBot][iNext], f) + random(-0.8, 0.8);

      // Right-edge baked caramel/sienna crispness on upper sheet
      let segCol = col;
      if (opts.crispRight && x1 > 965) {
        let tCrisp = map(x1, 965, X1, 0, 1);
        segCol = tCrisp > 0.6 ? (random() < 0.5 ? "#7a2611" : "#b84b1e") : "#d48035";
      }

      brush.set("burnish_pencil", segCol, random(0.85, 1.35));
      brush.line(x1, y1, x2, y2);
    }
  }

  // 2. Vertical knife-cut hydration & starch micro-shading across the pasta lamina
  for (let i = 0; i <= N_PTS; i++) {
    let x = getX(i) + random(-2, 2);
    let yT = H[hTop][i];
    let yB = H[hBot][i];
    let yMid = (yT + yB) * 0.5;

    // Cool grey-ivory subtle vertical knife drag
    brush.set("wax_detail", i % 3 === 0 ? "#cfc4a8" : "#fcfaf2", 0.55);
    brush.line(x, yT + 2, x, yB - 2);

    // Bright burnished ivory center highlight
    brush.set("wax_detail", "#fffdf7", 0.85);
    brush.line(x - 3, yMid + random(-1.5, 1.5), min(X1, x + 5), yMid + random(-1.5, 1.5));
  }

  // 3. Geological Thrust-Fault / Pasta Sheet Overlap Seam
  if (opts.thrustX > 0) {
    let tx = opts.thrustX;
    let tyTop = interpH(hTop, tx - 28);
    let tyBot = interpH(hBot, tx + 28);
    // Diagonal shear plane where one pasta sheet overrides the adjacent sheet
    brush.set("wax_detail", "#6e2914", 1.1);
    brush.line(tx - 28, tyTop + 1, tx + 28, tyBot - 1);
    brush.set("wax_detail", "#c96d28", 0.9);
    brush.line(tx - 26, tyTop + 3, tx + 30, tyBot - 2);
    brush.set("wax_detail", "#fffcf2", 0.95);
    brush.line(tx - 30, tyTop, tx + 26, tyBot - 3);
  }

  // 4. Crisp dark sienna/caramel bedding plane contacts at top and bottom of pasta sheet
  for (let i = 0; i < N_PTS; i++) {
    let x1 = getX(i);
    let x2 = getX(i + 1);
    brush.set("wax_detail", "#5e2212", 0.75);
    brush.line(x1, H[hTop][i], x2, H[hTop][i + 1]);
    brush.set("wax_detail", "#472118", 0.7);
    brush.line(x1, H[hBot][i], x2, H[hBot][i + 1]);
  }
}

// ---------------------------------------------------------------------------
// RICOTTA & BÉCHAMEL SEAMS (COOL IVORY CURDS, SLATE SHADOWS, CARAMEL FAT)
// ---------------------------------------------------------------------------

function drawRicottaSeam(hTop, hBot, layerTag) {
  let bulge = layerTag === "upper" ? 12 : 10;

  // 1. Cool-palette shadow modulation & warm caramel contact aureoles
  for (let i = 0; i < N_PTS; i++) {
    let x = getX(i);
    let yT = H[hTop][i];
    let yB = H[hBot][i];
    let h = yB - yT;
    if (h < 4) continue;

    // Warm caramel/sienna diffusion along top & bottom sauce contacts
    brush.set("burnish_pencil", "#d48d46", 1.1);
    brush.line(x, yT + 2, x + DX, H[hTop][i + 1] + 2);
    brush.set("burnish_pencil", "#c77832", 1.0);
    brush.line(x, yB - 2, x + DX, H[hBot][i + 1] - 2);

    // Cool blue-grey / slate-ivory interior shadow pockets (gives hyperrealist depth)
    let nVal = noise(i * 0.18, hTop * 3.1);
    let midCol = nVal < 0.38 ? "#b8c3d1" : (nVal < 0.68 ? "#d6dde6" : "#eceff4");
    brush.set("burnish_pencil", midCol, 1.45);
    brush.line(x, yT + h * 0.35, x + DX, yT + h * 0.65);
  }

  // 2. Foliated stretched mozzarella & béchamel flow lines inside the seam
  let nStreams = 28;
  for (let s = 0; s < nStreams; s++) {
    let f = map(s, 0, nStreams - 1, 0.12, 0.88);
    let iStart = floor(random(0, N_PTS - 14));
    let iEnd = min(N_PTS, iStart + floor(random(10, 26)));
    let pts = [];
    for (let i = iStart; i <= iEnd; i += 2) {
      let x = getX(i);
      let y = lerp(H[hTop][i], H[hBot][i], f) + sin(i * 22 + s * 35) * 2.5;
      pts.push([x, y, random(0.6, 1.2)]);
    }
    if (pts.length >= 3) {
      let streamCol = random(["#f7f8fa", "#ffffff", "#e6dec8", "#c2ccd9", "#e0b375"]);
      brush.set("burnish_pencil", streamCol, random(0.75, 1.3));
      brush.spline(pts, 0.35);
    }
  }

  // 3. Granular Ricotta Curds (hundreds of tiny 3D curd aggregates)
  let nCurds = layerTag === "upper" ? 520 : 460;
  for (let c = 0; c < nCurds; c++) {
    let x = random(X0 - bulge * 0.6, X1 + bulge * 0.6);
    let yT = interpH(hTop, x);
    let yB = interpH(hBot, x);
    if (yB - yT < 7) continue;

    let y = random(yT + 3.5, yB - 3.5);
    let r = random(2.2, 5.5);

    // Cool slate-grey lower curd shadow
    brush.set("wax_detail", random(["#8f9eb0", "#a6b3c2", "#7b8a9c"]), 0.7);
    brush.line(x - r, y + r * 0.45, x + r, y + r * 0.35);

    // Burnished warm/cool ivory curd body
    brush.set("burnish_pencil", random(["#f2f4f7", "#faf8f2", "#e8ecf2"]), 0.95);
    brush.line(x - r * 0.9, y, x + r * 0.9, y - r * 0.2);

    // Bright white/ivory crown highlight
    brush.set("wax_detail", "#ffffff", 0.75);
    brush.line(x - r * 0.6, y - r * 0.45, x + r * 0.5, y - r * 0.5);
  }

  // 4. Tiny black-pepper grains, cool sage/parsley specks & nutmeg caramel flecks
  for (let p = 0; p < 75; p++) {
    let x = random(X0 - 4, X1 + 4);
    let yT = interpH(hTop, x);
    let yB = interpH(hBot, x);
    if (yB - yT < 6) continue;
    let y = random(yT + 3, yB - 3);
    let speckCol = random(["#1e2630", "#2f423c", "#425750", "#8c3d19"]);
    brush.set("wax_detail", speckCol, random(0.6, 1.0));
    brush.line(x, y, x + random(1.5, 3.5), y + random(-1.5, 1.5));
  }
}

// ---------------------------------------------------------------------------
// BOLOGNESE BANDS (CADMIUM RED, BURNT SIENNA, CARAMEL & CLASTIC MEAT GRAINS)
// ---------------------------------------------------------------------------

function drawBologneseBand(hTop, hBot, densityScale, bandTag) {
  let bulge = bandTag === "middle" ? 15 : 12;

  // 1. Deep cool-undertone shadow matrix + rich burnt sienna & cadmium red burnishing
  let matrixCols = [
    "#1c1d2b", // cool indigo-umber deep crevice
    "#3d181a", // dark mahogany-slate
    "#6e2014", // deep burnt sienna
    "#8f2b18", // rich sienna
    "#b8321e", // deep cadmium red
    "#d63f24", // bright cadmium red
    "#e6582c", // fiery cadmium scarlet
    "#c96d28", // burnt caramel
    "#e09641"  // golden caramel emulsion
  ];

  // Layered directional coloured-pencil cross-burnishing across the stratum
  let nStr = densityScale * 9;
  for (let s = 0; s < nStr; s++) {
    let x = random(X0 - bulge * 0.7, X1 + bulge * 0.7);
    let yT = interpH(hTop, x);
    let yB = interpH(hBot, x);
    let h = yB - yT;
    if (h < 5) continue;

    let f = random(0.04, 0.96);
    let y = lerp(yT, yB, f);
    let len = random(14, 48);
    let ang = random(-16, 16);
    let x2 = constrain(x + cos(ang) * len, X0 - bulge, X1 + bulge);
    let y2 = constrain(y + sin(ang) * len, interpH(hTop, x2) + 1, interpH(hBot, x2) - 1);

    // Darker sienna/indigo near basal & top contacts, brighter cadmium/caramel in middle
    let col;
    if (f < 0.16 || f > 0.84) {
      col = random(["#1c1d2b", "#3d181a", "#6e2014", "#8f2b18"]);
    } else {
      col = random(matrixCols);
    }

    brush.set("burnish_pencil", col, random(0.85, 1.55));
    brush.line(x, y, x2, y2);
  }

  // 2. Clastic Meat & Soffritto Grains (Sub-rounded geological conglomerate clasts)
  let nClasts = floor(densityScale * 2.6);
  for (let c = 0; c < nClasts; c++) {
    let cx = random(X0 - bulge * 0.5, X1 + bulge * 0.5);
    let yT = interpH(hTop, cx);
    let yB = interpH(hBot, cx);
    let h = yB - yT;
    if (h < 12) continue;

    let cy = random(yT + 6, yB - 6);
    let rx = random(4.5, min(14, h * 0.32));
    let ry = rx * random(0.55, 0.85);

    let isCarrot = random() < 0.13; // Translucent caramel-orange soffritto cube
    let isRichMeat = !isCarrot;

    if (isCarrot) {
      // Caramel-cadmium soffritto clast
      brush.set("burnish_pencil", "#b3441a", 1.0);
      brush.line(cx - rx, cy + ry * 0.5, cx + rx, cy + ry * 0.4);
      brush.set("burnish_pencil", "#e37424", 1.25);
      brush.line(cx - rx * 0.9, cy, cx + rx * 0.9, cy - ry * 0.1);
      brush.set("wax_detail", "#f7be68", 0.9);
      brush.line(cx - rx * 0.6, cy - ry * 0.45, cx + rx * 0.5, cy - ry * 0.45);
    } else {
      // Browned beef/pork clast with cool indigo-slate shadow rim, sienna core & ivory glaze
      brush.set("wax_detail", random(["#181b28", "#2e161b"]), 0.85);
      brush.line(cx - rx, cy + ry * 0.6, cx + rx * 0.9, cy + ry * 0.5);

      brush.set("burnish_pencil", random(["#541e16", "#73291a", "#8c3720"]), 1.2);
      brush.line(cx - rx * 0.95, cy + ry * 0.15, cx + rx * 0.95, cy);
      brush.line(cx - rx * 0.85, cy - ry * 0.2, cx + rx * 0.85, cy - ry * 0.25);

      // Caramelized edge & wet specular rim on clast
      brush.set("wax_detail", random(["#c96b2c", "#e08e45", "#f2d6b3"]), 0.75);
      brush.line(cx - rx * 0.65, cy - ry * 0.55, cx + rx * 0.55, cy - ry * 0.5);
    }
  }

  // 3. Glossy Emulsified Cadmium-Red & Ivory Oil Meniscus Highlights
  let nGlints = floor(densityScale * 0.95);
  for (let g = 0; g < nGlints; g++) {
    let gx = random(X0 - 6, X1 + 6);
    let yT = interpH(hTop, gx);
    let yB = interpH(hBot, gx);
    if (yB - yT < 8) continue;
    let gy = random(yT + 4, yB - 4);
    let glen = random(4, 14);

    // Bright cadmium red halo
    brush.set("wax_detail", "#eb4726", 1.0);
    brush.line(gx - 1, gy + 1, gx + glen + 1, gy + 1);
    // Razor-sharp cool ivory specular reflection of wet sauce
    brush.set("wax_detail", random(["#fffdf7", "#eef4fa", "#fae3c6"]), 0.75);
    brush.line(gx, gy, gx + glen, gy + random(-1, 1));
  }
}

// ---------------------------------------------------------------------------
// STRATUM IX: BROWNED & BLISTERED CHEESE CRUST (CAPROCK)
// ---------------------------------------------------------------------------

function drawBrownedCrust(hTop, hBot) {
  // 1. Rich Maillard reaction gradient from golden ivory base to blistered sienna/charred peaks
  for (let i = 0; i < N_PTS; i++) {
    let x1 = getX(i);
    let x2 = getX(i + 1);
    let yT1 = H[hTop][i];
    let yB1 = H[hBot][i];
    let yT2 = H[hTop][i + 1];
    let yB2 = H[hBot][i + 1];

    // How high is this blister dome? Higher domes (smaller yT) are more charred/sienna
    let blisterFactor = constrain(map(yT1, 422, 388, 0, 1), 0, 1);

    let steps = 12;
    for (let s = 0; s <= steps; s++) {
      let f = s / steps; // 0 at top surface, 1 at base of crust
      let py1 = lerp(yT1, yB1, f) + random(-1, 1);
      let py2 = lerp(yT2, yB2, f) + random(-1, 1);

      let col;
      if (f < 0.18) {
        col = blisterFactor > 0.55
          ? random(["#171b26", "#2e1c24", "#541b11"])
          : random(["#782814", "#9e3c1b", "#bd5622"]);
      } else if (f < 0.45) {
        col = blisterFactor > 0.5
          ? random(["#6e2211", "#993818", "#bf5624"])
          : random(["#c76b26", "#de8a37", "#b0481c"]);
      } else if (f < 0.75) {
        col = random(["#d98836", "#e8ad58", "#f0cb86", "#c46828"]);
      } else {
        col = random(["#f5e8c8", "#ebd4a7", "#d99b4e", "#c74822"]);
      }

      brush.set("burnish_pencil", col, random(0.95, 1.5));
      brush.line(x1, py1, x2, py2);
    }
  }

  // 2. Stretched melted mozzarella fibers & golden caramel crust blisters
  for (let k = 0; k < 140; k++) {
    let x = random(X0 - 4, X1 + 4);
    let yT = interpH(hTop, x);
    let yB = interpH(hBot, x);
    let f = random(0.15, 0.9);
    let y = lerp(yT, yB, f);
    let len = random(10, 34);
    let x2 = constrain(x + len, X0 - 4, X1 + 4);
    let y2 = lerp(interpH(hTop, x2), interpH(hBot, x2), f) + random(-2, 2);

    let c = f < 0.35 ? random(["#4a1810", "#822b14", "#d96b27"]) : random(["#fffcf2", "#f5e3be", "#e39d46"]);
    brush.set("wax_detail", c, random(0.65, 1.1));
    brush.line(x, y, x2, y2);
  }

  // 3. Crisp top crust rim highlight & blistered silhouette edge
  for (let i = 0; i < N_PTS; i++) {
    let x1 = getX(i);
    let x2 = getX(i + 1);
    let y1 = H[hTop][i];
    let y2 = H[hTop][i + 1];
    let isPeak = y1 < 404;

    brush.set("wax_detail", isPeak ? "#181c26" : "#6b2312", 1.05);
    brush.line(x1, y1, x2, y2);

    // Specular rim just below the top edge catching cool overhead light
    brush.set("wax_detail", isPeak ? "#d68238" : "#faf2de", 0.75);
    brush.line(x1, y1 + 2.2, x2, y2 + 2.2);
  }
}

// ---------------------------------------------------------------------------
// 6. OOZING INTRUSIONS (DIAPIRS, DIKES & CUT-EDGE VISCOUS DRIPS)
// ---------------------------------------------------------------------------

function drawOozingIntrusions() {
  // A. Geological Diapirs & Flame Intrusions (sauce & ricotta squeezing across horizons)
  let intrusions = [
    // Upward flame of cadmium-red/sienna bolognese intruding into lower ricotta seam
    { cx: 267, cy: 734, rx: 24, ry: 22, type: "ragu_up" },
    { cx: 627, cy: 726, rx: 32, ry: 28, type: "ragu_up" },
    { cx: 915, cy: 736, rx: 22, ry: 20, type: "ragu_up" },
    // Downward bulbous diapir lobe of creamy ricotta sinking into middle bolognese
    { cx: 366, cy: 612, rx: 30, ry: 26, type: "ricotta_down" },
    { cx: 843, cy: 604, rx: 25, ry: 22, type: "ricotta_down" },
    // Magmatic feeder dike breaching the upper pasta sheet at x = 495
    { cx: 495, cy: 520, rx: 18, ry: 26, type: "dike_breach" }
  ];

  for (let intr of intrusions) {
    let rings = 9;
    for (let r = rings; r >= 1; r--) {
      let t = r / rings;
      let pts = [];
      let nPts = 16;
      for (let k = 0; k <= nPts; k++) {
        let ang = map(k, 0, nPts, 0, 360);
        let radX = intr.rx * t * (1 + 0.15 * sin(ang * 2));
        let radY = intr.ry * t * (1 + 0.2 * cos(ang));
        // Pinch the neck of the diapir
        if (intr.type === "ragu_up" && sin(ang) > 0.3) radX *= 0.65;
        if (intr.type === "ricotta_down" && sin(ang) < -0.3) radX *= 0.65;
        pts.push([intr.cx + cos(ang) * radX, intr.cy + sin(ang) * radY, 0.9]);
      }

      let col;
      if (intr.type === "ricotta_down") {
        col = t > 0.75 ? "#c9833e" : (t > 0.45 ? "#dfe5ed" : "#ffffff");
      } else {
        col = t > 0.75 ? "#4a1912" : (t > 0.4 ? "#c9311e" : "#e87a2e");
      }
      brush.set("burnish_pencil", col, 1.15);
      brush.spline(pts, 0.4);
    }
  }

  // B. Lateral Cut-Edge Viscous Drips (oozing down the vertical knife-cut faces at X0 and X1)
  let sideDrips = [
    { x: X0 - 6, yStart: 560, yEnd: 695, col1: "#b82e1c", col2: "#f5f2e9", w: 9 },
    { x: X0 - 5, yStart: 725, yEnd: 838, col1: "#d43d22", col2: "#e39542", w: 8 },
    { x: X1 + 6, yStart: 495, yEnd: 635, col1: "#9e2716", col2: "#e64f25", w: 10 },
    { x: X1 + 5, yStart: 690, yEnd: 825, col1: "#c7351e", col2: "#f2ece1", w: 8 }
  ];

  for (let d of sideDrips) {
    let steps = 28;
    for (let s = 0; s < steps; s++) {
      let f = s / steps;
      let y = lerp(d.yStart, d.yEnd, f);
      // Tear-shaped bulb at bottom of drip
      let wCurr = d.w * (0.45 + 0.65 * pow(f, 1.6)) * sin(f * 170 + 10);
      let xIn = d.x < X0 ? X0 + 3 : X1 - 3;
      let xOut = d.x < X0 ? X0 - wCurr : X1 + wCurr;

      // Dark sienna shadow edge
      brush.set("burnish_pencil", "#3d1614", 1.1);
      brush.line(xIn, y + 1, xOut, y + 1);
      // Cadmium red & caramel body
      brush.set("burnish_pencil", f % 0.2 < 0.1 ? d.col1 : d.col2, 1.2);
      brush.line(xIn, y, xOut, y);
      // Wet specular highlight down the outer curve of the drip
      if (s % 2 === 0) {
        brush.set("wax_detail", "#ffffff", 0.8);
        brush.line(lerp(xIn, xOut, 0.72), y, lerp(xIn, xOut, 0.88), y + 3);
      }
    }
  }
}

// ---------------------------------------------------------------------------
// 7. BUBBLED VOIDS (CUT STEAM & AIR VESICLES ACROSS THE SECTION)
// ---------------------------------------------------------------------------

function drawBubbledVoids() {
  // Cut hollow vesicles sliced cleanly by the blade:
  // Deep cool Prussian-umber/sienna concave top shadow, warm/cool bounced light floor,
  // and razor-sharp ivory specular lower rim.
  let voids = [
    // In browned cheese crust (Stratum IX)
    { x: 245, y: 422, rx: 16, ry: 11, host: "crust" },
    { x: 355, y: 432, rx: 11, ry: 8,  host: "crust" },
    { x: 488, y: 414, rx: 21, ry: 13, host: "crust" },
    { x: 612, y: 435, rx: 13, ry: 9,  host: "crust" },
    { x: 732, y: 418, rx: 19, ry: 12, host: "crust" },
    { x: 878, y: 428, rx: 14, ry: 9,  host: "crust" },
    { x: 968, y: 415, rx: 15, ry: 10, host: "crust" },

    // In upper bolognese & mingling zone (Stratum VIII)
    { x: 295, y: 482, rx: 12, ry: 8,  host: "ragu" },
    { x: 565, y: 486, rx: 15, ry: 9,  host: "ragu" },
    { x: 815, y: 478, rx: 13, ry: 8,  host: "ragu" },

    // In upper ricotta seam (Stratum VI)
    { x: 215, y: 558, rx: 14, ry: 9,  host: "ricotta" },
    { x: 442, y: 560, rx: 18, ry: 11, host: "ricotta" },
    { x: 668, y: 556, rx: 12, ry: 8,  host: "ricotta" },
    { x: 895, y: 562, rx: 16, ry: 10, host: "ricotta" },

    // In middle bolognese band (Stratum V)
    { x: 258, y: 628, rx: 15, ry: 9,  host: "ragu" },
    { x: 472, y: 636, rx: 19, ry: 11, host: "ragu" },
    { x: 695, y: 622, rx: 14, ry: 9,  host: "ragu" },
    { x: 938, y: 632, rx: 16, ry: 10, host: "ragu" },

    // In lower ricotta seam (Stratum III)
    { x: 318, y: 726, rx: 15, ry: 9,  host: "ricotta" },
    { x: 525, y: 722, rx: 13, ry: 8,  host: "ricotta" },
    { x: 775, y: 728, rx: 17, ry: 10, host: "ricotta" },

    // In lower bolognese band (Stratum II - flattened by overburden pressure)
    { x: 405, y: 788, rx: 16, ry: 8,  host: "ragu" },
    { x: 660, y: 792, rx: 18, ry: 8,  host: "ragu" },
    { x: 862, y: 786, rx: 14, ry: 7,  host: "ragu" }
  ];

  for (let v of voids) {
    // 1. Dark concave interior wash
    let pts = [];
    for (let a = 0; a < 360; a += 20) {
      let rMod = 1 + 0.08 * sin(a * 3 + v.x);
      pts.push([v.x + cos(a) * v.rx * rMod, v.y + sin(a) * v.ry * rMod]);
    }
    brush.noStroke();
    brush.wash("#181c28", 230);
    drawClosedShape(pts, 0.25);
    brush.noWash();

    // 2. Concave internal shading (cool indigo-black at top of dome -> warm sienna/caramel floor)
    let bands = 10;
    for (let b = 0; b <= bands; b++) {
      let f = map(b, 0, bands, -0.9, 0.9); // -1 top of cavity, +1 bottom of cavity
      let halfW = v.rx * sqrt(max(0, 1 - f * f));
      let py = v.y + f * v.ry;

      let cavCol;
      if (f < -0.25) {
        cavCol = "#121621"; // Deep cool Prussian-black upper overhang shadow
      } else if (f < 0.25) {
        cavCol = v.host === "ricotta" ? "#3b495c" : "#471914";
      } else if (f < 0.65) {
        cavCol = v.host === "ricotta" ? "#7c8ea3" : "#8c2f19";
      } else {
        cavCol = v.host === "ricotta" ? "#c5cfd9" : "#d16e28"; // Bounced warm/cool floor light
      }

      brush.set("wax_detail", cavCol, 0.95);
      brush.line(v.x - halfW, py, v.x + halfW, py);
    }

    // 3. Stretched internal cheese/sauce filament bridging across larger voids
    if (v.rx > 15) {
      let fx = v.x + random(-v.rx * 0.35, v.rx * 0.35);
      brush.set("wax_detail", v.host === "ricotta" ? "#dce3ec" : "#c95a24", 0.65);
      brush.line(fx - 2, v.y - v.ry * 0.75, fx + 2, v.y + v.ry * 0.75);
    }

    // 4. Crisp knife-cut upper rim (dark overhang) and lower rim (bright specular lip)
    let topArc = [];
    let botArc = [];
    for (let a = 190; a <= 350; a += 20) {
      topArc.push([v.x + cos(a) * v.rx, v.y + sin(a) * v.ry, 0.9]);
    }
    for (let a = 15; a <= 165; a += 20) {
      botArc.push([v.x + cos(a) * v.rx, v.y + sin(a) * (v.ry + 1.2), 1.0]);
    }
    brush.set("wax_detail", "#0e121b", 0.95);
    brush.spline(topArc, 0.35);

    let rimCol = v.host === "ricotta" ? "#ffffff" : "#fae8c8";
    brush.set("wax_detail", rimCol, 1.05);
    brush.spline(botArc, 0.35);
  }
}

// ---------------------------------------------------------------------------
// 8. FINAL OPTICAL BURNISHING & VERTICAL KNIFE-CUT SHEAR STRIATIONS
// ---------------------------------------------------------------------------

function drawFinalBurnishAndKnifeMarks() {
  // Subtle vertical micro-striations across the entire cut face where the sharp blade sheared through
  for (let i = 0; i < 65; i++) {
    let x = random(X0 + 8, X1 - 8);
    let yTop = interpH(0, x) + random(5, 40);
    let yBot = interpH(9, x) - random(5, 30);
    let segY1 = random(yTop, yBot - 60);
    let segY2 = segY1 + random(35, 95);

    brush.set("wax_detail", i % 2 === 0 ? "#f7f3e8" : "#d8e0eb", 0.35);
    brush.line(x, segY1, x + random(-1, 1), segY2);
  }

  // High-gloss specular pinpoints on wet bolognese & ricotta edges
  for (let i = 0; i < 95; i++) {
    let x = random(X0, X1);
    let y = random(interpH(0, x) + 12, interpH(8, x) - 6);
    brush.set("wax_detail", "#ffffff", random(0.65, 1.05));
    brush.line(x, y, x + random(2, 6), y + random(-0.5, 0.5));
  }
}

// ---------------------------------------------------------------------------
// 9. INKED GEOLOGICAL MARGINALIA, TICK MARKS & HATCHED LEGEND SWATCHES
// ---------------------------------------------------------------------------

function drawGeologicalMarginalia() {
  let inkDark = "#1d2633";
  let inkMid = "#415063";
  let inkLight = "#7b8c9e";

  // A. Corner Registration Crop Marks around the whole scientific plate
  let corners = [
    [95, 110, 1, 1],
    [1105, 110, -1, 1],
    [95, 885, 1, -1],
    [1105, 885, -1, -1]
  ];
  for (let c of corners) {
    let cx = c[0], cy = c[1], dx = c[2], dy = c[3];
    brush.set("rotring", inkDark, 0.75);
    brush.line(cx, cy, cx + dx * 24, cy);
    brush.line(cx, cy, cx, cy + dy * 24);
    // Tiny registration target circle at corner
    brush.circle(cx, cy, 3.5, 0.05);
  }

  // B. Left & Right Vertical Stratigraphic Datum Axes with Horizon Tick Marks
  let leftAxisX = 122;
  let rightAxisX = 1078;
  let yAxisTop = 135;
  let yAxisBot = 860;

  brush.set("rotring", inkDark, 0.7);
  brush.line(leftAxisX, yAxisTop, leftAxisX, yAxisBot);
  brush.line(rightAxisX, yAxisTop, rightAxisX, yAxisBot);

  // Double-line outer rule on the stratigraphic columns
  brush.set("rotring", inkMid, 0.45);
  brush.line(leftAxisX - 6, yAxisTop, leftAxisX - 6, yAxisBot);
  brush.line(rightAxisX + 6, yAxisTop, rightAxisX + 6, yAxisBot);

  // Fine subdivision ticks every 10px along both vertical axes
  for (let y = yAxisTop; y <= yAxisBot; y += 10) {
    let isMajor = (y - yAxisTop) % 50 === 0;
    let tLen = isMajor ? 9 : 4.5;
    brush.set("rotring", isMajor ? inkDark : inkMid, isMajor ? 0.65 : 0.4);
    brush.line(leftAxisX - tLen, y, leftAxisX, y);
    brush.line(rightAxisX, y, rightAxisX + tLen, y);

    // Alternating hatched bar segments in the 6px column strip
    if (isMajor && y + 25 <= yAxisBot) {
      for (let hy = y + 2; hy < y + 25; hy += 3.5) {
        brush.set("rotring", inkMid, 0.35);
        brush.line(leftAxisX - 6, hy, leftAxisX, hy);
        brush.line(rightAxisX, hy, rightAxisX + 6, hy);
      }
    }
  }

  // Stratum Boundary Leader Ticks & Geometric Petrographic Markers (strictly wordless)
  for (let k = 0; k <= 9; k++) {
    let yL = H[k][0];
    let yR = H[k][N_PTS];

    // Left boundary tick & dashed extension toward cut face
    brush.set("rotring", inkDark, 0.8);
    brush.line(leftAxisX, yL, leftAxisX + 14, yL);
    brush.set("rotring", inkLight, 0.4);
    brush.line(leftAxisX + 17, yL, leftAxisX + 22, yL);

    // Right boundary tick & dashed extension
    brush.set("rotring", inkDark, 0.8);
    brush.line(rightAxisX - 14, yR, rightAxisX, yR);
    brush.set("rotring", inkLight, 0.4);
    brush.line(rightAxisX - 22, yR, rightAxisX - 17, yR);

    // Small inked geometric symbol outside the axis for each horizon (triangle / diamond)
    if (k < 9) {
      let yMidL = (H[k][0] + H[k + 1][0]) * 0.5;
      let yMidR = (H[k][N_PTS] + H[k + 1][N_PTS]) * 0.5;
      drawSymbolTick(leftAxisX - 16, yMidL, k % 3, inkDark);
      drawSymbolTick(rightAxisX + 16, yMidR, k % 3, inkDark);
    }
  }

  // C. Horizontal Geological Scale Bar below the section (y = 885)
  let sbX0 = 420;
  let sbX1 = 780;
  let sbY = 886;
  let sbH = 7;
  brush.set("rotring", inkDark, 0.65);
  brush.rect(sbX0, sbY, sbX1 - sbX0, sbH, "corner");

  let nDivs = 6;
  let divW = (sbX1 - sbX0) / nDivs;
  for (let d = 0; d <= nDivs; d++) {
    let dx = sbX0 + d * divW;
    brush.set("rotring", inkDark, 0.7);
    brush.line(dx, sbY - 5, dx, sbY + sbH + 5);

    if (d < nDivs && d % 2 === 0) {
      // Hatch alternate scale-bar blocks with dense ink lines
      for (let hx = dx + 2; hx < dx + divW; hx += 3) {
        brush.set("rotring", inkDark, 0.55);
        brush.line(hx, sbY, hx, sbY + sbH);
      }
    }
  }

  // D. Six Hatched & Burnished Legend Swatches in the Lower Margin (y = 935..1005, NO WORDS)
  let swW = 112;
  let swH = 68;
  let swGap = 32;
  let totalSwW = 6 * swW + 5 * swGap;
  let swStartX = (1200 - totalSwW) * 0.5;
  let swY = 938;

  for (let idx = 0; idx < 6; idx++) {
    let sx = swStartX + idx * (swW + swGap);
    drawLegendSwatch(sx, swY, swW, swH, idx, inkDark, inkMid);
  }
}

function drawSymbolTick(cx, cy, symType, col) {
  brush.set("rotring", col, 0.55);
  if (symType === 0) {
    // Small open diamond
    brush.line(cx, cy - 4, cx + 4, cy);
    brush.line(cx + 4, cy, cx, cy + 4);
    brush.line(cx, cy + 4, cx - 4, cy);
    brush.line(cx - 4, cy, cx, cy - 4);
  } else if (symType === 1) {
    // Small circle with horizontal tick
    brush.circle(cx, cy, 3.2, 0.05);
    brush.line(cx - 6, cy, cx + 6, cy);
  } else {
    // Small triangle pointer
    brush.line(cx - 4, cy - 3.5, cx + 4, cy);
    brush.line(cx + 4, cy, cx - 4, cy + 3.5);
    brush.line(cx - 4, cy + 3.5, cx - 4, cy - 3.5);
  }
}

function drawLegendSwatch(x, y, w, h, typeIdx, inkDark, inkMid) {
  // Swatch combines burnished coloured-pencil lithography on left/top with
  // classic petrographic inked hatching across the box.

  // 1. Base wash per lithology type
  let baseCol = ["#e8dbb8", "#dfe5ed", "#b5331e", "#d67b2c", "#6e2414", "#364759"][typeIdx];
  brush.noStroke();
  brush.wash(baseCol, 205);
  brush.rect(x, y, w, h, "corner");
  brush.noWash();

  // 2. Burnished coloured-pencil texture inside the swatch
  if (typeIdx === 0) {
    // Swatch 0: Pasta Lamina (ivory, buff & caramel horizontal laminations)
    for (let py = y + 3; py < y + h - 2; py += 3) {
      let c = (py - y < 12 || y + h - py < 12) ? "#b87940" : "#f7f2e1";
      brush.set("burnish_pencil", c, 1.1);
      brush.line(x + 2, py, x + w - 2, py);
    }
    // Inked geological bedding dashes
    for (let py = y + 10; py < y + h - 6; py += 11) {
      for (let px = x + 8; px < x + w - 10; px += 18) {
        brush.set("rotring", inkDark, 0.5);
        brush.line(px, py, px + 10, py);
      }
    }
  } else if (typeIdx === 1) {
    // Swatch 1: Ricotta Seam (cool slate-ivory curds + stippled petrographic dots)
    for (let py = y + 4; py < y + h - 3; py += 4) {
      brush.set("burnish_pencil", py % 8 < 4 ? "#f5f7fa" : "#c4cedb", 1.15);
      brush.line(x + 2, py, x + w - 2, py);
    }
    for (let k = 0; k < 42; k++) {
      let cx = random(x + 6, x + w - 6);
      let cy = random(y + 6, y + h - 6);
      brush.set("wax_detail", "#ffffff", 0.9);
      brush.line(cx - 2, cy, cx + 2, cy);
      brush.set("rotring", inkDark, 0.45);
      brush.line(cx, cy + 2, cx + 1.5, cy + 2);
    }
  } else if (typeIdx === 2) {
    // Swatch 2: Bolognese Clastic Matrix (cadmium red & sienna + inked clast polygons)
    for (let py = y + 3; py < y + h - 3; py += 3.5) {
      brush.set("burnish_pencil", random(["#8a2616", "#cf3721", "#e35629", "#4f1b16"]), 1.2);
      brush.line(x + 2, py, x + w - 2, py + random(-2, 2));
    }
    brush.hatchStyle("rotring", inkDark, 0.45);
    brush.hatch(7, 38, { rand: 0.04 });
    brush.noStroke();
    brush.rect(x + w * 0.45, y + 4, w * 0.51, h - 8, "corner");
    brush.noHatch();
  } else if (typeIdx === 3) {
    // Swatch 3: Oozing Intrusion / Diapir Fold (caramel, cadmium red & curved flow lines)
    for (let k = 0; k < 16; k++) {
      let fy = map(k, 0, 15, y + 5, y + h - 5);
      let pts = [];
      for (let s = 0; s <= 8; s++) {
        let fx = lerp(x + 3, x + w - 3, s / 8);
        let wave = sin(s / 8 * 180) * 12 * (1 - k / 20);
        pts.push([fx, constrain(fy - wave, y + 2, y + h - 2), 0.9]);
      }
      brush.set("burnish_pencil", k % 2 === 0 ? "#e08b38" : "#c93820", 1.0);
      brush.spline(pts, 0.4);
      if (k % 3 === 0) {
        brush.set("rotring", inkDark, 0.45);
        brush.spline(pts, 0.4);
      }
    }
  } else if (typeIdx === 4) {
    // Swatch 4: Browned Crust & Bubbled Voids (sienna, caramel, cool black + inked vesicles)
    for (let py = y + 3; py < y + h - 3; py += 3.5) {
      let c = py < y + h * 0.4 ? "#261e29" : (py < y + h * 0.7 ? "#9e3818" : "#e39c46");
      brush.set("burnish_pencil", c, 1.2);
      brush.line(x + 2, py, x + w - 2, py);
    }
    let vCenters = [[x + 28, y + 24, 9], [x + 62, y + 42, 11], [x + 86, y + 22, 7]];
    for (let vc of vCenters) {
      brush.set("rotring", inkDark, 0.65);
      brush.circle(vc[0], vc[1], vc[2], 0.08);
      brush.set("wax_detail", "#fff8e8", 0.85);
      brush.arc(vc[0], vc[1], vc[2] - 1, 20, 160);
    }
  } else {
    // Swatch 5: Cool Slate Steam & Basal Datum Cross-Hatching
    for (let py = y + 3; py < y + h - 3; py += 3.5) {
      let t = (py - y) / h;
      let c = t < 0.5 ? "#8fa3b8" : "#2b3b4f";
      brush.set("burnish_pencil", c, 1.15);
      brush.line(x + 2, py, x + w - 2, py);
    }
    brush.hatchStyle("rotring", inkDark, 0.42);
    brush.hatch(5.5, 45, { rand: 0.02 });
    brush.noStroke();
    brush.rect(x + 4, y + 4, w - 8, h - 8, "corner");
    brush.noHatch();

    brush.hatchStyle("rotring", inkMid, 0.38);
    brush.hatch(5.5, -45, { rand: 0.02 });
    brush.noStroke();
    brush.rect(x + w * 0.45, y + 4, w * 0.51, h - 8, "corner");
    brush.noHatch();
  }

  // 3. Crisp rotring border around the swatch + calibration ticks on all 4 sides
  brush.set("rotring", inkDark, 0.75);
  brush.rect(x, y, w, h, "corner");

  // External tick marks on swatch frame (top, bottom, left, right)
  for (let frac of [0.25, 0.5, 0.75]) {
    let tx = x + w * frac;
    brush.set("rotring", inkDark, 0.55);
    brush.line(tx, y - 5, tx, y);
    brush.line(tx, y + h, tx, y + h + 5);
  }
  for (let frac of [0.33, 0.67]) {
    let ty = y + h * frac;
    brush.set("rotring", inkDark, 0.55);
    brush.line(x - 5, ty, x, ty);
    brush.line(x + w, ty, x + w + 5, ty);
  }

  // Small graphic code bar beneath each swatch (purely geometric lines & dots, zero text)
  let barY = y + h + 13;
  brush.set("rotring", inkDark, 0.65);
  brush.line(x + 12, barY, x + w - 12, barY);
  for (let k = 0; k <= idx + 1; k++) {
    let bx = x + 20 + k * 11;
    brush.line(bx, barY - 3.5, bx, barY + 3.5);
  }
}

// Hyperrealistic Halved Ripe Fig — Impact Dot-Matrix Printer Output on Greenbar Tractor-Feed Stock

let seeds = [];
let seedGrid = [];
const GRID_MIN_U = -320;
const GRID_MAX_U = 320;
const GRID_MIN_V = -320;
const GRID_MAX_V = 360;
const GRID_CELL = 16;
const GRID_COLS = Math.ceil((GRID_MAX_U - GRID_MIN_U) / GRID_CELL);
const GRID_ROWS = Math.ceil((GRID_MAX_V - GRID_MIN_V) / GRID_CELL);

let doubleStrikeRows = new Set();

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(8472);
  noiseSeed(8472);

  // Register custom impact-printer round pin brushes (called after scaleBrushes so weights stay exact)
  // Using weight: 2.2, spacing: 0.45 guarantees 1-2 tight overlapping stamps on a 1.05px micro-segment
  const dotConfigs = [
    { name: "pin_1", diam: 0.95, op: 165, scatter: 0.02 },
    { name: "pin_2", diam: 1.55, op: 185, scatter: 0.03 },
    { name: "pin_3", diam: 2.25, op: 205, scatter: 0.04 },
    { name: "pin_4", diam: 2.95, op: 225, scatter: 0.04 },
    { name: "pin_5", diam: 3.65, op: 242, scatter: 0.05 }
  ];

  for (let cfg of dotConfigs) {
    const d = cfg.diam;
    brush.add(cfg.name, {
      type: "custom",
      weight: 2.2,
      scatter: cfg.scatter,
      opacity: cfg.op,
      spacing: 0.45,
      pressure: (t) => 1,
      tip: (_m) => {
        _m.circle(0, 0, d);
        _m.circle(0, 0, d * 0.72);
      },
      rotate: "none",
      markerTip: false,
      noise: 0
    });
  }

  // Dense multi-dot horizontal carriage burst brush for deep shadow runs
  brush.add("pin_burst", {
    type: "custom",
    weight: 3.6,
    scatter: 0.05,
    opacity: 235,
    spacing: 0.52,
    pressure: (t) => 1,
    tip: (_m) => {
      _m.circle(0, 0, 2.35);
      _m.rect(-0.85, -0.85, 1.7, 1.7);
    },
    rotate: "none",
    markerTip: false,
    noise: 0
  });

  initSeedField();
  initPrinterRowAnomalies();
}

function draw() {
  translate(-width / 2, -height / 2);
  brush.noField();

  // 1. Render continuous tractor-feed greenbar paper stock
  drawTractorFeedPaper();

  // 2. Render the halved ripe fig & cast shadow in rigid horizontal rows of round ink dots
  drawImpactPrinterFig();

  noLoop();
}

// ---------------------------------------------------------------------------
// ANATOMICAL GEOMETRY & SEED INITIALIZATION
// ---------------------------------------------------------------------------

function getSpineU(v) {
  if (v < -110) {
    let t = constrain((-110 - v) / 325, 0, 1);
    return 62 * Math.pow(t, 1.85) + 12 * Math.sin(t * Math.PI);
  } else {
    let t = constrain((v + 110) / 455, 0, 1);
    return -7 * Math.sin(t * Math.PI);
  }
}

function getFigWidths(v, angleRad) {
  // Returns { wOuterLeft, wOuterRight, wCutLeft, wCutRight, pithThick }
  if (v < -432 || v > 342) return null;

  // Woody stem region: v in [-432, -345]
  if (v < -345) {
    let t = (v - (-432)) / 87; // 0 at stem tip, 1 at neck collar
    let stemW = 24 - 4 * Math.sin(t * Math.PI) + 12 * Math.pow(t, 2.2);
    let n = 2.0 * (noise(v * 0.04, 1.2) - 0.5);
    return {
      isStem: true,
      wOuterLeft: stemW + n,
      wOuterRight: stemW + 3 + n,
      wCutLeft: 0,
      wCutRight: 0,
      pithThick: 0
    };
  }

  // Main pyriform body: v in [-345, 342]
  let s = (v - (-345)) / 687; // 0 at top of neck, 1 at ostiole base
  let baseProfile;
  if (s < 0.24) {
    // Slender concave neck flaring into shoulders
    let k = s / 0.24;
    baseProfile = 32 + 78 * Math.pow(k, 1.65);
  } else if (s < 0.65) {
    // Swelling into plump lower belly
    let k = (s - 0.24) / 0.41;
    let ease = 0.5 - 0.5 * Math.cos(k * Math.PI);
    baseProfile = 110 + 168 * Math.pow(ease, 0.88);
  } else {
    // Rounding down to bottom apex & ostiole
    let k = (s - 0.65) / 0.35;
    let close = Math.pow(Math.max(0, 1 - Math.pow(k, 1.75)), 0.58);
    baseProfile = 24 + 254 * close;
    // Slight ostiole dimple at very bottom
    if (s > 0.95) {
      let d = (s - 0.95) / 0.05;
      baseProfile -= 11 * Math.sin(d * Math.PI * 0.5);
    }
  }

  // Subtle organic lobing & longitudinal skin ribs
  let ribL = 4.5 * Math.sin(s * 14) + 5.0 * (noise(s * 3.5, 10.4) - 0.5);
  let ribR = 5.5 * Math.cos(s * 12) + 6.0 * (noise(s * 3.5, 25.7) - 0.5);

  // Left side shows cut edge with a crisp dark aubergine skin rim;
  // Right side & upper shoulder swell outward in 3D showing bruised aubergine skin dome
  let wCutLeft = baseProfile * 0.96 + ribL;
  let wCutRight = baseProfile * 0.98 + ribR;

  let skinRimLeft = 10.5 + 3.5 * Math.sin(s * Math.PI) + 2.0 * noise(s * 8, 3.1);
  // 3D visible shoulder of bruised aubergine skin on right side & upper neck
  let shoulder3D = 54 * Math.sin(Math.pow(s, 0.72) * Math.PI) + 18 * (1 - s);
  if (s < 0.16) {
    shoulder3D += 22 * (1 - s / 0.16);
  }
  let skinRimRight = 13 + shoulder3D + 3.0 * noise(s * 7, 9.3);

  // Pith thickness around the interior cut face
  let pithThick = 25 + 9 * Math.pow(Math.abs(s - 0.58) * 1.8, 1.6);
  if (s < 0.22) {
    pithThick += 45 * Math.pow((0.22 - s) / 0.22, 1.5);
  }
  if (s > 0.86) {
    pithThick += 16 * Math.pow((s - 0.86) / 0.14, 1.3);
  }

  return {
    isStem: false,
    s: s,
    wOuterLeft: wCutLeft + skinRimLeft,
    wOuterRight: wCutRight + skinRimRight,
    wCutLeft: wCutLeft,
    wCutRight: wCutRight,
    pithThick: pithThick
  };
}

function initSeedField() {
  for (let i = 0; i < GRID_COLS * GRID_ROWS; i++) {
    seedGrid[i] = [];
  }

  // Generate ~430 stratified, non-overlapping fig achenes (seeds) inside the garnet flesh
  const FleshCenterV = 58;
  let attempts = 0;
  while (seeds.length < 440 && attempts < 14000) {
    attempts++;
    // Sample v inside the flesh cavity [-185, 295]
    let v = random(-182, 292);
    let geom = getFigWidths(v, 0);
    if (!geom || geom.isStem) continue;

    // Flesh horizontal bounds at this v
    let maxU = geom.wCutRight - geom.pithThick - 8;
    let minU = -(geom.wCutLeft - geom.pithThick - 8);
    if (maxU <= minU + 15) continue;

    let u = random(minU, maxU);

    // Compute normalized radial distance from central lumen
    let du = u;
    let dv = (v - FleshCenterV) * 0.76;
    let r = Math.sqrt(du * du + dv * dv);
    let ang = Math.atan2(v - FleshCenterV, u);

    // Exclude central hollow lumen cleft and bottom ostiole channel
    let lumenR = 26 + 9 * Math.sin(ang * 7) + 6 * Math.cos(ang * 4 - 0.8);
    if (r < lumenR + 5) continue;
    if (v > 140 && Math.abs(u) < 16 + 4 * Math.sin(v * 0.08)) continue;

    // Also check elliptical cap at top and bottom of flesh cavity
    let halfSpanU = 0.5 * (maxU - minU);
    let midU = 0.5 * (maxU + minU);
    let normU = Math.abs(u - midU) / Math.max(1, halfSpanU);
    if (normU > 0.94) continue;
    if (v < -145) {
      let topCap = (-145 - v) / 38;
      if (normU * normU + topCap * topCap > 0.92) continue;
    }
    if (v > 255) {
      let botCap = (v - 255) / 38;
      if (normU * normU + botCap * botCap > 0.92) continue;
    }

    // Minimum distance rejection for realistic packed drupelet spacing
    let minDist = 11.8 + 2.2 * noise(u * 0.02, v * 0.02);
    let gx = Math.floor((u - GRID_MIN_U) / GRID_CELL);
    let gy = Math.floor((v - GRID_MIN_V) / GRID_CELL);
    if (gx < 1 || gx >= GRID_COLS - 1 || gy < 1 || gy >= GRID_ROWS - 1) continue;

    let tooClose = false;
    for (let ny = gy - 1; ny <= gy + 1 && !tooClose; ny++) {
      for (let nx = gx - 1; nx <= gx + 1; nx++) {
        let cell = seedGrid[ny * GRID_COLS + nx];
        for (let k = 0; k < cell.length; k++) {
          let sOther = seeds[cell[k]];
          let d2 = (u - sOther.u) * (u - sOther.u) + (v - sOther.v) * (v - sOther.v);
          if (d2 < minDist * minDist) {
            tooClose = true;
            break;
          }
        }
      }
    }
    if (tooClose) continue;

    let seedIdx = seeds.length;
    let seedObj = {
      u: u,
      v: v,
      ang: ang + random(-0.22, 0.22),
      cosA: 0,
      sinA: 0,
      a: random(4.6, 6.3), // semi-major axis (teardrop length)
      b: random(2.8, 3.9), // semi-minor axis (teardrop width)
      shine: random(0.78, 1.05),
      shade: random(-0.05, 0.06)
    };
    seedObj.cosA = Math.cos(seedObj.ang);
    seedObj.sinA = Math.sin(seedObj.ang);

    seeds.push(seedObj);
    seedGrid[gy * GRID_COLS + gx].push(seedIdx);
  }
}

function initPrinterRowAnomalies() {
  // Select specific horizontal scanline indices to double-strike darker
  const strikes = [
    48, 63, 79, 80, 96, 114, 131, 132, 149, 168, 183, 197, 198, 214, 229
  ];
  for (let r of strikes) doubleStrikeRows.add(r);
}

// ---------------------------------------------------------------------------
// CONTINUOUS TRACTOR-FEED GREENBAR PAPER STOCK
// ---------------------------------------------------------------------------

function drawTractorFeedPaper() {
  // Dark cool slate desk margin at far left and right edges
  background("#22282e");

  // Main tractor-feed paper sheet (x = 20..1180)
  brush.noStroke();
  brush.wash("#f0f3ee", 255);
  brush.rect(20, 0, 1160, 1200, "corner");
  brush.noWash();

  // Subtle paper fiber wash
  brush.fill("#e2eae4", 42);
  brush.fillBleed(0.25, "in");
  brush.fillTexture(0.45, 0.12);
  brush.rect(24, 0, 1152, 1200, "corner");
  brush.noFill();

  // Alternating pale mint-green horizontal bands (classic 13-row = 54.6px greenbar)
  const bandH = 54.6;
  const startY = 33.0;
  const bandLeft = 122;
  const bandRight = 1078;
  const bandW = bandRight - bandLeft;

  // Batch all mint-green wash bands together for speed and crisp uniformity
  brush.noStroke();
  brush.wash("#d4e7dc", 190);
  for (let b = 0; b < 21; b += 2) {
    let by = startY + b * bandH;
    if (by + bandH <= 1185) {
      brush.rect(bandLeft, by, bandW, bandH, "corner");
    }
  }
  brush.noWash();

  // Crisp lithographic mint-green rules & faint 3-subband accounting lines
  brush.set("2H", "#89b79e", 0.36);
  for (let b = 0; b < 21; b += 2) {
    let by = startY + b * bandH;
    if (by + bandH <= 1185) {
      brush.line(bandLeft, by, bandRight, by);
      brush.line(bandLeft, by + bandH, bandRight, by + bandH);
    }
  }

  // Faint internal sub-rules inside each band
  brush.set("2H", "#b2d1c0", 0.22);
  for (let b = 0; b < 21; b++) {
    let by = startY + b * bandH;
    if (by + bandH <= 1185) {
      brush.line(bandLeft, by + bandH * 0.333, bandRight, by + bandH * 0.333);
      brush.line(bandLeft, by + bandH * 0.667, bandRight, by + bandH * 0.667);
    }
  }

  // Left and right greenbar table border lines + index column divider
  brush.set("2H", "#7ea992", 0.42);
  brush.line(bandLeft, startY, bandLeft, startY + 20 * bandH + bandH);
  brush.line(bandLeft + 22, startY, bandLeft + 22, startY + 20 * bandH + bandH);
  brush.line(bandRight, startY, bandRight, startY + 20 * bandH + bandH);

  // Tiny row-group calibration ticks inside the left greenbar index column
  brush.set("rotring", "#6c9881", 0.35);
  for (let b = 0; b <= 20; b++) {
    let by = startY + b * bandH;
    if (by <= 1180) {
      brush.line(bandLeft + 6, by + 14, bandLeft + 15, by + 14);
      brush.line(bandLeft + 8, by + 27, bandLeft + 14, by + 27);
      brush.line(bandLeft + 6, by + 41, bandLeft + 15, by + 41);
    }
  }

  // Vertical tear-off sprocket margin perforations at x = 104 and x = 1096
  // Plus horizontal fanfold perforations at y = 18 and y = 1182
  brush.set("2H", "#8d9993", 0.48);
  for (let y = 4; y < 1196; y += 7.5) {
    brush.line(104, y, 104, y + 4.0);
    brush.line(1096, y, 1096, y + 4.0);
  }
  for (let x = 22; x < 1178; x += 8.0) {
    brush.line(x, 18, x + 4.2, 18);
    brush.line(x, 1182, x + 4.2, 1182);
  }

  // Highlight ridge next to perforation slits for 3D embossed paper feel
  brush.set("2H", "#ffffff", 0.42);
  for (let y = 4; y < 1196; y += 7.5) {
    brush.line(105.3, y, 105.3, y + 3.8);
    brush.line(1094.7, y, 1094.7, y + 3.8);
  }

  // Outer paper edge deckle/shadow
  brush.set("2B", "#14181c", 0.75);
  brush.line(20, 0, 20, 1200);
  brush.line(1180, 0, 1180, 1200);

  // Tractor-feed sprocket holes down both margins (x = 62 and x = 1138)
  const holeSpacing = bandH; // 54.6px
  const holeStart = startY + bandH * 0.5;
  const holeRadius = 12.0;

  // Batch dark hole interiors
  brush.noStroke();
  brush.wash("#22282e", 250);
  for (let hy = holeStart; hy < 1180; hy += holeSpacing) {
    brush.circle(62, hy, holeRadius, 0.03);
    brush.circle(1138, hy, holeRadius, 0.03);
  }
  brush.noWash();

  // Crisp die-cut rims and tractor-pin pull notches on each sprocket hole
  brush.set("2H", "#7f8c86", 0.38);
  for (let hy = holeStart; hy < 1180; hy += holeSpacing) {
    brush.circle(62, hy, holeRadius + 0.4, 0.03);
    brush.circle(1138, hy, holeRadius + 0.4, 0.03);
    // Tiny top/bottom pin-pull stress ticks
    brush.line(62, hy - holeRadius - 2.2, 62, hy - holeRadius + 0.5);
    brush.line(1138, hy - holeRadius - 2.2, 1138, hy - holeRadius + 0.5);
  }
  brush.set("2H", "#ffffff", 0.45);
  for (let hy = holeStart; hy < 1180; hy += holeSpacing) {
    brush.arc(62, hy, holeRadius + 0.8, 25, 145);
    brush.arc(1138, hy, holeRadius + 0.8, 25, 145);
  }
}

// ---------------------------------------------------------------------------
// HYPERREALISTIC FIG SHADING & IMPACT DOT-MATRIX ENGINE
// ---------------------------------------------------------------------------

function evaluateFigAt(x, y, cosTilt, sinTilt) {
  const figCX = 582;
  const figCY = 638;

  // Transform canvas (x, y) into tilted fig frame (u, v)
  let dx = x - figCX;
  let dy = y - figCY;
  let u = dx * cosTilt + dy * sinTilt;
  let v = -dx * sinTilt + dy * cosTilt;

  let spineU = getSpineU(v);
  let uRel = u - spineU;

  let geom = getFigWidths(v, 0);

  // Check if inside the fig silhouette
  let insideFig = false;
  if (geom) {
    if (uRel >= -geom.wOuterLeft && uRel <= geom.wOuterRight) {
      // Round the very top tip of the stem and very bottom apex smoothly
      if (v < -418) {
        let tipCap = (-418 - v) / 14;
        let normU = uRel / geom.wOuterRight;
        insideFig = (normU * normU + tipCap * tipCap) <= 1.0;
      } else if (v > 328) {
        let botCap = (v - 328) / 14;
        let normU = uRel / Math.max(12, geom.wOuterRight);
        insideFig = (normU * normU + botCap * botCap) <= 1.0;
      } else {
        insideFig = true;
      }
    }
  }

  if (!insideFig) {
    // Evaluate directional cast shadow on the paper (cast toward lower-right)
    let shU = u - 46;
    let shV = v - 38;
    let shSpine = getSpineU(shV);
    let shURel = shU - shSpine;
    let shGeom = getFigWidths(shV, 0);
    if (shGeom && !shGeom.isStem && shV > -260 && shV < 355) {
      let wL = shGeom.wOuterLeft * 0.92;
      let wR = shGeom.wOuterRight * 1.16;
      if (shURel > -wL && shURel < wR) {
        let normDist = shURel >= 0 ? shURel / wR : Math.abs(shURel) / wL;
        if (normDist < 1.0) {
          // Distance from actual fruit boundary for dark contact occlusion vs soft penumbra
          let edgeDist = 0;
          if (geom) {
            edgeDist = uRel > 0 ? (uRel - geom.wOuterRight) : ( -uRel - geom.wOuterLeft);
          } else {
            edgeDist = v - 340;
          }
          edgeDist = Math.max(0, edgeDist);
          let contact = Math.exp(-edgeDist / 16.0);
          let penumbra = Math.pow(1 - normDist, 1.8) * Math.exp(-edgeDist / 72.0);
          let shDark = constrain(0.76 * contact + 0.34 * penumbra, 0, 0.86);
          if (shDark > 0.035) {
            return { black: shDark, magenta: 0, zone: "shadow" };
          }
        }
      }
    }
    return { black: 0, magenta: 0, zone: "outside" };
  }

  // 1. WOODY STEM (PEDUNCLE)
  if (geom.isStem) {
    let wSpan = geom.wOuterLeft + geom.wOuterRight;
    let tU = (uRel + geom.wOuterLeft) / wSpan; // 0 left, 1 right
    // Oblique cut woody ring at the very top of the stem
    let ovalD = Math.pow(uRel / (wSpan * 0.44), 2) + Math.pow((v - (-422)) / 8.5, 2);
    if (ovalD < 1.0) {
      let ring = Math.abs(Math.sqrt(ovalD) - 0.68) < 0.16 ? 0.62 : 0.28;
      return { black: ring + 0.12 * noise(u * 0.2, v * 0.2), magenta: 0, zone: "stem" };
    }
    // Cylindrical shading + fibrous woody ridges
    let cyl = 0.28 + 0.62 * Math.pow(tU, 1.35);
    let ridges = 0.16 * Math.sin(uRel * 0.65 + noise(u * 0.08, v * 0.05) * 3.0);
    let collarDark = v > -362 ? 0.18 * ((v - (-362)) / 17) : 0;
    let blk = constrain(cyl + ridges + collarDark, 0.14, 0.94);
    return { black: blk, magenta: 0, zone: "stem" };
  }

  // Check if point lies on the outer 3D Bruised Aubergine Skin or inside the Cut Face
  let cutTopV = -332;
  let cutBotV = 330;
  let inCutV = (v >= cutTopV && v <= cutBotV);
  let effCutL = geom.wCutLeft;
  let effCutR = geom.wCutRight;
  if (v < -290) {
    let k = constrain((v - cutTopV) / 42, 0, 1);
    effCutL *= Math.sqrt(k);
    effCutR *= Math.sqrt(k);
  } else if (v > 300) {
    let k = constrain((cutBotV - v) / 30, 0, 1);
    effCutL *= Math.sqrt(k);
    effCutR *= Math.sqrt(k);
  }

  let insideCutFace = inCutV && (uRel >= -effCutL && uRel <= effCutR);

  // 2. BRUISED AUBERGINE SKIN (Outer rim + 3D rounded shoulder & neck)
  if (!insideCutFace) {
    let isRightShoulder = uRel > 0;
    let distFromOuter = isRightShoulder ? (geom.wOuterRight - uRel) : (geom.wOuterLeft + uRel);
    let skinWidth = isRightShoulder ? (geom.wOuterRight - effCutR) : (geom.wOuterLeft - effCutL);
    let rimPos = constrain(distFromOuter / Math.max(4, skinWidth), 0, 1);

    // Longitudinal ribs flowing from stem to ostiole
    let s = geom.s;
    let normHoriz = uRel / Math.max(20, geom.wOuterRight);
    let ribPhase = normHoriz * 19.0 + 1.5 * noise(u * 0.015, v * 0.015);
    let ribWave = Math.sin(ribPhase);

    // Deep aubergine base + dark bruise patches + dusty waxy bloom highlight on upper-left
    let bruisePatch1 = noise(u * 0.012 + 4.1, v * 0.012 + 8.3);
    let bruisePatch2 = noise(u * 0.028 + 19.2, v * 0.022 + 2.7);
    let bruise = (bruisePatch1 > 0.52 ? 0.24 * (bruisePatch1 - 0.52) * 2.1 : 0) +
                 (bruisePatch2 > 0.56 ? 0.18 : -0.06);

    let baseSkin = 0.72 + bruise + 0.09 * ribWave;

    // 3D form lighting across the skin dome
    if (isRightShoulder) {
      // Rounded 3D right flank: catches a cool waxy bloom band along its upper ridge,
      // then rolls into deep aubergine-black core shadow and subtle reflected edge light
      let domeArc = Math.sin(rimPos * Math.PI);
      let upperBloom = (s < 0.58) ? (1 - s / 0.58) * 0.34 * Math.pow(domeArc, 1.4) : 0;
      let coreShadow = 0.22 * Math.sin(rimPos * Math.PI * 0.85);
      // Dark knife-cut epidermis line right at the cut edge (rimPos -> 1)
      let epidermisEdge = rimPos > 0.84 ? 0.22 * ((rimPos - 0.84) / 0.16) : 0;
      baseSkin = baseSkin - upperBloom + coreShadow + epidermisEdge;
    } else {
      // Left-side cut skin rim catches upper-left light on outer edge, dark epidermis on inner cut edge
      let leftLight = (s < 0.72) ? 0.28 * (1 - rimPos) * (1 - s * 0.5) : 0.08 * (1 - rimPos);
      let innerEpidermis = rimPos > 0.65 ? 0.25 : 0;
      baseSkin = baseSkin - leftLight + innerEpidermis;
    }

    // Tiny pale skin lenticels (pores) scattered on the dark aubergine skin
    let pore = noise(u * 0.38, v * 0.38);
    if (pore > 0.79 && rimPos > 0.12 && rimPos < 0.88) {
      baseSkin -= 0.42;
    }

    return { black: constrain(baseSkin, 0.16, 0.98), magenta: 0, zone: "skin" };
  }

  // 3. INSIDE THE CUT FACE: CREAM PITH vs. OSTIOLE vs. SEED-PACKED GARNET FLESH
  let distLeft = uRel + effCutL;
  let distRight = effCutR - uRel;
  let distHorizEdge = Math.min(distLeft, distRight);

  // Radial angle around the syconium center (0, 58)
  const fleshCenterV = 58;
  let ang = Math.atan2(v - fleshCenterV, uRel);

  // Scalloped, fibrous pith-to-flesh boundary where pale vascular bundles radiate inward
  let fiberScallop = 6.5 * Math.sin(ang * 38) + 4.5 * Math.cos(ang * 23 + 1.2) +
                     8.0 * (noise(Math.cos(ang) * 3.5, Math.sin(ang) * 3.5) - 0.5);
  let localPithThick = geom.pithThick + fiberScallop;

  // Also check top neck pith closure (v < -185) and bottom base pith (v > 282)
  let topPithDepth = (v < -165) ? ((-165 - v) * 0.85) : 0;
  let botPithDepth = (v > 270) ? ((v - 270) * 0.88) : 0;
  let effectiveDistInward = distHorizEdge - topPithDepth - botPithDepth;

  // Bottom Ostiole ("Eye" of the fig) channel piercing the base (v in [145, 330])
  if (v > 145) {
    let ostioleHalfW = 11 + 6 * Math.pow((v - 145) / 185, 1.4) + 2.5 * Math.sin(v * 0.18);
    if (Math.abs(uRel) < ostioleHalfW) {
      let tOst = Math.abs(uRel) / ostioleHalfW;
      // Overlapping ostiole scales at bottom (v > 275) vs narrow fleshy throat (v <= 275)
      let scaleTex = Math.sin(v * 0.35 + tOst * 4.0) * 0.18;
      let throatDark = 0.62 * (1 - tOst * 0.65) + scaleTex + (v > 290 ? 0.18 : 0);
      let throatMag = (v < 295) ? constrain(0.52 * (1 - (v - 145) / 160), 0, 0.55) : 0;
      // Wet highlight on scale tips
      if (Math.abs(tOst - 0.55) < 0.14 && Math.sin(v * 0.42) > 0.45) {
        throatDark = 0.08;
        throatMag = 0.05;
      }
      return {
        black: constrain(throatDark, 0.05, 0.92),
        magenta: throatMag,
        zone: "ostiole"
      };
    }
  }

  // CREAM PITH ZONE
  if (effectiveDistInward < localPithThick) {
    let tPith = constrain(effectiveDistInward / Math.max(6, localPithThick), 0, 1); // 0 at skin, 1 at flesh
    // Crisp dark shading right next to the outer skin epidermis (tPith < 0.14)
    let skinShadow = tPith < 0.14 ? 0.34 * (1 - tPith / 0.14) : 0;
    // Soft transition into radial floret stalks near the flesh boundary (tPith > 0.78)
    let fleshTransition = tPith > 0.78 ? 0.24 * ((tPith - 0.78) / 0.22) : 0;
    let radialStrand = 0.06 * Math.sin(ang * 52 + effectiveDistInward * 0.15);
    // Spongy cellular pores in the cream pith
    let sponge = 0.08 * (noise(uRel * 0.18, v * 0.18) - 0.42);
    // Subtle 3D shading across the flat cut face (slightly more shadowed on lower-right)
    let cutShade = 0.04 * (uRel / 250) + 0.04 * (v / 320);

    let pithBlack = constrain(0.055 + skinShadow + fleshTransition + radialStrand + sponge + cutShade, 0.02, 0.48);
    // Very faint rose blush only at the innermost 12% feathering into the flesh
    let pithMag = tPith > 0.88 ? 0.28 * ((tPith - 0.88) / 0.12) : 0;

    return { black: pithBlack, magenta: pithMag, zone: "pith" };
  }

  // 4. SEED-PACKED GARNET FLESH (SYCONIUM INTERIOR)
  let du = uRel;
  let dv = (v - fleshCenterV) * 0.76;
  let rCenter = Math.sqrt(du * du + dv * dv);

  // Central irregular star-shaped hollow cavity (lumen)
  let lumenRadius = 25 + 9 * Math.sin(ang * 7) + 6 * Math.cos(ang * 4 - 0.8) + 4 * Math.sin(ang * 13);
  if (rCenter < lumenRadius) {
    let tLumen = rCenter / Math.max(1, lumenRadius);
    if (tLumen < 0.68) {
      // Deep recessed hollow shadow inside central cleft
      return {
        black: constrain(0.84 + 0.12 * (1 - tLumen), 0.78, 0.96),
        magenta: 0.48,
        zone: "flesh"
      };
    } else {
      // Glistening wet tips of inward-pointing pulp sacs bordering the cavity
      let tipBump = Math.sin(ang * 26);
      if (tipBump > 0.25) {
        return { black: 0.03, magenta: 0.08, zone: "flesh" };
      }
      return { black: 0.58, magenta: 0.72, zone: "flesh" };
    }
  }

  // Base radial gelatinous garnet pulp filaments
  let fleshDepth = effectiveDistInward - localPithThick;
  let radialPulp = 0.5 + 0.5 * Math.sin(ang * 46 + rCenter * 0.06 + 2.2 * noise(uRel * 0.03, v * 0.03));
  let deepRing = Math.sin(constrain(fleshDepth / 145, 0, 1) * Math.PI);

  let pulpBlack = 0.46 + 0.26 * deepRing + 0.14 * radialPulp + 0.08 * (noise(uRel * 0.06, v * 0.06) - 0.5);
  let pulpMagenta = 0.62 + 0.26 * deepRing + 0.12 * (1 - radialPulp * 0.5);

  // Wet meniscus micro-highlights between pulp strands
  let wetGlint = noise(uRel * 0.24 + 50, v * 0.24 + 50);
  if (wetGlint > 0.78 && fleshDepth > 14) {
    pulpBlack *= 0.25;
    pulpMagenta *= 0.35;
  }

  // Query spatial hash grid for nearby 3D seeds (achenes)
  let gx = Math.floor((uRel - GRID_MIN_U) / GRID_CELL);
  let gy = Math.floor((v - GRID_MIN_V) / GRID_CELL);

  let bestQ2 = 999;
  let bestSeed = null;
  let bestSU = 0;
  let bestSV = 0;

  if (gx >= 0 && gx < GRID_COLS && gy >= 0 && gy < GRID_ROWS) {
    let minY = Math.max(0, gy - 1);
    let maxY = Math.min(GRID_ROWS - 1, gy + 1);
    let minX = Math.max(0, gx - 1);
    let maxX = Math.min(GRID_COLS - 1, gx + 1);

    for (let ny = minY; ny <= maxY; ny++) {
      let rowOffset = ny * GRID_COLS;
      for (let nx = minX; nx <= maxX; nx++) {
        let cell = seedGrid[rowOffset + nx];
        for (let k = 0; k < cell.length; k++) {
          let sd = seeds[cell[k]];
          let dsu = uRel - sd.u;
          let dsv = v - sd.v;
          if (Math.abs(dsu) > 9.5 || Math.abs(dsv) > 9.5) continue;

          // Rotate into seed's local radial axis
          let su = dsu * sd.cosA + dsv * sd.sinA;
          let sv = -dsu * sd.sinA + dsv * sd.cosA;
          // Teardrop taper (narrower toward outer stalk end)
          let taper = 1.0 - 0.22 * constrain(su / sd.a, -1, 1);
          let svTapered = sv / Math.max(0.55, taper);

          let q2 = (su * su) / (sd.a * sd.a) + (svTapered * svTapered) / (sd.b * sd.b);
          if (q2 < bestQ2) {
            bestQ2 = q2;
            bestSeed = sd;
            bestSU = su / sd.a;
            bestSV = svTapered / sd.b;
          }
        }
      }
    }
  }

  if (bestSeed !== null) {
    if (bestQ2 < 1.0) {
      // Inside a 3D teardrop seed (achene)
      let nz = Math.sqrt(Math.max(0.01, 1.0 - bestQ2));
      // Transform local seed normal back to canvas directions for upper-left lighting
      let nx = bestSU * bestSeed.cosA - bestSV * bestSeed.sinA;
      let ny = bestSU * bestSeed.sinA + bestSV * bestSeed.cosA;
      let lightDot = (-0.58 * nx - 0.54 * ny + 0.61 * nz) * bestSeed.shine;

      if (lightDot > 0.68) {
        // Specular wet highlight on upper-left dome of seed (bare paper shines through)
        pulpBlack = 0.0;
        pulpMagenta = 0.0;
      } else if (lightDot > 0.34) {
        // Luminous pale golden-cream seed coat midtone
        let tMid = (lightDot - 0.34) / 0.34;
        pulpBlack = lerp(0.28, 0.08, tMid) + bestSeed.shade;
        pulpMagenta = lerp(0.32, 0.10, tMid);
      } else {
        // Shadowed lower-right rim of the seed body
        let tShad = constrain((0.34 - lightDot) / 0.65, 0, 1);
        pulpBlack = lerp(0.30, 0.68, tShad) + bestSeed.shade;
        pulpMagenta = lerp(0.36, 0.72, tShad);
      }
    } else if (bestQ2 < 1.72) {
      // Deep garnet jelly socket / collar immediately surrounding the seed
      let tCollar = (bestQ2 - 1.0) / 0.72; // 0 at seed rim, 1 outer
      let socketBoost = Math.sin((1 - tCollar) * Math.PI * 0.85);
      pulpBlack = constrain(pulpBlack + 0.34 * socketBoost, 0.55, 0.96);
      pulpMagenta = constrain(pulpMagenta + 0.28 * socketBoost, 0.65, 0.96);
    }
  }

  return {
    black: constrain(pulpBlack, 0, 0.97),
    magenta: constrain(pulpMagenta, 0, 0.96),
    zone: "flesh"
  };
}

// ---------------------------------------------------------------------------
// RIGID HORIZONTAL ROW DOT-MATRIX RENDERING
// ---------------------------------------------------------------------------

function drawImpactPrinterFig() {
  const rowPitch = 4.2;     // Strict vertical scanline spacing (13 rows per 54.6px greenbar band)
  const colPitch = 3.5;     // Horizontal dot column grid pitch
  const startY = 175.8;
  const endY = 1045.2;
  const startX = 195.0;
  const endX = 1045.0;

  const tiltDeg = -10.5;
  const cosTilt = Math.cos(tiltDeg * Math.PI / 180);
  const sinTilt = Math.sin(tiltDeg * Math.PI / 180);

  // Batch queues grouped by brush & ink shade to minimize state switches
  // Black ribbon passes: 5 pin sizes x 2 ink intensities (standard carbon &worn/faint) + heavy burst
  let blackBatches = {
    faint_1: [], faint_2: [], faint_3: [],
    std_1: [], std_2: [], std_3: [], std_4: [], std_5: [],
    heavy_4: [], heavy_5: [],
    bursts: [],
    cores: []
  };

  // Single overprinted pass of magenta-red dots in the flesh
  let magentaBatches = {
    mag_1: [], mag_2: [], mag_3: [], mag_4: [], mag_5: [],
    mag_cores: []
  };

  // Ordered 4x4 halftone dither matrix for authentic impact printer dot frequency modulation
  const bayer4 = [
    [ 0.06, 0.56, 0.19, 0.69 ],
    [ 0.81, 0.31, 0.94, 0.44 ],
    [ 0.25, 0.75, 0.12, 0.62 ],
    [ 0.99, 0.50, 0.88, 0.38 ]
  ];

  let totalRows = Math.floor((endY - startY) / rowPitch);

  for (let r = 0; r <= totalRows; r++) {
    let yRow = startY + r * rowPitch;
    let isDoubleStrike = doubleStrikeRows.has(r);

    // Evaluate horizontal ribbon-fade stripe crossing the fruit (around y = 492..546, plus faint secondary at 772..793)
    let ribbonHealth = 1.0;
    if (yRow > 484 && yRow < 554) {
      let distMid = Math.abs(yRow - 519) / 35.0;
      let fadeCurve = 0.5 + 0.5 * Math.cos(distMid * Math.PI);
      ribbonHealth = 1.0 - 0.58 * fadeCurve;
      // One nearly dry pin wire inside the ribbon-fade band
      if (r === 81 || r === 83) ribbonHealth *= 0.68;
    } else if (yRow > 768 && yRow < 796) {
      let distMid = Math.abs(yRow - 782) / 14.0;
      ribbonHealth = 1.0 - 0.34 * (0.5 + 0.5 * Math.cos(distMid * Math.PI));
    }

    let burstStartX = null;
    let burstPrevX = null;

    let colIdx = 0;
    for (let xCol = startX; xCol <= endX; xCol += colPitch, colIdx++) {
      let sample = evaluateFigAt(xCol, yRow, cosTilt, sinTilt);
      if (sample.zone === "outside") {
        if (burstStartX !== null && burstPrevX - burstStartX >= 4.0) {
          blackBatches.bursts.push([burstStartX, yRow, burstPrevX]);
        }
        burstStartX = null;
        continue;
      }

      // Slight horizontal ribbon variation along the carriage sweep
      let carriageWear = ribbonHealth * (0.94 + 0.06 * Math.sin(xCol * 0.018 + r * 0.3));
      let blk = sample.black * carriageWear;
      if (isDoubleStrike && blk > 0.05) {
        blk = Math.min(0.99, blk * 1.24 + 0.07);
      }

      let dither = bayer4[r & 3][colIdx & 3];
      let isFaintRibbon = carriageWear < 0.72;

      // Determine whether a black dot fires at (xCol, yRow) and with what pin size
      let pinLevel = 0;
      if (blk >= 0.80) {
        pinLevel = 5;
      } else if (blk >= 0.62) {
        pinLevel = (blk - 0.62) * 5.5 > dither * 0.6 ? 5 : 4;
      } else if (blk >= 0.42) {
        pinLevel = (blk - 0.42) * 5.0 > dither * 0.7 ? 4 : 3;
      } else if (blk >= 0.24) {
        if (blk + 0.18 > dither * 0.52) {
          pinLevel = blk > 0.33 ? 3 : 2;
        }
      } else if (blk >= 0.04) {
        // Sparse dot density in the cream pith, specular seed rims & soft shadow
        let densityThresh = (blk - 0.03) * 3.6;
        if (densityThresh > dither) {
          pinLevel = blk > 0.14 ? 2 : 1;
        }
      }

      if (pinLevel > 0) {
        // Tiny mechanical pin jitter (< 0.25px) while staying strictly on the horizontal row
        let jx = xCol + (( (colIdx * 37 + r * 13) & 7 ) - 3.5) * 0.07;

        if (isFaintRibbon) {
          let faintLvl = Math.min(3, Math.max(1, pinLevel - 1));
          blackBatches["faint_" + faintLvl].push([jx, yRow]);
        } else if (isDoubleStrike && pinLevel >= 4) {
          blackBatches["heavy_" + pinLevel].push([jx, yRow]);
          // Second offset strike on double-strike rows
          blackBatches["std_" + Math.max(3, pinLevel - 1)].push([jx + 0.75, yRow + 0.55]);
        } else {
          blackBatches["std_" + pinLevel].push([jx, yRow]);
        }

        // High-density half-step sub-column strike in deepest shadow crevices & aubergine bruises
        if (blk >= 0.83 && !isFaintRibbon) {
          blackBatches.std_4.push([jx + colPitch * 0.5, yRow]);
          if (burstStartX === null) burstStartX = jx;
          burstPrevX = jx + colPitch * 0.5;
        } else {
          if (burstStartX !== null && burstPrevX - burstStartX >= 4.0) {
            blackBatches.bursts.push([burstStartX, yRow, burstPrevX]);
          }
          burstStartX = null;
        }

        // Pin-impact center core for crisp dark dots
        if (pinLevel >= 4 && !isFaintRibbon && ((colIdx + r) % 2 === 0)) {
          blackBatches.cores.push([jx, yRow]);
        }
      } else {
        if (burstStartX !== null && burstPrevX - burstStartX >= 4.0) {
          blackBatches.bursts.push([burstStartX, yRow, burstPrevX]);
        }
        burstStartX = null;
      }

      // SINGLE OVERPRINTED PASS OF MAGENTA-RED DOTS IN THE FLESH
      if (sample.zone === "flesh" || sample.zone === "ostiole" || (sample.zone === "pith" && sample.magenta > 0.05)) {
        // Evaluate with slight 2-pass carriage registration shift (+1.1px, +0.65px)
        let magVal = sample.magenta * (0.35 + 0.65 * carriageWear);
        let magDither = bayer4[(r + 2) & 3][(colIdx + 1) & 3];
        let magLevel = 0;

        if (magVal >= 0.78) {
          magLevel = 5;
        } else if (magVal >= 0.58) {
          magLevel = (magVal - 0.58) * 5.0 > magDither * 0.6 ? 4 : 3;
        } else if (magVal >= 0.35) {
          if (magVal + 0.16 > magDither * 0.65) {
            magLevel = magVal > 0.46 ? 3 : 2;
          }
        } else if (magVal >= 0.08) {
          if ((magVal - 0.05) * 3.2 > magDither) {
            magLevel = 1;
          }
        }

        if (magLevel > 0) {
          let mx = xCol + 1.15;
          let my = yRow + 0.65;
          magentaBatches["mag_" + magLevel].push([mx, my]);

          // Sub-column magenta dot in the richest garnet seed sockets
          if (magVal >= 0.84 && !isFaintRibbon) {
            magentaBatches.mag_3.push([mx + colPitch * 0.5, my]);
          }
          if (magLevel >= 4 && ((colIdx + r) & 1) === 0) {
            magentaBatches.mag_cores.push([mx, my]);
          }
        }
      }
    }

    if (burstStartX !== null && burstPrevX - burstStartX >= 4.0) {
      blackBatches.bursts.push([burstStartX, yRow, burstPrevX]);
    }
  }

  // -------------------------------------------------------------------------
  // EXECUTE BATCHED DOT-MATRIX PASSES
  // -------------------------------------------------------------------------
  brush.noFill();
  brush.noWash();

  // Helper to stamp an array of [x, y] dots with a guaranteed 1.05px micro-stroke
  const renderDotBatch = (brushName, hexColor, weight, pts) => {
    if (!pts || pts.length === 0) return;
    brush.set(brushName, hexColor, weight);
    for (let i = 0; i < pts.length; i++) {
      let p = pts[i];
      brush.line(p[0] - 0.52, p[1], p[0] + 0.53, p[1]);
    }
  };

  // PASS 1: Overprinted Magenta-Red Dots in the Flesh (drawn first and overstruck by black,
  // plus a final top glaze of magenta cores so both passes optically interleave like real ink!)
  renderDotBatch("pin_1", "#c62356", 1.0, magentaBatches.mag_1);
  renderDotBatch("pin_2", "#bd1c4f", 1.0, magentaBatches.mag_2);
  renderDotBatch("pin_3", "#ae1646", 1.0, magentaBatches.mag_3);
  renderDotBatch("pin_4", "#98113c", 1.0, magentaBatches.mag_4);
  renderDotBatch("pin_5", "#820c32", 1.0, magentaBatches.mag_5);

  // PASS 2: Ribbon Black Impact Dots (Worn/Faint Ribbon Track first, then Standard & Double-Strike)
  renderDotBatch("pin_1", "#4a535d", 1.0, blackBatches.faint_1);
  renderDotBatch("pin_2", "#3e4750", 1.0, blackBatches.faint_2);
  renderDotBatch("pin_3", "#333b43", 1.0, blackBatches.faint_3);

  renderDotBatch("pin_1", "#2c333b", 1.0, blackBatches.std_1);
  renderDotBatch("pin_2", "#232930", 1.0, blackBatches.std_2);
  renderDotBatch("pin_3", "#1b2026", 1.0, blackBatches.std_3);
  renderDotBatch("pin_4", "#14181d", 1.0, blackBatches.std_4);
  renderDotBatch("pin_5", "#0e1115", 1.0, blackBatches.std_5);

  // Continuous horizontal pin bursts in the deepest aubergine bruises & core shadow
  if (blackBatches.bursts.length > 0) {
    brush.set("pin_burst", "#101419", 1.0);
    for (let i = 0; i < blackBatches.bursts.length; i++) {
      let b = blackBatches.bursts[i];
      brush.line(b[0], b[1], b[2], b[1]);
    }
  }

  // Heavy double-strike rows
  renderDotBatch("pin_4", "#0a0d10", 1.08, blackBatches.heavy_4);
  renderDotBatch("pin_5", "#07090c", 1.12, blackBatches.heavy_5);

  // PASS 3: Crisp Pin-Impact Center Cores (built-in rotring micro-strikes for tactile metal-pin sharpness)
  renderDotBatch("rotring", "#a41342", 0.52, magentaBatches.mag_cores);
  renderDotBatch("rotring", "#080b0e", 0.55, blackBatches.cores);
}

// Hyperrealism in p5.brush: Bare Thigh Just Lifted from a Rattan Chair
// Medium: Sepia & raw-umber watercolour glazes, rose madder, worked into graphite (2H, HB, 2B)

const SEED = 4279;

// Tilt and grid parameters for the quiet over-and-under weave rhythm
const TILT_DEG = -15.5;
const WEFT_DEG = 66.0;
const SU = 54.0; // Warp period
const SV = 48.0; // Weft period

let cosU, sinU, cosV, sinV;

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(SEED);
  noiseSeed(SEED);

  cosU = cos(TILT_DEG);
  sinU = sin(TILT_DEG);
  cosV = cos(WEFT_DEG);
  sinV = sin(WEFT_DEG);
}

// Lower contour of the bare thigh just lifted from the rattan seat
function thighEdgeY(x) {
  let t = (x + 100) / 1400;
  let base = 852 - 0.135 * (x - 320);
  let belly = 48 * sin(constrain(t, 0, 1) * 180);
  let subtleWave = 10 * sin((x - 100) * 0.22);
  return base + belly + subtleWave;
}

// Cast shadow depth on the rattan chair directly below the lifted thigh
// Narrower on the left (thigh barely lifted), wider toward the right (lifted higher)
function castShadowDepth(x) {
  let lift = map(x, 0, 1200, 38, 155, true);
  let curve = 18 * sin((x / 1200) * 180);
  return lift + curve;
}

// Illumination on the curved cylinder of the thigh (0 = deep twilight/umber shadow, 1 = warm afternoon light)
function getSkinLight(x, y) {
  let edgeY = thighEdgeY(x);
  let distFromEdge = max(0, edgeY - y);

  // Cylindrical roll near the lower edge of the thigh:
  // 0..28px: warm reflected light from the golden rattan below
  // 35..115px: core shadow of the thigh's underside
  // >115px: opens up toward the upper-left afternoon light
  let cylinderFactor;
  if (distFromEdge < 34) {
    cylinderFactor = map(distFromEdge, 0, 34, 0.42, 0.22); // reflected bounce -> core shadow
  } else if (distFromEdge < 120) {
    cylinderFactor = map(distFromEdge, 34, 120, 0.22, 0.58);
  } else {
    cylinderFactor = map(distFromEdge, 120, 780, 0.58, 1.0, true);
  }

  // Afternoon light comes from the upper-left; dusky twilight falls toward the right
  let lateralLight = map(x * 0.72 + y * 0.28, 0, 1200, 1.05, 0.35, true);
  return constrain(cylinderFactor * 0.62 + lateralLight * 0.42, 0.08, 1.0);
}

// Illumination on the rattan chair weave below the thigh
function getChairLight(x, y) {
  let edgeY = thighEdgeY(x);
  let dy = y - edgeY;
  let sDepth = castShadowDepth(x);

  // Occlusion and cast shadow from the hovering thigh
  let shadowFactor = 1.0;
  if (dy < sDepth * 0.45) {
    shadowFactor = map(dy, 0, sDepth * 0.45, 0.10, 0.28, true);
  } else if (dy < sDepth) {
    shadowFactor = map(dy, sDepth * 0.45, sDepth, 0.28, 0.92, true);
  } else if (dy < sDepth * 1.35) {
    shadowFactor = map(dy, sDepth, sDepth * 1.35, 0.92, 1.0, true);
  }

  // Afternoon light raking from the left across the seat
  let seatLight = map(x, 0, 1200, 1.0, 0.56, true);
  return constrain(shadowFactor * seatLight, 0.08, 1.0);
}

// Map chair weave grid coordinates (u, v) to canvas (x, y)
// v = 0 starts near the thigh contour line and increases downward
function chairGridToXY(u, v) {
  let ox = 560;
  let oy = 795;
  let bx = ox + u * SU * cosU + v * SV * cosV;
  let by = oy + u * SU * sinU + v * SV * sinV;

  // Subtle weight-sag of the woven cane seat + organic hand-woven irregularity
  let sag = 16 * exp(-pow((bx - 480) / 480, 2)) * constrain((by - 680) / 400, 0, 1.2);
  let jx = (noise(u * 0.37 + 10, v * 0.37 + 10) - 0.5) * 4.5;
  let jy = (noise(u * 0.37 + 50, v * 0.37 + 50) - 0.5) * 4.5;

  return { x: bx + jx, y: by + sag + jy };
}

// Map embossed weave grid coordinates (u, v) onto the 3D curved surface of the lifted thigh
// Here v = 0 is just above the lower edge of the thigh, and v increases UPWARD across the skin
function skinGridToXY(u, v) {
  // The lifted thigh has shifted slightly up-left and rotated ~ -2.8 deg relative to the chair
  let skinTilt = TILT_DEG - 2.6;
  let skinNormal = skinTilt - 84.0; // pointing up-left across the cylinder of the thigh

  let cU = cos(skinTilt), sU = sin(skinTilt);
  let cV = cos(skinNormal), sV = sin(skinNormal);

  // Cylindrical foreshortening: compressed near v=0 (underside roll of the thigh),
  // full width across the mid-flank (v = 2..10), gently foreshortened near top curve
  let effectiveV = 0;
  let steps = 20;
  let dv = v / steps;
  for (let k = 0; k < steps; k++) {
    let vk = (k + 0.5) * dv;
    let scaleV;
    if (vk < 1.6) {
      scaleV = map(vk, 0, 1.6, 0.54, 0.96);
    } else if (vk < 10.5) {
      scaleV = 1.02;
    } else {
      scaleV = map(vk, 10.5, 19.0, 1.02, 0.76, true);
    }
    effectiveV += dv * scaleV;
  }

  let ox = 542;
  let oy = 772;
  let bx = ox + u * (SU * 1.01) * cU + effectiveV * SV * cV;
  let by = oy + u * (SU * 1.01) * sU + effectiveV * SV * sV;

  // Anatomical contour wrap: near the bottom of the thigh, the weave curves with the flesh belly
  let edgeAtX = thighEdgeY(bx);
  let linearEdge = 852 - 0.135 * (bx - 320);
  let contourDelta = edgeAtX - linearEdge;
  let wrapWeight = exp(-max(0, v) * 0.14);

  let jx = (noise(u * 0.33 + 110, v * 0.33 + 110) - 0.5) * 4.0;
  let jy = (noise(u * 0.33 + 170, v * 0.33 + 170) - 0.5) * 4.0;

  return {
    x: bx + jx,
    y: by + contourDelta * wrapWeight + jy
  };
}

// Strength of the pressed rattan impression on the thigh (0..1)
// Deepest where the weight of the thigh rested, softening naturally toward upper edges
function getImpressionStrength(u, v, x, y) {
  let edgeY = thighEdgeY(x);
  let distAbove = edgeY - y;
  if (distAbove < 4) return 0;

  // Vertical envelope across the curve of the thigh
  let vEnv;
  if (v < 0.7) {
    vEnv = map(v, -0.3, 0.7, 0.35, 0.92, true);
  } else if (v < 8.5) {
    vEnv = map(v, 0.7, 8.5, 1.0, 0.86);
  } else if (v < 14.5) {
    vEnv = map(v, 8.5, 14.5, 0.86, 0.38);
  } else {
    vEnv = map(v, 14.5, 19.5, 0.38, 0.08, true);
  }

  // Horizontal pressure distribution (heaviest under the main belly of the thigh)
  let hEnv = 1.0 - 0.32 * pow((x - 520) / 720, 2);
  let n = 0.88 + 0.24 * noise(u * 0.25 + 30, v * 0.25 + 30);

  return constrain(vEnv * hEnv * n, 0.05, 1.0);
}

// Safe polygon helper using beginShape/vertex/endShape
function drawPoly(pts, curvature = 0.22, closed = true) {
  if (!pts || pts.length < 3) return;
  let clean = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    let prev = clean[clean.length - 1];
    if (dist(pts[i][0], pts[i][1], prev[0], prev[1]) > 0.6) {
      clean.push(pts[i]);
    }
  }
  if (clean.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < clean.length; i++) {
    brush.vertex(clean[i][0], clean[i][1]);
  }
  brush.endShape(closed ? CLOSE : undefined);
}

// Safe spline helper
function drawSpline(pts, curvature = 0.5) {
  if (!pts || pts.length < 2) return;
  let clean = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    let prev = clean[clean.length - 1];
    if (dist(pts[i][0], pts[i][1], prev[0], prev[1]) > 0.6) {
      clean.push(pts[i]);
    }
  }
  if (clean.length < 2) return;
  if (clean.length === 2) {
    brush.line(clean[0][0], clean[0][1], clean[1][0], clean[1][1]);
  } else {
    brush.spline(clean, curvature);
  }
}

// Generate an oriented oval/lozenge polygon for a hollow or cushion
function makeOrientedOval(cx, cy, rx, ry, angleDeg, numPts = 10, irregularity = 0.06) {
  let pts = [];
  let ca = cos(angleDeg), sa = sin(angleDeg);
  for (let k = 0; k < numPts; k++) {
    let a = (k / numPts) * 360;
    // Slightly squarish superellipse for cane knuckle geometry
    let ct = cos(a), st = sin(a);
    let sgnC = ct >= 0 ? 1 : -1;
    let sgnS = st >= 0 ? 1 : -1;
    let lx = sgnC * pow(abs(ct), 0.82) * rx;
    let ly = sgnS * pow(abs(st), 0.82) * ry;
    let jit = 1 + (noise(cx * 0.03 + k, cy * 0.03 + k) - 0.5) * irregularity * 2;
    lx *= jit;
    ly *= jit;
    pts.push([cx + lx * ca - ly * sa, cy + lx * sa + ly * ca]);
  }
  return pts;
}

// Generate crescent polygon for pooled rose madder or shadow inside a dent
function makeDentCrescent(cx, cy, rx, ry, angleDeg, lightAngleDeg = -138) {
  let pts = [];
  let ca = cos(angleDeg), sa = sin(angleDeg);
  // Outer arc along the upper-left (shadowed/pooled) rim of the dent
  for (let k = 0; k <= 6; k++) {
    let a = map(k, 0, 6, 115, 295);
    let lx = cos(a) * rx * 1.04;
    let ly = sin(a) * ry * 1.04;
    pts.push([cx + lx * ca - ly * sa, cy + lx * sa + ly * ca]);
  }
  // Inner arc shifted slightly toward the lower-right
  let shiftX = cos(lightAngleDeg + 180) * rx * 0.34;
  let shiftY = sin(lightAngleDeg + 180) * ry * 0.38;
  for (let k = 6; k >= 0; k--) {
    let a = map(k, 0, 6, 125, 285);
    let lx = cos(a) * rx * 0.68 + shiftX;
    let ly = sin(a) * ry * 0.68 + shiftY;
    pts.push([cx + lx * ca - ly * sa, cy + lx * sa + ly * ca]);
  }
  return pts;
}

function draw() {
  translate(-width / 2, -height / 2);

  // Warm dusky archival rag paper ground
  background("#dfd3c5");

  // =========================================================================
  // 1. BROAD WATERCOLOUR GLAZES: VOLUMETRIC FLESH & RATTAN SEAT UNDERTONES
  // =========================================================================
  renderBaseWatercolourGlazes();

  // =========================================================================
  // 2. EMBOSSED WEAVE ON THE BARE THIGH (PINK RIDGES, ROSE MADDER, BLANCHING)
  // =========================================================================
  renderEmbossedSkinWeave();

  // =========================================================================
  // 3. GRAPHITE MODELLING, POOLED ROSE-MADDER CREASES & VELLUS HAIR ON THIGH
  // =========================================================================
  renderSkinGraphiteAndVellus();

  // =========================================================================
  // 4. REAL RATTAN CHAIR WEAVE BELOW THE LIFTED THIGH
  //    (OVER-AND-UNDER STRANDS, GLOSSY NODES, SPLIT FIBRE & FRAYED BINDING)
  // =========================================================================
  renderRealRattanWeave();

  // =========================================================================
  // 5. FINAL UNIFYING GLAZES, THIGH SEPARATION SHADOW & ATMOSPHERIC GRAIN
  // =========================================================================
  renderFinalUnifyingTouches();

  noLoop();
}

// ===========================================================================
// STEP 1: MACRO WATERCOLOUR GLAZES
// ===========================================================================
function renderBaseWatercolourGlazes() {
  brush.noStroke();
  brush.noHatch();

  // 1A. Warm afternoon light wash on upper-left thigh
  brush.fill("#f3e5d7", 95);
  brush.fillBleed(0.38, "out");
  brush.fillTexture(0.5, 0.2);
  drawPoly([
    [-40, -40], [820, -40], [640, 480], [280, 680], [-40, 740]
  ], 0.3);

  // 1B. Mid-thigh warm rose-ochre flesh glaze
  brush.fill("#dfc2b2", 82);
  brush.fillBleed(0.42, "out");
  brush.fillTexture(0.55, 0.25);
  drawPoly([
    [120, -40], [1080, -40], [980, 560], [520, 790], [-40, 830], [-40, 380]
  ], 0.3);

  // 1C. Subsurface rose-madder blush across the main pressure contact zone of the thigh
  brush.fill("#c97980", 52);
  brush.fillBleed(0.45, "out");
  brush.fillTexture(0.6, 0.3);
  drawPoly([
    [-20, 340], [480, 210], [960, 260], [1080, 580],
    [760, 770], [360, 855], [-20, 845]
  ], 0.35);

  // 1D. Dusky twilight mauve-umber shadow glaze on right & lower curve of the thigh
  brush.fill("#8c6b68", 78);
  brush.fillBleed(0.42, "out");
  brush.fillTexture(0.62, 0.32);
  drawPoly([
    [620, -40], [1240, -40], [1240, 710], [740, 790],
    [280, 860], [420, 580], [680, 290]
  ], 0.3);

  // 1E. Deep raw-umber & sepia core shadow band along the turning underside of the thigh
  let corePts = [];
  for (let x = -40; x <= 1240; x += 80) {
    corePts.push([x, thighEdgeY(x) - 105]);
  }
  for (let x = 1240; x >= -40; x -= 80) {
    corePts.push([x, thighEdgeY(x) - 14]);
  }
  brush.fill("#664947", 88);
  brush.fillBleed(0.36, "out");
  brush.fillTexture(0.65, 0.35);
  drawPoly(corePts, 0.25);

  // 1F. Warm golden-ochre reflected light along the very bottom rim of the thigh
  let rimPts = [];
  for (let x = -40; x <= 1240; x += 80) {
    rimPts.push([x, thighEdgeY(x) - 28]);
  }
  for (let x = 1240; x >= -40; x -= 80) {
    rimPts.push([x, thighEdgeY(x) + 2]);
  }
  brush.fill("#c49774", 75);
  brush.fillBleed(0.25, "out");
  brush.fillTexture(0.45, 0.2);
  drawPoly(rimPts, 0.2);

  // 1G. Rattan chair zone base: raw sienna & golden cane ochre
  let chairBasePts = [];
  for (let x = -40; x <= 1240; x += 80) {
    chairBasePts.push([x, thighEdgeY(x)]);
  }
  chairBasePts.push([1240, 1240], [-40, 1240]);
  brush.fill("#bf9668", 110);
  brush.fillBleed(0.25, "in");
  brush.fillTexture(0.55, 0.3);
  drawPoly(chairBasePts, 0.15);

  // 1H. Deep sepia and raw-umber cast shadow of the lifted thigh onto the rattan below
  let shadowPts = [];
  for (let x = -40; x <= 1240; x += 80) {
    shadowPts.push([x, thighEdgeY(x) - 2]);
  }
  for (let x = 1240; x >= -40; x -= 80) {
    shadowPts.push([x, thighEdgeY(x) + castShadowDepth(x)]);
  }
  brush.fill("#3d2b25", 135);
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.68, 0.4);
  drawPoly(shadowPts, 0.25);

  // Darker occlusion core right under the thigh contour
  let occPts = [];
  for (let x = -40; x <= 1240; x += 80) {
    occPts.push([x, thighEdgeY(x) - 1]);
  }
  for (let x = 1240; x >= -40; x -= 80) {
    occPts.push([x, thighEdgeY(x) + castShadowDepth(x) * 0.42]);
  }
  brush.fill("#281b18", 150);
  brush.fillBleed(0.22, "out");
  brush.fillTexture(0.6, 0.42);
  drawPoly(occPts, 0.2);

  brush.noFill();
  brush.noWash();
}

// ===========================================================================
// STEP 2: EMBOSSED WEAVE ON THE BARE THIGH
// ===========================================================================
let skinHollows = [];
let skinCushions = [];

function renderEmbossedSkinWeave() {
  skinHollows = [];
  skinCushions = [];

  let skinTilt = TILT_DEG - 2.6;
  let skinWeft = skinTilt - 84.0;

  // Collect all visible embossed knuckles (integer u, v) on the thigh
  for (let v = 0; v <= 19; v++) {
    for (let u = -14; u <= 15; u++) {
      let p = skinGridToXY(u, v);
      let edgeY = thighEdgeY(p.x);
      if (p.x < -70 || p.x > 1270 || p.y < -70 || p.y > edgeY - 8) continue;

      let imp = getImpressionStrength(u, v, p.x, p.y);
      let light = getSkinLight(p.x, p.y);
      let isWarpOver = ((u + v) % 2 + 2) % 2 === 0;

      // Foreshortening of vertical radius near bottom roll of thigh
      let vScale = v < 1.5 ? map(v, 0, 1.5, 0.58, 0.96, true) : (v > 12 ? 0.84 : 1.0);
      let angle = isWarpOver ? skinTilt : skinWeft;
      let rx = (isWarpOver ? 22.5 : 19.5 * vScale) * (0.82 + 0.22 * imp);
      let ry = (isWarpOver ? 13.5 * vScale : 14.5) * (0.82 + 0.22 * imp);

      // Does this cane knuckle carry a rattan growth node impression or split fibre mark?
      let hasNode = noise(u * 0.71 + 9, v * 0.71 + 3) > 0.68;
      let hasSplit = noise(u * 0.53 + 21, v * 0.53 + 47) > 0.64;

      skinHollows.push({
        u, v, x: p.x, y: p.y,
        rx, ry, angle,
        imp, light, isWarpOver,
        hasNode, hasSplit, vScale
      });
    }
  }

  // Collect raised interstitial skin cushions at half-integer (u + 0.5, v + 0.5)
  // (where skin bulged into the open holes between cane strands)
  for (let v = 0; v <= 18; v++) {
    for (let u = -14; u <= 14; u++) {
      let p = skinGridToXY(u + 0.5, v + 0.5);
      let edgeY = thighEdgeY(p.x);
      if (p.x < -50 || p.x > 1250 || p.y < -50 || p.y > edgeY - 12) continue;

      let imp = getImpressionStrength(u + 0.5, v + 0.5, p.x, p.y);
      let light = getSkinLight(p.x, p.y);
      let vScale = v < 1.5 ? map(v, 0, 1.5, 0.58, 0.96, true) : 1.0;

      skinCushions.push({
        u: u + 0.5, v: v + 0.5,
        x: p.x, y: p.y,
        r: 13.5 * (0.75 + 0.28 * imp),
        vScale, imp, light
      });
    }
  }

  brush.noStroke();
  brush.noHatch();

  // -------------------------------------------------------------------------
  // 2A. Pink Ridges & Raised Skin Cushions (Reactive Hyperemia / Flush)
  // -------------------------------------------------------------------------
  for (let c of skinCushions) {
    if (c.imp < 0.12) continue;
    // Pink ridge flush connecting across the raised cushion
    let alpha = floor(map(c.imp, 0.1, 1.0, 22, 92));
    let flushCol = c.light > 0.68 ? "#d68289" : (c.light > 0.42 ? "#be6771" : "#964b56");
    brush.wash(flushCol, alpha);
    let pts = makeOrientedOval(c.x, c.y, c.r * 1.38, c.r * 1.18 * c.vScale, skinTilt + 38, 8, 0.08);
    drawPoly(pts, 0.28);

    // Sunlit upper-left bevel of the raised pink cushion
    if (c.imp > 0.25) {
      let litCol = c.light > 0.65 ? "#f4dad2" : (c.light > 0.4 ? "#dfb7ae" : "#b58984");
      brush.wash(litCol, floor(alpha * 0.72));
      let litPts = makeOrientedOval(
        c.x - 3.2, c.y - 3.0 * c.vScale,
        c.r * 0.85, c.r * 0.72 * c.vScale,
        skinTilt - 25, 8, 0.05
      );
      drawPoly(litPts, 0.25);
    }

    // Shaded lower-right slope of the raised cushion (raw umber + twilight rose)
    if (c.imp > 0.22) {
      let shCol = c.light > 0.6 ? "#a86c6e" : (c.light > 0.35 ? "#825053" : "#5e383b");
      brush.wash(shCol, floor(alpha * 0.68));
      let shPts = makeOrientedOval(
        c.x + 3.8, c.y + 3.5 * c.vScale,
        c.r * 0.82, c.r * 0.68 * c.vScale,
        skinTilt - 25, 8, 0.05
      );
      drawPoly(shPts, 0.25);
    }
  }
  brush.noWash();

  // -------------------------------------------------------------------------
  // 2B. Watercolour Rose Madder Pooling in the Dents (Batched by tone)
  // -------------------------------------------------------------------------
  // Group hollows into 3 tonal batches for genuine watercolour bleed
  let madderBatches = [
    { minL: 0.66, maxL: 1.01, col: "#b84a5b", op: 88 },
    { minL: 0.38, maxL: 0.66, col: "#9e3748", op: 98 },
    { minL: 0.00, maxL: 0.38, col: "#7a2837", op: 105 }
  ];

  for (let b of madderBatches) {
    brush.fill(b.col, b.op);
    brush.fillBleed(0.24, "in");
    brush.fillTexture(0.62, 0.48);

    for (let h of skinHollows) {
      if (h.imp < 0.32 || h.light < b.minL || h.light >= b.maxL) continue;
      // Draw the pooled rose madder crescent along the upper-left inside wall of the dent
      let cres = makeDentCrescent(h.x, h.y, h.rx * 0.96, h.ry * 0.96, h.angle);
      drawPoly(cres, 0.22);
    }
  }
  brush.noFill();

  // Secondary wash pass for softer rose-madder halos around all dents
  for (let h of skinHollows) {
    if (h.imp < 0.15) continue;
    let rimAlpha = floor(map(h.imp, 0.15, 1.0, 20, 76));
    let rimCol = h.light > 0.65 ? "#cc6874" : (h.light > 0.38 ? "#ab4b59" : "#803441");
    brush.wash(rimCol, rimAlpha);
    let haloPts = makeOrientedOval(
      h.x - 1.5, h.y - 1.5,
      h.rx * 1.12, h.ry * 1.14,
      h.angle, 10, 0.05
    );
    drawPoly(haloPts, 0.25);
  }
  brush.noWash();

  // -------------------------------------------------------------------------
  // 2C. Pressure Blanching: Pale Hollows Where Cane Knuckles Compressed Skin
  // -------------------------------------------------------------------------
  // First pass: soft outer blanched floor of each hollow
  for (let h of skinHollows) {
    let blanchAlpha = floor(map(h.imp, 0.05, 1.0, 28, 145));
    let blanchCol;
    if (h.light > 0.72) {
      blanchCol = "#f6ebe0";
    } else if (h.light > 0.50) {
      blanchCol = "#ead8c9";
    } else if (h.light > 0.32) {
      blanchCol = "#ccb3a6";
    } else {
      blanchCol = "#a88d84";
    }

    brush.wash(blanchCol, blanchAlpha);
    // Shifted slightly toward lower-right where afternoon light hits the floor & far wall of dent
    let floorPts = makeOrientedOval(
      h.x + 1.4 * h.imp,
      h.y + 1.4 * h.imp,
      h.rx * 0.84,
      h.ry * 0.80,
      h.angle, 10, 0.04
    );
    drawPoly(floorPts, 0.25);

    // Brightest blanched core & sunlit lower-right inner lip of the hollow
    if (h.imp > 0.28) {
      let coreCol = h.light > 0.68 ? "#fbf3ea" : (h.light > 0.42 ? "#f0dfd2" : "#d1b8ad");
      brush.wash(coreCol, floor(blanchAlpha * 0.82));
      let corePts = makeOrientedOval(
        h.x + 2.8 * h.imp,
        h.y + 2.4 * h.imp,
        h.rx * 0.58,
        h.ry * 0.52,
        h.angle, 8, 0.03
      );
      drawPoly(corePts, 0.25);
    }
  }
  brush.noWash();
}

// ===========================================================================
// STEP 3: GRAPHITE MODELLING, POOLED ROSE-MADDER CREASES & VELLUS HAIR
// ===========================================================================
function renderSkinGraphiteAndVellus() {
  brush.noFill();
  brush.noWash();
  brush.noHatch();

  let skinTilt = TILT_DEG - 2.6;

  // -------------------------------------------------------------------------
  // 3A. Detailed Creases, Nodal Impressions & Split-Fibre Marks in Every Hollow
  // -------------------------------------------------------------------------
  for (let h of skinHollows) {
    if (h.imp < 0.14) continue;
    let ca = cos(h.angle), sa = sin(h.angle);

    // 1. Pooled rose-madder and sepia-umber crease along the upper-left wall of the dent
    let creaseCol = h.light > 0.6 ? "#8f3242" : (h.light > 0.35 ? "#6e2533" : "#4f1c26");
    let creaseW = map(h.imp, 0.14, 1.0, 0.18, 0.46);
    brush.set("HB", creaseCol, creaseW);

    let arcPts = [];
    for (let k = 0; k <= 6; k++) {
      let a = map(k, 0, 6, 130, 275);
      let lx = cos(a) * h.rx * 0.86;
      let ly = sin(a) * h.ry * 0.86;
      arcPts.push([h.x + lx * ca - ly * sa, h.y + lx * sa + ly * ca]);
    }
    drawSpline(arcPts, 0.45);

    // 2. Pinch notches at the two ends of the hollow (where perpendicular cane crossed)
    if (h.imp > 0.32) {
      brush.set("2H", "#63383b", creaseW * 0.85);
      for (let side of [-1, 1]) {
        let ex = h.x + side * h.rx * 0.88 * ca;
        let ey = h.y + side * h.rx * 0.88 * sa;
        let nx = -sa * h.ry * 0.48;
        let ny = ca * h.ry * 0.48;
        drawSpline([
          [ex - nx * 0.8, ey - ny * 0.8],
          [ex + side * ca * 2.5, ey + side * sa * 2.5],
          [ex + nx * 0.8, ey + ny * 0.8]
        ], 0.4);
      }
    }

    // 3. Form-following graphite cross-contour lines curving down into the hollow
    let numContours = floor(map(h.imp, 0.14, 1.0, 2, 6));
    let gCol = h.light > 0.65 ? "#8a6a66" : (h.light > 0.38 ? "#694d4b" : "#473333");
    brush.set("2H", gCol, map(h.imp, 0.14, 1.0, 0.14, 0.28));

    for (let m = 0; m < numContours; m++) {
      let t = map(m, 0, max(1, numContours - 1), -0.65, 0.65);
      let lx = t * h.rx * 0.78;
      let wSpan = sqrt(max(0.05, 1 - t * t)) * h.ry * 0.85;
      // 3-point curve bowing downward into the hollow floor
      let p1 = [h.x + lx * ca - (-wSpan) * sa, h.y + lx * sa + (-wSpan) * ca];
      let p2 = [h.x + (lx + 2.2 * h.imp) * ca, h.y + (lx + 2.2 * h.imp) * sa + 1.8 * h.imp];
      let p3 = [h.x + lx * ca - wSpan * sa, h.y + lx * sa + wSpan * ca];
      drawSpline([p1, p2, p3], 0.45);
    }

    // 4. Impression of the cane's glossy node (a sharp transverse double-crease of rose madder)
    if (h.hasNode && h.imp > 0.35) {
      let nOffset = (noise(h.u * 1.3, h.v * 1.3) - 0.5) * h.rx * 0.55;
      let nx = h.x + nOffset * ca;
      let ny = h.y + nOffset * sa;
      let perpX = -sa * h.ry * 0.72;
      let perpY = ca * h.ry * 0.72;

      brush.set("rotring", "#8c2f3f", 0.26 * h.imp);
      drawSpline([
        [nx - perpX, ny - perpY],
        [nx - 1.2 * ca, ny - 1.2 * sa],
        [nx + perpX, ny + perpY]
      ], 0.35);

      // Adjacent blanched micro-ridge next to the node dent
      brush.set("cpencil", "#fbf0e4", 0.32 * h.imp);
      drawSpline([
        [nx + 2.2 * ca - perpX * 0.85, ny + 2.2 * sa - perpY * 0.85],
        [nx + 1.2 * ca, ny + 1.2 * sa],
        [nx + 2.2 * ca + perpX * 0.85, ny + 2.2 * sa + perpY * 0.85]
      ], 0.35);
    }

    // 5. Impression of split cane fibre (fine longitudinal rose-sepia scratch inside the hollow)
    if (h.hasSplit && h.imp > 0.3) {
      let sOff = (noise(h.u * 2.1, h.v * 2.1) - 0.5) * h.ry * 0.6;
      let sx = h.x - sOff * sa;
      let sy = h.y + sOff * ca;
      brush.set("2H", "#7d2d3b", 0.22 * h.imp);
      drawSpline([
        [sx - ca * h.rx * 0.75, sy - sa * h.rx * 0.75],
        [sx + sa * 1.5, sy - ca * 1.5],
        [sx + ca * h.rx * 0.78, sy + sa * h.rx * 0.78]
      ], 0.3);
    }
  }

  // -------------------------------------------------------------------------
  // 3B. Frayed Binding Impressions & Ridge Modeling Around the Skin Cushions
  // -------------------------------------------------------------------------
  for (let c of skinCushions) {
    if (c.imp < 0.2) continue;

    // Shaded lower-right contour of the pink skin cushion (graphite + raw umber)
    let shCol = c.light > 0.55 ? "#7a4e50" : "#543537";
    brush.set("HB", shCol, map(c.imp, 0.2, 1.0, 0.16, 0.36));

    let ridgeArc = [];
    for (let k = 0; k <= 5; k++) {
      let a = map(k, 0, 5, -35, 115);
      let rx = c.x + cos(a) * c.r * 0.95;
      let ry = c.y + sin(a) * c.r * 0.88 * c.vScale;
      ridgeArc.push([rx, ry]);
    }
    drawSpline(ridgeArc, 0.45);

    // Diagonal frayed-binding crease marks radiating from the corners of the raised cushion
    if (c.imp > 0.38) {
      brush.set("2H", "#853844", 0.22 * c.imp);
      for (let dAngle of [skinTilt + 42, skinTilt - 42]) {
        let dx = cos(dAngle) * c.r * 1.15;
        let dy = sin(dAngle) * c.r * 1.05 * c.vScale;
        brush.line(c.x - dx, c.y - dy, c.x - dx * 0.45, c.y - dy * 0.45);
        brush.line(c.x + dx * 0.45, c.y + dy * 0.45, c.x + dx, c.y + dy);
      }
    }
  }

  // -------------------------------------------------------------------------
  // 3C. Broad Graphite Hatching Across the Cylindrical Shadow & Dermatoglyphics
  // -------------------------------------------------------------------------
  // Long, supple graphite strokes following the anatomical curve of the thigh in the shadow zones
  for (let i = 0; i < 420; i++) {
    let x = random(-30, 1230);
    let edgeY = thighEdgeY(x);
    let y = random(-20, edgeY - 6);
    let light = getSkinLight(x, y);

    // Concentrate graphite shading in the twilight right side and lower core shadow
    if (random() > (1.08 - light * 0.88)) continue;

    let distEdge = edgeY - y;
    let strokeAngle = distEdge < 160
      ? map(distEdge, 0, 160, -8, skinTilt) + random(-6, 6)
      : skinTilt + random(-14, 14);

    let len = random(28, 72);
    let col = light < 0.35 ? "#453334" : (light < 0.6 ? "#664d4d" : "#8c706c");
    let w = map(light, 0.1, 0.9, 0.28, 0.14);

    brush.set("2H", col, w);
    let hx = cos(strokeAngle) * len * 0.5;
    let hy = sin(strokeAngle) * len * 0.5;
    let midCurve = random(-3.5, 3.5);
    drawSpline([
      [x - hx, y - hy],
      [x - sin(strokeAngle) * midCurve, y + cos(strokeAngle) * midCurve],
      [x + hx, y + hy]
    ], 0.4);
  }

  // Fine dermatoglyphic skin pore triangles / Langer's furrow lines
  for (let i = 0; i < 650; i++) {
    let x = random(0, 1200);
    let edgeY = thighEdgeY(x);
    let y = random(0, edgeY - 8);
    let light = getSkinLight(x, y);

    let furrowCol = light > 0.6 ? "#b08682" : "#705250";
    brush.set("2H", furrowCol, random(0.11, 0.19));
    let a = skinTilt + (noise(x * 0.005, y * 0.005) - 0.5) * 50 + (i % 2 === 0 ? 18 : -18);
    let l = random(6, 15);
    brush.line(x, y, x + cos(a) * l, y + sin(a) * l);
  }

  // -------------------------------------------------------------------------
  // 3D. Faint Vellus Hair (Peach Fuzz) Catching the Soft Afternoon Light
  // -------------------------------------------------------------------------
  for (let i = 0; i < 980; i++) {
    let x = random(-10, 1210);
    let edgeY = thighEdgeY(x);
    let y = random(-10, edgeY - 2);
    let distEdge = edgeY - y;
    let light = getSkinLight(x, y);

    // Natural hair stream wrapping gently around the thigh cylinder
    let streamAngle = TILT_DEG + 12 * sin(x * 0.25) + map(distEdge, 0, 700, 16, -8, true);
    streamAngle += (noise(x * 0.008, y * 0.008) - 0.5) * 28;

    let hairLen = random(13, 27);
    let curl = random(-4.5, 4.5);

    // Where afternoon light grazes the mid-tone roll or the bottom contour of the thigh,
    // vellus hairs glow as luminous pale-gold / ivory filaments
    let isGrazingZone = (light > 0.36 && light < 0.78) || distEdge < 55;
    if (isGrazingZone && random() < 0.72) {
      let glowCol = distEdge < 45 ? "#f5e3cc" : "#fbf1e4";
      brush.set("cpencil", glowCol, random(0.18, 0.32));
    } else {
      let shadowHairCol = light > 0.65 ? "#bfa292" : "#80665c";
      brush.set("2H", shadowHairCol, random(0.14, 0.24));
    }

    let x1 = x + cos(streamAngle) * hairLen * 0.5;
    let y1 = y + sin(streamAngle) * hairLen * 0.5 - curl * 0.5;
    let x2 = x + cos(streamAngle + curl) * hairLen;
    let y2 = y + sin(streamAngle + curl) * hairLen;

    // Allow a few backlit vellus hairs right along the lower thigh edge to slightly cross the contour
    if (y2 > edgeY + 5) continue;
    drawSpline([[x, y], [x1, y1], [x2, y2]], 0.55);
  }
}

// ===========================================================================
// STEP 4: REAL RATTAN CHAIR WEAVE BELOW THE LIFTED THIGH
// ===========================================================================
function renderRealRattanWeave() {
  brush.noStroke();
  brush.noFill();
  brush.noWash();
  brush.noHatch();

  let uMin = -14, uMax = 15;
  let vMin = -2, vMax = 11;

  // -------------------------------------------------------------------------
  // 4A. Deep Recessed Interstices (Dark Holes Between Cane Strands)
  // -------------------------------------------------------------------------
  let gapPolys = [];
  for (let v = vMin; v <= vMax; v++) {
    for (let u = uMin; u <= uMax; u++) {
      let c = chairGridToXY(u + 0.5, v + 0.5);
      let edgeY = thighEdgeY(c.x);
      if (c.x < -60 || c.x > 1260 || c.y < edgeY - 4 || c.y > 1260) continue;

      // Octagonal/diamond hole between the warp & weft strands
      let rU = 10.5, rV = 9.5;
      let pts = [];
      for (let k = 0; k < 8; k++) {
        let a = k * 45;
        let du = cos(a) * rU;
        let dv = sin(a) * rV;
        let px = c.x + du * cosU + dv * cosV;
        let py = max(thighEdgeY(px), c.y + du * sinU + dv * sinV);
        pts.push([px, py]);
      }
      gapPolys.push({ c, pts, u, v });
    }
  }

  // Fill dark interstices
  for (let g of gapPolys) {
    brush.wash("#1b120e", 215);
    drawPoly(g.pts, 0.1);
  }
  brush.noWash();

  // Deep graphite cross-hatching inside the holes
  for (let g of gapPolys) {
    brush.set("2B", "#120b09", 0.38);
    for (let s = -5; s <= 5; s += 3.5) {
      let x1 = g.c.x - 7 + s, y1 = max(thighEdgeY(g.c.x - 7 + s), g.c.y - 6);
      let x2 = g.c.x + 7 + s, y2 = max(thighEdgeY(g.c.x + 7 + s), g.c.y + 6);
      if (y2 > y1 + 1) brush.line(x1, y1, x2, y2);
    }
  }

  // -------------------------------------------------------------------------
  // 4B. Diagonal Binding Strands & Frayed Bindings Across the Interstices
  // -------------------------------------------------------------------------
  for (let g of gapPolys) {
    let light = getChairLight(g.c.x, g.c.y);

    // Two slender diagonal cane binding strips crossing the gap corners
    for (let diag of [-1, 1]) {
      let dAngle = TILT_DEG + diag * 38;
      let ca = cos(dAngle), sa = sin(dAngle);
      let nx = -sa, ny = ca;
      let len = 18.0;
      let halfW = 3.2;

      let x1 = g.c.x - ca * len + nx * diag * 3.5;
      let y1 = g.c.y - sa * len + ny * diag * 3.5;
      let x2 = g.c.x + ca * len + nx * diag * 3.5;
      let y2 = g.c.y + sa * len + ny * diag * 3.5;

      let e1 = thighEdgeY(x1), e2 = thighEdgeY(x2);
      if (y1 < e1 && y2 < e2) continue;
      y1 = max(e1, y1);
      y2 = max(e2, y2);

      // Base wash of the binding strip
      let bindCol = light > 0.65 ? "#b58b5c" : (light > 0.35 ? "#785739" : "#453020");
      brush.noStroke();
      brush.wash(bindCol, 195);
      drawPoly([
        [x1 - nx * halfW, y1 - ny * halfW],
        [x2 - nx * halfW, y2 - ny * halfW],
        [x2 + nx * halfW, y2 + ny * halfW],
        [x1 + nx * halfW, y1 + ny * halfW]
      ], 0.1);
      brush.noWash();

      // Crisp edges and longitudinal fibre of the binding strip
      brush.set("rotring", light > 0.5 ? "#3d2817" : "#1f140c", 0.25);
      brush.line(x1 - nx * halfW, y1 - ny * halfW, x2 - nx * halfW, y2 - ny * halfW);
      brush.line(x1 + nx * halfW, y1 + ny * halfW, x2 + nx * halfW, y2 + ny * halfW);

      if (light > 0.32) {
        brush.set("cpencil", light > 0.68 ? "#e8cba0" : "#9e7b54", 0.24);
        brush.line(x1, y1, x2, y2);
      }

      // Frayed binding ends: delicate whiskery cane fibers splaying out from the binding
      let numFrays = floor(random(3, 6));
      for (let f = 0; f < numFrays; f++) {
        let ft = random(0.15, 0.85);
        let fx = lerp(x1, x2, ft) + (random() < 0.5 ? -1 : 1) * nx * halfW;
        let fy = lerp(y1, y2, ft) + (random() < 0.5 ? -1 : 1) * ny * halfW;
        if (fy < thighEdgeY(fx) + 2) continue;

        let fAngle = dAngle + random(-48, 48);
        let fLen = random(7, 16);
        let fCurl = random(-18, 18);
        let fx1 = fx + cos(fAngle) * fLen * 0.5;
        let fy1 = max(thighEdgeY(fx1), fy + sin(fAngle) * fLen * 0.5);
        let fx2 = fx + cos(fAngle + fCurl) * fLen;
        let fy2 = max(thighEdgeY(fx2), fy + sin(fAngle + fCurl) * fLen);

        // Dark shadow of frayed fiber
        brush.set("rotring", "#24160e", 0.18);
        drawSpline([[fx, fy + 1.2], [fx1, fy1 + 1.2], [fx2, fy2 + 1.2]], 0.45);

        // Sunlit or sepia frayed fiber strand
        let frayCol = (light > 0.55 && random() < 0.65) ? "#ebd2ab" : "#8c6845";
        brush.set("2H", frayCol, 0.20);
        drawSpline([[fx, fy], [fx1, fy1], [fx2, fy2]], 0.45);
      }
    }
  }

  // -------------------------------------------------------------------------
  // 4C. Collect All Warp (u) and Weft (v) Cane Strand Segments
  // -------------------------------------------------------------------------
  let underSegments = [];
  let overSegments = [];

  // Warp segments (running along u at fixed integer v, centered at integer u)
  for (let v = vMin; v <= vMax; v++) {
    for (let u = uMin; u <= uMax; u++) {
      let pStart = chairGridToXY(u - 0.54, v);
      let pMid = chairGridToXY(u, v);
      let pEnd = chairGridToXY(u + 0.54, v);

      if (pMid.x < -80 || pMid.x > 1280 || pMid.y > 1260) continue;
      if (pStart.y < thighEdgeY(pStart.x) - 10 &&
          pMid.y < thighEdgeY(pMid.x) - 10 &&
          pEnd.y < thighEdgeY(pEnd.x) - 10) continue;

      let isOver = ((u + v) % 2 + 2) % 2 === 0;
      let seg = {
        type: "warp", u, v, isOver,
        pStart, pMid, pEnd,
        halfW: 16.8,
        angle: TILT_DEG,
        hasNode: noise(u * 0.71 + 9, v * 0.71 + 3) > 0.66,
        hasSplit: noise(u * 0.53 + 21, v * 0.53 + 47) > 0.52
      };
      if (isOver) overSegments.push(seg);
      else underSegments.push(seg);
    }
  }

  // Weft segments (running along v at fixed integer u, centered at integer v)
  for (let v = vMin; v <= vMax; v++) {
    for (let u = uMin; u <= uMax; u++) {
      let pStart = chairGridToXY(u, v - 0.54);
      let pMid = chairGridToXY(u, v);
      let pEnd = chairGridToXY(u, v + 0.54);

      if (pMid.x < -80 || pMid.x > 1280 || pMid.y > 1260) continue;
      if (pStart.y < thighEdgeY(pStart.x) - 10 &&
          pMid.y < thighEdgeY(pMid.x) - 10 &&
          pEnd.y < thighEdgeY(pEnd.x) - 10) continue;

      let isOver = ((u + v) % 2 + 2) % 2 === 1;
      let seg = {
        type: "weft", u, v, isOver,
        pStart, pMid, pEnd,
        halfW: 15.8,
        angle: WEFT_DEG,
        hasNode: noise(u * 0.67 + 41, v * 0.67 + 19) > 0.66,
        hasSplit: noise(u * 0.49 + 83, v * 0.49 + 11) > 0.52
      };
      if (isOver) overSegments.push(seg);
      else underSegments.push(seg);
    }
  }

  // Draw all "UNDER" segments first, then all "OVER" segments on top
  for (let seg of underSegments) {
    drawCaneSegment(seg);
  }
  for (let seg of overSegments) {
    drawCaneSegment(seg);
  }
}

// Render an individual rattan cane strand segment with 3D cylindrical shading,
// pinch shadows, vascular grain, glossy node, and split fibres
function drawCaneSegment(seg) {
  let { pStart, pMid, pEnd, halfW, isOver, hasNode, hasSplit, u, v } = seg;

  // Direction & perpendicular normal vectors
  let dx = pEnd.x - pStart.x;
  let dy = pEnd.y - pStart.y;
  let len = sqrt(dx * dx + dy * dy);
  if (len < 2) return;
  let tx = dx / len, ty = dy / len;
  let nx = -ty, ny = tx;
  // Ensure normal points toward upper-left (toward afternoon light)
  if (nx * (-0.7) + ny * (-0.7) < 0) {
    nx = -nx;
    ny = -ny;
  }

  // 3D over-and-under arch displacement: "OVER" crowns up-left; "UNDER" dips down-right
  let archSign = isOver ? 1.0 : -0.65;
  let archAmp = 3.8 * archSign;
  let midX = pMid.x + nx * archAmp;
  let midY = pMid.y + ny * archAmp;

  let light = getChairLight(midX, midY);
  if (!isOver) light *= 0.68; // Recessed under-strands receive less direct light

  // Helper to get clipped point along the cane ribbon
  // s in [0..1] along length, w in [-1..1] across width (-1 = shaded side, +1 = lit side)
  function ptOnStrand(s, w) {
    // Quadratic Bezier interpolation along pStart -> mid -> pEnd
    let omt = 1 - s;
    let cx = omt * omt * pStart.x + 2 * omt * s * midX + s * s * pEnd.x;
    let cy = omt * omt * pStart.y + 2 * omt * s * midY + s * s * pEnd.y;
    let px = cx + nx * (w * halfW);
    let py = cy + ny * (w * halfW);
    // Clip cleanly against the underside of the lifted thigh
    let ey = thighEdgeY(px);
    return [px, max(ey, py), py < ey];
  }

  // Check if entire segment is hidden behind the thigh
  let c0 = ptOnStrand(0.1, 0), c1 = ptOnStrand(0.5, 0), c2 = ptOnStrand(0.9, 0);
  if (c0[2] && c1[2] && c2[2]) return;

  // -------------------------------------------------------------------------
  // 1. Cast shadow of an "OVER" strand onto the underlying weave
  // -------------------------------------------------------------------------
  if (isOver) {
    brush.noStroke();
    brush.wash("#1e130d", 145);
    let shRibbon = [];
    for (let s = 0; s <= 1.01; s += 0.25) {
      let p = ptOnStrand(s, -1.18);
      shRibbon.push([p[0] + 2.2, max(thighEdgeY(p[0] + 2.2), p[1] + 2.5)]);
    }
    for (let s = 1.0; s >= -0.01; s -= 0.25) {
      let p = ptOnStrand(s, 0.85);
      shRibbon.push([p[0] + 2.2, max(thighEdgeY(p[0] + 2.2), p[1] + 2.5)]);
    }
    drawPoly(shRibbon, 0.15);
    brush.noWash();
  }

  // -------------------------------------------------------------------------
  // 2. Cylindrical Tonal Bands of the Cane Peel (Lit Bevel, Spine, Shaded Bevel)
  // -------------------------------------------------------------------------
  let bands = [
    // Shaded lower-right bevel
    {
      w0: -1.0, w1: -0.25,
      col: light > 0.65 ? "#8c643e" : (light > 0.35 ? "#593e27" : "#302016"),
      op: 225
    },
    // Central convex crown
    {
      w0: -0.32, w1: 0.42,
      col: light > 0.65 ? "#cca272" : (light > 0.35 ? "#876342" : "#4a3323"),
      op: 225
    },
    // Sunlit upper-left bevel
    {
      w0: 0.35, w1: 1.0,
      col: light > 0.65 ? "#e6c699" : (light > 0.35 ? "#9e7852" : "#593f2c"),
      op: 225
    }
  ];

  brush.noStroke();
  for (let b of bands) {
    brush.wash(b.col, b.op);
    let poly = [];
    for (let s = 0; s <= 1.01; s += 0.25) {
      let p = ptOnStrand(s, b.w0);
      poly.push([p[0], p[1]]);
    }
    for (let s = 1.0; s >= -0.01; s -= 0.25) {
      let p = ptOnStrand(s, b.w1);
      poly.push([p[0], p[1]]);
    }
    drawPoly(poly, 0.12);
  }

  // Specular silica sheen along the crest of an "OVER" strand
  if (isOver && light > 0.30) {
    let sheenCol = light > 0.65 ? "#f6e5c8" : "#baa07d";
    brush.wash(sheenCol, floor(map(light, 0.3, 1.0, 55, 155)));
    let sheenPoly = [];
    for (let s = 0.15; s <= 0.86; s += 0.175) {
      let p = ptOnStrand(s, 0.12);
      sheenPoly.push([p[0], p[1]]);
    }
    for (let s = 0.85; s >= 0.14; s -= 0.175) {
      let p = ptOnStrand(s, 0.52);
      sheenPoly.push([p[0], p[1]]);
    }
    drawPoly(sheenPoly, 0.18);
  }

  // Deep sepia pinch-shadows at both ends of an "UNDER" segment where crossing strands press over it
  if (!isOver) {
    brush.wash("#21150e", 185);
    for (let endRange of [[0.0, 0.28], [0.72, 1.0]]) {
      let pinchPoly = [];
      for (let s = endRange[0]; s <= endRange[1] + 0.01; s += 0.14) {
        let p = ptOnStrand(s, -1.02);
        pinchPoly.push([p[0], p[1]]);
      }
      for (let s = endRange[1]; s >= endRange[0] - 0.01; s -= 0.14) {
        let p = ptOnStrand(s, 1.02);
        pinchPoly.push([p[0], p[1]]);
      }
      drawPoly(pinchPoly, 0.08);
    }
  }
  brush.noWash();

  // -------------------------------------------------------------------------
  // 3. Longitudinal Vascular Fibres (Graphite & Sepia Ink Striations)
  // -------------------------------------------------------------------------
  let numFibres = 9;
  for (let f = 0; f <= numFibres; f++) {
    let w = map(f, 0, numFibres, -0.96, 0.96);
    let isEdge = (f === 0 || f === numFibres);

    let fCol, fBrush, fWeight;
    if (isEdge) {
      fBrush = "rotring";
      fCol = f === 0 ? "#1f130c" : (light > 0.5 ? "#4a321f" : "#24170f");
      fWeight = f === 0 ? 0.42 : 0.30;
    } else if (w > 0.15 && w < 0.55 && isOver && light > 0.45 && f % 2 === 0) {
      // Glossy silica vascular ridge
      fBrush = "cpencil";
      fCol = light > 0.7 ? "#fbf0dc" : "#d4b892";
      fWeight = 0.28;
    } else {
      fBrush = f % 2 === 0 ? "2H" : "HB";
      fCol = light > 0.6 ? "#66482c" : (light > 0.32 ? "#422e1d" : "#261a11");
      fWeight = random(0.16, 0.26);
    }

    brush.set(fBrush, fCol, fWeight);
    let fPts = [];
    for (let s = 0.02; s <= 0.99; s += 0.24) {
      let p = ptOnStrand(s, w);
      if (!p[2]) fPts.push([p[0], p[1]]);
    }
    if (fPts.length >= 2) drawSpline(fPts, 0.35);
  }

  // -------------------------------------------------------------------------
  // 4. Glossy Rattan Node (Swollen Transverse Joint Ring & Specular Highlight)
  // -------------------------------------------------------------------------
  if (hasNode) {
    let ns = constrain(0.32 + 0.36 * noise(u * 1.7, v * 1.7), 0.24, 0.76);
    let np0 = ptOnStrand(ns, -1.06);
    let npMid = ptOnStrand(ns + 0.03, 0.0);
    let np1 = ptOnStrand(ns, 1.06);

    if (!npMid[2]) {
      // Warm burnt-umber nodal collar wash
      brush.noStroke();
      brush.wash(light > 0.5 ? "#6e4726" : "#362213", 145);
      let collar = [];
      for (let w of [-1.05, 0, 1.05]) {
        let p = ptOnStrand(ns - 0.06, w);
        collar.push([p[0], p[1]]);
      }
      for (let w of [1.05, 0, -1.05]) {
        let p = ptOnStrand(ns + 0.06, w);
        collar.push([p[0], p[1]]);
      }
      drawPoly(collar, 0.2);
      brush.noWash();

      // Deep sepia nodal ring crease across the cane
      brush.set("rotring", "#24140b", 0.52);
      drawSpline([[np0[0], np0[1]], [npMid[0], npMid[1]], [np1[0], np1[1]]], 0.4);

      // Secondary graphite shadow ridge of the node
      let ns2 = ns - 0.035;
      let s0 = ptOnStrand(ns2, -0.95), sMid = ptOnStrand(ns2 + 0.02, 0), s1 = ptOnStrand(ns2, 0.95);
      brush.set("HB", "#4a2f1b", 0.34);
      drawSpline([[s0[0], s0[1]], [sMid[0], sMid[1]], [s1[0], s1[1]]], 0.4);

      // Bright glossy silicate highlight on the raised lip of the node
      if (light > 0.22) {
        let hCol = light > 0.6 ? "#fff8ec" : "#dec49e";
        let nsLip = ns + 0.032;
        let l0 = ptOnStrand(nsLip, -0.55);
        let lMid = ptOnStrand(nsLip + 0.025, 0.22);
        let l1 = ptOnStrand(nsLip, 0.92);

        brush.set("cpencil", hCol, map(light, 0.2, 1.0, 0.38, 0.72));
        drawSpline([[l0[0], l0[1]], [lMid[0], lMid[1]], [l1[0], l1[1]]], 0.4);

        // Longitudinal specular flare gleaming off the node lip
        let flareEnd = ptOnStrand(min(0.92, nsLip + 0.18), 0.32);
        brush.set("rotring", hCol, 0.32);
        brush.line(lMid[0], lMid[1], flareEnd[0], flareEnd[1]);
      }
    }
  }

  // -------------------------------------------------------------------------
  // 5. Split Fibre & Peeling Cane Splinters
  // -------------------------------------------------------------------------
  if (hasSplit) {
    // 5A. Longitudinal split crack inside the cane peel
    let splitW = (noise(u * 3.1, v * 3.1) - 0.5) * 1.1;
    let sStart = 0.12 + 0.2 * noise(u, v);
    let sEnd = min(0.92, sStart + 0.48);

    let pA = ptOnStrand(sStart, splitW);
    let pB = ptOnStrand((sStart + sEnd) * 0.5, splitW + 0.08);
    let pC = ptOnStrand(sEnd, splitW - 0.05);

    if (!pB[2]) {
      // Dark sepia crack line
      brush.set("rotring", "#1c1009", 0.34);
      drawSpline([[pA[0], pA[1]], [pB[0], pB[1]], [pC[0], pC[1]]], 0.35);

      // Bright splinter lip right beside the split
      if (light > 0.3) {
        brush.set("cpencil", light > 0.65 ? "#f7e3bd" : "#bfa078", 0.28);
        drawSpline([
          [pA[0] + nx * 1.3, pA[1] + ny * 1.3],
          [pB[0] + nx * 1.3, pB[1] + ny * 1.3],
          [pC[0] + nx * 1.3, pC[1] + ny * 1.3]
        ], 0.35);
      }
    }

    // 5B. Peeling split fibre lifting off the edge of the cane strand
    let edgeSide = noise(u * 4.3, v * 2.9) > 0.5 ? 1.0 : -1.0;
    let peelS = 0.25 + 0.4 * noise(v * 2.1, u * 2.1);
    let rootPt = ptOnStrand(peelS, edgeSide * 0.96);

    if (!rootPt[2]) {
      let peelLen = random(14, 28);
      let peelAngle = seg.angle + edgeSide * random(14, 29);
      let px1 = rootPt[0] + cos(peelAngle) * peelLen * 0.55;
      let py1 = max(thighEdgeY(px1), rootPt[1] + sin(peelAngle) * peelLen * 0.55);
      let px2 = rootPt[0] + cos(peelAngle + edgeSide * 10) * peelLen;
      let py2 = max(thighEdgeY(px2), rootPt[1] + sin(peelAngle + edgeSide * 10) * peelLen);

      // Tiny cast shadow of the peeling splinter onto the cane
      brush.set("rotring", "#1a0f09", 0.22);
      drawSpline([
        [rootPt[0] + 1.5, rootPt[1] + 2.0],
        [px1 + 1.8, py1 + 2.2],
        [px2 + 2.0, py2 + 2.5]
      ], 0.45);

      // Pale golden-ochre peeling fibre
      let splinterCol = light > 0.55 ? "#f2d8ae" : (light > 0.3 ? "#b59066" : "#6e5238");
      brush.set("cpencil", splinterCol, 0.28);
      drawSpline([[rootPt[0], rootPt[1]], [px1, py1], [px2, py2]], 0.45);
    }
  }
}

// ===========================================================================
// STEP 5: FINAL UNIFYING TOUCHES, THIGH CONTOUR & ATMOSPHERIC GLAZES
// ===========================================================================
function renderFinalUnifyingTouches() {
  brush.noFill();
  brush.noWash();
  brush.noHatch();

  // -------------------------------------------------------------------------
  // 5A. Modulated Sepia & Graphite Contour Along the Underside of the Lifted Thigh
  // -------------------------------------------------------------------------
  for (let x = -20; x < 1200; x += 28) {
    let x0 = x;
    let x1 = x + 16;
    let x2 = x + 32;
    let y0 = thighEdgeY(x0);
    let y1 = thighEdgeY(x1);
    let y2 = thighEdgeY(x2);

    // Deep sepia-umber occlusion crease right under the skin edge
    let w = map(x, 0, 1200, 0.55, 0.32, true);
    brush.set("HB", "#2b1c18", w);
    drawSpline([[x0, y0 + 0.8], [x1, y1 + 0.8], [x2, y2 + 0.8]], 0.4);

    // Soft raw-umber & rose-sepia skin boundary
    brush.set("2H", "#593d3a", w * 0.75);
    drawSpline([[x0, y0 - 0.6], [x1, y1 - 0.6], [x2, y2 - 0.6]], 0.4);

    // Subtle warm reflected-light kiss along the lower skin rim
    if (random() < 0.75) {
      let refCol = x < 650 ? "#ddb898" : "#b58d76";
      brush.set("cpencil", refCol, 0.28);
      drawSpline([[x0, y0 - 2.2], [x1, y1 - 2.2], [x2, y2 - 2.2]], 0.4);
    }
  }

  // -------------------------------------------------------------------------
  // 5B. Translucent Twilight Sepia & Rose-Madder Glaze Unification
  // -------------------------------------------------------------------------
  brush.noStroke();

  // Soft twilight sepia-plum wash over the lower-right corner to deepen dusk mood
  brush.fill("#4a3638", 42);
  brush.fillBleed(0.45, "out");
  brush.fillTexture(0.55, 0.25);
  drawPoly([
    [760, 420], [1240, 260], [1240, 1240], [520, 1240], [640, 780]
  ], 0.3);

  // Subtle warm afternoon gold glaze in the upper-left light
  brush.fill("#f7e8d4", 28);
  brush.fillBleed(0.4, "out");
  brush.fillTexture(0.4, 0.15);
  drawPoly([
    [-40, -40], [620, -40], [420, 420], [-40, 560]
  ], 0.3);

  brush.noFill();
}
